function Logic.detect(place, universe)
	for _, game in ipairs(Logic.games) do
		if
			game.place == place
			or (game.eventPlace and game.eventPlace == place)
			or (game.universe and game.universe == universe)
		then
			return game
		end
		for _, alternate in ipairs(game.alternatePlaces or {}) do
			if alternate == place then
				return game
			end
		end
	end
	return nil
end

function Logic.quest(quests, id)
	if type(quests) == "table" then
		for _, quest in pairs(quests) do
			if type(quest) == "table" and quest.id == id then
				return quest
			end
		end
	end
	return nil
end

function Logic.contains(values, needle)
	if type(values) ~= "table" then
		return false
	end
	for _, value in pairs(values) do
		if value == needle then
			return true
		end
	end
	return false
end

-- pipes
function Logic.solve(board, engine, checkpoint, currentTurns)
	if type(board) ~= "table" or type(board.Cells) ~= "table" or type(board.Size) ~= "number" then
		return nil, "No puzzle board"
	end
	local size = board.Size
	if size < 1 or size > 10 or size % 1 ~= 0 or #board.Cells ~= size * size then
		return nil, "Unsupported board size"
	end
	if type(engine) ~= "table" or type(engine.openings) ~= "function" or type(engine.trace) ~= "function" then
		return nil, "Puzzle rules unavailable"
	end
	if
		type(board.SourceRow) ~= "number"
		or type(board.SinkRow) ~= "number"
		or board.SourceRow < 1
		or board.SourceRow > size
		or board.SinkRow < 1
		or board.SinkRow > size
		or board.SourceRow % 1 ~= 0
		or board.SinkRow % 1 ~= 0
	then
		return nil, "Invalid puzzle endpoints"
	end
	local domains, neighbors, placed = {}, {}, {}
	local source = (board.SourceRow - 1) * size + 1
	local sink = (board.SinkRow - 1) * size + size
	local directions = { { 0, -1, 1, 4 }, { 1, 0, 2, 8 }, { 0, 1, 4, 1 }, { -1, 0, 8, 2 } }
	for index, cell in ipairs(board.Cells) do
		if type(cell) ~= "table" then
			return nil, "Invalid tile " .. index
		end
		local x, y = (index - 1) % size, math.floor((index - 1) / size)
		domains[index], neighbors[index], placed[index] = {}, {}, true
		local masks = {}
		local start = currentTurns and currentTurns[index] or cell.Start
		start = type(start) == "number" and start or 0
		for offset = 0, 3 do
			local turn = (start + offset) % 4
			local ok, mask = pcall(engine.openings, cell.Shape, turn)
			if not ok or type(mask) ~= "number" then
				return nil, "Unknown tile shape at " .. index
			end
			local allowed = (index ~= source or bit32.band(mask, 8) ~= 0)
				and (index ~= sink or bit32.band(mask, 2) ~= 0)
			if allowed and not masks[mask] then
				masks[mask] = true
				table.insert(domains[index], { mask = mask, turn = turn })
			end
		end
		if #domains[index] == 0 then
			return nil, "No rotation connects a puzzle endpoint"
		end
		for _, direction in ipairs(directions) do
			local nx, ny = x + direction[1], y + direction[2]
			if nx >= 0 and nx < size and ny >= 0 and ny < size then
				table.insert(neighbors[index], { index = ny * size + nx + 1, bit = direction[3], back = direction[4] })
			end
		end
	end
	local visits = 0
	local function check()
		visits += 1
		return visits < 100000 and (not checkpoint or checkpoint(visits))
	end
	local function trace(current)
		local turns = {}
		for index, domain in ipairs(current) do
			turns[index] = domain[1].turn
		end
		local reached, exit = engine.trace(board, turns, placed)
		local reachedCount = 0
		for index in ipairs(board.Cells) do
			if reached[index] then
				reachedCount += 1
			end
		end
		return turns, reached, reachedCount, exit
	end
	local function propagate(current)
		local changed = true
		while changed do
			if not check() then
				return false, "Search stopped"
			end
			changed = false
			local possible = {}
			for index, domain in ipairs(current) do
				local mask = 0
				for _, option in ipairs(domain) do
					mask = bit32.bor(mask, option.mask)
				end
				possible[index] = mask
			end
			local discovery, low, required = {}, {}, {}
			local seen = 0
			local function visit(index, parent)
				seen += 1
				discovery[index], low[index] = seen, seen
				local leadsToSink = index == sink
				for _, edge in ipairs(neighbors[index]) do
					if
						bit32.band(possible[index], edge.bit) == 0
						or bit32.band(possible[edge.index], edge.back) == 0
					then
						continue
					end
					if not discovery[edge.index] then
						local childLeadsToSink = visit(edge.index, index)
						leadsToSink = leadsToSink or childLeadsToSink
						low[index] = math.min(low[index], low[edge.index])
						if childLeadsToSink and low[edge.index] > discovery[index] then
							required[index] = bit32.bor(required[index] or 0, edge.bit)
							required[edge.index] = bit32.bor(required[edge.index] or 0, edge.back)
						end
					elseif edge.index ~= parent then
						low[index] = math.min(low[index], discovery[edge.index])
					end
				end
				return leadsToSink
			end
			if not visit(source, 0) then
				return false
			end
			for index, mask in pairs(required) do
				local remaining = {}
				for _, option in ipairs(current[index]) do
					if bit32.band(option.mask, mask) == mask then
						table.insert(remaining, option)
					end
				end
				if #remaining == 0 then
					return false
				end
				if #remaining < #current[index] then
					current[index], changed = remaining, true
				end
			end
		end
		return true
	end
	local function search(current)
		local valid, reason = propagate(current)
		if not valid then
			return nil, reason
		end
		local turns, reached, _, exit = trace(current)
		if exit then
			return turns
		end
		local chosen, pressure
		for index, domain in ipairs(current) do
			if #domain > 1 then
				local score = reached[index] and 8 or 0
				local frontier = reached[index] ~= nil
				for _, edge in ipairs(neighbors[index]) do
					frontier = frontier or reached[edge.index] ~= nil
					score += #current[edge.index] == 1 and 4 or 0
					if (reached[index] ~= nil) ~= (reached[edge.index] ~= nil) then
						score += 2
					end
				end
				if
					frontier
					and (not chosen or #domain < #current[chosen] or (#domain == #current[chosen] and score > pressure))
				then
					chosen, pressure = index, score
				end
			end
		end
		if not chosen then
			return nil
		end
		local options = {}
		for order, option in ipairs(current[chosen]) do
			local branch = table.clone(current)
			branch[chosen] = { option }
			local _, _, connected, exits = trace(branch)
			local score = connected * 8 + (exits and 4 or 0)
			for _, edge in ipairs(neighbors[chosen]) do
				if bit32.band(option.mask, edge.bit) ~= 0 then
					score += 1
				end
			end
			table.insert(options, { option = option, score = score, order = order })
		end
		table.sort(options, function(a, b)
			return a.score > b.score or (a.score == b.score and a.order < b.order)
		end)
		for _, choice in ipairs(options) do
			local branch = table.clone(current)
			branch[chosen] = { choice.option }
			local turns, reason = search(branch)
			if turns or reason then
				return turns, reason
			end
		end
		return nil
	end
	local turns, reason = search(domains)
	return turns, reason or (not turns and "No source-to-exit path found" or nil)
end

-- pillars
function Logic.solvePillars(turns, effects, maxTurns, costs, checkpoint)
	if type(turns) ~= "table" or type(effects) ~= "table" or #turns < 1 or #turns > 8 then
		return nil
	end
	local count = #turns
	local function valid(row)
		if type(row) ~= "table" or #row ~= count then
			return false
		end
		for index = 1, count do
			local value = row[index]
			if type(value) ~= "number" or value % 1 ~= 0 or value < 0 or value > 3 then
				return false
			end
		end
		return true
	end
	if not valid(turns) then
		return nil
	end
	local actions = {}
	for action = 1, count do
		local price = costs and costs[action] or 1
		if
			valid(effects[action])
			and type(price) == "number"
			and price % 1 == 0
			and price >= 0
			and price < math.huge
		then
			table.insert(actions, { index = action, effect = effects[action], cost = price })
		end
	end
	local function key(row)
		local value, scale = 0, 1
		for index = 1, count do
			value += row[index] * scale
			scale *= 4
		end
		return value
	end
	if key(turns) == 0 then
		return {}, 0
	end
	local budget = type(maxTurns) == "number" and maxTurns >= 0 and maxTurns or math.huge
	local middle, left, ticks, stopped = math.floor(#actions / 2), {}, 0, false
	local function enumerate(first, last, visit)
		local values, presses = table.create(count, 0), {}
		local function walk(index, cost, length)
			ticks += 1
			if ticks % 128 == 0 and checkpoint and not checkpoint() then
				stopped = true
				return
			end
			if stopped or cost > budget then
				return
			end
			if index > last then
				visit(values, presses, cost, length)
				return
			end
			local action = actions[index]
			for amount = 0, 3 do
				presses[action.index] = amount
				walk(index + 1, cost + amount * action.cost, length + amount)
				if stopped then
					return
				end
				for row = 1, count do
					values[row] = (values[row] + action.effect[row]) % 4
				end
			end
			presses[action.index] = nil
		end
		walk(first, 0, 0)
	end
	enumerate(1, middle, function(values, presses, cost, length)
		local id = key(values)
		local old = left[id]
		if not old or cost < old.cost or cost == old.cost and length < old.length then
			left[id] = { presses = table.clone(presses), cost = cost, length = length }
		end
	end)
	local winner
	enumerate(middle + 1, #actions, function(values, presses, cost, length)
		local needed = {}
		for row = 1, count do
			needed[row] = (-turns[row] - values[row]) % 4
		end
		local other = left[key(needed)]
		if not other then
			return
		end
		local total, size = cost + other.cost, length + other.length
		if total <= budget and (not winner or total < winner.cost or total == winner.cost and size < winner.length) then
			local moves = {}
			for action = 1, count do
				for _ = 1, (other.presses[action] or 0) + (presses[action] or 0) do
					table.insert(moves, action)
				end
			end
			winner = { moves = moves, cost = total, length = size }
		end
	end)
	if stopped then
		return nil, nil, "Search stopped"
	end
	if winner then
		return winner.moves, winner.cost
	end
	return nil
end

-- graves
function Logic.solveTomb(graves, slots)
	if type(graves) ~= "table" or type(slots) ~= "number" or slots % 1 ~= 0 or slots < 1 or slots > 6 then
		return nil, "The coffin's slot count hasn't loaded"
	end
	local rows, seen = {}, {}
	for _, grave in ipairs(graves) do
		if
			type(grave) ~= "table"
			or type(grave.key) ~= "string"
			or type(grave.icon) ~= "string"
			or type(grave.birth) ~= "number"
			or grave.birth % 1 ~= 0
			or math.abs(grave.birth) == math.huge
			or type(grave.death) ~= "number"
			or grave.death % 1 ~= 0
			or math.abs(grave.death) == math.huge
			or grave.death < grave.birth
		then
			return nil, "A grave's dates or symbol are missing"
		end
		if not seen[grave.key] then
			seen[grave.key] = true
			table.insert(rows, { key = grave.key, icon = grave.icon, age = grave.death - grave.birth })
		end
	end
	if #rows < slots then
		return nil, "There are still unread graves"
	end
	table.sort(rows, function(a, b)
		return a.age < b.age or a.age == b.age and a.key < b.key
	end)
	for index = 1, math.min(slots, #rows - 1) do
		if rows[index].age == rows[index + 1].age and rows[index].icon ~= rows[index + 1].icon then
			return nil, "Two graves have the same lifespan. Check the clue before choosing their order."
		end
	end
	local combo = {}
	for index = 1, slots do
		combo[index] = rows[index].icon
	end
	return combo, rows
end

-- mirrors
function Logic.mirrorPresses(mirrors, current, target)
	local n, rows, transform = #mirrors, {}, {}
	if n < 1 or n > 24 or #current ~= n then
		return nil
	end
	for i = 1, n do
		if type(current[i]) ~= "number" or current[i] % 1 ~= 0 then
			return nil
		end
		transform[i] = table.create(n, 0)
		transform[i][i] = 1
		if target[i] ~= nil then
			if type(target[i]) ~= "number" or target[i] % 1 ~= 0 then
				return nil
			end
			local row = table.create(n + 1, 0)
			for j, mirror in ipairs(mirrors) do
				row[j] = i == j and 1 or 0
				for _, linked in ipairs(mirror.Links or {}) do
					if linked == i then
						row[j] += 1
					end
				end
				row[j] %= 8
			end
			row[n + 1] = (target[i] - current[i]) % 8
			table.insert(rows, row)
		end
	end
	local function divisor(value)
		return value % 2 == 1 and 1 or value % 4 == 2 and 2 or value == 4 and 4 or 8
	end
	local rank = 0
	for k = 1, math.min(n, #rows) do
		local best, ri, ci = 8, nil, nil
		for i = k, #rows do
			for j = k, n do
				local d = divisor(rows[i][j])
				if d < best then
					best, ri, ci = d, i, j
				end
			end
		end
		if not ri then
			break
		end
		rows[k], rows[ri] = rows[ri], rows[k]
		for _, row in ipairs(rows) do
			row[k], row[ci] = row[ci], row[k]
		end
		for _, row in ipairs(transform) do
			row[k], row[ci] = row[ci], row[k]
		end
		local odd = rows[k][k] / best
		for j = k, n + 1 do
			rows[k][j] = (rows[k][j] * odd) % 8
		end
		for i = k + 1, #rows do
			local q = rows[i][k] / best
			for j = k, n + 1 do
				rows[i][j] = (rows[i][j] - q * rows[k][j]) % 8
			end
		end
		for j = k + 1, n do
			local q = rows[k][j] / best
			for _, row in ipairs(rows) do
				row[j] = (row[j] - q * row[k]) % 8
			end
			for _, row in ipairs(transform) do
				row[j] = (row[j] - q * row[k]) % 8
			end
		end
		rank = k
	end
	local values = table.create(n, 0)
	for i, row in ipairs(rows) do
		if i > rank then
			if row[n + 1] ~= 0 then
				return nil
			end
		elseif row[n + 1] % row[i] ~= 0 then
			return nil
		else
			values[i] = row[n + 1] / row[i]
		end
	end
	local presses = {}
	for i, row in ipairs(transform) do
		local sum = 0
		for j = 1, n do
			sum += row[j] * values[j]
		end
		presses[i] = sum % 8
	end
	return presses
end

function Logic.solveMirrors(layout, engine, current, params, checkpoint)
	if
		type(layout) ~= "table"
		or type(layout.Mirrors) ~= "table"
		or #layout.Mirrors < 1
		or #layout.Mirrors > 24
		or type(current) ~= "table"
		or #current ~= #layout.Mirrors
	then
		return nil, "The mirror layout hasn't loaded"
	end
	for _, turn in ipairs(current) do
		if type(turn) ~= "number" or turn % 1 ~= 0 then
			return nil, "A mirror's starting position hasn't loaded"
		end
	end
	local target, yaws, nodes, stopped = {}, {}, 0, false
	local function search()
		nodes += 1
		if nodes > 200000 or checkpoint and not checkpoint() then
			stopped = true
			return nil
		end
		local ray = engine.trace(layout, yaws, params)
		if ray.Complete then
			local presses = Logic.mirrorPresses(layout.Mirrors, current, target)
			if presses then
				return presses
			end
		elseif ray.Unknown and not yaws[ray.Unknown] then
			local index = ray.Unknown
			for delta = 0, 7 do
				target[index] = (current[index] + delta) % 8
				yaws[index] = engine.yawFor(layout.Mirrors[index], target[index])
				local result = search()
				if result or stopped then
					return result
				end
			end
			target[index], yaws[index] = nil, nil
		end
		return nil
	end
	local presses = search()
	if not presses then
		return nil, stopped and "Mirror search stopped" or "Couldn't find a connected mirror route"
	end
	local turns = table.clone(current)
	for index, amount in ipairs(presses) do
		turns[index] = (turns[index] + amount) % 8
		for _, linked in ipairs(layout.Mirrors[index].Links or {}) do
			turns[linked] = (turns[linked] + amount) % 8
		end
	end
	for index, turn in ipairs(turns) do
		yaws[index] = engine.yawFor(layout.Mirrors[index], turn)
	end
	if not engine.trace(layout, yaws, params).Complete then
		return nil, "The linked mirrors changed the beam route"
	end
	return presses, turns
end

-- sliding picture
function Logic.solveCandyPicture(input, checkpoint)
	if type(input) ~= "table" or #input ~= 9 then
		return nil, "The picture hasn't loaded"
	end
	local board, seen, blank, missing = table.clone(input), {}, nil, nil
	for index, value in ipairs(board) do
		if type(value) ~= "number" or value % 1 ~= 0 or value < 0 or value > 9 or seen[value] then
			return nil, "The picture is still changing"
		end
		seen[value] = true
		if value == 0 then
			blank = index
		end
	end
	if not blank then
		return nil, "The empty picture square hasn't loaded"
	end
	for value = 1, 9 do
		if not seen[value] then
			missing = value
		end
	end
	if not missing then
		return nil, "The picture is still changing"
	end
	local function distance(a, b)
		return math.abs(math.floor((a - 1) / 3) - math.floor((b - 1) / 3)) + math.abs((a - 1) % 3 - (b - 1) % 3)
	end
	local estimate, inversions = 0, 0
	for i, value in ipairs(board) do
		if value ~= 0 then
			estimate += distance(i, value)
			for j = i + 1, 9 do
				if board[j] ~= 0 and value > board[j] then
					inversions += 1
				end
			end
		end
	end
	if inversions % 2 ~= 0 then
		return nil, "Waiting for the picture to stop moving"
	end
	local moves, nodes, stopped = {}, 0, false
	local function search(space, previous, depth, h, bound)
		nodes += 1
		if nodes > 500000 or nodes % 256 == 1 and checkpoint and not checkpoint() then
			stopped = true
			return nil
		end
		if depth + h > bound then
			return depth + h
		end
		if h == 0 then
			return true
		end
		local nextBound = math.huge
		for _, index in ipairs({ space - 3, space + 3, space - 1, space + 1 }) do
			if index >= 1 and index <= 9 and index ~= previous and distance(index, space) == 1 then
				local value = board[index]
				local nextH = h - distance(index, value) + distance(space, value)
				board[space], board[index] = value, 0
				moves[depth + 1] = index
				local result = search(index, space, depth + 1, nextH, bound)
				board[index], board[space] = value, 0
				if result == true then
					return true
				end
				moves[depth + 1] = nil
				if stopped then
					return nil
				end
				nextBound = math.min(nextBound, result or math.huge)
			end
		end
		return nextBound
	end
	local bound = estimate
	while bound <= 40 do
		local result = search(blank, nil, 0, estimate, bound)
		if result == true then
			return moves
		end
		if stopped then
			return nil, "Picture search stopped"
		end
		if not result or result == math.huge then
			break
		end
		bound = result
	end
	return nil, "Couldn't solve this picture layout"
end

return Logic

end)()
