local function log(message)
	if not App.alive then
		return
	end
	table.insert(App.logs, 1, os.date("%H:%M:%S") .. "  " .. tostring(message))
	if #App.logs > 30 then
		table.remove(App.logs)
	end
	if ui.log then
		ui.log.Text = table.concat(App.logs, "\n")
	end
end

local function status(title, detail, progress)
	if not App.alive then
		return
	end
	if
		App.status == title
		and App.detail == (detail or "")
		and (progress == nil or App.progress == math.clamp(progress, 0, 1))
	then
		return
	end
	App.status, App.detail = title, detail or ""
	if progress ~= nil then
		App.progress = math.clamp(progress, 0, 1)
	end
	refresh()
end

local function pruneConnections()
	local kept = 0
	for _, connection in ipairs(App.connections) do
		if connection.Connected ~= false then
			kept += 1
			App.connections[kept] = connection
		end
	end
	for index = #App.connections, kept + 1, -1 do
		App.connections[index] = nil
	end
	App.connectionAdds = 0
end

local function connect(signal, callback)
	App.connectionAdds = (App.connectionAdds or 0) + 1
	if App.connectionAdds >= 64 then
		pruneConnections()
	end
	local lastError, nextLog = nil, 0
	local connection = signal:Connect(function(...)
		if not App.alive then
			return
		end
		local ok, err = pcall(callback, ...)
		if not ok then
			App.errors += 1
			local message = tostring(err):sub(1, 220)
			if message ~= lastError or os.clock() >= nextLog then
				lastError, nextLog = message, os.clock() + 5
				log(message)
			end
		end
	end)
	table.insert(App.connections, connection)
	return connection
end

local function active(generation)
	return App.alive and (generation == nil or (App.running and App.generation == generation))
end

local function waitUntil(callback, seconds, generation)
	local deadline = os.clock() + (seconds or 10)
	repeat
		if not active(generation) then
			return nil, "Stopped"
		end
		local value = callback()
		if value then
			return value
		end
		task.wait(0.1)
	until os.clock() >= deadline
	return nil, "Timed out"
end

local function pause(seconds, generation)
	local finish = os.clock() + seconds
	repeat
		if not active(generation) then
			return false
		end
		task.wait(math.min(0.1, math.max(0, finish - os.clock())))
	until os.clock() >= finish
	return active(generation)
end

local function call(key, callback, seconds, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	if App.pending[key] then
		return false, "Still waiting for " .. tostring(key)
	end
	local request = { done = false }
	App.pending[key] = request
	task.spawn(function()
		request.result = table.pack(pcall(callback))
		request.done = true
		if App.pending[key] == request then
			App.pending[key] = nil
		end
	end)
	local ready, reason = waitUntil(function()
		return request.done
	end, seconds or 8, generation)
	if not ready then
		return false, reason .. ": " .. tostring(key)
	end
	if not active(generation) then
		return false, "Stopped"
	end
	return table.unpack(request.result, 1, request.result.n)
end

local function getPath(root, ...)
	local object = root
	for index = 1, select("#", ...) do
		local name = select(index, ...)
		if not object or name == nil then
			break
		end
		object = object:FindFirstChild(name)
	end
	return object
end

local function module(object, generation)
	if not object or not object:IsA("ModuleScript") then
		return nil, "Still loading"
	end
	if App.modules[object] then
		return App.modules[object]
	end
	local ok, result = call(object, function()
		return nativeRequire(object)
	end, 12, generation)
	if ok and type(result) == "table" then
		App.modules[object] = result
		return result
	end
	return nil, tostring(result)
end

local function hollowModule(name, generation)
	if type(gameGlobals.require) ~= "function" then
		return nil, "The Hollow is still loading"
