	local ok, result = call(key, function()
		return gameGlobals.require(name)
	end, 12, generation)
	if ok and type(result) == "table" then
		App.modules[key] = result
		return result
	end
	return nil, tostring(result)
end

local function invoke(remote, generation, ...)
	if not remote or not remote:IsA("RemoteFunction") then
		return false, "The game's controls haven't loaded yet"
	end
	local args = table.pack(...)
	return call(remote, function()
		return remote:InvokeServer(table.unpack(args, 1, args.n))
	end, 8, generation)
end

local function fire(remote, ...)
	if not remote or not remote:IsA("RemoteEvent") then
		return false, "The game's controls haven't loaded yet"
	end
	return pcall(remote.FireServer, remote, ...)
end

local function prepareTravel(destination, resume, autoBuyCash)
	local queue = queue_on_teleport or queueonteleport
	if type(queue) ~= "function" and type(syn) == "table" then
		queue = syn.queue_on_teleport
	end
	if type(queue) ~= "function" and type(fluxus) == "table" then
		queue = fluxus.queue_on_teleport
	end
	if type(queue) ~= "function" or type(continuationSource) ~= "string" then
		return false
	end
	local arrival = resume and tostring(destination) or "nil"
	local source = "task.spawn(function()\nlocal source = "
		.. string.format("%q", continuationSource)
		.. "\nlocal oldJob = "
		.. string.format("%q", game and game.JobId or "")
		.. [[

local deadline, stableAt, lastPlayer, lastScripts = os.clock() + 120, nil, nil, nil
while os.clock() < deadline do
    local player = game:GetService("Players").LocalPlayer
    local scripts = player and player:FindFirstChild("PlayerScripts")
    local ready = game:IsLoaded() and game.PlaceId ~= 0
        and (oldJob == "" or game.JobId ~= oldJob)
        and player and player:FindFirstChild("PlayerGui") and scripts
    if not ready or player ~= lastPlayer or scripts ~= lastScripts then
        stableAt = nil
        lastPlayer, lastScripts = player, scripts
    elseif stableAt and os.clock() - stableAt >= 1 then
        break
    end
    if ready then stableAt = stableAt or os.clock() end
    task.wait(0.25)
end
if not stableAt or os.clock() - stableAt < 1 then return end
local launch = loadstring(source)
if launch then launch(source, ]]
		.. arrival
		.. (autoBuyCash == false and ", false" or "")
		.. ") end\nend)"
	local ok = pcall(queue, source)
	return ok
end

local function character()
	local model = App.player and App.player.Character
	local root = model and model:FindFirstChild("HumanoidRootPart")
	local humanoid = model and model:FindFirstChildOfClass("Humanoid")
	if root and humanoid and humanoid.Health > 0 then
		return model, root, humanoid
	end
	return nil
end

local function positionOf(object)
	if not object then
		return nil
	end
	if object:IsA("BasePart") then
		return object.Position
	end
	if object:IsA("Model") then
		return object:GetPivot().Position
	end
	return nil
end

local function nearest(tag, predicate)
	local _, root = character()
	local found, distance
	for _, object in ipairs(Collection:GetTagged(tag)) do
		if object:IsDescendantOf(workspace) and (not predicate or predicate(object)) then
			local position = positionOf(object)
			local length = position and root and (position - root.Position).Magnitude or math.huge
			if position and (not found or length < distance) then
				found, distance = object, length
			end
		end
	end
	return found
end

local function findRaceTrack(raceId)
	for _, object in ipairs(Collection:GetTagged("RaceTrack")) do
		if object.Name == raceId and object:IsDescendantOf(workspace) then
			return object
		end
	end
	return nil
end

local function approach(position, generation, ignore, insideCabin, canMove, timing)
	local model, root, humanoid = character()
	if not model then
		return false, "Waiting for character"
	end
	if canMove and not canMove() then
		return false, "Movement paused"
	end
	if typeof(position) ~= "Vector3" or position.Y <= workspace.FallenPartsDestroyHeight + 32 then
		return false, "Unsafe destination"
	end
	call("Streaming", function()
		App.player:RequestStreamAroundAsync(position, timing and timing.streamSeconds or 3)
	end, timing and timing.streamWait or 4, generation)
	if not active(generation) or App.player.Character ~= model then
		return false, "Character changed"
	end
	if canMove and not canMove() then
		return false, "Movement paused"
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local excluded = { model }
	if ignore then
		table.insert(excluded, ignore)
	end
	for _, other in ipairs(Players:GetPlayers()) do
		if other.Character and other.Character ~= model then
			table.insert(excluded, other.Character)
		end
	end
	params.FilterDescendantsInstances = excluded
	params.RespectCanCollide = true
	params.IgnoreWater = true
	local destination
	local filters = { { Enum.RaycastFilterType.Exclude, excluded } }
	if insideCabin then
		if not ignore or not ignore:IsA("BasePart") then
			return false, "The elevator hasn't loaded yet"
		end
		local interior = ignore:FindFirstChild("ElevatorInterior")
		if interior then
			table.insert(filters, 1, { Enum.RaycastFilterType.Include, { interior } })
		end
	end
	local offsetSize = insideCabin and 1 or 2
	for _, filter in ipairs(filters) do
		params.FilterType, params.FilterDescendantsInstances = filter[1], filter[2]
		for _, offset in ipairs({
			Vector3.zero,
			Vector3.new(offsetSize, 0, 0),
			Vector3.new(-offsetSize, 0, 0),
			Vector3.new(0, 0, offsetSize),
			Vector3.new(0, 0, -offsetSize),
		}) do
			local origin = position + offset + Vector3.new(0, insideCabin and 0 or 8, 0)
			local length = insideCabin and ignore.Size.Y / 2 + 3 or 40
			local hit = workspace:Raycast(origin, Vector3.new(0, -length, 0), params)
			if hit and hit.Normal.Y > 0.6 and hit.Position.Y > workspace.FallenPartsDestroyHeight + 32 then
				local candidate = hit.Position + Vector3.new(0, math.max(2.6, humanoid.HipHeight + root.Size.Y / 2), 0)
				local safe = true
				if insideCabin then
					local point = ignore.CFrame:PointToObjectSpace(candidate)
					safe = hit.Position.Y < position.Y
						and math.abs(point.X) < ignore.Size.X / 2
						and math.abs(point.Z) < ignore.Size.Z / 2
						and math.abs(point.Y) < ignore.Size.Y / 2
				end
				if safe then
					destination = candidate
					break
				end
			end
		end
		if destination then
			break
		end
	end
	if not destination then
		return false, insideCabin and "No safe floor inside the elevator" or "Couldn't find a safe place to stand"
	end
	if not active(generation) or App.player.Character ~= model then
		return false, "Stopped"
	end
	if canMove and not canMove() then
		return false, "Movement paused"
	end
	root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	local target = CFrame.new(destination) * root.CFrame.Rotation
	if timing and type(timing.move) == "function" then
		return timing.move(model, root, humanoid, target)
	end
	model:PivotTo(target * root.CFrame:ToObjectSpace(model:GetPivot()))
	return pause(timing and timing.settleSeconds or 0.45, generation)
end

local function rideElevator(part, clientState, objects, generation, floor)
	local kind = floor and "MazeElevatorEntrance" or "MazeElevatorExit"
	local ok, controller = call(part, function()
		return objects.getObjectAsync(kind, part)
	end, 8, generation)
	if not ok or type(controller) ~= "table" or type(controller.enterElevator) ~= "function" then
		return false, "The elevator isn't ready yet"
	end
	local moved, reason = approach(part.Position, generation, part, true)
	if not moved then
		return false, reason
	end
	local rider = waitUntil(function()
		return clientState.getState("CurrentCharacter")
	end, 4, generation)
	if
		rider
		and not controller.riding
		and not clientState.getState("PromptElevator")
		and not clientState.isLocked("CharacterBusyState")
	then
		local started, why = call("Elevator animation", function()
			controller:enterElevator(rider)
		end, 5, generation)
		if not started then
			return false, why
		end
	end
	local selected = false
	local arrived = waitUntil(function()
		if floor and clientState.getState("PromptElevator") and not selected then
			selected = true
			status("Selecting floor " .. floor, "", 0.08)
			log("Elevator: selected floor " .. floor)
			clientState.setState("ElevatorSelection", floor)
		end
		local maze = App.player:GetAttribute("InMaze")
		local inMaze = maze ~= nil and maze ~= false
		return floor and inMaze and (type(maze) ~= "number" or maze == floor) or (not floor and not inMaze)
	end, 30, generation)
	if not arrived then
		local ownsRide = env.__HOLLOW_PANEL == App
			and (active(generation) or (App.generation == generation + 1 and not App.running))
		if ownsRide and floor and clientState.getState("PromptElevator") then
			clientState.setState("ElevatorSelection", -1)
		end
		return false, floor and "The elevator didn't start" or "The exit didn't open"
	end
	local ready = waitUntil(function()
		return not clientState.isLocked("CharacterBusyState")
	end, 12, generation)
	return ready ~= nil, if ready then nil else "The elevator ride got stuck. Try again."
end

-- floor 1
local function applyPipeTurns(puzzle, turns, generation)
	local board = puzzle.getBoard()
	local current = puzzle.getTurns()
	if not board or type(current) ~= "table" or #current ~= #turns then
		return false, "The puzzle is still loading"
	end
	local needed = 0
	for index, turn in ipairs(turns) do
		if type(current[index]) ~= "number" or not puzzle.isPlaced(index) then
			return false, "Puzzle tile " .. index .. " is not ready"
		end
		needed += (turn - current[index]) % 4
	end
	local kick = needed == 0 and 4 or 0
	needed += kick
	local rotated = 0
	for index, turn in ipairs(turns) do
		local attempts = 0
		local extra = index == 1 and kick or 0
		while true do
			if not active(generation) then
				return false, "Stopped"
			end
			if puzzle.isSolved() then
				return true
			end
			current = puzzle.getTurns()
			if puzzle.getBoard() ~= board or type(current) ~= "table" or type(current[index]) ~= "number" then
				return false, "Puzzle changed while rotating tiles"
			end
			if extra == 0 and (turn - current[index]) % 4 == 0 then
				break
			end
			local before = current[index]
			local ok, changed = pcall(puzzle.rotate, index)
			if not ok then
				return false, "Tile interaction failed: " .. tostring(changed)
			end
			current = puzzle.getTurns()
			if changed and type(current) == "table" and current[index] ~= before then
				attempts = 0
				extra = math.max(0, extra - 1)
				rotated += 1
				status(
					"Rotating pipe tiles",
					string.format("Tile %d / %d", index, #turns),
					0.65 + 0.2 * math.min(rotated / needed, 1)
				)
				if rotated > #turns * 12 then
					return false, "Let go of the tiles, then try again."
				end
			else
				if type(puzzle.isReached) == "function" and puzzle.isReached() then
					local accepted = waitUntil(puzzle.isSolved, 10, generation)
					if accepted then
						return true
					end
					return false, active(generation) and "The game didn't accept this solution" or "Stopped"
				end
				attempts += 1
				if attempts > 20 then
					return false, "Puzzle tile " .. index .. " did not rotate"
				end
			end
			if not pause(0.08, generation) then
				return false, "Stopped"
			end
		end
	end
	status("Waiting for the puzzle to open", "", 0.85)
	local accepted = waitUntil(puzzle.isSolved, 10, generation)
	if accepted then
		return true
	end
	return false, active(generation) and "The puzzle didn't open. Try again." or "Stopped"
end

local function readHollowData(name)
	local value = getPath(App.player, "PlayerGui", "Data", name)
	if not value or not value:IsA("StringValue") then
		return nil
	end
	local ok, decoded = pcall(Http.JSONDecode, Http, value.Value)
	return ok and decoded or nil
end

local function checkBadge(id, force)
	local cached = App.badgeState[id]
	if cached and (cached.owned == true or (not force and os.clock() - cached.at < 8)) then
		return cached.owned
	end
	if not App.player then
		return nil
	end
	local ok, owned = call("Badge " .. tostring(id), function()
		return Badges:UserHasBadgeAsync(App.player.UserId, id)
	end, 8)
	if ok and type(owned) == "boolean" then
		App.badgeState[id] = { owned = owned, at = os.clock() }
		return owned
	end
	log("Couldn't check badge: " .. tostring(id))
	return nil
end

local function verify(gameInfo, force)
	if not gameInfo.badges then
		return nil
	end
	local unknown = false
	for _, id in ipairs(gameInfo.badges) do
		local owned = checkBadge(id, force)
		if owned then
			App.rows[gameInfo.id] = "Badge earned"
			refresh()
			return true
		end
		if owned == nil then
			unknown = true
		end
	end
	App.rows[gameInfo.id] = unknown and "Couldn't check" or "Badge not earned"
	refresh()
	if unknown then
		return nil
	end
	return false
end

local function cleanRun()
	local cleanups = App.cleanups
	App.cleanups = {}
	for index = #cleanups, 1, -1 do
		pcall(cleanups[index])
	end
	pruneConnections()
end

local function stop()
	App.generation += 1
	App.running = false
	cleanRun()
	if App.doorsStop then
		pcall(App.doorsStop)
	end
	status("Stopped", "", App.progress)
end

local function claimTickets(generation)
	local earned, queued = readHollowData("EarnedBadges"), readHollowData("BadgeQueue")
	local claimed, bonus = readHollowData("ClaimedCurrencyBadges"), readHollowData("ClaimedBonusBadges")
	local config = module(getPath(Storage, "Config", "CurrencyBadgeConfig"), generation)
	if not config or not earned or not claimed or not bonus then
		return false, "Badges are still loading"
	end
	local count = 0
	for id, reward in pairs(config) do
		if Logic.contains(earned, id) or Logic.contains(queued, id) then
			if
				not Logic.contains(claimed, id)
				or (reward.featuredDay == workspace:GetAttribute("EventDay") and not Logic.contains(bonus, id))
			then
				count += 1
			end
		end
	end
	if count == 0 then
		return true, "No tickets to claim"
	end
	local ok, reason = fire(getPath(Storage, "Remotes", "ClaimBadgeCurrency"))
	if not ok then
		return false, reason
	end
	local changed = waitUntil(function()
		local latest = readHollowData("ClaimedCurrencyBadges")
		local latestBonus = readHollowData("ClaimedBonusBadges")
		return latest and latestBonus and (#latest > #claimed or #latestBonus > #bonus)
	end, 8, generation)
	return changed ~= nil, changed and "Tickets claimed" or "Claim sent. Check your tickets in the game."
end

-- floor 2
local Pillars = {}

function Pillars.signature(packet)
	if type(packet.Faces) ~= "table" or packet.Target == nil then
		return nil
	end
	local parts = { tostring(packet.Target) }
	local count = 0
	for name in pairs(packet.Faces) do
		if type(name) == "string" then
			count = math.max(count, tonumber(name:match("^Pillar([1-8])$")) or 0)
		end
	end
	if count == 0 then
		return nil
	end
	for index = 1, count do
		local faces = packet.Faces["Pillar" .. index]
		if type(faces) ~= "table" then
			return nil
		end
		for _, side in ipairs({ "Front", "Back", "Left", "Right" }) do
			if faces[side] == nil then
				return nil
			end
			table.insert(parts, tostring(faces[side]))
		end
	end
	return table.concat(parts, "\0")
end

function Pillars.watch(generation)
	local remote = getPath(Storage, "Remotes", "ThreePillars")
	if not remote or not remote:IsA("RemoteEvent") then
		return nil, "Waiting for the pillar puzzle to load"
	end
	local session =
		{ version = 0, epoch = 0, effects = {}, costs = {}, turns = {}, resets = 0, retries = {}, count = 6 }
	local connection = remote.OnClientEvent:Connect(function(packet)
		if not active(generation) or type(packet) ~= "table" or type(packet.Kind) ~= "string" then
			return
		end
		local maze = App.player:GetAttribute("InMaze")
		if maze == nil or maze == false or type(maze) == "number" and maze ~= 2 then
			return
		end
		session.version += 1
		session.kind = packet.Kind
		session.changedAt = os.clock()
		local previousBudget = session.turnsLeft
		if type(packet.TurnsLeft) == "number" and packet.TurnsLeft % 1 == 0 and packet.TurnsLeft >= 0 then
			session.turnsLeft = packet.TurnsLeft
		end
		if packet.Kind == "Scramble" then
			local signature = Pillars.signature(packet)
			if not signature or session.signature and session.signature ~= signature then
				session.effects, session.costs = {}, {}
			end
			if session.resetting or previousBudget and session.turnsLeft and session.turnsLeft > previousBudget then
				session.resets += 1
			end
			session.signature, session.epoch = signature, session.epoch + 1
			session.turns, session.resetting, session.count = {}, false, 0
			session.solved = packet.Solved == true
		elseif packet.Kind == "Reset" then
			session.resets += 1
			session.resetting = false
		elseif packet.Kind == "Solve" or packet.Kind ~= "Spin" and packet.Solved == true then
			session.solved = true
		end
		if type(packet.Steps) == "table" then
			for _, step in ipairs(packet.Steps) do
				if
					type(step) == "table"
					and type(step.Name) == "string"
					and type(step.Turn) == "number"
					and step.Turn % 1 == 0
					and math.abs(step.Turn) < math.huge
				then
					local index = tonumber(step.Name:match("^Pillar([1-8])$"))
					if index then
						session.turns[index] = step.Turn % 4
						session.count = math.max(session.count, index)
					end
				end
			end
		end
		if type(packet.Faces) == "table" then
			for name in pairs(packet.Faces) do
				if type(name) == "string" then
					session.count = math.max(session.count, tonumber(name:match("^Pillar([1-8])$")) or 0)
				end
			end
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
		Pillars.release(session)
	end)
	return session
end

function Pillars.alive(clientState, generation, model)
	local live, root, humanoid = character()
	local maze = App.player:GetAttribute("InMaze")
	return active(generation)
		and live
		and (not model or live == model)
		and not root.Anchored
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and maze ~= nil
		and maze ~= false
		and (type(maze) ~= "number" or maze == 2)
		and not clientState.isLocked("CharacterBusyState")
		and not clientState.getState("ElevatorTeleporting")
end

function Pillars.find(objects, generation, session)
	local lever = nearest("%PillarLever")
	if not lever or not lever:IsA("BasePart") then
		return nil
	end
	local group, parts, count = lever.Parent, {}, 0
	for _, part in ipairs(Collection:GetTagged("%ThreePillar")) do
		if part:IsA("BasePart") and part.Parent == group then
			local index = tonumber(part.Name:match("^Pillar([1-8])$"))
			if index then
				parts[index] = part
				count = math.max(count, index)
			end
		end
	end
	if count == 0 or session and count ~= session.count then
		return nil
	end
	for index = 1, count do
		if not parts[index] then
			return nil
		end
	end
	local result = { group = group, pillars = {}, count = count }
	for index = 1, count + 1 do
		local part = index == count + 1 and lever or parts[index]
		local kind = index == count + 1 and "PillarLever" or "ThreePillar"
		local ok, object = call(part, function()
			return objects.getObjectAsync(kind, part)
		end, 5, generation)
		if not ok or not object or object.adornee ~= part or not object.prompt then
			return nil
		end
		if index == count + 1 then
			result.lever = object
		else
			result.pillars[index] = object
		end
	end
	return result
end

function Pillars.read(group, session)
	local turns = {}
	if session and group.count ~= session.count then
		return nil
	end
	if not group.group:IsDescendantOf(workspace) or group.lever.adornee.Parent ~= group.group then
		return nil
	end
	if not group.lever.prompt.Parent or not group.lever.prompt.Enabled then
		return nil
	end
	for index, pillar in ipairs(group.pillars) do
		local part, prompt = pillar.adornee, pillar.prompt
		if
			part.Parent ~= group.group
			or not prompt.Parent
			or not prompt.Enabled
			or typeof(pillar.restCFrame) ~= "CFrame"
		then
			return nil
		end
		local relative = pillar.restCFrame:ToObjectSpace(part.CFrame)
		local look = relative.LookVector
		if math.abs(look.Y) > 0.02 or relative.UpVector.Y < 0.99 then
			return nil
		end
		local quarter = math.atan2(-look.X, -look.Z) / (math.pi / 2)
		local rounded = math.round(quarter)
		if math.abs(quarter - rounded) > 0.02 then
			return nil
		end
		turns[index] = rounded % 4
		if session and session.turns[index] ~= nil and turns[index] ~= session.turns[index] then
			return nil
		end
	end
	if session and session.changedAt and os.clock() - session.changedAt < 0.55 then
		return nil
	end
	return turns
end

function Pillars.aligned(turns)
	for _, turn in ipairs(turns) do
		if turn ~= 0 then
			return false
		end
	end
	return #turns > 0
end

function Pillars.turnBudget(session)
	if session.turnsLeft ~= nil then
		return session.turnsLeft
	end
	for _, frame in ipairs(Collection:GetTagged("%RiddleFrame")) do
		if frame:IsDescendantOf(workspace) and frame:GetAttribute("Riddle") == "Pillars" then
			for _, face in ipairs(frame:GetChildren()) do
				local footer = face:IsA("SurfaceGui") and getPath(face, "Card", "Footer")
				if footer and footer:IsA("TextLabel") and footer.Visible then
					if footer.Text == "Next turn resets" then
						return 0
					end
					local count = tonumber(footer.Text:match("^(%d+) turns? left$"))
					if count then
						return count
					end
				end
			end
		end
	end
	return nil
end

function Pillars.release(session)
	local hold = session.hold
	session.hold = nil
	if not hold then
		return
	end
	if hold.began then
		pcall(hold.prompt.InputHoldEnd, hold.prompt)
	end
	if
		hold.camera
		and workspace.CurrentCamera == hold.camera
		and hold.camera.CFrame == hold.aim
		and hold.cameraEpoch == App.cameraEpoch
	then
		hold.camera.CFrame = hold.previous
	end
end

function Pillars.press(session, group, object, clientState, generation)
	local model = character()
	local prompt, part = object.prompt, object.adornee
	local function allowed()
		return Pillars.alive(clientState, generation, model)
			and part.Parent == group.group
			and part:IsDescendantOf(workspace)
			and prompt.Parent
			and prompt.Enabled
			and not session.solved
			and App.player:GetAttribute("HasRelic") ~= true
	end
	if not allowed() then
		return nil, "Waiting for the pillar controls"
	end
	local offset = math.clamp(prompt.MaxActivationDistance * 0.5, 1, 4)
	local moved, reason = approach(part.Position + part.CFrame.LookVector * offset, generation, part, false, allowed)
	if not moved or not allowed() then
		return nil, reason or "The pillar controls changed"
	end
	local before = Pillars.read(group, session)
	if not before then
		return nil, "Waiting for the pillars to stop turning"
	end
	if object == group.lever and not Pillars.aligned(before) then
		return nil, "The pillar alignment changed"
	end
	local _, root = character()
	local anchor = prompt.Parent:IsA("Attachment") and prompt.Parent.WorldPosition or part.Position
	if (root.Position - anchor).Magnitude > prompt.MaxActivationDistance + 0.5 then
		return nil, "Couldn't get close enough to the pillar control"
	end
	local version, epoch, beforeBudget = session.version, session.epoch, Pillars.turnBudget(session)
	for index = 1, #before do
		if session.turns[index] == nil then
			session.turns[index] = before[index]
		end
	end
	local hold = { prompt = prompt }
	session.hold = hold
	local camera = workspace.CurrentCamera
	if
		camera
		and not App.cameraBusy
		and camera.CameraType ~= Enum.CameraType.Scriptable
		and (camera.CFrame.Position - anchor).Magnitude > 0.1
	then
		hold.camera, hold.previous, hold.cameraEpoch = camera, camera.CFrame, App.cameraEpoch
		hold.aim = CFrame.lookAt(camera.CFrame.Position, anchor)
		camera.CFrame = hold.aim
	end
	local sent, inputError
	if type(fireproximityprompt) == "function" then
		sent, inputError = call(prompt, function()
			if allowed() then
				return fireproximityprompt(prompt)
			end
			error("Pillar input cancelled")
		end, math.clamp(prompt.HoldDuration, 0, 10) + 3, generation)
	else
		hold.began = true
		sent, inputError = pcall(prompt.InputHoldBegin, prompt)
		if sent then
			local untilTime = os.clock() + math.clamp(prompt.HoldDuration, 0, 10) + 0.1
			while allowed() and os.clock() < untilTime and session.version == version do
				if not pause(0.05, generation) then
					break
				end
			end
		end
	end
	Pillars.release(session)
	if not sent then
		return false, inputError or "The pillar input didn't start"
	end
	local confirmed = waitUntil(function()
		if not Pillars.alive(clientState, generation, model) then
			return { cancelled = true }
		end
		if App.player:GetAttribute("HasRelic") == true or session.solved then
			return { solved = true }
		end
		if session.epoch ~= epoch then
			return { changed = true }
		end
		if session.version > version then
			local after = Pillars.read(group, session)
			if after then
				return {
					before = before,
					after = after,
					kind = session.kind,
					beforeBudget = beforeBudget,
					afterBudget = Pillars.turnBudget(session),
				}
			end
		end
		return nil
	end, 12, generation)
	if not confirmed then
		return false,
			active(generation) and "The pillar press wasn't confirmed. Check the puzzle before trying again."
				or "Stopped"
	end
	if confirmed.cancelled then
		return false, "The character or floor changed"
	end
	return confirmed
end

function Pillars.solve(session, objects, clientState, generation)
	local deadline, actions, missingAt, group = os.clock() + 180, 0, os.clock(), nil
	while active(generation) and os.clock() < deadline and actions < 40 do
		if App.player:GetAttribute("HasRelic") == true or session.solved then
			return true
		end
		if not Pillars.alive(clientState, generation) then
			return false, "Waiting for your character to finish entering floor 2"
		end
		if group then
			for _, pillar in ipairs(group.pillars) do
				if pillar.adornee.Parent ~= group.group then
					group = nil
					break
				end
			end
		end
		if
			not group
			or group.count ~= session.count
			or not group.group:IsDescendantOf(workspace)
			or group.lever.adornee.Parent ~= group.group
		then
			group = Pillars.find(objects, generation, session)
		end
		if group and session.group ~= group.group then
			if session.group then
				session.effects, session.costs, session.turns = {}, {}, {}
			end
			session.group = group.group
			log("Pillar room: " .. group.count .. " stones")
		end
		local turns = group and Pillars.read(group, session)
		if not turns then
			status("Loading floor 2", "Waiting for all " .. session.count .. " pillars and the lever", 0.15)
			if os.clock() - missingAt > 45 then
				return false, "The pillar controls haven't loaded. Move closer to the pillar room and press Start."
			end
			if not group and os.clock() >= (session.probeAfter or 0) then
				session.probeAfter = os.clock() + 8
				local hint = nearest("%RiddleFrame", function(frame)
					return frame:GetAttribute("Riddle") == "Pillars"
				end)
				if hint and hint:IsA("BasePart") then
					approach(hint.Position, generation, hint, false, function()
						return Pillars.alive(clientState, generation) and hint:IsDescendantOf(workspace)
					end)
				end
			end
			if not pause(0.3, generation) then
				break
			end
			continue
		end
		missingAt = os.clock()
		local aligned = Pillars.aligned(turns)
		local plan, planCost
		if not aligned then
			local slice = os.clock()
			plan, planCost = Logic.solvePillars(turns, session.effects, nil, session.costs, function()
				if os.clock() - slice > 0.003 then
					task.wait()
					slice = os.clock()
				end
				return active(generation) and os.clock() < deadline
			end)
		end
		local budget = Pillars.turnBudget(session)
		local action = plan and plan[1]
		local learning = false
		if plan and (budget == nil or planCost <= math.max(0, budget - (session.leverReserve or 0))) then
			session.resetting = false
		end
		if not aligned and (not action or budget and planCost > math.max(0, budget - (session.leverReserve or 0))) then
			action = nil
			for index = 1, #turns do
				if not session.effects[index] then
					action = index
					learning = true
					break
				end
			end
			if not action then
				if budget == nil then
					return false, "The pillar links don't give a solution, and the turn counter is missing."
				end
				session.resetting = true
				local largest = -1
				for index = 1, #turns do
					local cost = session.costs[index] or 1
					if cost > largest then
						action, largest = index, cost
					end
				end
				if largest == 0 and budget > 0 then
					return false, "The pillar links changed. Check the last turns in Logs."
				end
			end
		end
		status(
			aligned and "Pulling the pillar lever"
				or learning and "Learning pillar " .. action
				or session.resetting and "Resetting the turn budget"
				or "Solving the pillars",
			aligned and "All three symbols are lined up"
				or "Pillars: "
					.. table.concat(turns, " / ")
					.. (budget and string.format(" | %d turns left", budget) or ""),
			aligned and 0.85 or 0.55
		)
		local result, why =
			Pillars.press(session, group, aligned and group.lever or group.pillars[action], clientState, generation)
		if result == false then
			return false, why
		elseif result == nil then
			local target = aligned and group.lever or group.pillars[action]
			session.retries[target] = (session.retries[target] or 0) + 1
			if session.retries[target] >= 3 then
				return false, why or "Couldn't reach the pillar control"
			end
		elseif result then
			actions += 1
			session.retries = {}
			if result.solved then
				return true
			elseif result.changed then
				if aligned then
					session.leverReserve = 1
				end
				group = nil
			elseif not aligned and result.kind == "Spin" then
				local effect, previous, changed = {}, session.effects[action], false
				for index = 1, #result.before do
					effect[index] = (result.after[index] - result.before[index]) % 4
					changed = changed or previous ~= nil and previous[index] ~= effect[index]
				end
				if changed then
					session.effects, session.costs = {}, {}
					log("The pillars changed, checking them again")
				end
				session.effects[action] = effect
				if result.beforeBudget and result.afterBudget and result.beforeBudget >= result.afterBudget then
					session.costs[action] = result.beforeBudget - result.afterBudget
				end
				log(
					string.format(
						"Pillar %d: %s -> %s | cost %s | %s turns left",
						action,
						table.concat(result.before, "/"),
						table.concat(result.after, "/"),
						tostring(session.costs[action] or "?"),
						tostring(result.afterBudget or "?")
					)
				)
			elseif aligned and result.kind == "Reset" then
				session.leverReserve = 1
			end
			if result.kind == "Reset" or result.changed then
				session.resetting = false
				log("Pillar layout reset")
			end
			if session.resets > 3 then
				return false, "The pillar puzzle reset several times. Check the room before trying again."
			end
		end
		if not pause(0.15, generation) then
			break
		end
	end
	return false, active(generation) and "Couldn't finish this pillar layout within the attempt limit" or "Stopped"
end

-- floor 3
local Tomb = {}

function Tomb.alive(clientState, generation, model)
	local live, root, humanoid = character()
	local floor = App.player:GetAttribute("InMaze")
	return active(generation)
		and live
		and (not model or live == model)
		and not root.Anchored
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and floor ~= nil
		and floor ~= false
		and (type(floor) ~= "number" or floor == 3)
		and not clientState.isLocked("CharacterBusyState")
		and not clientState.getState("ElevatorTeleporting")
end

function Tomb.read(object, icons)
	if not object.applied or not object.adornee:IsDescendantOf(workspace) then
		return nil
	end
	local plate = object.adornee:FindFirstChild("EpitaphPlate") or object.adornee
	local card = getPath(plate, "Epitaph", "Card")
	local dates, image = getPath(card, "Dates"), getPath(card, "IconSlot", "Icon")
	if not dates or not dates:IsA("TextLabel") or not image or not image:IsA("ImageLabel") then
		return nil
	end
	local text = dates.Text:gsub("\226\128\147", "|"):gsub("\226\128\148", "|"):gsub("%s+%-%s+", "|")
	local birth, death = text:match("^%s*(%-?%d+)%s*|%s*(%-?%d+)%s*$")
	if not birth or not death then
		return nil
	end
	for name, asset in pairs(icons) do
		if image.Image == asset then
			return { key = object.key, icon = name, birth = tonumber(birth), death = tonumber(death) }
		end
	end
	return nil
end

function Tomb.scan(session, objects, icons, generation)
	local records, seen, pending, closest = {}, {}, nil, math.huge
	local _, root = character()
	for _, part in ipairs(Collection:GetTagged("%TombStone")) do
		if part:IsA("BasePart") and part:IsDescendantOf(workspace) then
			local object = session.objects[part]
			if not object then
				local ok, result = call(part, function()
					return objects.getObjectAsync("TombStone", part)
				end, 3, generation)
				if ok and result and type(result.key) == "string" then
					object = result
					session.objects[part] = object
				end
			end
			if object and not seen[object.key] then
				seen[object.key] = true
				local record = Tomb.read(object, icons)
				if record then
					table.insert(records, record)
				elseif root and os.clock() >= (session.retryAt[part] or 0) then
					local distance = (part.Position - root.Position).Magnitude
					if distance < closest then
						pending, closest = object, distance
					end
				end
			end
		end
	end
	table.sort(records, function(a, b)
		return a.key < b.key
	end)
	local keys = {}
	for _, record in ipairs(records) do
		table.insert(keys, record.key .. ":" .. record.icon .. ":" .. record.birth .. ":" .. record.death)
	end
	return records, pending, table.concat(keys, "|")
end

function Tomb.solve(objects, clientState, generation)
	local puzzle, why = hollowModule("TombStone", generation)
	local style = hollowModule("HauntUI", generation)
	if not puzzle or not style or type(style.Icons) ~= "table" then
		return false, why or "The grave puzzle hasn't loaded"
	end
	local session =
		{ objects = setmetatable({}, { __mode = "k" }), retryAt = setmetatable({}, { __mode = "k" }), failures = {} }
	local deadline, lastChange, fingerprint = os.clock() + 300, os.clock(), nil
	local stableAt, attempts, coffin = os.clock(), 0, nil
	while active(generation) and os.clock() < deadline do
		if App.player:GetAttribute("HasRelic") == true or puzzle.isSolved() then
			return true
		end
		if not Tomb.alive(clientState, generation) then
			return false, "The character or floor changed"
		end
		if not coffin or not coffin.adornee:IsDescendantOf(workspace) then
			local part = nearest("%TombChest")
			if part then
				local ok, object = call(part, function()
					return objects.getObjectAsync("TombChest", part)
				end, 5, generation)
				if ok and object and object.body and object.body:IsA("BasePart") then
					coffin = object
				end
			end
		end
		local records, pending, signature = Tomb.scan(session, objects, style.Icons, generation)
		if not active(generation) then
			break
		end
		if signature ~= fingerprint then
			fingerprint, stableAt, lastChange = signature, os.clock(), os.clock()
		end
		local read, total = puzzle.getReadCount()
		local ready, slots = puzzle.isReady(), puzzle.getSlotCount()
		read, total = tonumber(read) or 0, tonumber(total) or 0
		status(
			"Reading the graves",
			string.format("%d / %d graves read", read, total),
			total > 0 and 0.15 + 0.5 * math.min(read / total, 1) or 0.1
		)
		if ready and pending then
			local part, model = pending.adornee, character()
			local function allowed()
				return Tomb.alive(clientState, generation, model) and part:IsDescendantOf(workspace)
			end
			local moved, reason = approach(part.Position + part.CFrame.LookVector * 4, generation, part, false, allowed)
			if not active(generation) then
				break
			end
			local revealed = moved
				and waitUntil(function()
					if not allowed() then
						return nil
					end
					return Tomb.read(pending, style.Icons)
				end, 6, generation)
			if not revealed then
				session.failures[part] = (session.failures[part] or 0) + 1
				session.retryAt[part] = os.clock() + 4
				if session.failures[part] >= 3 then
					return false, reason or "A grave isn't revealing. Move closer and try again."
				end
			end
		elseif
			ready
			and coffin
			and total > 0
			and read >= total
			and #records == total
			and os.clock() - stableAt >= 1
		then
			local combo, rows = Logic.solveTomb(records, slots)
			if not combo then
				return false, rows
			end
			local body, model = coffin.body, character()
			local function allowed()
				return Tomb.alive(clientState, generation, model) and coffin.adornee:IsDescendantOf(workspace)
			end
			local moved, reason =
				approach(body.Position + body.CFrame.LookVector * 4, generation, coffin.adornee, false, allowed)
			if not moved then
				return false, reason
			end
			local latest, _, latestKey = Tomb.scan(session, objects, style.Icons, generation)
			local currentRead, currentTotal = puzzle.getReadCount()
			if latestKey ~= signature or currentRead ~= currentTotal or #latest ~= currentTotal then
				stableAt = os.clock()
				continue
			end
			if not allowed() then
				return false, "The character or floor changed"
			end
			if (select(2, character()).Position - body.Position).Magnitude > 10 then
				return false, "Couldn't get close enough to the coffin"
			end
			local summary = {}
			for index = 1, slots do
				table.insert(summary, rows[index].icon .. " (" .. rows[index].age .. " years)")
			end
			log("Coffin: " .. table.concat(summary, ", "))
			status("Unlocking the coffin", table.concat(combo, " / "), 0.8)
			local ok, result = call("Tomb combination", function()
				if not allowed() then
					return nil
				end
				return puzzle.guess(table.clone(combo))
			end, 10, generation)
			if not active(generation) then
				break
			end
			if not ok or type(result) ~= "table" then
				return false, "The coffin reply hasn't arrived. Wait before trying again."
			end
			if result.Result == "Correct" or puzzle.isSolved() then
				return true
			end
			attempts += 1
			if result.Result == "Wrong" then
				return false, "The coffin rejected the lifespan order. Check the grave details in Logs."
			end
			if attempts >= 3 then
				return false, "The coffin still wants more grave data. Explore the room and try again."
			end
			if result.Result == "Unread" then
				local offset = ({ Vector3.new(80, 0, 0), Vector3.new(-80, 0, 0), Vector3.new(0, 0, 80) })[attempts]
				call("Tomb streaming", function()
					App.player:RequestStreamAroundAsync(body.Position + offset, 2)
				end, 3, generation)
			elseif result.Result ~= "Wait" and result.Result ~= "Far" then
				return false, "The coffin returned an unknown result"
			end
			stableAt = os.clock()
			if not pause(math.clamp(tonumber(result.Wait) or 1, 1, 15), generation) then
				break
			end
		elseif not coffin or not ready or total == 0 then
			if os.clock() >= (session.hintAt or 0) then
				session.hintAt = os.clock() + 8
				local hint = nearest("%RiddleFrame", function(part)
					return part:GetAttribute("Riddle") == "Tombstone"
				end)
				if hint then
					approach(hint.Position, generation, hint, false, function()
						return Tomb.alive(clientState, generation)
					end)
				end
			end
		end
		if os.clock() - lastChange > 60 then
			return false, "No new graves have loaded for a minute. Move into the grave room and try again."
		end
		if not pause(0.2, generation) then
			break
		end
	end
	return false, active(generation) and "The grave puzzle reached its time limit" or "Stopped"
end

-- floor 4
local Bridge = {}

function Bridge.alive(clientState, generation, model)
	local live, root, humanoid = character()
	local floor = App.player:GetAttribute("InMaze")
	return active(generation)
		and live
		and (not model or model == live)
		and floor ~= nil
		and floor ~= false
		and (type(floor) ~= "number" or floor == 4)
		and not root.Anchored
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and not clientState.isLocked("CharacterBusyState")
		and not clientState.getState("ElevatorTeleporting")
end

function Bridge.route(puzzle)
	if
		type(puzzle.path) ~= "table"
		or type(puzzle.tiles) ~= "table"
		or #puzzle.path == 0
		or #puzzle.path > 500
		or type(puzzle.columns) ~= "number"
		or type(puzzle.rows) ~= "number"
	then
		return nil
	end
	local route, seen = {}, {}
	for _, index in ipairs(puzzle.path) do
		local tile = type(index) == "number" and puzzle.tiles[index]
		if
			type(index) ~= "number"
			or index % 1 ~= 0
			or index < 1
			or index > puzzle.columns * puzzle.rows
			or seen[index]
			or type(tile) ~= "table"
			or not tile.Part
			or not tile.Rest
			or tile.Broken
		then
			return nil
		end
		seen[index] = true
		table.insert(route, { index = index, tile = tile })
	end
	return route
end

function Bridge.land(session, puzzle, part, generation, clientState, tile)
	local model, root, humanoid = character()
	if not model or not Bridge.alive(clientState, generation, model) then
		return false
	end
	local function allowed()
		return Bridge.alive(clientState, generation, model)
			and puzzle.adornee:IsDescendantOf(workspace)
			and puzzle.state == "Play"
			and part.Parent
			and part.CanCollide
			and (not tile or not tile.Broken)
	end
	if not allowed() then
		return false
	end
	local height = humanoid.HipHeight + root.Size.Y / 2 + part.Size.Y / 2 + 0.05
	local destination = (tile and tile.Rest.Position or part.Position) + Vector3.new(0, height, 0)
	session.control = { root = root, humanoid = humanoid }
	humanoid:Move(Vector3.zero, false)
	humanoid.Jump = false
	if not allowed() then
		return false
	end
	root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	model:PivotTo(model:GetPivot() + (destination - root.Position))
	local deadline = os.clock() + 2
	while active(generation) and Bridge.alive(clientState, generation, model) and os.clock() < deadline do
		if App.player:GetAttribute("HasRelic") == true or puzzle.state == "Won" then
			return true
		end
		if not allowed() then
			return false
		end
		humanoid:Move(Vector3.zero, false)
		root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
		local delta = root.Position - destination
		if
			Vector3.new(delta.X, 0, delta.Z).Magnitude < math.min(2, part.Size.X * 0.3)
			and math.abs(delta.Y) < 4
			and (not tile or tile.Lit == true)
		then
			return true
		end
		if not pause(0.05, generation) then
			break
		end
	end
	return false
end

function Bridge.solve(objects, clientState, generation)
	local session = {}
	table.insert(App.cleanups, function()
		local control = session.control
		if control then
			pcall(function()
				local _, root, humanoid = character()
				if root == control.root and humanoid == control.humanoid then
					humanoid:Move(Vector3.zero, false)
				end
			end)
		end
	end)
	local failures, pendingAt = 0, os.clock()
	while active(generation) and os.clock() - pendingAt < 240 do
		if App.player:GetAttribute("HasRelic") == true then
			return true
		end
		local part = nearest("%ZombieBridge")
		if not part then
			status("Loading the bridge", "Waiting for the bridge to load", 0.1)
			if not pause(0.25, generation) then
				break
			end
			continue
		end
		local ok, puzzle = call("Loading the bridge", function()
			return objects.getObjectAsync("ZombieBridge", part)
		end, 8, generation)
		if not ok or type(puzzle) ~= "table" or puzzle.adornee ~= part then
			if not pause(0.5, generation) then
				break
			end
			continue
		end
		if not Bridge.alive(clientState, generation) then
			return false, "The character or floor changed"
		end
		if puzzle.state == "Loading" then
			status("Loading the bridge", "Waiting for the game's route", 0.1)
		elseif puzzle.state == "Idle" then
			local platform = puzzle.startPlatform
			if not platform or not platform.Parent then
				return false, "The bridge's starting platform is missing"
			end
			status("Starting the bridge", "Moving onto the starting platform", 0.15)
			local moved = approach(platform.Position, generation, nil, false, function()
				return Bridge.alive(clientState, generation)
					and part:IsDescendantOf(workspace)
					and puzzle.state == "Idle"
			end)
			if not moved then
				failures += 1
			end
		elseif puzzle.state == "Show" then
			status("Watching the zombie", "Waiting for the full demonstration", 0.25)
		elseif puzzle.state == "Fail" then
			status("Retrying the bridge", "Waiting for the game to reset the tiles", 0.2)
		elseif puzzle.state == "Won" then
			status("Bridge crossed", "Waiting for the relic to be awarded", 0.85)
			if
				waitUntil(function()
					return App.player:GetAttribute("HasRelic") == true or puzzle.state ~= "Won"
				end, 12, generation) and App.player:GetAttribute("HasRelic") == true
			then
				return true
			end
		elseif puzzle.state == "Play" then
			local route = Bridge.route(puzzle)
			if not route then
				return false, "The bridge route hasn't finished loading or changed unexpectedly"
			end
			local landed = true
			for index, step in ipairs(route) do
				if App.player:GetAttribute("HasRelic") == true or puzzle.state == "Won" then
					break
				end
				if
					puzzle.state ~= "Play"
					or puzzle.path[index] ~= step.index
					or puzzle.tiles[step.index] ~= step.tile
				then
					landed = false
					break
				end
				if not step.tile.Lit then
					status(
						"Crossing the bridge",
						string.format("Safe tile %d / %d", index, #route),
						0.3 + 0.45 * index / #route
					)
					landed = Bridge.land(session, puzzle, step.tile.Part, generation, clientState, step.tile)
					if not landed or not pause(0.16, generation) then
						landed = false
						break
					end
				end
			end
			if not active(generation) then
				return false, "Stopped"
			end
			if landed and puzzle.state == "Play" and App.player:GetAttribute("HasRelic") ~= true then
				local platform = puzzle.endPlatform
				if not platform or not platform.Parent then
					return false, "The bridge's exit platform is missing"
				end
				status("Finishing the bridge", "Teleporting onto the exit platform", 0.8)
				landed = Bridge.land(session, puzzle, platform, generation, clientState)
				if landed then
					waitUntil(function()
						return App.player:GetAttribute("HasRelic") == true or puzzle.state ~= "Play"
					end, 2, generation)
				end
			end
			if not landed or puzzle.state == "Play" and App.player:GetAttribute("HasRelic") ~= true then
				failures += 1
			end
		else
			return false, "The bridge changed. Try Start again."
		end
		if failures >= 4 then
			return false, "The bridge didn't accept the landing after four attempts"
		end
		if not pause(0.15, generation) then
			break
		end
	end
	return false, active(generation) and "The bridge didn't finish in time" or "Stopped"
end

function Bridge.completed()
	for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
		if tonumber(number) == 4 then
			return true
		end
	end
	return false
end

do
	-- floor 5
	local Mirrors = {}
	Mirrors.maxAttempts = 64

	function Mirrors.completed()
		for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
			if tonumber(number) == 5 then
				return true
			end
		end
		return false
	end

	function Mirrors.alive(puzzle, clientState, generation, model)
		local live, root = character()
		local floor = App.player:GetAttribute("InMaze")
		return active(generation)
			and live == model
			and root
			and not root.Anchored
			and floor ~= nil
			and floor ~= false
			and (type(floor) ~= "number" or floor == 5)
			and puzzle.adornee:IsDescendantOf(workspace)
			and not clientState.isLocked("CharacterBusyState")
			and not clientState.getState("ElevatorTeleporting")
	end

	function Mirrors.state(puzzle, generation)
		local remote = getPath(Storage, "Remotes", "LightMirrorState")
		local ok, state = invoke(remote, generation)
		if
			not ok
			or type(state) ~= "table"
			or type(state.Turns) ~= "table"
			or #state.Turns ~= #puzzle.layout.Mirrors
		then
			return nil
		end
		for _, turn in ipairs(state.Turns) do
			if type(turn) ~= "number" or turn % 1 ~= 0 or math.abs(turn) == math.huge then
				return nil
			end
		end
		return state
	end

	function Mirrors.solve(objects, clientState, generation)
		local engine, why = hollowModule("LightBeam", generation)
		if not engine then
			return false, why
		end
		hollowModule("LightPuzzle", generation)
		status("Loading the mirrors", "Waiting for floor 5's puzzle", 0.12)
		local part = waitUntil(function()
			return nearest("%LightPuzzle")
		end, 45, generation)
		if not part then
			return false, "The mirrors haven't loaded yet"
		end
		local ok, puzzle = call("Loading the mirrors", function()
			return objects.getObjectAsync("LightPuzzle", part)
		end, 12, generation)
		if not ok or type(puzzle) ~= "table" or puzzle.adornee ~= part then
			return false, "The mirrors aren't ready yet"
		end
		if
			not waitUntil(function()
				return puzzle.layout and puzzle.mirrors and puzzle.turns
			end, 15, generation)
		then
			return false, "Waiting for the mirrors' starting positions"
		end
		local model = character()
		local function alive()
			return Mirrors.alive(puzzle, clientState, generation, model)
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Include
		params.FilterDescendantsInstances = { puzzle.layout.Blockers }
		for attempt = 1, Mirrors.maxAttempts do
			if not alive() then
				return false, "The character or floor changed"
			end
			if App.player:GetAttribute("HasRelic") == true then
				return true
			end
			local state = Mirrors.state(puzzle, generation)
			if not state then
				return false, "The mirror positions haven't loaded. Try again."
			end
			if state.Solved == true then
				break
			end
			status(
				"Solving the mirrors",
				string.format("Finding a beam route  |  Try %d / %d", attempt, Mirrors.maxAttempts),
				0.25
			)
			local deadline, slice = os.clock() + 30, os.clock()
			local presses, target = Logic.solveMirrors(puzzle.layout, engine, state.Turns, params, function()
				if os.clock() - slice > 0.003 then
					task.wait()
					slice = os.clock()
				end
				return alive() and os.clock() < deadline
			end)
			if not presses then
				return false, target
			end
			local expected, changed, total, done = table.clone(state.Turns), false, 0, 0
			for _, count in ipairs(presses) do
				total += count
			end
			for index, count in ipairs(presses) do
				if changed then
					break
				end
				for _ = 1, count do
					local mirror = puzzle.mirrors[index]
					if not alive() or not mirror or not mirror.Info or not mirror.Info.Base.Parent then
						return false, "A mirror or the character changed"
					end
					status(
						"Turning the mirrors",
						string.format("%d / %d turns", done, total),
						0.3 + 0.45 * done / math.max(total, 1)
					)
					local moved, reason = approach(mirror.Info.Base.Position, generation, nil, false, alive)
					if not moved then
						return false, reason
					end
					if puzzle.solved or App.player:GetAttribute("HasRelic") == true then
						break
					end
					if
						not waitUntil(function()
							return not puzzle.submitting
						end, 8, generation) or not alive()
					then
						return false, "Waiting for the mirror interaction to finish"
					end
					local sent = call("Turn mirror", function()
						puzzle:turn(index)
					end, 8, generation)
					if not sent or not pause(0.35, generation) then
						return false, "The mirror didn't respond"
					end
					expected[index] += 1
					for _, linked in ipairs(puzzle.layout.Mirrors[index].Links or {}) do
						expected[linked] += 1
					end
					local reply = Mirrors.state(puzzle, generation)
					local acknowledgeBy = os.clock() + 3
					while reply and os.clock() < acknowledgeBy do
						local matches = true
						for i, value in ipairs(expected) do
							if reply.Turns[i] % 8 ~= value % 8 then
								matches = false
								break
							end
						end
						if matches or reply.Solved == true then
							break
						end
						if not alive() or not pause(0.2, generation) then
							return false, "Stopped or the floor changed"
						end
						reply = Mirrors.state(puzzle, generation)
					end
					if not reply then
						return false, "Waiting for the mirror to finish turning"
					end
					if reply.Solved == true then
						break
					end
					for i, value in ipairs(expected) do
						if reply.Turns[i] % 8 ~= value % 8 then
							changed = true
							break
						end
					end
					done += 1
					if changed then
						break
					end
				end
			end
			if not changed then
				local layout = puzzle.layout
				local moved, reason = approach(layout.Origin - layout.Direction * 5, generation, nil, false, alive)
				if not moved then
					return false, reason
				end
				status("Charging the skull", "Waiting for the game to award the relic", 0.83)
				if
					waitUntil(function()
						return App.player:GetAttribute("HasRelic") == true
					end, 15, generation)
				then
					return true
				end
			end
			if attempt == Mirrors.maxAttempts then
				return false, "The mirrors haven't awarded the relic. Try again once the room settles."
			end
		end
		return waitUntil(function()
			return App.player:GetAttribute("HasRelic") == true
		end, 15, generation) ~= nil,
			"Waiting for the mirror relic"
	end

	Bridge.solveMirrors = Mirrors.solve
	Bridge.mirrorsCompleted = Mirrors.completed
end

do
	-- floor 6
	local Brew = {}
	Brew.colors = { Red = true, Orange = true, Yellow = true, Green = true, Cyan = true, Pink = true, White = true }
	function Brew.completed()
		for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
			if tonumber(number) == 6 then
				return true
			end
		end
		return false
	end
	function Brew.read(generation)
		local ok, data = invoke(getPath(Storage, "Remotes", "WitchesBrewRecipe"), generation)
		if
			not ok
			or type(data) ~= "table"
			or type(data.Recipe) ~= "table"
			or #data.Recipe < 1
			or #data.Recipe > 64
			or type(data.Pads) ~= "table"
			or type(data.Step) ~= "number"
			or data.Step % 1 ~= 0
			or data.Step < 0
			or data.Step > #data.Recipe
		then
			return nil
		end
		for _, color in ipairs(data.Recipe) do
			if not Brew.colors[color] then
				return nil
			end
		end
		return data
	end
	function Brew.pad(data, color)
		local model, root = character()
		if not model then
			return nil
		end
		local best, bestDistance, bestKey
		for _, part in ipairs(Collection:GetTagged("%CauldronSpawn")) do
			if part:IsA("BasePart") and part:IsDescendantOf(workspace) then
				local point = part.Position
				local key = string.format("%.0f,%.0f,%.0f", point.X, point.Y, point.Z)
				local distance = (point - root.Position).Magnitude
				if data.Pads[key] == color and (not bestDistance or distance < bestDistance) then
					best, bestDistance, bestKey = part, distance, key
				end
			end
		end
		return best, bestKey
	end
	function Brew.stream(data, color, generation)
		if type(App.player.RequestStreamAroundAsync) ~= "function" then
			return
		end
		local _, root = character()
		if not root then
			return
		end
		local best, distance
		for key, assigned in pairs(data.Pads) do
			if assigned == color and type(key) == "string" and #key < 96 then
				local x, y, z = key:match("^(-?%d+),(-?%d+),(-?%d+)$")
				x, y, z = tonumber(x), tonumber(y), tonumber(z)
				if x and y and z and math.abs(x) < 1000000 and math.abs(y) < 1000000 and math.abs(z) < 1000000 then
					local point = Vector3.new(x, y, z)
					local gap = (point - root.Position).Magnitude
					if not distance or gap < distance then
						best, distance = point, gap
					end
				end
			end
		end
		if best then
			call("Brew ingredient streaming", function()
				App.player:RequestStreamAroundAsync(best, 2)
			end, 3, generation)
		end
	end
	function Brew.solve(objects, clientState, generation)
		status("Loading floor 6", "Finding the cauldron and its recipe", 0.12)
		hollowModule("WitchesBrewPuzzle", generation)
		local part = waitUntil(function()
			return nearest("%WitchCauldron")
		end, 45, generation)
		if not part then
			return false, "The cauldron hasn't loaded yet"
		end
		local ok, cauldron = call("Witch cauldron", function()
			return objects.getObjectAsync("WitchCauldron", part)
		end, 12, generation)
		if not ok or type(cauldron) ~= "table" or typeof(cauldron.center) ~= "Vector3" then
			return false, "The cauldron isn't ready yet"
		end
		local model = character()
		local function alive()
			local live = character()
			local floor = App.player:GetAttribute("InMaze")
			return active(generation)
				and live == model
				and floor ~= nil
				and floor ~= false
				and (type(floor) ~= "number" or floor == 6)
				and part:IsDescendantOf(workspace)
		end
		local failures, deadline, missingAt, streamAt = 0, os.clock() + 600, nil, 0
		while alive() and os.clock() < deadline do
			if App.player:GetAttribute("HasRelic") == true then
				return true
			end
			local _, root = character()
			if
				root.Anchored
				or clientState.isLocked("CharacterBusyState")
				or clientState.getState("ElevatorTeleporting")
			then
				if not pause(0.2, generation) then
					break
				end
				continue
			end
			local data = Brew.read(generation)
			if not alive() then
				break
			end
			if data and data.Solved == true then
				return true
			end
			if not data then
				failures += 1
				status("Loading the brew recipe", "Waiting for the current recipe and ingredient pads", 0.15)
			elseif data.Step == #data.Recipe then
				status("Finishing the brew", "Waiting for the game to grant the relic", 0.85)
			else
				if type(cauldron.setRecipe) == "function" then
					pcall(cauldron.setRecipe, cauldron, data.Recipe, data.Step, data.Solved == true)
				end
				local color = data.Recipe[data.Step + 1]
				local pad, key = Brew.pad(data, color)
				status(
					"Brewing the potion",
					string.format("Ingredient %d / %d: %s", data.Step + 1, #data.Recipe, color),
					0.18 + data.Step / #data.Recipe * 0.65
				)
				if not pad then
					missingAt = missingAt or os.clock()
					status("Finding " .. color, "Waiting for the ingredient to load", App.progress)
					if os.clock() >= streamAt then
						Brew.stream(data, color, generation)
						streamAt = os.clock() + 2
					end
					if os.clock() - missingAt > 45 then
						return false,
							"The "
								.. color
								.. " ingredient pad hasn't loaded. Move closer to the puzzle and try Start again."
					end
				else
					missingAt = nil
					local moved, why = approach(pad.Position, generation, pad, false, alive)
					if not moved then
						return false, why
					end
					if not alive() then
						break
					end
					local grabbed, accepted = invoke(getPath(Storage, "Remotes", "WitchesBrewGrab"), generation, key)
					if not alive() then
						break
					end
					if grabbed and accepted == true then
						local _, nowRoot = character()
						local delta = nowRoot.Position - cauldron.center
						local flat = Vector3.new(delta.X, 0, delta.Z)
						local offset = flat.Magnitude > 0.1 and flat.Unit * 4.5 or Vector3.new(0, 0, 4.5)
						moved, why = approach(cauldron.center + offset, generation, part, false, alive)
						if not moved then
							return false, why
						end
						if not alive() then
							break
						end
						local dropped, reply = invoke(getPath(Storage, "Remotes", "WitchesBrewDrop"), generation)
						if not alive() then
							break
						end
						if
							dropped
							and type(reply) == "table"
							and reply.Correct == true
							and type(reply.Step) == "number"
							and reply.Step > data.Step
						then
							failures = 0
							if type(cauldron.setRecipe) == "function" then
								pcall(cauldron.setRecipe, cauldron, data.Recipe, reply.Step, reply.Solved == true)
							end
							if reply.Solved == true then
								return true
							end
						else
							failures += 1
						end
					else
						failures += 1
					end
				end
			end
			if failures >= 10 then
				return false, "The brew hasn't advanced. Check the loaded pads and try Start again."
			end
			if not pause(0.5, generation) then
				break
			end
		end
		return false, active(generation) and "The floor changed or the brew took too long" or "Stopped"
	end
	Bridge.solveBrew, Bridge.brewCompleted = Brew.solve, Brew.completed
end

local function runHollow(generation)
	local floor = App.floor
	local maze = App.player:GetAttribute("InMaze")
	if type(maze) == "number" then
		floor = maze
		App.floor = floor
	end
	if type(floor) ~= "number" or floor % 1 ~= 0 or floor < 1 or floor > 9 then
		return false, "Choose a floor from 1 to 9"
	end
	local loaded = waitUntil(function()
		return App.player:FindFirstChild("Loaded")
	end, 15, generation)
	if not loaded then
		return false, "Your Hollow progress is still loading"
	end
	local completed = floor == 4 and Bridge.completed()
		or floor == 5 and Bridge.mirrorsCompleted()
		or floor == 6 and Bridge.brewCompleted()
		or floor == 7 and Bridge.lanternsCompleted()
		or floor == 8 and Bridge.offeringsCompleted()
		or floor == 9 and Bridge.leversCompleted()
	if completed and not App.player:GetAttribute("InMaze") and App.player:GetAttribute("HasRelic") ~= true then
		return true, "Floor " .. floor .. " has already been completed"
	end
	local clientState, reason = hollowModule("ClientState", generation)
	if not clientState then
		return false, reason
	end
	local objects, objectError = hollowModule("OOPTags", generation)
	if not objects then
		return false, objectError
	end
	local schedule = hollowModule("EventSchedule", generation)
	if not schedule or not schedule.checkPassed("Chapter" .. tostring(floor)) then
		return false, "This floor is not open yet"
	end
	local pillarSession
	if floor == 2 and App.player:GetAttribute("HasRelic") ~= true then
		local why
		pillarSession, why = Pillars.watch(generation)
		if not pillarSession then
			return false, why
		end
		local puzzle, loadError = hollowModule("ThreePillarPuzzle", generation)
		if not puzzle then
			return false, loadError
		end
	end
	if not App.player:GetAttribute("InMaze") then
		local entrance = nearest("%MazeElevatorEntrance")
		if not entrance then
			return false, "Waiting for the elevator to load"
		end
		status("Entering floor " .. floor, "", 0.05)
		local entered, why = rideElevator(entrance, clientState, objects, generation, floor)
		if not entered then
			return false, why
		end
	end
	if not pause(2, generation) then
		return false, "Stopped"
	end
	if floor == 9 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solveLevers(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 8 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solveOfferings(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 7 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solveLanterns(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 6 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solveBrew(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 5 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solveMirrors(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 4 then
		if not completed and App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Bridge.solve(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 3 then
		if App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Tomb.solve(objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	elseif floor == 2 then
		if App.player:GetAttribute("HasRelic") ~= true then
			local solved, solveError = Pillars.solve(pillarSession, objects, clientState, generation)
			if not solved then
				return false, solveError
			end
		end
	else
		local puzzle, why = hollowModule("MazeLockPuzzle", generation)
		if not puzzle then
			return false, why
		end
		puzzle.load()
		local board = waitUntil(function()
			return puzzle.getBoard()
		end, 15, generation)
		if not board then
			return false, "No pipe puzzle is available on this floor"
		end
		log(
			string.format(
				"Pipe board: %dx%d, start row %s, exit row %s",
				board.Size,
				board.Size,
				tostring(board.SourceRow),
				tostring(board.SinkRow)
			)
		)
		local rules = hollowModule("MazePath", generation)
		if not rules then
			return false, "Couldn't load the pipe puzzle"
		end
		local door = waitUntil(function()
			return nearest("%MazeDoor")
		end, 12, generation)
		if not door then
			return false, "Waiting for the puzzle door to load"
		end
		local ok, doorObject = call("Maze door", function()
			return objects.getObjectAsync("MazeDoor", door)
		end, 8, generation)
		if not ok or not doorObject or not doorObject.board then
			return false, "The puzzle door isn't ready yet"
		end
		if not puzzle.isSolved() then
			local attempts, collected = 0, {}
			while active(generation) do
				local placed, total = 0, #board.Cells
				for index in ipairs(board.Cells) do
					if puzzle.isPlaced(index) then
						placed += 1
					end
				end
				if placed == total then
					break
				end
				status(
					"Gathering puzzle pieces",
					string.format("%d / %d tiles placed", placed, total),
					0.1 + 0.45 * placed / total
				)
				local tile = nearest("%MazeTile", function(part)
					return not collected[part] and part:GetAttribute(tostring(App.player.UserId)) ~= nil
				end)
				if tile then
					local ready, tileObject = call("Maze tile", function()
						return objects.getObjectAsync("MazeTile", tile)
					end, 8, generation)
					if ready and tileObject and tileObject.model then
						local moved, moveError = approach(tile.Position, generation)
						if not moved then
							return false, moveError
						end
						local taken = waitUntil(function()
							return not tileObject.model
						end, 3, generation)
						if taken then
							collected[tile] = true
						end
					elseif ready and tileObject and not tileObject.model then
						collected[tile] = true
					end
				end
				local moved, moveError = approach(doorObject.board.Position, generation)
				if not moved then
					return false, moveError
				end
				if not pause(2, generation) then
					return false, "Stopped"
				end
				attempts += 1
				if attempts > total * 3 then
					return false, "Some tiles are missing. Waiting for them to load."
				end
			end
			if not active(generation) then
				return false, "Stopped"
			end
			status("Solving pipe puzzle", "", 0.65)
			local deadline, slice = os.clock() + 8, os.clock()
			local turns, solveError = Logic.solve(board, rules, function()
				if os.clock() - slice > 0.003 then
					task.wait()
					slice = os.clock()
				end
				return active(generation) and os.clock() < deadline
			end, table.clone(puzzle.getTurns()))
			if not turns then
				if solveError == "Search stopped" and active(generation) then
					return false, "Couldn't solve this board. Try again."
				end
				return false, solveError
			end
			if puzzle.getBoard() ~= board then
				return false, "The board changed. Press Start to try this floor again."
			end
			local moved, moveError = approach(doorObject.board.Position, generation)
			if not moved then
				return false, moveError
			end
			log("Turning the tiles to connect the pipes")
			local accepted, applyError = applyPipeTurns(puzzle, turns, generation)
			if not accepted then
				return false, applyError
			end
		end
	end
	local relic = waitUntil(function()
		return completed or App.player:GetAttribute("HasRelic") == true
	end, 12, generation)
	if not relic then
		return false, "The puzzle opened, but the relic hasn't arrived yet"
	end
	status("Relic ready", "Heading back in 10 seconds", 0.88)
	if not pause(10, generation) then
		return false, "Stopped"
	end
	status("Returning the relic", "", 0.9)
	local exit = waitUntil(function()
		return nearest("%MazeElevatorExit")
	end, 15, generation)
	if not exit then
		return false, "Waiting for the exit elevator to load"
	end
	local returned, returnError = rideElevator(exit, clientState, objects, generation)
	if not returned then
		return false, returnError
	end
	if
		(floor >= 4 and floor <= 9)
		and not waitUntil(function()
			return (
				floor == 4 and Bridge.completed()
				or floor == 5 and Bridge.mirrorsCompleted()
				or floor == 6 and Bridge.brewCompleted()
				or floor == 7 and Bridge.lanternsCompleted()
				or floor == 8 and Bridge.offeringsCompleted()
				or floor == 9 and Bridge.leversCompleted()
			)
				and not App.player:GetAttribute("InMaze")
				and App.player:GetAttribute("HasRelic") ~= true
		end, 15, generation)
	then
		return false, "Waiting for floor " .. floor .. "'s delivered relic to be saved"
	end
	App.rows.hollow = "Relic returned"
	return true, "Relic delivered. Check your reward in the game."
end

local function runKeyboard(generation)
	status("Loading Keyboard Escape", "Waiting for world data", 0)
	local loadingTime = resumePlace and 90 or 30
	local config, reason = waitUntil(function()
		local data = module(Storage:FindFirstChild("Config"), generation)
		return data and type(data.WORLD) == "number" and data
	end, loadingTime, generation)
	if not config then
		return false, active(generation) and (reason or "World data hasn't loaded yet") or "Stopped"
	end
	if config.WORLD ~= 5 then
		local continued = prepareTravel(128614435234859, true)
		local sent, why = fire(getPath(Storage, "Remotes", "RequestWorldTeleport"), 5)
		return false,
			sent
					and (continued and "Heading to Hallo'World. I'll carry on when we arrive." or "Heading to Hallo'World. Run the script again when you arrive.")
				or why
	end
	local feature, why = waitUntil(function()
		local data = module(getPath(Storage, "_FRAMEWORK", "Features", "eventQuests"), generation)
		return data
			and data.remotes
			and data.remotes.requestState
			and data.remotes.claimQuest
			and type(data.getQuests) == "function"
			and data
	end, loadingTime, generation)
	if not feature then
		return false, active(generation) and (why or "The event quest hasn't loaded yet") or "Stopped"
	end
	local nextRefresh = 0
	local function refreshState()
		if active(generation) and os.clock() >= nextRefresh then
			nextRefresh = os.clock() + 0.55
			local ok, err = pcall(feature.remotes.requestState.fire, feature.remotes.requestState)
			if not ok then
				log("Quest refresh: " .. tostring(err))
			end
		end
	end
	local function quest()
		local ok, quests = pcall(feature.getQuests)
		return ok and Logic.quest(quests, "halloween_stage_11") or nil
	end
	local function stageZone(stage)
		for _, zone in ipairs(Collection:GetTagged("Zone")) do
			if
				zone:IsA("BasePart")
				and zone:IsDescendantOf(workspace)
				and zone:GetAttribute("ZoneId") == "SAS"
				and zone:GetAttribute("SAS") == stage
			then
				return zone
			end
		end
	end
	local function confirmed(stage)
		local state = quest()
		return state and type(state.progress) == "number" and state.progress >= stage
	end
	status("Loading event progress", "Loading your quest progress", 0)
	local ready = waitUntil(function()
		refreshState()
		return quest()
	end, loadingTime, generation)
	if not ready then
		return false,
			active(generation) and "The quest didn't load. Check that you're in the event and try again." or "Stopped"
	end
	for stage = 1, 11 do
		if not active(generation) then
			return false, "Stopped"
		end
		if verify(current) then
			return true, "Hollow badge earned"
		end
		if confirmed(11) then
			break
		end
		if confirmed(stage) then
			continue
		end
		local accepted, lastError = false, nil
		for attempt = 1, 3 do
			if not active(generation) then
				return false, "Stopped"
			end
			status(
				"Waiting for stage " .. stage,
				string.format("Looking for the stage  |  Try %d / 3", attempt),
				(stage - 1) / 12
			)
			local zone = waitUntil(function()
				refreshState()
				return confirmed(stage) and true or stageZone(stage)
			end, 20, generation)
			if not active(generation) then
				return false, "Stopped"
			end
			if zone == true then
				accepted = true
				break
			end
			if zone and zone:IsDescendantOf(workspace) then
				status("Hallo'World", string.format("Stage %d / 11  |  Try %d / 3", stage, attempt), stage / 12)
				local moved, moveError = approach(
					zone.Position,
					generation,
					nil,
					nil,
					nil,
					attempt == 1 and { streamSeconds = 0.12, streamWait = 0.3, settleSeconds = 0.06 } or nil
				)
				lastError = moveError
				if moved then
					accepted = waitUntil(function()
						refreshState()
						return confirmed(stage)
					end, 6, generation) ~= nil
					lastError = "The game didn't count stage " .. stage
				end
			else
				lastError = "Stage " .. stage .. " hasn't loaded yet"
			end
			if accepted then
				break
			end
			log((lastError or "Stage not found") .. string.format(" (attempt %d / 3)", attempt))
			if not pause(0.12, generation) then
				return false, "Stopped"
			end
		end
		if not accepted then
			return false, lastError or "Stage " .. stage .. " still hasn't counted after three tries"
		end
	end
	local final = waitUntil(function()
		refreshState()
		local state = quest()
		return state and (state.done or state.claimed) and state
	end, 10, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	if not final then
		return false, "Last stage reached. Waiting for the quest to finish."
	end
	if final and final.done and not final.claimed then
		feature.remotes.claimQuest:fire("halloween_stage_11")
		if not pause(2, generation) then
			return false, "Stopped"
		end
	end
	return verify(current, true) == true, "Last stage reached. Check your badge in the game."
end

local function stepEggTeleport(route, track, state, mountRules, session, generation)
	if not active(generation) then
		return nil, "Stopped"
	end
	local player = App.player
	local raceId, heat = player:GetAttribute("RaceId"), player:GetAttribute("RaceHeat")
	local goAt = state:GetAttribute("RaceGoAt")
	if
		raceId ~= track.Name
		or not track:IsDescendantOf(workspace)
		or state:GetAttribute("RacePhase") ~= "Racing"
		or (type(goAt) == "number" and workspace:GetServerTimeNow() < goAt)
		or player:GetAttribute("RaceCutscenePlaying")
		or player:GetAttribute("RaceFinishPlace") ~= nil
	then
		return nil, nil, "Waiting for an active race"
	end
	local model, root = character()
	local mount = model and model:FindFirstChild(mountRules.MountName or "RaceMount")
	local mountRoot = mount and mount:FindFirstChild("HumanoidRootPart")
	if not root or not mountRoot or not mount:FindFirstChild("Hitbox") or not mountRoot:FindFirstChild("Seat") then
		return nil, nil, "Waiting for the race mount"
	end
	local length = route.Length
	if type(length) ~= "number" or length ~= length or length <= 0 or length >= 1e7 then
		return nil, "Couldn't read this track"
	end
	local lap = player:GetAttribute("RaceLap")
	lap = type(lap) == "number" and math.max(1, math.floor(lap)) or 1
	local checkpointMode = App.eggCheckpointMode == true
	if
		not session
		or session.route ~= route
		or session.root ~= root
		or session.heat ~= heat
		or session.goAt ~= goAt
		or session.checkpointMode ~= checkpointMode
		or lap < session.lap
	then
		local ok, projected = pcall(route.Project, route, root.Position, 0, length, length)
		if not ok or type(projected) ~= "number" or projected ~= projected or math.abs(projected) >= 1e7 then
			return nil, "Couldn't find your rider on the track"
		end
		local cursor = projected % length
		if lap == 1 and cursor > length - math.min(80, length * 0.1) then
			cursor -= length
		end
		local finishOffset, finish = 0, nil
		if checkpointMode then
			finish = track:FindFirstChild("FinishLine")
			if not finish or not finish:IsA("BasePart") then
				return nil, nil, "Waiting for the finish line"
			end
			local found, offset = pcall(route.Project, route, finish.Position, 0, length, length)
			if not found or type(offset) ~= "number" or offset ~= offset or math.abs(offset) >= 1e7 then
				return nil, "Couldn't locate the finish line on the track"
			end
			finishOffset = offset % length
			if finishOffset > length / 2 then
				finishOffset -= length
			end
		end
		session = {
			route = route,
			root = root,
			heat = heat,
			goAt = goAt,
			lap = lap,
			cursor = cursor,
			boundary = length + finishOffset + 12,
			attempt = 1,
			step = 64,
			interval = checkpointMode and 0.05 or 0.06,
			checkpointMode = checkpointMode,
			finish = finish,
			hopStage = 0,
		}
	elseif lap > session.lap then
		session.boundary += (lap - session.lap) * length
		session.lap, session.attempt, session.step = lap, 1, 64
		session.interval = checkpointMode and 0.05 or 0.06
		session.hopStage = 0
		session.awaiting, session.awaitingCursor = nil, nil
	end
	local laps = state:GetAttribute("RaceLaps")
	laps = type(laps) == "number" and laps > 0 and laps or 3
	if checkpointMode and lap > laps then
		session.finishPendingSince = session.finishPendingSince or os.clock()
		if os.clock() - session.finishPendingSince > 8 then
			return nil, "The laps counted, but the game hasn't confirmed the finish."
		end
		return session, nil, "Waiting for the finish to count"
	end
	if checkpointMode and session.hopStage >= 2 then
		session.awaiting = session.awaiting or os.clock()
		if os.clock() - session.awaiting < 1.5 then
			return session, nil, lap >= laps and "Waiting for the finish to count" or "Waiting for the lap to count"
		end
		if session.attempt >= 3 then
			return nil, "The game isn't counting direct lap hops. Turn them off to use the normal route."
		end
		session.attempt += 1
		session.hopStage, session.awaiting = 0, nil
		log(string.format("Lap %d didn't count. Retrying the finish (%d / 3).", lap, session.attempt))
	end
	if not checkpointMode and (lap > laps or session.cursor >= session.boundary - 0.001) then
		if not session.awaiting then
			session.awaiting, session.awaitingCursor = os.clock(), session.cursor
		end
		if os.clock() - session.awaiting >= 8 and session.cursor - session.awaitingCursor >= length then
			if lap > laps or session.attempt >= 3 then
				return nil, "The lap didn't count. Stop and try another race."
			end
			session.attempt += 1
			session.step = math.max(16, session.step / 2)
			session.interval = 0.06 + 0.02 * (session.attempt - 1)
			session.boundary = session.cursor + length
			session.awaiting, session.awaitingCursor = nil, nil
			log(string.format("Lap %d didn't count. Slowing down (%d / 3).", lap, session.attempt))
		end
	end
	local nextDistance
	if checkpointMode then
		if track:FindFirstChild("FinishLine") ~= session.finish then
			return nil, nil, "The finish line changed. Checking the new race."
		end
		nextDistance = session.hopStage == 0 and session.boundary - 18 or session.boundary
	else
		local cycle = math.floor(session.cursor / length) * length
		nextDistance = math.min(session.cursor + session.step, cycle + length)
		for _, offset in ipairs(route.Starts or {}) do
			local corner = cycle + offset
			if corner > session.cursor + 0.001 then
				nextDistance = math.min(nextDistance, corner)
				break
			end
		end
	end
	local ok, target = pcall(function()
		return mountRules.RiderFrame(mount, route:FrameAt(nextDistance))
	end)
	if not ok or typeof(target) ~= "CFrame" then
		return nil, "Could not place the race mount on its path"
	end
	local position = target.Position
	if
		position.X ~= position.X
		or position.Y ~= position.Y
		or position.Z ~= position.Z
		or math.max(math.abs(position.X), math.abs(position.Y), math.abs(position.Z)) >= 1e7
		or position.Y <= workspace.FallenPartsDestroyHeight + 32
	then
		return nil, "Couldn't find a safe spot on the track"
	end
	local _, latestRoot = character()
	if not active(generation) then
		return nil, "Stopped"
	end
	if
		latestRoot ~= root
		or player:GetAttribute("RaceId") ~= raceId
		or player:GetAttribute("RaceHeat") ~= heat
		or player:GetAttribute("RaceCutscenePlaying")
		or player:GetAttribute("RaceFinishPlace") ~= nil
		or state:GetAttribute("RacePhase") ~= "Racing"
		or state:GetAttribute("RaceGoAt") ~= goAt
		or (App.eggCheckpointMode == true) ~= checkpointMode
		or (checkpointMode and track:FindFirstChild("FinishLine") ~= session.finish)
		or not track:IsDescendantOf(workspace)
	then
		return nil, nil, "The race changed. Checking the new race."
	end
	root.AssemblyLinearVelocity = Vector3.zero
	root.AssemblyAngularVelocity = Vector3.zero
	root.CFrame = target
	session.cursor = nextDistance
	if checkpointMode then
		session.hopStage += 1
		if session.hopStage == 2 then
			session.awaiting = os.clock()
		end
	end
	return session
end

local function runEgg(generation)
	status("Loading race helper", "Loading the track and controls", 0)
	local controlsModule = waitUntil(function()
		return getPath(App.player, "PlayerScripts", "PlayerModule")
	end, 20, generation)
	local playerModule, reason = module(controlsModule, generation)
	local pathObject = waitUntil(function()
		return getPath(Storage, "Shared", "Modules", "RaceTrackPath")
	end, 20, generation)
	local pathModule = module(pathObject, generation)
	local mountObject = waitUntil(function()
		return getPath(Storage, "Data", "MountRace")
	end, 20, generation)
	local mountRules = module(mountObject, generation)
	local save = module(getPath(Storage, "Shared", "Save"), generation)
	if
		not playerModule
		or not pathModule
		or type(pathModule.new) ~= "function"
		or not mountRules
		or type(mountRules.RiderFrame) ~= "function"
	then
		return false, reason or "The race is still loading"
	end
	local controls = waitUntil(function()
		return playerModule:GetControls()
	end, 20, generation)
	if not controls or type(controls.GetMoveVector) ~= "function" then
		return false, "The race controls haven't loaded yet"
	end
	local networking = waitUntil(function()
		return getPath(Storage, "Packages", "Networking", "RF/TheHollow/AskEnter")
	end, 20, generation)
	if not networking then
		return false, "Couldn't load race entry"
	end
	local command = nil
	local original = controls.GetMoveVector
	local wrapper
	wrapper = function(self, ...)
		if active(generation) and App.player:GetAttribute("RaceId") and command then
			return command
		end
		return original(self, ...)
	end
	controls.GetMoveVector = wrapper
	table.insert(App.cleanups, function()
		command = nil
		if controls.GetMoveVector == wrapper then
			controls.GetMoveVector = original
		end
	end)
	local function wins()
		local data = save and type(save.Peek) == "function" and save.Peek()
		local value = data and data.TheHollow and data.TheHollow.Wins
		return type(value) == "number" and value or nil
	end
	local track, path, teleport, joinWindow, joinAttempts = nil, nil, nil, nil, 0
	local trackedRace, missingSince, nextPathCheck, pathError = nil, nil, 0, nil
	local mountMissingSince = nil
	local lastJoin, lastBadge, deadline = -math.huge, -math.huge, os.clock() + 1200
	local badgeProbe = false
	while active(generation) and os.clock() < deadline do
		local total = wins()
		if total and total >= 3 then
			local verified = verify(current, true)
			return verified == true,
				verified and "Three wins! Hollow badge earned." or "Three wins! Waiting for the badge."
		end
		if os.clock() - lastBadge > 10 and not badgeProbe then
			lastBadge = os.clock()
			badgeProbe = true
			task.spawn(function()
				local ok, why = pcall(verify, current, true)
				badgeProbe = false
				if not ok then
					log(why)
				end
			end)
		end
		local badge = App.badgeState[current.badges[1]]
		if badge and badge.owned then
			return true, "Hollow badge earned"
		end
		local raceId = App.player:GetAttribute("RaceId")
		if raceId then
			if trackedRace ~= raceId or (track and not track:IsDescendantOf(workspace)) then
				trackedRace, track, path, teleport = raceId, nil, nil, nil
				missingSince, nextPathCheck, pathError = nil, 0, nil
				mountMissingSince = nil
			end
			track = track or findRaceTrack(raceId)
			local waiting = not track and "Waiting for active track " .. tostring(raceId) or nil
			if track and os.clock() >= nextPathCheck then
				nextPathCheck = os.clock() + 0.5
				local attachments = track:FindFirstChild("AttachmentTrack")
				local count = attachments and #attachments:GetChildren() or 0
				if not path or path.attachments ~= attachments or path.count ~= count then
					path, teleport = nil, nil
					if attachments and count >= 3 then
						local ok, route = pcall(pathModule.new, attachments)
						if
							ok
							and type(route) == "table"
							and type(route.Project) == "function"
							and type(route.FrameAt) == "function"
							and type(route.Length) == "number"
							and route.Length > 0
						then
							path = { track = track, attachments = attachments, count = count, value = route }
							pathError = nil
						else
							local why = ok and "Track path is not ready" or tostring(route)
							if why ~= pathError then
								log("Race path: " .. why:sub(1, 180))
							end
							pathError = why
							nextPathCheck = os.clock() + 1
						end
					end
				end
			end
			local heat = App.player:GetAttribute("RaceHeat")
			local state = track
				and (type(heat) == "string" and getPath(track, "RaceHeats", heat) or (heat == nil and track or nil))
			local phase = state and state:GetAttribute("RacePhase")
			local goAt = state and state:GetAttribute("RaceGoAt")
			if not waiting and not path then
				waiting = "Waiting for the track to finish loading"
			elseif not waiting and not phase then
				waiting = "Waiting for the race to load"
			end
			if waiting then
				command = nil
				missingSince = missingSince or os.clock()
				status("Waiting for race data", waiting .. "  |  Checking again", total and total / 3 or 0)
				if os.clock() - missingSince > 30 then
					return false,
						waiting
							.. " did not arrive after 30 seconds"
							.. (pathError and (": " .. pathError:sub(1, 160)) or "")
				end
				if not pause(0.5, generation) then
					return false, "Stopped"
				end
				continue
			end
			missingSince = nil
			local _, root = character()
			local teleportDetail
			if
				root
				and phase == "Racing"
				and (type(goAt) ~= "number" or workspace:GetServerTimeNow() >= goAt)
				and not App.player:GetAttribute("RaceCutscenePlaying")
				and App.player:GetAttribute("RaceFinishPlace") == nil
			then
				local teleportError
				teleport, teleportError, teleportDetail =
					stepEggTeleport(path.value, track, state, mountRules, teleport, generation)
				if teleportError then
					return false, teleportError
				end
				command = teleport and Vector3.zero or nil
				if teleport then
					mountMissingSince = nil
				else
					mountMissingSince = mountMissingSince or os.clock()
					if os.clock() - mountMissingSince > 30 then
						return false, teleportDetail or "Your rider didn't load. Try again."
					end
				end
			else
				command = nil
				teleport, mountMissingSince = nil, nil
			end
			status(
				teleport and teleport.checkpointMode and "Hollow races | Direct lap hops" or "Hollow races",
				teleportDetail
					or string.format(
						"%s wins / 3  |  Lap %s",
						total and tostring(total) or "?",
						tostring(App.player:GetAttribute("RaceLap") or "-")
					),
				total and total / 3 or 0
			)
		else
			command, track, path, teleport = nil, nil, nil, nil
			trackedRace, missingSince, nextPathCheck = nil, nil, 0
			mountMissingSince = nil
			local closes = workspace:GetAttribute("TheHollowJoinEndsAt")
			if closes ~= joinWindow then
				joinWindow, joinAttempts = closes, 0
			end
			status(
				"Waiting for a race",
				total and (total .. " / 3 wins") or "Loading your progress",
				total and total / 3 or 0
			)
			if
				type(closes) == "number"
				and closes > workspace:GetServerTimeNow()
				and os.clock() - lastJoin > 4
				and joinAttempts < 3
			then
				lastJoin, joinAttempts = os.clock(), joinAttempts + 1
				local ok, accepted, why = invoke(networking, generation)
				if not ok then
					log("Race entry: " .. tostring(accepted))
				elseif accepted == false and why then
					log("Race entry: " .. tostring(why))
				end
			end
		end
		if not pause(teleport and teleport.interval or 0.1, generation) then
			return false, "Stopped"
		end
	end
	return false, "Race stopped. The badge hasn't been awarded yet."
end

local function findRoyaleSensor()
	for _, object in ipairs(workspace:GetChildren()) do
		if object.Name ~= "BadgeAwarder" then
			continue
		end
		local sensor = object:FindFirstChild("InsideBrickSensor")
		local controller = sensor and sensor:FindFirstChild("BadgeAwarderScriptv2")
		local awarded = controller and controller:FindFirstChild("AwardedBadge")
		if
			sensor
			and sensor:IsA("BasePart")
			and sensor:IsDescendantOf(workspace)
			and awarded
			and awarded:IsA("RemoteEvent")
		then
			return sensor
		end
	end
	return nil
end

local function enterRoyaleSensor(sensor, generation, attempt)
	if not active(generation) then
		return false, "Stopped"
	end
	if not sensor:IsDescendantOf(workspace) then
		return false, "The badge pickup disappeared. Waiting for it to load again."
	end
	local offset = sensor.CFrame.RightVector * (sensor.Size.X / 2 + 3)
	local entry = sensor.Position + offset * (attempt == 2 and -1 or 1)
	if attempt == 3 then
		entry = sensor.Position
	end
	local moved, why = approach(entry, generation, sensor)
	if not moved then
		return false, why
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local model, root, humanoid = character()
	if not model or not sensor:IsDescendantOf(workspace) then
		return false, "Your character or the badge pickup changed"
	end
	local walking = true
	local function cancelWalk()
		if not walking then
			return
		end
		walking = false
		local currentModel, currentRoot = character()
		if currentModel == model and currentRoot == root then
			pcall(humanoid.MoveTo, humanoid, root.Position)
		end
	end
	table.insert(App.cleanups, cancelWalk)
	local ok, err = pcall(humanoid.MoveTo, humanoid, sensor.Position)
	if not ok then
		cancelWalk()
		return false, "Could not enter the badge pickup: " .. tostring(err)
	end
	local entered = waitUntil(function()
		local currentModel, currentRoot = character()
		if currentModel ~= model or currentRoot ~= root or not sensor:IsDescendantOf(workspace) then
			return nil
		end
		local point = sensor.CFrame:PointToObjectSpace(root.Position)
		return math.abs(point.X) <= sensor.Size.X / 2
			and math.abs(point.Y) <= sensor.Size.Y / 2
			and math.abs(point.Z) <= sensor.Size.Z / 2
	end, 4, generation)
	cancelWalk()
	if not active(generation) then
		return false, "Stopped"
	end
	if not sensor:IsDescendantOf(workspace) then
		return false, "The badge pickup disappeared. Waiting for it to load again."
	end
	if not entered then
		return false, "Could not walk into the badge pickup"
	end
	if not pause(0.5, generation) then
		return false, "Stopped"
	end
	return true
end

local function runRoyale(generation)
	if verify(current, true) == true then
		return true, "Royalloween badge earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if game.PlaceId ~= current.eventPlace then
		status("Entering Wickery Cliffs", "Waiting to enter Wickery Cliffs", 0.1)
		local remote = waitUntil(function()
			return Storage:FindFirstChild("QuickTeleportByName")
		end, 15, generation)
		if not active(generation) then
			return false, "Stopped"
		end
		local continued = prepareTravel(current.eventPlace, true)
		App.traveling = true
		local sent, err
		if remote and remote:IsA("RemoteEvent") then
			sent, err = fire(remote, current.realm)
		else
			sent, err = pcall(Teleport.Teleport, Teleport, current.eventPlace, App.player)
		end
		if not sent then
			App.traveling = false
			return false, "Royale High transfer failed: " .. tostring(err)
		end
		return nil,
			continued and "Heading to Wickery Cliffs. I'll carry on when we arrive."
				or "Heading to Wickery Cliffs. Run the script again when you arrive."
	end
	local lastError = "The Royalloween badge hasn't arrived yet"
	for attempt = 1, 3 do
		if not active(generation) then
			return false, "Stopped"
		end
		if verify(current, true) == true then
			return true, "Royalloween badge earned"
		end
		status("Finding the event badge", string.format("Wickery Cliffs  |  Attempt %d / 3", attempt), 0.25)
		local area = current.badgeArea
		call("Royale badge streaming", function()
			App.player:RequestStreamAroundAsync(Vector3.new(area[1], area[2], area[3]), 3)
		end, 4, generation)
		local sensor = waitUntil(findRoyaleSensor, 15, generation)
		if not active(generation) then
			return false, "Stopped"
		end
		if sensor then
			status("Collecting the event badge", string.format("Entering the pickup  |  Attempt %d / 3", attempt), 0.6)
			local entered, why = enterRoyaleSensor(sensor, generation, attempt)
			if not active(generation) then
				return false, "Stopped"
			end
			lastError = why or "Could not enter the badge pickup"
			if entered then
				status("Checking the event badge", "Waiting for the badge", 0.85)
				for _ = 1, 3 do
					if not pause(2, generation) then
						return false, "Stopped"
					end
					if verify(current, true) == true then
						return true, "Royalloween badge earned"
					end
				end
				lastError = "Reached the pickup, but the badge hasn't arrived yet"
			end
		else
			lastError = "The badge pickup hasn't loaded in Wickery Cliffs"
		end
		log(lastError .. string.format(" (attempt %d / 3)", attempt))
		if not pause(1, generation) then
			return false, "Stopped"
		end
	end
	return false, lastError
end

local function gardenFarm()
	local farms = workspace:FindFirstChild("Farm")
	for _, farm in ipairs(farms and farms:GetChildren() or {}) do
		local owner = getPath(farm, "Important", "Data", "Owner")
		if
			owner
			and owner:IsA("StringValue")
			and owner.Value == App.player.Name
			and not farm:GetAttribute("CommunityGarden")
		then
			return farm
		end
	end
	return nil
end

local function gardenTools(plantTypes, favoriteKey, seedName, soldTools)
	local seed, fruit
	for _, name in ipairs({ "Backpack", "Character" }) do
		local container = name == "Character" and App.player.Character or App.player:FindFirstChild(name)
		for _, tool in ipairs(container and container:GetChildren() or {}) do
			if
				not tool:IsA("Tool")
				or (soldTools and soldTools[tool])
				or tool:GetAttribute(favoriteKey)
				or tool:GetAttribute("Favorited")
			then
				continue
			end
			if tool:GetAttribute("Seed") == seedName then
				seed = seed or tool
			elseif tool:GetAttribute("Seed") == nil then
				local item = tool:FindFirstChild("Item_String")
				if item and item:IsA("StringValue") and plantTypes[item.Value] then
					fruit = fruit or tool
				end
			end
		end
	end
	return seed, fruit
end

local function gardenHarvest(farm, plantTypes, cooldowns, favoriteKey)
	local candidates = {}
	local _, root = character()
	for _, prompt in ipairs(Collection:GetTagged("CollectPrompt")) do
		if not prompt:IsA("ProximityPrompt") or not prompt:IsDescendantOf(farm) or not prompt.Enabled then
			continue
		end
		local crop = prompt.Parent and prompt.Parent.Parent
		if
			not crop
			or not plantTypes[crop.Name]
			or crop:GetAttribute("Collected")
			or (cooldowns[crop] or 0) > os.clock()
		then
			continue
		end
		local parent, favorited = crop, false
		while parent and parent ~= farm do
			favorited = favorited or parent:GetAttribute("Favorited") or parent:GetAttribute(favoriteKey)
			parent = parent.Parent
		end
		local age = getPath(crop, "Grow", "Age")
		local maximum = crop:GetAttribute("MaxAge")
		if
			not favorited
			and age
			and type(maximum) == "number"
			and age.Value >= maximum
			and crop:FindFirstChild("Item_Seed")
			and crop:FindFirstChild("Variant")
		then
			local point = positionOf(prompt.Parent)
			if point then
				table.insert(candidates, {
					crop = crop,
					prompt = prompt,
					distance = root
							and ((point.X - root.Position.X) ^ 2 + (point.Y - root.Position.Y) ^ 2 + (point.Z - root.Position.Z) ^ 2)
						or 0,
				})
			end
		end
	end
	table.sort(candidates, function(a, b)
		return a.distance < b.distance
	end)
	local chosen = candidates[1]
	return chosen and chosen.crop, chosen and chosen.prompt, candidates
end

local function gardenPlantPosition(farm, cursor)
	local locations = getPath(farm, "Important", "Plant_Locations")
	local physical = getPath(farm, "Important", "Plants_Physical")
	if not locations or not physical then
		return nil
	end
	local occupied, candidates = {}, {}
	for _, plant in ipairs(physical:GetChildren()) do
		local position = positionOf(plant)
		if position then
			table.insert(occupied, position)
		end
	end
	for _, patch in ipairs(locations:GetChildren()) do
		if not patch:IsA("BasePart") or patch.Name ~= "Can_Plant" then
			continue
		end
		local halfX, halfZ = math.min(patch.Size.X / 2, 40) - 3, math.min(patch.Size.Z / 2, 40) - 3
		for x = -halfX, halfX, 6 do
			for z = -halfZ, halfZ, 6 do
				table.insert(candidates, (patch.CFrame * CFrame.new(x, patch.Size.Y / 2, z)).Position)
			end
		end
	end
	for offset = 1, #candidates do
		local index = (cursor + offset - 1) % #candidates + 1
		local point, clear = candidates[index], true
		for _, position in ipairs(occupied) do
			if (position.X - point.X) ^ 2 + (position.Z - point.Z) ^ 2 < 25 then
				clear = false
				break
			end
		end
		if clear then
			return point, index
		end
	end
	return nil
end

local function runGarden(generation)
	if verify(current, true) == true then
		return true, "Sweet Fortune badge earned"
	end
	status("Loading the Ghoul Garden", "Loading the event and your progress", 0)
	local sources = {
		{ "Modules", "DataService" },
		{ "Data", "Events", "Halloween2026Event", "SweetFortuneQuestData" },
		{ "Data", "Events", "Halloween2026Event", "Halloween2026EventShopData" },
		{ "Modules", "PlantTraitsData", "HalloweenSlot" },
		{ "Data", "EnumRegistry", "InventoryServiceEnums" },
		{ "Modules", "SpecialSlotWindow" },
	}
	local loaded = {}
	for index, path in ipairs(sources) do
		loaded[index] = waitUntil(function()
			return module(getPath(Storage, table.unpack(path)), generation)
		end, 30, generation)
		if not loaded[index] then
			return false, "Waiting for Grow a Garden module: " .. path[#path]
		end
	end
	local service, config, shop, traits, enums, window = table.unpack(loaded)
	local slot, seedName, shopName = "HALLOWEEN_2026", "Halloween Candy Corn Carrot", "Scary Seeds"
	local seedInfo = shop.SeedShop and shop.SeedShop[seedName]
	if
		config.Enabled ~= true
		or config.BadgeId ~= current.badges[1]
		or config.ProgressKey ~= "Halloween2026SweetFortune"
		or config.Target ~= 500
		or not seedInfo
		or seedInfo.ItemType ~= "Seed"
		or seedInfo.SpecialCurrencyType ~= "CandyCorn"
		or seedInfo.Price ~= 10
		or type(enums.Favorite) ~= "string"
	then
		return false, "The Sweet Fortune event changed. Stopping here."
	end
	local plantTypes = {}
	for _, name in ipairs(traits.Plants or {}) do
		plantTypes[name] = true
	end
	if not plantTypes[seedName] or type(window.IsOpen) ~= "function" then
		return false, "Couldn't load the Ghoul Garden"
	end
	local function readData()
		if service.Receiver and type(service.Receiver.GetData) == "function" then
			local ok, profile = pcall(service.Receiver.GetData, service.Receiver)
			return ok and type(profile) == "table" and profile.Table or nil
		end
		local ok, data = call("Garden player data", function()
			return service:GetData()
		end, 3, generation)
		return ok and type(data) == "table" and data or nil
	end
	local function selected()
		local data = readData()
		return active(generation)
			and data
			and data.SaveSlots
			and data.SaveSlots.SelectedSlot == slot
			and App.player:GetAttribute("SelectedSlot") == slot
	end
	local function earned(data)
		local value = data and data.BadgeData and data.BadgeData[config.ProgressKey]
		return type(value) == "number" and value == value and math.clamp(value, 0, config.Target) or 0
	end
	local function wallet(data)
		return data and data.SpecialCurrency and tonumber(data.SpecialCurrency.CandyCorn) or 0
	end
	local function stock(data)
		local entry = data and data.EventShopStock and data.EventShopStock[shopName]
		entry = entry and entry.Stocks and entry.Stocks[seedName]
		return entry and tonumber(entry.Stock) or 0
	end
	local function remote(...)
		return getPath(Storage, "GameEvents", ...)
	end
	local teleportPlayer
	local teleportModule = getPath(Storage, "Modules", "TeleportPlayer")
	if teleportModule then
		local ok, callback = call("Garden teleport", function()
			return nativeRequire(teleportModule)
		end, 5, generation)
		if ok and type(callback) == "function" then
			teleportPlayer = callback
		end
	end
	local function npc(name)
		local market = getPath(workspace, "Interaction", "Halloween2026MarketModel")
		local model = market and market:FindFirstChild(name, true)
		local root = model and model:FindFirstChild("HumanoidRootPart")
		return root and root:IsA("BasePart") and root
	end
	local function withinNPC(name)
		local target = npc(name)
		local _, root = character()
		if not root or not target then
			return false
		end
		local dx, dy, dz =
			root.Position.X - target.Position.X,
			root.Position.Y - target.Position.Y,
			root.Position.Z - target.Position.Z
		return dx * dx + dy * dy + dz * dz <= 12 * 12
	end
	local function nearNPC(name)
		status("Visiting " .. name, string.format("%d / 500 Candy Corn earned", earned(readData())), App.progress)
		local root = waitUntil(function()
			return npc(name)
		end, 20, generation)
		if not root then
			return false, name .. " hasn't loaded yet"
		end
		local label = name == "SinisterSteven" and "Sinister Sales" or "Scary Seeds"
		local timing = teleportPlayer
				and {
					move = function(model, _, _, target)
						local facing = CFrame.lookAt(
							target.Position,
							Vector3.new(root.Position.X, target.Position.Y, root.Position.Z)
						)
						local ok = pcall(teleportPlayer, App.player, facing, label)
						return ok and App.player.Character == model and pause(0.5, generation)
					end,
				}
			or nil
		local moved, why =
			approach((root.CFrame * CFrame.new(0, 0, -8)).Position, generation, root.Parent, nil, nil, timing)
		if not moved then
			return false, why
		end
		if not teleportPlayer and active(generation) then
			fire(remote("PlayerTeleportTriggered"), label)
		end
		local arrived = waitUntil(function()
			return withinNPC(name)
		end, 2, generation)
		return arrived ~= nil, if arrived then nil else "Couldn't reach " .. name
	end
	local originalCharacter, _, originalHumanoid = character()
	local originalTool = originalCharacter and originalCharacter:FindFirstChildOfClass("Tool")
	local equipped
	table.insert(App.cleanups, function()
		local held = originalCharacter and originalCharacter:FindFirstChildOfClass("Tool")
		if
			App.player.Character == originalCharacter
			and originalHumanoid
			and equipped
			and (not held or held == equipped)
		then
			if held == equipped then
				originalHumanoid:UnequipTools()
			end
			if originalTool and originalTool.Parent == App.player:FindFirstChild("Backpack") then
				originalHumanoid:EquipTool(originalTool)
			end
		end
	end)
	local function equip(tool)
		local model, _, humanoid = character()
		if
			not model
			or not active(generation)
			or tool:GetAttribute(enums.Favorite)
			or tool:GetAttribute("Favorited")
		then
			return false
		end
		if tool.Parent ~= model and tool.Parent ~= App.player:FindFirstChild("Backpack") then
			return false
		end
		if tool.Parent ~= model then
			humanoid:EquipTool(tool)
		end
		equipped = tool
		return waitUntil(function()
			return tool.Parent == model
		end, 3, generation) ~= nil
	end
	local function ready(farm)
		return selected() and character() ~= nil and gardenFarm() == farm
	end
	local soldTools = setmetatable({}, { __mode = "k" })
	local function saleTools()
		local tools, safe = {}, true
		for _, name in ipairs({ "Backpack", "Character" }) do
			local container = name == "Character" and App.player.Character or App.player:FindFirstChild(name)
			for _, tool in ipairs(container and container:GetChildren() or {}) do
				local item = tool:IsA("Tool")
					and tool:GetAttribute("Seed") == nil
					and tool:FindFirstChild("Item_String")
				if item and item:IsA("StringValue") and plantTypes[item.Value] and not soldTools[tool] then
					if tool:GetAttribute(enums.Favorite) or tool:GetAttribute("Favorited") then
						safe = false
					else
						table.insert(tools, tool)
					end
				end
			end
		end
		return tools, safe
	end
	local cooldowns = setmetatable({}, { __mode = "k" })
	local failures, cursor = {}, 0
	local function failed(key, reason)
		failures[key] = (failures[key] or 0) + 1
		log(reason .. string.format(" (%d / 3)", failures[key]))
		return failures[key] >= 3
	end
	local lastBadge, lastEarned, unavailableAt = os.clock(), -1, os.clock()
	local deadline = os.clock() + 3600
	while active(generation) and os.clock() < deadline do
		local data = readData()
		if not data or not data.SaveSlots or not character() then
			status("Waiting for your garden", "Waiting for your garden and character to load", App.progress)
			if os.clock() - unavailableAt > 45 then
				return false, "Your character or progress didn't load. Try again."
			end
			pause(1, generation)
			continue
		end
		unavailableAt = os.clock()
		local progress = earned(data)
		status(
			"Sweet Fortune",
			string.format("%d / 500 Candy Corn earned  |  %d available", progress, wallet(data)),
			progress / config.Target
		)
		if progress ~= lastEarned or os.clock() - lastBadge >= 15 then
			lastBadge, lastEarned = os.clock(), progress
			if verify(current, true) == true then
				return true, "Sweet Fortune badge earned"
			end
		end
		if not active(generation) then
			return false, "Stopped"
		end
		if progress >= config.Target then
			status("Checking Sweet Fortune", "500 Candy Corn earned! Waiting for the badge.", 1)
			for _ = 1, 10 do
				if not pause(2, generation) then
					return false, "Stopped"
				end
				if verify(current, true) == true then
					return true, "Sweet Fortune badge earned"
				end
			end
			return false, "You earned 500 Candy Corn, but Sweet Fortune hasn't arrived yet"
		end
		local open, isOpen = pcall(window.IsOpen, slot)
		if not open or not isOpen then
			return false, "The Ghoul Garden event isn't available in this server"
		end
		if App.player:GetAttribute("InTutorial") or workspace:GetAttribute("InTutorial") then
			status(
				"Waiting for the introduction",
				"Finish the opening tutorial. I'll carry on after that.",
				App.progress
			)
			if
				not waitUntil(function()
					return not App.player:GetAttribute("InTutorial") and not workspace:GetAttribute("InTutorial")
				end, 180, generation)
			then
				return false, "Finish the opening tutorial, then press Start"
			end
			continue
		end
		if not selected() then
			status("Entering the Ghoul Garden", "Waiting for your Ghoul Garden to load", App.progress)
			if not active(generation) then
				return false, "Stopped"
			end
			local sent = fire(remote("EasterEvent", "LoadSpecialGardenRE"), slot)
			if not sent or not waitUntil(selected, 12, generation) then
				if failed("slot", "Your Ghoul Garden didn't load") then
					return false, "Your Ghoul Garden still hasn't loaded after three tries"
				end
			else
				failures.slot = nil
				pause(1, generation)
			end
			continue
		end
		local farm = waitUntil(gardenFarm, 30, generation)
		local physical = farm and getPath(farm, "Important", "Plants_Physical")
		if not farm or not physical then
			if failed("farm", "Your garden hasn't loaded yet") then
				return false, "Your garden hasn't loaded yet"
			end
			pause(1, generation)
			continue
		end
		failures.farm = nil
		local seed, fruit = gardenTools(plantTypes, enums.Favorite, seedName, soldTools)
		local spawn = farm:FindFirstChild("Spawn_Point")
		local _, root = character()
		if not fruit and spawn and spawn:IsA("BasePart") and root then
			local dx, dz = root.Position.X - spawn.Position.X, root.Position.Z - spawn.Position.Z
			if dx * dx + dz * dz > 60 * 60 or math.abs(root.Position.Y - spawn.Position.Y) > 30 then
				local moved, why = approach(spawn.Position, generation, physical)
				if not moved and active(generation) and failed("return", why or "Could not return to your garden") then
					return false, why or "Could not return to your garden"
				end
				if moved then
					failures["return"] = nil
				end
				if not pause(1, generation) then
					return false, "Stopped"
				end
				continue
			end
		end
		local crop, prompt = gardenHarvest(farm, plantTypes, cooldowns, enums.Favorite)
		local growing = 0
		for _, plant in ipairs(physical:GetChildren()) do
			if plant.Name == seedName then
				growing += 1
			end
		end
		if fruit then
			local moved, why = nearNPC("SinisterSteven")
			if moved and ready(farm) and failures.sell and fruit.Parent == App.player.Character then
				local _, _, humanoid = character()
				humanoid:UnequipTools()
				if not pause(0.2, generation) then
					return false, "Stopped"
				end
			end
			if
				moved
				and ready(farm)
				and equip(fruit)
				and ready(farm)
				and fruit.Parent == App.player.Character
				and not fruit:GetAttribute(enums.Favorite)
				and not fruit:GetAttribute("Favorited")
			then
				local model = App.player.Character
				status("Selling Halloween crops", "Waiting for Steven", App.progress)
				local targets, safeInventory = saleTools()
				local inventorySale = safeInventory and (failures.sell or 0) > 0
				local saleRemote = waitUntil(function()
					local held = remote("HalloweenEvent", "HalloweenSellHeldRE")
					local inventory = safeInventory and remote("HalloweenEvent", "HalloweenSellInventoryRE")
					held = held and held:IsA("RemoteEvent") and held or nil
					if inventory and inventory:IsA("RemoteEvent") and (inventorySale or not held) then
						inventorySale = true
						return inventory
					end
					return held
				end, 10, generation)
				if not pause(0.6, generation) then
					return false, "Stopped"
				end
				if
					not ready(farm)
					or App.player.Character ~= model
					or fruit.Parent ~= model
					or fruit:GetAttribute(enums.Favorite)
					or fruit:GetAttribute("Favorited")
				then
					continue
				end
				if not withinNPC("SinisterSteven") then
					if failed("sell", "Moved away from Steven") then
						return false, "Couldn't stay near Steven. Try again at the shop."
					end
					pause(0.5, generation)
					continue
				end
				if inventorySale then
					targets, safeInventory = saleTools()
					if not safeInventory then
						saleRemote = remote("HalloweenEvent", "HalloweenSellHeldRE")
						inventorySale = false
					end
				end
				if not inventorySale then
					targets = { fruit }
				end
				local before = readData()
				local previous = earned(before)
				if previous >= config.Target then
					continue
				end
				local id = type(enums.ITEM_UUID) == "string" and fruit:GetAttribute(enums.ITEM_UUID)
				local tracked = id
					and before
					and type(before.InventoryData) == "table"
					and before.InventoryData[id] ~= nil
				local sent = fire(saleRemote)
				local sold = sent
					and waitUntil(function()
						if not ready(farm) or App.player.Character ~= model then
							return false
						end
						local latest = readData()
						return earned(latest) > previous
							or (tracked and latest and type(latest.InventoryData) == "table" and latest.InventoryData[id] == nil)
							or (fruit.Parent ~= model and fruit.Parent ~= App.player:FindFirstChild("Backpack"))
					end, 10, generation)
				if sold then
					for _, tool in ipairs(targets) do
						soldTools[tool] = true
					end
					failures.sell = nil
				elseif not active(generation) then
					return false, "Stopped"
				elseif
					failed("sell", saleRemote and "Steven didn't buy the crop" or "The sell controls haven't loaded")
				then
					return false,
						saleRemote and "Steven isn't buying right now. Try again at the shop."
							or "The sell controls didn't load. Press Start to retry."
				end
			elseif active(generation) and failed("sell", why or "Could not equip the Halloween crop at Steven") then
				return false, why or "Could not sell the Halloween crop"
			end
		elseif crop then
			local moved, why = approach(positionOf(prompt.Parent), generation, physical)
			if moved and ready(farm) and gardenHarvest(farm, plantTypes, cooldowns, enums.Favorite) == crop then
				local _, root = character()
				local _, _, nearby = gardenHarvest(farm, plantTypes, cooldowns, enums.Favorite)
				local batch = {}
				for _, entry in ipairs(nearby) do
					local point = positionOf(entry.prompt.Parent)
					local reach = type(entry.prompt.MaxActivationDistance) == "number"
							and entry.prompt.MaxActivationDistance
						or 8
					if
						point
						and root
						and (point.X - root.Position.X) ^ 2 + (point.Y - root.Position.Y) ^ 2 + (point.Z - root.Position.Z) ^ 2
							<= math.min(reach, 12) ^ 2
					then
						table.insert(batch, entry.crop)
						if #batch >= 8 then
							break
						end
					end
				end
				local sent = #batch > 0 and fire(remote("Crops", "Collect"), batch)
				for _, plant in ipairs(batch) do
					cooldowns[plant] = os.clock() + 3
				end
				local collected = sent
					and waitUntil(function()
						local _, harvested = gardenTools(plantTypes, enums.Favorite, seedName, soldTools)
						return harvested
							or not crop:IsDescendantOf(farm)
							or not prompt:IsDescendantOf(farm)
							or not prompt.Enabled
					end, 5, generation)
				if collected then
					failures.harvest = nil
				elseif failed("harvest", "The crop hasn't been collected yet") then
					return false, "The game didn't count that harvest"
				end
			elseif active(generation) and failed("harvest", why or "Harvest target changed") then
				return false, why or "Could not reach the Halloween crop"
			end
		elseif seed and growing < 6 then
			local nextCursor
			local point = waitUntil(function()
				local position, index = gardenPlantPosition(farm, cursor)
				nextCursor = index
				return position
			end, 10, generation)
			if not point then
				if not active(generation) then
					return false, "Stopped"
				end
				if failed("space", "Looking for an empty patch of dirt") then
					return false, "No room to plant in your Ghoul Garden"
				end
				pause(1, generation)
				continue
			end
			failures.space = nil
			cursor = nextCursor
			local moved, why = approach(point, generation, physical)
			if
				moved
				and ready(farm)
				and equip(seed)
				and ready(farm)
				and seed.Parent == App.player.Character
				and not seed:GetAttribute(enums.Favorite)
				and not seed:GetAttribute("Favorited")
			then
				local model = App.player.Character
				status("Planting seeds", "Waiting for planting to load", App.progress)
				local plantRemote = waitUntil(function()
					local event = remote("Plant_RE")
					return event and event:IsA("RemoteEvent") and event
				end, 10, generation)
				if not active(generation) then
					return false, "Stopped"
				end
				if not plantRemote then
					if failed("plant", "Planting hasn't loaded yet") then
						return false, "Couldn't load planting. Try again."
					end
					continue
				end
				if not pause(0.25, generation) then
					return false, "Stopped"
				end
				if
					not ready(farm)
					or App.player.Character ~= model
					or seed.Parent ~= model
					or seed:GetAttribute("Seed") ~= seedName
					or seed:GetAttribute(enums.Favorite)
					or seed:GetAttribute("Favorited")
				then
					continue
				end
				local latest = readData()
				if not active(generation) then
					return false, "Stopped"
				end
				if earned(latest) >= config.Target then
					continue
				end
				local uses, plantedAt = seed:GetAttribute(enums.Uses), App.player:GetAttribute("HalloweenPlantedAt")
				local previousPlants = {}
				for _, plant in ipairs(physical:GetChildren()) do
					previousPlants[plant] = true
				end
				status("Planting seeds", "Waiting for planting to register", App.progress)
				local sent, sendError = fire(plantRemote, point, seedName)
				local planted = sent
					and waitUntil(function()
						if App.player.Character ~= model then
							return false
						end
						local newUses = seed:GetAttribute(enums.Uses)
						local newPlantedAt = App.player:GetAttribute("HalloweenPlantedAt")
						if
							seed.Parent == nil
							or (type(uses) == "number" and type(newUses) == "number" and newUses < uses)
							or (type(newPlantedAt) == "number" and newPlantedAt > (tonumber(plantedAt) or -math.huge))
						then
							return true
						end
						for _, plant in ipairs(physical:GetChildren()) do
							if plant.Name == seedName and not previousPlants[plant] then
								local plantedPosition = positionOf(plant)
								if
									plantedPosition
									and (plantedPosition.X - point.X) ^ 2 + (plantedPosition.Z - point.Z) ^ 2 <= 4
								then
									return true
								end
							end
						end
						return false
					end, 6, generation)
				if planted then
					failures.plant = nil
				elseif not active(generation) then
					return false, "Stopped"
				elseif
					failed(
						"plant",
						not sent and ("Couldn't plant: " .. tostring(sendError)) or "The seed hasn't planted yet"
					)
				then
					return false,
						not sent and ("Couldn't plant: " .. tostring(sendError)) or "The game didn't plant the seed"
				end
			elseif active(generation) and failed("plant", why or "Could not equip the starter seed") then
				return false, why or "Could not plant the starter seed"
			end
		elseif not seed and growing < 6 and wallet(data) >= seedInfo.Price and stock(data) > 0 then
			local moved, why = nearNPC("HalloweenSam")
			local latest = readData()
			if
				moved
				and ready(farm)
				and earned(latest) < config.Target
				and wallet(latest) >= seedInfo.Price
				and stock(latest) > 0
			then
				local before = wallet(latest)
				local sent = fire(remote("BuyEventShopStock"), seedName, shopName)
				local bought = sent
					and waitUntil(function()
						return gardenTools(plantTypes, enums.Favorite, seedName, soldTools)
					end, 10, generation)
				if bought then
					failures.buy = nil
				elseif wallet(readData()) < before then
					return false,
						"The seed cost Candy Corn but hasn't arrived. Check your inventory before buying again."
				elseif failed("buy", "The seed hasn't arrived yet") then
					return false, "Scary Seeds didn't sell us the seed"
				end
			elseif active(generation) and not moved and failed("buy", why or "Could not reach Scary Seeds") then
				return false, why or "Could not reach Scary Seeds"
			end
		else
			local reason = growing > 0 and string.format("%d starter plants growing", growing)
				or (stock(data) <= 0 and "Waiting for Scary Seeds to restock")
				or "Need a starter seed or 10 Candy Corn"
			status("Tending the Ghoul Garden", reason .. string.format("  |  %d / 500 earned", progress), App.progress)
		end
		if not pause(0.5, generation) then
			return false, "Stopped"
		end
	end
	return false, active(generation) and "Stopped after an hour. Your garden progress is saved." or "Stopped"
end

local function mvsdValue(replica, path)
	if type(replica) ~= "table" or type(replica.TryIndex) ~= "function" then
		return nil
	end
	local ok, value = pcall(replica.TryIndex, replica, path)
	if ok then
		return value
	end
	return nil
end

local function mvsdMatch(globals, player)
	local key = tostring(player.UserId)
	local id = mvsdValue(globals.PlayerMatches, { key })
	local match = id and mvsdValue(globals.RunningGames, { id })
	if type(match) ~= "table" then
		return nil, id
	end
	local participant = type(match.Participants) == "table" and match.Participants[key]
	return match, id, participant
end

local function mvsdRoundActive(match, participant)
	return type(match) == "table"
		and match.Variant == "Infection"
		and match.Phase == "InGame"
		and not match.CurrentRoundEnded
		and type(match.RoundTimer) == "number"
		and match.RoundTimer > 0
		and type(participant) == "table"
		and participant.Alive == true
		and not participant.Forfeited
		and (participant.TeamId == "Survivors" or participant.TeamId == "Infected")
end

local function clearMvsdESP(session)
	for player, mark in pairs(session.marks) do
		mark.highlight:Destroy()
		session.marks[player] = nil
	end
end

local function updateMvsdESP(globals, session, generation)
	local match, id, me = mvsdMatch(globals, App.player)
	if not active(generation) or not mvsdRoundActive(match, me) then
		clearMvsdESP(session)
		return 0, "Play Infection manually. ESP appears during your active round."
	end
	local visible, count = {}, 0
	for _, player in ipairs(Players:GetPlayers()) do
		if player == App.player then
			continue
		end
		local otherMatch, otherId, participant = mvsdMatch(globals, player)
		local model = player.Character
		local humanoid = model and model:FindFirstChildOfClass("Humanoid")
		if
			otherId == id
			and mvsdRoundActive(otherMatch, participant)
			and participant.TeamId ~= me.TeamId
			and model
			and model:IsDescendantOf(workspace)
			and humanoid
			and humanoid.Health > 0
			and not model:GetAttribute("InfectionDowned")
			and not player:GetAttribute("InfectionDowned")
		then
			visible[player] = true
			local mark = session.marks[player]
			if mark and (mark.model ~= model or mark.highlight.Parent ~= session.folder) then
				mark.highlight:Destroy()
				session.marks[player], mark = nil, nil
			end
			if not mark then
				local ok, highlight = pcall(function()
					local object = Instance.new("Highlight")
					object.Name = "InfectionOpponent"
					object.Adornee = model
					object.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
					object.FillTransparency, object.OutlineTransparency = 0.7, 0
					object.Parent = session.folder
					return object
				end)
				if not ok then
					return nil, "ESP isn't available on this executor"
				end
				mark = { model = model, highlight = highlight }
				session.marks[player] = mark
			end
			if mark.team ~= participant.TeamId then
				local color = participant.TeamId == "Infected" and Color3.fromRGB(255, 100, 100)
					or Color3.fromRGB(90, 205, 255)
				mark.highlight.FillColor, mark.highlight.OutlineColor = color, color
				mark.team = participant.TeamId
			end
			count += 1
		end
	end
	for player, mark in pairs(session.marks) do
		if not visible[player] then
			mark.highlight:Destroy()
			session.marks[player] = nil
		end
	end
	return count, string.format("%d opponent%s marked | Play the round manually", count, count == 1 and "" or "s")
end

local function mvsdAimShot(globals, args, generation, range)
	if
		not active(generation)
		or not App.mvsdSilentAim
		or args.n ~= 4
		or typeof(args[1]) ~= "Vector3"
		or typeof(args[2]) ~= "Vector3"
		or Input:GetFocusedTextBox()
	then
		return nil
	end
	local model, root = character()
	local match, id, me = mvsdMatch(globals, App.player)
	if
		not model
		or not mvsdRoundActive(match, me)
		or model:GetAttribute("InfectionDowned")
		or App.player:GetAttribute("InfectionDowned")
		or not model:FindFirstChildOfClass("Tool")
		or (args[1] - root.Position).Magnitude > 30
	then
		return nil
	end
	local direction = args[2] - args[1]
	if direction.Magnitude < 0.01 then
		return nil
	end
	local candidates = {}
	local camera = workspace.CurrentCamera
	if not camera then
		return nil
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if player == App.player then
			continue
		end
		local otherMatch, otherId, participant = mvsdMatch(globals, player)
		local other = player.Character
		local health = other and other:FindFirstChildOfClass("Humanoid")
		local part = other and (other:FindFirstChild("UpperTorso") or other:FindFirstChild("HumanoidRootPart"))
		if
			otherId ~= id
			or not mvsdRoundActive(otherMatch, participant)
			or participant.TeamId == me.TeamId
			or not other
			or not other:IsDescendantOf(workspace)
			or not health
			or health.Health <= 0
			or not part
			or not part:IsA("BasePart")
			or other:GetAttribute("InfectionDowned")
			or player:GetAttribute("InfectionDowned")
			or other:FindFirstChildOfClass("ForceField")
		then
			continue
		end
		local offset = part.Position - args[1]
		local _, visible = camera:WorldToViewportPoint(part.Position)
		if visible and offset.Magnitude > 0.01 and offset.Magnitude <= math.min(500, range or 500) then
			local dot = direction.Unit:Dot(offset.Unit)
			if dot >= 0.927 then
				table.insert(candidates, { part = part, model = other, dot = dot })
			end
		end
	end
	table.sort(candidates, function(a, b)
		return a.dot > b.dot
	end)
	local params = RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, { model }
	params.RespectCanCollide = true
	for index = 1, math.min(8, #candidates) do
		local target = candidates[index]
		local offset = target.part.Position - args[1]
		local hit = workspace:Raycast(args[1], offset.Unit * (offset.Magnitude + 1), params)
		if hit and hit.Instance:IsDescendantOf(target.model) and active(generation) and App.mvsdSilentAim then
			return { n = 4, args[1], target.part.Position, hit.Instance, hit.Position }
		end
	end
end

local function refreshMvsdAim(session)
	local hook = session.aimHook
	if not hook or hook.mode ~= "raycast" then
		return
	end
	local model = App.player.Character
	local tool = model and model:FindFirstChildOfClass("Tool")
	local gun = tool and (Collection:HasTag(tool, "Gun") or tool.Name == "DefaultGun")
	local scripts = {}
	if gun then
		local direct = tool:FindFirstChild("LocalScript")
		if direct and direct:IsA("LocalScript") then
			scripts[direct] = true
		end
		local pending = { tool }
		for index = 1, 64 do
			local object = pending[index]
			if not object then
				break
			end
			if object:IsA("LocalScript") then
				scripts[object] = true
			end
			for _, child in ipairs(object:GetChildren()) do
				if #pending >= 64 then
					break
				end
				table.insert(pending, child)
			end
		end
	end
	hook.scripts = scripts
	session.aimWaiting = not next(scripts) and "Equip your gun to use silent aim." or nil
end

local function installMvsdAim(globals, session, generation)
	local remote = getPath(Storage, "Remotes", "ShootGun")
	local mode = remote and remote:IsA("RemoteEvent") and type(remote.FireServer) == "function" and "remote"
		or "raycast"
	if mode == "raycast" and type(getcallingscript) ~= "function" then
		return false, "This gun version needs getcallingscript support for silent aim. ESP still works."
	end
	if mode == "raycast" and type(workspace.Raycast) ~= "function" then
		return false, "This executor can't access the gun raycast. ESP still works."
	end
	local hook = env.__HOLLOW_INFECTION_AIM
	if type(hook) == "table" and hook.version ~= 3 then
		hook.dispatch = nil
	end
	if type(hook) ~= "table" or hook.version ~= 3 or hook.game ~= game then
		if type(hookmetamethod) ~= "function" or type(getnamecallmethod) ~= "function" then
			return false, "Silent aim needs namecall-hook support on this executor. ESP still works."
		end
		hook = { version = 3, game = game }
		local previous
		local getMethod = getnamecallmethod
		local wrapper = function(remote, ...)
			if hook.processing then
				return previous(remote, ...)
			end
			local dispatch = hook.dispatch
			if dispatch and (remote == hook.remote or remote == workspace) and hook.enabled and hook.enabled() then
				local method = getMethod()
				local casting = false
				if hook.mode == "raycast" and remote == workspace and method == "Raycast" and hook.getCaller then
					local ok, caller = pcall(hook.getCaller)
					casting = ok and hook.scripts[caller] == true
				end
				if casting or hook.mode == "remote" and remote == hook.remote and method == "FireServer" then
					local original = table.pack(...)
					hook.processing = true
					local ok, redirected = pcall(dispatch, original, casting)
					hook.processing = false
					local args = ok and redirected or original
					local send = casting and hook.cast or hook.send
					return send(remote, table.unpack(args, 1, args.n))
				end
			end
			return previous(remote, ...)
		end
		if type(newcclosure) == "function" then
			local ok, wrapped = pcall(newcclosure, wrapper)
			if not ok then
				return false, "This executor couldn't wrap silent aim. ESP still works."
			end
			wrapper = wrapped
		end
		local ok, original = pcall(hookmetamethod, game, "__namecall", wrapper)
		if not ok or type(original) ~= "function" then
			return false, "This executor couldn't install silent aim. ESP still works."
		end
		previous = original
		env.__HOLLOW_INFECTION_AIM = hook
	end
	local dispatch = function(args, casting)
		if casting then
			if args.n < 2 or typeof(args[1]) ~= "Vector3" or typeof(args[2]) ~= "Vector3" or args[2].Magnitude < 8 then
				return nil
			end
			local redirected =
				mvsdAimShot(globals, { n = 4, args[1], args[1] + args[2], nil, nil }, generation, args[2].Magnitude)
			if not redirected then
				return nil
			end
			local result = table.clone(args)
			result[2] = (redirected[2] - args[1]).Unit * args[2].Magnitude
			return result
		end
		return mvsdAimShot(globals, args, generation)
	end
	hook.mode, hook.remote = mode, mode == "remote" and remote or nil
	hook.send = mode == "remote" and remote.FireServer or nil
	hook.cast, hook.getCaller, hook.scripts = workspace.Raycast, getcallingscript, {}
	hook.enabled = function()
		return active(generation) and App.mvsdSilentAim == true
	end
	hook.dispatch = dispatch
	session.aimHook, session.aimDispatch = hook, dispatch
	session.aimReason = nil
	refreshMvsdAim(session)
	return true
end

local function runMvsd(generation)
	status("Loading Infection ESP", "Join Infection through the game's own menu", 0)
	local globals = waitUntil(function()
		local reference = gameGlobals.ReplicatorClientReference
		if type(reference) == "table" and type(reference.get) == "function" then
			local ok, data = pcall(function()
				return { PlayerMatches = reference.get("PlayerMatches"), RunningGames = reference.get("RunningGames") }
			end)
			if ok and data.PlayerMatches and data.RunningGames then
				return data
			end
		end
		local data = module(getPath(Storage, "Client", "Modules", "ClientGlobals"), generation)
		return type(data) == "table" and data.PlayerMatches and data.RunningGames and data or nil
	end, 30, generation)
	if not globals then
		return false, active(generation) and "Match data hasn't loaded. Join Infection and try ESP again." or "Stopped"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = { marks = {}, folder = Instance.new("Folder") }
	session.folder.Name, session.folder.Parent = "HollowInfectionESP", workspace
	table.insert(App.cleanups, function()
		clearMvsdESP(session)
		if session.aimHook and session.aimHook.dispatch == session.aimDispatch then
			session.aimHook.dispatch = nil
			session.aimHook.enabled = nil
			session.aimHook.scripts = {}
		end
		session.folder:Destroy()
	end)
	while active(generation) do
		if
			App.mvsdSilentAim
			and (
				not session.aimAttached
				or session.aimHook.mode == "remote"
					and session.aimHook.remote ~= getPath(Storage, "Remotes", "ShootGun")
			)
		then
			session.aimAttached, session.aimReason = installMvsdAim(globals, session, generation)
			if not session.aimAttached then
				App.mvsdSilentAim = false
				log(session.aimReason)
				refresh()
			end
		end
		if App.mvsdSilentAim and session.aimAttached then
			refreshMvsdAim(session)
		end
		local count, detail = updateMvsdESP(globals, session, generation)
		if count == nil then
			return false, detail
		end
		status(
			"Infection helpers",
			detail
				.. (App.mvsdSilentAim and "\nGun silent aim on" or "")
				.. (session.aimReason and "\n" .. session.aimReason or "")
				.. (App.mvsdSilentAim and session.aimWaiting and "\n" .. session.aimWaiting or ""),
			0
		)
		if not pause(App.mvsdSilentAim and 0.25 or 0.5, generation) then
			break
		end
	end
	return false, "Stopped"
end

local function duelsProgress()
	if App.player:GetAttribute("DataReady") ~= true then
		return nil
	end
	local startAt, endAt = Storage:GetAttribute("Fl8StartAt"), Storage:GetAttribute("Fl8EndAt")
	local badge = Storage:GetAttribute("Fl8_mainBadgeId")
	local games, kills = Storage:GetAttribute("Fl8_mainGames"), Storage:GetAttribute("Fl8_mainKills")
	local played, earned = App.player:GetAttribute("Fl8Games") or 0, App.player:GetAttribute("Fl8Kills") or 0
	for _, value in ipairs({ games, kills, played, earned }) do
		if type(value) ~= "number" or value ~= value or value < 0 or value >= math.huge or value % 1 ~= 0 then
			return nil
		end
	end
	if type(games) ~= "number" or type(kills) ~= "number" or games + kills < 1 or games + kills > 20000 then
		return nil
	end
	if
		type(startAt) ~= "number"
		or type(endAt) ~= "number"
		or startAt ~= startAt
		or endAt ~= endAt
		or math.abs(startAt) == math.huge
		or math.abs(endAt) == math.huge
		or type(badge) ~= "number"
		or Storage:GetAttribute("Fl8Enabled") == nil
	then
		return nil
	end
	return {
		games = played,
		kills = earned,
		needGames = games,
		needKills = kills,
		main = App.player:GetAttribute("Fl8Main") == true,
		enabled = Storage:GetAttribute("Fl8Enabled") == true,
		startAt = startAt,
		endAt = endAt,
		badge = badge,
	}
end

local function duelsModes(state)
	if type(state) ~= "table" or state.leaderUserId ~= App.player.UserId or type(state.members) ~= "table" then
		return nil
	end
	local size = #state.members
	if size < 1 or size > 4 then
		return nil
	end
	if App.player:GetAttribute("TutorialPhase") == 1 then
		return size <= 2 and { "2v2" } or nil
	end
	local modes = {}
	for teamSize = size, 4 do
		table.insert(modes, teamSize .. "v" .. teamSize)
	end
	return modes
end

local function duelsLive(player, session)
	local id, side = player:GetAttribute("MatchId"), player:GetAttribute("MatchSide")
	if
		type(id) ~= "string"
		or id == ""
		or id == "PRACTICE"
		or (side ~= "A" and side ~= "B")
		or player:GetAttribute("InMatch") ~= true
		or player:GetAttribute("Alive") == false
		or player:GetAttribute("VotingPhase") == true
		or player:GetAttribute("Spectating")
		or player:GetAttribute("WieldedPreviewActive") == true
	then
		return nil, nil, player:GetAttribute("Alive") == false and "Waiting to respawn" or "Waiting to join a team"
	end
	local match = getPath(Storage, "ActiveMatches", id)
	local ending = match and match:GetAttribute("RoundEndTime")
	if session.roundMatch == id and session.roundPhase and session.roundPhase ~= "RoundLive" then
		local phase = session.roundPhase
		local countdown = phase == "Countdown" or phase == "CountdownTick" or phase == "MatchStarted"
		local shared = Storage:FindFirstChild("MatchmakingShared")
		local state = match and match:GetAttribute("State")
		local tutorialLive = countdown
			and shared
			and shared:GetAttribute("MMTutorialMatch") == true
			and (state == "Live" or state == nil)
			and type(ending) == "number"
			and ending < math.huge
			and ending > workspace:GetServerTimeNow()
			and type(session.countdownUntil) == "number"
			and os.clock() >= session.countdownUntil
			and App.player:GetAttribute("MatchId") == id
			and App.player:GetAttribute("BackpackEnabled") == true
			and App.player:GetAttribute("_WinScreenOpen") ~= true
		if not tutorialLive then
			return nil, nil, "Round state: " .. tostring(phase)
		end
	end
	if type(ending) ~= "number" or ending <= workspace:GetServerTimeNow() then
		return nil, nil, "Waiting for the live round timer"
	end
	return id, side
end

local function duelsMode()
	return App.duelsMelee == false and "Off" or (App.duelsMode or "TP Knife")
end

local function duelsRoster(session, id, generation)
	if session.rosterMatch == id and session.roster and os.clock() < (session.nextRosterScan or 0) then
		return session.roster
	end
	session.rosterMatch, session.nextRosterScan = id, os.clock() + 0.15
	local roster = table.clone(Players:GetPlayers())
	local entries, observed = {}, false
	local folder = getPath(Storage, "ActiveMatches", id, "Bots")
	if folder then
		observed = true
		for _, info in ipairs(folder:GetChildren()) do
			if info:IsA("Folder") then
				table.insert(
					entries,
					{
						proxy = info,
						userId = info:GetAttribute("UserId"),
						name = info:GetAttribute("BotName") or info.Name,
					}
				)
			end
		end
	else
		if not session.botPlayers and not session.botLoading and os.clock() >= (session.nextBotModule or 0) then
			session.nextBotModule = os.clock() + 2
			local object = getPath(Storage, "Shared", "BotPlayers")
			if object then
				session.botLoading = true
				task.spawn(function()
					local value = module(object, generation)
					if active(generation) and not session.closed then
						session.botPlayers, session.botLoading = value, nil
						session.nextRosterScan = 0
					end
				end)
			end
		end
		local bots = session.botPlayers
		local ok, proxies = false, nil
		if bots and type(bots.GetBotProxies) == "function" then
			ok, proxies = pcall(bots.GetBotProxies, id)
		end
		if ok and type(proxies) == "table" then
			observed = true
			for _, proxy in ipairs(proxies) do
				if type(proxy) == "table" and type(proxy.GetAttribute) == "function" then
					table.insert(entries, { proxy = proxy, userId = proxy.UserId, name = proxy.Name })
				end
			end
		end
	end
	if observed then
		local characters = workspace:FindFirstChild("Characters")
		local models, targets = {}, {}
		for _, model in ipairs(characters and characters:GetChildren() or {}) do
			if model:IsA("Model") and model:GetAttribute("PracticeNPC") ~= true and not model:GetAttribute("Decoy") then
				local userId = model:GetAttribute("BotUserId")
				local matchId = model:GetAttribute("MatchId")
				if
					type(userId) == "number"
					and userId == userId
					and userId ~= 0
					and (matchId == nil or matchId == id)
				then
					if not models[userId] or model:GetAttribute("BotMatchBot") == true then
						models[userId] = model
					end
				end
			end
		end
		for _, entry in ipairs(entries) do
			local userId, proxy = entry.userId, entry.proxy
			if type(userId) ~= "number" or userId ~= userId or userId == 0 then
				continue
			end
			local target = session.botTargets and session.botTargets[userId]
			if not target then
				target = { UserId = userId, _hollowBot = true }
				target.GetAttribute = function(self, name)
					local value = self.proxy:GetAttribute(name)
					if name == "InMatch" and value == nil then
						return true
					end
					if name == "MatchId" and value == nil then
						return self.matchId
					end
					return value
				end
			end
			target.proxy, target.Character, target.matchId, target.Name = proxy, models[userId], id, entry.name
			targets[userId] = target
		end
		session.botTargets = targets
	end
	for _, target in pairs(session.botTargets or {}) do
		if target.matchId == id then
			table.insert(roster, target)
		end
	end
	session.rosterMembers = {}
	for _, player in ipairs(roster) do
		session.rosterMembers[player] = true
	end
	session.roster = roster
	return roster
end

local function stopDuelsAim(session)
	if session.aimBinding then
		RunService:UnbindFromRenderStep(session.aimBinding)
		session.aimBinding = nil
	end
	local camera = session.aimCamera
	if
		camera
		and workspace.CurrentCamera == camera
		and camera.CFrame == session.aimFrame
		and session.aimEpoch == App.cameraEpoch
	then
		camera.CFrame = session.originalCamera
	end
	session.aimCamera, session.aimFrame, session.originalCamera = nil, nil, nil
	session.aimPart, session.aimReady = nil, nil
end

local function aimDuels(session, part, ready, generation)
	if App.cameraBusy then
		stopDuelsAim(session)
		return
	end
	session.aimPart, session.aimReady = part, ready
	local function update()
		local target = session.aimPart
		if App.cameraBusy or not target or not target.Parent or not session.aimReady or not session.aimReady() then
			stopDuelsAim(session)
			return
		end
		local camera = workspace.CurrentCamera
		if not camera or (target.Position - camera.CFrame.Position).Magnitude < 0.01 then
			return
		end
		if session.aimCamera ~= camera or camera.CFrame ~= session.aimFrame then
			session.originalCamera = camera.CFrame
		end
		session.aimCamera, session.aimEpoch = camera, App.cameraEpoch
		session.aimFrame = CFrame.lookAt(camera.CFrame.Position, target.Position)
		camera.CFrame = session.aimFrame
	end
	if not session.aimBinding then
		session.aimBinding = "HollowDuelsAim_" .. App.player.UserId .. "_" .. generation
		RunService:BindToRenderStep(session.aimBinding, Enum.RenderPriority.Camera.Value + 1, function()
			local ok, why = pcall(update)
			if not ok then
				session.aimError = tostring(why)
				stopDuelsAim(session)
			end
		end)
	end
	update()
end

local function releaseDuelsTool(session, keepAim)
	local tool = session.toolHeld
	local released, why = true, nil
	local input = session.inputHeld
	if input then
		released, why = pcall(input.fire, "Attack", Enum.UserInputState.End)
		if released then
			session.inputHeld = nil
		end
	end
	if tool then
		local ended, err = pcall(tool.Deactivate, tool)
		if ended then
			session.toolHeld = nil
		end
		if not ended then
			released, why = false, err
		end
	end
	if not keepAim or not released then
		stopDuelsAim(session)
	end
	return released, why
end

local function teleportDuels(session, model, root, humanoid, opponent, part, ready)
	if not ready() then
		return false, "Checking the match"
	end
	if session.followPart ~= part then
		session.followPart, session.lastTeleport, session.landingCursor, session.lastLanding = part, nil, 0, nil
	end
	if os.clock() - (session.lastTeleport or -math.huge) < 0.04 then
		return false, "Following the target"
	end
	local position = part.Position
	if
		typeof(position) ~= "Vector3"
		or position.X ~= position.X
		or position.Y ~= position.Y
		or position.Z ~= position.Z
		or position.Magnitude > 1000000
		or position.Y <= workspace.FallenPartsDestroyHeight + 32
	then
		return false, "The target is outside the playable map"
	end
	local excluded = { model }
	local characters = workspace:FindFirstChild("Characters")
	if characters then
		table.insert(excluded, characters)
	end
	for _, player in ipairs(session.roster or Players:GetPlayers()) do
		if player.Character and player.Character ~= model then
			table.insert(excluded, player.Character)
		end
	end
	local params = RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, excluded
	params.RespectCanCollide, params.IgnoreWater = true, true
	local look = part.CFrame.LookVector
	local back = Vector3.new(-look.X, 0, -look.Z)
	if back.Magnitude < 0.01 then
		back = Vector3.new(0, 0, 1)
	else
		back = back.Unit
	end
	local right = Vector3.new(back.Z, 0, -back.X)
	local offsets =
		{ back * 4, back * 3.8 + right, back * 3.8 - right, back * 3.8 + right * 1.8, back * 3.8 - right * 1.8 }
	local height = math.max(2.6, humanoid.HipHeight + root.Size.Y / 2)
	local destination
	for step = 1, #offsets do
		local index = ((session.landingCursor or 0) + step - 1) % #offsets + 1
		local offset = offsets[index]
		local hit = workspace:Raycast(position + offset + Vector3.new(0, 3, 0), Vector3.new(0, -12, 0), params)
		if
			hit
			and hit.Normal.Y > 0.65
			and hit.Position.Y < position.Y
			and hit.Position.Y > workspace.FallenPartsDestroyHeight + 32
		then
			local candidate = hit.Position + Vector3.new(0, height, 0)
			local toward = Vector3.new(position.X, candidate.Y, position.Z) - candidate
			if
				math.abs(candidate.Y - position.Y) <= 12
				and toward.Magnitude > 0.1
				and not workspace:Raycast(candidate, toward, params)
				and not workspace:Raycast(candidate, Vector3.new(0, 3, 0), params)
			then
				destination = candidate
				session.lastLanding = index
				break
			end
		end
	end
	if not destination then
		return false, "No safe ground behind the target"
	end
	if not ready() then
		return false, "Target or round changed before teleporting"
	end
	root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	local frame = CFrame.lookAt(destination, Vector3.new(position.X, destination.Y, position.Z))
	model:PivotTo(frame * root.CFrame:ToObjectSpace(model:GetPivot()))
	session.lastTeleport = os.clock()
	return true, "Teleporting behind the target"
end

local function stepDuels(session, generation)
	local function idle(detail)
		releaseDuelsTool(session)
		return false, detail
	end
	local mode = duelsMode()
	if not active(generation) then
		return idle("Stopped")
	end
	if mode == "Off" then
		return idle("Combat is off. Matchmaking and event progress are still running.")
	end
	if session.combatDisabled then
		return idle(session.combatReason or "Attacks paused")
	end
	if mode ~= "TP Knife" and mode ~= "Gun" then
		return idle("Unknown combat mode")
	end
	if session.aimError then
		local why = session.aimError
		session.aimError = nil
		releaseDuelsTool(session)
		return nil, why
	end
	local model, root, humanoid = character()
	local id, side, waiting = duelsLive(App.player, session)
	if not id or not model then
		return idle(waiting or "Waiting for the character")
	end
	if workspace:GetAttribute("LoadingScreenCompleted") ~= true then
		return idle("Waiting for the game to finish loading")
	end
	if App.player:GetAttribute("BackpackEnabled") ~= true then
		return idle("Waiting for the game to enable weapons")
	end
	if root.Anchored or humanoid.Sit or humanoid.PlatformStand or model:FindFirstChildOfClass("ForceField") then
		return idle("Waiting until you can fight")
	end
	local input = session.input
	if
		(
			input
			and (
				(type(input.isCapturing) == "function" and input.isCapturing())
				or (type(input.isDown) == "function" and input.isDown("Attack"))
				or (type(input.isPhysicallyDown) == "function" and input.isPhysicallyDown("Attack"))
			)
		)
		or Input:GetFocusedTextBox()
		or Input:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
	then
		return idle("Waiting for you to release the attack button")
	end
	local wanted = mode == "Gun" and "Revolver" or "Knife"
	local backpack = App.player:FindFirstChildOfClass("Backpack")
	local tool = model:FindFirstChild(wanted) or (backpack and backpack:FindFirstChild(wanted))
	if not tool or not tool:IsA("Tool") then
		return idle("Waiting for the " .. wanted .. " tool")
	end
	if tool.Parent ~= model then
		if os.clock() - (session.lastEquip or -math.huge) >= 0.5 then
			if not session.savedTool then
				session.originalTool, session.savedTool = model:FindFirstChildOfClass("Tool"), true
			end
			session.lastEquip = os.clock()
			humanoid:EquipTool(tool)
		end
		return false, "Equipping " .. wanted .. ", waiting for it to equip"
	end
	session.selectedTool = tool
	local roster = duelsRoster(session, id, generation)
	local function valid(player)
		if player == App.player or not session.rosterMembers[player] then
			return nil, nil, true
		end
		local otherId, otherSide = player:GetAttribute("MatchId"), player:GetAttribute("MatchSide")
		if
			player:GetAttribute("Alive") == false
			or player:GetAttribute("InMatch") == false
			or player:GetAttribute("Spectating")
			or otherId ~= nil and otherId ~= id
			or otherSide ~= nil and otherSide == side
		then
			return nil, nil, true
		end
		local other = player.Character
		local part = other and other:FindFirstChild("HumanoidRootPart")
		local health = other and other:FindFirstChildOfClass("Humanoid")
		if health and health.Health <= 0 then
			return nil, nil, true
		end
		if otherId ~= id or otherSide ~= "A" and otherSide ~= "B" then
			return nil, "Waiting for the opponent's match data"
		end
		if
			not part
			or not health
			or type(player) == "table" and player._hollowBot and not other:IsDescendantOf(workspace)
		then
			return nil, "Waiting for the opponent's character"
		end
		if other:FindFirstChildOfClass("ForceField") then
			return part, "Waiting for spawn protection to end"
		end
		return part
	end
	local opponent = session.target
	if session.targetMatch and session.targetMatch ~= id then
		opponent = nil
		session.target = nil
	end
	local part, targetWait, removed
	if opponent then
		part, targetWait, removed = valid(opponent)
	end
	if removed then
		session.target, opponent = nil, nil
	end
	if not opponent then
		local distance, pending
		for _, player in ipairs(roster) do
			local candidate, why, gone = valid(player)
			local length = candidate and (candidate.Position - root.Position).Magnitude
			if length and not why and (not distance or length < distance) then
				session.target, distance = player, length
			elseif
				not gone
				and not pending
				and player:GetAttribute("MatchId") == id
				and player:GetAttribute("MatchSide") ~= side
			then
				pending = player
			end
		end
		session.target = session.target or pending
		session.targetMatch = id
		opponent = session.target
		if opponent then
			part, targetWait = valid(opponent)
		end
	end
	if not part or targetWait then
		return idle(targetWait or "Waiting for the opponent to spawn")
	end
	local function ready()
		local latestId, latestSide = duelsLive(App.player, session)
		local currentPart, blocked = valid(opponent)
		return active(generation)
			and not session.closed
			and duelsMode() == mode
			and not session.combatDisabled
			and App.player.Character == model
			and root.Parent == model
			and humanoid.Parent == model
			and humanoid.Health > 0
			and not humanoid.Sit
			and not humanoid.PlatformStand
			and not root.Anchored
			and not model:FindFirstChildOfClass("ForceField")
			and tool.Parent == model
			and App.player:GetAttribute("BackpackEnabled") == true
			and latestId == id
			and latestSide == side
			and currentPart == part
			and not blocked
	end
	local _, moveReason = teleportDuels(session, model, root, humanoid, opponent, part, ready)
	if not ready() then
		return idle("Checking the target")
	end
	local aim = opponent.Character:FindFirstChild("Head") or part
	if not aim:IsA("BasePart") then
		aim = part
	end
	if not workspace.CurrentCamera then
		return idle("Waiting for the aiming camera")
	end
	aimDuels(session, aim, ready, generation)
	local offset = part.Position - root.Position
	if offset.Magnitude > 4.25 or math.abs(offset.Y) > 3 then
		return false, moveReason
	end
	if tool.Enabled == false then
		return false, wanted .. " is reloading or on cooldown"
	end
	local timing = session.timings and session.timings[wanted]
	local cooldown = wanted == "Revolver" and 2 or 0.33
	local configured = timing and (wanted == "Revolver" and timing.SHOT_COOLDOWN or timing.MELEE_COOLDOWN)
	if type(configured) == "number" and configured >= 0.1 and configured <= 10 then
		cooldown = configured
	end
	session.lastAttacks = session.lastAttacks or {}
	if os.clock() - (session.lastAttacks[wanted] or -math.huge) < cooldown then
		return false, "Waiting for " .. wanted .. " cooldown"
	end
	local camera = workspace.CurrentCamera
	local origin = mode == "Gun" and camera.CFrame.Position or root.Position
	local difference = aim.Position - origin
	local params = RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, { model, opponent.Character }
	params.RespectCanCollide = true
	if difference.Magnitude < 0.01 or workspace:Raycast(origin, difference, params) then
		session.landingCursor = session.lastLanding or 0
		return idle("Waiting for a clear " .. wanted .. " attack")
	end
	if not ready() then
		return idle("Target or round changed before attacking")
	end
	session.lastAttacks[wanted] = os.clock()
	local ok, why
	if input and type(input.fire) == "function" and type(input.isDown) == "function" then
		session.inputHeld = input
		ok, why = pcall(input.fire, "Attack", Enum.UserInputState.Begin)
		if ok and not input.isDown("Attack") then
			ok, why = pcall(input.fire, "Attack", Enum.UserInputState.End)
			if ok then
				session.inputHeld, session.toolHeld = nil, tool
				ok, why = pcall(tool.Activate, tool)
			end
		end
	else
		session.toolHeld = tool
		ok, why = pcall(tool.Activate, tool)
	end
	local held = ok and pause(0.04, generation)
	local released, releaseError = releaseDuelsTool(session, ok and held and ready())
	if not ok or not released then
		return nil, tostring(not ok and why or releaseError)
	end
	if not held or not ready() then
		return false, "Stopped or the round changed during the attack"
	end
	return true, mode .. ": following and attacking the target"
end

local function runDuels(generation)
	if verify(current, true) == true then
		return true, "Murder Duels Hollow badge earned"
	end
	status("Loading Murder Duels", "Loading the event and matchmaking", 0)
	local progress = waitUntil(duelsProgress, 60, generation)
	if not progress then
		return false, "The event or player data has not loaded"
	end
	if progress.badge ~= current.badges[1] then
		return false, "This server has a different event badge"
	end
	local remotes = waitUntil(function()
		local folder = getPath(Storage, "MatchmakingShared", "Remotes")
		return folder
			and folder:FindFirstChild("GetMyState")
			and folder:FindFirstChild("QueueModes")
			and folder:FindFirstChild("CancelQueue")
			and folder
	end, 30, generation)
	if not remotes then
		return false, "The matchmaking remotes have not loaded"
	end
	local session = {
		connections = {},
		lastState = -math.huge,
		lastQueue = -math.huge,
		attempts = 0,
		timings = {},
		timingChecked = {},
	}
	local function tickets(state)
		return type(state) == "table" and type(state.activeTickets) == "table" and next(state.activeTickets) ~= nil
	end
	local function sameTickets(expected, actual)
		for mode, ticket in pairs(expected) do
			if type(ticket) == "table" or actual[mode] ~= ticket then
				return false
			end
		end
		for mode in pairs(actual) do
			if expected[mode] == nil then
				return false
			end
		end
		return true
	end
	local function cancelOwned()
		if not session.owned or session.canceling or App.player:GetAttribute("InMatch") == true then
			return
		end
		session.canceling = true
		task.spawn(function()
			local ok, state = pcall(function()
				return remotes.GetMyState:InvokeServer()
			end)
			if
				ok
				and type(state) == "table"
				and not state.matched
				and tickets(state)
				and state.leaderUserId == App.player.UserId
				and type(state.members) == "table"
				and #state.members == session.partySize
			then
				local ours = true
				for mode in pairs(state.activeTickets) do
					if not table.find(session.modes or {}, mode) then
						ours = false
					end
				end
				if session.ticketLease and not sameTickets(session.ticketLease, state.activeTickets) then
					ours = false
				end
				if ours and App.player:GetAttribute("InMatch") ~= true then
					pcall(function()
						remotes.CancelQueue:InvokeServer()
					end)
				end
			end
			session.owned, session.canceling = false, false
		end)
	end
	table.insert(App.cleanups, function()
		session.closed = true
		releaseDuelsTool(session)
		local model, _, humanoid = character()
		local original = session.originalTool
		if
			model
			and original
			and session.selectedTool
			and session.selectedTool.Parent == model
			and (original.Parent == model or original.Parent == App.player:FindFirstChildOfClass("Backpack"))
		then
			pcall(humanoid.EquipTool, humanoid, original)
		end
		for _, connection in ipairs(session.connections) do
			connection:Disconnect()
		end
		cancelOwned()
	end)
	local function listen(signal, callback)
		if signal then
			table.insert(
				session.connections,
				signal:Connect(function(...)
					if active(generation) and not session.closed then
						local ok, why = pcall(callback, ...)
						if not ok then
							session.listenerError = tostring(why)
						end
					end
				end)
			)
		end
	end
	local function snapshot(state)
		if type(state) == "table" then
			session.state, session.lastState = state, os.clock()
			if state.matched then
				session.owned = false
			elseif session.owned then
				if tickets(state) then
					if not session.ticketLease then
						session.ticketLease = table.clone(state.activeTickets)
					elseif not sameTickets(session.ticketLease, state.activeTickets) then
						session.owned = false
					end
				elseif not session.awaiting then
					session.owned = false
				end
			end
		end
	end
	for _, name in ipairs({ "PartyStateChanged", "QueueStateChanged" }) do
		local event = remotes:FindFirstChild(name)
		listen(event and event.OnClientEvent, snapshot)
	end
	local roundState = getPath(Storage, "MatchRemotes", "State")
	listen(roundState and roundState.OnClientEvent, function(id, state)
		if id == App.player:GetAttribute("MatchId") and type(state) == "table" then
			if
				state.t == "RoundLive"
				or state.t == "Countdown"
				or state.t == "CountdownTick"
				or state.t == "RoundEnded"
				or state.t == "MatchEnded"
				or state.t == "MatchStarted"
			then
				session.roundMatch, session.roundPhase = id, state.t
				if state.t == "Countdown" or state.t == "CountdownTick" or state.t == "MatchStarted" then
					local left = state.t == "CountdownTick" and state.left or 3
					if type(left) ~= "number" or left ~= left or left < 0 or left > 30 then
						left = 3
					end
					session.countdownUntil = os.clock() + left + 0.25
				else
					session.countdownUntil = nil
				end
				if state.t ~= "RoundLive" then
					releaseDuelsTool(session)
				end
				if state.t == "RoundEnded" or state.t == "MatchEnded" then
					session.target, session.targetMatch = nil, nil
				end
				session.nextRosterScan = 0
			end
		end
	end)
	listen(App.player.OnTeleport, function(state, destination)
		if state == Enum.TeleportState.Started and not session.prepared and type(destination) == "number" then
			session.prepared = true
			if not prepareTravel(destination, true) then
				log("Run the script again when you arrive")
			end
		end
	end)
	listen(Teleport.TeleportInitFailed, function(player, _, message)
		if player == App.player then
			session.teleportFailure = tostring(message)
		end
	end)
	local deadline, stateErrors, combatErrors = os.clock() + 3600, 0, 0
	while active(generation) and os.clock() < deadline do
		progress = duelsProgress()
		if not progress then
			releaseDuelsTool(session)
			progress = waitUntil(duelsProgress, 30, generation)
		end
		if not progress then
			return false, "Your event progress stopped loading. Try again."
		end
		if progress.badge ~= current.badges[1] then
			return false, "The event changed. Stopping here."
		end
		local ratio = (math.min(progress.games, progress.needGames) + math.min(progress.kills, progress.needKills))
			/ (progress.needGames + progress.needKills)
		local counts = string.format(
			"%d / %d games  |  %d / %d kills",
			progress.games,
			progress.needGames,
			progress.kills,
			progress.needKills
		)
		if progress.main or (progress.games >= progress.needGames and progress.kills >= progress.needKills) then
			releaseDuelsTool(session)
			cancelOwned()
			status("Checking your Hollow badge", counts, ratio)
			for _ = 1, 10 do
				if verify(current, true) == true then
					return true, "Murder Duels Hollow badge earned"
				end
				if not pause(2, generation) then
					return false, "Stopped"
				end
			end
			return false, "Goals reached! Waiting for the Hollow badge."
		end
		local now = workspace:GetServerTimeNow()
		if not progress.enabled or now < progress.startAt or now >= progress.endAt then
			return false, "The Hollow quest is not active in this server"
		end
		if session.teleportFailure then
			return false, "The game's match transfer failed: " .. session.teleportFailure
		end
		if session.listenerError then
			return false, "A Murder Duels state listener failed: " .. session.listenerError
		end
		local inMatch = App.player:GetAttribute("InMatch") == true
		local matchmaking = Storage:FindFirstChild("MatchmakingShared")
		if
			matchmaking
			and matchmaking:GetAttribute("MMTutorialMatch") == true
			and App.player:GetAttribute("_WinScreenOpen") == true
		then
			releaseDuelsTool(session)
			local matchId = App.player:GetAttribute("MatchId")
				or App.player:GetAttribute("_LastMatchId")
				or session.roundMatch
			session.tutorialReturnAt = session.tutorialReturnAt or os.clock()
			status("Tutorial finished", "Returning to the lobby before queueing normal matches", ratio)
			if type(matchId) == "string" and session.tutorialDismissed ~= matchId then
				local sent, why = fire(getPath(Storage, "MatchRemotes", "WinScreenDismiss"), matchId)
				if not sent then
					return false, "Couldn't close the tutorial results: " .. tostring(why)
				end
				session.tutorialDismissed, session.tutorialReturnAt = matchId, os.clock()
			end
			if session.tutorialReturnAt and os.clock() - session.tutorialReturnAt > 30 then
				return false, "The tutorial return didn't finish. Use Return to Lobby in the game."
			end
			if not pause(0.25, generation) then
				return false, "Stopped"
			end
			continue
		end
		local detail, delay = nil, 0.5
		if inMatch then
			session.owned, session.awaiting, session.attempts = false, false, 0
			session.matchedAt = nil
			local mode = duelsMode()
			if session.currentMode ~= mode then
				releaseDuelsTool(session)
				session.currentMode, session.combatDisabled, session.combatReason = mode, false, nil
				session.followPart, session.lastTeleport, session.nextScan = nil, nil, 0
				combatErrors = 0
			end
			if mode ~= "Off" and not session.combatDisabled then
				if not session.inputChecked and workspace:GetAttribute("LoadingScreenCompleted") == true then
					local object = getPath(Storage, "Extensions", "InputMap")
					session.inputDeadline = session.inputDeadline or os.clock() + 20
					if object then
						session.inputChecked = true
						session.input = module(object, generation)
					elseif os.clock() >= session.inputDeadline then
						session.inputChecked = true
					end
				end
				local wanted = mode == "Gun" and "Revolver" or "Knife"
				if not session.timingChecked[wanted] then
					session.timingChecked[wanted] = true
					session.timings[wanted] = module(getPath(Storage, "Shared", wanted .. "Timing"), generation)
				end
				local ok, attempted, reason = pcall(stepDuels, session, generation)
				if session.toolHeld or session.inputHeld then
					return false, "The weapon got stuck, so combat has stopped. Try equipping it again."
				end
				if not ok or attempted == nil then
					combatErrors += 1
					releaseDuelsTool(session)
					session.combatReason = tostring(not ok and attempted or reason):sub(1, 180)
					log("Murder Duels combat: " .. session.combatReason)
					if combatErrors >= 3 then
						session.combatDisabled = true
					end
				else
					combatErrors = 0
				end
				detail, delay = ok and reason or session.combatReason, 0.05
			else
				releaseDuelsTool(session)
			end
			if session.combatDisabled then
				detail = mode .. " paused: " .. (session.combatReason or "A combat error occurred")
			elseif mode == "Off" then
				detail = "Combat is off. Matchmaking and event progress are still running."
			end
		else
			releaseDuelsTool(session)
			if os.clock() - session.lastState >= 5 then
				local ok, state = call("Murder Duels queue state", function()
					return remotes.GetMyState:InvokeServer()
				end, 8, generation)
				session.lastState = os.clock()
				if ok and type(state) == "table" then
					snapshot(state)
					stateErrors = 0
				else
					stateErrors += 1
					if stateErrors >= 3 or App.pending["Murder Duels queue state"] then
						return false, "Couldn't read the queue. Check matchmaking in the game."
					end
				end
			end
			local state = session.state
			local reserved = getPath(Storage, "MatchmakingShared", "IsReservedServer")
			local busy = App.player:GetAttribute("VotingPhase") == true
				or App.player:GetAttribute("DuelStationQueued") == true
				or App.player:GetAttribute("Spectating")
				or App.player:GetAttribute("_SpinnerOpen") == true
				or (
					(App.player:GetAttribute("_WinScreenOpen") == true or (reserved and reserved.Value == true))
					and App.player:GetAttribute("MMRequeueReady") ~= true
				)
			if type(state) ~= "table" then
				detail = "Waiting for matchmaking state"
			elseif state.matched then
				session.owned, session.awaiting = false, false
				session.matchedAt = session.matchedAt or os.clock()
				detail = "Found a match, waiting to join"
				if os.clock() - session.matchedAt > 45 then
					return false, "The match didn't load. Check the game before queuing again."
				end
			elseif tickets(state) then
				session.awaiting, session.matchedAt, session.attempts = false, nil, 0
				detail = "Searching selected modes"
			elseif session.awaiting then
				detail = "Joining the queue"
				if os.clock() - session.lastQueue >= 8 then
					return false, "The queue didn't respond. Check matchmaking in the game."
				end
			elseif busy then
				detail = "Waiting for the tutorial, results screen, or current activity to finish"
			else
				local modes = duelsModes(state)
				local shared = Storage:FindFirstChild("MatchmakingShared")
				if not modes then
					detail = "Waiting for the party leader to queue"
				elseif shared and shared:GetAttribute("MMEnabled") == false then
					detail = "Matchmaking is temporarily disabled"
				elseif os.clock() - session.lastQueue >= 5 then
					if session.attempts >= 3 then
						return false, "Couldn't join the queue after three tries. Check Logs."
					end
					session.modes, session.partySize = modes, #state.members
					if App.player:GetAttribute("TutorialPhase") == 1 and not session.tutorialPanelOpened then
						local sent, why = fire(remotes:FindFirstChild("TutorialPanelOpened"))
						if not sent then
							return false, "Tutorial entry is still loading: " .. tostring(why)
						end
						session.tutorialPanelOpened = true
					end
					session.ticketLease = nil
					session.lastQueue, session.attempts = os.clock(), session.attempts + 1
					local ok, accepted, why = call("Murder Duels queue", function()
						if not active(generation) then
							return false
						end
						local accepted, why = remotes.QueueModes:InvokeServer(modes)
						session.owned = accepted ~= false
						if session.closed then
							cancelOwned()
						end
						return accepted, why
					end, 8, generation)
					if not ok then
						return false, "Couldn't join the queue: " .. tostring(accepted)
					end
					if accepted == false then
						log("Matchmaking rejected: " .. tostring(why))
						detail = "Couldn't queue yet, trying again in a moment"
					else
						session.awaiting = true
						session.lastState = -math.huge
						detail = "Queueing " .. table.concat(modes, ", ")
					end
				else
					detail = "Waiting before the next queue attempt"
				end
			end
		end
		status("Murder Duels", counts .. "\n" .. (detail or "Waiting for the next match"), ratio)
		if not pause(delay, generation) then
			return false, "Stopped"
		end
	end
	return false, active(generation) and "Stopped after an hour. Your event progress is saved." or "Stopped"
end

local function huntedProgress(controller)
	if
		type(controller) ~= "table"
		or type(controller.isPlayerDataReady) ~= "function"
		or type(controller.getPlayerDataValue) ~= "function"
		or not controller:isPlayerDataReady()
	then
		return nil
	end
	local coins = controller:getPlayerDataValue("EventCoins")
	if coins == nil then
		return 0
	end
	if type(coins) ~= "table" then
		return nil
	end
	local count = coins.HalloweenCoins
	if count == nil then
		return 0
	end
	if type(count) ~= "number" or count ~= count or count < 0 or count > 1000000000 then
		return nil
	end
	return count
end

local function huntedEventScript(claim)
	local scripts = App.player:FindFirstChild("PlayerScripts")
	local object = scripts and scripts:FindFirstChild(claim and "TheHollowEvent" or "HalloweenEvent")
	if not object and not claim then
		object = getPath(scripts, "OnJoin", "HalloweenEvent")
	end
	return object and object:IsA("LocalScript") and not object.Disabled and object
end

local function huntedPointKey(position)
	return string.format(
		"%d:%d:%d",
		math.floor(position.X * 2 + 0.5),
		math.floor(position.Y * 2 + 0.5),
		math.floor(position.Z * 2 + 0.5)
	)
end

local function huntedMemory()
	local scope = tostring(game.PlaceId)
		.. ":"
		.. tostring(game.JobId)
		.. ":"
		.. tostring(workspace:GetAttribute("RoundRestarted"))
	local memory = env.__HOLLOW_HUNTED_VISITS
	if type(memory) ~= "table" or memory.scope ~= scope then
		memory = { scope = scope, visited = {} }
		env.__HOLLOW_HUNTED_VISITS = memory
	end
	return memory.visited
end

local function recoverHunted(session, manual)
	local saved = session and session.interaction
	if not saved and not manual then
		return true
	end
	if App.huntedRecovering then
		return false, "Already resetting the event controls"
	end
	if session then
		session.interaction = nil
	end
	local model, root, humanoid = character()
	if saved and model ~= saved.model then
		return false, "You respawned. Try resetting the controls again."
	end
	local camera = workspace.CurrentCamera
	App.huntedRecovering = true
	local eventScript = saved and saved.script or huntedEventScript(false)
	local errors = {}
	local function restore(callback)
		local ok, why = pcall(callback)
		if not ok then
			table.insert(errors, tostring(why))
		end
		return ok
	end
	local restarted = eventScript
		and eventScript.Parent
		and not eventScript.Disabled
		and restore(function()
			eventScript.Disabled = true
		end)
	if root and (manual or root == saved.root) then
		restore(function()
			root.Anchored = saved and saved.anchored or false
		end)
	end
	if camera and (manual or camera == saved.camera) and camera.CameraType == Enum.CameraType.Scriptable then
		restore(function()
			camera.CameraType = saved and saved.cameraType or Enum.CameraType.Custom
			camera.CameraSubject = saved and saved.subject or humanoid
			if saved and saved.frame then
				camera.CFrame = saved.frame
			end
		end)
	end
	task.defer(function()
		if restarted and eventScript.Parent and eventScript.Disabled then
			restore(function()
				eventScript.Disabled = false
			end)
		end
		App.huntedRecovering = false
		if #errors > 0 then
			log("HUNTED reset: " .. table.concat(errors, ", "))
		end
	end)
	return #errors == 0,
		#errors == 0 and "You can move again. Door controls restarted."
			or "Couldn't reset all the controls. Check Logs."
end

local function huntedDoor(session)
	local _, root = character()
	local folder = workspace:FindFirstChild("HalloweenDoors")
	local found, position, distance
	for _, door in ipairs(folder and folder:GetChildren() or {}) do
		if session.used[door] or not door:IsA("Model") then
			continue
		end
		local collider = door:FindFirstChild("ClickCollider", true)
		local camera = door:FindFirstChild("CameraPosition", true)
		if not collider or not collider:IsA("BasePart") or not camera or not camera:IsA("BasePart") then
			continue
		end
		local key = huntedPointKey(collider.Position)
		local detector = collider:FindFirstChildOfClass("ClickDetector")
		if detector and detector.MaxActivationDistance <= 0 then
			session.visited[key] = collider.Position
		end
		local blocked = session.blocked[key]
		if session.visited[key] or (blocked and blocked.untilAt > os.clock()) then
			continue
		end
		local real = door:FindFirstChild("RealMonkey", true)
		local fake = door:FindFirstChild("FakeMonkey", true)
		if
			not detector
			or not real
			or not fake
			or not fake:FindFirstChild("StartCoinAttach", true)
			or not camera:FindFirstChild("EndCoinAttach", true)
		then
			continue
		end
		local length = root and (collider.Position - root.Position).Magnitude or math.huge
		if not found or length < distance then
			found, position, distance = door, camera.Position, length
		end
	end
	return found, position
end

local function probeHuntedDoors(session, generation)
	local points, seen = {}, {}
	local spawners = workspace:FindFirstChild("HDoorSpawner")
	local function add(position)
		local key = huntedPointKey(position)
		if not seen[key] then
			seen[key] = true
			table.insert(points, { position = position, key = key })
		end
	end
	for _, part in ipairs(spawners and spawners:GetChildren() or {}) do
		if part:IsA("BasePart") then
			add(part.Position)
		end
	end
	for _, value in ipairs(current.doorAreas and current.doorAreas[game.PlaceId] or {}) do
		add(Vector3.new(value[1], value[2], value[3]))
	end
	if #points == 0 or os.clock() < (session.nextProbe or 0) then
		return false
	end
	for offset = 1, #points do
		local index = ((session.probeIndex or 0) + offset - 1) % #points + 1
		local point = points[index]
		local done = false
		for _, position in pairs(session.visited) do
			if (position - point.position).Magnitude <= 12 then
				done = true
				break
			end
		end
		if not done and os.clock() - (session.probed[point.key] or -math.huge) >= 45 then
			session.probeIndex, session.probed[point.key], session.nextProbe = index, os.clock(), os.clock() + 3
			call("HUNTED door streaming", function()
				App.player:RequestStreamAroundAsync(point.position, 3)
			end, 4, generation)
			if not active(generation) then
				return false
			end
			if huntedDoor(session) then
				return true
			end
			local moved = approach(point.position, generation, spawners)
			if moved then
				pause(0.3, generation)
			end
			return moved
		end
	end
	return false
end

local function runHunted(generation)
	if verify(current, true) == true then
		return true, "HUNTED Hollow badge earned"
	end
	status("Loading HUNTED", "Loading the event and your candy count", 0)
	local loadingReason = "Loading your candy count"
	local function missing(detail)
		loadingReason = detail
		status("Loading HUNTED", detail, 0)
		return nil
	end
	local controller, nextDataLookup = nil, 0
	local registry = shared
	if type(getrenv) == "function" then
		local ok, native = pcall(getrenv)
		if ok and type(native) == "table" and native.shared then
			registry = native.shared
		end
	end
	local loaded = waitUntil(function()
		if workspace:GetAttribute("loaded") ~= true then
			return missing("Waiting for HUNTED's world to finish loading")
		end
		if not App.player:GetAttribute("DATA_LOADED") then
			return missing("Waiting for HUNTED to finish loading")
		end
		if not controller and os.clock() >= nextDataLookup then
			nextDataLookup = os.clock() + 1
			if registry then
				local ok, value = call("Loading HUNTED", function()
					return registry("DataController")
				end, 3, generation)
				if
					ok
					and type(value) == "table"
					and type(value.getPlayerDataValue) == "function"
					and type(value.isPlayerDataReady) == "function"
				then
					controller = value
				end
			end
			if not controller then
				local folder = getPath(game:GetService("ReplicatedFirst"), "Client", "systems", "internal", "data")
				local object
				for _, child in ipairs(folder and folder:GetChildren() or {}) do
					if child:IsA("ModuleScript") then
						if object then
							object = nil
							break
						end
						object = child
					end
				end
				if object then
					controller = module(object, generation)
				end
			end
		end
		if not controller then
			return missing("Waiting for your HUNTED progress to load")
		end
		local count = huntedProgress(controller)
		if count == nil then
			return missing("Loading your Halloween candy count")
		end
		if count >= 75 or App.player:GetAttribute("HalloweenBadgeEligible") == true then
			return true
		end
		return huntedEventScript(false) or missing("Waiting for the Halloween doors to load")
	end, 45, generation)
	if not loaded then
		return false, active(generation) and "HUNTED loading timed out: " .. loadingReason or "Stopped"
	end
	local function returnToLobby(count)
		local transferError
		local connection = Teleport.TeleportInitFailed:Connect(function(player, _, message)
			if player == App.player and active(generation) then
				transferError = tostring(message)
			end
		end)
		table.insert(App.cleanups, function()
			connection:Disconnect()
		end)
		status("Returning to the altar", string.format("%d / 75 candies", math.floor(count)), 0.9)
		local continued = prepareTravel(current.place, true)
		App.traveling = true
		local sent, why = pcall(Teleport.Teleport, Teleport, current.place, App.player)
		if not sent then
			App.traveling = false
			return false, "HUNTED lobby transfer failed: " .. tostring(why)
		end
		local startedAt = os.clock()
		while active(generation) and os.clock() - startedAt < 12 do
			if transferError then
				App.traveling = false
				return false, "HUNTED lobby transfer failed: " .. transferError
			end
			pause(0.25, generation)
		end
		if not active(generation) then
			return false, "Stopped"
		end
		return nil,
			continued and "Heading to HUNTED's lobby. I'll keep going there."
				or "Heading to HUNTED's lobby. Run the script again there."
	end
	local initialCount = huntedProgress(controller)
	if initialCount == nil then
		return false, "Your candy count stopped loading. Try again."
	end
	if game.PlaceId ~= current.place and initialCount and initialCount >= 75 then
		return returnToLobby(initialCount)
	end
	local remotes = {}
	if initialCount < 75 and App.player:GetAttribute("HalloweenBadgeEligible") ~= true then
		remotes.doors = waitUntil(function()
			local folder = Storage:FindFirstChild("HalloweenRemotes")
			for _, name in ipairs({ "RequestInteract", "DoorResult", "PlayCoinSFX", "CoinArrived", "CloseDoor" }) do
				local remote = folder and folder:FindFirstChild(name)
				if not remote or not remote:IsA("RemoteEvent") then
					return missing("Waiting for HalloweenRemotes." .. name)
				end
			end
			return folder
		end, 30, generation)
		if not remotes.doors then
			return false, active(generation) and "HUNTED loading timed out: " .. loadingReason or "Stopped"
		end
	end
	local session = {
		connections = {},
		used = setmetatable({}, { __mode = "k" }),
		visited = huntedMemory(),
		blocked = {},
		probed = {},
	}
	table.insert(App.cleanups, function()
		session.closed = true
		recoverHunted(session, false)
		for _, connection in ipairs(session.connections) do
			connection:Disconnect()
		end
	end)
	local function listen(signal, callback)
		table.insert(
			session.connections,
			signal:Connect(function(...)
				if active(generation) and not session.closed then
					local ok, why = pcall(callback, ...)
					if not ok then
						session.error = tostring(why)
					end
				end
			end)
		)
	end
	if remotes.doors then
		listen(remotes.doors.DoorResult.OnClientEvent, function(door, kind)
			if door == session.door and (kind == "Real" or kind == "Fake") then
				session.result, session.resultAt = kind, os.clock()
			elseif door == nil and session.door then
				session.denied = true
			end
		end)
		listen(remotes.doors.CloseDoor.OnClientEvent, function(door)
			if door == session.door then
				session.closedAt = os.clock()
			end
		end)
	end
	local constants = module(getPath(Storage, "GameEvents", "Halloween", "HalloweenConstants"), generation) or {}
	local function timing(name, fallback)
		local value = constants[name]
		return type(value) == "number" and value >= 0 and value <= 10 and value or fallback
	end
	local function cameraReady()
		local _, root = character()
		local camera = workspace.CurrentCamera
		return root and not root.Anchored and camera and camera.CameraType ~= Enum.CameraType.Scriptable
	end
	local function countText(count)
		return string.format("%d / 75 candies", math.floor(count))
	end
	local deadline, idleSince, failures = os.clock() + 3600, os.clock(), 0
	while active(generation) and os.clock() < deadline do
		if session.error then
			return false, "HUNTED event listener failed: " .. session.error
		end
		local count = huntedProgress(controller)
		if count == nil then
			status("Waiting for candy data", "Your event progress is still loading", nil)
			if not waitUntil(function()
				return huntedProgress(controller) ~= nil
			end, 30, generation) then
				return false, active(generation) and "Your candy count didn't load. Try again." or "Stopped"
			end
			continue
		end
		if count >= 75 or App.player:GetAttribute("HalloweenBadgeEligible") == true then
			if game.PlaceId ~= current.place then
				return returnToLobby(count)
			end
			if not remotes.badge then
				remotes.badge = waitUntil(function()
					if not huntedEventScript(true) then
						return missing("Waiting for the lobby reward to load")
					end
					local folder = Storage:FindFirstChild("HalloweenBadgeRemotes")
					for _, name in ipairs({ "RequestClaim", "ClaimStart", "CandyArrived", "FinaleDone" }) do
						local remote = folder and folder:FindFirstChild(name)
						if not remote or not remote:IsA("RemoteEvent") then
							return missing("Waiting for the lobby's HalloweenBadgeRemotes." .. name)
						end
					end
					return folder
				end, 30, generation)
				if not remotes.badge then
					return false,
						active(generation) and "HUNTED claim loading timed out: " .. loadingReason or "Stopped"
				end
				listen(remotes.badge.ClaimStart.OnClientEvent, function(amount)
					if
						session.claiming
						and type(amount) == "number"
						and amount >= 1
						and amount <= 1000
						and amount % 1 == 0
					then
						session.claimStarted = true
					end
				end)
			end
			status("Finding the reward altar", countText(count), 0.9)
			if
				not waitUntil(function()
					return App.player:GetAttribute("HalloweenBadgeEligible") == true
				end, 15, generation)
			then
				return false,
					active(generation) and "75 candies collected. Waiting for the altar to unlock." or "Stopped"
			end
			local altar = waitUntil(function()
				local event = workspace:FindFirstChild("TheHollowEvent")
				local part = event and event:FindFirstChild("ClickPart", true)
				return part and part:IsA("BasePart") and part
			end, 30, generation)
			if not altar then
				return false, active(generation) and "The reward altar hasn't loaded yet" or "Stopped"
			end
			if not waitUntil(cameraReady, 15, generation) then
				return false, active(generation) and "Waiting for the current game animation to finish" or "Stopped"
			end
			local moved, why = approach(altar.Position, generation, altar.Parent)
			if not moved then
				return false, why
			end
			local _, root = character()
			if not active(generation) or not root or not altar:IsDescendantOf(workspace) then
				return false, "Stopped or the altar changed"
			end
			if (root.Position - altar.Position).Magnitude > 24 then
				return false, "Could not reach the reward altar safely"
			end
			if App.player:GetAttribute("HalloweenBadgeEligible") ~= true then
				continue
			end
			session.claiming = true
			local sent, err = fire(remotes.badge.RequestClaim)
			if not sent then
				return false, "Altar request failed: " .. tostring(err)
			end
			status("Claiming the Hollow badge", "Waiting for the finale and your badge", 0.95)
			for attempt = 1, 25 do
				if not active(generation) then
					return false, "Stopped"
				end
				if attempt % 2 == 1 and verify(current, true) == true then
					return true, "HUNTED Hollow badge earned"
				end
				if not pause(2, generation) then
					return false, "Stopped"
				end
			end
			return false,
				session.claimStarted and "The finale started, but the badge hasn't arrived yet"
					or "The altar hasn't given the reward yet. Check it in the game."
		end
		if not remotes.doors then
			return false, "You need more candy. Press Start to collect it."
		end
		status("Collecting trick-or-treat candy", countText(count), count / 75)
		if not cameraReady() then
			if not pause(0.25, generation) then
				return false, "Stopped"
			end
			if os.clock() - idleSince > 90 then
				return false, "Waiting for the animation to finish so you can move"
			end
			continue
		end
		local door, position = huntedDoor(session)
		if not door then
			status("Waiting for trick-or-treat doors", countText(count) .. "  |  Looking for more doors", count / 75)
			probeHuntedDoors(session, generation)
			if os.clock() - idleSince > 90 then
				return false, "No new doors found. Enter an event portal, then press Start."
			end
			if not pause(0.5, generation) then
				return false, "Stopped"
			end
			continue
		end
		local moved, why = approach(position, generation, door)
		if not active(generation) then
			return false, "Stopped"
		end
		local _, root = character()
		local collider = door.Parent and door:FindFirstChild("ClickCollider", true)
		if
			not moved
			or not root
			or not collider
			or not collider:IsA("BasePart")
			or not door:IsDescendantOf(workspace)
		then
			local key = huntedPointKey(position)
			local collider = door.Parent and door:FindFirstChild("ClickCollider", true)
			if collider and collider:IsA("BasePart") then
				key = huntedPointKey(collider.Position)
			end
			local prior = session.blocked[key]
			local attempts = (prior and prior.attempts or 0) + 1
			session.blocked[key] = { attempts = attempts, untilAt = os.clock() + (attempts >= 3 and 90 or 8) }
			log("HUNTED door: " .. tostring(why or "Door or character changed"))
			status("Looking for more doors", "Couldn't reach that door. Trying another.", count / 75)
			pause(0.5, generation)
			continue
		end
		local updatedCount = huntedProgress(controller)
		if
			updatedCount == nil
			or updatedCount >= 75
			or App.player:GetAttribute("HalloweenBadgeEligible") == true
			or not cameraReady()
		then
			continue
		end
		if (root.Position - collider.Position).Magnitude > timing("CLICK_MAX_DISTANCE", 8) then
			session.blocked[huntedPointKey(collider.Position)] = { attempts = 1, untilAt = os.clock() + 8 }
			pause(0.5, generation)
			continue
		end
		local detector = collider:FindFirstChildOfClass("ClickDetector")
		if not detector or detector.MaxActivationDistance <= 0 then
			if detector then
				session.visited[huntedPointKey(collider.Position)] = collider.Position
			end
			continue
		end
		local camera = workspace.CurrentCamera
		session.interaction = {
			model = App.player.Character,
			root = root,
			anchored = root.Anchored,
			camera = camera,
			cameraType = camera.CameraType,
			subject = camera.CameraSubject,
			frame = camera.CFrame,
			script = huntedEventScript(false),
		}
		session.door, session.result, session.resultAt, session.closedAt, session.denied = door, nil, nil, nil, false
		session.used[door] = true
		session.visited[huntedPointKey(collider.Position)] = collider.Position
		detector.MaxActivationDistance = 0
		local sent, err = fire(remotes.doors.RequestInteract, door)
		if not sent then
			return false, "Door interaction failed: " .. tostring(err)
		end
		local responded = waitUntil(function()
			return session.result or session.denied
		end, 8, generation)
		if not active(generation) then
			return false, "Stopped"
		end
		if not responded or session.denied then
			failures += 1
			recoverHunted(session, false)
			session.door = nil
			if failures >= 3 then
				return false, "Three doors didn't respond. Try Start again."
			end
			continue
		end
		status(
			session.result == "Fake" and "Collecting candy" or "Trick door",
			countText(count) .. "  |  Waiting for the door sequence",
			count / 75
		)
		local knock = door:FindFirstChild("KnochDoorSFX", true)
		local knockTime = knock and knock:IsA("Sound") and math.clamp(knock.TimeLength, 0, 15) or 0
		local closingTime = timing("DOOR_CLOSE_TIME", 0.6) + timing("FINAL_WAIT", 1) + 1
		local realTime = timing("KNOCK_DELAY", 0.4)
			+ knockTime
			+ timing("WAIT_BEFORE_OPEN", 1)
			+ timing("DOOR_OPEN_TIME", 0.25)
			+ timing("REAL_JUMPSCARE_TO_CLOSE", 0.8)
			+ closingTime
		local finished = waitUntil(function()
			local closing = session.result == "Real" and session.resultAt + realTime
				or (session.closedAt and session.closedAt + closingTime)
			return closing and os.clock() >= closing and cameraReady()
		end, session.result == "Fake" and 20 or 30, generation)
		if not active(generation) then
			return false, "Stopped"
		end
		if not finished then
			recoverHunted(session, false)
			return false, "That door got stuck. Controls reset so you can move again."
		end
		if session.result == "Fake" then
			local credited = waitUntil(function()
				local updated = huntedProgress(controller)
				return (updated and updated > count) or App.player:GetAttribute("HalloweenBadgeEligible") == true
			end, 10, generation)
			if not credited then
				return false, active(generation) and "The animation finished, but no candy was added" or "Stopped"
			end
		end
		session.interaction = nil
		session.door, failures, idleSince = nil, 0, os.clock()
	end
	return false, active(generation) and "Stopped after an hour. Your candy is saved." or "Stopped"
end

-- arcade
local function arcadeReady(match, owned)
	if
		not match.Parent
		or match:GetAttribute("Phase") ~= "Live"
		or match:GetAttribute("MatchType") ~= "public"
		or match:GetAttribute("EventLive") ~= true
		or match:GetAttribute("Finale")
		or match:GetAttribute("Cutscene")
		or App.player:GetAttribute("Alive") ~= true
		or App.player:GetAttribute("InCutscene")
		or App.player:GetAttribute("DeathScreen")
		or App.player:GetAttribute("ResultsCamera")
	then
		return nil
	end
	local model, root, humanoid = character()
	if
		model
		and not (
			(root.Anchored and not (owned and owned.model == model and owned.prompt ~= nil))
			or humanoid.PlatformStand
			or model:GetAttribute("Ragdolled")
		)
	then
		return model, root
	end
	return nil
end

local function releaseArcadePrompt(session)
	local hold = session.hold
	session.hold = nil
	if not hold then
		return
	end
	pcall(function()
		RunService:UnbindFromRenderStep(hold.binding)
	end)
	if hold.began then
		hold.began = nil
		pcall(hold.prompt.InputHoldEnd, hold.prompt)
	end
	local camera = workspace.CurrentCamera
	if
		camera ~= nil
		and camera == hold.camera
		and camera.CameraType == hold.cameraType
		and camera.CFrame == hold.aim
		and character() == hold.model
		and hold.cameraEpoch == App.cameraEpoch
	then
		pcall(function()
			camera.CFrame = hold.frame
		end)
	end
end

local function arcadeTarget(session, carrying)
	local model, root = arcadeReady(session.match)
	if not root then
		return nil
	end
	local pinned = session.target
	if pinned and session.targetModel == model and pinned.generator == carrying then
		local object, body, prompt = pinned.object, pinned.body, pinned.prompt
		if
			object:IsDescendantOf(workspace)
			and body:IsDescendantOf(workspace)
			and prompt.Parent == body
			and (session.blocked[object] or 0) <= os.clock()
			and prompt:GetAttribute("Blocked") ~= true
			and (
				carrying and object:GetAttribute("GenState") == "live"
				or not carrying
					and object:GetAttribute("Kind") == "payload"
					and object:GetAttribute("Flying") ~= true
					and object:GetAttribute("Thrown") ~= true
			)
		then
			return pinned
		end
	end
	session.target, session.targetModel = nil, nil
	local items = workspace:FindFirstChild("ArcadeItems")
	local candidates = carrying and Collection:GetTagged("Generator") or (items and items:GetChildren() or {})
	local best, distance
	for _, object in ipairs(candidates) do
		if not object:IsDescendantOf(workspace) or (session.blocked[object] or 0) > os.clock() then
			continue
		end
		local body = object:IsA("BasePart") and object or object:FindFirstChild("GeneratorVolume")
		if not body or not body:IsA("BasePart") then
			continue
		end
		if carrying then
			if object:GetAttribute("GenState") ~= "live" then
				continue
			end
		elseif
			object:GetAttribute("Kind") ~= "payload"
			or object:GetAttribute("Flying") == true
			or object:GetAttribute("Thrown") == true
		then
			continue
		end
		local prompt = body:FindFirstChildOfClass("ProximityPrompt")
		if not prompt or prompt:GetAttribute("Blocked") == true or (not carrying and not prompt.Enabled) then
			continue
		end
		local length = (body.Position - root.Position).Magnitude
		if not distance or length < distance then
			best, distance = { object = object, body = body, prompt = prompt, generator = carrying }, length
		end
	end
	session.target, session.targetModel = best, best and model
	return best
end

local function useArcadePrompt(session, target, generation)
	releaseArcadePrompt(session)
	local model, root = arcadeReady(session.match)
	local body, prompt = target.body, target.prompt
	if not model or not body:IsDescendantOf(workspace) or prompt.Parent ~= body then
		return false, "Interaction changed"
	end
	local count = tonumber(App.player:GetAttribute("EventCans")) or 0
	local function carrying()
		if App.arcadeHasGas then
			return App.arcadeHasGas()
		end
		return App.player:GetAttribute("HandItem") == "PAYLOAD" or App.player:GetAttribute("BackItem") == "PAYLOAD"
	end
	local function confirmed()
		return target.generator and (tonumber(App.player:GetAttribute("EventCans")) or 0) > count
			or not target.generator and carrying()
	end
	local function live()
		return active(generation) and arcadeReady(session.match, session.hold) == model
	end
	local points = {}
	local x = target.generator and body.Size.X / 2 + 2 or 2.5
	local z = target.generator and body.Size.Z / 2 + 2 or 2.5
	for _, offset in ipairs({ Vector3.new(x, 0, 0), Vector3.new(-x, 0, 0), Vector3.new(0, 0, z), Vector3.new(0, 0, -z) }) do
		local point = body.CFrame:PointToWorldSpace(offset)
		if (point - body.Position).Magnitude < prompt.MaxActivationDistance then
			table.insert(points, point)
		end
	end
	table.sort(points, function(a, b)
		return (a - root.Position).Magnitude < (b - root.Position).Magnitude
	end)
	local function valid()
		return live()
			and body:IsDescendantOf(workspace)
			and prompt.Parent == body
			and (not target.generator or target.object:GetAttribute("GenState") == "live")
	end
	local moved, reason = false, "No safe landing within prompt range"
	if confirmed() then
		session.target, session.targetModel = nil, nil
		return true
	end
	if (root.Position - body.Position).Magnitude <= math.max(1, prompt.MaxActivationDistance - 1) then
		moved = true
	end
	for _, point in ipairs(moved and {} or points) do
		if not valid() then
			break
		end
		moved, reason = approach(point, generation, target.object, false, valid)
		if moved then
			break
		end
	end
	if not moved or not valid() then
		return false, reason or "Checking the prompt again"
	end
	local _, currentRoot = arcadeReady(session.match)
	if (currentRoot.Position - body.Position).Magnitude > prompt.MaxActivationDistance then
		return false, "Prompt is out of reach"
	end
	local camera = workspace.CurrentCamera
	local hold = {
		prompt = prompt,
		camera = camera,
		cameraType = camera and camera.CameraType,
		frame = camera and camera.CFrame,
		model = model,
		binding = "HollowArcadePrompt",
		cameraEpoch = App.cameraEpoch,
	}
	session.hold = hold
	local function aim()
		if
			session.hold == hold
			and live()
			and body:IsDescendantOf(workspace)
			and workspace.CurrentCamera == camera
			and camera
			and camera.CameraType ~= Enum.CameraType.Scriptable
			and not App.cameraBusy
		then
			if hold.cameraEpoch ~= App.cameraEpoch then
				hold.frame, hold.cameraEpoch = camera.CFrame, App.cameraEpoch
			end
			local position = camera.CFrame.Position
			if (body.Position - position).Magnitude > 0.1 then
				hold.aim = CFrame.lookAt(position, body.Position)
				camera.CFrame = hold.aim
			end
		end
	end
	pcall(function()
		RunService:BindToRenderStep(hold.binding, Enum.RenderPriority.Camera.Value + 1, aim)
	end)
	local function step()
		aim()
		return pause(0.05, generation)
	end
	local function endInput()
		if hold.began then
			hold.began = nil
			pcall(prompt.InputHoldEnd, prompt)
		end
	end
	local function finish(ok, why, retry)
		releaseArcadePrompt(session)
		if ok or not retry then
			session.target, session.targetModel = nil, nil
		end
		return ok, why, retry
	end
	if target.generator and not camera then
		return finish(false, "Waiting for the camera", true)
	end
	local duration = tonumber(prompt.HoldDuration)
	if not duration or duration ~= duration or duration < 0 or duration > 30 then
		return finish(false, "The prompt's hold time is not ready", true)
	end
	local deadline = os.clock() + math.max(30, duration * 3 + 24)
	for attempt = 1, 3 do
		local readyAt = math.min(deadline, os.clock() + 5)
		while live() and not confirmed() and os.clock() < readyAt do
			if
				valid()
				and prompt.Enabled
				and prompt:GetAttribute("Blocked") ~= true
				and (not target.generator or carrying())
			then
				break
			end
			if not step() then
				break
			end
		end
		if confirmed() and live() then
			return finish(true, target.generator and "Gas delivered" or "Got the gas can")
		end
		if not live() then
			return finish(false, "Interaction interrupted")
		end
		if not valid() or target.generator and not carrying() then
			break
		end
		if not prompt.Enabled or prompt:GetAttribute("Blocked") == true then
			target.waits = (target.waits or 0) + 1
			return finish(false, "Waiting for this interaction prompt", target.waits < 3)
		end
		target.waits = 0
		local endsAt = os.clock() + duration + 0.15
		local began, why
		if attempt == 1 or type(fireproximityprompt) ~= "function" then
			hold.began = true
			began, why = pcall(prompt.InputHoldBegin, prompt)
		end
		if (not began or attempt > 1) and valid() and type(fireproximityprompt) == "function" then
			endInput()
			began, why = call(prompt, function()
				if live() and valid() and prompt.Enabled then
					return fireproximityprompt(prompt, duration)
				end
				return false
			end, duration + 2, generation)
			began = began and why ~= false
		end
		if not began then
			return finish(false, tostring(why or "The prompt rejected input"), true)
		end
		local disabledAt
		while live() and not confirmed() and os.clock() < endsAt do
			if not valid() or target.generator and not carrying() then
				break
			end
			if not prompt.Enabled or prompt:GetAttribute("Blocked") == true then
				disabledAt = disabledAt or os.clock()
				if os.clock() - disabledAt > 0.25 then
					break
				end
			else
				disabledAt = nil
			end
			if not step() then
				break
			end
		end
		endInput()
		local interruptedHold = os.clock() < endsAt and valid() and (not target.generator or carrying())
		local acknowledgeAt = math.min(deadline, os.clock() + (interruptedHold and 0.35 or 8))
		local inventoryChanged
		while live() and not confirmed() and os.clock() < acknowledgeAt do
			if
				not inventoryChanged
				and (target.generator and not carrying() or not target.generator and not body:IsDescendantOf(workspace))
			then
				inventoryChanged = true
				acknowledgeAt = math.min(deadline, math.max(acknowledgeAt, os.clock() + 8))
			end
			if not step() then
				break
			end
		end
		if confirmed() and live() then
			return finish(true, target.generator and "Gas delivered" or "Got the gas can")
		end
		if not live() then
			return finish(false, "Interaction interrupted")
		end
		if not valid() or target.generator and not carrying() or os.clock() >= deadline then
			break
		end
		status(
			"Trying the prompt again",
			"Staying at the same " .. (target.generator and "generator" or "gas can"),
			count / 3
		)
	end
	return finish(
		false,
		target.generator and "The generator hasn't credited this gas delivery"
			or "The gas can hasn't appeared in your inventory"
	)
end

local function probeArcade(session, generation)
	if os.clock() < (session.nextProbe or 0) or not arcadeReady(session.match) then
		return
	end
	session.nextProbe = os.clock() + 4
	local markers = getPath(workspace, "Maze", "Markers", "PayloadSpawns")
	local points = {}
	for _, marker in ipairs(markers and markers:GetChildren() or {}) do
		if marker:IsA("BasePart") then
			table.insert(points, marker.Position)
		end
	end
	for _, area in ipairs(current.searchAreas) do
		table.insert(points, Vector3.new(area[1], area[2], area[3]))
	end
	if #points == 0 then
		return
	end
	session.probe = (session.probe or 0) % #points + 1
	local point = points[session.probe]
	call("Arcade streaming", function()
		App.player:RequestStreamAroundAsync(point, 2)
	end, 3, generation)
end

local function watchArcadeTravel(session)
	local connection = App.player.OnTeleport:Connect(function(state)
		if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
			session.traveling = true
		elseif state == Enum.TeleportState.Failed then
			session.failed = true
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
		releaseArcadePrompt(session)
	end)
end

local function queueArcade(session, generation)
	status("Arcade Quick Play", "Waiting for lobby matchmaking", 0.05)
	local object = waitUntil(function()
		return getPath(App.player, "PlayerScripts", "Lobby", "PartyClient")
	end, 30, generation)
	local party, reason = module(object, generation)
	if
		not party
		or type(party.create) ~= "function"
		or type(party.setMatch) ~= "function"
		or type(party.play) ~= "function"
		or type(party.cancel) ~= "function"
		or type(party.leave) ~= "function"
	then
		return false, reason or "Arcade party controls are not ready"
	end
	if not waitUntil(function()
		return party.synced
	end, 15, generation) then
		return false, "Your party hasn't loaded yet. Try Start again."
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local state = party.state
	if state and (state.mode ~= "arcade" or state.leaderId ~= App.player.UserId or #state.members > 1) then
		return false, "Have your party leader select Arcade Quick Play first"
	end
	local created, sent = false, false
	table.insert(App.cleanups, function()
		local now = party.state
		if
			not session.traveling
			and now
			and state
			and now.id == state.id
			and not now.launching
			and now.leaderId == App.player.UserId
			and #now.members == 1
		then
			if sent then
				pcall(party.cancel)
			end
			if created and now.leaderId == App.player.UserId and #now.members == 1 then
				pcall(party.leave)
			end
		end
	end)
	if not state then
		party.create("private", "arcade")
		state = waitUntil(function()
			return party.state
		end, 8, generation)
		created = state and state.mode == "arcade" and state.leaderId == App.player.UserId and #state.members == 1
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if not state or state.mode ~= "arcade" or state.leaderId ~= App.player.UserId or #state.members ~= 1 then
		return false, "Select Arcade Quick Play in the game, then press Start"
	end
	if state.privateServer then
		return false, "The event requires Quick Play from a public lobby"
	end
	if state.match ~= "public" then
		if state.launching or state.searchingSince then
			return false, "Cancel the private match in the game before starting Quick Play"
		end
		party.setMatch("public")
		if
			not waitUntil(function()
				return party.state and party.state.id == state.id and party.state.match == "public"
			end, 6, generation)
		then
			return false, "Quick Play selection was not confirmed"
		end
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local continued = prepareTravel(current.eventPlace, true)
	state = party.state
	if
		not state
		or state.mode ~= "arcade"
		or state.match ~= "public"
		or state.leaderId ~= App.player.UserId
		or state.privateServer
		or #state.members ~= 1
	then
		return false, "Party changed before matchmaking"
	end
	if not state.searchingSince and not state.launching then
		sent = true
		party.play()
	end
	status("Finding an Arcade match", "Public Quick Play  |  Stop cancels this search", 0.1)
	waitUntil(function()
		return session.traveling or session.failed or not party.state or party.state.id ~= state.id
	end, 120, generation)
	if session.traveling then
		App.traveling = true
		return nil,
			continued and "Entering Arcade. I'll carry on when we arrive."
				or "Entering Arcade. Run the script again when you arrive."
	end
	return false,
		session.failed and "Couldn't join Arcade. Try Start again." or "Quick Play didn't load. Try Start again."
end

local function runArcade(generation)
	if verify(current, true) == true then
		return true, "Oil Run badge earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = { blocked = setmetatable({}, { __mode = "k" }) }
	watchArcadeTravel(session)
	if game.PlaceId ~= current.eventPlace then
		return queueArcade(session, generation)
	end
	status("Loading Arcade", "Loading the match and your gas deliveries", 0)
	local match = waitUntil(function()
		local value = Storage:FindFirstChild("ArcadeMatch")
		return value and type(App.player:GetAttribute("EventCans")) == "number" and value
	end, 45, generation)
	if not match then
		return false, "Arcade isn't ready yet. Try Start again."
	end
	session.match = match
	local began = os.clock()
	while active(generation) and os.clock() - began < 1200 do
		local count = math.max(0, math.floor(App.player:GetAttribute("EventCans") or 0))
		if count >= 3 then
			status("Checking Oil Run", "Three deliveries done! Waiting for the badge.", 0.95)
			for _ = 1, 6 do
				if not active(generation) then
					return false, "Stopped"
				end
				if verify(current, true) == true then
					return true, "Oil Run badge earned"
				end
				if not pause(2, generation) then
					return false, "Stopped"
				end
			end
			return false, "Three deliveries done, but Oil Run hasn't arrived yet"
		end
		if match:GetAttribute("MatchType") == "private" then
			return false, "Private matches don't count. Join public Quick Play."
		end
		if match:GetAttribute("EventEnded") == true then
			return false, "The Hollow event has ended in this server"
		end
		local phase = match:GetAttribute("Phase")
		local model = arcadeReady(match)
		if phase == "Results" or (phase == "Live" and App.player:GetAttribute("Alive") == false) then
			releaseArcadePrompt(session)
			if not (match:GetAttribute("Cutscene") or App.player:GetAttribute("DeathScreen")) then
				local continued = prepareTravel(current.place, true)
				local sent, why = fire(getPath(Storage, "ArcadeRemotes", "ResultsLeave"))
				if not sent then
					return false, "Could not return to the lobby: " .. tostring(why)
				end
				status("Returning to Quick Play", string.format("%d / 3 deliveries saved", count), count / 3)
				waitUntil(function()
					return session.traveling or session.failed
				end, 15, generation)
				if session.traveling then
					App.traveling = true
					return nil,
						continued and "Heading back to queue for Quick Play"
							or "Heading back to the lobby. Run the script again there."
				end
				return false, "Couldn't return to the lobby. Use Back to Lobby in the game."
			end
		elseif model then
			local carrying
			if App.arcadeHasGas then
				carrying = App.arcadeHasGas()
			else
				carrying = App.player:GetAttribute("HandItem") == "PAYLOAD"
					or App.player:GetAttribute("BackItem") == "PAYLOAD"
			end
			status(
				carrying and "Refueling a generator" or "Finding a gas can",
				string.format("%d / 3 deliveries saved", count),
				count / 3
			)
			local target = arcadeTarget(session, carrying)
			if target then
				local used, why, retry = useArcadePrompt(session, target, generation)
				if not used and why then
					status("Trying the prompt again", why, count / 3)
				end
				if not used and not retry then
					session.blocked[target.object] = os.clock() + 5
				end
			else
				status(
					carrying and "Finding an unfinished generator" or "Waiting for gas cans",
					"Looking for cans and generators",
					count / 3
				)
				probeArcade(session, generation)
			end
		else
			status("Waiting for Arcade", tostring(phase or "Loading") .. "  |  Waiting until you can move", count / 3)
		end
		if not pause(0.35, generation) then
			return false, "Stopped"
		end
	end
	return false, "Arcade stopped. Your deliveries are saved."
end

local function graveReady()
	for _, flag in ipairs({
		"CutsceneActive",
		"NeedleInputLocked",
		"DialogueActive",
		"NeedleRoundComplete",
		"BossRagdolled",
		"BossRagdollRecovering",
		"BossKnockdownCamera",
		"PumpkinGrabbed",
		"PumpkinSnared",
		"PumpkinPulled",
		"PumpkinEscape",
		"UpgradeBookOpen",
		"ShopViewOpen",
		"HintViewerOpen",
	}) do
		if App.player:GetAttribute(flag) == true then
			return nil
		end
	end
	if (tonumber(App.player:GetAttribute("BossStunnedUntil")) or 0) > workspace:GetServerTimeNow() then
		return nil
	end
	local model, root, humanoid = character()
	if model and not (root.Anchored or humanoid.PlatformStand or model:GetAttribute("Ragdolled")) then
		return model, root
	end
	return nil
end

local function stopGraveVacuum(session)
	if session.vacuum then
		session.vacuum = false
		fire(getPath(Storage, "NeedleHaystack", "VacuumAction"), "Stop")
	end
end

local function graveEquip(session, slot, generation)
	if not active(generation) or not graveReady() then
		return false
	end
	if session.slots.getEquipped() ~= slot then
		stopGraveVacuum(session)
		session.slots.setEquipped(slot)
		session.lastSlot = slot
		if not pause(0.12, generation) then
			return false
		end
	end
	return active(generation) and graveReady() ~= nil and session.slots.getEquipped() == slot
end

-- graveyard movement
local function graveTween(model, root, humanoid, target, generation, valid)
	if not active(generation) or not valid() then
		return false
	end
	local distance = (root.Position - target.Position).Magnitude
	if distance < 0.5 then
		return true
	end
	local duration = math.max(0.15, distance / 34)
	local tween = game:GetService("TweenService")
		:Create(root, TweenInfo.new(duration, Enum.EasingStyle.Linear), { CFrame = target })
	local parts, done, released = {}, false, false
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("BasePart") then
			parts[part] = part.CanCollide
			part.CanCollide = false
		end
	end
	local completed = tween.Completed:Connect(function(state)
		done = state == Enum.PlaybackState.Completed
	end)
	local cleanups = App.cleanups
	local function release()
		if released then
			return
		end
		released = true
		pcall(tween.Cancel, tween)
		completed:Disconnect()
		for part, value in pairs(parts) do
			if part.Parent and part.CanCollide == false then
				part.CanCollide = value
			end
		end
	end
	table.insert(cleanups, release)
	local ok = pcall(function()
		tween:Play()
		local deadline = os.clock() + duration + 2
		while active(generation) and valid() and App.player.Character == model and not done and os.clock() < deadline do
			humanoid:Move(Vector3.zero, false)
			root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
			if not pause(0.03, generation) then
				break
			end
		end
	end)
	release()
	if App.cleanups == cleanups then
		local index = table.find(cleanups, release)
		if index then
			table.remove(cleanups, index)
		end
	end
	return ok and done and active(generation) and valid() and (root.Position - target.Position).Magnitude < 1.5
end

local function graveMove(object, position, reach, generation, predicate)
	local model, root = graveReady()
	local function valid()
		return active(generation)
			and graveReady() == model
			and object:IsDescendantOf(workspace)
			and (not predicate or predicate())
	end
	if not model or not valid() then
		return false
	end
	if (position - root.Position).Magnitude <= reach then
		return true
	end
	local moved = approach(position, generation, object, false, valid, {
		move = function(live, nowRoot, humanoid, target)
			return graveTween(live, nowRoot, humanoid, target, generation, valid)
		end,
	})
	local currentModel, currentRoot = graveReady()
	return moved and valid() and currentModel == model and (position - currentRoot.Position).Magnitude <= reach
end

local function graveLevel(config, id, override)
	local track = config.UPGRADE_TRACKS and config.UPGRADE_TRACKS[id]
	if not track or type(track.Levels) ~= "table" then
		return {}, nil
	end
	local level = override and override[id] or tonumber(App.player:GetAttribute("HayUpgrade" .. id)) or 1
	if level % 1 ~= 0 or level < 1 or level > #track.Levels then
		return {}, nil
	end
	return track.Levels[level], level
end

local function graveToolRates(session, override, item)
	local config = session.config
	local function level(id)
		return graveLevel(config, id, override)
	end
	local currentGrab = graveLevel(config, "Grab")
	local grab = level("Grab")
	local count = math.max(
		1,
		(tonumber(App.player:GetAttribute("HayGrabCount")) or currentGrab.Count or 1)
			+ (grab.Count or 1)
			- (currentGrab.Count or 1)
	)
	local speed = level("Speed")
	local currentSpeed = graveLevel(config, "Speed")
	local delay = (tonumber(App.player:GetAttribute("HayPickCooldown")) or config.PICK_COOLDOWN or 0.55)
		* (speed.Cooldown or 0.55)
		/ (currentSpeed.Cooldown or 0.55)
	local hand = count / math.max(0.1, delay)
	local fork, vacuum = 0, 0
	local ownsFork = item == "Pitchfork" or App.player:GetAttribute("PitchforkOwned") == true
	if ownsFork then
		local sweep, cooling = level("Pitchfork"), level("PitchforkCooldown")
		local currentCooling = graveLevel(config, "PitchforkCooldown")
		local cooldown = (tonumber(App.player:GetAttribute("PitchforkCooldown")) or config.PITCHFORK_COOLDOWN or 0.85)
			* (cooling.Cooldown or 0.85)
			/ (currentCooling.Cooldown or 0.85)
		fork = (sweep.Scoop or 12) / math.max(0.1, cooldown)
	end
	if item == "Vacuum" or App.player:GetAttribute("VacuumOwned") == true then
		local power = level("VacuumPower")
		vacuum = (power.Count or config.VACUUM_GRAB_COUNT or 5) / math.max(0.08, config.VACUUM_TICK or 0.16)
	end
	return hand, fork, vacuum
end

local function graveProductivity(session, override, item)
	local config = session.config
	local hand, fork, vacuum = graveToolRates(session, override, item)
	local base = math.max(hand, fork)
	if vacuum > base then
		local runtime = graveLevel(config, "VacuumRuntime", override)
		local cooling = graveLevel(config, "VacuumCooling", override)
		local currentCooling = graveLevel(config, "VacuumCooling")
		local coolTime = (
			tonumber(App.player:GetAttribute("VacuumCoolTime"))
			or currentCooling.Cooldown
			or config.VACUUM_COOL_TIME
			or 20
		)
			* (cooling.Cooldown or 20)
			/ (currentCooling.Cooldown or 20)
		local duration = runtime.Duration or config.VACUUM_HEAT_TIME or 30
		base = (vacuum * duration + base * coolTime) / math.max(1, duration + coolTime)
	end
	if App.player:GetAttribute("InfiniteBagOwned") ~= true then
		local current = graveLevel(config, "Capacity")
		local nextLevel = graveLevel(config, "Capacity", override)
		local capacity = math.max(
			1,
			(tonumber(App.player:GetAttribute("HayCapacity")) or current.Capacity or 25)
				+ (nextLevel.Capacity or 25)
				- (current.Capacity or 25)
		)
		base = 1 / (1 / math.max(0.1, base) + 3 / capacity)
	end
	if App.player:GetAttribute("DroneOwned") == true then
		local speed = graveLevel(config, "DroneSpeed", override)
		local grab = graveLevel(config, "DroneGrab", override)
		local bag = graveLevel(config, "DroneCapacity", override)
		local capacity, count = bag.Capacity or 36, grab.Count or 6
		local travel = 60 / math.max(1, speed.FlightSpeed or config.DRONE_FLIGHT_SPEED or 12.5)
		base += capacity / (math.ceil(capacity / count) * (config.DRONE_HARVEST_PAUSE or 0.7) + travel + (config.DRONE_SELL_PAUSE or 1.15))
	end
	return base
end

local function graveCashItem(id)
	local paths = {
		Pitchfork = { "BarnShop", "ToolBoard", "PitchforkTemplate" },
		Vacuum = { "BarnShop", "ToolBoard2", "VacuumTemplate" },
	}
	local path = paths[id]
	local object = path and getPath(workspace, table.unpack(path))
	if
		not object
		or object:GetAttribute("ShopItemId") ~= id
		or object:GetAttribute("ShopBalanceCurrency") ~= "Cash"
	then
		return nil
	end
	for _, option in ipairs({ "A", "B", "C" }) do
		local currency = object:GetAttribute("ShopCurrency" .. option)
		local value = object:GetAttribute("ShopPrice" .. option)
		if currency ~= "Coins" and currency ~= "Cash" then
			continue
		end
		local price = type(value) == "number" and value
			or (type(value) == "string" and tonumber(value:match("^%$(%d+%.?%d*)$")))
		if price and price == price and price > 0 and price <= 1000000 then
			return object, price
		end
	end
	return nil
end

local function graveCashPlan(session, cash)
	if type(cash) ~= "number" or cash ~= cash or cash < 0 or cash == math.huge then
		return nil
	end
	local config, shop = session.config, session.shop
	local base = graveProductivity(session)
	local remaining = tonumber(session.hay:GetAttribute("RemainingHay"))
	local total = tonumber(session.hay:GetAttribute("TotalHay")) or config.TOTAL_HAY
	local candles = workspace:FindFirstChild("HayCandles")
	local hidden, count, lastReveal = 0, 0, 0
	for _, candle in ipairs(candles and candles:GetChildren() or {}) do
		if candle:GetAttribute("HayCandle") == true then
			count += 1
			if candle:GetAttribute("Revealed") ~= true then
				hidden += 1
			end
			local at = tonumber(candle:GetAttribute("RevealAt"))
			if at and at >= 0 and at <= 1 then
				lastReveal = math.max(lastReveal, at)
			end
		end
	end
	if count >= 4 and hidden == 0 then
		return nil
	end
	local untilRitual = lastReveal > 0 and remaining and total and math.max(0, remaining - total * (1 - lastReveal))
	if untilRitual and untilRitual < 100 then
		return nil
	end
	local best
	local function consider(value, rate)
		if value.cost > cash or shop.blocked[value.key] or value.cost <= 0 then
			return
		end
		local gain = rate - base
		if gain <= 0.0001 then
			return
		end
		local score = gain / value.cost
		if
			untilRitual
			and untilRitual / math.max(base, 0.1) < value.cost / math.max(gain * (config.HAY_VALUE or 0.01), 0.001)
		then
			return
		end
		if not best or score > best.score or (score == best.score and value.key < best.key) then
			value.score = score
			best = value
		end
	end
	local requirements = {
		Capacity = App.player:GetAttribute("InfiniteBagOwned") ~= true,
		Grab = true,
		Speed = true,
		Pitchfork = App.player:GetAttribute("PitchforkOwned") == true,
		PitchforkCooldown = App.player:GetAttribute("PitchforkOwned") == true,
		VacuumPower = App.player:GetAttribute("VacuumOwned") == true,
		VacuumRuntime = App.player:GetAttribute("VacuumOwned") == true,
		VacuumCooling = App.player:GetAttribute("VacuumOwned") == true,
		DroneSpeed = App.player:GetAttribute("DroneOwned") == true,
		DroneGrab = App.player:GetAttribute("DroneOwned") == true,
		DroneCapacity = App.player:GetAttribute("DroneOwned") == true,
	}
	for _, id in ipairs({
		"Grab",
		"Speed",
		"Capacity",
		"Pitchfork",
		"PitchforkCooldown",
		"VacuumPower",
		"VacuumCooling",
		"VacuumRuntime",
		"DroneGrab",
		"DroneCapacity",
		"DroneSpeed",
	}) do
		if not requirements[id] then
			continue
		end
		local attribute = "HayUpgrade" .. id
		if type(App.player:GetAttribute(attribute)) ~= "number" then
			continue
		end
		local _, level = graveLevel(config, id)
		local track = config.UPGRADE_TRACKS and config.UPGRADE_TRACKS[id]
		local nextLevel = track and level and track.Levels[level + 1]
		if not nextLevel or type(nextLevel.Cost) ~= "number" then
			continue
		end
		local multiplier = tonumber(App.player:GetAttribute("UpgradeCostMultiplier")) or 1
		if id:sub(1, 9) == "Pitchfork" then
			multiplier *= tonumber(App.player:GetAttribute("PitchforkUpgradeCostMultiplier")) or 1
		end
		local cost = math.round(nextLevel.Cost * multiplier * 100) / 100
		if cost ~= cost or cost <= 0 or cost == math.huge then
			continue
		end
		consider({
			id = id,
			key = attribute .. ":" .. tostring(level + 1),
			attribute = attribute,
			before = level,
			after = level + 1,
			cost = cost,
			name = track.DisplayName or id,
		}, graveProductivity(session, { [id] = level + 1 }))
	end
	for _, id in ipairs({ "Pitchfork", "Vacuum" }) do
		local attribute = id .. "Owned"
		if App.player:GetAttribute(attribute) ~= false then
			continue
		end
		local object, cost = graveCashItem(id)
		if object then
			consider({
				id = id,
				key = "Item:" .. id,
				attribute = attribute,
				before = false,
				after = true,
				cost = cost,
				name = id,
				object = object,
			}, graveProductivity(session, nil, id))
		end
	end
	return best
end

local function graveShopMemory()
	local key = tostring(game.PlaceId) .. ":" .. tostring(game.JobId) .. ":" .. tostring(App.player.UserId)
	local memory = env.__HOLLOW_GRAVE_SHOP
	if type(memory) ~= "table" or memory.key ~= key then
		memory = { key = key, blocked = {}, spent = 0 }
		env.__HOLLOW_GRAVE_SHOP = memory
	end
	App.graveSpent = memory.spent
	App.graveShopState = memory
	return memory
end

local function graveShopping(session, generation)
	local shop = session.shop
	local wallet = getPath(App.player, "leaderstats", "Cash")
	local cash = wallet and tonumber(wallet.Value)
	if shop.pending then
		local order = shop.pending
		if App.player:GetAttribute(order.attribute) == order.after then
			shop.spent += order.cost
			App.graveSpent = shop.spent
			shop.pending, shop.nextCheck = nil, os.clock() + 1
			log(string.format("Cash auto-buy: %s ($%.2f)", order.name, order.cost))
			refresh()
		elseif os.clock() - order.at >= 10 then
			shop.disabled, shop.pending = true, nil
			shop.blocked[order.key] = true
			log("Cash auto-buy paused: " .. order.name .. " hasn't arrived yet. Still collecting hay.")
			refresh()
		end
		return false
	end
	if
		shop.disabled
		or App.graveAutoBuy == false
		or not active(generation)
		or not graveReady()
		or App.player:GetAttribute("CarryingCandle") ~= nil
		or os.clock() < (shop.nextCheck or 0)
	then
		return false
	end
	local holders = workspace:FindFirstChild("WhereToPlaceCandles")
	if
		not holders
		or holders:GetAttribute("AllLit") == true
		or (tonumber(holders:GetAttribute("CandlesLit")) or 0) >= 4
	then
		return false
	end
	shop.nextCheck = os.clock() + 1
	if
		type(App.player:GetAttribute("HayUpgradeCapacity")) ~= "number"
		or type(App.player:GetAttribute("HayUpgradeGrab")) ~= "number"
		or type(App.player:GetAttribute("HayUpgradeSpeed")) ~= "number"
	then
		return false
	end
	local order = graveCashPlan(session, cash)
	if not order then
		return false
	end
	local remote = session.hay:FindFirstChild(order.object and "BuyShopItem" or "BuyUpgrade")
	if not remote or not remote:IsA("RemoteEvent") then
		return false
	end
	local model = graveReady()
	stopGraveVacuum(session)
	if order.object then
		local position = positionOf(order.object)
		if not position or not graveMove(order.object, position + Vector3.new(3, 0, 0), 12, generation) then
			shop.blocked[order.key] = true
			log("Cash auto-buy skipped an unreachable " .. order.name)
			return true
		end
		local object, cost = graveCashItem(order.id)
		if object ~= order.object or cost ~= order.cost then
			return true
		end
	end
	wallet = getPath(App.player, "leaderstats", "Cash")
	local now = wallet and tonumber(wallet.Value)
	if
		not active(generation)
		or graveReady() ~= model
		or App.graveAutoBuy == false
		or not now
		or now < order.cost
		or App.player:GetAttribute(order.attribute) ~= order.before
		or App.player:GetAttribute("CarryingCandle") ~= nil
		or holders:GetAttribute("AllLit") == true
		or (tonumber(holders:GetAttribute("CandlesLit")) or 0) >= 4
	then
		return true
	end
	if remote.Parent ~= session.hay then
		return false
	end
	order.at, order.cash = os.clock(), now
	shop.pending = order
	local sent, reason = fire(remote, order.id)
	if not sent then
		shop.disabled = true
		log("Cash auto-buy paused after a request error: " .. tostring(reason))
	else
		status("Cash auto-buy", string.format("%s  |  $%.2f", order.name, order.cost))
	end
	refresh()
	return true
end

local function graveDrone(session, generation)
	local shop = session.shop
	if
		not active(generation)
		or not graveReady()
		or App.player:GetAttribute("DroneOwned") ~= true
		or App.player:GetAttribute("DroneDeployed") == true
		or App.player:GetAttribute("CarryingCandle") ~= nil
	then
		return false
	end
	local model = App.player.Character
	if shop.drone and shop.drone.model == model then
		return false
	end
	local drones = workspace:FindFirstChild("HayDrones")
	for _, drone in ipairs(drones and drones:GetChildren() or {}) do
		if drone:GetAttribute("OwnerUserId") == App.player.UserId then
			return false
		end
	end
	local remote = session.hay:FindFirstChild("DeployDrone")
	if
		not remote
		or not remote:IsA("RemoteEvent")
		or not graveEquip(session, session.config.DRONE_SLOT_INDEX, generation)
	then
		return false
	end
	if not active(generation) or graveReady() ~= model or App.player:GetAttribute("DroneDeployed") == true then
		return false
	end
	shop.drone = { model = model }
	local sent = fire(remote)
	if sent then
		if not pause(0.75, generation) then
			return true
		end
		waitUntil(function()
			return App.player:GetAttribute("DroneDeployed") == true or App.player.Character ~= model
		end, 2.25, generation)
	end
	if active(generation) then
		log(
			App.player:GetAttribute("DroneDeployed") == true and "Owned drone deployed"
				or "The drone hasn't appeared yet. Check it in the game."
		)
	end
	return true
end

local function graveHay(session)
	local folder = workspace:FindFirstChild("HaystackClient")
	local model, root = graveReady()
	local head = model and model:FindFirstChild("Head")
	if not folder or not head then
		return nil
	end
	session.overlap.FilterDescendantsInstances = { folder }
	session.rays.FilterDescendantsInstances = { folder }
	local best, distance, casts = nil, nil, 0
	for _, part in
		ipairs(workspace:GetPartBoundsInRadius(root.Position, session.config.INTERACT_DISTANCE, session.overlap))
	do
		if
			part.Parent ~= folder
			or type(part:GetAttribute("HayId")) ~= "number"
			or (session.blocked[part] or 0) > os.clock()
		then
			continue
		end
		local delta = part.Position - head.Position
		if delta.Magnitude <= 0.05 then
			continue
		end
		if casts >= 8 then
			break
		end
		casts += 1
		local hit = workspace:Raycast(head.Position, delta.Unit * (delta.Magnitude + 0.2), session.rays)
		local visible = hit and hit.Instance
		if not visible or visible.Parent ~= folder or type(visible:GetAttribute("HayId")) ~= "number" then
			continue
		end
		local length = (visible.Position - root.Position).Magnitude
		if
			length <= session.config.INTERACT_DISTANCE
			and (session.blocked[visible] or 0) <= os.clock()
			and (not distance or length < distance)
		then
			best, distance = visible, length
		end
		if best then
			break
		end
	end
	return best
end

local function graveHarvest(session, generation)
	local config = session.config
	local held = math.max(0, tonumber(App.player:GetAttribute("HayHeld")) or 0)
	local capacity = math.max(1, tonumber(App.player:GetAttribute("HayCapacity")) or 25)
	if held >= capacity and App.player:GetAttribute("InfiniteBagOwned") ~= true then
		stopGraveVacuum(session)
		local sell = nearest(config.SELL_PART_NAME, function(part)
			return part:IsA("BasePart")
		end)
		if not sell then
			session.sellMissingAt = session.sellMissingAt or os.clock()
			if os.clock() - session.sellMissingAt > 30 then
				return false, "The hay selling point hasn't loaded yet"
			end
			return nil, "Waiting for the hay selling point"
		end
		session.sellMissingAt = nil
		if not graveMove(sell, sell.Position + Vector3.new(3, 0, 0), config.SELL_INTERACT_DISTANCE - 3, generation) then
			return false, "Could not reach the hay selling point"
		end
		local sent, reason = fire(session.hay:FindFirstChild("SellHay"))
		if not sent then
			return false, reason
		end
		local sold = waitUntil(function()
			return (tonumber(App.player:GetAttribute("HayHeld")) or held) < held
		end, 4, generation)
		return sold ~= nil, sold and "Hay sold" or "The hay sale didn't go through"
	end
	if os.clock() < (session.nextHarvest or 0) then
		return nil
	end
	local part = graveHay(session)
	if not part then
		stopGraveVacuum(session)
		session.searchingAt = session.searchingAt or os.clock()
		if os.clock() - session.searchingAt > 90 then
			return false, "No hay nearby. Move closer to the Graveyard haystack."
		end
		if os.clock() >= (session.nextProbe or 0) then
			session.nextProbe = os.clock() + 4
			local angle = (session.probe or 0) * math.pi / 3
			session.probe = (session.probe or 0) + 1
			local point = config.PILE_CENTER
				+ Vector3.new(math.cos(angle), 0, math.sin(angle)) * (config.PILE_RADIUS + 3)
			local pile = workspace:FindFirstChild("HaystackClient")
			if pile then
				graveMove(pile, point, 4, generation)
			end
		end
		return nil, "Looking for hay"
	end
	session.searchingAt = nil
	local handRate, forkRate, vacuumRate = graveToolRates(session)
	local vacuum = vacuumRate > math.max(handRate, forkRate)
		and App.player:GetAttribute("VacuumOwned") == true
		and App.player:GetAttribute("VacuumState") ~= "Overheated"
	local fork = not vacuum and forkRate > handRate and App.player:GetAttribute("PitchforkOwned") == true
	local slot = vacuum and config.VACUUM_SLOT_INDEX or (fork and config.PITCHFORK_SLOT_INDEX or 1)
	if not graveEquip(session, slot, generation) then
		return nil, "Waiting for the harvesting slot"
	end
	local cooldown = vacuum and config.VACUUM_TICK
		or (
			fork and (App.player:GetAttribute("PitchforkCooldown") or config.PITCHFORK_COOLDOWN)
			or (App.player:GetAttribute("HayPickCooldown") or config.PICK_COOLDOWN)
		)
	if part.Parent ~= workspace:FindFirstChild("HaystackClient") or not graveReady() then
		return nil
	end
	local model, root = graveReady()
	local reach = vacuum and config.VACUUM_RANGE
		or (fork and (config.PITCHFORK_REACH or 4.2) or config.INTERACT_DISTANCE)
	if (part.Position - root.Position).Magnitude > reach then
		stopGraveVacuum(session)
		if not graveMove(part, part.Position, reach - 1, generation) then
			session.blocked[part] = os.clock() + 8
			return nil, "Trying another safe approach to the hay"
		end
	end
	if not active(generation) or graveReady() ~= model or part.Parent ~= workspace:FindFirstChild("HaystackClient") then
		return nil
	end
	session.nextHarvest = os.clock() + math.clamp(tonumber(cooldown) or 0.55, 0.08, 5)
	local id = part:GetAttribute("HayId")
	local before = tonumber(session.hay:GetAttribute("RemainingHay"))
	local sent, reason
	if vacuum then
		local remote = session.hay:FindFirstChild("VacuumAction")
		if not session.vacuum then
			sent, reason = fire(remote, "Start")
			if not sent then
				return false, reason
			end
			session.vacuum = true
		end
		local head = model:FindFirstChild("Head")
		local delta = head and part.Position - head.Position
		if not delta or delta.Magnitude < 0.05 then
			return nil
		end
		local preferred, seen = { id }, { [id] = true }
		local power = graveLevel(config, "VacuumPower")
		local maxCount = math.clamp(power.Count or config.VACUUM_GRAB_COUNT or 5, 1, 96)
		local space = App.player:GetAttribute("InfiniteBagOwned") == true and maxCount or math.max(1, capacity - held)
		for _, other in
			ipairs(workspace:GetPartBoundsInRadius(part.Position, config.VACUUM_HARVEST_REACH or 2.85, session.overlap))
		do
			local otherId = other:GetAttribute("HayId")
			if other.Parent == part.Parent and type(otherId) == "number" and not seen[otherId] then
				seen[otherId] = true
				table.insert(preferred, otherId)
				if #preferred >= math.min(maxCount, space) then
					break
				end
			end
		end
		while #preferred > math.min(maxCount, space) do
			table.remove(preferred)
		end
		sent, reason =
			fire(remote, "Tick", part.Position, head.Position + delta.Unit * math.min(2, delta.Magnitude), preferred)
	else
		stopGraveVacuum(session)
		if fork then
			sent, reason = fire(session.hay:FindFirstChild("PitchforkDig"), id)
		else
			local bonus = {}
			local count = math.clamp(tonumber(App.player:GetAttribute("HayGrabCount")) or 1, 1, 96)
			local radius = math.clamp(tonumber(App.player:GetAttribute("HayGrabRadius")) or 0, 0, 64)
			if count > 1 and radius > 0 then
				local nearby = {}
				for _, other in ipairs(workspace:GetPartBoundsInRadius(part.Position, radius, session.overlap)) do
					local otherId = other:GetAttribute("HayId")
					if
						other ~= part
						and other.Parent == part.Parent
						and type(otherId) == "number"
						and (other.Position - part.Position).Magnitude <= radius
					then
						table.insert(nearby, { id = otherId, distance = (other.Position - part.Position).Magnitude })
					end
				end
				table.sort(nearby, function(a, b)
					return a.distance == b.distance and a.id < b.id or a.distance < b.distance
				end)
				local space = App.player:GetAttribute("InfiniteBagOwned") == true and count
					or math.max(1, capacity - held)
				for index = 1, math.min(#nearby, count - 1, space - 1) do
					table.insert(bonus, nearby[index].id)
				end
			end
			sent, reason = fire(session.hay:FindFirstChild("PickHay"), id, bonus)
		end
	end
	if not sent then
		return false, reason
	end
	session.blocked[part] = os.clock() + math.max(1, tonumber(cooldown) or 0.55)
	session.firstHarvest = session.firstHarvest or os.clock()
	local remaining = tonumber(session.hay:GetAttribute("RemainingHay"))
	if remaining and before and remaining < before then
		session.lastProgress = os.clock()
	end
	return nil
end

local function graveCandle(session, generation)
	local holders = workspace:FindFirstChild("WhereToPlaceCandles")
	local candles = workspace:FindFirstChild("HayCandles")
	local _, root = graveReady()
	if not root or not holders or not candles then
		return nil, "Waiting for the candle ritual"
	end
	local carrying = App.player:GetAttribute("CarryingCandle") ~= nil
	local target, position, distance
	for _, holder in ipairs(holders:GetChildren()) do
		if holder:GetAttribute("ReservedBy") == App.player.UserId and holder:GetAttribute("Lit") ~= true then
			stopGraveVacuum(session)
			return true, "Lighting a candle. Waiting for the matching puzzle."
		end
	end
	for _, object in ipairs((carrying and holders or candles):GetChildren()) do
		local available = carrying and object:GetAttribute("Lit") ~= true and object:GetAttribute("ReservedBy") == nil
			or (
				not carrying
				and object:GetAttribute("HayCandle") == true
				and object:GetAttribute("Revealed") == true
				and object:GetAttribute("HeldBy") == nil
				and object:GetAttribute("Placed") == nil
			)
		local body = object:FindFirstChild("Root")
		local point = body and body:IsA("BasePart") and body.Position or positionOf(object)
		if available and point and (session.blocked[object] or 0) <= os.clock() then
			local length = (point - root.Position).Magnitude
			if not distance or length < distance then
				target, position, distance = object, point, length
			end
		end
	end
	if not target then
		return carrying and true or nil, carrying and "Waiting for a free candle holder" or nil
	end
	stopGraveVacuum(session)
	local function available()
		return carrying
				and App.player:GetAttribute("CarryingCandle") ~= nil
				and target:GetAttribute("Lit") ~= true
				and target:GetAttribute("ReservedBy") == nil
			or (
				not carrying
				and App.player:GetAttribute("CarryingCandle") == nil
				and target:GetAttribute("Revealed") == true
				and target:GetAttribute("HeldBy") == nil
				and target:GetAttribute("Placed") == nil
			)
	end
	if not graveMove(target, position + Vector3.new(2, 0, 0), 10, generation, available) then
		session.blocked[target] = os.clock() + 8
		return false, "Could not reach the candle interaction"
	end
	if not active(generation) or not available() or not graveReady() then
		return nil
	end
	local remote = getPath(Storage, "CandleRitual", "Remotes", carrying and "PlaceCandle" or "PickUpCandle")
	local sent, reason = fire(remote, target)
	if not sent then
		return false, reason
	end
	local accepted = waitUntil(function()
		return carrying
				and (target:GetAttribute("Lit") == true or target:GetAttribute("ReservedBy") == App.player.UserId)
			or (not carrying and App.player:GetAttribute("CarryingCandle") ~= nil)
	end, 5, generation)
	session.blocked[target] = os.clock() + 5
	return accepted ~= nil,
		accepted and (carrying and "Lighting the candle" or "Candle collected") or "The candle didn't respond"
end

local function graveTrap(session, kind, data, generation)
	if not active(generation) then
		return
	end
	if kind == "ClearAreas" then
		session.trap = nil
		return
	end
	if type(data) ~= "table" then
		return
	end
	if data.userId and data.userId ~= App.player.UserId then
		return
	end
	if type(data.users) == "table" and not table.find(data.users, App.player.UserId) then
		return
	end
	if kind == "Grabbed" or kind == "Pulled" or kind == "Snared" then
		if data.id == nil then
			return
		end
		local deadline = tonumber(data.deadline or data.endsAt)
		if not deadline or deadline <= workspace:GetServerTimeNow() then
			return
		end
		session.trap = {
			kind = kind,
			id = data.id,
			deadline = deadline,
			model = App.player.Character,
			sent = {},
			after = os.clock() + math.max(0.9, math.clamp(tonumber(data.presses) or 12, 1, 64) * 0.12),
			prompts = type(data.prompts) == "table" and data.prompts or {},
			good = math.clamp(tonumber(data.good) or 0.3, 0.05, 0.5),
		}
	elseif
		kind == "GrabEnd"
		or kind == "PullEnd"
		or kind == "SnareRelease"
		or kind == "SnareFreed"
		or kind == "ClearAreas"
	then
		if session.trap and (data.id == nil or data.id == session.trap.id) then
			session.trap = nil
		end
	end
end

local function stepGraveTrap(session, generation)
	local trap = session.trap
	if not trap or not active(generation) then
		return
	end
	local now = workspace:GetServerTimeNow()
	if App.player.Character ~= trap.model or now > trap.deadline then
		session.trap = nil
		return
	end
	local feedback = getPath(Storage, "PumpkinBoss", "Feedback")
	if trap.kind == "Snared" and App.player:GetAttribute("PumpkinSnared") == true then
		for index, prompt in ipairs(trap.prompts) do
			if index > 16 then
				break
			end
			local at = type(prompt) == "table" and tonumber(prompt.perfectAt)
			if at and not trap.sent[index] and now >= at and now - at <= trap.good then
				trap.sent[index] = true
				fire(feedback, "SnarePress", trap.id, index, now)
			end
		end
	elseif os.clock() >= trap.after and not trap.sent.escape then
		local flag = trap.kind == "Grabbed" and "PumpkinGrabbed" or "PumpkinPulled"
		if App.player:GetAttribute(flag) == true then
			trap.sent.escape = true
			fire(feedback, trap.kind == "Grabbed" and "GrabEscape" or "PullEscape", trap.id)
		end
	end
end

local function graveFight(session, generation)
	stopGraveVacuum(session)
	local model, root = graveReady()
	if not model or App.player:GetAttribute("PitchforkOwned") ~= true then
		return nil, "Waiting for the ritual pitchfork"
	end
	local target
	for _, rig in ipairs(session.aim.rigs()) do
		if rig.rig == session.boss then
			target = target or rig
		end
		if rig.minion and (rig.root.Position - root.Position).Magnitude < 7 then
			target = rig
			break
		end
	end
	if not target then
		return nil, "Waiting for a vulnerable boss phase"
	end
	if not target.minion and target.rig:GetAttribute("BossVulnerable") ~= true then
		return nil, "Waiting for a vulnerable boss phase"
	end
	if not graveEquip(session, session.config.PITCHFORK_SLOT_INDEX, generation) then
		return nil, "Waiting for the pitchfork slot"
	end
	local point = target.root.Position - target.root.CFrame.LookVector * (target.minion and 4 or 9)
	if (point - root.Position).Magnitude > 4 and os.clock() >= (session.nextMove or 0) then
		session.nextMove = os.clock() + 1
		if
			not graveMove(target.rig, point, 4, generation, function()
				return target.rig:GetAttribute("BossState") ~= "Defeated"
			end)
		then
			return false, "No safe landing near the boss"
		end
	end
	if os.clock() < (session.nextAttack or 0) then
		return nil
	end
	local cooldown = tonumber(App.player:GetAttribute("PitchforkCooldown")) or session.config.PITCHFORK_COOLDOWN
	session.nextAttack = os.clock() + math.clamp(cooldown, 0.1, 5)
	if
		not pause(session.config.PITCHFORK_WINDUP_TIME + session.config.PITCHFORK_STRIKE_TIME, generation)
		or graveReady() ~= model
	then
		return nil
	end
	local head = model:FindFirstChild("Head")
	local hitbox = target.rig:FindFirstChild("BossHitbox") or target.root
	if not head or not hitbox:IsDescendantOf(workspace) then
		return nil
	end
	local delta = hitbox.Position - head.Position
	if delta.Magnitude < 0.05 then
		return nil
	end
	local range = math.clamp(tonumber(App.player:GetAttribute("PitchforkReach")) or session.range, session.range, 24)
	local hit, rig = session.aim.cast(head.Position, delta.Unit, range + 2, 0.8, { model })
	if not hit then
		hit, rig = session.aim.assist(head.Position, delta.Unit, range, { model })
	end
	if rig ~= target.rig or not hit or (hit - head.Position).Magnitude > range + 2 then
		return nil, "Repositioning for a clear pitchfork hit"
	end
	if
		not active(generation)
		or graveReady() ~= model
		or session.slots.getEquipped() ~= session.config.PITCHFORK_SLOT_INDEX
	then
		return nil
	end
	if not target.minion and target.rig:GetAttribute("BossVulnerable") ~= true then
		return nil
	end
	local direction = hit - head.Position
	if direction.Magnitude < 0.05 then
		return nil
	end
	local sent, reason = fire(session.hay:FindFirstChild("PitchforkDig"), "Boss", head.Position, direction.Unit)
	if not sent then
		return false, reason
	end
	session.firstAttack = session.firstAttack or os.clock()
	return nil
end

local function runGraveyard(generation)
	if verify(current, true) == true then
		return true, "Search For The Needle Hollow badge earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if game.PlaceId ~= current.eventPlace then
		local continued = prepareTravel(current.eventPlace, true, App.graveAutoBuy)
		local ok, reason = pcall(Teleport.Teleport, Teleport, current.eventPlace, App.player)
		if not ok then
			return false, "Graveyard transfer failed: " .. tostring(reason)
		end
		App.traveling = true
		return nil,
			continued and "Entering Graveyard. I'll carry on when we arrive."
				or "Entering Graveyard. Run the script again when you arrive."
	end
	status("Loading Graveyard", "Loading the ritual and your tools", 0)
	local hay = waitUntil(function()
		local folder = Storage:FindFirstChild("NeedleHaystack")
		return folder
			and folder:FindFirstChild("Config")
			and getPath(App.player, "PlayerScripts", "HotbarSlots")
			and getPath(Storage, "BossFight", "BossAim")
			and getPath(Storage, "BossFight", "Config")
			and folder
	end, 40, generation)
	if not hay then
		return false, "Graveyard hasn't loaded yet. Try Start again."
	end
	local config, why = module(hay and hay:FindFirstChild("Config"), generation)
	local slots = module(getPath(App.player, "PlayerScripts", "HotbarSlots"), generation)
	local aim = module(getPath(Storage, "BossFight", "BossAim"), generation)
	local bossConfig = module(getPath(Storage, "BossFight", "Config"), generation)
	if
		not config
		or config.MAP ~= "GRAVEYARD"
		or not slots
		or type(slots.setEquipped) ~= "function"
		or type(slots.getEquipped) ~= "function"
		or not aim
		or type(aim.rigs) ~= "function"
		or type(aim.cast) ~= "function"
		or type(aim.assist) ~= "function"
		or not bossConfig
	then
		return false, why or "Graveyard isn't ready yet. Try Start again."
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = {
		hay = hay,
		config = config,
		slots = slots,
		aim = aim,
		range = tonumber(bossConfig.PitchforkRange) or 13,
		blocked = setmetatable({}, { __mode = "k" }),
		overlap = OverlapParams.new(),
		rays = RaycastParams.new(),
		originalSlot = slots.getEquipped(),
		shop = graveShopMemory(),
	}
	session.overlap.FilterType, session.overlap.MaxParts = Enum.RaycastFilterType.Include, 96
	session.rays.FilterType = Enum.RaycastFilterType.Include
	local feedback = waitUntil(function()
		return getPath(Storage, "PumpkinBoss", "Feedback")
	end, 20, generation)
	if not feedback or not feedback:IsA("RemoteEvent") then
		return false, "Pumpkin boss feedback has not loaded"
	end
	local connection = connect(feedback.OnClientEvent, function(kind, data)
		graveTrap(session, kind, data, generation)
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
		session.trap = nil
		stopGraveVacuum(session)
		if session.lastSlot and slots.getEquipped() == session.lastSlot and graveReady() then
			pcall(slots.setEquipped, session.originalSlot)
		end
	end)
	local began, nextBadge, failures = os.clock(), 0, 0
	while active(generation) and os.clock() - began < 3600 do
		if session.shop.pending then
			graveShopping(session, generation)
		end
		stepGraveTrap(session, generation)
		if os.clock() >= nextBadge then
			nextBadge = os.clock() + 20
			if verify(current, true) == true then
				return true, "Search For The Needle Hollow badge earned"
			end
			if not active(generation) then
				return false, "Stopped"
			end
		end
		session.boss = workspace:FindFirstChild("PumpkinGolem_Rig")
		local holders = workspace:FindFirstChild("WhereToPlaceCandles")
		local lit = holders and tonumber(holders:GetAttribute("CandlesLit")) or 0
		local health = session.boss and tonumber(session.boss:GetAttribute("BossHealth"))
		if health and session.health and health < session.health then
			session.firstAttack = os.clock()
		end
		if health then
			session.health = health
		end
		local remaining = tonumber(hay:GetAttribute("RemainingHay"))
		if remaining and session.remaining and remaining < session.remaining then
			session.lastProgress = os.clock()
		end
		if remaining then
			session.remaining = remaining
		end
		local bossState = session.boss and session.boss:GetAttribute("BossState")
		local handled, reason
		if bossState == "Defeated" or App.player:GetAttribute("NeedleRoundComplete") == true then
			stopGraveVacuum(session)
			session.finishedAt = session.finishedAt or os.clock()
			status("Waiting for the Graveyard award", "Waiting for the ending to finish", 0.95)
			if os.clock() - session.finishedAt > 180 then
				return false, "The ending finished, but the Hollow badge hasn't arrived yet"
			end
		elseif not graveReady() then
			stopGraveVacuum(session)
			local puzzle = getPath(App.player, "PlayerGui", "CandleMatchMinigame")
			status(
				puzzle and puzzle.Enabled and "Lighting a candle" or "Waiting for Graveyard controls",
				"Waiting for the puzzle or cutscene to finish",
				math.min(0.45, (lit or 0) / 4 * 0.45)
			)
		elseif holders and (holders:GetAttribute("AllLit") == true or lit >= 4) then
			status(
				"Fighting the Hollow King",
				health and string.format("Boss health: %d", health) or tostring(bossState or "Loading"),
				0.5
			)
			handled, reason = graveFight(session, generation)
			if session.firstAttack and os.clock() - session.firstAttack > 120 then
				return false, "The pitchfork isn't doing damage. Check the boss and try again."
			end
		else
			status("Preparing the candle ritual", string.format("%d / 4 candles lit", lit or 0), (lit or 0) / 4 * 0.45)
			handled, reason = graveCandle(session, generation)
			if handled == nil then
				if not graveDrone(session, generation) and not graveShopping(session, generation) then
					handled, reason = graveHarvest(session, generation)
				end
			end
			if session.firstHarvest and os.clock() - (session.lastProgress or session.firstHarvest) > 90 then
				return false, "No hay is being collected. Check your tool and try again."
			end
		end
		if handled == false then
			failures += 1
		else
			failures = 0
		end
		if reason then
			status("Graveyard", reason)
		end
		if failures >= 3 then
			return false, reason or "Graveyard interactions failed repeatedly"
		end
		if not pause(handled == false and 1 or 0.05, generation) then
			return false, "Stopped"
		end
	end
	return false, "Graveyard run stopped or reached its one-hour limit"
end

local function prismState()
	local ready = App.player:FindFirstChild("UiSetFinish")
	local state = getPath(Storage, "GameValue", "CurrentState")
	local server = getPath(Storage, "GameValue", "CurrentServer")
	local event = getPath(Storage, "GameValue", "TheHollow")
	if
		not App.player:FindFirstChild("DataSetFinish")
		or not ready
		or not ready:IsA("BoolValue")
		or ready.Value ~= true
		or not state
		or not state:IsA("StringValue")
		or not server
		or not server:IsA("StringValue")
		or server.Value == ""
		or not event
		or not event:IsA("BoolValue")
	then
		return nil
	end
	return { state = state.Value, server = server.Value, enabled = event.Value }
end

local function dressPrism(session, generation)
	local state = prismState()
	if not active(generation) or not state or not state.enabled or state.state ~= "Backstage" then
		return nil
	end
	local model = character()
	if not model or App.player:GetAttribute("UsingStation") or App.player:GetAttribute("UseDressroom") then
		return nil, "Waiting for the character's wardrobe controls"
	end
	local male = App.player:GetAttribute("isMale") == true
	local fit = session.outfit
	if not fit or fit.model ~= model or fit.male ~= male then
		fit = { model = model, male = male, began = os.clock(), groups = {}, tried = {}, attempts = {}, equipped = 0 }
		session.outfit = fit
	end
	if fit.done then
		for _, item in ipairs(model:GetChildren()) do
			if item:IsA("Accessory") and not item:GetAttribute("Default") and session.avatarInfo[item.Name] then
				return true, fit.detail
			end
		end
		session.outfit = nil
		return nil, "The outfit came off, picking another"
	end
	local object = getPath(Storage, "GameInfo", "AvatarInfo")
	local catalog = session.avatarInfo
	if not catalog and object then
		local info = module(object, generation)
		catalog = info and info.AvatarInfoTable
		if type(catalog) == "table" then
			session.avatarInfo = catalog
		else
			catalog = nil
		end
	end
	local remote = getPath(Storage, "Event", "AccEvent")
	if not catalog or not remote or not remote:IsA("RemoteEvent") then
		if os.clock() - fit.began > 40 then
			return false, "Prism's wardrobe hasn't loaded yet"
		end
		return nil, "Loading Prism's wardrobe"
	end
	local function ready()
		local now = prismState()
		return active(generation)
			and now
			and now.enabled
			and now.state == "Backstage"
			and character() == model
			and (App.player:GetAttribute("isMale") == true) == male
			and not App.player:GetAttribute("UsingStation")
			and not App.player:GetAttribute("UseDressroom")
			and getPath(Storage, "Event", "AccEvent") == remote
	end
	if not ready() then
		return nil
	end
	local function worn(key)
		local item = model:FindFirstChild(key)
		return item and item:IsA("Accessory") and not item:GetAttribute("Default") and item
	end
	if fit.pending then
		if worn(fit.pending.key) then
			fit.equipped += 1
			fit.groups[fit.pending.group] = true
			fit.pending = nil
		elseif os.clock() - fit.pending.at < 6 then
			return nil, "Waiting for the game to equip " .. fit.pending.key
		else
			fit.pending = nil
		end
	end
	local function eligible(key, item)
		if type(item) ~= "table" or item.IsActivate ~= true or worn(key) then
			return false
		end
		if item.Gender ~= "Unisex" and item.Gender ~= (male and "Male" or "Female") then
			return false
		end
		local own = getPath(App.player, "subdata", "Own", "LimitAvatar")
		if item.PremiumType ~= "Default" and not (own and own:FindFirstChild(key)) then
			return false
		end
		local asset = getPath(Storage, "Avatar", key)
		return asset and asset:IsA("Accessory")
	end
	local wearing = 0
	for _, item in ipairs(model:GetChildren()) do
		if catalog[item.Name] and worn(item.Name) then
			wearing += 1
		end
	end
	local extraSlots = getPath(App.player, "subdata", "Pass", "BM3")
	local limit = extraSlots and (tonumber(extraSlots.Value) or 0) > os.time() and 24 or 12
	if wearing >= limit then
		fit.done, fit.detail = true, "Your outfit is full. Keeping it as it is."
		return true, fit.detail
	end
	local key, group
	for _, kind in ipairs({ "Top", "Bottom", "Shoes", "HeadNeck" }) do
		if fit.groups[kind] or (fit.attempts[kind] or 0) >= 2 then
			continue
		end
		if kind == "HeadNeck" and fit.equipped > 0 then
			break
		end
		local choices = {}
		for id, item in pairs(catalog) do
			if
				type(id) == "string"
				and type(item) == "table"
				and not fit.tried[id]
				and item.FilteringType == kind
				and eligible(id, item)
			then
				table.insert(choices, id)
			end
		end
		if #choices > 0 then
			key, group = choices[math.random(1, #choices)], kind
			break
		end
		fit.groups[kind] = true
	end
	if not key then
		if fit.equipped == 0 then
			if os.clock() - fit.began < 40 then
				fit.groups = {}
				return nil, "Waiting for available outfit items"
			end
			return false, "No clothes equipped. Put on a free item in the game, then press Start."
		end
		fit.done, fit.detail = true, string.format("Outfit ready (%d items)", fit.equipped)
		return true, fit.detail
	end
	if not ready() or not eligible(key, catalog[key]) then
		return nil
	end
	fit.tried[key] = true
	fit.attempts[group] = (fit.attempts[group] or 0) + 1
	fit.pending = { key = key, group = group, at = os.clock() }
	local sent, reason = fire(remote, "setAvatar", key)
	if not sent then
		return false, "Prism outfit request failed: " .. tostring(reason)
	end
	return nil, "Putting on " .. (catalog[key].DisplayName or key)
end

local function closePrismResults(session, generation)
	local state = prismState()
	local board = getPath(App.player, "PlayerGui", "PopUpGui", "LeaderBoard")
	if not board or not board.Visible then
		session.boardAt, session.closedBoard = nil, nil
		return nil
	end
	if
		not state
		or not state.enabled
		or (state.state ~= "Waiting" and state.state ~= "Intermission" and state.state ~= "Backstage")
	then
		return nil
	end
	session.boardAt = session.boardAt or os.clock()
	if session.closedBoard == board then
		if os.clock() - session.closedAt > 5 then
			return false, "Close the results screen, then press Start again."
		end
		return nil
	end
	if os.clock() - session.boardAt < 1.5 then
		return nil
	end
	local remote = getPath(Storage, "Event", "LeaderboardClosed")
	local object = getPath(App.player, "PlayerGui", "UIInteractionModule")
	if not remote or not remote:IsA("RemoteEvent") or not object then
		return nil
	end
	local controls, reason = module(object, generation)
	if not controls or type(controls.PopUp) ~= "function" then
		return false, reason or "Prism's results controls have not loaded"
	end
	state = prismState()
	if
		not active(generation)
		or not state
		or not state.enabled
		or (state.state ~= "Waiting" and state.state ~= "Intermission" and state.state ~= "Backstage")
		or board ~= getPath(App.player, "PlayerGui", "PopUpGui", "LeaderBoard")
		or not board.Visible
		or remote ~= getPath(Storage, "Event", "LeaderboardClosed")
	then
		return nil
	end
	local closed, why = pcall(controls.PopUp, "LeaderBoard", false)
	if not closed then
		return false, "Could not close Prism results: " .. tostring(why)
	end
	session.closedBoard, session.closedAt = board, os.clock()
	if not pause(0.3, generation) then
		return false, "Stopped"
	end
	state = prismState()
	if
		state
		and state.enabled
		and (state.state == "Waiting" or state.state == "Intermission" or state.state == "Backstage")
	then
		return fire(remote)
	end
	return nil
end

local function runPrism(generation)
	if verify(current, true) == true then
		return true, "Prism Hollow badge earned"
	end
	status("Loading Prism", "Loading your event progress and the runway", 0)
	local loaded = waitUntil(prismState, 40, generation)
	if not loaded then
		return false, active(generation) and "Prism's event hasn't loaded yet. Try Start again." or "Stopped"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if not loaded.enabled then
		return false, "Prism's Hollow event is not active in this server"
	end
	if loaded.server ~= "MainServer" and loaded.server ~= "EliteServer" then
		local remote = waitUntil(function()
			local object = getPath(Storage, "Event", "MoveServerRequest")
			return object and object:IsA("RemoteEvent") and object
		end, 15, generation)
		if not remote or not active(generation) then
			return false, active(generation) and "Prism's Main server transfer has not loaded" or "Stopped"
		end
		local session = {}
		local connection = connect(App.player.OnTeleport, function(state)
			if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
				session.traveling = true
			elseif state == Enum.TeleportState.Failed then
				session.failed = true
			end
		end)
		local failed = connect(Teleport.TeleportInitFailed, function(player)
			if player == App.player then
				session.failed = true
			end
		end)
		table.insert(App.cleanups, function()
			connection:Disconnect()
			failed:Disconnect()
		end)
		local continued = prepareTravel(current.place, true)
		if not active(generation) then
			return false, "Stopped"
		end
		local sent, reason = fire(remote, "MainServer")
		if not sent then
			return false, "Prism transfer failed: " .. tostring(reason)
		end
		status("Entering Prism's Main server", "Runway shows take place here", 0.05)
		waitUntil(function()
			return session.traveling or session.failed
		end, 25, generation)
		if not active(generation) then
			return false, "Stopped"
		end
		if session.failed or not session.traveling then
			return false, "Couldn't enter Prism's Main server. Try Start again."
		end
		App.traveling = true
		return nil,
			continued and "Heading to Prism's Main server. I'll carry on when we arrive."
				or "Heading to Prism's Main server. Run the script again when you arrive."
	end
	local session = { nextBadge = 0 }
	local finish = waitUntil(function()
		local remote = getPath(Storage, "Event", "RunwayFinish")
		return remote and remote:IsA("RemoteEvent") and remote
	end, 20, generation)
	if not finish then
		return false, active(generation) and "Prism's runway events have not loaded" or "Stopped"
	end
	local connection = connect(finish.OnClientEvent, function()
		if active(generation) then
			session.nextBadge = math.min(session.nextBadge, os.clock() + 2)
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
	end)
	local began = os.clock()
	while active(generation) and os.clock() - began < 3600 do
		local state = prismState()
		if state and not state.enabled then
			return false, "Prism's Hollow event is no longer active"
		end
		if os.clock() >= session.nextBadge then
			session.nextBadge = os.clock() + 20
			if verify(current, true) == true then
				return true, "Prism Hollow badge earned"
			end
			if not active(generation) then
				return false, "Stopped"
			end
		end
		local progress = getPath(App.player, "Eventdata", "Halloween", "DailyQuest1", "Progress")
		local count = progress and tonumber(progress.Value)
		if not state or not count then
			session.missingAt = session.missingAt or os.clock()
			status("Loading Prism", "Loading your runway progress")
			if os.clock() - session.missingAt > 40 then
				return false, "Your runway progress hasn't loaded. Try Start again."
			end
		else
			session.missingAt = nil
			if session.phase ~= state.state then
				if state.state == "Backstage" then
					session.outfit = nil
				end
				session.phase = state.state
			end
			local dressed, outfit = dressPrism(session, generation)
			if dressed == false then
				return false, outfit
			end
			status(
				"Prism Halloween runways",
				string.format(
					"Daily runways: %d / 2  |  %s\n%s",
					math.max(0, math.floor(count)),
					state.state,
					outfit or "Waiting for the next show"
				),
				math.min(0.9, math.max(0, count) / 2 * 0.85)
			)
			local ok, reason = closePrismResults(session, generation)
			if ok == false then
				return false, reason
			end
		end
		if not pause(1, generation) then
			return false, "Stopped"
		end
	end
	return false, active(generation) and "Stopped after an hour. The Hollow badge hasn't arrived yet." or "Stopped"
end

local function mooState(session)
	local event = session.event.LoadedEvent
	local badge = event and event.Badges and event.Badges.MooMooMystery
	if
		not badge
		or badge.Id ~= current.badges[1]
		or event.EventId ~= "Halloween"
		or type(badge.Requirement) ~= "number"
		or badge.Requirement < 1
		or badge.Requirement % 1 ~= 0
	then
		return nil, "Waiting for Moo Moo's Halloween event"
	end
	local data = session.event.EventData_ById[event.EventId]
	local raw = data and data.RawSaveData
	if type(raw) ~= "table" or type(raw.TrackProgress) ~= "table" then
		return nil, "Loading your Halloween progress"
	end
	local kinds = session.shared.RewardTrackKind
	local ghosts = session.shared.TrackObjectGet(raw.TrackProgress, kinds.scavenger_hunt)
	local owned = {}
	for _, index in ipairs(ghosts and ghosts.Data and ghosts.Data.C or {}) do
		owned[index] = true
	end
	local nextGhostReward
	for _, spec in ipairs(event.RewardTracks or {}) do
		if spec.Kind == kinds.scavenger_hunt and spec.Identifier == (ghosts and ghosts.Identifier) then
			for index, reward in ipairs(spec.Rewards or {}) do
				if not ghosts or not session.shared.TrackProgressRewardIsClaimed(ghosts, index) then
					if type(reward.Requirement) == "number" then
						nextGhostReward = reward.Requirement
						break
					end
				end
			end
		end
	end
	return {
		event = event,
		data = data,
		tracks = raw.TrackProgress,
		claimed = session.shared.EventSaveDataGetRewardCount(raw.TrackProgress),
		ghosts = ghosts and tonumber(ghosts.Progress) or 0,
		owned = owned,
		identifier = ghosts and ghosts.Identifier,
		nextGhostReward = nextGhostReward,
		needed = badge.Requirement,
	}
end

local function mooReady(session)
	local data, gameState = session.data, session.game
	local flags, player = data.Flags, data.LocalPlayerState
	local model, root, humanoid = character()
	local native = data.LocalCharacterState
	if
		not model
		or not native
		or native.Character ~= model
		or not native.Initialized
		or not native.Alive
		or not player
		or not player.IsPlayingGame
		or player.IsAFKing
		or not flags.Initialized
		or not flags.IntroSequenceComplete
		or not flags.LocalPlayerIsInMap
		or not flags.IsAlive
		or not flags.AimingEnabled
		or flags.OnMainMenu
		or flags.InSpectateMode
		or flags.InCinematicCam
		or flags.InRoundEndCamera
		or flags.InSpecialCameraState
		or flags.JumpscareActive
		or root.Anchored
		or humanoid.PlatformStand
		or humanoid.WalkSpeed <= 0
		or gameState.GameStateType ~= session.common.GameStateType.Running
	then
		return nil
	end
	return model, root
end

local function mooPackets(session, messages)
	if type(messages) ~= "table" then
		return
	end
	local requests = session.common.GameRequestType
	for _, message in ipairs(messages) do
		if type(message) ~= "table" then
			continue
		end
		if
			message.R == requests.Snapshot
			or (
				message.R == requests.GameState
				and type(message.S) == "number"
				and message.S <= session.common.GameStateType.InLobby
			)
		then
			table.clear(session.memory.chests)
		end
		local pickups = message.R == requests.Pickups and message or (message.R == requests.Snapshot and message.P)
		if type(pickups) ~= "table" then
			continue
		end
		local spawned = type(pickups.Pn) == "table" and pickups.Pn.R_E1
		for _, entry in ipairs(type(spawned) == "table" and spawned or {}) do
			if
				type(entry) ~= "table"
				or (type(entry.I) ~= "number" and type(entry.I) ~= "string")
				or typeof(entry.O) ~= "CFrame"
			then
				continue
			end
			local old = session.memory.chests[entry.I]
			if not old or old.origin ~= entry.O or old.phase ~= session.game.GameStateChangedAt then
				session.memory.chests[entry.I] = {
					id = entry.I,
					origin = entry.O,
					kind = "R_E1",
					phase = session.game.GameStateChangedAt,
				}
			end
		end
		for id, collected in pairs(type(pickups.Pc) == "table" and pickups.Pc or {}) do
			local chest = session.memory.chests[id]
			if chest then
				chest.claimed = true
				chest.collector = type(collected) == "table" and collected.U or nil
				local returns = type(pickups.Ca) == "table" and pickups.Ca[id]
				local reward = type(returns) == "table" and returns[1]
				local event = type(reward) == "table" and reward.EventCollectibles
				if type(event) == "table" and event.EventId == "Halloween" and type(event.Collectibles) == "table" then
					chest.identifier, chest.collectibles = event.Identifier, {}
					for _, index in ipairs(event.Collectibles) do
						if type(index) == "number" and index > 0 and index % 1 == 0 then
							table.insert(chest.collectibles, index)
						end
					end
				end
			end
		end
	end
end

local function claimMooReward(session, state, generation)
	local pending = session.memory.reward
	if pending then
		local track = session.shared.TrackObjectGet(state.tracks, pending.kind, pending.identifier)
		if track and session.shared.TrackProgressRewardIsClaimed(track, pending.index) then
			session.memory.reward = nil
			log("Halloween reward claimed")
		elseif os.clock() - pending.at > 12 then
			return false, "The reward hasn't arrived yet. Check it in the event menu before trying again."
		end
		return nil
	end
	if state.claimed >= state.needed then
		return nil
	end
	local player = session.event.GetPlayerDataReplicated()
	local kinds = session.shared.RewardTrackKind
	for _, kind in ipairs({ kinds.daily_login, kinds.scavenger_hunt, kinds.playtime, kinds.challenge }) do
		for _, spec in ipairs(state.event.RewardTracks) do
			if spec.Kind ~= kind or not session.shared.TrackPermissionsCanAccess(spec, state.data.TrackPermissions) then
				continue
			end
			local progress = session.shared.TrackObjectGet(state.tracks, spec.Kind, spec.Identifier)
				or { Kind = spec.Kind, Identifier = spec.Identifier, Progress = 0, Claimed = {} }
			for index in ipairs(spec.Rewards) do
				if not session.shared.TrackProgressCanClaimReward(player, spec, progress, index) then
					continue
				end
				local remote = getPath(Storage, "BUEShared", "RequestClaimReward")
				if not remote or not remote:IsA("RemoteEvent") then
					return nil
				end
				local latest = mooState(session)
				if
					not active(generation)
					or not latest
					or latest.event ~= state.event
					or latest.claimed >= latest.needed
				then
					return nil
				end
				session.memory.reward =
					{ kind = spec.Kind, identifier = spec.Identifier, index = index, at = os.clock() }
				local sent, reason = fire(remote, state.event.EventId, index, spec.Kind, spec.Identifier)
				if not sent then
					return false, "Halloween reward request failed: " .. tostring(reason)
				end
				return true
			end
		end
	end
	return nil
end

local function joinMooRound(session, generation)
	local skipped = session.memory.resetRound
	if skipped then
		if
			session.game.GameStateType == session.common.GameStateType.Running
			and session.game.GameStateChangedAt == skipped
		then
			local credit = session.memory.lastCredit
			return nil,
				credit and credit.phase == skipped and string.format(
					"Ghosts %d -> %d confirmed. Waiting for the next round.",
					credit.before,
					credit.after
				) or "Chest collected. Waiting for the next round."
		end
		session.memory.resetRound = nil
	end
	local flags, player = session.data.Flags, session.data.LocalPlayerState
	if not flags.Initialized or not flags.IntroSequenceComplete then
		return nil, "Waiting for the game's Play screen"
	end
	if player and player.IsAFKing then
		return nil, "Turn off AFK in the game to join rounds"
	end
	if player and player.IsPlayingGame then
		return nil
	end
	local phase, types = session.game.GameStateType, session.common.GameStateType
	if
		flags.HasSpectated
		or not flags.JoinButtonActive
		or flags.InSpecialCameraState
		or phase < types.StartCountdown
		or phase > types.Running
	then
		return nil, "Waiting for the next round"
	end
	if
		phase == types.Running
		and session.game.GameStateChangesAt - session.settings.GameTime_JoinAllowedUntil < session.common.Now
	then
		return nil, "Waiting for the next round's join window"
	end
	local stamp = tostring(session.game.GameStateChangedAt)
	if session.joinedStamp == stamp then
		return nil, "Waiting to join the round"
	end
	local remote = getPath(Storage, "Remotes", "Game")
	if not active(generation) then
		return nil
	end
	session.joinedStamp = stamp
	local sent, why = fire(remote, session.common.GameRequestType.Join)
	if not sent then
		return false, "Moo Moo round entry failed: " .. tostring(why)
	end
	return true, "Joining the current round"
end

local function resetMooAfterChest(session, generation)
	local pending = session.memory.reset
	if not pending then
		return nil
	end
	if not active(generation) then
		return true, "Stopped"
	end
	if
		App.player.Character ~= pending.model
		or session.memory.chests[pending.entry.id] ~= pending.entry
		or session.game.GameStateType ~= session.common.GameStateType.Running
		or session.game.GameStateChangedAt ~= pending.phase
	then
		session.memory.reset = nil
		return nil
	end
	local state = mooState(session)
	if os.clock() > pending.at + 15 then
		session.memory.reset = nil
		return nil
	end
	local credited = false
	if
		state
		and pending.entry.kind == "R_E1"
		and pending.entry.phase == pending.phase
		and pending.entry.identifier == state.identifier
	then
		for _, index in ipairs(pending.entry.collectibles or {}) do
			if not (pending.owned or {})[index] and state.owned[index] then
				credited = index
				break
			end
		end
	end
	if
		os.clock() < pending.at + 3.5
		or not state
		or pending.entry.collector ~= App.player.UserId
		or state.ghosts <= pending.ghosts
		or not credited
		or mooReady(session) ~= pending.model
	then
		return true, "Waiting for the chest reward and animation to finish"
	end
	local native = session.data.LocalCharacterState
	if not native or native.Character ~= pending.model or native.Destroyed or not native.Initialized then
		return true, "Waiting until you can move"
	end
	session.memory.reset = nil
	session.memory.resetRound = pending.phase
	session.memory.lastCredit = {
		before = pending.ghosts,
		after = state.ghosts,
		index = credited,
		phase = pending.phase,
	}
	local confirmation = string.format("Ghosts %d -> %d confirmed", pending.ghosts, state.ghosts)
	log(confirmation .. string.format(" | %d / %d rewards claimed", state.claimed, state.needed))
	local ok, reason = pcall(session.characterState.KillCharacter, native)
	if not ok then
		return false, "Moo Moo reset failed: " .. tostring(reason)
	end
	return true, confirmation .. ". Waiting for the next round."
end

local function collectMooChest(session, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	for _, entry in pairs(session.memory.chests) do
		local pending = entry.pending
		if pending then
			if pending.phase ~= session.game.GameStateChangedAt then
				entry.pending = nil
			elseif pending.request.Response == session.common.ResponseType.AwaitingResponse and not entry.claimed then
				return nil, "Waiting for the chest reply"
			elseif entry.claimed or pending.request.Response == session.common.ResponseType.Success then
				entry.pending, entry.claimed = nil, true
				if pending.before then
					session.memory.reset = {
						model = pending.model,
						phase = pending.phase,
						entry = entry,
						ghosts = pending.before.ghosts,
						owned = pending.before.owned,
						at = os.clock(),
					}
				end
				return nil, "Chest opened. Checking the reward."
			else
				entry.pending, entry.attempted = nil, nil
				entry.blockedUntil = os.clock() + 5
			end
		end
	end
	if
		session.memory.reset
		or (session.memory.resetRound and session.memory.resetRound == session.game.GameStateChangedAt)
	then
		return nil, "Chest collected. Waiting for the next round."
	end
	local model, root = mooReady(session)
	if not model then
		return nil, "Waiting until you're back in the round"
	end
	local folder = workspace:FindFirstChild("Pickups")
	local chosen, distance
	for _, object in ipairs(folder and folder:GetChildren() or {}) do
		if object.Name ~= "Chest" or not object:IsA("Model") then
			continue
		end
		local point = object:GetPivot().Position
		for _, entry in pairs(session.memory.chests) do
			if
				entry.kind ~= "R_E1"
				or entry.phase ~= session.game.GameStateChangedAt
				or entry.claimed
				or entry.attempted
				or (entry.blockedUntil or 0) > os.clock()
				or (point - entry.origin.Position).Magnitude > 0.75
			then
				continue
			end
			local length = (point - root.Position).Magnitude
			if not distance or length < distance then
				chosen, distance = { object = object, entry = entry, point = point }, length
			end
		end
	end
	if not chosen then
		if os.clock() >= (session.nextStream or 0) then
			session.nextStream = os.clock() + 5
			for _, entry in pairs(session.memory.chests) do
				if
					entry.kind ~= "R_E1"
					or entry.phase ~= session.game.GameStateChangedAt
					or entry.claimed
					or entry.attempted
				then
					continue
				end
				call("Moo chest streaming", function()
					App.player:RequestStreamAroundAsync(entry.origin.Position, 2)
				end, 3, generation)
				break
			end
		end
		return nil, "Waiting for the next secret chest to appear"
	end
	local object, entry = chosen.object, chosen.entry
	local phaseAt = session.game.GameStateChangedAt
	local function valid()
		return active(generation)
			and mooReady(session) == model
			and not entry.claimed
			and not entry.attempted
			and object.Parent == folder
			and session.memory.chests[entry.id] == entry
			and entry.kind == "R_E1"
			and entry.phase == phaseAt
			and (object:GetPivot().Position - entry.origin.Position).Magnitude <= 0.75
			and session.game.GameStateChangedAt == phaseAt
	end
	local reach = math.min(12, session.settings.PickupsInteractRewardChestCollectionRadius - 2)
	if distance > reach then
		local moved = approach(chosen.point + Vector3.new(3, 0, 0), generation, object, false, valid)
		if not moved then
			entry.blockedUntil = os.clock() + 15
			return nil, "Couldn't reach that chest safely. Trying another."
		end
	end
	local _, nowRoot = mooReady(session)
	if not valid() or not nowRoot or (entry.origin.Position - nowRoot.Position).Magnitude > reach then
		return nil
	end
	local remote = getPath(Storage, "Remotes", "Game")
	if not remote or not remote:IsA("RemoteEvent") then
		return nil
	end
	local before = mooState(session)
	entry.attempted = true
	local ok, request = pcall(session.network.MakeRequest, {
		Remote = remote,
		Request = session.common.GameRequestType.PickupCollect,
		Args = { entry.id },
	})
	if not ok or type(request) ~= "table" then
		entry.attempted, entry.blockedUntil = nil, os.clock() + 5
		return nil, "The chest didn't respond. Retrying shortly."
	end
	entry.pending = { request = request, before = before, model = model, phase = phaseAt }
	waitUntil(function()
		return entry.claimed
			or request.Response ~= session.common.ResponseType.AwaitingResponse
			or not mooReady(session)
	end, 8, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	if entry.claimed or request.Response == session.common.ResponseType.Success then
		entry.pending = nil
		if before then
			session.memory.reset = {
				model = model,
				phase = phaseAt,
				entry = entry,
				ghosts = before.ghosts,
				owned = before.owned,
				at = os.clock(),
			}
		end
		if not pause(3.5, generation) then
			return false, "Stopped"
		end
		local reset, detail = resetMooAfterChest(session, generation)
		if reset == false then
			return false, detail
		end
		return true, detail
	end
	if not mooReady(session) then
		return nil
	end
	session.rejected = (session.rejected or 0) + 1
	if request.Response ~= session.common.ResponseType.AwaitingResponse then
		entry.pending, entry.attempted = nil, nil
		entry.blockedUntil = os.clock() + math.min(3 + session.rejected, 15)
	end
	return nil, entry.pending and "Waiting for the chest reply" or "That chest didn't count. Retrying shortly."
end

local function runMoo(generation)
	if verify(current, true) == true then
		return true, "Moo Moo Hollow badge earned"
	end
	status("Loading Moo Moo", "Loading the event and your progress", 0)
	local paths = {
		event = { "BUEClient" },
		shared = { "BUEShared" },
		common = { "CommonData" },
		settings = { "Settings" },
		data = { "Modules", "ClientData" },
		game = { "Modules", "GameStateHandler" },
		network = { "Modules", "NetworkRequestUtility" },
		characterState = { "Modules", "CharacterStateHandler" },
	}
	local session = {}
	for key, path in pairs(paths) do
		local object = waitUntil(function()
			return getPath(Storage, table.unpack(path))
		end, 30, generation)
		local value, reason = module(object, generation)
		if not value then
			return false, "Moo Moo module " .. key .. " is not ready: " .. tostring(reason)
		end
		session[key] = value
	end
	if
		type(session.event.GetPlayerDataReplicated) ~= "function"
		or type(session.shared.TrackProgressCanClaimReward) ~= "function"
		or type(session.network.MakeRequest) ~= "function"
		or type(session.characterState.KillCharacter) ~= "function"
		or type(session.data.Flags) ~= "table"
	then
		return false, "Moo Moo's event hasn't finished loading"
	end
	if session.settings.EventsEnabled ~= true then
		return false, "Moo Moo events are disabled in this server"
	end
	local memoryKey = tostring(game.JobId) .. ":" .. tostring(App.player.UserId)
	if type(env.__HOLLOW_MOO) ~= "table" or env.__HOLLOW_MOO.key ~= memoryKey or env.__HOLLOW_MOO.version ~= 2 then
		env.__HOLLOW_MOO = { key = memoryKey, version = 2, chests = {} }
	end
	session.memory = env.__HOLLOW_MOO
	local remote = waitUntil(function()
		return getPath(Storage, "Remotes", "Game")
	end, 15, generation)
	if not remote or not remote:IsA("RemoteEvent") or not active(generation) then
		return false, "Moo Moo's round messages have not loaded"
	end
	local connection = connect(remote.OnClientEvent, function(messages)
		if active(generation) then
			mooPackets(session, messages)
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
	end)
	local began, nextBadge = os.clock(), 0
	while active(generation) and os.clock() - began < 7200 do
		if os.clock() >= nextBadge then
			nextBadge = os.clock() + 20
			if verify(current, true) == true then
				return true, "Moo Moo Hollow badge earned"
			end
			if not active(generation) then
				return false, "Stopped"
			end
		end
		local state, missing = mooState(session)
		if not state then
			session.missingAt = session.missingAt or os.clock()
			status("Loading Moo Moo", missing)
			if os.clock() - session.missingAt > 45 then
				return false, missing .. ". Press Start again once the event loads."
			end
		else
			session.missingAt = nil
			local claimed, reason = claimMooReward(session, state, generation)
			if claimed == false then
				return false, reason
			end
			if state.claimed >= state.needed then
				session.completedAt = session.completedAt or os.clock()
				status("Checking the Moo Moo badge", "Eight rewards claimed! Waiting for the badge.", 0.95)
				if os.clock() - session.completedAt > 90 then
					return false, "Eight rewards claimed, but the Hollow badge hasn't arrived yet"
				end
			else
				session.completedAt = nil
				local resetting, detail = resetMooAfterChest(session, generation)
				if resetting == false then
					return false, detail
				end
				local joined
				if not resetting then
					joined, detail = joinMooRound(session, generation)
				end
				if joined == false then
					return false, detail
				end
				if not joined and not resetting then
					local collected, why = collectMooChest(session, generation)
					if collected == false then
						return false, why
					end
					detail = detail or why
				end
				state = mooState(session) or state
				local nextReward = state.nextGhostReward
						and (state.ghosts >= state.nextGhostReward and "Waiting for the ghost reward to count" or string.format(
							"Next ghost reward: %d / %d ghosts",
							state.ghosts,
							state.nextGhostReward
						))
					or "Checking the other Halloween reward tracks."
				status(
					"Moo Moo Halloween rewards",
					string.format(
						"Rewards: %d / %d claimed  |  Ghosts: %d\n%s\n%s",
						state.claimed,
						state.needed,
						state.ghosts,
						nextReward,
						detail or "Waiting for the next chest"
					),
					math.min(0.9, state.claimed / state.needed * 0.9)
				)
			end
		end
		if not pause(0.5, generation) then
			return false, "Stopped"
		end
	end
	return false, active(generation) and "Stopped after two hours. The Hollow badge hasn't arrived yet." or "Stopped"
end

local function duckProgress(session)
	if type(rawget(session.data, "_dataReceived")) ~= "table" or not session.data:IsDataLoaded() then
		return nil
	end
	local earned = session.data:GetRaw({ "Statistics", "CandyEarned" })
	if type(earned) ~= "number" or earned ~= earned or earned < 0 or earned == math.huge then
		return nil
	end
	return earned
end

local function duckReady(session)
	local model, root, humanoid = character()
	if
		not model
		or root.Anchored
		or humanoid.PlatformStand
		or humanoid.WalkSpeed <= 0
		or App.player:GetAttribute("AliveInRound") ~= true
		or App.player:GetAttribute("AFK") == true
		or session.game.getGameState("RoundState") ~= "Round"
		or session.game.getGameState("Transitioning") == true
	then
		return nil
	end
	return model, root
end

local function collectDuckCandy(session, generation)
	local model, root = duckReady(session)
	if not model then
		return nil,
			App.player:GetAttribute("AFK") == true and "Turn off AFK in the game to join rounds"
				or "Waiting until you're back in a match"
	end
	local map = workspace:FindFirstChild("CurrentMap")
	if not map then
		return nil, "Waiting for the map to load"
	end
	local round = tostring(session.game.getGameState("TotalRounds"))
		.. ":"
		.. tostring(session.game.getGameState("Round"))
	local memory = session.memory
	if memory.map ~= map or memory.round ~= round then
		memory.map, memory.round, memory.attempts, memory.pending = map, round, {}, {}
	end
	memory.pending = memory.pending or {}
	local chosen, distance
	local constants = session.toolkit.Constants
	for object in pairs(session.targets) do
		if not object:IsDescendantOf(map) or not object:IsA("BasePart") then
			continue
		end
		if object:GetAttribute(constants.ActiveAttribute) ~= true then
			memory.attempts[object] = nil
			continue
		end
		local pending = memory.pending[object]
		if pending and pending.done then
			memory.pending[object] = nil
		end
		local attempted = memory.attempts[object]
		if
			pending and not pending.done
			or attempted == true
			or type(attempted) == "number" and attempted > os.clock()
			or not session.toolkit.getCandyData(object:GetAttribute(constants.TypeAttribute))
		then
			continue
		end
		local length = (object.Position - root.Position).Magnitude
		if not distance or length < distance then
			chosen, distance = object, length
		end
	end
	if not chosen then
		return nil, "No candy left here. Waiting for more or the next round."
	end
	local function valid()
		return active(generation)
			and duckReady(session) == model
			and workspace:FindFirstChild("CurrentMap") == map
			and tostring(session.game.getGameState("TotalRounds")) .. ":" .. tostring(
				session.game.getGameState("Round")
			) == round
			and chosen:IsDescendantOf(map)
			and session.targets[chosen]
			and chosen:GetAttribute(constants.ActiveAttribute) == true
			and session.toolkit.isActive(workspace:GetServerTimeNow())
	end
	local before = duckProgress(session)
	if not before or before >= session.config.CandyBadgeGoal or not valid() then
		return nil
	end
	memory.attempts[chosen] = os.clock() + 3
	if distance > 6 then
		local moved = approach(chosen.Position + Vector3.new(3, 0, 0), generation, chosen, false, valid)
		if not moved then
			if not active(generation) then
				return false, "Stopped"
			end
			return nil, "Couldn't reach that candy safely. Trying another."
		end
	end
	local earned = duckProgress(session)
	if earned and earned > before then
		memory.attempts[chosen] = true
		return true, "Candy collected"
	end
	local _, nowRoot = duckReady(session)
	if not valid() or not nowRoot or (chosen.Position - nowRoot.Position).Magnitude > 6 then
		return nil
	end
	local server = rawget(session.controller, "Server")
	if type(server) ~= "table" or type(rawget(server, "RequestPickup")) ~= "function" then
		memory.attempts[chosen] = nil
		return nil, "Candy pickups are still loading"
	end
	local rejected, failure
	local ok, promise = pcall(session.controller.RequestPickup, session.controller, chosen)
	if
		not ok
		or type(promise) ~= "table"
		or type(promise.andThen) ~= "function"
		or type(promise.catch) ~= "function"
	then
		memory.attempts[chosen] = os.clock() + 5
		return nil, "Couldn't pick up that candy yet. Trying again shortly."
	end
	local receipt = {}
	memory.pending[chosen] = receipt
	promise
		:andThen(function(result)
			receipt.done = true
			if result == false then
				rejected = true
			end
		end)
		:catch(function(reason)
			receipt.done = true
			rejected, failure = true, tostring(reason)
		end)
	waitUntil(function()
		local count = duckProgress(session)
		return (count and count > before)
			or rejected
			or duckReady(session) ~= model
			or workspace:FindFirstChild("CurrentMap") ~= map
	end, 8, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	earned = duckProgress(session)
	if earned and earned > before then
		session.unconfirmed = 0
		memory.attempts[chosen], memory.pending[chosen] = true, nil
		return true, "Candy collected"
	end
	if duckReady(session) ~= model or workspace:FindFirstChild("CurrentMap") ~= map then
		return nil, "Waiting for the next match"
	end
	session.unconfirmed = (session.unconfirmed or 0) + 1
	memory.attempts[chosen] = os.clock() + math.min(3 + session.unconfirmed, 12)
	return nil,
		receipt.done and "That candy didn't count. Retrying shortly."
			or "Waiting for the pickup reply. Checking other candy."
end

local function travelDuck(generation)
	local travel = {}
	local connection = connect(App.player.OnTeleport, function(state)
		if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
			travel.started = true
		elseif state == Enum.TeleportState.Failed then
			travel.failed = true
		end
	end)
	local failed = connect(Teleport.TeleportInitFailed, function(player)
		if player == App.player then
			travel.failed = true
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
		failed:Disconnect()
	end)
	local continued = prepareTravel(current.place, true)
	if not active(generation) then
		return false, "Stopped"
	end
	local sent, reason = pcall(Teleport.Teleport, Teleport, current.place, App.player)
	if not sent then
		return false, "Duck Duck transfer failed: " .. tostring(reason)
	end
	status("Entering Duck Duck matches", "The Trading Hub does not spawn match candy", 0)
	waitUntil(function()
		return travel.started or travel.failed
	end, 25, generation)
	if not active(generation) then
		return false, "Stopped"
	end
	if travel.failed or not travel.started then
		return false, "Couldn't enter Duck Duck. Try Start again."
	end
	App.traveling = true
	return nil,
		continued and "Heading to Duck Duck. I'll carry on when we arrive."
			or "Heading to Duck Duck. Run the script again when you arrive."
end

local function runDuck(generation)
	if verify(current, true) == true then
		return true, "Duck Duck Hollow badge earned"
	end
	if game.PlaceId == 136645373137939 then
		return travelDuck(generation)
	end
	status("Loading Duck Duck", "Loading the match, event, and your progress", 0)
	local paths = {
		data = { "PlayerData", "DataController" },
		game = { "Game", "GameStore" },
		config = { "HalloweenEvent", "HalloweenEventData" },
		toolkit = { "HalloweenEvent", "CandyEventToolkit" },
		controller = { "HalloweenEvent", "CandyEventController" },
		badges = { "PlayerBadge", "PlayerBadgeData" },
	}
	local session = { targets = {} }
	for key, path in pairs(paths) do
		local object = waitUntil(function()
			return getPath(Storage, "src", "Systems", path[1], path[2])
		end, 30, generation)
		local value, reason = module(object, generation)
		if not value then
			return false, "Duck Duck module " .. key .. " is not ready: " .. tostring(reason)
		end
		session[key] = value
	end
	local badge
	for _, entry in ipairs(session.badges) do
		if entry.Name == session.config.CandyBadgeName then
			badge = entry.BadgeId
		end
	end
	if
		badge ~= current.badges[1]
		or session.config.CandyBadgeGoal ~= 250
		or type(session.data.IsDataLoaded) ~= "function"
		or type(session.data.GetRaw) ~= "function"
		or type(session.game.getGameState) ~= "function"
		or type(session.controller.RequestPickup) ~= "function"
		or type(session.toolkit.isActive) ~= "function"
		or type(session.toolkit.getCandyData) ~= "function"
		or type(session.toolkit.Constants) ~= "table"
		or session.toolkit.Constants.ComponentTag ~= "CandyPickup"
	then
		return false, "Duck Duck's event changed. Try an updated script."
	end
	local key = tostring(game.JobId) .. ":" .. tostring(App.player.UserId)
	if type(env.__HOLLOW_DUCK) ~= "table" or env.__HOLLOW_DUCK.key ~= key then
		env.__HOLLOW_DUCK = { key = key, attempts = {} }
	end
	session.memory = env.__HOLLOW_DUCK
	local tag = session.toolkit.Constants.ComponentTag
	local added = connect(Collection:GetInstanceAddedSignal(tag), function(object)
		if active(generation) then
			session.targets[object] = true
		end
	end)
	local removed = connect(Collection:GetInstanceRemovedSignal(tag), function(object)
		session.targets[object], session.memory.attempts[object] = nil, nil
	end)
	table.insert(App.cleanups, function()
		added:Disconnect()
		removed:Disconnect()
	end)
	for _, object in ipairs(Collection:GetTagged(tag)) do
		session.targets[object] = true
	end
	for object in pairs(session.memory.attempts) do
		if not session.targets[object] then
			session.memory.attempts[object] = nil
		end
	end
	local began, nextBadge = os.clock(), 0
	while active(generation) and os.clock() - began < 7200 do
		if not session.toolkit.isActive(workspace:GetServerTimeNow()) then
			return false, "Duck Duck's Halloween candy event is not active"
		end
		if os.clock() >= nextBadge then
			nextBadge = os.clock() + 20
			if verify(current, true) == true then
				return true, "Duck Duck Hollow badge earned"
			end
			if not active(generation) then
				return false, "Stopped"
			end
		end
		local earned = duckProgress(session)
		if not earned then
			session.missingAt = session.missingAt or os.clock()
			status("Loading Duck Duck", "Loading your candy count")
			if os.clock() - session.missingAt > 60 then
				return false, "Your candy count hasn't loaded. Try Start again."
			end
		else
			session.missingAt = nil
			local detail
			if earned >= session.config.CandyBadgeGoal then
				session.completedAt = session.completedAt or os.clock()
				detail = "Goal reached! Waiting for the badge."
				if os.clock() - session.completedAt > 90 then
					return false, "250 candy earned, but the Hollow badge hasn't arrived yet"
				end
			else
				local collected
				collected, detail = collectDuckCandy(session, generation)
				if collected == false then
					return false, detail
				end
			end
			status(
				"Duck Duck candy",
				string.format("%d / 250 candy earned\n%s", math.floor(earned), detail or "Waiting for the next candy"),
				math.min(0.95, earned / session.config.CandyBadgeGoal * 0.95)
			)
		end
		if not pause(0.5, generation) then
			return false, "Stopped"
		end
	end
	return false, active(generation) and "Stopped after two hours. The Hollow badge hasn't arrived yet." or "Stopped"
end

local function bloxState(session)
	local stats = getPath(Storage, "Stats", App.player.Name)
	local earned = getPath(stats, "RobloxEventsHolder", "TotalEventCurrency")
	local state = getPath(Storage, "Modules", "EventService", "HalloweenService", "SeasonalMinigameState")
	local index = getPath(state, "CurrentMinigameIndex")
	local ongoing = getPath(state, "HasOngoingMinigame")
	local playing = getPath(stats, "IsPlaying")
	if
		not stats
		or stats.Value ~= true
		or not earned
		or not index
		or not ongoing
		or not playing
		or type(earned.Value) ~= "number"
		or earned.Value ~= earned.Value
		or earned.Value < 0
		or earned.Value == math.huge
	then
		return nil
	end
	local tasks = getPath(state, "DataValues", tostring(App.player.UserId) .. "_Tasks")
	return {
		stats = stats,
		earned = earned.Value,
		playing = playing.Value == true,
		index = index.Value,
		name = session.handler.Config.Minigames[index.Value],
		ongoing = ongoing.Value == true,
		tasks = tasks and tasks.Value or 0,
	}
end

function App.bloxCloseMenu(session)
	local menu = session.menu
	if not menu then
		return
	end
	if type(menu.Close) == "function" then
		pcall(menu.Close, menu)
	end
	local ok, currentMenu = pcall(session.interact.GetMenu, session.interact)
	if ok and currentMenu == menu and type(session.interact.CloseMenu) == "function" then
		pcall(session.interact.CloseMenu, session.interact)
		ok, currentMenu = pcall(session.interact.GetMenu, session.interact)
	end
	if ok and currentMenu ~= menu then
		session.menu = nil
	end
end

local function bloxReady(session, index)
	local state = bloxState(session)
	local model, root, humanoid = character()
	local menu = session.interact:GetMenu()
	local target = menu and menu.Target
	local background = menu
		and menu.IsBackground == true
		and state
		and session.objects[state.name]
		and session.objects[state.name][target] == true
	if
		not state
		or not state.playing
		or not model
		or root.Anchored
		or humanoid.Sit
		or humanoid.PlatformStand
		or humanoid.WalkSpeed <= 0
		or session.interactionData.ALL_INTERACTIONS_LOCKED
		or session.halloween.Modules.BuildUI:InBuildMode()
		or (menu and menu ~= session.menu and not background)
		or (index and (not state.ongoing or state.index ~= index))
	then
		return nil
	end
	return model, root, state
end

local function bloxMove(session, object, position, index, generation, check, radius)
	local model, root = bloxReady(session, index)
	if not model or not object:IsDescendantOf(workspace) then
		return nil
	end
	local function valid()
		return active(generation)
			and bloxReady(session, index) == model
			and object:IsDescendantOf(workspace)
			and session.handler:CanParticipate()
			and (not check or check())
	end
	if not valid() then
		return nil
	end
	if (position - root.Position).Magnitude > (radius or 5) then
		local moved, reason = approach(position, generation, object, false, valid)
		if not moved then
			return nil, reason
		end
	end
	if not valid() then
		return nil
	end
	return true
end

local function bloxInteract(session, object, action, index, generation, check)
	local function valid()
		local _, root = bloxReady(session, index)
		local origin = object.Parent and session.interactionData:GetOrigin(object, 6)
		return active(generation)
			and root
			and origin
			and object:IsDescendantOf(workspace)
			and (root.Position - origin.Position).Magnitude <= 8
			and session.handler:CanParticipate()
			and (not check or check())
	end
	if not valid() then
		return nil
	end
	local menu = session.interact:GetMenu()
	if menu and menu ~= session.menu and not (menu.IsBackground and menu.Target == object) then
		return nil, "Close the game's menu to carry on"
	end
	if menu and menu.Target ~= object then
		App.bloxCloseMenu(session)
		menu = nil
	end
	if not menu then
		local ok, result = pcall(session.interact.ShowMenu, session.interact, object, nil, nil, nil, true)
		if not ok then
			session.interactions[object] = nil
			return false, "The interaction didn't open. Retrying."
		end
		menu = result
	end
	if type(menu) ~= "table" then
		return nil, "Waiting for the interaction to appear"
	end
	session.menu = menu
	local function finish(result, detail)
		App.bloxCloseMenu(session)
		if not result then
			session.interactions[object] = nil
		end
		return result, detail
	end
	if not valid() then
		return finish(nil)
	end
	local data = menu.IsCustom and menu.Data
	if type(data) ~= "table" then
		return finish(nil, "Waiting for the minigame controls")
	end
	session.interactions[object] = data
	for _, factory in ipairs(data) do
		if type(factory) ~= "function" then
			continue
		end
		local ok, name, permission, callback = pcall(factory, object)
		if not ok then
			return finish(false, "That interaction changed. Retrying.")
		end
		if name == action and permission == 0 and type(callback) == "function" then
			if not valid() then
				return finish(nil)
			end
			local accepted, result
			if type(menu.Click) == "function" and type(menu.Buttons) == "table" and #menu.Buttons == 1 then
				accepted, result = pcall(menu.Click, menu, 1)
			else
				accepted, result = pcall(callback)
			end
			if not accepted or result == false then
				return finish(false, "That action didn't go through. Retrying.")
			end
			return finish(true)
		end
	end
	return finish(nil, "Waiting for that action to be ready")
end

local function bloxReleaseDoorLook(session)
	local look = session.doorLook
	session.doorLook = nil
	if not look then
		return
	end
	if look.bound then
		pcall(function()
			RunService:UnbindFromRenderStep("HollowBloxDoor")
		end)
	end
	if
		workspace.CurrentCamera == look.camera
		and look.camera.CameraType == look.kind
		and look.camera.CFrame == look.aim
		and App.cameraEpoch == look.epoch
		and character() == look.model
	then
		look.camera.CFrame = look.previous
	end
end

local function bloxKnock(session, object, index, generation, check)
	bloxReleaseDoorLook(session)
	local model = bloxReady(session, index)
	local camera = workspace.CurrentCamera
	if not model or not camera or App.cameraBusy or camera.CameraType == Enum.CameraType.Scriptable then
		return nil, "Waiting for the camera before knocking"
	end
	local look = {
		camera = camera,
		kind = camera.CameraType,
		previous = camera.CFrame,
		epoch = App.cameraEpoch,
		model = model,
	}
	session.doorLook = look
	local function aim()
		if
			session.doorLook ~= look
			or not active(generation)
			or bloxReady(session, index) ~= model
			or not object:IsDescendantOf(workspace)
			or not session.handler:CanParticipate()
			or workspace.CurrentCamera ~= camera
			or camera.CameraType ~= look.kind
			or App.cameraBusy
			or App.cameraEpoch ~= look.epoch
			or (check and not check())
		then
			return false
		end
		local origin = session.interactionData:GetOrigin(object, 6)
		local _, root = character()
		if not origin or not root or (origin.Position - root.Position).Magnitude > 8 then
			return false
		end
		local position = camera.CFrame.Position
		if (origin.Position - position).Magnitude < 0.1 then
			return false
		end
		look.aim = CFrame.lookAt(position, origin.Position)
		camera.CFrame = look.aim
		return true
	end
	local ok, clicked, reason = pcall(function()
		if not aim() then
			return nil, "Waiting to face the matching door"
		end
		look.bound = pcall(function()
			local priority = Enum.RenderPriority.Last and Enum.RenderPriority.Last.Value - 1
				or Enum.RenderPriority.Camera.Value + 1
			RunService:BindToRenderStep("HollowBloxDoor", priority, function()
				pcall(aim)
			end)
		end)
		if not pause(0.12, generation) or not aim() then
			return nil, "The door interaction changed"
		end
		local accepted, why = bloxInteract(session, object, "I_Knock", index, generation, aim)
		if accepted and active(generation) then
			pause(0.18, generation)
		end
		return accepted, why
	end)
	bloxReleaseDoorLook(session)
	if not ok then
		return false, "The door interaction changed. Retrying."
	end
	return clicked, reason
end

local function bloxPace(session, kind, key, shortest, longest, missChance)
	session.pacing = session.pacing or {}
	local timing = session.pacing[kind]
	if not timing or timing.key ~= key then
		local random = session.random or math.random
		local streak = timing and timing.streak or 0
		local readyAt = os.clock() + shortest + random() * (longest - shortest)
		local skip = missChance > 0 and (streak >= 4 or random() < missChance)
		timing = {
			key = key,
			readyAt = readyAt,
			skip = skip,
			streak = skip and 0 or streak + 1,
		}
		session.pacing[kind] = timing
	end
	return not timing.skip and os.clock() >= timing.readyAt, timing.skip
end

local function bloxPumpkin(session, state, generation)
	local target = session.pumpkin
	if target and (not target.object:IsDescendantOf(workspace) or os.clock() - target.at > 2.4) then
		session.pumpkin, target = nil, nil
	end
	if not target then
		local oldest
		for npc in pairs(session.objects.PumpkinPanic) do
			if not npc:IsDescendantOf(workspace) or not npc.Name:find("NPC", 1, true) then
				continue
			end
			for _, object in ipairs(npc:GetChildren()) do
				if object.Name == "ShadowPart" and object:IsA("BasePart") then
					local seen = session.shadows[object]
					if not seen then
						seen = os.clock()
						session.shadows[object] = seen
					end
					if os.clock() - seen <= 2.4 and (not oldest or seen < oldest.at) then
						oldest = { object = object, at = seen }
					end
				end
			end
		end
		target, session.pumpkin = oldest, oldest
	end
	if not target then
		return nil, "Waiting for a pumpkin"
	end
	local ready, skipped = bloxPace(session, "pumpkin", target.object, 0.25, 0.7, 0.2)
	if not ready then
		if skipped and not target.steppedAside then
			target.steppedAside = true
			local _, root = bloxReady(session, state.index)
			local point = target.object.Position
			if root and (point - root.Position).Magnitude < 8 then
				bloxMove(session, target.object, point + Vector3.new(10, 0, 0), state.index, generation)
			end
		end
		return nil, skipped and "Letting this pumpkin go" or "Watching the pumpkin"
	end
	local moved = bloxMove(session, target.object, target.object.Position, state.index, generation, function()
		return session.pumpkin == target and target.object.Parent ~= nil
	end)
	if moved then
		return true, "Waiting under the pumpkin"
	end
	return nil, "Looking for the next pumpkin"
end

local function bloxColorKey(color)
	local hue, saturation, value = color:ToHSV()
	if saturation < 0.15 or value < 0.15 then
		return nil
	end
	return hue, saturation
end

local function bloxChromatic(session, state, generation)
	local center
	for object in pairs(session.objects.ChromaticChaos) do
		if object.Name == "CenterOrb" and object:IsDescendantOf(workspace) then
			center = object:FindFirstChild("LightPart", true)
			if center then
				break
			end
		end
	end
	local hue, saturation
	if center then
		hue, saturation = bloxColorKey(center.Color)
	end
	if not hue then
		return nil, "Waiting for the orb's next color"
	end
	local key = string.format("%.3f:%.3f", hue, saturation)
	local attempt = session.knock
	if attempt and attempt.key == key then
		if state.tasks > attempt.tasks or state.earned > attempt.earned then
			attempt.done = true
		end
		if attempt.done then
			return nil, "Door counted. Waiting for the next color."
		end
		if os.clock() < attempt.retryAt then
			return nil, "Waiting for the knock to count"
		end
	end
	local ready, skipped = bloxPace(session, "color", key, 0.35, 0.9, 0.18)
	if not ready then
		return nil, skipped and "Waiting for the next color" or "Watching the colors"
	end
	local function matches(part)
		if not part or not part.Parent then
			return false
		end
		local h, s = bloxColorKey(part.Color)
		if not h then
			return false
		end
		local difference = math.abs(h - hue)
		return math.min(difference, 1 - difference) < 0.025 and math.abs(s - saturation) < 0.05
	end
	local _, root = bloxReady(session, state.index)
	if not root then
		return nil
	end
	local chosen, light, distance
	for object in pairs(session.objects.ChromaticChaos) do
		if
			object.Name ~= "Tomb"
			or not object:IsDescendantOf(workspace)
			or (session.blocked[object] or 0) > os.clock()
		then
			continue
		end
		local part = object:FindFirstChild("LightPart", true)
		if matches(part) then
			local length = (part.Position - root.Position).Magnitude
			if not distance or length < distance then
				chosen, light, distance = object, part, length
			end
		end
	end
	if not chosen then
		return nil, "Looking for the matching color"
	end
	local function sameColor()
		return center:IsDescendantOf(workspace) and matches(center) and matches(light)
	end
	local origin = session.interactionData:GetOrigin(chosen, 6)
	if not origin then
		return nil, "Waiting for the door to load"
	end
	local moved = bloxMove(session, chosen, origin.Position, state.index, generation, sameColor)
	if not moved then
		session.blocked[chosen] = os.clock() + 2
		return nil, "Looking for a way to the matching tomb"
	end
	local clicked, reason = bloxKnock(session, chosen, state.index, generation, sameColor)
	local retries = attempt and attempt.key == key and (attempt.retries or 0) + 1 or 1
	session.knock = {
		key = key,
		tasks = state.tasks,
		earned = state.earned,
		retries = retries,
		retryAt = os.clock() + math.min(6, 1 + retries),
	}
	if clicked then
		session.blocked[chosen] = os.clock() + 1
	end
	return clicked, reason or "Waiting for the next color"
end

local function bloxRecipeWanted(session)
	local allowed = { Egg = true, Flower = true, Mushroom = true, FrogTears = true }
	for object in pairs(session.objects.RecipeRitual) do
		if object.Name ~= "Book" or not object:IsDescendantOf(workspace) then
			continue
		end
		local animator = object:FindFirstChildWhichIsA("Animator", true)
		if animator then
			local ok, tracks = pcall(animator.GetPlayingAnimationTracks, animator)
			if ok and type(tracks) == "table" then
				for _, track in ipairs(tracks) do
					local read, ingredient = pcall(function()
						return track:GetParameter("Ingredient")
					end)
					if read and type(ingredient) == "string" and allowed[ingredient] then
						return ingredient
					end
				end
			end
		end
	end
	return nil
end

local function bloxRecipe(session, state, generation)
	local model = bloxReady(session, state.index)
	if not model then
		return nil
	end
	local equipped = getPath(state.stats, "EquippedItem")
	local wanted = bloxRecipeWanted(session)
	if not equipped or not wanted then
		return nil, "Checking what the recipe needs"
	end
	local held = session.ingredient
	if held and held.model ~= model then
		session.ingredient, held = nil, nil
	end
	if not held and equipped.Value then
		local name = equipped.Value.Name
		for _, ingredient in ipairs({ "Egg", "Flower", "Mushroom", "FrogTears" }) do
			if name == ingredient then
				held = { model = model, name = ingredient, at = os.clock(), tasks = state.tasks, earned = state.earned }
				session.ingredient = held
				break
			end
		end
	end
	if held then
		if held.delivering then
			if state.tasks > held.tasks or state.earned > held.earned then
				session.ingredient, session.unconfirmed = nil, 0
				return true, "Ingredient delivered"
			end
			local elapsed = os.clock() - held.delivering
			if equipped.Value == nil and elapsed >= 3 then
				session.ingredient = nil
				session.unconfirmed = (session.unconfirmed or 0) + 1
				return nil, "Checking the next recipe"
			end
			if elapsed >= 5 and equipped.Value then
				held.delivering = nil
				held.retryAt = os.clock() + math.min(5, 1 + (held.retries or 0))
				held.retries = (held.retries or 0) + 1
				return nil, "Still holding the ingredient. Retrying the drop-off."
			end
			return nil, "Waiting for the ingredient to land"
		end
		if not equipped.Value then
			if os.clock() - held.at >= 3 then
				session.ingredient = nil
				if held.object then
					session.interactions[held.object] = nil
					session.blocked[held.object] = os.clock() + 2
				end
				return nil, "Missed the pickup. Trying again."
			end
			return nil, "Picking up the ingredient"
		end
		if (held.retryAt or 0) > os.clock() then
			return nil, "Getting ready to try the cauldron again"
		end
		if not bloxPace(session, "recipeDelivery", held, 0.3, 0.8, 0) then
			return nil, "Getting ready to throw"
		end
		for object in pairs(session.objects.RecipeRitual) do
			if object.Name ~= "Cauldron" or not object:IsDescendantOf(workspace) then
				continue
			end
			local area = object:FindFirstChild("DropOffArea", true)
			if not area or not area:IsA("BasePart") then
				continue
			end
			local function carrying()
				return session.ingredient == held and equipped.Value ~= nil
			end
			local moved = bloxMove(session, object, area.Position, state.index, generation, carrying, 0.8)
			if not active(generation) or bloxReady(session, state.index) ~= model then
				return nil
			end
			if moved or equipped.Value == nil then
				held.delivering = os.clock()
				local entry = session.handler._minigames[state.index]
				local controller = entry and entry.Module
				local _, nowRoot = bloxReady(session, state.index)
				if
					equipped.Value
					and controller
					and type(controller.InAreaUpdate) == "function"
					and nowRoot
					and area.Size
				then
					local point, size = area.CFrame:PointToObjectSpace(nowRoot.Position), area.Size
					local inside
					if size.X <= size.Y and size.X <= size.Z then
						inside = math.abs(point.Y) <= size.Y / 2 and math.abs(point.Z) <= size.Z / 2
					elseif size.Y <= size.X and size.Y <= size.Z then
						inside = math.abs(point.X) <= size.X / 2 and math.abs(point.Z) <= size.Z / 2
					else
						inside = math.abs(point.X) <= size.X / 2 and math.abs(point.Y) <= size.Y / 2
					end
					if inside and carrying() then
						pcall(controller.InAreaUpdate, controller, true, nowRoot.Position)
					end
				end
				return true, wanted == held.name and "Delivering " .. held.name or "Clearing the old ingredient"
			end
		end
		return nil, "Waiting for the cauldron to load"
	end
	if equipped.Value then
		return nil, "Put away your item so you can pick up an ingredient"
	end
	local _, root = bloxReady(session, state.index)
	local candidates = {}
	for object in pairs(session.objects.RecipeRitual) do
		if
			object:GetAttribute("Ingredient") == wanted
			and object:GetAttribute("Respawning") ~= true
			and object:IsDescendantOf(workspace)
			and (session.blocked[object] or 0) <= os.clock()
		then
			local origin = session.interactionData:GetOrigin(object, 6)
			if origin and root then
				table.insert(
					candidates,
					{ object = object, point = origin.Position, distance = (origin.Position - root.Position).Magnitude }
				)
			end
		end
	end
	table.sort(candidates, function(a, b)
		return a.distance < b.distance
	end)
	for _, candidate in ipairs(candidates) do
		local object = candidate.object
		local function available()
			return bloxRecipeWanted(session) == wanted
				and object:GetAttribute("Respawning") ~= true
				and equipped.Value == nil
		end
		local ready = bloxPace(session, "recipePickup", object, 0.35, 0.9, 0)
		local timing = session.pacing.recipePickup
		if not timing.breakChosen then
			timing.breakChosen = true
			local random = session.random or math.random
			if random() < 0.15 then
				timing.readyAt += 1.2 + random()
				ready = false
			end
		end
		if not ready then
			return nil, "Checking the recipe"
		end
		local moved = bloxMove(session, object, candidate.point, state.index, generation, available)
		if not moved then
			session.blocked[object] = os.clock() + 3
			continue
		end
		local taken, reason = bloxInteract(session, object, "I_Take", state.index, generation, available)
		if taken then
			session.pacing.recipePickup = nil
			session.ingredient = {
				model = model,
				object = object,
				name = wanted,
				at = os.clock(),
				tasks = state.tasks,
				earned = state.earned,
			}
		elseif taken == false then
			session.interactions[object] = nil
			session.blocked[object] = os.clock() + 2
		end
		return taken, reason or "Picking up " .. wanted
	end
	return nil, "Waiting for an available " .. wanted .. " spawn"
end

local function runBloxburg(generation)
	local checked, owned = pcall(verify, current, true)
	if not active(generation) then
		return false, "Stopped"
	end
	if checked and owned == true then
		return true, "Bloxburg Hollow badge earned"
	end
	local halloween, handler
	while active(generation) do
		status("Loading Bloxburg", "Waiting for the Halloween event", 0)
		local object = waitUntil(function()
			return getPath(App.player, "PlayerScripts", "Modules", "_Event", "HalloweenHandler")
		end, 25, generation)
		if object then
			halloween = module(object, generation)
		end
		if halloween then
			handler = waitUntil(function()
				local value = halloween.SeasonalMinigames
				return type(value) == "table"
					and type(value._minigames) == "table"
					and type(halloween.Modules) == "table"
					and halloween.Modules.InteractionHandler
					and halloween.Modules.BuildUI
					and type(halloween.Shared) == "table"
					and halloween.Shared.InteractionData
					and halloween.Shared.RobloxEventsService
					and halloween.Shared.BadgesService
					and value
			end, 25, generation)
		end
		if handler then
			break
		end
		if not pause(2, generation) then
			return false, "Stopped"
		end
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local shared, config = halloween.Shared, handler.Config
	local goal = shared.RobloxEventsService.ROBLOX_EVENT_STANDARD_BADGE_EVENT_CURRENCY
	if
		goal ~= 15000
		or type(shared.BadgesService.BADGES) ~= "table"
		or shared.BadgesService.BADGES.ROBLOX_STANDARD_HALLOWEEN_EVENT_2026 ~= current.badges[1]
		or type(config) ~= "table"
		or type(config.Minigames) ~= "table"
		or #config.Minigames ~= 3
		or config.Minigames[1] ~= "PumpkinPanic"
		or config.Minigames[2] ~= "ChromaticChaos"
		or config.Minigames[3] ~= "RecipeRitual"
		or type(handler.CanParticipate) ~= "function"
		or type(halloween.Modules.InteractionHandler.ShowMenu) ~= "function"
		or type(halloween.Modules.InteractionHandler.GetMenu) ~= "function"
		or type(halloween.Modules.BuildUI.InBuildMode) ~= "function"
		or type(shared.InteractionData.GetOrigin) ~= "function"
	then
		return false, "Bloxburg's event changed. Try an updated script."
	end
	local session = {
		halloween = halloween,
		handler = handler,
		interact = halloween.Modules.InteractionHandler,
		interactionData = shared.InteractionData,
		interactions = {},
		objects = {},
		blocked = {},
		shadows = setmetatable({}, { __mode = "k" }),
	}
	local connections = {}
	table.insert(App.cleanups, function()
		bloxReleaseDoorLook(session)
		App.bloxCloseMenu(session)
		for _, connection in ipairs(connections) do
			pcall(connection.Disconnect, connection)
		end
	end)
	for _, name in ipairs({ "Area", "PumpkinPanic", "ChromaticChaos", "RecipeRitual" }) do
		local tag = name == "Area" and "SeasonalMinigamesArea" or "SeasonalMinigames:" .. name
		local objects = {}
		session.objects[name] = objects
		table.insert(
			connections,
			connect(Collection:GetInstanceAddedSignal(tag), function(target)
				if active(generation) then
					objects[target] = true
				end
			end)
		)
		table.insert(
			connections,
			connect(Collection:GetInstanceRemovedSignal(tag), function(target)
				objects[target], session.interactions[target], session.blocked[target] = nil, nil, nil
			end)
		)
		for _, target in ipairs(Collection:GetTagged(tag)) do
			objects[target] = true
		end
	end
	local nextBadge, nextAction, errors = 0, 0, 0
	local function step()
		local state = bloxState(session)
		if not state then
			status("Loading Bloxburg", "Waiting for your event progress")
			session.interactions = {}
			return
		end
		local model = character()
		if session.index ~= state.index or session.model ~= model or not state.ongoing then
			bloxReleaseDoorLook(session)
			App.bloxCloseMenu(session)
			session.index, session.model = state.index, model
			session.ingredient, session.pumpkin, session.knock, session.pacing = nil, nil, nil, nil
			session.interactions, session.blocked = {}, {}
			nextAction = 0
		end
		local detail
		if state.earned >= goal then
			detail = "15,000 earned! Waiting for the Hollow badge."
		elseif not bloxReady(session) then
			detail = "Close build mode or any open menus. I'll carry on when you're ready."
		elseif not handler:CanParticipate() then
			detail = "Choose Kid or older to play the minigames"
		else
			local inArea = false
			local _, root = bloxReady(session)
			for area in pairs(session.objects.Area) do
				local collider = area:IsDescendantOf(workspace) and area:FindFirstChild("TouchCollider")
				if collider and collider:IsA("BasePart") then
					local point = collider.CFrame:PointToObjectSpace(root.Position)
					if math.abs(point.X) < collider.Size.X / 2 and math.abs(point.Z) < collider.Size.Z / 2 then
						inArea = true
						break
					end
				end
			end
			if not inArea then
				detail = "Head into the Halloween event arena. I'll start once you're inside."
			elseif not state.ongoing or not state.name then
				detail = "Waiting for the next minigame"
			elseif os.clock() >= nextAction then
				nextAction = os.clock() + (state.name == "PumpkinPanic" and 0.12 or 0.3)
				local played
				if state.name == "PumpkinPanic" then
					played, detail = bloxPumpkin(session, state, generation)
				elseif state.name == "ChromaticChaos" then
					played, detail = bloxChromatic(session, state, generation)
				elseif state.name == "RecipeRitual" then
					played, detail = bloxRecipe(session, state, generation)
				end
				if not active(generation) then
					return
				end
				if played == false then
					errors = math.min(errors + 1, 4)
					nextAction = os.clock() + math.min(6, 0.5 * 2 ^ errors)
					session.interactions = {}
					App.bloxCloseMenu(session)
					detail = "That action didn't go through. Trying again shortly."
				elseif played then
					errors = 0
				end
				session.detail = detail
			else
				detail = session.detail
			end
		end
		if not active(generation) then
			return
		end
		status(
			"Bloxburg Halloween minigames",
			string.format(
				"%d / 15,000 earned  |  %s  |  %d tasks\n%s",
				math.floor(state.earned),
				({ PumpkinPanic = "Pumpkin Panic", ChromaticChaos = "Chromatic Chaos", RecipeRitual = "Recipe Ritual" })[state.name]
					or "Intermission",
				state.tasks,
				detail or "Waiting for the next task"
			),
			math.min(0.95, state.earned / goal * 0.95)
		)
	end
	while active(generation) do
		if os.clock() >= nextBadge then
			nextBadge = os.clock() + 20
			local checked, earned = pcall(verify, current, true)
			if not active(generation) then
				return false, "Stopped"
			end
			if checked and earned == true then
				return true, "Bloxburg Hollow badge earned"
			end
		end
		local ok = pcall(step)
		if not ok and active(generation) then
			errors = math.min(errors + 1, 4)
			bloxReleaseDoorLook(session)
			App.bloxCloseMenu(session)
			session.interactions = {}
			status("Retrying Bloxburg", "Waiting for the task to be ready")
			if not pause(math.min(6, 0.5 * 2 ^ errors), generation) then
				return false, "Stopped"
			end
		end
		if not pause(0.1, generation) then
			return false, "Stopped"
		end
	end
	return false, "Stopped"
end

local function toonLife(moving)
	local model, root, humanoid = character()
	local health = model and model:GetAttribute("Health")
	if
		not model
		or not model:IsDescendantOf(workspace)
		or (type(health) == "number" and health <= 0)
		or (game.PlaceId == current.gameplayPlace and type(health) ~= "number")
	then
		return nil
	end
	if
		moving
		and (
			root.Anchored
			or humanoid.PlatformStand
			or humanoid.Sit
			or model:GetAttribute("Movement") == false
			or model:GetAttribute("Frozen") == true
			or model:GetAttribute("Struggling") == true
			or (workspace.CurrentCamera and workspace.CurrentCamera.CameraType == Enum.CameraType.Scriptable)
		)
	then
		return nil
	end
	return model, root, humanoid
end

local function toonRound()
	local stats = workspace:FindFirstChild("MapStats")
	local floor, playing, completed =
		getPath(stats, "Floor"), getPath(stats, "GameActive"), getPath(stats, "IsFloorCompleted")
	if not floor or not playing or not completed or type(floor.Value) ~= "number" then
		return nil
	end
	local objective = getPath(stats, "MainTask")
	local description = getPath(stats, "TaskDescription")
	return {
		stats = stats,
		floor = floor.Value,
		playing = playing.Value == true,
		completed = completed.Value == true,
		candle = stats:GetAttribute("CandleFloor") == true,
		map = workspace:FindFirstChild("Map"),
		objective = objective and type(objective.Value) == "string" and objective.Value or "",
		description = description and type(description.Value) == "string" and description.Value or "",
	}
end

local function toonRisk(session)
	local stalled = os.clock() - (session.lastProgress or os.clock())
	if stalled >= 90 then
		return { target = 18, approach = 14, panic = 10, chase = 14, stage = 3 }
	elseif stalled >= 40 then
		return { target = 24, approach = 20, panic = 14, chase = 20, stage = 2 }
	elseif stalled >= 15 then
		return { target = 34, approach = 28, panic = 22, chase = 30, stage = 1 }
	end
	return { target = 46, approach = 40, panic = 36, chase = math.huge, stage = 0 }
end

local function toonProgress(session, round)
	local phase = round.objective .. "\n" .. round.description
	local changed = session.phase ~= phase
	session.phase = phase
	session.progressValues = session.progressValues or {}
	local function observe(value)
		if value and type(value.Value) == "number" then
			local before = session.progressValues[value]
			if value.Value > (before or 0) then
				changed = true
			end
			session.progressValues[value] = value.Value
		end
	end
	for _, name in ipairs({ "BarPercentage", "FinishedMachines", "FinishedBigMachines" }) do
		observe(getPath(round.stats, name))
	end
	for object, kind in pairs(session.tasks or {}) do
		if object:IsDescendantOf(workspace) then
			observe(object:FindFirstChild(kind[1]))
		end
	end
	if changed then
		session.lastProgress = os.clock()
		session.explored, session.exploreCount = {}, 0
	end
end

local function toonRepairOnly(round)
	if not round then
		return false
	end
	local main = round.objective:lower()
	if main:find("return to", 1, true) or main:find("get back", 1, true) then
		return false
	end
	for _, text in ipairs({ round.objective, round.description }) do
		local objective = text:lower()
		if
			objective:find("elevator", 1, true)
			and not objective:find("fuse", 1, true)
			and (objective:find("repair", 1, true) or objective:find("fix", 1, true))
		then
			return true
		end
	end
	return false
end

local function toonFusePhase(round)
	if toonRepairOnly(round) then
		return true
	end
	if not round then
		return false
	end
	local main = round.objective:lower()
	if main:find("return to", 1, true) or main:find("get back", 1, true) then
		return false
	end
	for _, objective in ipairs({ round.objective, round.description }) do
		if objective:lower():find("fuse", 1, true) then
			local have, goal = objective:match("(%d+)%s*/%s*(%d+)")
			if not have or tonumber(have) < tonumber(goal) then
				return true
			end
			return false
		end
	end
	return false
end

local function toonEscape(round)
	if not round then
		return false
	end
	if toonFusePhase(round) then
		return false
	end
	if round.completed or not round.playing then
		return true
	end
	local guide = getPath(App.player, "PlayerGui", "ElevatorGuide")
	local pad = guide and guide.Adornee
	return guide and guide.Enabled and pad and pad:IsA("BasePart") and pad:IsDescendantOf(workspace) or false
end

local function toonChased(session, round)
	local chasing = false
	for monster, scope in pairs(session.chasing or {}) do
		if
			typeof(monster) ~= "Instance"
			or not monster:IsDescendantOf(workspace)
			or monster:GetAttribute("Hidden") == true
			or type(scope) == "table" and (scope.floor ~= round.floor or scope.map ~= round.map)
		then
			session.chasing[monster] = nil
		else
			chasing = true
		end
	end
	return chasing
end

local function toonWatchMonsters(session, connections)
	local folder = workspace:FindFirstChild("MonsterFolder")
	if folder == session.monsterFolder then
		return
	end
	for _, connection in ipairs(session.monsterWatches or {}) do
		connection:Disconnect()
	end
	session.monsterFolder, session.monsterWatches, session.monsters, session.chasing = folder, {}, {}, {}
	if not folder then
		return
	end
	for _, monster in ipairs(folder:GetChildren()) do
		session.monsters[monster] = true
	end
	table.insert(
		session.monsterWatches,
		connect(folder.ChildAdded, function(monster)
			session.monsters[monster] = true
		end)
	)
	table.insert(
		session.monsterWatches,
		connect(folder.ChildRemoved, function(monster)
			session.monsters[monster] = nil
			session.chasing[monster] = nil
		end)
	)
	for _, connection in ipairs(session.monsterWatches) do
		table.insert(connections, connection)
	end
end

local function toonThreat(session, point)
	local closest = math.huge
	local remaining
	local function inspect(monster, depth)
		if remaining <= 0 or not monster:IsDescendantOf(workspace) or monster:GetAttribute("Hidden") == true then
			return
		end
		remaining -= 1
		local root = monster:IsA("BasePart") and monster
			or monster:FindFirstChild("HumanoidRootPart")
			or monster:FindFirstChild("RootPart")
			or monster:IsA("Model") and monster.PrimaryPart
		if root and root:IsA("BasePart") then
			closest = math.min(closest, (root.Position - point).Magnitude)
			return
		end
		if depth < 3 and (monster:IsA("Folder") or monster:IsA("Model")) then
			for index, child in ipairs(monster:GetChildren()) do
				if index > 64 or remaining <= 0 then
					break
				end
				if child:IsA("Model") or child:IsA("Folder") or child:IsA("BasePart") then
					inspect(child, depth + 1)
				end
			end
		end
	end
	for monster in pairs(session.monsters or {}) do
		remaining = 48
		inspect(monster, 0)
	end
	return closest
end

local function toonMove(session, point, generation, target, check, cabin)
	local model, root, humanoid = toonLife(true)
	if
		not active(generation)
		or not model
		or typeof(point) ~= "Vector3"
		or point.Y <= workspace.FallenPartsDestroyHeight + 32
		or (check and not check())
	then
		return nil
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	local excluded = { model }
	for _, name in ipairs({
		"Alive",
		"MonsterFolder",
		"OilMachines",
		"Computers",
		"Candies",
		"PathNodes",
		"MonsterSpawnNodes",
	}) do
		local object = workspace:FindFirstChild(name)
		if object then
			table.insert(excluded, object)
		end
	end
	if target then
		table.insert(excluded, target)
	end
	params.FilterDescendantsInstances, params.RespectCanCollide, params.IgnoreWater = excluded, true, true
	local hit = workspace:Raycast(point + Vector3.new(0, 3, 0), Vector3.new(0, -16, 0), params)
	if
		not hit
		or hit.Normal.Y < 0.65
		or hit.Position.Y > point.Y + 1
		or hit.Position.Y <= workspace.FallenPartsDestroyHeight + 32
	then
		return nil, "Waiting for safe ground"
	end
	local position = hit.Position + Vector3.new(0, math.max(2.6, humanoid.HipHeight + root.Size.Y / 2), 0)
	if cabin then
		local offset = cabin.CFrame:PointToObjectSpace(position)
		if
			math.abs(offset.X) >= cabin.Size.X / 2 - 1
			or math.abs(offset.Z) >= cabin.Size.Z / 2 - 1
			or math.abs(offset.Y) >= cabin.Size.Y / 2
		then
			return nil, "Waiting for room inside the elevator"
		end
	end
	local round = toonRound()
	local flood = round and round.stats:GetAttribute("FloodLevel")
	local head = model:FindFirstChild("Head")
	local headOffset = head and head:IsA("BasePart") and head.Position.Y - root.Position.Y or 1.5
	if
		round
		and round.stats:GetAttribute("FloodActive") == true
		and type(flood) == "number"
		and position.Y + math.max(1.5, headOffset) <= flood + 0.5
	then
		return nil, "That spot is flooded"
	end
	if workspace:Raycast(position, Vector3.new(0, 3, 0), params) then
		return nil, "Not enough room to stand there"
	end
	if not active(generation) or toonLife(true) ~= model or (check and not check()) then
		return nil
	end
	root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	local transform = CFrame.new(position) * root.CFrame.Rotation
	model:PivotTo(transform * root.CFrame:ToObjectSpace(model:GetPivot()))
	return true
end

local function toonElevator(round)
	local map = round and round.map
	if map and map:GetAttribute("ExitElevator") == "ExitElevator" then
		return getPath(map, "SpecialFolder", "ExitElevator")
	end
	local guide = getPath(App.player, "PlayerGui", "ElevatorGuide")
	local pad = guide and guide.Adornee
	if
		guide
		and guide.Enabled
		and pad
		and pad:IsA("BasePart")
		and pad.Name == "TeleportPart"
		and pad:IsDescendantOf(workspace)
	then
		return pad.Parent
	end
	return workspace:FindFirstChild("Elevator")
end

local function toonRefuge(session, generation, returning)
	local model, root = toonLife(true)
	if not model then
		return nil, "Waiting until you can move"
	end
	local round = toonRound()
	local elevator = toonElevator(round)
	local pad, cabin = getPath(elevator, "TeleportPart"), getPath(elevator, "Hitbox")
	local spots = {}
	if pad and pad:IsA("BasePart") then
		cabin = cabin and cabin:IsA("BasePart") and cabin or nil
		local side, depth = cabin and math.min(6, cabin.Size.X / 4) or 2, cabin and math.min(6, cabin.Size.Z / 4) or 2
		local frame = cabin and cabin.CFrame or pad.CFrame
		for _, offset in ipairs({ { 0, 0 }, { 0, depth }, { 0, -depth }, { -side, 0 }, { side, 0 } }) do
			local point = pad.Position + frame.RightVector * offset[1] + frame.LookVector * offset[2]
			local space = toonThreat(session, point)
			if returning or space >= 30 then
				table.insert(spots, { point = point, clearance = space, cabin = cabin, order = #spots + 1 })
			end
		end
	end
	table.sort(spots, function(a, b)
		if returning then
			return a.order < b.order
		end
		return a.clearance > b.clearance or a.clearance == b.clearance and a.order < b.order
	end)
	if os.clock() < (session.nextRetreat or 0) and (not returning or session.wasReturning) then
		return nil, returning and "Heading back to the exit" or "Checking a safe place to wait"
	end
	session.wasReturning = returning
	session.nextRetreat = os.clock() + (returning and 0.25 or 0.75)
	local function trySpot(spot)
		local point = spot.point
		local offset = root.Position - point
		local inside = spot.cabin and spot.cabin.CFrame:PointToObjectSpace(root.Position)
		local reached = inside
				and math.abs(inside.X) < spot.cabin.Size.X / 2 - 1
				and math.abs(inside.Z) < spot.cabin.Size.Z / 2 - 1
				and math.abs(inside.Y) < spot.cabin.Size.Y / 2
			or not spot.cabin
				and math.abs(offset.X) <= 1.5
				and math.abs(offset.Z) <= 1.5
				and math.abs(offset.Y) <= 6
		if
			(returning and reached or not returning and offset.Magnitude <= 5)
			and (returning or toonThreat(session, root.Position) >= 30)
		then
			return true
		end
		return toonMove(session, point, generation, spot.cabin, function()
			local latest = toonRound()
			return toonLife(true) == model
				and toonElevator(latest) == elevator
				and (not round or latest and latest.floor == round.floor and latest.map == round.map)
				and (returning or toonThreat(session, point) >= 30)
		end, spot.cabin)
	end
	for _, spot in ipairs(spots) do
		if trySpot(spot) then
			return true, returning and "Waiting inside the elevator" or "Waiting away from the monsters"
		end
	end
	if returning then
		return nil, "Waiting for safe ground inside the exit elevator"
	end
	do
		local nodes = workspace:FindFirstChild("PathNodes")
		local candidates, count = {}, 0
		for _, node in ipairs(nodes and nodes:GetChildren() or {}) do
			count += 1
			if count > 128 then
				break
			end
			if not node:IsA("BasePart") then
				continue
			end
			local space = toonThreat(session, node.Position)
			if space >= 42 then
				table.insert(candidates, { point = node.Position, clearance = space, order = count })
			end
		end
		table.sort(candidates, function(a, b)
			return a.clearance > b.clearance or a.clearance == b.clearance and a.order < b.order
		end)
		for index = 1, math.min(4, #candidates) do
			if trySpot(candidates[index]) then
				return true, "Waiting away from the monsters"
			end
		end
	end
	return nil, "Looking for a hiding spot"
end

local function toonEndPrompt(session)
	local request = session.promptRequest
	session.promptRequest = nil
	if request and not request.done and request.thread then
		pcall(task.cancel, request.thread)
	end
	local held = session.holding
	session.holding = nil
	if held then
		pcall(held.InputHoldEnd, held)
	end
	local touching = session.touching
	session.touching = nil
	if touching and type(firetouchinterest) == "function" then
		pcall(firetouchinterest, touching.root, touching.part, 1)
	end
end

local function toonRelease(session)
	toonEndPrompt(session)
	local box = session.boxOwned
	session.boxOwned, session.breaker = nil, nil
	if box and App.player.Character == box.model then
		local gui = getPath(App.player, "PlayerGui", "HUD", "BlackoutBox")
		if gui and gui.Visible and App.player:GetAttribute("BoxOpen") == true then
			gui.Visible = false
		end
	end
	local owned = session.working
	local binding = session.input and session.input.Actions.SkillCheckExit
	if
		not owned
		or not binding
		or session.leaving == binding
		or App.player.Character ~= owned.model
		or (binding.OwnerTag ~= "OilMachineClient" and binding.OwnerTag ~= "ComputerClient")
	then
		return
	end
	session.leaving = binding
	task.spawn(function()
		if App.player.Character == owned.model and session.input.Actions.SkillCheckExit == binding then
			local ok, reason = pcall(binding.OnAction, Enum.UserInputState.Begin)
			if not ok then
				log("Couldn't leave the machine: " .. tostring(reason))
			end
		end
	end)
end

local function toonPromptPoint(prompt)
	local parent = prompt and prompt.Parent
	return parent and (parent:IsA("Attachment") and parent.WorldPosition or positionOf(parent))
end

local function toonPrompt(session, prompt, generation, check, accepted, fullHold)
	local model, root = toonLife(true)
	if
		not model
		or not active(generation)
		or not prompt
		or not prompt:IsA("ProximityPrompt")
		or not prompt.Enabled
		or not prompt:IsDescendantOf(workspace)
		or (check and not check())
	then
		return nil
	end
	local point = toonPromptPoint(prompt)
	if not point or (point - root.Position).Magnitude > prompt.MaxActivationDistance - 0.5 then
		return nil
	end
	local duration = prompt.HoldDuration
	if type(duration) ~= "number" or duration ~= duration or duration < 0 or duration > (fullHold and 120 or 30) then
		return nil
	end
	local initial = toonRound()
	local holdUntil, inputOwned
	local function finish(result, reason)
		toonEndPrompt(session)
		return result, reason
	end
	local function poll()
		if not active(generation) then
			return nil, "Stopped"
		end
		local nowModel, nowRoot = toonLife(false)
		if
			nowModel ~= model
			or (nowRoot.Position - point).Magnitude > prompt.MaxActivationDistance
			or toonThreat(session, nowRoot.Position) < toonRisk(session).panic
		then
			return nil, "Leaving that prompt"
		end
		local acknowledgement = accepted and accepted()
		if acknowledgement then
			if
				not fullHold
				or acknowledgement == "session"
				or acknowledgement == "complete"
				or holdUntil and os.clock() >= holdUntil
			then
				return true
			end
		end
		if not toonLife(true) then
			local camera = workspace.CurrentCamera
			local _, _, humanoid = toonLife(false)
			if
				not (
					fullHold
					and inputOwned
					and humanoid
					and not humanoid.Sit
					and not humanoid.PlatformStand
					and model:GetAttribute("Frozen") ~= true
					and model:GetAttribute("Struggling") ~= true
					and not (camera and camera.CameraType == Enum.CameraType.Scriptable)
				)
			then
				return nil, "Waiting until you can move"
			end
		end
		return "waiting"
	end
	local function waitFor(seconds)
		local deadline = os.clock() + seconds
		repeat
			local result, reason = poll()
			if result ~= "waiting" then
				return result, reason
			end
			local round = toonRound()
			if
				not round
				or not initial
				or round.floor ~= initial.floor
				or round.map ~= initial.map
				or (not round.playing or round.completed) and not toonFusePhase(round)
				or toonEscape(round)
			then
				return nil, "The floor changed"
			end
			task.wait(0.03)
		until os.clock() >= deadline
		return "waiting"
	end
	local function ready()
		return prompt:IsDescendantOf(workspace) and prompt.Enabled and (not check or check())
	end
	local result, reason = waitFor(0.25)
	if result ~= "waiting" or not ready() then
		return finish(result == true and true or nil, reason)
	end
	local started = pcall(prompt.InputHoldBegin, prompt)
	if started then
		session.holding = prompt
		inputOwned = true
	end
	holdUntil = os.clock() + duration + 0.1
	result, reason = waitFor(duration + 0.12)
	toonEndPrompt(session)
	if result ~= "waiting" then
		return finish(result, reason)
	end
	if started then
		result, reason = waitFor(1.2)
		if result ~= "waiting" then
			return finish(result, reason)
		end
	end
	if type(fireproximityprompt) == "function" and ready() then
		local request = {}
		session.promptRequest = request
		if fullHold then
			holdUntil, inputOwned = os.clock() + duration + 0.1, true
		end
		request.thread = task.spawn(function()
			if active(generation) and ready() then
				request.ok, request.reason = pcall(fireproximityprompt, prompt)
			end
			request.done = true
		end)
		result, reason = waitFor(duration + 1.5)
		if result ~= "waiting" then
			return finish(result, reason)
		end
		if request.done and not request.ok then
			log("Couldn't trigger that prompt: " .. tostring(request.reason))
		end
	end
	return finish(false, "That prompt didn't start. I'll retry it.")
end

local function toonSkillWindow(kind)
	if kind == "OilMachineSkillCheck" then
		local main = getPath(App.player, "PlayerGui", "LockUI", "HUD", "Skillcheck", "Main")
		local marker, objective = getPath(main, "Marker"), getPath(main, "Objective")
		if
			not marker
			or not objective
			or not marker.Visible
			or not objective.Visible
			or objective.AbsoluteSize.X <= 0
		then
			return false
		end
		local ratio = (marker.AbsolutePosition.X - objective.AbsolutePosition.X) / objective.AbsoluteSize.X
		return ratio >= 0.36 and ratio <= 0.44
	elseif kind == "ComputerSkillCheck" then
		local main = getPath(App.player, "PlayerGui", "RoundSkillcheck", "Container", "Normal")
		local aim, target = getPath(main, "AimImage"), getPath(main, "Target")
		if not main or not main.Visible or not aim or not target then
			return false
		end
		local angle = (aim.Rotation + 360) % 360 - 180
		local left = (target.Rotation - 30 + 180) % 360 - 180
		local right = (target.Rotation + 30 + 180) % 360 - 180
		local inside = left < right and angle >= left and angle <= right
			or left >= right and (angle >= left or angle <= right)
		if not inside then
			return false
		end
		local ratio = math.abs((angle - left + 180) % 360 - 180) / 60
		return ratio >= 0.36 and ratio <= 0.44
	end
	return false
end

local function toonSkill(session, generation)
	local work = session.working
	local model, root = toonLife(false)
	if not work or model ~= work.model then
		return nil
	end
	if toonEscape(toonRound()) then
		toonRelease(session)
		session.working = nil
		return nil
	end
	local exit = session.input.Actions.SkillCheckExit
	if exit and (exit.OwnerTag == "OilMachineClient" or exit.OwnerTag == "ComputerClient") then
		work.started = true
		if
			toonThreat(session, root.Position) < (work.risk or toonRisk(session)).panic
			or os.clock() - math.max(work.at, session.lastProgress or work.at) > 90
		then
			session.blocked[work.object] = os.clock() + 10
			toonRelease(session)
			return true, "A monster is close. Leaving the machine."
		end
		local binding = session.input.Actions.SkillCheckHit
		if binding and session.hitBinding ~= binding and toonSkillWindow(binding.OwnerTag) and active(generation) then
			session.hitBinding = binding
			task.spawn(function()
				if
					active(generation)
					and session.working == work
					and toonLife(false) == model
					and session.input.Actions.SkillCheckHit == binding
					and toonThreat(session, root.Position) >= (work.risk or toonRisk(session)).panic
					and toonSkillWindow(binding.OwnerTag)
				then
					local ok, reason = pcall(binding.OnAction, Enum.UserInputState.Begin)
					if not ok then
						log("Couldn't finish the skill check: " .. tostring(reason))
						toonRelease(session)
					end
				elseif session.hitBinding == binding then
					session.hitBinding = nil
				end
			end)
		end
		return true, "Working on the machine"
	end
	if work.started or os.clock() - work.at > 4 then
		session.blocked[work.object] = os.clock() + (work.started and 1 or 8)
		session.working, session.leaving, session.hitBinding = nil, nil, nil
		return nil
	end
	if toonThreat(session, root.Position) < (work.risk or toonRisk(session)).panic then
		session.working = nil
		return nil
	end
	return true, "Waiting for the machine to start"
end

local function toonTasks(session, round)
	if session.taskMap ~= round.map or session.taskFloor ~= round.floor then
		for _, connection in ipairs(session.taskWatches or {}) do
			connection:Disconnect()
		end
		session.taskMap, session.tasks, session.taskQueue, session.taskHead, session.taskSeen, session.taskWatches =
			round.map, {}, {}, 1, {}, {}
		session.taskFloor = round.floor
		session.fusePrompts, session.fuseParts = {}, {}
		session.taskRoots = setmetatable({}, { __mode = "k" })
		if not session.taskCleanup then
			session.taskCleanup = true
			table.insert(App.cleanups, function()
				for _, connection in ipairs(session.taskWatches or {}) do
					connection:Disconnect()
				end
			end)
		end
		local function enqueue(object, refresh)
			if object and object:IsA("ProximityPrompt") then
				session.fusePrompts[object] = true
				return
			end
			if object and object:IsA("BasePart") then
				local name = object.Name:lower():gsub("[^%w]", "")
				if name == "fuse" or name == "fusepickup" or name:match("^fuse%d+$") then
					session.fuseParts[object] = true
				end
				if #object:GetChildren() == 0 then
					return
				end
			end
			if
				object
				and (object:IsA("Model") or object:IsA("Folder") or object:IsA("BasePart") or object:IsA("Attachment") or object:IsA(
					"ProximityPrompt"
				))
				and (refresh or not session.taskSeen[object])
			then
				session.taskSeen[object] = true
				table.insert(session.taskQueue, object)
			end
		end
		session.taskEnqueue = enqueue
		local roots = { round.map }
		for _, name in ipairs({ "Computers", "OilMachines", "Fuses", "Items", "Elevator" }) do
			local root = workspace:FindFirstChild(name)
			if root then
				table.insert(roots, root)
			end
		end
		for _, root in ipairs(workspace:GetChildren()) do
			if root.Name:lower():find("fuse", 1, true) then
				table.insert(roots, root)
			end
		end
		local function watch(root)
			if root and not session.taskRoots[root] then
				session.taskRoots[root] = true
				enqueue(root)
				table.insert(
					session.taskWatches,
					connect(root.DescendantAdded, function(object)
						if object.Name == "ComputerPercentage" or object.Name == "OilValue" then
							enqueue(object.Parent, true)
						else
							enqueue(object)
						end
					end)
				)
			end
		end
		session.taskWatch = watch
		for _, root in ipairs(roots) do
			watch(root)
		end
		table.insert(
			session.taskWatches,
			connect(workspace.ChildAdded, function(root)
				if
					root.Name:lower():find("fuse", 1, true)
					or root.Name == "Elevator"
					or root.Name == "Computers"
					or root.Name == "OilMachines"
					or root.Name == "Items"
				then
					watch(root)
				end
			end)
		)
	end
	if session.taskWatch then
		session.taskWatch(toonElevator(round))
	end
	for _ = 1, 64 do
		local object = session.taskQueue[session.taskHead]
		if not object then
			session.taskQueue, session.taskHead = {}, 1
			break
		end
		session.taskHead += 1
		if not object:IsDescendantOf(workspace) then
			session.tasks[object] = nil
			continue
		end
		if object:IsA("Model") then
			if object:FindFirstChild("ComputerPercentage") then
				session.tasks[object] = { "ComputerPercentage", "ComputerClient" }
			elseif object:FindFirstChild("OilValue") then
				session.tasks[object] = { "OilValue", "OilMachineClient" }
			end
			local name = object.Name:lower():gsub("[^%w]", "")
			if name == "fuse" or name == "fusepickup" or name:match("^fuse%d+$") then
				local part = object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart")
				if part then
					session.fuseParts[part] = true
				end
			end
		end
		if object:IsA("ProximityPrompt") then
			session.fusePrompts[object] = true
		elseif object:IsA("BasePart") then
			local name = object.Name:lower():gsub("[^%w]", "")
			if name == "fuse" or name == "fusepickup" or name:match("^fuse%d+$") then
				session.fuseParts[object] = true
			end
		end
		for _, child in ipairs(object:GetChildren()) do
			session.taskEnqueue(child)
		end
	end
	return session.tasks
end

local function toonFuseHeld()
	local amount
	for _, object in ipairs({ App.player, App.player.Character }) do
		if object then
			for _, name in ipairs({ "HasFuse", "HoldingFuse", "CarryingFuse", "FuseCount", "Fuses" }) do
				local value = object:GetAttribute(name)
				local child = object:FindFirstChild(name)
				if
					value == nil
					and child
					and (child:IsA("BoolValue") or child:IsA("IntValue") or child:IsA("NumberValue"))
				then
					value = child.Value
				end
				if type(value) == "boolean" or type(value) == "number" then
					local count = value == true and 1 or type(value) == "number" and value or 0
					amount = math.max(amount or 0, count)
				end
			end
		end
	end
	return amount
end

local function toonFuseRole(prompt)
	local action = prompt.ActionText:lower()
	if action:find("buy", 1, true) or action:find("purchase", 1, true) or action:find("sell", 1, true) then
		return nil
	end
	local direct = (prompt.Name .. " " .. prompt.ObjectText):lower()
	if direct:find("shop", 1, true) or direct:find("store", 1, true) then
		return nil
	end
	local hints = prompt.Name .. " " .. prompt.ObjectText .. " " .. action
	local parent = prompt.Parent
	for _ = 1, 8 do
		if not parent or parent == workspace then
			break
		end
		hints ..= " " .. parent.Name
		parent = parent.Parent
	end
	hints = hints:lower()
	if not hints:find("fuse", 1, true) then
		if
			hints:find("elevator", 1, true)
			and (
				action:find("repair", 1, true)
				or action:find("fix", 1, true)
				or prompt.Name:lower():find("repair", 1, true)
			)
		then
			return "repair"
		end
		return nil
	end
	if action:find("pick", 1, true) or action:find("collect", 1, true) or action:find("grab", 1, true) then
		return "pickup"
	end
	if
		hints:find("box", 1, true)
		or action:find("insert", 1, true)
		or action:find("place", 1, true)
		or action:find("repair", 1, true)
		or action:find("deposit", 1, true)
	then
		return "box"
	end
	return "pickup"
end

local function toonWatchBreaker(session, connections, generation)
	local remote = getPath(Storage, "Remotes", "RecvBreakerData")
	if session.breakerRemote == remote then
		return
	end
	if session.breakerConnection then
		session.breakerConnection:Disconnect()
	end
	session.breakerRemote, session.breakerConnection = remote, nil
	if not remote or not remote:IsA("RemoteEvent") then
		return
	end
	local connection = connect(remote.OnClientEvent, function(data)
		local owned, round = session.boxOwned, toonRound()
		if
			not active(generation)
			or not owned
			or not round
			or App.player.Character ~= owned.model
			or owned.floor ~= round.floor
			or owned.map ~= round.map
		then
			return
		end
		if data == "Completed" then
			session.breaker = session.breaker or {}
			session.breaker.completed = true
		elseif type(data) == "table" then
			for index = 1, 7 do
				if type(data[index]) ~= "boolean" then
					return
				end
			end
			session.breaker = session.breaker or {}
			session.breaker.values = table.clone(data)
		end
	end)
	session.breakerConnection = connection
	table.insert(connections, connection)
end

local function toonBreaker(session, round, generation)
	local owned = session.boxOwned
	if not owned then
		return nil
	end
	local model, root = toonLife(false)
	local gui = getPath(App.player, "PlayerGui", "HUD", "BlackoutBox")
	if
		not active(generation)
		or model ~= owned.model
		or owned.floor ~= round.floor
		or owned.map ~= round.map
		or toonEscape(round)
		or toonThreat(session, root.Position) < (owned.risk or toonRisk(session)).panic
	then
		toonRelease(session)
		return nil
	end
	if not gui or not gui.Visible then
		if not owned.guiSeen and os.clock() - owned.at < 4 then
			return true, "Waiting for the fusebox controls to open"
		end
		session.boxOwned, session.breaker = nil, nil
		return nil
	end
	owned.guiSeen = true
	local state = session.breaker
	if state and state.completed then
		session.lastProgress, session.wantFuseBox = os.clock(), false
		toonRelease(session)
		return nil
	end
	if state and state.values then
		if state.sent then
			if state.values[state.sent] == true then
				session.lastProgress = os.clock()
				state.sent = nil
			elseif os.clock() - state.at > 3 then
				session.blocked[owned.prompt] = os.clock() + 10
				toonRelease(session)
				return nil, "The fusebox didn't confirm that switch. Trying again shortly."
			end
		end
		if not state.sent and os.clock() >= (state.nextFlip or 0) then
			for index = 1, 7 do
				if state.values[index] == false then
					local remote = getPath(Storage, "Remotes", "SendBreakerData")
					local sent = fire(remote, "FuseFlip", index)
					if sent then
						state.sent, state.at = index, os.clock()
					end
					state.nextFlip = os.clock() + 0.4
					break
				end
			end
		end
	end
	if os.clock() - owned.at > 20 then
		session.blocked[owned.prompt] = os.clock() + 10
		toonRelease(session)
		return nil, "The fusebox is taking too long. Looking for another route."
	end
	return true, "Repairing the fusebox"
end

local function toonFuses(session, round, generation)
	if not toonFusePhase(round) then
		return nil
	end
	local model, root = toonLife(true)
	if not model or not round.map then
		return nil
	end
	toonTasks(session, round)
	local risk, held = toonRisk(session), toonFuseHeld()
	local repairing = toonRepairOnly(round)
	local pickup, box
	local function consider(object, role, prompt)
		if
			not object:IsDescendantOf(workspace)
			or (session.blocked[object] or 0) > os.clock()
			or object:IsDescendantOf(model)
		then
			return
		end
		local alive = workspace:FindFirstChild("Alive")
		if alive and object:IsDescendantOf(alive) then
			return
		end
		local point = prompt and toonPromptPoint(prompt) or object.Position
		if not point or toonThreat(session, point) < risk.target then
			return
		end
		local distance = (point - root.Position).Magnitude
		local candidate = { object = object, prompt = prompt, role = role, point = point, distance = distance }
		if role == "box" or role == "repair" then
			if not box or role == "repair" and box.role ~= "repair" or role == box.role and distance < box.distance then
				box = candidate
			end
		elseif not pickup or distance < pickup.distance then
			pickup = candidate
		end
	end
	for prompt in pairs(session.fusePrompts or {}) do
		if not prompt:IsDescendantOf(workspace) then
			session.fusePrompts[prompt] = nil
			continue
		end
		if prompt:IsDescendantOf(workspace) and prompt.Enabled then
			local role = toonFuseRole(prompt)
			if role == "box" then
				session.fuseBoxSeen = true
			end
			if role and (not repairing or role ~= "pickup") and (repairing or role ~= "repair") then
				consider(prompt, role, prompt)
			end
		end
	end
	for part in pairs(not repairing and session.fuseParts or {}) do
		local parent = part.Parent
		if
			parent
			and part.CanTouch ~= false
			and not part:FindFirstChildWhichIsA("ProximityPrompt", true)
			and not (parent:IsA("Model") and parent:FindFirstChildWhichIsA("ProximityPrompt", true))
		then
			consider(part, "pickup", nil)
		end
	end
	if not repairing and not box and (held and held > 0 or session.wantFuseBox and session.fuseBoxSeen) then
		return nil, "Got a fuse, looking for the fusebox"
	end
	local chosen = repairing and box
		or box and (session.wantFuseBox or held and held > 0 or not pickup) and box
		or pickup
	if not chosen then
		return nil,
			repairing and "No repair control is visible yet. Staying by the elevator."
				or "Looking for fuse pickups and the fusebox"
	end
	local beforeObjective, beforeDescription, beforeBar =
		round.objective, round.description, getPath(round.stats, "BarPercentage")
	beforeBar = beforeBar and beforeBar.Value
	local boxGui = getPath(App.player, "PlayerGui", "HUD", "BlackoutBox")
	local boxWasOpen = boxGui and boxGui.Visible
	local beforeBinding = session.input.Actions.SkillCheckExit
	local function valid()
		local latest = toonRound()
		return active(generation)
			and toonLife(true) == model
			and latest
			and latest.floor == round.floor
			and latest.map == round.map
			and toonFusePhase(latest)
			and chosen.object:IsDescendantOf(workspace)
			and (not chosen.prompt or chosen.prompt.Enabled)
			and toonThreat(session, chosen.point) >= toonRisk(session).approach
	end
	local direction = chosen.prompt and chosen.prompt.Parent
	if direction and direction:IsA("Attachment") then
		direction = direction.Parent
	elseif direction and direction:IsA("Model") then
		direction = direction.PrimaryPart or direction:FindFirstChildWhichIsA("BasePart")
	end
	local point = chosen.point
	if direction and direction:IsA("BasePart") then
		point += direction.CFrame.LookVector * math.min(2.5, chosen.prompt.MaxActivationDistance * 0.35)
	end
	local target = direction and direction:IsA("BasePart") and direction or chosen.object
	local moved, why = toonMove(session, point, generation, target, valid)
	if not moved then
		session.blocked[chosen.object] = os.clock() + 5
		return nil, why
	end
	if chosen.role ~= "pickup" then
		session.breaker = nil
		session.boxOwned = {
			model = model,
			floor = round.floor,
			map = round.map,
			prompt = chosen.prompt,
			at = os.clock(),
			risk = risk,
		}
	end
	local function accepted()
		local latest = toonRound()
		if not latest or latest.floor ~= round.floor or latest.map ~= round.map then
			return false
		end
		local nowHeld = toonFuseHeld()
		local bar = getPath(latest.stats, "BarPercentage")
		boxGui = getPath(App.player, "PlayerGui", "HUD", "BlackoutBox")
		if chosen.role == "pickup" then
			return latest.objective ~= beforeObjective
				or beforeBar and bar and bar.Value > beforeBar
				or not chosen.object:IsDescendantOf(workspace)
				or chosen.object:IsDescendantOf(model)
				or nowHeld and nowHeld > (held or 0)
				or chosen.object:GetAttribute("Collected") == true
		end
		if chosen.role ~= "pickup" then
			local binding = session.input.Actions.SkillCheckExit
			if
				binding
				and binding ~= beforeBinding
				and (binding.OwnerTag == "ComputerClient" or binding.OwnerTag == "OilMachineClient")
			then
				session.working = { object = chosen.object, model = model, at = os.clock(), risk = risk }
				session.boxOwned = nil
				return "session"
			end
		end
		if
			not boxWasOpen and boxGui and boxGui.Visible and App.player:GetAttribute("BoxOpen") == true
			or session.breaker ~= nil
		then
			local owned = session.boxOwned
			if owned and not owned.opened then
				owned.opened, owned.at = true, os.clock()
			end
			return "session"
		end
		if latest.objective ~= beforeObjective or latest.description ~= beforeDescription then
			return repairing and not toonRepairOnly(latest) and "complete" or true
		end
		return beforeBar and bar and bar.Value > beforeBar or held and nowHeld and nowHeld < held
	end
	local used, reason
	if chosen.prompt then
		used, reason = toonPrompt(session, chosen.prompt, generation, valid, accepted, repairing)
	else
		if not accepted() and type(firetouchinterest) == "function" then
			local request = {}
			session.promptRequest = request
			session.touching = { root = root, part = chosen.object }
			request.thread = task.spawn(function()
				if active(generation) and valid() and (root.Position - chosen.point).Magnitude <= 8 then
					pcall(firetouchinterest, root, chosen.object, 0)
				end
				request.done = true
			end)
		end
		local began = os.clock()
		while active(generation) and os.clock() - began < 1.5 do
			local nowModel, nowRoot = toonLife(false)
			if nowModel ~= model or toonThreat(session, nowRoot.Position) < toonRisk(session).panic then
				break
			end
			if accepted() then
				used = true
				break
			end
			if not valid() then
				break
			end
			task.wait(0.05)
		end
		toonEndPrompt(session)
	end
	session.blocked[chosen.object] = os.clock() + (used and chosen.role ~= "pickup" and 0.5 or used and 3 or 8)
	if used then
		local latest, nowHeld = toonRound(), toonFuseHeld()
		boxGui = getPath(App.player, "PlayerGui", "HUD", "BlackoutBox")
		local bar = latest and getPath(latest.stats, "BarPercentage")
		if
			chosen.role == "pickup"
			or latest and (latest.objective ~= beforeObjective or latest.description ~= beforeDescription)
			or beforeBar and bar and bar.Value > beforeBar
			or held and nowHeld and nowHeld < held
		then
			session.lastProgress = os.clock()
		end
		session.wantFuseBox = chosen.role == "pickup"
		if chosen.role ~= "pickup" and not session.breaker and not (boxGui and boxGui.Visible) then
			session.boxOwned, session.breaker = nil, nil
		end
		return true,
			repairing and "Repairing the elevator"
				or chosen.role == "pickup" and "Picked up a fuse. Taking it back."
				or "Returning fuses to the fusebox"
	end
	if chosen.role ~= "pickup" then
		toonRelease(session)
		session.wantFuseBox = false
	end
	return nil,
		reason
			or (
				repairing and "That repair hasn't confirmed yet. Checking again shortly."
				or "That fuse hasn't confirmed yet. Checking another one."
			)
end

local function toonExplore(session, round, generation)
	local model, root = toonLife(true)
	if
		not model
		or toonEscape(round)
		or toonRepairOnly(round)
		or not round.map
		or os.clock() - (session.lastProgress or os.clock()) < 12
	then
		return nil
	end
	if os.clock() < (session.nextExplore or 0) then
		return nil
	end
	local folder = workspace:FindFirstChild("PathNodes")
	local nodes = folder and folder:GetChildren() or {}
	if #nodes == 0 then
		return nil
	end
	session.explored = session.explored or {}
	local best, distance
	for _ = 1, math.min(64, #nodes) do
		session.exploreCursor = (session.exploreCursor or 0) % #nodes + 1
		local node = nodes[session.exploreCursor]
		if
			node:IsA("BasePart")
			and (session.explored[node] or -math.huge) < os.clock() - 60
			and toonThreat(session, node.Position) >= toonRisk(session).target
		then
			local length = (node.Position - root.Position).Magnitude
			if length > 10 and (not distance or length < distance) then
				best, distance = node, length
			end
		end
	end
	if not best then
		return nil
	end
	session.nextExplore, session.explored[best] = os.clock() + 2, os.clock()
	if os.clock() >= (session.nextStream or 0) then
		session.nextStream = os.clock() + 4
		task.spawn(function()
			if active(generation) then
				pcall(function()
					App.player:RequestStreamAroundAsync(best.Position, 2)
				end)
			end
		end)
	end
	local moved, why = toonMove(session, best.Position, generation, nil, function()
		local latest = toonRound()
		return active(generation)
			and toonLife(true) == model
			and latest
			and latest.floor == round.floor
			and latest.map == round.map
			and not toonEscape(latest)
			and toonThreat(session, best.Position) >= toonRisk(session).approach
	end)
	return moved, moved and "Checking another part of the floor for objectives" or why
end

local function toonObjective(session, round, generation)
	local model, root = toonLife(true)
	if not model or not round.map or not round.map:IsDescendantOf(workspace) then
		return nil
	end
	local tasks = toonTasks(session, round)
	local risk = toonRisk(session)
	local chosen, distance
	local function consider(object, progress, candle, owner)
		if
			not object:IsA("Model")
			or not object:IsDescendantOf(workspace)
			or (session.blocked[object] or 0) > os.clock()
		then
			return
		end
		local part = object:FindFirstChild("PromptPart") or object.PrimaryPart
		local prompt = candle and object:FindFirstChild("SnuffPrompt", true)
			or getPath(part, "ProximityPrompt")
			or part and part:FindFirstChildWhichIsA("ProximityPrompt", true)
		if
			not part
			or not part:IsA("BasePart")
			or not prompt
			or not prompt:IsA("ProximityPrompt")
			or not prompt.Enabled
			or (progress and progress.Value >= 100)
		then
			return
		end
		if candle and prompt.Name ~= "SnuffPrompt" then
			return
		end
		local point = toonPromptPoint(prompt)
		if not point or toonThreat(session, point) < risk.target then
			return
		end
		local length = (point - root.Position).Magnitude - (candle and 10000 or 0)
		if not distance or length < distance then
			chosen, distance =
				{
					object = object,
					part = part,
					point = point,
					prompt = prompt,
					candle = candle,
					progress = progress,
					owner = owner,
				}, length
		end
	end
	if not round.candle then
		for candle in pairs(session.candles) do
			consider(candle, nil, true)
		end
	end
	if not chosen then
		for _, pair in ipairs({
			{ "Computers", "ComputerPercentage", "ComputerClient" },
			{ "OilMachines", "OilValue", "OilMachineClient" },
		}) do
			local folder = workspace:FindFirstChild(pair[1])
			for _, machine in ipairs(folder and folder:GetChildren() or {}) do
				local progress = machine:FindFirstChild(pair[2])
				if progress then
					consider(machine, progress, false, pair[3])
				end
			end
		end
		for object, kind in pairs(tasks) do
			local progress = object:FindFirstChild(kind[1])
			if progress then
				consider(object, progress, false, kind[2])
			end
		end
	end
	if not chosen then
		return nil
	end
	local function valid()
		local latest = toonRound()
		return active(generation)
			and toonLife(true) == model
			and latest
			and latest.floor == round.floor
			and latest.map == round.map
			and latest.playing
			and not latest.completed
			and chosen.object:IsDescendantOf(workspace)
			and chosen.prompt.Enabled
			and toonThreat(session, chosen.point) >= toonRisk(session).approach
	end
	local point = chosen.point
		+ chosen.part.CFrame.LookVector * math.min(2.5, chosen.prompt.MaxActivationDistance * 0.35)
	local moved, moveReason = toonMove(session, point, generation, chosen.object, valid)
	if not moved then
		session.blocked[chosen.object] = os.clock() + 8
		return nil, moveReason
	end
	if not chosen.candle then
		session.working = { object = chosen.object, model = model, at = os.clock(), risk = risk }
	end
	local before = chosen.progress and chosen.progress.Value
	local lastVote = session.candleVote
	local function accepted()
		local latest = toonRound()
		if not latest or latest.floor ~= round.floor or latest.map ~= round.map then
			return false
		end
		if chosen.candle then
			return latest.candle or session.candleVote ~= lastVote
		end
		local binding = session.input.Actions.SkillCheckExit
		if binding and binding.OwnerTag == chosen.owner then
			session.working.started = true
			return true
		end
		return chosen.progress:IsDescendantOf(workspace) and chosen.progress.Value > before
	end
	local used, reason = toonPrompt(session, chosen.prompt, generation, valid, accepted)
	session.blocked[chosen.object] = os.clock() + (used and chosen.candle and 15 or used and 3 or 1.5)
	if not chosen.candle and (not used or not session.working.started) then
		toonRelease(session)
		session.working = nil
	end
	if used == false then
		session.promptMisses = session.promptMisses or {}
		session.promptMisses[chosen.object] = (session.promptMisses[chosen.object] or 0) + 1
		if session.promptMisses[chosen.object] >= 3 then
			session.blocked[chosen.object] = os.clock() + 30
			session.promptMisses[chosen.object] = 0
			log("That prompt hasn't started after three tries. Staying near the exit and checking again shortly.")
			return nil, "That task isn't responding. Waiting near the elevator, then retrying."
		end
		return nil, reason
	end
	if used and session.promptMisses then
		session.promptMisses[chosen.object] = nil
	end
	if used == nil then
		return nil, reason
	end
	return used, chosen.candle and "Snuffing the candle" or "Starting a machine"
end

local function toonWatchTravel(session, destination)
	local connection = connect(App.player.OnTeleport, function(state)
		if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
			session.traveling = true
		elseif state == Enum.TeleportState.Failed then
			session.failed = true
		end
	end)
	local failed = connect(Teleport.TeleportInitFailed, function(player)
		if player == App.player then
			session.failed = true
		end
	end)
	table.insert(App.cleanups, function()
		connection:Disconnect()
		failed:Disconnect()
	end)
	session.continued = prepareTravel(destination, true)
end

local function toonLobby(generation)
	local session = {}
	local folder = waitUntil(function()
		return getPath(Storage, "Data", "CandleHollowConfig")
	end, 30, generation)
	local config = module(folder, generation)
	local object = waitUntil(function()
		return getPath(Storage, "Modules", "ClientState")
	end, 30, generation)
	local data = module(object, generation)
	local remote = getPath(Storage, "Remotes", "CandleHollow")
	if
		not config
		or not data
		or type(data.Get) ~= "function"
		or config.BadgeId ~= current.badges[1]
		or config.Goal ~= 12
		or type(config.Tiers) ~= "table"
		or not remote
		or not remote:IsA("RemoteFunction")
	then
		return false, "The Candle Hollow event hasn't loaded. Try Start again."
	end
	local ok, state = invoke(remote, generation, "Get")
	if
		not ok
		or type(state) ~= "table"
		or type(state.Floors) ~= "number"
		or type(state.Claimed) ~= "table"
		or type(state.Ready) ~= "table"
	then
		return false, "Couldn't load your Candle Floor progress. Try Start again."
	end
	env.__HOLLOW_TOONS_PROGRESS = { userId = App.player.UserId, floors = state.Floors }
	for index, tier in ipairs(config.Tiers) do
		local key = tostring(index)
		if state.Floors >= tier.Floors and state.Ready[key] == true and state.Claimed[key] ~= true then
			local sent, accepted, why = invoke(remote, generation, "Claim", index)
			if not sent or accepted ~= true then
				return false, "Couldn't claim that reward. " .. tostring(why or accepted)
			end
			if not pause(0.4, generation) then
				return false, "Stopped"
			end
		end
	end
	if state.Floors >= 12 then
		for _ = 1, 5 do
			if not active(generation) then
				return false, "Stopped"
			end
			if verify(current, true) == true then
				return true, "Toons Universe Hollow badge earned"
			end
			if not pause(5, generation) then
				return false, "Stopped"
			end
		end
		return false, "Twelve floors done. Check the last reward in the Candle Hollow menu."
	end
	if type(config.IsActive) ~= "function" or not config.IsActive() then
		return false, "Candle Hollow isn't active in this server"
	end
	toonWatchTravel(session, current.gameplayPlace)
	local elevatorRemote = getPath(Storage, "Remotes", "Elevator")
	if elevatorRemote and elevatorRemote:IsA("RemoteEvent") then
		local connection = connect(elevatorRemote.OnClientEvent, function(kind)
			if kind == "Enter" or kind == "Close" then
				session.queued = true
			end
			if kind == "Leave" then
				session.queued = false
			end
		end)
		table.insert(App.cleanups, function()
			connection:Disconnect()
		end)
	end
	local began, tried = os.clock(), false
	while active(generation) and os.clock() - began < 150 do
		if session.failed then
			return false, "The elevator couldn't load the run. Try Start again."
		end
		if session.traveling then
			App.traveling = true
			return nil,
				session.continued and "Entering the run. I'll carry on when we arrive."
					or "Entering the run. Run the script again when you arrive."
		end
		if not tried and toonLife(true) then
			local elevators = workspace:FindFirstChild("Elevators")
			for _, elevator in ipairs(elevators and elevators:GetChildren() or {}) do
				local door, pad = getPath(elevator, "TouchDoor"), getPath(elevator, "TeleportPart")
				if door and pad and door:IsA("BasePart") and pad:IsA("BasePart") then
					local point = Vector3.new(door.Position.X, pad.Position.Y, door.Position.Z)
					if toonMove({ monsters = {} }, point, generation, door) then
						tried = true
						break
					end
				end
			end
		end
		status(
			"Candle Hollow",
			string.format(
				"%d / 12 Candle Floors\n%s",
				state.Floors,
				session.queued and "Waiting for the elevator to leave" or "Step into an open elevator to start a run"
			),
			math.min(0.9, state.Floors / 12)
		)
		if not pause(0.25, generation) then
			return false, "Stopped"
		end
	end
	return false,
		active(generation) and "The elevator hasn't left yet. Join one in the game, then try again." or "Stopped"
end

local function runToons(generation)
	if game.PlaceId ~= current.gameplayPlace then
		if verify(current, true) == true then
			return true, "Toons Universe Hollow badge earned"
		end
		return toonLobby(generation)
	end
	status("Loading Toons Universe", "Waiting for the run to load", 0)
	local object = waitUntil(function()
		return getPath(Storage, "Modules", "InputService")
	end, 30, generation)
	local input = module(object, generation)
	if not input or type(input.Actions) ~= "table" then
		return false, "The game controls haven't loaded. Try Start again."
	end
	local key = tostring(game.JobId) .. ":" .. tostring(App.player.UserId)
	if type(env.__HOLLOW_TOONS_RUN) ~= "table" or env.__HOLLOW_TOONS_RUN.key ~= key then
		env.__HOLLOW_TOONS_RUN = { key = key, counted = {}, candles = {} }
	end
	local memory = env.__HOLLOW_TOONS_RUN
	local session = { input = input, monsters = {}, candles = {}, blocked = {}, counted = memory.counted, done = 0 }
	for _ in pairs(memory.counted) do
		session.done += 1
	end
	local connections = {}
	table.insert(App.cleanups, function()
		for _, connection in ipairs(connections) do
			connection:Disconnect()
		end
		toonRelease(session)
	end)
	toonWatchMonsters(session, connections)
	for _, candle in ipairs(Collection:GetTagged("CandleFloorCandle")) do
		session.candles[candle] = true
	end
	table.insert(
		connections,
		connect(Collection:GetInstanceAddedSignal("CandleFloorCandle"), function(candle)
			session.candles[candle] = true
		end)
	)
	table.insert(
		connections,
		connect(Collection:GetInstanceRemovedSignal("CandleFloorCandle"), function(candle)
			session.candles[candle] = nil
		end)
	)
	local vote = getPath(Storage, "Remotes", "CandleVote")
	if vote and vote:IsA("RemoteEvent") then
		table.insert(
			connections,
			connect(vote.OnClientEvent, function(kind, view)
				if not active(generation) then
					return
				end
				if
					(kind == "Open" or kind == "Update")
					and type(view) == "table"
					and type(view.Id) == "number"
					and type(view.EndsAt) == "number"
					and view.EndsAt > workspace:GetServerTimeNow()
				then
					session.candleVote = view.Id
					if view.Choice == nil and session.vote ~= view.Id and toonLife(false) then
						session.vote = view.Id
						fire(vote, "Vote", view.Id, true)
					end
				end
			end)
		)
	end
	local chase = getPath(Storage, "Remotes", "Chase")
	session.chasing = {}
	if chase and chase:IsA("RemoteEvent") then
		table.insert(
			connections,
			connect(chase.OnClientEvent, function(monster, kind)
				if kind == "Started" and typeof(monster) == "Instance" then
					local round = toonRound()
					if round then
						session.chasing[monster] = { floor = round.floor, map = round.map }
					end
				else
					session.chasing[monster] = nil
				end
			end)
		)
	end
	toonWatchBreaker(session, connections, generation)
	toonWatchTravel(session, current.place)
	local nextAction, missing, deadAt = 0, nil, nil
	local previousFloor, previousMap
	while active(generation) do
		if session.failed then
			return false, "Couldn't return to the lobby. Use Back to Lobby in the game."
		end
		if session.traveling then
			App.traveling = true
			return nil,
				session.continued and "Back to the lobby. I'll check rewards and start another run."
					or "Back to the lobby. Run the script again to check rewards."
		end
		local round = toonRound()
		toonWatchMonsters(session, connections)
		toonWatchBreaker(session, connections, generation)
		local model, root = toonLife(false)
		local detail
		if not round then
			missing = missing or os.clock()
			toonRelease(session)
			local _, waiting = toonRefuge(session, generation, true)
			detail = os.clock() - missing > 45 and "Waiting for the floor to load" or "Waiting for the floor to load"
			status("Candle Hollow", detail .. "\n" .. (waiting or "Staying near the elevator"))
		else
			missing = nil
			if previousFloor ~= round.floor or previousMap ~= round.map then
				toonRelease(session)
				previousFloor, previousMap = round.floor, round.map
				session.blocked, session.working, session.hitBinding, session.promptMisses = {}, nil, nil, {}
				session.chasing, session.nextRetreat = {}, 0
				session.lastProgress, session.progressValues, session.phase = os.clock(), {}, nil
				session.wantFuseBox, session.explored, session.exploreCount = false, {}, 0
				session.fuseBoxSeen = false
			end
			toonProgress(session, round)
			if round.candle then
				memory.candles[round.floor] = true
			end
			if
				round.completed
				and not toonFusePhase(round)
				and memory.candles[round.floor]
				and not session.counted[round.floor]
			then
				session.counted[round.floor] = true
				session.done += 1
				session.lastProgress = os.clock()
			end
			local saved = env.__HOLLOW_TOONS_PROGRESS
			local baseline = type(saved) == "table" and saved.userId == App.player.UserId and tonumber(saved.floors)
				or 0
			baseline = baseline or 0
			if not model then
				deadAt = deadAt or os.clock()
				detail = "Waiting for the death screen"
			else
				deadAt = nil
				local escaping = toonEscape(round)
				if escaping then
					toonRelease(session)
					session.working = nil
					local _, why = toonRefuge(session, generation, true)
					detail = why
				elseif session.boxOwned then
					local _, why = toonBreaker(session, round, generation)
					detail = why
				elseif session.working then
					local working, why = toonSkill(session, generation)
					if working == false then
						return false, why
					end
					detail = why
				end
				if not detail then
					local risk = toonRisk(session)
					local nearest = toonThreat(session, root.Position)
					local danger = nearest < risk.panic or toonChased(session, round) and nearest < risk.chase
					if danger then
						toonRelease(session)
						local _, why = toonRefuge(session, generation, false)
						detail = why
					elseif os.clock() >= nextAction and toonLife(true) then
						nextAction = os.clock() + 0.5
						local worked, why
						if toonFusePhase(round) then
							worked, why = toonFuses(session, round, generation)
						else
							worked, why = toonObjective(session, round, generation)
						end
						if worked == false then
							log(why)
							session.working = nil
						end
						detail = why
						if not worked then
							local explored, looking = toonExplore(session, round, generation)
							if explored then
								detail = looking
							else
								local _, idle = toonRefuge(session, generation, false)
								detail = detail or idle or looking
							end
						end
					end
				end
			end
			if
				((deadAt and os.clock() - deadAt > 12) or baseline + session.done >= 12 and not toonFusePhase(round))
				and not session.returned
			then
				local remote = getPath(Storage, "Remotes", "Lobby")
				if not remote or not remote:IsA("RemoteEvent") then
					return false, "Use Back to Lobby to claim your Candle Hollow rewards"
				end
				toonRelease(session)
				session.returned = os.clock()
				local sent = fire(remote)
				if not sent then
					return false, "Couldn't return to the lobby. Use Back to Lobby in the game."
				end
			end
			if session.returned and os.clock() - session.returned > 30 then
				return false, "Use Back to Lobby in the game, then run the script again"
			end
			local risk = toonRisk(session)
			status(
				"Candle Hollow",
				string.format(
					"Floor %d  |  %d candle floors finished this run\n%s%s",
					round.floor,
					session.done,
					round.objective ~= "" and round.objective .. "\n" or "",
					(detail or (session.returned and "Returning to the lobby" or "Watching the floor"))
						.. (risk.stage > 0 and not toonEscape(round) and "\nTrying a closer route." or "")
				),
				math.min(0.9, (baseline + session.done) / 12 * 0.9)
			)
		end
		if not pause(session.working and 0.025 or 0.15, generation) then
			return false, "Stopped"
		end
	end
	return false, "Stopped"
end

local Lemons = {
	currency = "Halloween2026",
	goal = 5,
	price = 1000,
	starter = {
		{ "Structure", "Halloween Tycoon", 0 },
		{ "Droppers", "Toffee Dropper", 0 },
		{ "Structure", "Floor 1 Conveyor 2", 5 },
		{ "Droppers", "Bonbon Dropper", 10 },
		{ "Upgraders", "Quality Scanner", 40 },
		{ "Droppers", "Pumpkin Press", 100 },
		{ "Upgraders", "Precision Weigher", 425 },
		{ "Cannons", "Floor 1 Cannon Tier 2", 100 },
	},
}

function Lemons.load(session, generation)
	session.classes = session.classes or {}
	for name, path in pairs({
		Player = { "Core", "Player" },
		Save = { "Modules", "Player", "UserDataSlot" },
		Currency = { "Modules", "Player", "EventCurrency" },
		Stickers = { "Modules", "Player", "PlayerStickers" },
		Purchases = { "Modules", "Player", "PlayerSpecialPurchases" },
		StickerConfig = { "Config", "Stickers" },
		HalloweenConfig = { "Config", "Halloween" },
	}) do
		if not session.classes[name] then
			local value = module(getPath(Storage, table.unpack(path)), generation)
			if not value then
				return nil, "Waiting for the game's " .. name .. " module"
			end
			session.classes[name] = value
		end
	end
	local sheets = session.classes.StickerConfig.StickerSheets
	local sheet = type(sheets) == "table" and sheets[Lemons.currency]
	local pack = sheet and sheet.Packs and sheet.Packs.Common
	if
		not sheet
		or not sheet.Active
		or sheet.Currency ~= Lemons.currency
		or not pack
		or pack.Cost ~= Lemons.price
		or session.classes.HalloweenConfig.RequiredPacks ~= Lemons.goal
	then
		return nil, "The sticker shop changed, so buying is paused.", true
	end
	return true
end

function Lemons.owned(plot)
	local tycoon = plot and plot.Parent
	local owner = tycoon and tycoon:FindFirstChild("Owner")
	return plot
		and plot.Name == "HalloweenPlot"
		and plot:IsDescendantOf(workspace)
		and owner
		and owner:IsA("ObjectValue")
		and owner.Value == App.player
end

function Lemons.read(session)
	local ok, state = pcall(function()
		local classes = session.classes
		local player = classes.Player.getLocal()
		if not player or player:IsDestroyed() then
			return nil
		end
		local save = player:GetComponent(classes.Save)
		local currency = player:GetComponent(classes.Currency)
		local stickers = player:GetComponent(classes.Stickers)
		local purchases = player:GetComponent(classes.Purchases)
		for _, component in pairs({ save, currency, stickers, purchases }) do
			if not component or not component:IsLoaded() then
				return nil
			end
		end
		if not save or not currency or not stickers or not purchases then
			return nil
		end
		local money = currency:Get(Lemons.currency, true)
		local packs = stickers:GetOpenedPacks(Lemons.currency)
		if
			type(money) ~= "number"
			or money ~= money
			or money < 0
			or money == math.huge
			or type(packs) ~= "number"
			or packs < 0
			or packs % 1 ~= 0
			or packs == math.huge
		then
			return nil
		end
		if not Lemons.owned(session.plot) then
			session.plot = nil
			for _, tycoon in ipairs(Collection:GetTagged("Tycoon")) do
				local plot = tycoon:FindFirstChild("HalloweenPlot")
				if Lemons.owned(plot) then
					session.plot = plot
					break
				end
			end
		end
		local area = getPath(workspace, "Map", "Event", "DropArea")
		if packs < Lemons.goal and (not session.plot or not area or not area:IsA("BasePart")) then
			return nil
		end
		return { player = player, money = money, packs = packs, purchases = purchases, plot = session.plot, area = area }
	end)
	return ok and state or nil
end

function Lemons.inEvent(point, area)
	if not area or typeof(point) ~= "Vector3" or point.X ~= point.X or point.Y ~= point.Y or point.Z ~= point.Z then
		return false
	end
	local relative = area.CFrame:PointToObjectSpace(point)
	return math.abs(relative.X) <= area.Size.X / 2 + 2
		and math.abs(relative.Z) <= area.Size.Z / 2 + 2
		and point.Y < area.Position.Y + 8
		and point.Y > area.Position.Y - 128
		and point.Y > workspace.FallenPartsDestroyHeight + 32
end

function Lemons.ready(state, generation, model)
	local live, root, humanoid = character()
	return active(generation)
		and live
		and (not model or live == model)
		and not root.Anchored
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and Lemons.owned(state.plot)
end

function Lemons.purchased(state, button)
	return button:GetAttribute("Unlocked") == true or state.purchases:IsPurchased((button.Name:gsub("[^%w]", "")))
end

function Lemons.upgrade(state)
	if not Lemons.owned(state.plot) or state.packs > 0 or state.money >= Lemons.goal * Lemons.price then
		return nil
	end
	local buttons = state.plot:FindFirstChild("Buttons")
	for _, entry in ipairs(Lemons.starter) do
		local button = getPath(buttons, entry[1], entry[2])
		local cost = button and button:GetAttribute("EventCurrencyCost")
		if
			button
			and Collection:HasTag(button, "Tycoon.EventPurchase")
			and button:GetAttribute("EventCurrency") == Lemons.currency
			and type(cost) == "number"
			and cost >= 0
			and cost <= entry[3]
			and cost <= state.money
			and button:GetAttribute("Shown") == true
			and button:GetAttribute("Enabled") == true
			and not Lemons.purchased(state, button)
		then
			return button, cost
		end
	end
	return nil
end

function Lemons.journal()
	local key = tostring(App.player.UserId) .. ":" .. game.JobId
	if type(env.__HOLLOW_LEMONS_PURCHASE) ~= "table" or env.__HOLLOW_LEMONS_PURCHASE.key ~= key then
		env.__HOLLOW_LEMONS_PURCHASE = { key = key }
	end
	return env.__HOLLOW_LEMONS_PURCHASE
end

function Lemons.settle(session, state)
	local journal = Lemons.journal()
	local purchase = journal.purchase
	if not purchase then
		return true
	end
	local accepted = purchase.kind == "pack" and state.packs > purchase.packs
	if purchase.kind == "upgrade" and purchase.button.Parent and Lemons.owned(purchase.plot) then
		accepted = Lemons.purchased(state, purchase.button)
	end
	if purchase.done and accepted then
		journal.purchase, session.failures = nil, 0
		return true
	end
	if purchase.done and (not purchase.issued or purchase.ok and purchase.result == false) then
		journal.purchase = nil
		session.failures = (session.failures or 0) + 1
		session.buyAfter = os.clock() + 4
		if session.failures >= 3 then
			return false, "The shop rejected three purchases. Check the shop before trying again."
		end
		return false
	end
	if (purchase.done and os.clock() - purchase.finished > 15) or os.clock() - purchase.started > 30 then
		return false, "A purchase hasn't synced yet. Wait for it to finish, or rejoin before trying again."
	end
	return false
end

function Lemons.buy(session, state, generation, button)
	local journal = Lemons.journal()
	if journal.purchase or os.clock() < (session.buyAfter or 0) or not Lemons.ready(state, generation) then
		return false
	end
	local remote = button and button:FindFirstChild("Unlock")
		or (not button and getPath(Storage, "Core", "RemoteRequest", "PlayerStickers.PurchasePack"))
	if not remote or not remote:IsA("RemoteFunction") then
		session.buyAfter = os.clock() + 2
		return false
	end
	local purchase = {
		kind = button and "upgrade" or "pack",
		button = button,
		plot = state.plot,
		packs = state.packs,
		started = os.clock(),
	}
	journal.purchase = purchase
	task.spawn(function()
		purchase.ok, purchase.result = pcall(function()
			local fresh = Lemons.read(session)
			if not fresh or not Lemons.ready(fresh, generation) or fresh.plot ~= state.plot then
				return false
			end
			if button then
				if Lemons.upgrade(fresh) ~= button or not button:IsDescendantOf(fresh.plot) then
					return false
				end
			elseif fresh.packs ~= purchase.packs or fresh.packs >= Lemons.goal or fresh.money < Lemons.price then
				return false
			end
			if not active(generation) then
				return false
			end
			purchase.issued = true
			if button then
				return remote:InvokeServer()
			end
			return remote:InvokeServer(Lemons.currency, "Common")
		end)
		purchase.finished, purchase.done = os.clock(), true
	end)
	return true
end

function Lemons.clearCoins(session)
	for _, connection in ipairs(session.coinConnections or {}) do
		connection:Disconnect()
	end
	session.coinConnections, session.coins, session.drops = {}, {}, nil
end

function Lemons.coin(session, state, root)
	local drops = workspace:FindFirstChild("Drops")
	if drops ~= session.drops then
		Lemons.clearCoins(session)
		session.drops = drops
		if drops then
			local function add(coin)
				if coin.Name == "SpookyCoinDrop" and coin:IsA("BasePart") then
					session.coins[coin] = true
				end
			end
			session.coinConnections = {
				drops.ChildAdded:Connect(add),
				drops.ChildRemoved:Connect(function(coin)
					session.coins[coin], session.coinAfter[coin] = nil, nil
				end),
			}
			for _, coin in ipairs(drops:GetChildren()) do
				add(coin)
			end
		end
	end
	local best, distance
	for coin in pairs(session.coins) do
		if
			coin.Parent == drops
			and coin.CanTouch
			and coin:FindFirstChild("Token")
			and os.clock() >= (session.coinAfter[coin] or 0)
			and Lemons.inEvent(coin.Position, state.area)
		then
			local length = (coin.Position - root.Position).Magnitude
			if not distance or length < distance then
				best, distance = coin, length
			end
		end
	end
	return best
end

function Lemons.collect(session, state, coin, generation)
	local model = character()
	local function allowed()
		return Lemons.ready(state, generation, model)
			and coin.Parent == session.drops
			and coin:FindFirstChild("Token")
			and Lemons.inEvent(coin.Position, state.area)
	end
	session.coinAfter[coin] = os.clock() + 6
	if not allowed() then
		return false
	end
	local moved = approach(coin.Position, generation, session.drops, false, allowed)
	if not moved or not allowed() then
		return false
	end
	local _, root = character()
	if (root.Position - coin.Position).Magnitude <= 9 and type(firetouchinterest) == "function" then
		pcall(firetouchinterest, root, coin, 0)
		pcall(firetouchinterest, root, coin, 1)
	end
	waitUntil(function()
		return not allowed() or not coin:FindFirstChild("Token")
	end, 1.2, generation)
	return true
end

local function runLemons(generation)
	if verify(current, true) then
		return true, "You already have the Sell Lemons badge"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if game.PlaceId ~= current.place then
		prepareTravel(current.place, true)
		local ok = pcall(Teleport.Teleport, Teleport, current.place, App.player)
		if ok then
			return nil, "Heading to the Halloween area in World 1"
		end
		return false, "Couldn't join World 1"
	end
	local session = { coins = {}, coinAfter = setmetatable({}, { __mode = "k" }), coinConnections = {} }
	table.insert(App.cleanups, function()
		Lemons.clearCoins(session)
	end)
	local deadline, dataAt, progressAt = os.clock() + 7200, os.clock(), os.clock()
	local previousMoney, previousPacks, entered, claimAt, claims, completedAt = nil, nil, false, 0, 0, nil
	local loaded = false
	while active(generation) and os.clock() < deadline do
		local reason, changed
		if not loaded then
			loaded, reason, changed = Lemons.load(session, generation)
			if changed then
				return false, reason
			end
		end
		if not active(generation) then
			break
		end
		local state = loaded and Lemons.read(session)
		if not state then
			status("Loading Sell Lemons", reason or "Waiting for your save and Halloween factory", 0)
			if os.clock() - dataAt > 90 then
				return false,
					reason or "Your Halloween save or factory hasn't loaded. Try again once the game is ready."
			end
			if not pause(1, generation) then
				break
			end
			continue
		end
		dataAt = os.clock()
		if state.money ~= previousMoney or state.packs ~= previousPacks then
			previousMoney, previousPacks, progressAt = state.money, state.packs, os.clock()
		end
		if state.packs >= Lemons.goal then
			Lemons.settle(session, state)
			completedAt = completedAt or os.clock()
			status("Five packs opened", "Claiming the Sell Lemons badge", 1)
			if os.clock() >= claimAt then
				if verify(current, true) then
					return true, "Sell Lemons badge earned"
				end
				if not active(generation) then
					break
				end
				local remote = getPath(Storage, "Core", "RemoteSignal", "ClaimHollowBadge")
				if claims < 4 and fire(remote) then
					claims += 1
				end
				claimAt = os.clock() + 15
			end
			if os.clock() - completedAt > 75 then
				return false, "Five packs are saved, but the badge isn't confirmed yet. Try Check badges shortly."
			end
		else
			local settled, failure = Lemons.settle(session, state)
			if failure then
				return false, failure
			end
			local _, root = character()
			local action = settled and "Collecting coins in the Halloween area" or "Waiting for the purchase to sync"
			if root and Lemons.ready(state, generation) then
				if not entered or not Lemons.inEvent(root.Position, state.area) then
					action = "Heading to your candy factory"
					local location = state.plot:FindFirstChild("Halloween")
					if location and location:IsA("BasePart") and os.clock() >= (session.enterAfter or 0) then
						session.enterAfter = os.clock() + 5
						entered = approach(location.Position, generation, location, false, function()
							return Lemons.ready(state, generation) and location:IsDescendantOf(state.plot)
						end) and Lemons.inEvent(root.Position, state.area)
					end
				else
					local button = settled and Lemons.upgrade(state)
					if settled and button then
						if Lemons.buy(session, state, generation, button) then
							action = "Buying " .. button.Name
						end
					elseif settled and state.money >= Lemons.price then
						if Lemons.buy(session, state, generation) then
							action = "Opening a 1,000-coin Halloween pack"
						end
					end
					local coin = Lemons.coin(session, state, root)
					if coin then
						Lemons.collect(session, state, coin, generation)
					end
				end
			else
				action = "Waiting for your character"
				entered = false
			end
			if not active(generation) then
				break
			end
			status(
				"Sell Lemons",
				string.format(
					"%d / 5 packs | %s Spooky Coins\n%s",
					state.packs,
					tostring(math.floor(state.money)),
					action
				),
				math.min(0.99, (state.packs + math.min(state.money / Lemons.price, 1)) / 5)
			)
			if os.clock() - progressAt > 300 then
				return false,
					"No Spooky Coins or pack progress for five minutes. Check that the Halloween event is running."
			end
		end
		if not pause(0.35, generation) then
			break
		end
	end
	return false, active(generation) and "The Sell Lemons run reached its time limit" or "Stopped"
end

local EventInput = {}

function EventInput.point(object)
	if not object or not object.Parent then
		return nil
	end
	if object:IsA("Attachment") then
		return object.WorldPosition
	end
	local anchor = object:FindFirstChild("PromptAnchor")
	return anchor and EventInput.point(anchor) or positionOf(object)
end

function EventInput.endLook(session)
	local look = session.look
	session.look = nil
	if look then
		if look.binding then
			pcall(RunService.UnbindFromRenderStep, RunService, look.binding)
		end
		pcall(function()
			if
				look.camera.CameraType == look.kind
				and look.camera.CFrame == look.aim
				and look.cameraEpoch == App.cameraEpoch
				and not App.cameraBusy
			then
				look.camera.CFrame = look.previous
			end
		end)
	end
end

function EventInput.release(session)
	local hold = session.holdState
	session.holdState = nil
	if hold then
		hold.closed = true
		if hold.connection then
			pcall(hold.connection.Disconnect, hold.connection)
		end
	end
	local prompt = session.prompt
	session.prompt = nil
	if prompt then
		pcall(prompt.InputHoldEnd, prompt)
	end
	if session.key then
		pcall(session.key.release)
		session.key = nil
	end
	EventInput.endLook(session)
end

function EventInput.hold(session, prompt, generation, allowed, options)
	options = options or {}
	local model, root = character()
	if not model or not prompt or not prompt:IsA("ProximityPrompt") then
		return false, "Waiting for the interaction prompt"
	end
	local point = EventInput.point(prompt.Parent)
	local duration = prompt.HoldDuration
	if not point or type(duration) ~= "number" or duration ~= duration or duration < 0 or duration > 30 then
		return false, "The interaction changed"
	end
	if session.holdState then
		return false, "Finishing the current interaction"
	end
	local hold = {}
	session.holdState = hold
	local function owned()
		return session.holdState == hold and not hold.closed and active(generation) and App.player.Character == model
	end
	local function completed()
		if not owned() then
			return false
		end
		if options.accepted then
			local ok, value = pcall(options.accepted)
			if ok and value then
				return true
			end
		end
		return hold.triggered and hold.started and os.clock() >= hold.started + duration
	end
	local function finish(ok, why)
		if session.holdState ~= hold then
			return false, "The interaction was cancelled"
		end
		hold.closed, session.holdState = true, nil
		if hold.connection then
			pcall(hold.connection.Disconnect, hold.connection)
		end
		if options.keepLook then
			hold.kept = true
			if session.prompt then
				pcall(session.prompt.InputHoldEnd, session.prompt)
				session.prompt = nil
			end
		else
			EventInput.release(session)
		end
		return ok, why
	end
	local function ready(retained)
		local nowModel, nowRoot = character()
		point = prompt.Parent and EventInput.point(prompt.Parent)
		local permitted = true
		if allowed then
			local ok, value = pcall(allowed)
			permitted = ok and value
		end
		return (
			owned()
			or retained
				and hold.kept
				and session.holdState == nil
				and active(generation)
				and App.player.Character == model
		)
			and nowModel == model
			and point
			and prompt:IsDescendantOf(workspace)
			and prompt.Enabled
			and (nowRoot.Position - point).Magnitude <= prompt.MaxActivationDistance
			and permitted
	end
	if not ready() then
		return finish(false, "Couldn't reach the prompt")
	end
	EventInput.endLook(session)
	local camera = workspace.CurrentCamera
	if
		camera
		and not App.cameraBusy
		and (camera.CameraType ~= Enum.CameraType.Scriptable or options.customCamera == true)
		and (camera.CFrame.Position - point).Magnitude > 0.1
	then
		local aim = CFrame.lookAt(camera.CFrame.Position, point)
		session.look = {
			camera = camera,
			kind = camera.CameraType,
			previous = camera.CFrame,
			aim = aim,
			cameraEpoch = App.cameraEpoch,
		}
		camera.CFrame = aim
		local look = session.look
		look.update = function()
			if session.look ~= look then
				return
			end
			if
				not ready(true)
				or App.cameraBusy
				or App.cameraEpoch ~= look.cameraEpoch
				or workspace.CurrentCamera ~= camera
				or camera.CameraType ~= look.kind
			then
				EventInput.endLook(session)
				return
			end
			if (camera.CFrame.Position - point).Magnitude > 0.1 then
				if camera.CFrame ~= look.aim then
					look.previous = camera.CFrame
				end
				look.aim = CFrame.lookAt(camera.CFrame.Position, point)
				camera.CFrame = look.aim
			end
		end
		if RunService and type(RunService.BindToRenderStep) == "function" then
			EventInput.lookSerial = (EventInput.lookSerial or 0) + 1
			local binding = "HollowPromptLook_" .. EventInput.lookSerial
			local priority = Enum.RenderPriority and Enum.RenderPriority.Last and Enum.RenderPriority.Last.Value - 1
				or 201
			local bound = pcall(RunService.BindToRenderStep, RunService, binding, priority, function()
				local ok = pcall(look.update)
				if not ok then
					EventInput.endLook(session)
				end
			end)
			if bound then
				look.binding = binding
			end
		end
		if not pause(0.06, generation) or not ready() then
			return finish(completed() == true, "The interaction changed")
		end
	end
	if prompt.Triggered then
		local ok, connection = pcall(prompt.Triggered.Connect, prompt.Triggered, function(player)
			if owned() and (player == nil or player == App.player) then
				hold.triggered = true
			end
		end)
		if ok then
			hold.connection = connection
		end
	end
	session.prompt = prompt
	hold.started = os.clock()
	local deadline = hold.started + duration + (hold.connection and 0.45 or 0.12)
	if session.look and session.look.update then
		session.look.update()
	end
	local began, reason = pcall(prompt.InputHoldBegin, prompt)
	if not began and ready() and type(fireproximityprompt) == "function" then
		began, reason = call(prompt, function()
			if ready() then
				return fireproximityprompt(prompt, duration)
			end
			return false
		end, duration + 2, generation)
		began = began and reason ~= false
	end
	if began then
		while not completed() and ready() and os.clock() < deadline do
			if session.look and session.look.update then
				session.look.update()
			end
			if not pause(0.04, generation) then
				break
			end
		end
		began = completed() or ready() and os.clock() >= deadline
	end
	return finish(began == true, if began then nil else (reason or "The interaction ended early"))
end

function EventInput.guiPress(object, touch)
	if type(firesignal) ~= "function" or not object or not object:IsA("GuiObject") then
		return nil
	end
	local ancestor = object
	while ancestor do
		if ancestor:IsA("GuiObject") and not ancestor.Visible or ancestor:IsA("ScreenGui") and not ancestor.Enabled then
			return nil
		end
		ancestor = ancestor.Parent
	end
	local release = function()
		if touch then
			firesignal(
				object.InputEnded,
				{ UserInputType = Enum.UserInputType.Touch, UserInputState = Enum.UserInputState.End }
			)
		else
			firesignal(object.MouseButton1Up)
		end
	end
	local ok, result = pcall(function()
		if touch then
			return firesignal(
				object.InputBegan,
				{ UserInputType = Enum.UserInputType.Touch, UserInputState = Enum.UserInputState.Begin }
			)
		end
		return firesignal(object.MouseButton1Down)
	end)
	if ok and result ~= false then
		return { release = release }
	end
	pcall(release)
	return nil
end

function EventInput.tap(session, generation, keyCode, touchTarget)
	if not active(generation) or session.key then
		return false
	end
	local checked, focused = pcall(function()
		return Input:GetFocusedTextBox()
	end)
	if checked and focused then
		return false
	end
	keyCode = keyCode or Enum.KeyCode.E
	if touchTarget then
		session.key = EventInput.guiPress(touchTarget, true)
	end
	local ok, service = pcall(game.GetService, game, "VirtualInputManager")
	local key
	if ok then
		key = {
			press = function()
				service:SendKeyEvent(true, keyCode, false, game)
			end,
			release = function()
				service:SendKeyEvent(false, keyCode, false, game)
			end,
		}
	end
	if key and not session.key then
		if pcall(key.press) then
			session.key = key
		else
			pcall(key.release)
		end
	end
	if not session.key and type(keypress) == "function" and type(keyrelease) == "function" then
		local name = keyCode.Name or tostring(keyCode)
		local code = #name == 1 and name:upper():byte() or ({ Space = 0x20, Return = 0x0D, Escape = 0x1B })[name]
		if not code then
			return false
		end
		key = {
			press = function()
				keypress(code)
			end,
			release = function()
				keyrelease(code)
			end,
		}
		if pcall(key.press) then
			session.key = key
		else
			pcall(key.release)
		end
	end
	if not session.key then
		return false
	end
	pause(0.04, generation)
	local held = session.key
	session.key = nil
	if held then
		pcall(held.release)
	end
	return active(generation)
end

local Flee = {}

function Flee.value(session, name)
	if not session.stats or type(session.stats.GetValue) ~= "function" then
		return nil
	end
	local ok, value = pcall(session.stats.GetValue, name)
	if ok then
		return value
	end
	return nil
end

function Flee.map()
	local value = Storage:FindFirstChild("CurrentMap")
	return value and value:IsA("ObjectValue") and value.Value
end

function Flee.beasts(session)
	local generation = session.generation or App.generation
	if not active(generation) then
		return {}
	end
	if os.clock() >= (session.beastScanAt or 0) then
		session.beastScanAt = os.clock() + 0.25
		session.beasts = {}
		session.beastRoles = session.beastRoles or setmetatable({}, { __mode = "k" })
		for _, player in ipairs(Players:GetPlayers()) do
			if player == App.player then
				continue
			end
			local object = player:FindFirstChild("TempPlayerStatsModule")
			local entry = session.beastRoles[player]
			if not entry or entry.object ~= object then
				entry = { object = object }
				session.beastRoles[player] = entry
			end
			if object and not entry.stats and not entry.loading and os.clock() >= (entry.retryAt or 0) then
				entry.loading = true
				task.spawn(function()
					local stats = module(object, generation)
					if
						active(generation)
						and session.beastRoles
						and session.beastRoles[player] == entry
						and player:FindFirstChild("TempPlayerStatsModule") == object
					then
						entry.stats = stats
						entry.loading, entry.retryAt = nil, os.clock() + 3
						session.beastScanAt = 0
					end
				end)
			end
			local model = player.Character
			local root = model and model:FindFirstChild("HumanoidRootPart")
			local humanoid = model and model:FindFirstChildOfClass("Humanoid")
			local beast = Flee.value(entry, "IsBeast")
			if beast == nil and object then
				local value = object:FindFirstChild("IsBeast")
				if value and value:IsA("BoolValue") then
					beast = value.Value
				end
			end
			if beast == nil then
				beast = model and model:FindFirstChild("BeastPowers") ~= nil
			end
			if beast == true and root and humanoid and humanoid.Health > 0 and model:IsDescendantOf(workspace) then
				table.insert(session.beasts, { player = player, model = model, root = root, humanoid = humanoid })
			end
		end
	end
	return session.beasts or {}
end

function Flee.distance(session, point)
	local nearest = math.huge
	for _, beast in ipairs(Flee.beasts(session)) do
		if
			beast.player.Character == beast.model
			and beast.root:IsDescendantOf(beast.model)
			and beast.model:IsDescendantOf(workspace)
			and beast.humanoid.Health > 0
		then
			nearest = math.min(nearest, (beast.root.Position - point).Magnitude)
		end
	end
	return nearest
end

function Flee.threatened(session)
	local _, root = character()
	return root ~= nil and Flee.distance(session, root.Position) < 36
end

function Flee.safe(session, from, point, margin)
	if Flee.distance(session, point) < (margin or 56) then
		return false
	end
	local delta = point - from
	local length = delta.Magnitude ^ 2
	for _, beast in ipairs(Flee.beasts(session)) do
		if
			beast.player.Character == beast.model
			and beast.root:IsDescendantOf(beast.model)
			and beast.model:IsDescendantOf(workspace)
			and beast.humanoid.Health > 0
		then
			local relative = beast.root.Position - from
			local alpha = length > 0
					and math.clamp((relative.X * delta.X + relative.Y * delta.Y + relative.Z * delta.Z) / length, 0, 1)
				or 0
			if (beast.root.Position - (from + delta * alpha)).Magnitude < math.min(20, relative.Magnitude - 1) then
				return false
			end
		end
	end
	return true
end

function Flee.finished(session, computer)
	if not session.map or not computer or computer == session.map or not computer:IsDescendantOf(session.map) then
		return false
	end
	if session.finished and session.finished[computer] then
		return true
	end
	local screen = computer:FindFirstChild("Screen")
	if not screen or not screen:IsA("BasePart") then
		return false
	end
	local color = screen.Color
	if typeof(color) == "Color3" and color.G >= 0.35 and color.R <= color.G * 0.6 and color.B <= color.G * 0.6 then
		session.finished = session.finished or setmetatable({}, { __mode = "k" })
		session.finished[computer] = true
		return true
	end
	return false
end

function Flee.life(session, generation, model, interaction)
	local nowModel, root, humanoid = character()
	local round = Storage:FindFirstChild("IsGameActive")
	local health = Flee.value(session, "Health")
	return active(generation)
		and nowModel ~= nil
		and (not model or nowModel == model)
		and (root.Anchored == false or interaction and session.trigger ~= nil and (session.hacking or session.openingExit ~= nil or os.clock() < (session.hackStartingUntil or 0)))
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and round ~= nil
		and round.Value == true
		and Flee.map() == session.map
		and session.map ~= nil
		and session.map:IsDescendantOf(workspace)
		and type(health) == "number"
		and health > 0
		and Flee.value(session, "IsBeast") == false
		and Flee.value(session, "Captured") ~= true
		and Flee.value(session, "Ragdoll") ~= true
		and Flee.value(session, "Escaped") ~= true
		and Flee.value(session, "DisableInteraction") ~= true
end

function Flee.cancelMove(session)
	local motion = session.motion
	session.motion = nil
	if motion then
		if motion.connection then
			motion.connection:Disconnect()
		end
		if motion.tween then
			pcall(motion.tween.Cancel, motion.tween)
		end
		if motion.collisionAdded then
			motion.collisionAdded:Disconnect()
		end
		for part in pairs(motion.collisions or {}) do
			pcall(function()
				if part:IsDescendantOf(motion.model) and part.CanCollide == false then
					part.CanCollide = true
				end
			end)
		end
	end
end

function Flee.release(session)
	Flee.cancelMove(session)
	EventInput.release(session)
	if session.trigger then
		fire(session.remote, "Input", "Action", false)
		fire(session.remote, "Input", "Trigger", false)
		session.trigger = nil
	end
	session.hacking, session.hackStartingUntil, session.openingExit = nil, nil, nil
end

function Flee.move(session, point, generation, target, allowed)
	Flee.cancelMove(session)
	local model, root, humanoid = character()
	if not model or typeof(point) ~= "Vector3" then
		return false
	end
	local function ready()
		return Flee.life(session, generation, model)
			and (not target or target:IsDescendantOf(workspace))
			and (not allowed or allowed())
	end
	if not ready() then
		return false
	end
	if (root.Position - point).Magnitude < 0.75 then
		return true
	end
	local loaded, service = pcall(function()
		return game:GetService("TweenService")
	end)
	if not loaded then
		return false, "Waiting for movement services"
	end
	local params = RaycastParams.new()
	params.FilterType, params.RespectCanCollide, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true, true
	params.FilterDescendantsInstances = { model }
	local height = math.max(2.5, (humanoid.HipHeight or 2) + root.Size.Y / 2)
	local function ground(position)
		local hit = workspace:Raycast(position + Vector3.new(0, 6, 0), Vector3.new(0, -18, 0), params)
		if hit and hit.Normal.Y > 0.65 and hit.Position.Y > workspace.FallenPartsDestroyHeight + 32 then
			return hit.Position + Vector3.new(0, height, 0)
		end
	end
	local goal = ground(point)
	if not goal or not ready() then
		return false, "Waiting for the floor to load"
	end
	local function finish(ok, reason)
		Flee.cancelMove(session)
		return ok, reason
	end
	local delta = goal - root.Position
	if delta.Magnitude < 0.5 then
		return true
	end
	if goal.Y <= workspace.FallenPartsDestroyHeight + 32 or delta.Magnitude > 10000 then
		return false, "Unsafe movement destination"
	end
	local route = { goal }
	local computer = target and target.Name:find("ComputerTrigger", 1, true) ~= nil
	local flat = Vector3.new(delta.X, 0, delta.Z)
	if computer and not session.evading and flat.Magnitude > 8 then
		local side = Vector3.new(-flat.Z, 0, flat.X) * (1 / flat.Magnitude)
		local width = math.clamp(flat.Magnitude * 0.2, 6, 18)
		route = nil
		local preferred = session.routeSide or 1
		for _, direction in ipairs({ preferred, -preferred }) do
			local first = ground(root.Position + delta * 0.35 + side * (width * direction))
			local second = ground(root.Position + delta * 0.7 + side * (width * direction))
			if
				first
				and second
				and Flee.safe(session, root.Position, first)
				and Flee.safe(session, first, second)
				and Flee.safe(session, second, goal)
			then
				route = { first, second, goal }
				session.routeSide = -direction
				break
			end
		end
		if not route or not ready() then
			return false, "Waiting for a safe route to this computer"
		end
	end
	local speed = session.evading and 60 or 48
	local motion = { done = false, model = model, collisions = {} }
	session.motion = motion
	local function noCollision(part)
		if part:IsA("BasePart") and part.CanCollide == true then
			motion.collisions[part] = true
			part.CanCollide = false
		end
	end
	for _, part in ipairs(model:GetDescendants()) do
		noCollision(part)
	end
	motion.collisionAdded = model.DescendantAdded:Connect(noCollision)
	for _, waypoint in ipairs(route) do
		local loaded = ground(waypoint)
		if not loaded or not ready() or (loaded - waypoint).Magnitude > 4 then
			return finish(false, "The route's floor changed")
		end
		local duration = (waypoint - root.Position).Magnitude / speed
		if duration < 0.01 then
			continue
		end
		local created, tween = pcall(
			service.Create,
			service,
			root,
			TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut),
			{ CFrame = CFrame.lookAt(waypoint, waypoint + root.CFrame.LookVector) }
		)
		if not created then
			return finish(false, "Couldn't start the movement tween")
		end
		motion.tween, motion.done, motion.state = tween, false, nil
		motion.connection = tween.Completed:Connect(function(state)
			motion.done, motion.state = true, state
		end)
		if not pcall(tween.Play, tween) then
			return finish(false, "Couldn't start the movement tween")
		end
		local deadline = os.clock() + duration + 2
		while not motion.done do
			if session.motion ~= motion or not ready() or os.clock() > deadline then
				return finish(false, "Movement interrupted")
			end
			root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
			for part in pairs(motion.collisions) do
				if part:IsDescendantOf(model) then
					part.CanCollide = false
				end
			end
			if not pause(0.03, generation) then
				return finish(false, "Stopped")
			end
		end
		if
			not ready()
			or motion.state ~= Enum.PlaybackState.Completed
			or (root.Position - waypoint).Magnitude > 1.25
		then
			return finish(false, "The game interrupted movement")
		end
		motion.connection:Disconnect()
		motion.connection = nil
	end
	return finish((root.Position - goal).Magnitude <= 1.25)
end

function Flee.cachePart(session, object)
	if not object:IsA("BasePart") or not object:IsDescendantOf(session.map) then
		return
	end
	if object.Name:find("Trigger", 1, true) then
		session.triggers[object] = true
	end
	if not session.partsSeen[object] then
		session.partsSeen[object] = true
		table.insert(session.streamParts, object)
	end
	local point = object.Position
	local key = string.format("%d:%d:%d", math.floor(point.X / 80), math.floor(point.Y / 16), math.floor(point.Z / 80))
	local region = session.regions[key]
	if not region then
		region = { part = object }
		session.regions[key] = region
		table.insert(session.regionList, region)
	elseif
		not region.part:IsDescendantOf(session.map)
		or region.part.CanCollide == false and object.CanCollide ~= false
	then
		region.part = object
	end
end

function Flee.refresh(session)
	local parts = session.streamParts or {}
	if not session.map or not session.partsSeen then
		return
	end
	for _ = 1, math.min(128, #parts) do
		session.refreshIndex = (session.refreshIndex or 0) % #parts + 1
		Flee.cachePart(session, parts[session.refreshIndex])
	end
end

function Flee.watchMap(session, map)
	Flee.release(session)
	if session.added then
		session.added:Disconnect()
	end
	session.added, session.map, session.triggers, session.streamParts = nil, map, {}, {}
	session.computer, session.seat, session.finished = nil, nil, nil
	session.streamAt, session.streamIndex, session.streamPartIndex, session.seatFailures, session.refreshIndex =
		0, 0, 0, 0, 0
	session.idleSince = nil
	session.evading, session.beasts, session.beastRoles, session.beastScanAt = nil, nil, nil, 0
	session.partsSeen, session.regions, session.regionList = setmetatable({}, { __mode = "k" }), {}, {}
	session.delayed = setmetatable({}, { __mode = "k" })
	if not map or not map:IsDescendantOf(workspace) then
		return
	end
	local function add(object)
		Flee.cachePart(session, object)
	end
	session.added = map.DescendantAdded:Connect(add)
	for _, object in ipairs(map:GetDescendants()) do
		add(object)
	end
end

function Flee.stream(session, generation)
	if not Flee.life(session, generation) or os.clock() < (session.streamAt or 0) then
		return
	end
	session.streamAt = os.clock() + 3
	Flee.refresh(session)
	local point, anchor
	local regions = session.regionList or {}
	for _ = 1, math.min(64, #regions) do
		session.streamIndex = (session.streamIndex or 0) % #regions + 1
		local part = regions[session.streamIndex].part
		if part:IsDescendantOf(session.map) and part.CanCollide ~= false then
			point, anchor = part.Position, part
			break
		end
	end
	if not point and session.map:IsA("Model") then
		local ok, frame, size = pcall(function()
			return session.map:GetBoundingBox()
		end)
		if ok and typeof(frame) == "CFrame" and typeof(size) == "Vector3" then
			local offsets = {
				Vector3.zero,
				Vector3.new(0.35, 0, 0.35),
				Vector3.new(-0.35, 0, 0.35),
				Vector3.new(0.35, 0, -0.35),
				Vector3.new(-0.35, 0, -0.35),
			}
			session.streamIndex = (session.streamIndex or 0) % #offsets + 1
			local offset = offsets[session.streamIndex]
			point = frame.Position + Vector3.new(offset.X * size.X, 0, offset.Z * size.Z)
		end
	end
	if not point then
		local parts = session.streamParts or {}
		for _ = 1, math.min(64, #parts) do
			session.streamPartIndex = (session.streamPartIndex or 0) % math.max(1, #parts) + 1
			local part = parts[session.streamPartIndex]
			if part and part:IsDescendantOf(session.map) and part.CanCollide ~= false then
				point, anchor = part.Position, part
				break
			end
		end
	end
	if not point then
		return
	end
	call("Flee map streaming", function()
		if Flee.life(session, generation) then
			App.player:RequestStreamAroundAsync(point, 2)
		end
	end, 3, generation)
	return point, anchor
end

function Flee.escapeReady()
	local left = Storage:FindFirstChild("ComputersLeft")
	return left ~= nil and type(left.Value) == "number" and left.Value <= 0
end

function Flee.search(session, generation, escape)
	if not Flee.life(session, generation) or Flee.escapeReady() ~= escape then
		return nil
	end
	session.idleSince = session.idleSince or os.clock()
	Flee.refresh(session)
	local target = Flee.pick(session, escape)
	if target then
		return target
	end
	local left = Storage:FindFirstChild("ComputersLeft")
	local count = left and tonumber(left.Value)
	status(
		escape and "Looking for an exit" or "Looking for the next computer",
		escape and "Checking the map for an exit"
			or ((count and tostring(count) .. " computers left. " or "") .. "Looking for another unfinished PC"),
		App.progress
	)
	local point, anchor = Flee.stream(session, generation)
	if not Flee.life(session, generation) or Flee.escapeReady() ~= escape then
		return nil
	end
	target = Flee.pick(session, escape)
	if target or not point or os.clock() - session.idleSince < 4 then
		return target
	end
	local model, root = character()
	if not model or (root.Position - point).Magnitude < 16 then
		return nil
	end
	local map = session.map
	Flee.move(session, point, generation, anchor, function()
		return session.map == map
			and Flee.life(session, generation, model)
			and not Flee.threatened(session)
			and Flee.safe(session, root.Position, point)
			and Flee.escapeReady() == escape
			and Flee.pick(session, escape) == nil
	end)
	if Flee.life(session, generation, model) and Flee.escapeReady() == escape then
		return Flee.pick(session, escape)
	end
	return nil
end

function Flee.pick(session, escape)
	local _, root = character()
	if not root then
		return nil
	end
	local seat = session.seat
	if seat then
		local sign = seat.Parent and seat:FindFirstChild("ActionSign")
		local busy = seat.Parent and seat:FindFirstChild("Value")
		if
			escape
			or not seat:IsDescendantOf(session.map)
			or not sign
			or sign.Value ~= 20
			or Flee.finished(session, seat.Parent)
			or not Flee.safe(session, root.Position, seat.Position)
			or busy and busy.Value and (session.trigger ~= seat or Flee.value(session, "CurrentAnimation") ~= "Typing")
			or (session.seatFailures or 0) >= 3
		then
			if (session.seatFailures or 0) >= 3 and seat.Parent then
				session.delayed[seat.Parent] = os.clock() + 12
			end
			session.seat, session.computer = nil, nil
			session.seatFailures = 0
		else
			return os.clock() >= (session.delayed[seat] or 0) and seat or nil
		end
	end
	local best, score
	for object in pairs(session.triggers) do
		if not object:IsDescendantOf(session.map) then
			session.triggers[object] = nil
			continue
		end
		if (session.delayed[object] or 0) > os.clock() or (session.delayed[object.Parent] or 0) > os.clock() then
			continue
		end
		local sign, event = object:FindFirstChild("ActionSign"), object:FindFirstChild("Event")
		local kind = sign and sign.Value
		if kind == 20 and Flee.finished(session, object.Parent) then
			continue
		end
		local valid = event
			and ((escape and object.Name == "ExitDoorTrigger") or (not escape and (kind == 20 or kind == 31)))
		local busy = object:FindFirstChild("Value")
		if kind == 20 and busy and busy:IsA("BoolValue") and busy.Value then
			valid = false
		end
		if not valid then
			continue
		end
		if not Flee.safe(session, root.Position, object.Position) then
			continue
		end
		local distance = (object.Position - root.Position).Magnitude
		local rank = distance - (kind == 31 and 10000 or 0)
		if not score or rank < score then
			best, score = object, rank
		end
	end
	return best
end

function Flee.refuge(session, root, computer)
	local target, point, best
	for candidate in pairs(session.triggers) do
		local sign = candidate:FindFirstChild("ActionSign")
		local busy = candidate:FindFirstChild("Value")
		if
			candidate:IsDescendantOf(session.map)
			and candidate.Parent ~= computer
			and sign
			and sign.Value == 20
			and candidate:FindFirstChild("Event")
			and not (busy and busy.Value)
			and not Flee.finished(session, candidate.Parent)
			and os.clock() >= (session.delayed[candidate.Parent] or 0)
			and os.clock() >= (session.delayed[candidate] or 0)
			and Flee.safe(session, root.Position, candidate.Position, 64)
		then
			local score = (candidate.Position - root.Position).Magnitude
			if not best or score < best then
				target, point, best = candidate, candidate.Position, score
			end
		end
	end
	if not point then
		for _, region in ipairs(session.regionList or {}) do
			local part = region.part
			if
				part:IsDescendantOf(session.map)
				and part.CanCollide ~= false
				and os.clock() >= (session.delayed[part] or 0)
				and os.clock() >= (session.delayed[part.Parent] or 0)
				and Flee.safe(session, root.Position, part.Position, 64)
			then
				local score = (part.Position - root.Position).Magnitude
				if not best or score < best then
					target, point, best = part, part.Position, score
				end
			end
		end
	end
	if not point then
		local nearest, away
		for _, beast in ipairs(Flee.beasts(session)) do
			if
				beast.player.Character == beast.model
				and beast.root:IsDescendantOf(beast.model)
				and beast.model:IsDescendantOf(workspace)
				and beast.humanoid.Health > 0
			then
				local delta = root.Position - beast.root.Position
				if not nearest or delta.Magnitude < nearest then
					nearest, away = delta.Magnitude, Vector3.new(delta.X, 0, delta.Z)
				end
			end
		end
		if away then
			if away.Magnitude < 0.1 then
				away = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
			end
			local turn = (session.evadeAttempt or 0) % 3
			if turn == 1 then
				away = Vector3.new(away.X - away.Z * 0.75, 0, away.Z + away.X * 0.75)
			elseif turn == 2 then
				away = Vector3.new(away.X + away.Z * 0.75, 0, away.Z - away.X * 0.75)
			end
			local candidate = root.Position + away * (80 / away.Magnitude)
			if Flee.safe(session, root.Position, candidate, 64) then
				point = candidate
			end
		end
	end
	return target, point
end

function Flee.evade(session, generation)
	local model, root = character()
	if not model or not Flee.life(session, generation, model, true) then
		return false
	end
	local distance = Flee.distance(session, root.Position)
	if distance >= (session.evading and 56 or 36) then
		session.evading = nil
		return false
	end
	session.evading = true
	local computer = session.computer
	Flee.release(session)
	if computer then
		session.delayed[computer] = os.clock() + 12
	end
	session.seat, session.computer, session.seatFailures = nil, nil, 0
	status("Beast nearby", "Moving away before continuing", App.progress)
	local ready = waitUntil(function()
		return not active(generation) or Flee.life(session, generation, model)
	end, 0.6, generation)
	if not ready or not Flee.life(session, generation, model) then
		return true
	end
	for _ = 1, 3 do
		local target, point = Flee.refuge(session, root, computer)
		session.evadeAttempt = (session.evadeAttempt or 0) + 1
		if not point then
			break
		end
		status(
			"Beast nearby",
			target and target.Name:find("ComputerTrigger", 1, true) and "Switching to another computer"
				or "Moving to a safer room",
			App.progress
		)
		local moved = Flee.move(session, point, generation, target, function()
			return Flee.life(session, generation, model) and Flee.safe(session, root.Position, point, 52)
		end)
		if moved or not Flee.life(session, generation, model) or Flee.distance(session, root.Position) >= 56 then
			break
		end
		if target then
			session.delayed[target] = os.clock() + 3
			if target.Name:find("ComputerTrigger", 1, true) then
				session.delayed[target.Parent] = os.clock() + 3
			end
		end
	end
	return true
end

function Flee.exitOpen(session, target)
	if not Flee.escapeReady() or not target:IsDescendantOf(session.map) then
		return false
	end
	local door = target.Parent
	local sign = target:FindFirstChild("ActionSign")
	if door:GetAttribute("Opened") == true or door:GetAttribute("Open") == true or sign and sign.Value == 11 then
		return true
	end
	if sign and sign.Value == 12 then
		return false
	end
	local panel = door:FindFirstChild("Door")
	local hinge = panel and panel:FindFirstChild("Hinge")
	local area = door:FindFirstChild("ExitArea")
	if not hinge or not hinge:IsA("BasePart") or not area or not area:IsA("BasePart") then
		return false
	end
	local model = character()
	local toward = area.Position - target.Position
	local axis = area.CFrame.LookVector
	local along = axis.X * toward.X + axis.Y * toward.Y + axis.Z * toward.Z
	if math.abs(along) < 1 then
		axis = Vector3.new(toward.X, 0, toward.Z)
		if axis.Magnitude < 1 then
			return false
		end
		axis = axis * (1 / axis.Magnitude)
		along = toward.Magnitude
	elseif along < 0 then
		axis, along = axis * -1, -along
	end
	local params = RaycastParams.new()
	params.FilterType, params.RespectCanCollide = Enum.RaycastFilterType.Exclude, true
	params.FilterDescendantsInstances = model and { model } or {}
	local delta = axis * (along + 2)
	return workspace:Raycast(area.Position - delta, delta, params) == nil
end

function Flee.openExit(session, target, generation)
	local model = character()
	local sign, event = target:FindFirstChild("ActionSign"), target:FindFirstChild("Event")
	local door, map = target.Parent, session.map
	local function valid()
		return Flee.life(session, generation, model, true)
			and Flee.escapeReady()
			and not Flee.threatened(session)
			and session.map == map
			and target:IsDescendantOf(map)
			and target.Parent == door
			and target:FindFirstChild("ActionSign") == sign
			and target:FindFirstChild("Event") == event
	end
	if not sign or not event or not valid() then
		return
	end
	if not Flee.move(session, target.Position, generation, target, valid) then
		return
	end
	local _, root = character()
	if not valid() or (root.Position - target.Position).Magnitude > 5 then
		return
	end
	if not Flee.exitOpen(session, target) then
		status("Opening the exit", "Staying at the wheel until the door opens", App.progress)
		local ready = waitUntil(function()
			return not valid() and "interrupted"
				or Flee.exitOpen(session, target) and "open"
				or sign.Value == 12 and "ready"
		end, 6, generation)
		if ready == "ready" then
			root.CFrame = CFrame.lookAt(root.Position, root.Position + target.CFrame.LookVector)
			session.trigger, session.openingExit = target, target
			fire(session.remote, "Input", "Trigger", true, event)
			local accepted = waitUntil(function()
				return not valid() and "interrupted"
					or Flee.exitOpen(session, target) and "open"
					or Flee.value(session, "OnTrigger") == true and "ready"
			end, 3, generation)
			if accepted == "ready" and valid() then
				if type(session.stats.SetValue) == "function" then
					pcall(session.stats.SetValue, "ActionInput", true)
				end
				fire(session.remote, "Input", "Action", true)
				local expires = os.clock() + 45
				while valid() and not Flee.exitOpen(session, target) and os.clock() < expires do
					if (root.Position - target.Position).Magnitude > 5 then
						break
					end
					if not pause(0.05, generation) then
						break
					end
				end
			end
		end
		Flee.release(session)
	end
	if not valid() or not Flee.exitOpen(session, target) then
		session.delayed[target] = os.clock() + 2
		if Flee.threatened(session) then
			Flee.evade(session, generation)
		end
		return
	end
	if
		not waitUntil(function()
			return not valid() and "interrupted" or Flee.life(session, generation, model) and "ready"
		end, 2, generation) or not valid()
	then
		return
	end
	local area = door:FindFirstChild("ExitArea")
	if area and area:IsA("BasePart") then
		status("Leaving through the open exit", "Door's open, heading out", App.progress)
		Flee.move(session, area.Position, generation, area, function()
			return valid() and Flee.exitOpen(session, target)
		end)
	end
end

function Flee.use(session, target, generation)
	if target.Name == "ExitDoorTrigger" then
		return Flee.openExit(session, target, generation)
	end
	local model = character()
	local sign = target:FindFirstChild("ActionSign")
	local event = target:FindFirstChild("Event")
	local kind = sign and sign.Value
	local computer = target.Parent
	local function allowed()
		return Flee.life(session, generation, model, kind == 20)
			and not Flee.threatened(session)
			and target:IsDescendantOf(session.map)
			and target:FindFirstChild("ActionSign") == sign
			and target:FindFirstChild("Event") == event
			and (kind ~= 20 or target.Parent == computer and not Flee.finished(session, computer))
	end
	if not sign or not event or not allowed() then
		return
	end
	if kind == 20 then
		if session.seat ~= target then
			session.seatFailures = 0
		end
		session.seat, session.computer = target, target.Parent
	end
	local moved, moveReason = Flee.move(session, target.Position, generation, target, allowed)
	if not moved or not allowed() or sign.Value ~= kind then
		if kind == 20 and allowed() then
			session.seatFailures = (session.seatFailures or 0) + 1
		end
		session.delayed[target] = os.clock() + 2
		if moveReason and allowed() then
			status("Moving to the interaction", moveReason, App.progress)
		end
		return
	end
	local _, root = character()
	if (root.Position - target.Position).Magnitude > 5 then
		return
	end
	root.CFrame = CFrame.lookAt(root.Position, root.Position + target.CFrame.LookVector)
	session.trigger = target
	fire(session.remote, "Input", "Trigger", true, event)
	local accepted = waitUntil(function()
		return not allowed() and "interrupted" or Flee.value(session, "OnTrigger") == true and "ready"
	end, 3, generation)
	if accepted ~= "ready" then
		if kind == 20 then
			session.seatFailures = (session.seatFailures or 0) + 1
		end
		Flee.release(session)
		session.delayed[target] = os.clock() + 2
		Flee.evade(session, generation)
		return
	end
	local function press()
		if not allowed() or sign.Value ~= kind or Flee.value(session, "OnTrigger") ~= true then
			return false
		end
		local previous = Flee.value(session, "ActionProgress")
		if type(session.stats.SetValue) == "function" then
			pcall(session.stats.SetValue, "ActionInput", true)
		end
		if kind == 20 then
			session.hackStartingUntil = os.clock() + 2.5
		end
		fire(session.remote, "Input", "Action", true)
		local started = waitUntil(function()
			local progress = Flee.value(session, "ActionProgress")
			return not allowed()
				or Flee.value(session, "CurrentAnimation") == "Typing"
				or type(progress) == "number" and progress > (tonumber(previous) or 0)
		end, kind == 20 and 2 or 0.2, generation)
		fire(session.remote, "Input", "Action", false)
		return started and allowed()
	end
	if kind == 20 then
		local started = false
		for _ = 1, 3 do
			if not allowed() or sign.Value ~= kind then
				break
			end
			started = press()
			if started then
				break
			end
			if not pause(0.35, generation) then
				break
			end
		end
		if not started then
			session.seatFailures = (session.seatFailures or 0) + 1
			Flee.release(session)
			session.delayed[target] = os.clock() + 2
			if Flee.evade(session, generation) then
				return
			end
			status("Starting the hack", "Waiting for the computer to accept the interaction", App.progress)
			return
		end
		status("Hacking the computer", "Staying at this keyboard until the hack finishes", App.progress)
		session.seatFailures = 0
		session.hacking = true
	elseif kind == 31 or kind == 12 then
		press()
	end
	local lastProgress = Flee.value(session, "ActionProgress")
	local changed, deadline, nextPress = os.clock(), os.clock() + 600, os.clock() + 2
	local finishedAt, stalled
	while allowed() and os.clock() < deadline do
		local carry = tonumber(session.candy.UnstoredCandy) or 0
		local stored = tonumber(session.candy.StoredCandy) or 0
		if kind ~= 20 and carry >= math.min(30, math.max(1, 100 - stored)) and stored < 100 then
			break
		end
		if kind ~= 20 and sign.Value ~= kind then
			break
		end
		local progress = Flee.value(session, "ActionProgress")
		if progress ~= lastProgress then
			lastProgress, changed = progress, os.clock()
		end
		if kind == 20 then
			local typing = Flee.value(session, "CurrentAnimation") == "Typing"
			local progressing = type(progress) == "number" and progress > 0 and progress < 1
			if sign.Value ~= 20 and not typing and not progressing then
				finishedAt = finishedAt or os.clock()
				if os.clock() - finishedAt >= 1.25 then
					break
				end
			else
				finishedAt = nil
			end
			if (root.Position - target.Position).Magnitude > 5 then
				break
			end
			if Flee.value(session, "OnTrigger") ~= true then
				fire(session.remote, "Input", "Trigger", true, event)
				if not pause(0.25, generation) then
					break
				end
			elseif
				Flee.value(session, "CurrentAnimation") ~= "Typing"
				and os.clock() - changed > 2
				and os.clock() >= nextPress
			then
				press()
				nextPress = os.clock() + 2
			end
			if os.clock() - changed > 45 then
				stalled = true
				break
			end
			Flee.solveTiming(session, generation)
		elseif kind == 31 then
			local torso = target:FindFirstChild("CapturedTorso")
			if not torso or not torso.Value then
				break
			end
			if os.clock() - changed > 10 then
				break
			end
		elseif kind == 12 then
			if os.clock() - changed > 18 then
				break
			end
		else
			break
		end
		if not pause(kind == 20 and 0.03 or 0.12, generation) then
			break
		end
	end
	if Flee.threatened(session) and Flee.evade(session, generation) then
		return
	end
	Flee.release(session)
	if stalled then
		session.seat, session.computer, session.seatFailures = nil, nil, 0
		session.delayed[computer] = os.clock() + 12
		status("Computer stopped responding", "Trying another task before returning to this PC", App.progress)
		return
	end
	if kind == 20 and Flee.finished(session, computer) then
		session.seat, session.computer, session.seatFailures = nil, nil, 0
		status("Computer finished", "Moving on to the next task", App.progress)
		return
	end
	if not allowed() then
		return
	end
	if kind == 20 and sign.Value ~= 20 then
		session.seat, session.computer = nil, nil
		session.delayed[target.Parent] = os.clock() + 3
	end
	session.delayed[target] = os.clock() + 2
end

function Flee.deposit(session, generation)
	Flee.release(session)
	local bucket = session.candy.CandyBucket
	local prompt = bucket
		and bucket:IsDescendantOf(workspace)
		and bucket:FindFirstChildWhichIsA("ProximityPrompt", true)
	local point = prompt and EventInput.point(prompt.Parent)
	local model = character()
	local function allowed()
		return Flee.life(session, generation, model)
			and not Flee.threatened(session)
			and session.candy.CandyBucket == bucket
	end
	if not point or not allowed() then
		return false
	end
	local carry, stored = session.candy.UnstoredCandy, session.candy.StoredCandy
	if not Flee.move(session, point, generation, bucket, allowed) or not allowed() then
		return false
	end
	EventInput.hold(session, prompt, generation, allowed)
	return waitUntil(function()
		return not allowed() or session.candy.StoredCandy ~= stored or session.candy.UnstoredCandy ~= carry
	end, 4, generation) and allowed()
end

function Flee.solveTiming(session, generation)
	local circle = getPath(App.player, "PlayerGui", "ScreenGui", "TimingCircle")
	local pin = circle and circle:FindFirstChild("TimingPin")
	local base = circle and circle:FindFirstChild("TimingBase")
	local goal = Flee.value(session, "TimingGoalPosition")
	if
		session.trigger
		and Flee.life(session, generation, nil, true)
		and not Flee.threatened(session)
		and circle
		and circle.Visible
		and pin
		and base
		and type(goal) == "number"
		and goal > 0
		and Flee.value(session, "ActionInput") == false
		and Flee.value(session, "OnTrigger") == true
		and pin.Rotation >= goal + 20
		and pin.Rotation <= goal + 65
	then
		pcall(session.stats.SetValue, "ActionInput", true)
		fire(session.remote, "Input", "Action", true)
		pause(0.04, generation)
		fire(session.remote, "Input", "Action", false)
	end
end

function Flee.timing(session, generation)
	while active(generation) do
		Flee.solveTiming(session, generation)
		if not pause(0.025, generation) then
			break
		end
	end
end

local function runFlee(generation)
	if verify(current, true) then
		return true, "The Flee the Facility badge is already earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = { triggers = {}, delayed = {}, generation = generation }
	table.insert(App.cleanups, function()
		Flee.release(session)
		if session.added then
			session.added:Disconnect()
		end
	end)
	local loaded = waitUntil(function()
		return getPath(Storage, "Halloween2026ClientAssets", "HalloweenClientModule")
			and App.player:FindFirstChild("TempPlayerStatsModule")
			and Storage:FindFirstChild("RemoteEvent")
	end, 45, generation)
	if not loaded then
		return false, "Flee's Halloween event hasn't loaded. Join a round, then try again."
	end
	session.statsObject = App.player:FindFirstChild("TempPlayerStatsModule")
	session.stats = module(session.statsObject, generation)
	session.candy = module(getPath(Storage, "Halloween2026ClientAssets", "HalloweenClientModule"), generation)
	session.remote = Storage:FindFirstChild("RemoteEvent")
	if type(session.stats) ~= "table" or type(session.candy) ~= "table" then
		return false, "Couldn't read Flee's round or candy data"
	end
	local expires, badgeAt, depositAt = os.clock() + 10800, 0, 0
	while active(generation) and os.clock() < expires do
		local statsObject = App.player:FindFirstChild("TempPlayerStatsModule")
		if statsObject ~= session.statsObject or not session.stats and os.clock() >= (session.statsRetryAt or 0) then
			Flee.release(session)
			session.statsObject = statsObject
			session.stats = statsObject and module(statsObject, generation)
			session.statsRetryAt = os.clock() + 2
		end
		if session.map ~= Flee.map() then
			Flee.watchMap(session, Flee.map())
		end
		local stored = tonumber(session.candy.StoredCandy) or 0
		local carry = tonumber(session.candy.UnstoredCandy) or 0
		if os.clock() >= badgeAt and (stored >= 100 or Flee.value(session, "Escaped")) then
			badgeAt = os.clock() + 15
			if verify(current, true) then
				return true, "Flee the Facility badge earned"
			end
			if not active(generation) then
				break
			end
		end
		local detail = string.format("%d / 100 stored | %d / 30 carried", stored, carry)
		if session.candy._Status ~= "Active" then
			status("Waiting for Halloween", "The game's event UI hasn't started yet", stored / 110)
		elseif not Flee.life(session, generation) then
			Flee.release(session)
			local beast = Flee.value(session, "IsBeast")
			status(
				"Flee the Facility",
				detail
					.. "\n"
					.. (
						beast and "You're the Beast. The helper will resume when you're a survivor."
						or "Waiting for a survivor round, or for you to be freed"
					),
				stored / 110
			)
		elseif Flee.evade(session, generation) then
		elseif carry > 0 and stored < 100 and os.clock() >= depositAt then
			status("Storing candy", detail, stored / 110)
			local deposited = Flee.deposit(session, generation)
			depositAt = os.clock() + (deposited and 1 or 6)
		else
			local escaping = Flee.escapeReady()
			local target = Flee.pick(session, escaping)
			if not target then
				target = Flee.search(session, generation, escaping)
			end
			if target then
				session.idleSince = nil
				status(
					"Flee the Facility",
					detail .. "\n" .. (escaping and "Opening an exit and escaping" or "Hacking and freeing survivors"),
					stored / 110
				)
				Flee.use(session, target, generation)
			end
		end
		if not pause(0.35, generation) then
			break
		end
	end
	return false, active(generation) and "The Flee run reached its time limit" or "Stopped"
end

local Demon = {}

function Demon.life(session, generation, allowHold)
	local model, root, humanoid = character()
	return active(generation)
		and model ~= nil
		and (not session.model or model == session.model)
		and workspace:GetAttribute("IntroState") == "Complete"
		and not App.player:GetAttribute("Caught")
		and not App.player:GetAttribute("Dead")
		and not App.player:GetAttribute("Escaped")
		and not App.player:GetAttribute("WatchingReveal")
		and not App.player:GetAttribute("Hiding")
		and not App.player:GetAttribute("PickingLock")
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and (not root.Anchored or (allowHold and session.prompt ~= nil))
end

function Demon.hunt(session)
	local state = session.state
	local hunt = state:GetAttribute("HuntState")
	local monster = getPath(session.world, "Runtime", "Shapeshifter")
	return state:GetAttribute("Hunting") == true
		or hunt == "Arriving"
		or hunt == "Hunting"
		or (
			monster
			and monster:GetAttribute("Mode") == "Chasing"
			and monster:GetAttribute("Target") == App.player.UserId
		)
end

function Demon.equip(session, generation)
	local carried = App.player:GetAttribute("CarriedRelic")
	if not carried or carried == "" then
		return true
	end
	local item = App.player:GetAttribute("InvSlot1")
	if not item or item == "" then
		return false
	end
	if App.player:GetAttribute("EquippedObject") == item then
		return true
	end
	if not Demon.life(session, generation) then
		return false
	end
	fire(getPath(Storage, "Events", "RequestItemEquip"), "InvSlot1")
	return waitUntil(function()
		return not Demon.life(session, generation) or App.player:GetAttribute("EquippedObject") == item
	end, 3, generation) and Demon.life(session, generation)
end

function Demon.fingerprint(session)
	local values = {
		tostring(session.state:GetAttribute("Stage")),
		tostring(session.state:GetAttribute("RelicsPlaced")),
		tostring(App.player:GetAttribute("CarriedRelic")),
		tostring(session.state:GetAttribute("PortalState")),
	}
	for _, relic in ipairs(session.relics:GetChildren()) do
		table.insert(
			values,
			relic.Name
				.. ":"
				.. tostring(relic:GetAttribute("State"))
				.. ":"
				.. tostring(relic:GetAttribute("Step"))
				.. ":"
				.. tostring(relic:GetAttribute("Progress"))
		)
	end
	table.sort(values)
	return table.concat(values, "|")
end

function Demon.associated(target, relic, quest)
	if quest and target:IsDescendantOf(quest) then
		return true
	end
	local display = relic:GetAttribute("DisplayName")
	if
		target.Name == relic.Name
		or (type(display) == "string" and display ~= "" and target:GetAttribute("DisplayName") == display)
	then
		return true
	end
	local hint = relic:GetAttribute("HintPosition")
	local point = EventInput.point(target)
	return typeof(hint) == "Vector3" and point ~= nil and (point - hint).Magnitude < 24
end

function Demon.targets(session, predicate)
	local result = {}
	for _, target in ipairs(Collection:GetTagged("LiminalTarget")) do
		if
			target:IsDescendantOf(workspace)
			and not target:GetAttribute("Uninteractable")
			and (not predicate or predicate(target))
		then
			table.insert(result, target)
		end
	end
	return result
end

function Demon.stepKey(relic)
	return relic.Name .. ":" .. tostring(relic:GetAttribute("Step")) .. ":" .. tostring(relic:GetAttribute("StepType"))
end

function Demon.choose(session)
	local carried = App.player:GetAttribute("CarriedRelic")
	local stage = session.state:GetAttribute("Stage")
	if
		stage == "FindAltar"
		or stage == "Ritual"
		or stage == "Portal"
		or session.relics:FindFirstChild(carried or "")
	then
		local attr = stage == "Portal" and "PortalCFrame" or (stage == "Ritual" and "RitualCFrame" or "AltarCFrame")
		local frame = session.state:GetAttribute(attr) or session.state:GetAttribute("AltarCFrame")
		local role = stage == "Ritual" and "Ritual" or "Altar"
		local targets = Demon.targets(session, function(target)
			if target:GetAttribute("Role") == role or (stage == "Ritual" and target.Name == "RitualSpot") then
				return true
			end
			local point = EventInput.point(target)
			local quests = session.world:FindFirstChild("Quests")
			return stage == "Ritual"
				and frame
				and point
				and (point - frame.Position).Magnitude < 12
				and not (quests and target:IsDescendantOf(quests))
				and target:GetAttribute("Role") ~= "Altar"
		end)
		return targets[1], frame and frame.Position, nil
	end
	if stage ~= "Relics" then
		return nil
	end
	local relics = session.relics:GetChildren()
	table.sort(relics, function(a, b)
		return (a:GetAttribute("Order") or 0) < (b:GetAttribute("Order") or 0)
	end)
	local _, root = character()
	local relic = session.focus
	local function available(value)
		local state = value and value.Parent and value:GetAttribute("State")
		return (state == "InProgress" or state == "Available" or state == "Dropped")
			and ((session.blocked and session.blocked[value]) or 0) <= os.clock()
	end
	if not available(relic) then
		relic = nil
		for _, item in ipairs(relics) do
			if available(item) then
				relic = item
				break
			end
		end
		session.focus = relic
	end
	if not relic then
		return nil
	end
	local quest = getPath(session.world, "Quests", relic.Name)
	local hint = relic:GetAttribute("HintPosition")
	if relic:GetAttribute("StepType") == "HoldZone" and relic:GetAttribute("State") == "InProgress" then
		local zone = quest and quest:FindFirstChild("Zone")
		return nil, relic:GetAttribute("ZoneCenter") or (zone and EventInput.point(zone)) or hint, relic
	end
	local candidates = Demon.targets(session, function(target)
		local role = target:GetAttribute("Role")
		local state = relic:GetAttribute("State")
		if state == "Available" or state == "Dropped" or relic:GetAttribute("StepType") == "Collect" then
			return role == "Relic" and Demon.associated(target, relic, quest)
		end
		return role ~= "Altar" and role ~= "Ritual" and role ~= "Relic" and Demon.associated(target, relic, quest)
	end)
	if relic:GetAttribute("StepType") == "FindTicking" then
		local dressing = getPath(session.world, "Runtime", "QuestDressing")
		local towers = quest and quest:FindFirstChild("ClockTowers")
		local tower
		if dressing and towers then
			for _, item in ipairs(dressing:GetDescendants()) do
				if item:GetAttribute("Ticking") == true then
					tower = towers:FindFirstChild(item.Name)
					if tower then
						break
					end
				end
			end
		end
		if not tower then
			return nil, hint, relic
		end
		local matching = {}
		for _, target in ipairs(candidates) do
			if target == tower or target:IsDescendantOf(tower) then
				table.insert(matching, target)
			end
		end
		candidates = matching
	end
	local missing
	for _, target in ipairs(candidates) do
		local need = target:GetAttribute("Needs")
		if need and need ~= carried then
			missing = need
			break
		end
	end
	if missing then
		local spec = session.config.QuestItems[missing]
		local source = spec and quest and quest:FindFirstChild(spec.Source, true)
		local sources = Demon.targets(session, function(target)
			return (source and (target == source or target:IsDescendantOf(source)))
				or target.Name == missing
				or (spec and target:GetAttribute("DisplayName") == spec.DisplayName)
		end)
		if #sources > 0 then
			candidates = sources
		else
			return nil, source and EventInput.point(source) or hint, relic
		end
	end
	local best, score
	for _, target in ipairs(candidates) do
		if (session.delayed[target] or 0) > os.clock() then
			continue
		end
		if session.done and session.done[target] == Demon.stepKey(relic) then
			continue
		end
		local need = target:GetAttribute("Needs")
		if need and need ~= carried then
			continue
		end
		local point = EventInput.point(target)
		if not point then
			continue
		end
		local rank = root and (root.Position - point).Magnitude or 0
		if target:GetAttribute("Highlighted") then
			rank -= 10000
		end
		if target:GetAttribute("Ticking") == false then
			continue
		end
		if relic:GetAttribute("StepType") == "InteractOrdered" then
			local order = target:GetAttribute("Order") or tonumber(target.Name:match("%d+"))
			if order then
				if order ~= (relic:GetAttribute("Progress") or 0) + 1 then
					continue
				end
				rank -= 20000
			end
		end
		if not score or rank < score then
			best, score = target, rank
		end
	end
	return best, best and EventInput.point(best) or hint, relic
end

function Demon.makeRoom(session, target, generation)
	local role, need = target:GetAttribute("Role"), target:GetAttribute("Needs")
	local taking = role == "Relic" or role == "QuestItem"
	for id, spec in pairs(session.config.QuestItems or {}) do
		if
			target.Name == id
			or target.Name == spec.Source
			or (type(spec.DisplayName) == "string" and target:GetAttribute("DisplayName") == spec.DisplayName)
		then
			taking = true
		end
	end
	if not taking or need then
		return true
	end
	local carried, item = App.player:GetAttribute("CarriedRelic"), App.player:GetAttribute("InvSlot1")
	if not item or item == "" then
		return not carried or carried == ""
	end
	if session.relics:FindFirstChild(carried or "") then
		return false, "Take the carried relic to the altar first"
	end
	local spec = carried and session.config.QuestItems[carried]
	if spec and spec.Relic then
		local quest = session.relics:FindFirstChild(spec.Relic)
		if quest and quest:GetAttribute("State") == "InProgress" and quest:GetAttribute("StepType") ~= "Collect" then
			return false, "The " .. carried .. " is still needed for its quest"
		end
	elseif carried and carried ~= "" and not spec then
		return false, "Put down the item you're carrying before taking this relic"
	end
	local model = character()
	local function allowed()
		return Demon.life(session, generation)
			and App.player.Character == model
			and target:IsDescendantOf(workspace)
			and not Demon.hunt(session)
	end
	if not allowed() then
		return false, "Waiting until you can put the item down"
	end
	if session.drop and session.drop.item ~= item then
		session.drop = nil
	end
	if not session.drop then
		if App.player:GetAttribute("EquippedObject") ~= item then
			fire(getPath(Storage, "Events", "RequestItemEquip"), "InvSlot1")
			waitUntil(function()
				return not allowed() or App.player:GetAttribute("EquippedObject") == item
			end, 3, generation)
		end
		if
			not allowed()
			or App.player:GetAttribute("InvSlot1") ~= item
			or App.player:GetAttribute("EquippedObject") ~= item
		then
			return false, "Waiting for the carried item to be equipped"
		end
		status(
			"Making room for the relic",
			"Putting down " .. (spec and spec.DisplayName or "the held item"),
			App.progress
		)
		local sent, reason = fire(getPath(Storage, "Events", "RequestItemDrop"), "InvSlot1")
		if not sent then
			return false, reason
		end
		session.drop = { item = item }
	end
	local function empty()
		local slot, holding = App.player:GetAttribute("InvSlot1"), App.player:GetAttribute("CarriedRelic")
		return (not slot or slot == "") and (not holding or holding == "")
	end
	waitUntil(function()
		return not allowed() or empty()
	end, 4, generation)
	if allowed() and empty() then
		session.drop = nil
		return true
	end
	return false, "Waiting for the inventory slot to clear"
end

function Demon.interact(session, target, generation)
	if not target or not Demon.life(session, generation) then
		return false
	end
	local room, reason = Demon.makeRoom(session, target, generation)
	if not room then
		return false, reason
	end
	if not Demon.equip(session, generation) then
		return false, "Waiting for the quest item to equip"
	end
	local prompt = target:FindFirstChildWhichIsA("ProximityPrompt", true)
	if not prompt then
		return false, "Waiting for the game's prompt"
	end
	local point = EventInput.point(prompt.Parent)
	local model = character()
	local function allowed(hold)
		return Demon.life(session, generation, hold)
			and App.player.Character == model
			and target:IsDescendantOf(workspace)
			and not target:GetAttribute("Uninteractable")
			and not Demon.hunt(session)
	end
	if not point or not allowed() then
		return false
	end
	local offset = target:IsA("Model") and target:GetPivot().LookVector or Vector3.new(0, 0, 1)
	local _, root = character()
	if (root.Position - point).Magnitude > math.min(4, prompt.MaxActivationDistance * 0.6) then
		if not approach(point + offset * 2.5, generation, target, false, allowed) then
			return false
		end
	end
	if not allowed() then
		return false
	end
	local before = Demon.fingerprint(session)
	local focus = session.focus
	local step = focus and Demon.stepKey(focus)
	local progress = focus and focus:GetAttribute("Progress")
	session.picked = true
	local sent, reason = EventInput.hold(session, prompt, generation, function()
		return allowed(true)
	end, {
		accepted = function()
			return Demon.fingerprint(session) ~= before
				or App.player:GetAttribute("PickingLock")
				or target:GetAttribute("Uninteractable")
		end,
	})
	if sent then
		waitUntil(function()
			return not active(generation)
				or Demon.fingerprint(session) ~= before
				or App.player:GetAttribute("PickingLock")
				or target:GetAttribute("Uninteractable")
		end, 3, generation)
	end
	session.delayed[target] = os.clock() + (Demon.fingerprint(session) ~= before and 0.25 or 5)
	if
		focus
		and step == Demon.stepKey(focus)
		and type(progress) == "number"
		and (focus:GetAttribute("Progress") or 0) > progress
	then
		session.done = session.done or setmetatable({}, { __mode = "k" })
		session.done[target] = step
	end
	return sent, reason
end

function Demon.shelter(session, generation)
	if not Demon.hunt(session) then
		if session.hid and App.player:GetAttribute("Hiding") then
			fire(session.remotes.Hide, nil)
			pause(0.4, generation)
		end
		session.hid = nil
		return false
	end
	EventInput.release(session)
	if App.player:GetAttribute("PickingLock") then
		fire(session.remotes.LockPick, "Cancel")
	end
	if App.player:GetAttribute("Hiding") then
		status("Demonology", "Waiting out the hunt in the wardrobe", App.progress)
		return true
	end
	if not Demon.life(session, generation) then
		return true
	end
	local _, root = character()
	local closet, distance
	for _, candidate in ipairs(Collection:GetTagged("LiminalCloset")) do
		if candidate:IsDescendantOf(workspace) and (candidate:GetAttribute("Occupant") or 0) == 0 then
			local point = EventInput.point(candidate)
			local length = point and (point - root.Position).Magnitude
			if length and (not distance or length < distance) then
				closet, distance = candidate, length
			end
		end
	end
	if closet then
		local prompt = closet:FindFirstChildWhichIsA("ProximityPrompt", true)
		local point = prompt and EventInput.point(prompt.Parent)
		local function ready()
			return Demon.life(session, generation) and Demon.hunt(session)
		end
		if point and approach(point, generation, closet, false, ready) and ready() then
			session.hid = true
			EventInput.hold(session, prompt, generation, ready)
		end
		status("Demonology", "Finding cover until the hunt passes", App.progress)
	else
		status("Demonology", "The hunt started, but the wardrobes haven't loaded", App.progress)
	end
	return true
end

function Demon.lockpick(session, generation)
	if not App.player:GetAttribute("PickingLock") then
		return false
	end
	local panel = getPath(App.player, "PlayerGui", "LockPick", "Panel")
	local needle = panel and getPath(panel, "Dial", "Needle")
	local notch = panel and getPath(panel, "Dial", "Notch")
	status("Picking the lock", "Waiting for the needle to enter the red notch", App.progress)
	local expires, tapAt = os.clock() + 35, os.clock() + 0.4
	while active(generation) and App.player:GetAttribute("PickingLock") and os.clock() < expires do
		if Demon.hunt(session) or App.player:GetAttribute("Caught") or App.player:GetAttribute("WatchingReveal") then
			fire(session.remotes.LockPick, "Cancel")
			return true
		end
		if panel and panel.Visible and needle and notch and os.clock() >= tapAt then
			local delta = math.abs((needle.Rotation - notch.Rotation + 180) % 360 - 180)
			if delta <= 8 then
				local touchTarget = getPath(App.player, "PlayerGui", "LockPick", "TapArea")
				if not EventInput.tap(session, generation, nil, touchTarget) then
					status("Pick the lock", "Tap the red notch yourself. I'll keep going after that.", App.progress)
					pause(0.5, generation)
				end
				tapAt = os.clock() + 0.4
			end
		end
		if not pause(0.025, generation) then
			break
		end
	end
	if active(generation) and App.player:GetAttribute("PickingLock") then
		fire(session.remotes.LockPick, "Cancel")
	end
	return true
end

function Demon.portalPoint(state)
	local doorway = state:GetAttribute("PortalDoorway")
	if typeof(doorway) == "CFrame" then
		return doorway.Position
	end
	local frame = state:GetAttribute("PortalCFrame")
	return typeof(frame) == "CFrame" and (frame * CFrame.new(0, 5, 0)).Position or nil
end

local function runDemonology(generation)
	if verify(current, true) then
		return true, "The Demonology badge is already earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	if game.PlaceId ~= current.eventPlace then
		local loaded = waitUntil(function()
			return getPath(Storage, "Events", "StartTheHollow")
		end, 40, generation)
		if not loaded then
			return false, "Open Demonology's lobby to start The Hollow"
		end
		if not App.player:GetAttribute("TutorialCompleted") then
			return false, "Finish Demonology's tutorial first"
		end
		if not App.player:GetAttribute("IsPartyLeader") then
			return false, "Ask your party leader to start The Hollow from the menu"
		end
		local times = module(getPath(Storage, "Modules", "Timestamps"), generation)
		local now = workspace:GetServerTimeNow()
		if
			type(times) ~= "table"
			or type(times.SomewhereElseEvent2026StartTime) ~= "number"
			or type(times.SomewhereElseEvent2026EndTime) ~= "number"
		then
			return false, "The event dates haven't loaded"
		end
		if now < times.SomewhereElseEvent2026StartTime or now >= times.SomewhereElseEvent2026EndTime then
			return false, "Demonology's Hollow event is closed"
		end
		if not active(generation) then
			return false, "Stopped"
		end
		prepareTravel(current.eventPlace, true)
		status("Joining Somewhere Else", "Make sure your party is ready", 0)
		local failed
		local connection = Teleport.TeleportInitFailed:Connect(function(player, _, message)
			if player == App.player then
				failed = tostring(message)
			end
		end)
		table.insert(App.cleanups, function()
			connection:Disconnect()
		end)
		local sent, reason = fire(loaded)
		if not sent then
			return false, reason
		end
		waitUntil(function()
			return failed
		end, 65, generation)
		if failed then
			return false, "Couldn't join: " .. failed
		end
		return false,
			active(generation) and "The event hasn't started. Check your party's ready status, then try again."
				or "Stopped"
	end
	local session = { delayed = setmetatable({}, { __mode = "k" }) }
	table.insert(App.cleanups, function()
		EventInput.release(session)
		if session.remotes then
			if session.hid and App.player:GetAttribute("Hiding") then
				fire(session.remotes.Hide, nil)
			end
			if session.picked and App.player:GetAttribute("PickingLock") then
				fire(session.remotes.LockPick, "Cancel")
			end
		end
	end)
	status("Loading Somewhere Else", "Waiting for the town and introduction", 0)
	local loaded = waitUntil(function()
		return getPath(Storage, "LiminalEvent", "Relics")
			and workspace:FindFirstChild("LiminalEvent")
			and getPath(Storage, "Events", "Liminal", "Interact")
	end, 60, generation)
	if not loaded then
		return false, "The Hollow quest hasn't loaded in this server"
	end
	session.state = Storage:FindFirstChild("LiminalEvent")
	session.relics = session.state:FindFirstChild("Relics")
	session.world = workspace:FindFirstChild("LiminalEvent")
	session.remotes = getPath(Storage, "Events", "Liminal")
	session.config = module(getPath(Storage, "Modules", "LiminalConfig"), generation)
	if type(session.config) ~= "table" then
		return false, "Couldn't read the relic quest rules"
	end
	local previous, progressAt, stalled = nil, os.clock(), 0
	local expires, badgeAt = os.clock() + 5400, 0
	while active(generation) and os.clock() < expires do
		local placed = tonumber(session.state:GetAttribute("RelicsPlaced")) or 0
		local count = tonumber(session.state:GetAttribute("RelicCount")) or 6
		local stage = session.state:GetAttribute("Stage")
		local escaped = App.player:GetAttribute("Escaped")
		if os.clock() >= badgeAt and (escaped or stage == "Complete") then
			badgeAt = os.clock() + 10
			if verify(current, true) then
				return true, "Demonology badge earned"
			end
			if not active(generation) then
				break
			end
		end
		if escaped then
			status("Back from Somewhere Else", "Waiting for the badge award", 0.98)
		elseif App.player:GetAttribute("Caught") or App.player:GetAttribute("Dead") then
			EventInput.release(session)
			status("Demonology", "You've been caught. Waiting for the game to return you or revive you.", App.progress)
		elseif workspace:GetAttribute("IntroState") ~= "Complete" or not stage then
			status("Demonology", "Waiting for the intro to finish", 0)
		elseif Demon.shelter(session, generation) then
		elseif App.player:GetAttribute("PickingLock") then
			session.picked = true
			Demon.lockpick(session, generation)
		elseif Demon.life(session, generation) then
			session.model = App.player.Character
			local fingerprint = Demon.fingerprint(session)
			if fingerprint ~= previous then
				previous, progressAt, stalled = fingerprint, os.clock(), 0
			end
			if os.clock() - progressAt > 60 then
				stalled += 1
				session.blocked = session.blocked or setmetatable({}, { __mode = "k" })
				if session.focus then
					session.blocked[session.focus] = os.clock() + 40
				end
				session.focus = nil
				session.delayed = setmetatable({}, { __mode = "k" })
				progressAt = os.clock()
				log("Still looking for the next relic")
				if stalled >= 4 and stage ~= "Ritual" then
					return false,
						"No quest progress after several attempts ("
							.. tostring(stage)
							.. "). Check Logs and the game's current objective, then try Start again."
				end
			end
			local target, point, relic = Demon.choose(session)
			local label = relic and (relic:GetAttribute("DisplayName") or relic.Name)
				or (session.config.StageObjectives[stage] or stage)
			local objective = relic and (relic:GetAttribute("Objective") or "") or ""
			if stage == "Ritual" and session.state:GetAttribute("RitualStyle") == "Gather" then
				objective = string.format(
					"%d / %d players in the circle. Waiting for everyone.",
					session.state:GetAttribute("GatherCount") or 0,
					session.state:GetAttribute("GatherNeeded") or 1
				)
			end
			status(
				"Demonology",
				string.format("%d / %d relics on the altar\n%s\n%s", placed, count, label, objective),
				math.min(0.95, placed / math.max(1, count) * 0.85 + (stage == "Portal" and 0.1 or 0))
			)
			if stage == "Portal" and session.state:GetAttribute("PortalState") == "Open" then
				local portal = Demon.portalPoint(session.state)
				if portal then
					approach(portal, generation, nil, false, function()
						return Demon.life(session, generation)
					end)
					pause(1, generation)
				end
			elseif target then
				local ok, reason = Demon.interact(session, target, generation)
				if not ok and reason then
					log(reason)
				end
			elseif typeof(point) == "Vector3" then
				local _, root = character()
				local distance = (root.Position - point).Magnitude
				local holdZone = relic and relic:GetAttribute("StepType") == "HoldZone"
				if distance > (holdZone and math.max(2, (relic:GetAttribute("ZoneRadius") or 5) * 0.4) or 6) then
					approach(point, generation, nil, false, function()
						return Demon.life(session, generation) and not Demon.hunt(session)
					end)
				end
			end
		else
			if session.model ~= App.player.Character then
				session.model = nil
			end
			status("Demonology", "Waiting until you can move again", App.progress)
		end
		if not pause(0.25, generation) then
			break
		end
	end
	return false, active(generation) and "The Demonology run reached its time limit" or "Stopped"
end

local Dandy = {}

function Dandy.value(object, name)
	local child = object and object:FindFirstChild(name)
	if child and child:IsA("ValueBase") then
		return child.Value
	end
	return nil
end

function Dandy.progress(session)
	if session.data and type(session.data.getMyReplica) == "function" then
		local ok, replica = pcall(session.data.getMyReplica, session.data)
		local seasonal = ok and replica and type(replica.Data) == "table" and replica.Data.Seasonal
		local holiday = type(seasonal) == "table" and seasonal.Halloween26
		if
			type(seasonal) == "table"
			and (holiday == nil or type(holiday) == "table" and holiday.RobloxEventEarned == nil)
		then
			return 0
		end
		if type(holiday) == "table" and type(holiday.RobloxEventEarned) == "number" then
			return holiday.RobloxEventEarned
		end
	end
	local folder = getPath(Storage, "PlayerData", tostring(App.player.UserId), "Seasonal", "Halloween26")
	return Dandy.value(folder, "RobloxEventEarned")
end

function Dandy.decoding()
	local model = App.player.Character
	return model and Dandy.value(model, "Decoding")
end

function Dandy.life(session, generation, allowDecode)
	local model, root, humanoid = character()
	return active(generation)
		and model ~= nil
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and model:FindFirstChild("Stats") ~= nil
		and model:IsDescendantOf(workspace:FindFirstChild("InGamePlayers") or workspace)
		and not model:GetAttribute("Transforming")
		and not model:GetAttribute("GrabbedBySquirm")
		and not model:FindFirstChild("Grabbed")
		and not model:GetAttribute("AbilityAnimationActive")
		and (
			not root.Anchored
			or (allowDecode and ((session.owned ~= nil and Dandy.decoding() == session.owned) or session.door ~= nil))
		)
end

function Dandy.round(session)
	return Dandy.value(session.info, "Floor"),
		Dandy.value(session.info, "FloorActive") == true
			and Dandy.value(session.info, "Loading") ~= true
			and Dandy.value(session.info, "Panic") ~= true
end

function Dandy.cancelMove(session)
	local motion = session.motion
	session.motion = nil
	if motion then
		if motion.connection then
			motion.connection:Disconnect()
		end
		if motion.tween then
			pcall(motion.tween.Cancel, motion.tween)
		end
	end
end

function Dandy.ground(position, root, humanoid, params, box)
	if typeof(position) ~= "Vector3" or position.Y <= workspace.FallenPartsDestroyHeight + 32 then
		return nil
	end
	local hit = workspace:Raycast(position + Vector3.new(0, box and 0 or 3, 0), Vector3.new(0, -12, 0), params)
	if not hit or hit.Normal.Y < 0.65 or hit.Position.Y <= workspace.FallenPartsDestroyHeight + 32 then
		return nil
	end
	local point = hit.Position + Vector3.new(0, math.max(2.6, (humanoid.HipHeight or 2) + root.Size.Y / 2), 0)
	if box then
		local relative = box.CFrame:PointToObjectSpace(point)
		if
			math.abs(relative.X) >= box.Size.X / 2 - 1
			or math.abs(relative.Z) >= box.Size.Z / 2 - 1
			or math.abs(relative.Y) >= box.Size.Y / 2
		then
			return nil
		end
	end
	return point
end

function Dandy.rays(model, ignore)
	local params = RaycastParams.new()
	params.FilterType, params.RespectCanCollide, params.IgnoreWater = Enum.RaycastFilterType.Exclude, true, true
	local excluded = { model }
	if ignore then
		table.insert(excluded, ignore)
	end
	for _, player in ipairs(Players:GetPlayers()) do
		if player.Character and player.Character ~= model then
			table.insert(excluded, player.Character)
		end
	end
	params.FilterDescendantsInstances = excluded
	return params
end

function Dandy.span(session, from, destination, root, humanoid, params, escaping)
	if (destination - from).Magnitude > 64 or not Dandy.safe(session, from, destination, escaping) then
		return false
	end
	local steps = math.max(1, math.ceil((destination - from).Magnitude / 2))
	local previous = from
	for index = 1, steps do
		local expected = from:Lerp(destination, index / steps)
		local point = Dandy.ground(expected, root, humanoid, params)
		if not point or math.abs(point.Y - expected.Y) > 0.75 or math.abs(point.Y - previous.Y) > 3 then
			return false
		end
		if (point - previous).Magnitude > 0.05 and workspace:Raycast(previous, point - previous, params) then
			return false
		end
		previous = point
	end
	return true
end

function Dandy.move(session, position, generation, ignore, insideCabin, canMove, escaping)
	Dandy.cancelMove(session)
	local model, root, humanoid = character()
	if not model or typeof(position) ~= "Vector3" or not escaping and os.clock() < (session.moveAfter or 0) then
		return false
	end
	local floor = Dandy.value(session.info, "Floor")
	local function ready()
		local nowModel, nowRoot, nowHumanoid = character()
		return active(generation)
			and nowModel == model
			and nowRoot == root
			and root:IsDescendantOf(workspace)
			and not root.Anchored
			and not nowHumanoid.Sit
			and not nowHumanoid.PlatformStand
			and nowHumanoid.WalkSpeed > 0
			and not model:GetAttribute("Transforming")
			and not model:GetAttribute("GrabbedBySquirm")
			and not model:FindFirstChild("Grabbed")
			and not model:GetAttribute("AbilityAnimationActive")
			and Dandy.value(session.info, "Floor") == floor
			and (not canMove or canMove())
	end
	if not ready() then
		return false
	end
	local params = Dandy.rays(model, ignore)
	local goal = Dandy.ground(position, root, humanoid, params, insideCabin and ignore or nil)
	if not goal then
		return false, "No floor at that destination"
	end
	if (root.Position - goal).Magnitude <= 0.75 then
		return true
	end
	local loaded, services = pcall(function()
		return { tween = game:GetService("TweenService"), paths = game:GetService("PathfindingService") }
	end)
	if not loaded then
		return false, "The movement services haven't loaded"
	end
	local waypoints = { { Position = goal } }
	if not Dandy.span(session, root.Position, goal, root, humanoid, params, escaping) then
		local planned, route = call("Dandy route", function()
			local path = services.paths:CreatePath({
				AgentRadius = 2,
				AgentHeight = 5,
				AgentCanJump = false,
				WaypointSpacing = 4,
			})
			path:ComputeAsync(root.Position, goal)
			if path.Status == Enum.PathStatus.Success then
				return path:GetWaypoints()
			end
			return nil
		end, 5, generation)
		if not planned or type(route) ~= "table" or #route == 0 or not ready() then
			session.moveAfter = os.clock() + 2
			return false, "Couldn't find a walkable route"
		end
		waypoints = route
	end
	local speed = math.min(52, humanoid.WalkSpeed * 3.25)
	local deadline = os.clock() + math.min(180, (root.Position - goal).Magnitude / speed * 3 + 12)
	local function finish(success, reason)
		Dandy.cancelMove(session)
		if not success and active(generation) then
			session.moveAfter = os.clock() + (escaping and 0 or 0.2)
			if reason and session.moveReason ~= reason then
				log(reason)
				session.moveReason = reason
			end
		elseif success then
			session.moveReason = nil
		end
		return success, reason
	end
	local previousPoint = root.Position
	for _, waypoint in ipairs(waypoints) do
		if not Dandy.safe(session, previousPoint, waypoint.Position, escaping) then
			return finish(false, "A Twisted blocks that route")
		end
		previousPoint = waypoint.Position
	end
	local route = {}
	local previous = root.Position
	for index, waypoint in ipairs(waypoints) do
		if waypoint.Action == Enum.PathWaypointAction.Jump then
			return finish(false, "That route needs a jump")
		end
		local point = index == #waypoints and goal or Dandy.ground(waypoint.Position, root, humanoid, params)
		if not point then
			return finish(false, "The next part of the floor hasn't loaded")
		end
		if (point - previous).Magnitude > 0.05 then
			table.insert(route, point)
			previous = point
		end
	end
	local index = 1
	while index <= #route do
		if not ready() then
			return finish(false, "Movement interrupted")
		end
		local reach, destination
		for candidate = math.min(#route, index + 7), index, -1 do
			if Dandy.span(session, root.Position, route[candidate], root, humanoid, params, escaping) then
				reach, destination = candidate, route[candidate]
				break
			end
		end
		if not destination then
			return finish(false, "That way's blocked, trying another route")
		end
		local steps = 1
		local from = root.Position
		for step = 1, steps do
			if not ready() or os.clock() > deadline then
				return finish(false, "Movement interrupted")
			end
			local point = Dandy.ground(from:Lerp(destination, step / steps), root, humanoid, params)
			if not point or math.abs(point.Y - root.Position.Y) > 3 then
				return finish(false, "The route crosses a gap or a steep ledge")
			end
			local delta = point - root.Position
			if delta.Magnitude < 0.05 then
				continue
			end
			if not Dandy.safe(session, root.Position, point, escaping) then
				return finish(false, "A Twisted is approaching")
			end
			if workspace:Raycast(root.Position, delta, params) then
				return finish(false, "The route is blocked")
			end
			local duration = math.max(0.025, delta.Magnitude / speed)
			local segmentUntil = os.clock() + duration + 2
			local motion = { root = root, done = false }
			session.motion = motion
			local made, tween = pcall(
				services.tween.Create,
				services.tween,
				root,
				TweenInfo.new(duration, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut),
				{ CFrame = CFrame.lookAt(point, point + root.CFrame.LookVector) }
			)
			if not made then
				return finish(false, "Couldn't start movement")
			end
			motion.tween = tween
			motion.connection = tween.Completed:Connect(function(state)
				motion.done = true
				motion.state = state
			end)
			local started = pcall(tween.Play, tween)
			if not started then
				return finish(false, "Couldn't start movement")
			end
			local previous, observed = root.Position, os.clock()
			while not motion.done do
				if session.motion ~= motion or not ready() then
					return finish(false, "Movement interrupted")
				end
				if not Dandy.safe(session, root.Position, point, escaping) then
					return finish(false, "A Twisted is approaching")
				end
				if not pause(0.02, generation) then
					return finish(false, "Stopped")
				end
				if session.motion ~= motion or not ready() then
					return finish(false, "Movement interrupted")
				end
				local now = os.clock()
				if not Dandy.safe(session, root.Position, point, escaping) then
					return finish(false, "A Twisted is approaching")
				end
				if (root.Position - previous).Magnitude > speed * (now - observed) + 2.5 then
					return finish(false, "Got moved, checking the route again")
				end
				if humanoid.WalkSpeed * 3.25 < speed - 0.1 then
					return finish(false, "Movement speed changed")
				end
				previous, observed = root.Position, now
				if now > deadline or now > segmentUntil then
					return finish(false, "Movement timed out")
				end
			end
			if
				not ready()
				or motion.state ~= Enum.PlaybackState.Completed
				or (root.Position - point).Magnitude > 1.25
			then
				return finish(false, "Movement did not finish")
			end
			Dandy.cancelMove(session)
		end
		index = reach + 1
	end
	if (root.Position - goal).Magnitude <= 1.25 then
		return finish(true)
	end
	return finish(false, "The destination changed")
end

function Dandy.endMachine(session)
	EventInput.release(session)
	local owned = session.owned
	session.owned = nil
	if owned and Dandy.decoding() == owned then
		fire(getPath(Storage, "Events", "StopInteracting"), "Stop")
	end
end

function Dandy.inside(root, box)
	if not root or not box then
		return false
	end
	local p = box.CFrame:PointToObjectSpace(root.Position)
	return math.abs(p.X) < box.Size.X / 2 - 1 and math.abs(p.Z) < box.Size.Z / 2 - 1 and math.abs(p.Y) < box.Size.Y / 2
end

function Dandy.elevator(session, generation)
	Dandy.endMachine(session)
	local box = getPath(workspace, "Elevators", "Elevator", "ElevatorHitBox")
	local model, root = character()
	if not box or not model then
		return false
	end
	if Dandy.inside(root, box) then
		return true
	end
	if not Dandy.life(session, generation) then
		waitUntil(function()
			return not active(generation) or Dandy.life(session, generation)
		end, 3, generation)
	end
	local function allowed()
		return Dandy.life(session, generation) and App.player.Character == model and box:IsDescendantOf(workspace)
	end
	if not allowed() then
		return false
	end
	local point = box.Position - Vector3.new(0, box.Size.Y / 2 - 4, 0)
	return Dandy.move(session, point, generation, box, true, allowed, true)
end

function Dandy.enemies(session)
	if os.clock() >= (session.enemyAt or 0) then
		session.enemyAt = os.clock() + 0.2
		for _, object in ipairs(Collection:GetTagged("Twisted")) do
			local model = object:IsA("Model") and object or object.Parent
			local root = if object:IsA("BasePart")
				then object
				else model and ((model:IsA("Model") and model.PrimaryPart) or model:FindFirstChild(
					"HumanoidRootPart"
				))
			if root and root:IsA("BasePart") and root:IsDescendantOf(workspace) then
				session.monsters[root] = true
			end
		end
	end
	return session.monsters
end

function Dandy.enemy(root)
	if not root:IsDescendantOf(workspace) or not root.Parent then
		return nil
	end
	local humanoid = root.Parent:FindFirstChildOfClass("Humanoid")
	if humanoid and humanoid.Health <= 0 then
		return nil
	end
	local position = root.Position
	local velocity = root.AssemblyLinearVelocity
	local predicted = position
	if typeof(velocity) == "Vector3" and velocity.Magnitude < 100 then
		predicted += velocity * 0.6
	end
	local chasing = root.Parent:GetAttribute("Chasing") == true or Dandy.value(root.Parent, "Chasing") == true
	local radius = root.Parent.Name == "DandyMonster" and 44 or chasing and 32 or 26
	return position, predicted, radius
end

function Dandy.safe(session, from, destination, escaping)
	local clearance, safe = math.huge, true
	local dx, dz = destination.X - from.X, destination.Z - from.Z
	local length = dx * dx + dz * dz
	for root in pairs(Dandy.enemies(session)) do
		local position, predicted, radius = Dandy.enemy(root)
		if not root:IsDescendantOf(workspace) then
			session.monsters[root] = nil
		elseif position then
			for _, point in ipairs({ position, predicted }) do
				if math.abs(point.Y - from.Y) > 14 and math.abs(point.Y - destination.Y) > 14 then
					continue
				end
				local alpha = length > 0
						and math.clamp(((point.X - from.X) * dx + (point.Z - from.Z) * dz) / length, 0, 1)
					or 0
				local x, z = from.X + dx * alpha - point.X, from.Z + dz * alpha - point.Z
				local distance = math.sqrt(x * x + z * z)
				clearance = math.min(clearance, distance - radius)
				if distance < radius then
					local start = math.sqrt((from.X - point.X) ^ 2 + (from.Z - point.Z) ^ 2)
					local attackBuffer = root.Parent.Name == "DandyMonster" and 16 or 12
					if not escaping or length > 0.0025 and distance < math.min(start, attackBuffer) - 0.1 then
						safe = false
					end
				end
			end
		end
	end
	return safe, clearance
end

function Dandy.retreat(session, generation)
	Dandy.endMachine(session)
	local model, root, humanoid = character()
	if not model or not Dandy.life(session, generation) then
		return false
	end
	session.retreatUntil = os.clock() + 3
	if os.clock() < (session.escapeRetryAt or 0) then
		return false
	end
	local _, currentClearance = Dandy.safe(session, root.Position, root.Position)
	local params = Dandy.rays(model)
	local candidates = {}
	local function add(point, box)
		local safe = Dandy.safe(session, root.Position, point, true)
		local _, clearance = Dandy.safe(session, point, point)
		if not safe or clearance < currentClearance + 0.5 then
			return
		end
		local floorParams = box and Dandy.rays(model, box) or params
		point = Dandy.ground(point, root, humanoid, floorParams, box)
		if not point then
			return
		end
		local delta = point - root.Position
		if delta.Magnitude < 2 then
			return
		end
		local clearLine = workspace:Raycast(root.Position, delta, floorParams) == nil
		local score = clearance + (clearLine and 10000 or 0) + (box and 6 or 0)
		if session.escapeDirection then
			score += 3 * (delta.X * session.escapeDirection.X + delta.Z * session.escapeDirection.Z) / delta.Magnitude
		end
		table.insert(candidates, { point = point, score = score, box = box })
	end
	local box = getPath(workspace, "Elevators", "Elevator", "ElevatorHitBox")
	if box then
		add(box.Position - Vector3.new(0, box.Size.Y / 2 - 4, 0), box)
	end
	for _, length in ipairs({ 10, 24 }) do
		for bearing = 0, 15 do
			local angle = bearing * math.pi / 8
			add(root.Position + Vector3.new(math.cos(angle) * length, 0, math.sin(angle) * length))
		end
	end
	table.sort(candidates, function(a, b)
		return a.score > b.score
	end)
	for index = 1, math.min(6, #candidates) do
		if not active(generation) then
			break
		end
		local candidate = candidates[index]
		local direction = candidate.point - root.Position
		status("Dandy's World", "Moving away from the Twisteds", App.progress)
		if
			Dandy.move(session, candidate.point, generation, candidate.box, candidate.box ~= nil, function()
				return Dandy.life(session, generation) and App.player.Character == model
			end, true)
		then
			local length = math.max(0.01, direction.Magnitude)
			session.escapeDirection = Vector3.new(direction.X / length, 0, direction.Z / length)
			session.escapeRetryAt = nil
			return true
		end
	end
	session.escapeRetryAt = os.clock() + 0.15
	status("Dandy's World", "Finding a clear path around the nearby obstacles", App.progress)
	return false
end

function Dandy.threat(session, point)
	local nearest = math.huge
	for root in pairs(Dandy.enemies(session)) do
		local position = Dandy.enemy(root)
		if not root:IsDescendantOf(workspace) then
			session.monsters[root] = nil
		elseif position then
			nearest = math.min(nearest, (position - point).Magnitude)
		end
	end
	return nearest
end

function Dandy.watch(session, room)
	Dandy.cancelMove(session)
	Dandy.endMachine(session)
	if session.added then
		session.added:Disconnect()
	end
	session.room, session.prompts, session.monsters = room, {}, {}
	session.enemyAt = nil
	session.delayed = setmetatable({}, { __mode = "k" })
	if not room then
		return
	end
	local function add(object)
		if object:IsA("ProximityPrompt") then
			session.prompts[object] = true
		end
		if object:IsA("BasePart") and object.Name == "HumanoidRootPart" then
			local parent = object.Parent
			while parent and parent ~= room do
				if parent.Name == "Monsters" then
					session.monsters[object] = true
					break
				end
				parent = parent.Parent
			end
		end
	end
	session.added = room.DescendantAdded:Connect(add)
	for _, object in ipairs(room:GetDescendants()) do
		add(object)
	end
end

function Dandy.classify(session, prompt)
	if not prompt:IsDescendantOf(session.room) or not prompt.Enabled or prompt.MaxActivationDistance <= 0 then
		return nil
	end
	local parent = prompt.Parent
	local slot = 1
	while parent and parent ~= session.room do
		local index = tonumber(parent.Name:match("^Prompt(%d+)$"))
		if index then
			slot = index
		end
		local stats = parent:FindFirstChild("Stats")
		if stats and Dandy.value(stats, "Completed") ~= nil then
			if Dandy.value(stats, "Completed") then
				return nil
			end
			local kind = parent:GetAttribute("Prompt" .. slot .. "MinigameType") or parent:GetAttribute("MinigameType")
			if kind == "Barnaby" then
				return nil, parent, "The remaining Barnaby cabinet needs manual play. The helper will resume afterward."
			end
			local occupant = Dandy.value(stats, "ActivePlayer" .. (slot == 1 and "" or tostring(slot)))
			if occupant and occupant ~= App.player.Character then
				return nil
			end
			return "machine", parent
		end
		if parent:GetAttribute("TrickOrTreatUsed") ~= nil then
			return parent:GetAttribute("TrickOrTreatUsed") == false and "door" or nil, parent
		end
		if parent.Name == "Pumpkins" or parent.Name == "Pumpkin" then
			return "pumpkin", parent
		end
		parent = parent.Parent
	end
	local text = string.lower(prompt.ObjectText or "")
	if text == "pumpkins" or text == "pumpkin" or text == "hallowed pumpkin" then
		return "pumpkin", prompt.Parent
	end
	return nil
end

function Dandy.pumpkins(session)
	local entries, seen = {}, {}
	local function add(target, kind, object, point)
		if point and not seen[object] then
			seen[object] = true
			table.insert(entries, { target = target, kind = kind, object = object, point = point })
		end
	end
	for prompt in pairs(session.prompts) do
		if not prompt:IsDescendantOf(session.room) then
			session.prompts[prompt] = nil
		else
			local role, owner = Dandy.classify(session, prompt)
			if role == "pumpkin" then
				if not owner:IsA("Model") and not owner:IsA("BasePart") then
					owner = prompt.Parent
				end
				add(prompt, role, owner, EventInput.point(prompt.Parent))
			end
		end
	end
	for _, tag in ipairs({ "TreatPumpkin", "HolidayCollectibleItem", "HalloweenCollectibleItem" }) do
		for _, piece in ipairs(Collection:GetTagged(tag)) do
			if piece:IsDescendantOf(workspace) and piece:GetAttribute("TreatPumpkinCollectedBy") == nil then
				local prompt = piece:FindFirstChildWhichIsA("ProximityPrompt", true)
				if tag == "TreatPumpkin" or not prompt then
					add(piece, "treat", piece, EventInput.point(piece))
				elseif prompt.Enabled then
					add(prompt, "pumpkin", piece, EventInput.point(prompt.Parent))
				end
			end
		end
	end
	return entries
end

function Dandy.pick(session)
	local _, root = character()
	if not root then
		return nil
	end
	local target, kind, object, best
	local entries = Dandy.pumpkins(session)
	for _, entry in ipairs(entries) do
		local distance = (entry.point - root.Position).Magnitude
		if
			(not best or distance < best)
			and (session.delayed[entry.target] or 0) <= os.clock()
			and Dandy.safe(session, entry.point, entry.point)
		then
			target, kind, object, best = entry.target, entry.kind, entry.object, distance
		end
	end
	return target, kind, object, #entries
end

function Dandy.clearEsp(state)
	if state.preview and state.preview.added then
		state.preview.added:Disconnect()
	end
	state.preview = nil
	for target, marker in pairs(state.marks) do
		marker:Destroy()
		state.marks[target] = nil
	end
	for target, label in pairs(state.labels or {}) do
		label:Destroy()
		state.labels[target] = nil
	end
	if state.folder then
		state.folder:Destroy()
		state.folder = nil
	end
end

function Dandy.espTick(state)
	local room = workspace:FindFirstChild("CurrentRoom")
	if not room then
		Dandy.clearEsp(state)
		return
	end
	local source = App.dandySession
	if not source or source.room ~= room then
		if not state.preview then
			state.preview = {}
		end
		if state.preview.room ~= room then
			Dandy.watch(state.preview, room)
		end
		source = state.preview
	elseif state.preview then
		if state.preview.added then
			state.preview.added:Disconnect()
		end
		state.preview = nil
	end
	local _, root = character()
	local entries = Dandy.pumpkins(source)
	local copies = {}
	for _, object in ipairs(workspace:GetChildren()) do
		if object.Name == "TreatPumpkinLocal" and (object:IsA("Model") or object:IsA("BasePart")) then
			local point = EventInput.point(object)
			if point then
				table.insert(copies, { object = object, point = point })
			end
		end
	end
	table.sort(entries, function(a, b)
		return (a.point - (root and root.Position or Vector3.zero)).Magnitude
			< (b.point - (root and root.Position or Vector3.zero)).Magnitude
	end)
	local visible, usedCopies = {}, {}
	state.labels = state.labels or {}
	for index = 1, math.min(24, #entries) do
		local entry = entries[index]
		local object = entry.object
		while object and object ~= room and not object:IsA("Model") and not object:IsA("BasePart") do
			object = object.Parent
		end
		if not object or object == room then
			continue
		end
		visible[entry.target] = true
		local marker = state.marks[entry.target]
		if not marker then
			if not state.folder then
				state.folder = Instance.new("Folder")
				state.folder.Name = "HollowPumpkinESP"
				state.folder.Parent = workspace
			end
			marker = Instance.new("Highlight")
			marker.Name = "Pumpkin"
			marker.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			marker.FillColor = Color3.fromRGB(255, 170, 75)
			marker.OutlineColor = Color3.fromRGB(255, 225, 155)
			marker.FillTransparency, marker.OutlineTransparency = 0.5, 0.1
			marker.Parent = state.folder
			state.marks[entry.target] = marker
		end
		local display, nearest = object, 2.5
		for _, copy in ipairs(copies) do
			if not usedCopies[copy.object] then
				local distance = (copy.point - entry.point).Magnitude
				if distance < nearest then
					display, nearest = copy.object, distance
				end
			end
		end
		usedCopies[display] = true
		marker.Adornee = display
		local anchor = object:IsA("BasePart") and object
			or object.PrimaryPart
			or object:FindFirstChildWhichIsA("BasePart", true)
		if anchor then
			local label = state.labels[entry.target]
			if not label then
				label = Instance.new("BillboardGui")
				label.Name = "PumpkinLabel"
				label.AlwaysOnTop = true
				label.LightInfluence = 0
				label.Size = UDim2.fromOffset(80, 24)
				label.StudsOffset = Vector3.new(0, 2, 0)
				label.Parent = state.folder
				local text = Instance.new("TextLabel")
				text.Name = "Text"
				text.BackgroundTransparency = 1
				text.Size = UDim2.fromScale(1, 1)
				text.Text = "Pumpkin"
				text.TextColor3 = Color3.fromRGB(255, 215, 135)
				text.TextStrokeTransparency = 0.25
				text.TextSize = 13
				text.Font = Enum.Font.GothamBold
				text.Parent = label
				state.labels[entry.target] = label
			end
			label.Adornee = anchor
		end
	end
	for target, marker in pairs(state.marks) do
		if not visible[target] then
			marker:Destroy()
			state.marks[target] = nil
			if state.labels[target] then
				state.labels[target]:Destroy()
				state.labels[target] = nil
			end
		end
	end
end

function Dandy.setEsp(enabled)
	App.dandyPumpkinEsp = enabled == true
	local previous = App.dandyEspState
	App.dandyEspState = nil
	if previous then
		Dandy.clearEsp(previous)
	end
	if not App.dandyPumpkinEsp or not App.alive then
		return
	end
	local state = { marks = {}, labels = {} }
	App.dandyEspState = state
	task.spawn(function()
		while App.alive and App.dandyEspState == state do
			local ok, reason = pcall(Dandy.espTick, state)
			if not ok then
				log("Pumpkin ESP stopped: " .. tostring(reason))
				Dandy.setEsp(false)
				refresh()
				break
			end
			task.wait(0.25)
		end
		Dandy.clearEsp(state)
	end)
end

function Dandy.skillTarget(session)
	local gui = App.player:FindFirstChild("PlayerGui")
	local menu = session.context and session.context.Gui and session.context.Gui:FindFirstChild("Menu")
	local bar = menu and menu:FindFirstChild("SkillCheckFrame")
	local marker = bar and bar:FindFirstChild("Marker")
	local area = bar and bar:FindFirstChild("RequiredArea")
	if bar and bar.Visible and marker and area then
		local x = marker.AbsolutePosition.X + marker.AbsoluteSize.X / 2
		local start, width = area.AbsolutePosition.X, area.AbsoluteSize.X
		return width > 0 and x >= start + width * 0.25 and x <= start + width * 0.75
	end
	local circle = gui and getPath(gui, "CircleSkillCheckGui", "SkillCheckFrame")
	local container = circle and circle:FindFirstChild("Container")
	if circle and circle.Visible and container then
		local shrinking, grey, yellow =
			container:FindFirstChild("ShrinkingCircle"),
			container:FindFirstChild("GreyCircle"),
			container:FindFirstChild("YellowCircle")
		if shrinking and grey and yellow then
			local size = shrinking.Size.X.Offset
			return size > yellow.Size.X.Offset + 1 and size < grey.Size.X.Offset - 1
		end
	end
	local tapping = gui and getPath(gui, "TreadmillTapSkillCheckGui", "TapSkillCheckFrame")
	if tapping and tapping.Visible then
		return true
	end
	return false
end

function Dandy.skill(session, generation)
	if
		not Dandy.life(session, generation, true)
		or not Dandy.skillTarget(session)
		or os.clock() < (session.tapAt or 0)
	then
		return false
	end
	if not (session.owned or session.door) then
		return false
	end
	local key = Enum.KeyCode.Space
	if session.input and type(session.input.GetBoundKeyCode) == "function" then
		local ok, value = pcall(session.input.GetBoundKeyCode, session.input, "SkillCheckTap", "Keyboard")
		if ok and typeof(value) == "EnumItem" then
			key = value
		end
	end
	session.tapAt = os.clock() + 0.16
	if not EventInput.tap(session, generation, key) then
		session.inputBlocked = true
		return false
	end
	session.inputBlocked = nil
	return true
end

function Dandy.use(session, prompt, role, object, generation)
	local model = character()
	local floor = Dandy.value(session.info, "Floor")
	local point = EventInput.point(prompt.Parent)
	local function allowed(hold)
		local now, live = Dandy.round(session)
		return Dandy.life(session, generation, hold)
			and App.player.Character == model
			and now == floor
			and live
			and prompt:IsDescendantOf(workspace)
			and Dandy.safe(session, point, point)
	end
	if not point or not allowed() or Dandy.decoding() then
		return
	end
	if not Dandy.move(session, point, generation, object, false, allowed) or not allowed() then
		session.delayed[prompt] = os.clock() + 4
		return
	end
	if role == "machine" then
		session.owned = object
	end
	if role == "door" then
		session.door = object
	end
	EventInput.hold(session, prompt, generation, function()
		return allowed(true)
	end)
	local deadline, progressed = os.clock() + 160, os.clock()
	local last = Dandy.value(object:FindFirstChild("Stats"), "Amount")
	if role == "machine" then
		waitUntil(function()
			return not allowed(true) or Dandy.decoding() == object
		end, 3, generation)
		while allowed(true) and Dandy.decoding() == object and os.clock() < deadline do
			local amount = Dandy.value(object:FindFirstChild("Stats"), "Amount")
			if amount ~= last then
				last, progressed = amount, os.clock()
			end
			if Dandy.value(object:FindFirstChild("Stats"), "Completed") == true or os.clock() - progressed > 22 then
				break
			end
			Dandy.skill(session, generation)
			if not pause(0.025, generation) then
				break
			end
		end
		Dandy.endMachine(session)
	elseif role == "door" then
		local ends = os.clock() + 12
		while allowed(true) and object:GetAttribute("TrickOrTreatUsed") == false and os.clock() < ends do
			Dandy.skill(session, generation)
			if not pause(0.025, generation) then
				break
			end
		end
		session.door = nil
	else
		waitUntil(function()
			return not allowed() or not object:IsDescendantOf(workspace) or not prompt.Enabled
		end, 2, generation)
	end
	session.delayed[prompt] = os.clock() + 4
end

function Dandy.treat(session, generation, chosen)
	local floor, live = Dandy.round(session)
	if not live or not Dandy.life(session, generation) or Dandy.decoding() then
		return false
	end
	if not chosen then
		local target, kind = Dandy.pick(session)
		chosen = kind == "treat" and target or nil
	end
	if not chosen then
		return false
	end
	local model = character()
	local function allowed()
		local now, running = Dandy.round(session)
		return Dandy.life(session, generation)
			and App.player.Character == model
			and now == floor
			and running
			and chosen:IsDescendantOf(workspace)
			and chosen:GetAttribute("TreatPumpkinCollectedBy") == nil
	end
	if Dandy.move(session, EventInput.point(chosen), generation, chosen, false, allowed) and allowed() then
		pause(0.35, generation)
	end
	session.delayed[chosen] = os.clock() + 3
	return true
end

function Dandy.queue(session, generation)
	if not active(generation) then
		return
	end
	if App.player:GetAttribute("InLobby") then
		status("Dandy's World", "Waiting for your current queue to leave", App.progress)
		return
	end
	local gates = getPath(workspace, "RobloxHalloweenEvent", "HollowEventExternal", "Teleports")
	if not gates then
		status("Dandy's World", "Waiting for the Hollow gates to load", App.progress)
		return
	end
	local best, distance
	local _, root = character()
	if not root or root.Anchored then
		return
	end
	for _, group in ipairs(gates:GetChildren()) do
		local gate = group:FindFirstChild("HalloweenGate")
		local spawn = gate and gate:FindFirstChild("spawn")
		local opened = gate and Dandy.value(gate:FindFirstChild("Elevator"), "Opened")
		if
			spawn
			and opened == true
			and gate:GetAttribute("MatchmakeFilter") == "RobloxHalloweenEvent"
			and not gate:GetAttribute("Disabled")
			and not gate:GetAttribute("Teleporting")
			and not gate:GetAttribute("Searching")
		then
			local length = (root.Position - spawn.Position).Magnitude
			if not distance or length < distance then
				best, distance = spawn, length
			end
		end
	end
	if not best then
		status("Dandy's World", "Waiting for a Hollow gate to open", App.progress)
		return
	end
	local function allowed()
		local model, nowRoot = character()
		return active(generation)
			and model ~= nil
			and not nowRoot.Anchored
			and not App.player:GetAttribute("InLobby")
			and best:IsDescendantOf(gates)
			and best.Parent:GetAttribute("Disabled") ~= true
	end
	prepareTravel(current.gameplayPlace, true)
	session.queueAttempt = true
	local moved = Dandy.move(session, best.Position, generation, best, false, allowed)
	if moved or App.player:GetAttribute("InLobby") then
		waitUntil(function()
			return App.player:GetAttribute("InLobby")
		end, 5, generation)
		session.joined = App.player:GetAttribute("InLobby") == true
		if not active(generation) and session.joined then
			fire(getPath(Storage, "SharedUtils", "Network", "RemoteEvent"), "LeaveGate")
		end
	end
end

function Dandy.select(session, generation)
	local data = getPath(Storage, "PlayerData", tostring(App.player.UserId))
	local selected = Dandy.value(data, "SelectedCharacter")
	if not selected or selected == "" then
		if os.clock() < (session.voteAt or 0) then
			return
		end
		local towers = data and data:FindFirstChild("Towers")
		local owned = towers and towers:GetChildren() or {}
		table.sort(owned, function(a, b)
			return a.Name < b.Name
		end)
		if #owned == 0 then
			status("Choose a Toon", "Pick a character in the game's selection menu", App.progress)
			return
		end
		session.voteAt = os.clock() + 8
		if not active(generation) then
			return
		end
		invoke(getPath(Storage, "Events", "Voted"), generation, owned[1].Name)
		return
	end
	local ready = session.info:FindFirstChild("ReadyUpPlayers")
	if ready and not ready:FindFirstChild(App.player.Name) and os.clock() >= (session.readyAt or 0) then
		session.readyAt = os.clock() + 5
		if active(generation) then
			fire(getPath(Storage, "Events", "ReadyUpEvent"), "ReadyUp")
		end
	end
	status("Dandy's World", "Toon picked, waiting for the round", App.progress)
end

local function runDandy(generation)
	if verify(current, true) then
		return true, "The Dandy's World badge is already earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = { prompts = {}, monsters = {}, delayed = {}, progressAt = os.clock() }
	App.dandySession = session
	table.insert(App.cleanups, function()
		if App.dandySession == session then
			App.dandySession = nil
		end
		Dandy.cancelMove(session)
		Dandy.endMachine(session)
		if session.added then
			session.added:Disconnect()
		end
		if session.queueAttempt then
			fire(getPath(Storage, "SharedUtils", "Network", "RemoteEvent"), "LeaveGate")
		end
	end)
	local lobby = game.PlaceId == current.place
	local dataModule = waitUntil(function()
		return lobby and getPath(Storage, "Modules", "MyDataController")
			or getPath(Storage, "Modules", "ClientUI", "MyDataController")
	end, 40, generation)
	session.data = dataModule and module(dataModule, generation)
	local expires, badgeAt, unknownAt = os.clock() + 10800, 0, os.clock()
	if not lobby then
		session.info = waitUntil(function()
			return workspace:FindFirstChild("Info")
		end, 40, generation)
		if not session.info then
			return false, "The round data hasn't loaded"
		end
	end
	local lastProgress, lastFloor
	while active(generation) and os.clock() < expires do
		local progress = Dandy.progress(session)
		if progress ~= nil then
			unknownAt = os.clock()
			if progress ~= lastProgress then
				lastProgress, session.progressAt = progress, os.clock()
			end
		end
		if progress and progress >= 200 then
			Dandy.endMachine(session)
			if os.clock() >= badgeAt then
				badgeAt = os.clock() + 10
				if verify(current, true) then
					return true, "Dandy's World Hollow badge earned"
				end
			end
			status("200 event pumpkins earned", "Waiting for the game's badge award", 0.99)
		elseif lobby then
			if workspace:GetAttribute("RobloxHalloweenEventLive") == false then
				return false, "Dandy's World's Hollow event is closed"
			end
			status(
				"Dandy's World",
				progress and string.format("%d / 200 event pumpkins | Joining a Hollow gate", progress)
					or "Loading saved event progress",
				(progress or 0) / 200
			)
			Dandy.queue(session, generation)
			if not pause(2, generation) then
				break
			end
		else
			local floor, live = Dandy.round(session)
			if workspace:FindFirstChild("CurrentRoom") ~= session.room then
				Dandy.watch(session, workspace:FindFirstChild("CurrentRoom"))
			end
			if floor ~= lastFloor then
				Dandy.endMachine(session)
				lastFloor, session.progressAt = floor, os.clock()
				session.delayed = setmetatable({}, { __mode = "k" })
			end
			status(
				"Dandy's World",
				string.format(
					"Floor %d | %s\n%s",
					floor or 0,
					progress and string.format("%d / 200 event pumpkins", progress)
						or "Waiting for saved event progress",
					"Collecting the nearest safe pumpkins"
				),
				(progress or 0) / 200
			)
			if Dandy.value(session.info, "Voting") == true then
				Dandy.select(session, generation)
			elseif not Dandy.life(session, generation, true) then
				Dandy.endMachine(session)
				local model, _, humanoid = character()
				local started = Dandy.value(session.info, "GameStarted") == true
				if started and (not model or humanoid.Health <= 0) and not session.returned then
					session.returned = true
					prepareTravel(current.place, true)
					fire(getPath(Storage, "Events", "Teleport"))
				end
			elseif not live then
				Dandy.elevator(session, generation)
			elseif session.room then
				local _, root = character()
				local safe, clearance = Dandy.safe(session, root.Position, root.Position)
				if not safe or os.clock() < (session.retreatUntil or 0) and clearance < 8 then
					Dandy.retreat(session, generation)
				elseif Dandy.decoding() then
					status("Dandy's World", "Finishing this machine first", (progress or 0) / 200)
				else
					local target, role, object, known = Dandy.pick(session)
					if role == "treat" then
						Dandy.treat(session, generation, target)
					elseif target then
						Dandy.use(session, target, role, object, generation)
					else
						status(
							"Dandy's World",
							known > 0 and string.format("%d pumpkins found, looking for a clear way in", known)
								or "No pumpkins left nearby. Waiting for the next floor's pickups.",
							(progress or 0) / 200
						)
					end
				end
			end
		end
		if progress == nil and os.clock() - unknownAt > 90 then
			return false, "Pumpkin progress hasn't loaded. Make sure you joined through a Hollow gate."
		end
		if not pause(os.clock() < (session.retreatUntil or 0) and 0.02 or 0.08, generation) then
			break
		end
	end
	return false, active(generation) and "The Dandy's World run reached its time limit" or "Stopped"
end

local Aooni = {}

function Aooni.location()
	if
		Storage:GetAttribute("inGame") == true
		or Storage:GetAttribute("inSearchGame") ~= nil
		or Storage:GetAttribute("sequenceStep") ~= nil
		or getPath(Storage, "InGame", "Instances")
	then
		return "gameplay"
	end
	for _, entry in ipairs({ { "InGame", "gameplay" }, { "Lobby", "lobby" } }) do
		local folder = getPath(Storage, "PlaceIds", entry[1])
		for _, place in ipairs(folder and folder:GetChildren() or {}) do
			if place:IsA("ValueBase") and place.Value == game.PlaceId then
				return entry[2]
			end
		end
	end
	if game.PlaceId == current.gameplayPlace or Logic.contains(current.alternatePlaces, game.PlaceId) then
		return "gameplay"
	end
	if game.PlaceId == current.place then
		return "lobby"
	end
	return nil
end

function Aooni.arrival()
	return resumePlace ~= nil and resumePlace == current.gameplayPlace and Aooni.location() == "gameplay"
end

function Aooni.progress()
	local count = App.player:GetAttribute("HalloweenPumpkins")
	local goal = Storage:GetAttribute("HalloweenPumpkinGoal")
	if type(goal) ~= "number" or goal < 1 or goal % 1 ~= 0 or goal == math.huge then
		goal = 50
	end
	if type(count) ~= "number" or count < 0 or count % 1 ~= 0 or count == math.huge then
		count = nil
	end
	return count, goal, App.player:GetAttribute("HalloweenBadgeOwned") == true
end

function Aooni.life(generation, model, step)
	local now, root, humanoid = character()
	if not active(generation) or not now or model and model ~= now then
		return false
	end
	for _, key in ipairs({ "inLoading", "inCutScene", "inSpectate", "inHide", "isBind", "isAooni" }) do
		if App.player:GetAttribute(key) == true then
			return false
		end
	end
	for _, key in ipairs({
		"inLoading",
		"GameEnded",
		"InDeathBlackout",
		"InDeathScene",
		"CutsceneCamera",
		"InPuzzleFocus",
	}) do
		if Storage:GetAttribute(key) == true then
			return false
		end
	end
	return not root.Anchored
		and not humanoid.Sit
		and not humanoid.PlatformStand
		and App.player:GetAttribute("isMoveable") ~= false
		and Storage:GetAttribute("HalloweenPumpkinLive") == true
		and Storage:GetAttribute("inSearchGame") == true
		and Storage:GetAttribute("sequenceState") == "SearchGame"
		and (step == nil or Storage:GetAttribute("sequenceStep") == step)
end

function Aooni.pumpkin(session, prompt)
	if not prompt:IsA("ProximityPrompt") or not prompt:IsDescendantOf(workspace) or not prompt.Enabled then
		return false
	end
	local action = tostring(prompt.ActionText):lower()
	for _, word in ipairs({ "buy", "purchase", "robux", "jumpscare", "shop" }) do
		if action:find(word, 1, true) then
			return false
		end
	end
	if (action .. " " .. tostring(prompt.ObjectText):lower()):find("pumpkin", 1, true) then
		return true
	end
	local object = prompt.Parent
	for _ = 1, 4 do
		if not object or object == workspace then
			break
		end
		if object.Name:lower():find("pumpkin", 1, true) then
			return true
		end
		object = object.Parent
	end
	object = prompt.Parent
	for _ = 1, 2 do
		if not object or object == workspace then
			break
		end
		for _, part in ipairs(object:GetChildren()) do
			if (part:IsA("MeshPart") or part:IsA("SpecialMesh")) and session.meshes[part.MeshId] then
				return true
			end
			if part:IsA("BasePart") then
				local mesh = part:FindFirstChildOfClass("SpecialMesh")
				if mesh and session.meshes[mesh.MeshId] then
					return true
				end
			end
		end
		object = object.Parent
	end
	return false
end

function Aooni.watch(session, generation)
	session.prompts, session.scan = {}, workspace:GetChildren()
	session.delayed = setmetatable({}, { __mode = "k" })
	session.meshes = {}
	local icon = getPath(Storage, "Halloween", "PumpkinIcon")
	if icon then
		for _, part in ipairs(icon:GetDescendants()) do
			if (part:IsA("MeshPart") or part:IsA("SpecialMesh")) and part.MeshId ~= "" then
				session.meshes[part.MeshId] = true
			end
		end
	end
	local function added(object)
		if active(generation) and object:IsA("ProximityPrompt") and object:IsDescendantOf(workspace) then
			session.prompts[object] = true
		end
	end
	for _, tag in ipairs({ "PlayerPP", "SearchGameAozeni" }) do
		for _, prompt in ipairs(Collection:GetTagged(tag)) do
			added(prompt)
		end
		table.insert(session.connections, Collection:GetInstanceAddedSignal(tag):Connect(added))
	end
	table.insert(session.connections, workspace.DescendantAdded:Connect(added))
	local ok, prompts = pcall(game.GetService, game, "ProximityPromptService")
	if ok then
		table.insert(session.connections, prompts.PromptShown:Connect(added))
	end
end

function Aooni.scan(session)
	local untilAt = os.clock() + 0.0015
	for _ = 1, 256 do
		local object = table.remove(session.scan)
		if not object then
			break
		end
		if object:IsDescendantOf(workspace) then
			if object:IsA("ProximityPrompt") then
				session.prompts[object] = true
			elseif
				object:IsA("Model")
				or object:IsA("Folder")
				or object:IsA("BasePart")
				or object:IsA("Attachment")
			then
				for _, child in ipairs(object:GetChildren()) do
					table.insert(session.scan, child)
				end
			end
		end
		if os.clock() >= untilAt then
			break
		end
	end
end

function Aooni.pick(session)
	local _, root = character()
	if not root then
		return nil
	end
	local chosen, nearest
	for prompt in pairs(session.prompts) do
		if not prompt:IsDescendantOf(workspace) then
			session.prompts[prompt] = nil
		elseif (session.delayed[prompt] or 0) <= os.clock() and Aooni.pumpkin(session, prompt) then
			local point = EventInput.point(prompt.Parent)
			if point then
				local length = (point - root.Position).Magnitude
				if not nearest or length < nearest then
					chosen, nearest = prompt, length
				end
			end
		end
	end
	return chosen
end

function Aooni.collect(session, prompt, generation)
	local model = character()
	local step = Storage:GetAttribute("sequenceStep")
	local point = EventInput.point(prompt.Parent)
	local before = Aooni.progress()
	local function allowed()
		return Aooni.life(generation, model, step) and Aooni.pumpkin(session, prompt)
	end
	if not point or before == nil or not allowed() then
		return false
	end
	session.delayed[prompt] = os.clock() + 8
	if not approach(point, generation, prompt.Parent, false, allowed) or not allowed() then
		return false
	end
	EventInput.hold(session, prompt, generation, allowed, {
		accepted = function()
			local count = Aooni.progress()
			return count and count > before
		end,
	})
	waitUntil(function()
		local count = Aooni.progress()
		return not allowed() or count and count > before
	end, 3, generation)
	local count = Aooni.progress()
	if count and count > before then
		session.idleAt = os.clock()
		return true
	end
	return false
end

function Aooni.listen(session, packets, name, generation, callback)
	local packet = packets[name]
	if type(packet) ~= "table" or type(packet.listen) ~= "function" then
		return false
	end
	local ok, release = pcall(packet.listen, function(value)
		if active(generation) then
			callback(value)
		end
	end)
	if ok and type(release) == "function" then
		table.insert(session.listeners, release)
	end
	return ok and type(release) == "function"
end

function Aooni.network(session, generation)
	if session.packets then
		return true
	end
	local net = module(getPath(Storage, "Common", "Net", "ModeSelectNet"), generation)
	local packets = net and net.packets
	if
		not active(generation)
		or type(packets) ~= "table"
		or not packets.CreateRoom
		or type(packets.CreateRoom.send) ~= "function"
	then
		return false
	end
	for _, name in ipairs({ "Enter", "Leave", "Tick", "CreateResult" }) do
		if type(packets[name]) ~= "table" or type(packets[name].listen) ~= "function" then
			return false
		end
	end
	session.packets = packets
	local entered = Aooni.listen(session, packets, "Enter", generation, function(room)
		if type(room) == "table" and type(room.MinSlots) == "number" and type(room.MaxSlots) == "number" then
			session.room = room
			session.submitted, session.departing, session.rejected = false, false, nil
			session.joined = session.attempting == true
		end
	end)
	local left = Aooni.listen(session, packets, "Leave", generation, function()
		session.room, session.attempting, session.joined = nil, false, false
		session.retryAt = os.clock() + 4
	end)
	local ticking = Aooni.listen(session, packets, "Tick", generation, function(tick)
		if session.room and type(tick) == "table" then
			session.room.IsCreator = tick.IsCreator
		end
	end)
	local resultReady = Aooni.listen(session, packets, "CreateResult", generation, function(result)
		if type(result) == "table" then
			if result.Ok and result.Phase == "Departing" then
				session.departing = true
				session.departAt = os.clock()
			elseif result.Ok == false then
				session.submitted = false
				session.rejected = tostring(result.Reason or "Room request rejected")
				session.failures = (session.failures or 0) + 1
				session.retryAt = os.clock() + 6
			end
		end
	end)
	if not entered or not left or not ticking or not resultReady then
		for _, release in ipairs(session.listeners) do
			pcall(release)
		end
		session.listeners, session.packets = {}, nil
		return false
	end
	return true
end

function Aooni.queue(session, generation)
	if not Aooni.network(session, generation) then
		return "Waiting for the classroom controls to load"
	end
	if not active(generation) then
		return "Stopped"
	end
	if session.departing then
		return "Joining the school"
	end
	if os.clock() < (session.retryAt or 0) then
		return session.rejected or "Waiting for a classroom"
	end
	if session.room then
		if session.room.IsCreator ~= true then
			return "Waiting for the room owner to start"
		end
		if not session.submitted then
			local slots = session.room.MinSlots
			if slots < 1 or slots > session.room.MaxSlots or slots > 255 or slots % 1 ~= 0 then
				return "The classroom settings haven't loaded"
			end
			session.submitted = true
			session.sentAt = os.clock()
			if not session.queued then
				prepareTravel(current.gameplayPlace, true)
				session.queued = true
			end
			if not active(generation) then
				return "Stopped"
			end
			local ok = pcall(
				session.packets.CreateRoom.send,
				{ ModeId = "Standard", Difficulty = "Easy", AcceptPlayers = slots }
			)
			if not ok then
				session.rejected = "Couldn't send the classroom request. Stop and try again."
			end
		end
		return session.rejected or "Starting School on Easy"
	end
	if session.attempting and os.clock() - session.enteredAt < 12 then
		return "Waiting for the classroom to open"
	end
	local model, root, humanoid = character()
	if not model or root.Anchored or humanoid.Sit or App.player:GetAttribute("isReserve") then
		return "Waiting for your character or current room"
	end
	local chosen, nearest
	for _, room in ipairs(Collection:GetTagged("SelectModeTeleporter")) do
		local seats = room:FindFirstChild("Seats")
		for _, seat in ipairs(seats and seats:GetChildren() or {}) do
			if seat:IsA("Seat") and not seat.Occupant and room:IsDescendantOf(workspace) then
				local distance = (seat.Position - root.Position).Magnitude
				if not nearest or distance < nearest then
					chosen, nearest = seat, distance
				end
			end
		end
	end
	if chosen then
		session.attempting, session.enteredAt = true, os.clock()
		if not session.queued then
			prepareTravel(current.gameplayPlace, true)
			session.queued = true
		end
		approach(chosen.Position, generation, chosen, false, function()
			return active(generation)
				and App.player.Character == model
				and not root.Anchored
				and chosen:IsDescendantOf(workspace)
		end)
	end
	return "Joining an available classroom"
end

local function runAooni(generation)
	if verify(current, true) then
		return true, "The AOONI Nightmare badge is already earned"
	end
	if not active(generation) then
		return false, "Stopped"
	end
	local session = { connections = {}, listeners = {}, idleAt = os.clock() }
	table.insert(App.cleanups, function()
		EventInput.release(session)
		if session.joined and not session.departing and session.packets and session.packets.Cancel then
			pcall(session.packets.Cancel.send, nil)
		end
		for _, release in ipairs(session.listeners) do
			pcall(release)
		end
		for _, connection in ipairs(session.connections) do
			connection:Disconnect()
		end
		session.scan, session.prompts = {}, {}
	end)
	table.insert(
		session.connections,
		Teleport.TeleportInitFailed:Connect(function(player)
			if active(generation) and player == App.player then
				session.travelFailed = true
			end
		end)
	)
	Aooni.watch(session, generation)
	local expires, missingAt, badgeAt, goalAt, lastStep, lastCount = os.clock() + 10800, os.clock(), 0, nil, nil, nil
	while active(generation) and os.clock() < expires do
		if session.travelFailed then
			return false, "The server transfer failed. Check the game's queue and try again."
		end
		local count, goal, owned = Aooni.progress()
		local location = Aooni.location()
		local message
		if count ~= nil then
			missingAt = os.clock()
			if count ~= lastCount then
				lastCount, session.idleAt = count, os.clock()
			end
		end
		if owned or count and count >= goal then
			goalAt = goalAt or os.clock()
			if os.clock() >= badgeAt then
				badgeAt = os.clock() + 10
				if verify(current, true) then
					return true, "AOONI Nightmare Hollow badge earned"
				end
			end
			if os.clock() - goalAt > 75 then
				return false,
					"The pumpkin goal is saved, but the badge isn't confirmed yet. Try Check badges again shortly."
			end
			message = "Got enough pumpkins, waiting for the badge"
		elseif Storage:GetAttribute("HalloweenPumpkinLive") == false then
			return false, "The AOONI pumpkin event is closed"
		elseif location == "lobby" then
			message = Aooni.queue(session, generation)
			if not session.packets and os.clock() - session.idleAt > 90 then
				return false, "The classroom controls haven't loaded. Try the game's room menu, then Start again."
			end
			if (session.failures or 0) >= 3 then
				return false, session.rejected
			end
			if session.submitted and os.clock() - session.sentAt > 35 and not session.departing then
				return false, "The classroom hasn't replied. Stop and check the game's room menu."
			end
			if session.departing and os.clock() - session.departAt > 45 then
				return false, "The school transfer didn't finish. Check the game's room menu."
			end
		elseif not location then
			message = "Waiting for the school or lobby to finish loading"
		elseif count == nil then
			message = "Loading your saved pumpkin count"
		elseif App.player:GetAttribute("inSpectate") == true or Storage:GetAttribute("GameEnded") == true then
			EventInput.release(session)
			message = "Returning to the lobby for another round"
			if not session.returnAt then
				local remote = getPath(Storage, "InGame", "Instances", "RemoteEvent", "ReturnToLobbyAction")
				if remote then
					prepareTravel(current.place, true)
					session.returnAt = os.clock()
					if active(generation) then
						fire(remote)
					end
				end
			elseif os.clock() - session.returnAt > 30 then
				return false, "The lobby transfer didn't finish. Use the game's Return to Lobby button."
			end
		else
			Aooni.scan(session)
			local step = Storage:GetAttribute("sequenceStep")
			if step ~= lastStep then
				lastStep, session.idleAt = step, os.clock()
				session.delayed = setmetatable({}, { __mode = "k" })
			end
			if Aooni.life(generation) then
				local prompt = Aooni.pick(session)
				message = "Looking for pumpkin prompts"
				if prompt then
					status("AOONI Nightmare", string.format("%d / %d pumpkins | Collecting", count, goal), count / goal)
					Aooni.collect(session, prompt, generation)
				elseif #session.scan == 0 and os.clock() - session.idleAt > 90 then
					return false,
						"No collectible pumpkin prompts found. Move near an event pumpkin and press Start again."
				end
			else
				EventInput.release(session)
				session.idleAt = os.clock()
				message = Storage:GetAttribute("inSearchGame") == true and "Waiting until you're free to move"
					or "Waiting for the next school search. Play the minigames yourself."
			end
		end
		status(
			"AOONI Nightmare",
			count and string.format("%d / %d pumpkins | %s", count, goal, message) or message,
			(count or 0) / goal
		)
		if count == nil and os.clock() - missingAt > 90 then
			return false, "Your saved pumpkin count hasn't loaded. Check that the Halloween event is available."
		end
		if not pause(0.3, generation) then
			break
		end
	end
	return false, active(generation) and "The AOONI run reached its time limit" or "Stopped"
end

local Doors = {}

function Doors.settings()
	App.doorsSettings = App.doorsSettings
		or {
			route = true,
			esp = false,
			alerts = false,
			dial = false,
			eyes = true,
			seek = true,
			bright = true,
			candy = true,
		}
	return App.doorsSettings
end

function Doors.restoreBrightness(state)
	state.lightRestoring = true
	if state.lightAdded then
		pcall(state.lightAdded.Disconnect, state.lightAdded)
		state.lightAdded = nil
	end
	for object, properties in pairs(state.lightSaved or {}) do
		for key, saved in pairs(properties) do
			if saved.connection then
				pcall(saved.connection.Disconnect, saved.connection)
			end
			pcall(function()
				if object[key] == saved.applied then
					object[key] = saved.previous
				end
			end)
		end
	end
	state.lightSaved, state.lightUi = nil, nil
	state.lightPlayerGui = nil
	state.lightRestoring = nil
end

function Doors.lightProperty(state, object, key, value, pin)
	state.lightSaved = state.lightSaved or {}
	local saved = state.lightSaved[object]
	if not saved then
		saved = {}
		state.lightSaved[object] = saved
	end
	local ok, currentValue = pcall(function()
		return object[key]
	end)
	if not ok or currentValue == nil then
		return
	end
	local record = saved[key]
	if not record then
		record = { previous = currentValue, applied = value }
		saved[key] = record
	elseif currentValue ~= record.applied then
		record.previous = currentValue
	end
	if currentValue ~= value then
		pcall(function()
			object[key] = value
		end)
	end
	if pin and not record.connection and type(object.GetPropertyChangedSignal) == "function" then
		local connected, connection = pcall(function()
			return object:GetPropertyChangedSignal(key):Connect(function()
				if record.writing or state.lightRestoring or not App.alive or not Doors.settings().bright then
					return
				end
				pcall(function()
					if object[key] ~= value then
						record.previous = object[key]
						record.writing = true
						object[key] = value
						record.writing = false
					end
				end)
			end)
		end)
		if connected then
			record.connection = connection
		end
	end
end

function Doors.darkOverlay(state, object)
	if state.lightRestoring or not object:IsA("GuiObject") then
		return
	end
	local root = object
	while root and not root:IsA("ScreenGui") do
		root = root.Parent
	end
	if not root then
		return
	end
	local name = object.Name:lower():gsub("[%s_]", "")
	local knownRoot = root.Name == "MainUI"
		or root.Name == "VaultSplash"
		or root.Name == "VaultImpact"
		or root.Name == "VaultTransition"
		or root.Name == "VaultTransitionWarm"
		or root.Name == "VaultCover"
		or root.Name == "EstateCard"
	local dark = name == "black"
		or name == "vignette"
		or name == "weirdvignette"
		or name == "weirdvignettelive"
		or name == "darkness"
		or name == "darkoverlay"
		or name == "darken"
		or name == "blackframe"
		or name == "blackscreen"
		or root.Name == "VaultCover" and name == "frame"
	if not knownRoot or not dark then
		return
	end
	state.lightUi[object] = true
	if object:IsA("ImageLabel") or root.Name == "VaultCover" and name == "frame" then
		Doors.lightProperty(state, object, "Visible", false, true)
	else
		Doors.lightProperty(state, object, "BackgroundTransparency", 1)
	end
end

function Doors.brightness(state)
	if not Doors.settings().bright then
		if state.lightSaved then
			Doors.restoreBrightness(state)
		end
		return
	end
	if os.clock() < (state.lightAt or 0) then
		return
	end
	state.lightAt = os.clock() + 0.35
	local ok, lighting = pcall(game.GetService, game, "Lighting")
	if not ok or not lighting then
		return
	end
	state.lightUi = state.lightUi or setmetatable({}, { __mode = "k" })
	state.lightValues = state.lightValues
		or {
			Brightness = 3,
			ExposureCompensation = 0.85,
			ClockTime = 14,
			Ambient = Color3.fromRGB(215, 215, 215),
			OutdoorAmbient = Color3.fromRGB(190, 190, 190),
			GlobalShadows = false,
			FogStart = 0,
			FogEnd = 100000,
		}
	for key, value in pairs(state.lightValues) do
		Doors.lightProperty(state, lighting, key, value)
	end
	for _, parent in ipairs({ lighting, workspace.CurrentCamera }) do
		for _, effect in ipairs(parent:GetChildren()) do
			if effect:IsA("ColorCorrectionEffect") or effect:IsA("BlurEffect") or effect:IsA("DepthOfFieldEffect") then
				Doors.lightProperty(state, effect, "Enabled", false)
			elseif effect:IsA("Atmosphere") then
				for _, property in ipairs({ "Density", "Haze", "Glare" }) do
					Doors.lightProperty(state, effect, property, 0)
				end
			end
		end
	end
	local playerGui = App.player:FindFirstChild("PlayerGui")
	if playerGui and playerGui ~= state.lightPlayerGui then
		if state.lightAdded then
			pcall(state.lightAdded.Disconnect, state.lightAdded)
		end
		state.lightPlayerGui = playerGui
		if playerGui.DescendantAdded then
			state.lightAdded = playerGui.DescendantAdded:Connect(function(object)
				if App.alive and App.doorsState == state and Doors.settings().bright then
					pcall(Doors.darkOverlay, state, object)
				end
			end)
		end
		for _, object in ipairs(playerGui:GetDescendants()) do
			Doors.darkOverlay(state, object)
		end
	end
	for object in pairs(state.lightUi) do
		if object:IsDescendantOf(playerGui or App.player) then
			Doors.darkOverlay(state, object)
		else
			state.lightUi[object] = nil
		end
	end
end

function Doors.candyTool(tool)
	if not tool:IsA("Tool") or tool.Name == "CandyBag" then
		return false
	end
	local id = tool:GetAttribute("CandyID") or tool:GetAttribute("Tool_CandyID")
	if type(id) ~= "string" or id == "" then
		id = tool:GetAttribute("Tool_CandyID")
	end
	return tool.Name == "Candy" or type(id) == "string" and id ~= ""
end

function Doors.releaseCandy(state)
	local eating = state.eating
	state.eating = nil
	if not eating then
		return
	end
	pcall(eating.tool.Deactivate, eating.tool)
	if eating.equipped and eating.tool.Parent == App.player.Character then
		local backpack = App.player:FindFirstChild("Backpack")
		if backpack then
			pcall(function()
				eating.tool.Parent = backpack
			end)
		end
	end
end

function Doors.eatCandy(state)
	local model, root, humanoid = character()
	local blocked = not Doors.settings().candy
		or state.candySuspended
		or not model
		or App.traveling
		or App.player:GetAttribute("Alive") == false
		or Doors.cutscene()
		or Doors.value("RunHasBeenEnded") == true
		or Doors.value("InGame") ~= true
		or state.terminal
		or state.dialFrame
		or Doors.dialFrame()
		or model:GetAttribute("InMinigame")
		or model:GetAttribute("Hiding")
		or Doors.hiding()
		or root.Anchored
		or humanoid.Sit
		or humanoid.PlatformStand
		or state.prompt
		or state.interacting
	if blocked then
		Doors.releaseCandy(state)
		return
	end
	local backpack = App.player:FindFirstChild("Backpack")
	local held = model:FindFirstChildOfClass("Tool")
	if held and not Doors.candyTool(held) then
		Doors.releaseCandy(state)
		return
	end
	local now = os.clock()
	local eating = state.eating
	if eating then
		if eating.tool.Parent ~= model then
			state.eating = nil
			state.candyAt = now + 0.5
			return
		end
		if now < eating.nextAt then
			return
		end
		if eating.attempts >= 3 then
			state.candyRetry = state.candyRetry or setmetatable({}, { __mode = "k" })
			state.candyRetry[eating.tool] = now + 8
			Doors.releaseCandy(state)
			return
		end
	elseif now >= (state.candyAt or 0) then
		local tool = held
		if not tool then
			for _, candidate in ipairs(backpack and backpack:GetChildren() or {}) do
				if Doors.candyTool(candidate) and now >= (state.candyRetry and state.candyRetry[candidate] or 0) then
					tool = candidate
					break
				end
			end
		end
		if
			not tool
			or not Doors.candyTool(tool)
			or tool.Enabled == false
			or now < (state.candyRetry and state.candyRetry[tool] or 0)
		then
			return
		end
		eating = { tool = tool, equipped = tool.Parent ~= model, attempts = 0 }
		state.eating = eating
		if eating.equipped then
			local equipped = pcall(humanoid.EquipTool, humanoid, tool)
			if not equipped or tool.Parent ~= model then
				state.eating = nil
				state.candyAt = now + 1
				return
			end
			eating.nextAt = now + 0.25
			return
		end
	else
		return
	end
	if eating.tool.Enabled == false then
		eating.nextAt = now + 0.25
		return
	end
	local ok = pcall(eating.tool.Activate, eating.tool)
	pcall(eating.tool.Deactivate, eating.tool)
	eating.attempts += 1
	eating.nextAt = now + (ok and 2 or 3)
end

function Doors.value(name)
	local object = getPath(Storage, "GameData", name)
	if object and object:IsA("ValueBase") then
		return object.Value
	end
	return nil
end

function Doors.waitingForHost()
	if Doors.value("WaitingForHost") ~= true or Doors.value("HostStart") == true then
		return false
	end
	if Doors.value("Floor") == "Halloween26" and Doors.value("InGame") == true then
		local number = tonumber(App.player:GetAttribute("CurrentRoom"))
		if number == nil and App.doorsState and App.doorsState.rooms then
			local _, detected = Doors.room(App.doorsState)
			number = detected
		end
		if number and number >= 1 and number < math.huge then
			return false
		end
		if number == 0 and Doors.value("OpenedFirstDoor") == true then
			return false
		end
		for prompt in pairs(App.doorsState and App.doorsState.prompts or {}) do
			if prompt:IsDescendantOf(workspace) and Doors.promptEnabled(prompt) then
				local kind = Doors.classify(prompt)
				if kind == "gate" or kind == "entrance" then
					return false
				end
			end
		end
	end
	return true
end

function Doors.cutscene()
	local model, root, humanoid = character()
	if
		Doors.value("InCutscene") ~= true
		and App.player:GetAttribute("InCutscene") ~= true
		and (not model or model:GetAttribute("InCutscene") ~= true)
	then
		return false
	end
	if not model or model:GetAttribute("InCutsceneFreeMotor") ~= true then
		return true
	end
	local camera = workspace.CurrentCamera
	return camera ~= nil and camera.CameraType == Enum.CameraType.Scriptable
		or root ~= nil and root.Anchored
		or humanoid ~= nil
			and (humanoid.Sit or humanoid.PlatformStand or type(humanoid.WalkSpeed) == "number" and humanoid.WalkSpeed <= 0)
end

function Doors.roomReady()
	if Doors.value("FinishedLoadingRoom") ~= false then
		return true
	end
	local state = App.doorsState or { rooms = workspace:FindFirstChild("CurrentRooms") }
	local room = Doors.room(state)
	local model, root = character()
	if
		not room
		or not root
		or room:GetAttribute("LoadModulesReady") ~= true
		or not (room:GetAttribute("_FromHalloween26") == true or room:GetAttribute("RoomStyle") == "Halloween26")
	then
		return false
	end
	local entrance = room:FindFirstChild("RoomEntrance")
	if not entrance or not entrance:IsA("BasePart") then
		return false
	end
	local checked = state.loadCheck
	if
		checked
		and checked.room == room
		and checked.model == model
		and os.clock() < checked.untilAt
		and (checked.point - root.Position).Magnitude < 4
	then
		return checked.ready
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { model }
	params.RespectCanCollide = true
	local hit = workspace:Raycast(root.Position + Vector3.new(0, 1, 0), Vector3.new(0, -12, 0), params)
	local ready = hit ~= nil and hit.Instance ~= nil and hit.Instance:IsDescendantOf(room) and hit.Normal.Y > 0.5
	state.loadCheck = { room = room, model = model, point = root.Position, untilAt = os.clock() + 0.2, ready = ready }
	return ready
end

function Doors.blocker(generation, walking)
	local model, root, humanoid = character()
	if not active(generation) then
		return "Stopped"
	end
	if not model then
		return "Waiting for your character and humanoid"
	end
	if App.player:GetAttribute("Alive") == false then
		return "The game marks your player as dead or spectating"
	end
	if Doors.value("Floor") ~= "Halloween26" then
		return "Waiting for The Candy Vault floor"
	end
	if Doors.cutscene() then
		return "The game's cutscene is still active"
	end
	if Doors.value("RunHasBeenEnded") == true then
		return "The run has ended"
	end
	if Doors.value("InGame") ~= true then
		return "Waiting for GameData.InGame to become active"
	end
	if walking then
		if not Doors.settings().route then
			return "Auto route is off"
		elseif root.Anchored or humanoid.Sit or humanoid.PlatformStand then
			return "The game has locked your character's movement"
		elseif model:GetAttribute("InMinigame") then
			return "Finishing the current minigame"
		elseif Doors.hiding() then
			return "Currently in a hiding spot"
		elseif Doors.waitingForHost() then
			return "Waiting for the host's start signal"
		elseif not Doors.roomReady() then
			return "The current room is still loading"
		end
	end
	return nil
end

function Doors.life(generation, walking)
	return Doors.blocker(generation, walking) == nil
end

function Doors.promptEnabled(prompt)
	local server = prompt:GetAttribute("_ServerEnabled")
	return server ~= false and (prompt.Enabled or server == true)
end

function Doors.classify(prompt)
	if not prompt:IsA("ProximityPrompt") then
		return nil
	end
	local object = prompt.Parent
	local rooms = workspace:FindFirstChild("CurrentRooms")
	local door, doorPart
	for _ = 1, 12 do
		if not object or object == workspace then
			break
		end
		if
			(prompt.Name == "ManualOpenPrompt" or prompt.Name == "UnlockPrompt")
			and rooms
			and object:IsDescendantOf(rooms)
			and object.Parent ~= rooms
		then
			if object:IsA("Model") then
				door = door or object
			elseif object:IsA("BasePart") then
				doorPart = doorPart or object
			end
		end
		local pickup = object:GetAttribute("Pickup")
		if type(pickup) == "string" then
			if pickup == "Candy" or pickup == "CandyBag" then
				return "candy", object, "Candy"
			elseif pickup:sub(1, 3) == "Key" then
				return "key", object, pickup
			elseif pickup == "Crucifix" or pickup == "Flashlight" or pickup == "StarVial" then
				return "supply", object, pickup
			end
			return nil
		end
		if prompt.Name == "HidePrompt" and (object:IsA("Model") or object:IsA("BasePart")) then
			return "hide", object, "Hiding spot"
		elseif object:FindFirstChild("VaultRemote") and prompt.Name == "UnlockPrompt" then
			return "vault", object, "Vault dial"
		elseif object:FindFirstChild("TerminalRemote") then
			return "terminal", object, "Perk terminal"
		elseif object.Name == "EstateFrontDoor" and prompt.Name == "StartPrompt" then
			return "entrance", object, "Enter the Estate"
		elseif object.Name == "GardenGateButton" and prompt.Name == "ActivateEventPrompt" then
			return "gate", object, "Garden gate"
		elseif
			object.Name == "Door"
			and object.Parent
			and object.Parent.Parent == workspace:FindFirstChild("CurrentRooms")
			and (prompt.Name == "ManualOpenPrompt" or prompt.Name == "UnlockPrompt")
		then
			return "door", object, "Open next door"
		elseif
			prompt.Name == "ActivateEventPrompt" and (object.Name == "DrawerContainer" or object.Name == "ChestBox")
		then
			return "drawer", object, "Search for the door key"
		end
		object = object.Parent
	end
	if door or doorPart then
		return "door", door or doorPart, "Open passage"
	end
	return nil
end

function Doors.attach(state)
	local rooms = workspace:FindFirstChild("CurrentRooms")
	if state.rooms == rooms then
		return
	end
	if state.added then
		state.added:Disconnect()
	end
	state.rooms, state.scan, state.prompts, state.exits = rooms, rooms and { rooms } or {}, {}, {}
	state.target = nil
	if rooms then
		state.added = rooms.DescendantAdded:Connect(function(object)
			if object:IsA("ProximityPrompt") then
				state.prompts[object] = true
			elseif object.Name == "RoomExit" and object:IsA("BasePart") then
				state.exits[object] = true
			end
		end)
	end
end

function Doors.scan(state)
	Doors.attach(state)
	local room = Doors.room(state)
	if room and state.scanRoom ~= room then
		state.scanRoom = room
		table.insert(state.scan, room)
	end
	local finish = os.clock() + 0.0015
	for _ = 1, 120 do
		local object = table.remove(state.scan)
		if not object then
			break
		end
		if object == state.rooms or object:IsDescendantOf(state.rooms) then
			if object:IsA("ProximityPrompt") then
				state.prompts[object] = true
			elseif object.Name == "RoomExit" and object:IsA("BasePart") then
				state.exits[object] = true
			end
			for _, child in ipairs(object:GetChildren()) do
				table.insert(state.scan, child)
			end
		end
		if os.clock() >= finish then
			break
		end
	end
end

function Doors.room(state)
	if not state.rooms then
		return nil
	end
	local number = tonumber(App.player:GetAttribute("CurrentRoom"))
	local room = number and state.rooms:FindFirstChild(tostring(number))
	if room then
		return room, number
	end
	local _, root = character()
	local nearest, best = nil, math.huge
	for _, candidate in ipairs(state.rooms:GetChildren()) do
		local entrance = candidate:FindFirstChild("RoomEntrance")
		local index = tonumber(candidate.Name)
		if root and index and entrance and entrance:IsA("BasePart") then
			local distance = (root.Position - entrance.Position).Magnitude
			if distance < best then
				nearest, best, number = candidate, distance, index
			end
		end
	end
	return nearest, number
end

function Doors.entityKind(object)
	local name = object.Name:lower()
	if name == "eyes" or name == "eyesmoving" or name == "lookman" then
		return "gaze"
	end
	if
		name:find("seek", 1, true)
		or name == "creak"
		or name == "creakmoving"
		or name == "creakchase"
		or name == "scarycreak"
		or Doors.value("ChaseInSession") == true
			and name ~= "rushmoving"
			and name ~= "ambushmoving"
			and name ~= "a60"
			and name ~= "a120"
	then
		return "chase"
	end
	return "hide"
end

function Doors.entities()
	local state = App.doorsState
	if state and os.clock() < (state.entityAt or 0) then
		for _, entity in ipairs(state.entities or {}) do
			if entity.object:IsDescendantOf(workspace) then
				entity.point = positionOf(entity.object) or entity.point
				entity.kind = Doors.entityKind(entity.object)
			end
		end
		return state.entities or {}
	end
	local entities, seen = {}, {}
	local function add(object)
		if not seen[object] and (object:IsA("Model") or object:IsA("BasePart")) then
			local point = positionOf(object)
			if point then
				seen[object] = true
				table.insert(
					entities,
					{ object = object, point = point, name = object.Name, kind = Doors.entityKind(object) }
				)
			end
		end
	end
	local live = workspace:FindFirstChild("LiveEntities")
	if live then
		for _, object in ipairs(live:GetChildren()) do
			add(object)
		end
	end
	for _, name in ipairs({
		"RushMoving",
		"AmbushMoving",
		"A60",
		"A120",
		"SeekMoving",
		"Eyes",
		"EyesMoving",
		"Lookman",
		"Creak",
		"CreakMoving",
		"CreakChase",
	}) do
		local object = workspace:FindFirstChild(name)
		if object then
			add(object)
		end
	end
	if state then
		state.entities, state.entityAt = entities, os.clock() + 0.08
	end
	return entities
end

function Doors.threat(all)
	local _, root = character()
	local nearest, best = nil, math.huge
	if root then
		for _, entity in ipairs(Doors.entities()) do
			if entity.object:IsDescendantOf(workspace) and (all or entity.kind == "hide") then
				local distance = (root.Position - entity.point).Magnitude
				if distance < best then
					nearest, best = entity, distance
				end
			end
		end
	end
	return nearest, best
end

function Doors.chaseActive()
	if Doors.value("ChaseInSession") == true then
		return true
	end
	for _, entity in ipairs(Doors.entities()) do
		if entity.kind == "chase" and entity.object:IsDescendantOf(workspace) then
			return true
		end
	end
	return false
end

function Doors.releaseGaze(state)
	local look = state.gaze
	state.gaze = nil
	if look then
		pcall(function()
			if
				character() == look.character
				and workspace.CurrentCamera == look.camera
				and look.camera.CameraType == look.kind
				and look.camera.CFrame == look.aim
				and look.epoch == App.cameraEpoch
			then
				look.camera.CFrame = look.previous
			end
		end)
	end
end

function Doors.eyeAssist(state)
	if state.closed then
		return
	end
	if not App.alive or not Doors.settings().eyes or state.entitySuspended or state.unfocused then
		Doors.releaseGaze(state)
		return
	end
	local model = character()
	local camera = workspace.CurrentCamera
	if
		not model
		or App.player:GetAttribute("Alive") == false
		or Doors.value("InGame") ~= true
		or Doors.value("RunHasBeenEnded") == true
		or Doors.cutscene()
		or Doors.hiding()
		or model:GetAttribute("InMinigame")
		or App.cameraBusy
		or Input:GetFocusedTextBox()
		or not camera
		or camera.CameraType == Enum.CameraType.Scriptable
	then
		Doors.releaseGaze(state)
		return
	end
	local position = camera.CFrame.Position
	local gazes, dangerous = {}, false
	local params = state.gazeParams
	for _, entity in ipairs(Doors.entities()) do
		local pursuing = entity.kind == "chase" and entity.name:lower():find("creak", 1, true) ~= nil
		if (entity.kind ~= "gaze" and not pursuing) or not entity.object:IsDescendantOf(workspace) then
			continue
		end
		local delta = entity.point - position
		if delta.Magnitude <= 120 and delta.Magnitude > 0.1 then
			if not params then
				params = RaycastParams.new()
				params.FilterType = Enum.RaycastFilterType.Exclude
				state.gazeParams = params
			end
			if state.gazeCharacter ~= model then
				params.FilterDescendantsInstances = { model }
				state.gazeCharacter = model
			end
			local hit = workspace:Raycast(position, delta, params)
			if
				not hit
				or hit.Instance == entity.object
				or hit.Instance and hit.Instance:IsDescendantOf(entity.object)
			then
				local direction = delta * (1 / delta.Magnitude)
				table.insert(gazes, direction)
				local look = camera.CFrame.LookVector
				if look.X * direction.X + look.Y * direction.Y + look.Z * direction.Z > 0.05 then
					dangerous = true
				end
			end
		end
	end
	if not dangerous then
		if #gazes == 0 then
			Doors.releaseGaze(state)
		end
		return
	end
	local best, score
	for _, direction in ipairs({
		Vector3.new(0, -1, -0.01),
		Vector3.new(0, 1, 0.01),
		Vector3.new(1, 0, 0),
		Vector3.new(-1, 0, 0),
		Vector3.new(0, 0, 1),
		Vector3.new(0, 0, -1),
	}) do
		direction = direction * (1 / direction.Magnitude)
		local worst = -math.huge
		for _, gaze in ipairs(gazes) do
			worst = math.max(worst, direction.X * gaze.X + direction.Y * gaze.Y + direction.Z * gaze.Z)
		end
		if not score or worst < score then
			best, score = direction, worst
		end
	end
	if best and score < 0.05 then
		local owned = state.gaze
		if not owned or owned.camera ~= camera or owned.character ~= model or owned.epoch ~= App.cameraEpoch then
			Doors.releaseGaze(state)
			owned = {
				camera = camera,
				character = model,
				kind = camera.CameraType,
				previous = camera.CFrame,
				epoch = App.cameraEpoch,
			}
			state.gaze = owned
		end
		owned.aim = CFrame.lookAt(position, position + best)
		camera.CFrame = owned.aim
	end
end

function Doors.releaseWalk(state)
	local walk = state.walk
	state.walk = nil
	if walk then
		if walk.binding then
			pcall(function()
				RunService:UnbindFromRenderStep(walk.binding)
			end)
		end
		if walk.blocked then
			walk.blocked:Disconnect()
		end
		pcall(function()
			local _, root, humanoid = character()
			if root == walk.root and humanoid == walk.humanoid then
				if walk.driving then
					pcall(humanoid.Move, humanoid, Vector3.zero, false)
				end
				humanoid:MoveTo(root.Position)
			end
		end)
	end
end

function Doors.clearSegment(from, to)
	local segment = to - from
	local length = segment.X * segment.X + segment.Y * segment.Y + segment.Z * segment.Z
	for _, entity in ipairs(Doors.entities()) do
		if entity.kind == "gaze" or not entity.object:IsDescendantOf(workspace) then
			continue
		end
		local offset = entity.point - from
		local along = length > 0
				and math.clamp((offset.X * segment.X + offset.Y * segment.Y + offset.Z * segment.Z) / length, 0, 1)
			or 0
		local clearance = (from + segment * along - entity.point).Magnitude
		if clearance < math.min(12, math.max(0, offset.Magnitude - 0.5)) then
			return false
		end
	end
	return true
end

function Doors.walkTo(state, point, generation, allowed, tolerance, options)
	local model, root, humanoid = character()
	options = options or {}
	tolerance = tolerance or 3
	local function ready()
		local now = character()
		local _, distance = Doors.threat()
		return now == model
			and Doors.life(generation, true)
			and distance > (options.evading and 0.5 or 65)
			and (not allowed or allowed())
	end
	if not root or not ready() then
		return false, "Movement paused"
	end
	if (root.Position - point).Magnitude <= tolerance then
		return true
	end
	local function atWaypoint(position, radius)
		local delta = root.Position - position
		local height = math.max(5, root.Size.Y / 2 + humanoid.HipHeight + 1)
		return delta.X * delta.X + delta.Z * delta.Z <= radius * radius and math.abs(delta.Y) <= height
	end
	local targets = { point }
	if options.prompt then
		targets = {}
		local toward = Vector3.new(root.Position.X - point.X, 0, root.Position.Z - point.Z)
		if toward.Magnitude < 0.1 then
			toward = Vector3.new(0, 0, 1)
		end
		toward = toward * (1 / toward.Magnitude)
		local radius = math.max(1, math.min(5, tolerance * 0.7))
		local side = Vector3.new(-toward.Z, 0, toward.X)
		for _, offset in ipairs({ toward * radius, side * radius, side * -radius, toward * -radius }) do
			table.insert(targets, point + offset)
		end
		table.insert(targets, point)
	end
	local ok, route = call("DOORS walking route", function()
		local path = game:GetService("PathfindingService"):CreatePath({
			AgentRadius = 1.8,
			AgentHeight = 5,
			AgentCanJump = true,
			WaypointSpacing = 5,
		})
		for _, target in ipairs(targets) do
			if not ready() then
				return nil
			end
			path:ComputeAsync(root.Position, target)
			if path.Status == Enum.PathStatus.Success then
				local waypoints = path:GetWaypoints()
				if #waypoints > 0 then
					return { points = waypoints, path = path }
				end
			end
		end
		return nil
	end, 3, generation)
	if not ok or type(route) ~= "table" or not ready() then
		return false, "Rechecking walkable approaches"
	end
	local waypoints = route.points
	local walk = { root = root, humanoid = humanoid, index = 1 }
	state.walk = walk
	local bound = pcall(function()
		local binding = "HollowDoorsWalk"
		RunService:BindToRenderStep(binding, Enum.RenderPriority.Character.Value + 1, function()
			if state.walk ~= walk then
				return
			end
			local ok, canMove = pcall(ready)
			local direction = Vector3.zero
			if ok and canMove and not walk.replan and walk.point and not atWaypoint(walk.point, 1.5) then
				local offset = walk.point - root.Position
				local flat = Vector3.new(offset.X, 0, offset.Z)
				if flat.Magnitude > 0.1 then
					direction = flat * (1 / flat.Magnitude)
				end
			end
			walk.driving = true
			pcall(humanoid.Move, humanoid, direction, false)
		end)
		walk.binding = binding
	end)
	if not bound then
		walk.binding = nil
	end
	if route.path.Blocked then
		walk.blocked = route.path.Blocked:Connect(function(index)
			if index >= walk.index then
				walk.replan = true
			end
		end)
	end
	local deadline, stalledAt, previous = os.clock() + 8, os.clock(), root.Position
	local startPoint = root.Position
	local reached = false
	for index, waypoint in ipairs(waypoints) do
		walk.index = index
		if not ready() or walk.replan then
			break
		end
		if options.evading and not Doors.clearSegment(root.Position, waypoint.Position) then
			break
		end
		if (root.Position - point).Magnitude <= tolerance then
			reached = true
			break
		end
		if not atWaypoint(waypoint.Position, 2.5) then
			if waypoint.Action == Enum.PathWaypointAction.Jump then
				humanoid.Jump = true
			end
			walk.point = waypoint.Position
			humanoid:MoveTo(waypoint.Position)
			while ready() and not walk.replan and not atWaypoint(waypoint.Position, 1.5) do
				if os.clock() >= (walk.checkDoorAt or 0) then
					walk.checkDoorAt = os.clock() + 0.2
					if Doors.nearDoor(state, options.prompt, point) then
						Doors.releaseWalk(state)
						return false, "Opening the passage ahead", true
					end
				end
				if (root.Position - point).Magnitude <= tolerance then
					reached = true
					break
				end
				if options.evading and not Doors.clearSegment(root.Position, waypoint.Position) then
					walk.replan = true
					break
				end
				if (root.Position - previous).Magnitude > 0.5 then
					previous, stalledAt = root.Position, os.clock()
				end
				if os.clock() - stalledAt > 1.6 or os.clock() > deadline then
					Doors.releaseWalk(state)
					local progressed = (root.Position - startPoint).Magnitude > 8
					return false,
						progressed and "Continuing through the room" or "Replanning around the obstacle",
						progressed
				end
				if not pause(0.06, generation) then
					break
				end
			end
		end
	end
	reached = reached or ready() and (root.Position - point).Magnitude <= tolerance
	Doors.releaseWalk(state)
	return reached, if reached then nil else "Rechecking the route", (root.Position - startPoint).Magnitude > 8
end

function Doors.dialFrame()
	local main = getPath(App.player, "PlayerGui", "MainUI")
	for _, frame in ipairs(main and main:GetChildren() or {}) do
		local guide = frame:FindFirstChild("Guide")
		if
			frame:IsA("GuiObject")
			and frame.Visible
			and guide
			and guide:IsA("GuiObject")
			and guide.Visible
			and guide:FindFirstChild("Progress")
			and guide:FindFirstChild("Correct")
			and frame:FindFirstChild("Next")
			and frame:FindFirstChild("Previous")
		then
			return frame
		end
	end
	return nil
end

function Doors.dialDecision(progress, width)
	if
		type(width) ~= "number"
		or width ~= width
		or width <= 0
		or width >= 1 / 7
		or type(progress) ~= "number"
		or progress ~= progress
		or progress < 0
		or progress > 1
	then
		return "wait"
	end
	local target = 1 - 7 * width
	if progress > target + width then
		return "wait"
	end
	return progress < target - 0.18 * width and "turn" or "hold"
end

function Doors.releaseKey(state)
	if state.dialKey then
		pcall(state.dialKey.release)
		state.dialKey = nil
	end
end

function Doors.key(state, direction)
	if os.clock() < (state.inputRetryAt or 0) then
		return false
	end
	if state.dialKey and state.dialKey.direction == direction then
		return true
	end
	Doors.releaseKey(state)
	local frame = Doors.dialFrame()
	local touchButton = frame and frame:FindFirstChild(direction == 1 and "Next" or "Previous")
	local native = EventInput.guiPress(touchButton)
	if native then
		native.direction = direction
		state.dialKey, state.dialMessage, state.dialMotionAt = native, nil, os.clock()
		return true
	end
	local keyCode = direction == 1 and Enum.KeyCode.D or Enum.KeyCode.A
	local ok, manager = pcall(game.GetService, game, "VirtualInputManager")
	local key
	if ok then
		key = {
			direction = direction,
			release = function()
				manager:SendKeyEvent(false, keyCode, false, game)
			end,
		}
		if pcall(manager.SendKeyEvent, manager, true, keyCode, false, game) then
			state.dialKey = key
			state.dialMessage, state.dialMotionAt = nil, os.clock()
			return true
		end
		pcall(key.release)
	end
	if type(keypress) == "function" and type(keyrelease) == "function" then
		local code = direction == 1 and 0x44 or 0x41
		key = {
			direction = direction,
			release = function()
				keyrelease(code)
			end,
		}
		if pcall(keypress, code) then
			state.dialKey = key
			state.dialMessage, state.dialMotionAt = nil, os.clock()
			return true
		end
		pcall(key.release)
	end
	state.dialMessage = "Input isn't available here. Turn the dial manually."
	state.inputRetryAt = os.clock() + 5
	return false
end

function Doors.assist(state)
	local settings = Doors.settings()
	local frame = Doors.dialFrame()
	local enabled = settings.dial or App.running and settings.route
	if frame ~= state.dialFrame then
		Doors.releaseKey(state)
		state.dialFrame, state.dialStart, state.dialMessage = frame, os.clock(), nil
		state.dialSignature, state.dialChanges = nil, 0
		state.inputRetryAt, state.dialMotionAt, state.dialProgress = 0, os.clock(), nil
	end
	local focused = Input:GetFocusedTextBox()
	if
		not frame
		or not enabled
		or frame == state.suspendFrame
		or not Doors.life(nil, false)
		or focused
		or state.unfocused
	then
		Doors.releaseKey(state)
		return
	end
	if os.clock() - (state.dialStart or 0) > 75 or (state.dialChanges or 0) > 30 then
		Doors.releaseKey(state)
		state.dialMessage = "Dial assist stopped after repeated attempts. Finish this dial manually."
		return
	end
	local guide = frame:FindFirstChild("Guide")
	local progress, correct = guide:FindFirstChild("Progress"), guide:FindFirstChild("Correct")
	if not progress:IsA("GuiObject") or not correct:IsA("GuiObject") then
		Doors.releaseKey(state)
		return
	end
	local nextButton, previous = frame:FindFirstChild("Next"), frame:FindFirstChild("Previous")
	local direction = nextButton.Visible and not previous.Visible and 1
		or previous.Visible and not nextButton.Visible and -1
		or nil
	local signature = tostring(direction) .. ":" .. tostring(correct.Size.X.Scale)
	if signature ~= state.dialSignature then
		Doors.releaseKey(state)
		state.dialSignature, state.dialWait = signature, os.clock() + 0.35
		state.dialChanges += 1
	end
	if not direction or os.clock() < state.dialWait or correct.BackgroundTransparency > 0.8 then
		Doors.releaseKey(state)
		return
	end
	local moved = progress.Size.X.Scale
	if moved ~= state.dialProgress then
		state.dialProgress, state.dialMotionAt = moved, os.clock()
	elseif state.dialKey and os.clock() - state.dialMotionAt > 2 then
		Doors.releaseKey(state)
		state.dialMessage, state.inputRetryAt =
			"The dial isn't responding to input. Try turning it manually.", os.clock() + 5
	end
	if Doors.dialDecision(progress.Size.X.Scale, correct.Size.X.Scale) == "turn" then
		Doors.key(state, direction)
	else
		Doors.releaseKey(state)
	end
end

function Doors.targets(state)
	local room = Doors.room(state)
	local targets = {}
	for prompt in pairs(state.prompts) do
		if not state.rooms or not prompt:IsDescendantOf(state.rooms) then
			state.prompts[prompt] = nil
		elseif Doors.promptEnabled(prompt) then
			local kind, object, title = Doors.classify(prompt)
			local point = kind and EventInput.point(prompt.Parent)
			if point then
				local owner = object
				while owner and owner.Parent ~= state.rooms do
					owner = owner.Parent
				end
				table.insert(targets, {
					prompt = prompt,
					object = object,
					kind = kind,
					title = title,
					point = point,
					room = owner,
					current = room and prompt:IsDescendantOf(room),
				})
			end
		end
	end
	for exit in pairs(state.exits) do
		if not state.rooms or not exit:IsDescendantOf(state.rooms) then
			state.exits[exit] = nil
		else
			table.insert(targets, {
				object = exit,
				point = exit.Position,
				kind = "exit",
				title = "Next door",
				current = room and exit:IsDescendantOf(room),
			})
		end
	end
	return targets
end

function Doors.keyTool()
	local model = App.player.Character
	for _, container in ipairs({ model, App.player:FindFirstChild("Backpack") }) do
		if container then
			for _, tool in ipairs(container:GetChildren()) do
				local name = tool:GetAttribute("Pickup") or tool.Name
				if tool:IsA("Tool") and type(name) == "string" and name:sub(1, 3) == "Key" and name ~= "KeyJewelry" then
					return tool
				end
			end
		end
	end
	return nil
end

function Doors.pastEntrance(room, point)
	local _, root = character()
	local entrance, exit = room:FindFirstChild("RoomEntrance"), room:FindFirstChild("RoomExit")
	if not root or not entrance or not exit or not entrance:IsA("BasePart") or not exit:IsA("BasePart") then
		return false
	end
	local direction = Vector3.new(exit.Position.X - entrance.Position.X, 0, exit.Position.Z - entrance.Position.Z)
	if direction.Magnitude < 1 then
		return false
	end
	local offset = root.Position - point
	return (offset.X * direction.X + offset.Z * direction.Z) / direction.Magnitude > 10
end

function Doors.doorOpen(target)
	if target.object:GetAttribute("Opened") == true or target.object:GetAttribute("Open") == true then
		return true
	end
	local action = target.prompt and target.prompt.ActionText
	if type(action) == "string" and action:lower() == "close" then
		return true
	end
	local hinge = target.object:FindFirstChildOfClass("HingeConstraint")
	return hinge ~= nil and type(hinge.CurrentAngle) == "number" and math.abs(hinge.CurrentAngle) >= 35
end

function Doors.nearDoor(state, except, destination)
	local _, root = character()
	if not root then
		return nil
	end
	if not destination and Doors.chaseActive() then
		local room = Doors.room(state)
		local exit = room and room:FindFirstChild("RoomExit")
		destination = exit and exit:IsA("BasePart") and exit.Position or nil
	end
	local best, distance
	for _, target in ipairs(Doors.targets(state)) do
		if target.kind ~= "door" or not target.current or target.prompt == except or Doors.doorOpen(target) then
			continue
		end
		local prior = state.attempts[target.prompt]
		local length = (target.point - root.Position).Magnitude
		if
			length <= math.min(10, target.prompt.MaxActivationDistance * 0.95)
			and (not prior or os.clock() >= (prior.retryAt or 0))
			and (not destination or (target.point - destination).Magnitude <= (root.Position - destination).Magnitude + 2)
			and (not distance or length < distance)
		then
			best, distance = target, length
		end
	end
	return best
end

function Doors.blockingDoor(state, destination, except)
	local model, root = character()
	if not root or not destination then
		return nil
	end
	local delta = Vector3.new(destination.X - root.Position.X, 0, destination.Z - root.Position.Z)
	if delta.Magnitude < 1 then
		return nil
	end
	local params = RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, { model }
	params.RespectCanCollide = true
	local hit = workspace:Raycast(root.Position, delta, params)
	if not hit or not hit.Instance then
		return nil
	end
	for _, target in ipairs(Doors.targets(state)) do
		local prior = state.attempts[target.prompt]
		if
			target.current
			and target.kind == "door"
			and target.prompt ~= except
			and not Doors.doorOpen(target)
			and (not prior or os.clock() >= (prior.retryAt or 0))
			and (hit.Instance == target.object or hit.Instance:IsDescendantOf(target.object))
		then
			return target
		end
	end
	return nil
end

function Doors.attempt(state, target, success)
	local previous = state.attempts[target.prompt] or { count = 0 }
	if target.kind == "door" and success then
		state.blocked, state.blockCount = nil, 0
	end
	previous.count += 1
	previous.retryAt = os.clock() + (success and 2 or math.min(10, previous.count * 1.5))
	if target.kind == "door" and success and not Doors.doorOpen(target) then
		previous.retryAt = os.clock() + 0.15
	end
	if previous.count >= 3 then
		previous.retryAt = os.clock() + 8
		previous.count = 0
	end
	state.attempts[target.prompt] = previous
end

function Doors.interactNow(state, target, generation, allowed)
	local model, root = character()
	local prompt, object = target.prompt, target.object
	local room = Doors.room(state)
	local opened, activated = object:GetAttribute("Opened"), object:GetAttribute("Activated")
	local locked, action = object:GetAttribute("Locked"), prompt.ActionText
	local enabled = prompt.Enabled
	local minigame = model and model:GetAttribute("InMinigame")
	local host = Doors.value("HostStart")
	local function changed()
		return not object:IsDescendantOf(workspace)
			or not prompt:IsDescendantOf(workspace)
			or prompt:GetAttribute("_ServerEnabled") == false
			or prompt.Enabled ~= enabled
			or object:GetAttribute("Opened") ~= opened
			or object:GetAttribute("Activated") ~= activated
			or object:GetAttribute("Locked") ~= locked
			or prompt.ActionText ~= action
			or target.kind == "door" and Doors.doorOpen(target)
			or Doors.room(state) ~= room
			or model:GetAttribute("InMinigame") ~= minigame
			or Doors.value("HostStart") ~= host
	end
	local function ready()
		local now, currentRoot = character()
		return now == model
			and Doors.life(generation, true)
			and Doors.promptEnabled(prompt)
			and object:IsDescendantOf(workspace)
			and (currentRoot.Position - target.point).Magnitude <= prompt.MaxActivationDistance
			and select(2, Doors.threat()) > 65
			and (not allowed or allowed())
	end
	if not model or not root or not ready() then
		return false
	end
	if type(fireproximityprompt) == "function" then
		call(prompt, function()
			if ready() then
				fireproximityprompt(prompt, prompt.HoldDuration)
			end
		end, math.min(32, prompt.HoldDuration + 2), generation)
		waitUntil(function()
			return changed() or not ready()
		end, 0.7, generation)
		if not active(generation) then
			return false
		end
		if changed() then
			return true
		end
	end
	if ready() then
		local held = EventInput.hold(state, prompt, generation, ready, { accepted = changed })
		return active(generation) and (changed() or held)
	end
	return false
end

function Doors.interact(state, target, generation, allowed)
	state.interacting = true
	Doors.releaseCandy(state)
	local result = table.pack(pcall(Doors.interactNow, state, target, generation, allowed))
	state.interacting = nil
	if not result[1] then
		error(result[2], 0)
	end
	return table.unpack(result, 2, result.n)
end

function Doors.nextTarget(state)
	local room = Doors.room(state)
	if not room then
		return nil, "Waiting for the current room to load"
	end
	local _, root = character()
	if not root then
		return nil, "Waiting for your character"
	end
	local nearby = Doors.nearDoor(state)
	if nearby then
		return nearby
	end
	local currentExit = room:FindFirstChild("RoomExit")
	local passage = currentExit and currentExit:IsA("BasePart") and Doors.blockingDoor(state, currentExit.Position)
	if passage then
		return passage
	end
	local urgent = Doors.chaseActive()
	if urgent then
		state.blocked, state.blockCount = nil, 0
	end
	local blocked = state.blocked
	if
		blocked
		and blocked.room == room
		and (root.Position - blocked.position).Magnitude < 8
		and os.clock() < blocked.retryAt
	then
		return nil, "Replanning the blocked route"
	end
	state.blocked = nil
	local door = room:FindFirstChild("Door")
	local locked = door and door:GetAttribute("Locked") == true
	if urgent then
		for _, target in ipairs(Doors.targets(state)) do
			if
				target.current
				and target.kind == "door"
				and target.object == door
				and not Doors.doorOpen(target)
				and not locked
			then
				return Doors.blockingDoor(state, target.point, target.prompt) or target
			end
		end
		local exit = room:FindFirstChild("RoomExit")
		if exit and exit:IsA("BasePart") and not locked then
			return { object = exit, point = exit.Position, kind = "exit", title = "Escape: next exit", room = room }
		end
	end
	local best, score, waiting = nil, math.huge, false
	local targets, key = Doors.targets(state), Doors.keyTool()
	for _, target in ipairs(targets) do
		local nextEntrance = target.kind == "entrance"
			and target.room ~= nil
			and tonumber(target.room.Name) == (tonumber(room.Name) or -2) + 1
			and currentExit ~= nil
			and currentExit:IsA("BasePart")
			and (target.point - currentExit.Position).Magnitude <= 24
		local priority = ({ gate = 1, entrance = 2, vault = 3, terminal = 5, door = 6 })[target.kind]
		if target.kind == "key" and target.title ~= "KeyJewelry" and locked and not key then
			priority = 4
		end
		if target.kind == "drawer" and locked and not key then
			priority = 7
		end
		if target.kind == "terminal" and state.visitedTerminals[target.object] then
			priority = nil
		end
		if target.kind == "terminal" and urgent then
			priority = nil
		end
		if target.kind == "entrance" and Doors.pastEntrance(target.room or room, target.point) then
			priority = nil
		end
		if
			target.kind == "door" and Doors.doorOpen(target)
			or target.kind ~= "door"
				and (target.object:GetAttribute("Activated") == true or target.object:GetAttribute("Opened") == true)
		then
			priority = nil
		end
		if (target.current or nextEntrance) and priority then
			local attempt = state.attempts[target.prompt]
			waiting = true
			if
				(not attempt or os.clock() >= (attempt.retryAt or 0))
				and target.object:GetAttribute("Occupied") ~= true
			then
				local value = priority * 10000 + (root.Position - target.point).Magnitude
				if value < score then
					best, score = target, value
				end
			end
		end
	end
	if best then
		return Doors.blockingDoor(state, best.point, best.prompt) or best
	end
	if waiting then
		return nil, "Waiting for the interaction to be ready, then retrying"
	end
	local exit = room:FindFirstChild("RoomExit")
	if exit and exit:IsA("BasePart") and not locked then
		return { object = exit, point = exit.Position, kind = "exit", title = "Next door", room = room }
	end
	return nil, locked and "Looking for the key" or "Waiting for the next doorway to load"
end

function Doors.releaseTerminal(state)
	local terminal = state.terminal
	state.terminal = nil
	if terminal and not terminal.released then
		terminal.released = true
		task.spawn(function()
			if terminal.request and not terminal.request.done then
				for _ = 1, 80 do
					if terminal.request.done then
						break
					end
					task.wait(0.1)
				end
			end
			pcall(terminal.remote.InvokeServer, terminal.remote, "Release")
		end)
	end
end

function Doors.terminalStep(state, generation)
	local terminal = state.terminal
	if not terminal then
		return false
	end
	if
		not Doors.life(generation, false)
		or not Doors.settings().route
		or App.player.Character ~= terminal.character
		or not terminal.object:IsDescendantOf(state.rooms)
	then
		Doors.releaseTerminal(state)
		return false
	end
	local model = App.player.Character
	if not model:GetAttribute("InMinigame") then
		if os.clock() < (terminal.openingUntil or 0) then
			return true, "Opening the perk terminal"
		end
		Doors.releaseTerminal(state)
		return false
	end
	if terminal.request then
		if not terminal.request.done then
			if os.clock() - terminal.request.started > 12 then
				Doors.attempt(state, terminal.target, false)
				Doors.releaseTerminal(state)
				return true, "The terminal didn't respond, trying it again"
			end
			return true, "Waiting for the perk terminal reply"
		end
		local result, command = terminal.request.result, terminal.request.command
		terminal.request = nil
		if not result[1] or type(result[2]) ~= "table" then
			Doors.attempt(state, terminal.target, false)
			Doors.releaseTerminal(state)
			return true, "That didn't count, trying the terminal again"
		end
		if command == "Abstain" then
			state.visitedTerminals[terminal.object] = true
			Doors.releaseTerminal(state)
			return true, "Done at the terminal, moving on"
		end
		terminal.command = "Abstain"
	end
	local request = { command = terminal.command or "Fetch", done = false, started = os.clock() }
	terminal.request = request
	local dispatched = false
	call(terminal.remote, function()
		dispatched = true
		request.result = table.pack(pcall(terminal.remote.InvokeServer, terminal.remote, request.command, nil))
		request.done = true
	end, 2, generation)
	if not dispatched then
		terminal.request = nil
	end
	return true,
		request.command == "Abstain" and "Skipping the optional perk without spending candy"
			or "Reading the perk terminal"
end

function Doors.adoptTerminal(state)
	local model, root = character()
	if not model or not model:GetAttribute("InMinigame") or state.terminal or not Doors.settings().route then
		return
	end
	for prompt in pairs(state.prompts) do
		if prompt:IsDescendantOf(state.rooms) then
			local kind, object = Doors.classify(prompt)
			local point = kind == "terminal" and EventInput.point(prompt.Parent)
			local remote = point and object:FindFirstChild("TerminalRemote")
			if
				point
				and remote
				and remote:IsA("RemoteFunction")
				and (root.Position - point).Magnitude <= prompt.MaxActivationDistance + 2
				and getPath(object, "ScreenUI", "Frame", "Terminal")
			then
				state.terminal = {
					object = object,
					remote = remote,
					character = model,
					target = { prompt = prompt, object = object },
				}
				return
			end
		end
	end
end

function Doors.avoid(state, generation)
	local model, root = character()
	if not model then
		return nil
	end
	local entity, distance = Doors.threat()
	local hiding = model:GetAttribute("Hiding") == true or App.player:GetAttribute("Hiding") == true
	if hiding then
		state.hideStarted = state.hideStarted or os.clock()
		if distance > 100 then
			state.clearAt = state.clearAt or os.clock()
		else
			state.clearAt = nil
		end
		if
			((state.clearAt and os.clock() - state.clearAt >= 2) or os.clock() - state.hideStarted > 8)
			and os.clock() >= (state.leaveHideAt or 0)
		then
			state.leaveHideAt = os.clock() + 1
			EventInput.tap(state, generation, Enum.KeyCode.W)
			return "Leaving cover and resuming the route"
		end
		return "Taking cover while the entity passes"
	end
	state.hideStarted, state.clearAt = nil, nil
	if not entity or distance > 65 then
		return nil
	end
	local covers = {}
	for _, target in ipairs(Doors.targets(state)) do
		if
			target.kind == "hide"
			and target.object:GetAttribute("Occupied") ~= true
			and (target.point - entity.point).Magnitude > 12
		then
			target.distance = (target.point - root.Position).Magnitude
			table.insert(covers, target)
		end
	end
	table.sort(covers, function(a, b)
		return a.distance < b.distance
	end)
	for index = 1, math.min(3, #covers) do
		local cover = covers[index]
		local reached = Doors.walkTo(state, cover.point, generation, function()
			return cover.prompt.Enabled
		end, math.min(6, cover.prompt.MaxActivationDistance * 0.8), { evading = true, prompt = true })
		if reached and Doors.life(generation, true) then
			EventInput.hold(state, cover.prompt, generation, function()
				return Doors.life(generation, true)
			end)
			if model:GetAttribute("Hiding") == true or App.player:GetAttribute("Hiding") == true then
				state.hideStarted = os.clock()
			end
		end
		if state.hideStarted or not active(generation) then
			return "Taking cover from " .. entity.name
		end
	end
	local destination, safest = nil, distance
	for _, target in ipairs(Doors.targets(state)) do
		if target.kind == "exit" then
			local clearance = (target.point - entity.point).Magnitude
			if clearance > safest + 5 then
				destination, safest = target.point, clearance
			end
		end
	end
	if destination then
		Doors.walkTo(state, destination, generation, nil, 4, { evading = true })
		return "Moving away from " .. entity.name
	end
	local away = Vector3.new(root.Position.X - entity.point.X, 0, root.Position.Z - entity.point.Z)
	if away.Magnitude > 0.1 then
		away = away * (1 / away.Magnitude)
		local side = Vector3.new(-away.Z, 0, away.X)
		for _, offset in ipairs({ away * 18, away * 12 + side * 12, away * 12 - side * 12 }) do
			local reached = Doors.walkTo(state, root.Position + offset, generation, nil, 3, { evading = true })
			if reached or not active(generation) then
				break
			end
		end
	end
	return "Finding a clear route away from " .. entity.name
end

function Doors.hiding()
	local model = character()
	return model and (model:GetAttribute("Hiding") == true or App.player:GetAttribute("Hiding") == true)
end

function Doors.mark(state, target, color)
	local object = target.object
	local part = object:IsA("BasePart") and object or object:FindFirstChildWhichIsA("BasePart", true)
	if not part then
		return
	end
	local marker = state.markers[object]
	if not marker then
		local highlight = Instance.new("Highlight")
		highlight.Adornee, highlight.FillTransparency = object, 0.85
		highlight.OutlineTransparency, highlight.DepthMode = 0, Enum.HighlightDepthMode.AlwaysOnTop
		highlight.Parent = state.folder
		local billboard = Instance.new("BillboardGui")
		billboard.Adornee, billboard.AlwaysOnTop, billboard.MaxDistance = part, true, 400
		billboard.Size, billboard.StudsOffsetWorldSpace = UDim2.fromOffset(160, 26), Vector3.new(0, 2.5, 0)
		billboard.Parent = state.folder
		local text = Instance.new("TextLabel")
		text.Size, text.BackgroundTransparency = UDim2.fromScale(1, 1), 1
		text.TextSize, text.Font, text.TextStrokeTransparency = 12, Enum.Font.GothamBold, 0.25
		text.Parent = billboard
		marker = { highlight = highlight, billboard = billboard, text = text }
		state.markers[object] = marker
	end
	marker.highlight.FillColor, marker.highlight.OutlineColor, marker.text.TextColor3 = color, color, color
	marker.text.Text = target.title
	return marker
end

function Doors.visuals(state)
	local settings = Doors.settings()
	if not state.folder then
		state.folder = Instance.new("Folder")
		state.folder.Name, state.folder.Parent = "DoorsHelpers", App.gui
	end
	if not state.alert then
		local alert = Instance.new("TextLabel")
		alert.Name, alert.AnchorPoint = "DoorsEntityWarning", Vector2.new(0.5, 0)
		alert.Position, alert.Size = UDim2.new(0.5, 0, 0, 55), UDim2.new(0.85, 0, 0, 44)
		alert.BackgroundTransparency, alert.TextStrokeTransparency = 1, 0.2
		alert.TextSize, alert.Font = 17, Enum.Font.GothamBold
		alert.TextWrapped, alert.TextColor3, alert.Parent = true, Color3.fromRGB(255, 166, 130), state.folder
		state.alert = alert
	end
	local enabled = Doors.value("InGame") == true and not Doors.cutscene()
	local entity, distance = Doors.threat(true)
	local chasing = settings.seek and not state.entitySuspended and Doors.chaseActive()
	state.alert.Visible = enabled and ((settings.alerts and entity ~= nil) or chasing)
	state.alert.Text = entity
			and string.format(
				"%s | %d studs | %s",
				entity.name,
				distance,
				entity.kind == "gaze" and "Look away"
					or entity.kind == "chase" and "Keep moving to the next exit"
					or "Use cover"
			)
		or (chasing and "Seek chase: keep moving to the next exit" or "")
	if ui.doorsHint then
		ui.doorsHint.Text = state.dialMessage
			or (
				state.dialFrame and "Vault dial open. Assist uses A/D when enabled."
				or "ESP and warnings work without Start. Stop releases walking and dial input."
			)
	end
	local candidates, selected = {}, {}
	local _, root = character()
	if enabled and root then
		if settings.esp then
			for _, target in ipairs(Doors.targets(state)) do
				target.distance = (root.Position - target.point).Magnitude
				if target.distance < 400 then
					table.insert(candidates, target)
				end
			end
		end
		if settings.alerts then
			for _, item in ipairs(Doors.entities()) do
				table.insert(candidates, {
					object = item.object,
					title = item.name,
					kind = "entity",
					distance = (root.Position - item.point).Magnitude,
				})
			end
		end
		if chasing then
			local room = Doors.room(state)
			local exit = room and room:FindFirstChild("RoomExit")
			if exit and exit:IsA("BasePart") then
				table.insert(candidates, {
					object = exit,
					title = "Seek: next exit",
					kind = "chase",
					distance = (root.Position - exit.Position).Magnitude,
				})
			end
		end
		table.sort(candidates, function(a, b)
			return a.distance < b.distance
		end)
		for index = 1, math.min(28, #candidates) do
			local target = candidates[index]
			selected[target.object] = true
			local color = target.kind == "entity" and Color3.fromRGB(255, 128, 112)
				or target.kind == "hide" and Color3.fromRGB(125, 185, 255)
				or target.kind == "candy" and Color3.fromRGB(255, 183, 92)
				or Color3.fromRGB(116, 224, 179)
			Doors.mark(state, target, color)
		end
	end
	for object, marker in pairs(state.markers) do
		if not selected[object] or not object.Parent then
			marker.highlight:Destroy()
			marker.billboard:Destroy()
			state.markers[object] = nil
		end
	end
end

function Doors.clear(state)
	if not state or state.closed then
		return
	end
	state.closed = true
	if App.doorsState == state then
		App.doorsState = nil
		App.doorsStop = nil
	end
	if state.eyeBinding then
		pcall(RunService.UnbindFromRenderStep, RunService, state.eyeBinding)
		state.eyeBinding = nil
	end
	pcall(Doors.releaseCandy, state)
	pcall(Doors.restoreBrightness, state)
	pcall(Doors.releaseGaze, state)
	pcall(Doors.releaseWalk, state)
	pcall(Doors.releaseKey, state)
	pcall(EventInput.release, state)
	pcall(Doors.releaseTerminal, state)
	if state.added then
		pcall(state.added.Disconnect, state.added)
		state.added = nil
	end
	for _, connection in ipairs(state.connections or {}) do
		pcall(connection.Disconnect, connection)
	end
	if state.folder then
		pcall(state.folder.Destroy, state.folder)
		state.folder = nil
	end
	state.gazeParams, state.gazeCharacter = nil, nil
end

function Doors.ensure()
	if App.doorsState then
		return App.doorsState
	end
	local state = {
		scan = {},
		prompts = {},
		exits = {},
		markers = {},
		attempts = {},
		connections = {},
		visitedTerminals = setmetatable({}, { __mode = "k" }),
	}
	App.doorsState = state
	App.doorsStop = function()
		state.entitySuspended = true
		state.candySuspended = true
		Doors.releaseCandy(state)
		Doors.releaseGaze(state)
		Doors.releaseWalk(state)
		Doors.releaseKey(state)
		EventInput.release(state)
		Doors.releaseTerminal(state)
		state.suspendFrame = Doors.dialFrame()
	end
	pcall(Doors.brightness, state)
	state.eyeBinding = "HollowEyes_" .. tostring(os.clock())
	local bound = pcall(function()
		RunService:BindToRenderStep(state.eyeBinding, Enum.RenderPriority.Camera.Value + 1, function()
			local ok = pcall(Doors.eyeAssist, state)
			if not ok then
				Doors.releaseGaze(state)
			end
		end)
	end)
	if not bound then
		state.eyeBinding = nil
	end
	for _, pair in ipairs({ { Input.WindowFocusReleased, true }, { Input.WindowFocused, false } }) do
		table.insert(
			state.connections,
			pair[1]:Connect(function()
				state.unfocused = pair[2]
				if state.unfocused then
					Doors.releaseKey(state)
				end
			end)
		)
	end
	task.spawn(function()
		while App.alive and App.doorsState == state do
			pcall(Doors.brightness, state)
			pcall(Doors.eatCandy, state)
			local ok, reason = pcall(function()
				Doors.scan(state)
				Doors.assist(state)
				if not state.eyeBinding then
					Doors.eyeAssist(state)
				end
				if os.clock() >= (state.visualAt or 0) then
					state.visualAt = os.clock() + 0.35
					Doors.visuals(state)
				end
			end)
			if not ok then
				Doors.releaseKey(state)
				if not state.errorLogged then
					state.errorLogged = true
					log("DOORS helper: " .. tostring(reason))
				end
			end
			task.wait(
				(state.dialFrame or not state.eyeBinding and Doors.settings().eyes and not state.entitySuspended)
						and 0.03
					or 0.15
			)
		end
	end)
	return state
end

function Doors.option(name)
	local settings = Doors.settings()
	settings[name] = not settings[name]
	local state = Doors.ensure()
	if name == "bright" then
		state.lightAt = 0
		pcall(Doors.brightness, state)
	end
	if name == "candy" then
		state.candySuspended = false
		if not settings.candy then
			Doors.releaseCandy(state)
		end
	end
	if name == "eyes" or name == "seek" then
		state.entitySuspended = false
		if not settings.eyes then
			Doors.releaseGaze(state)
		end
	end
	if name == "route" and not settings.route then
		Doors.releaseWalk(state)
		EventInput.release(state)
		Doors.releaseTerminal(state)
		if not settings.dial then
			Doors.releaseKey(state)
		end
	end
	if name == "dial" then
		state.suspendFrame = nil
		state.inputRetryAt, state.dialMotionAt = 0, os.clock()
		state.dialStart, state.dialChanges = os.clock(), 0
		if not settings.dial and not (App.running and settings.route) then
			Doors.releaseKey(state)
		end
	end
	if name == "route" then
		state.blocked, state.blockCount = nil, 0
	end
	refresh()
end

local function runDoors(generation)
	if verify(current, true) then
		return true, "Sweet Deceit is already on your account"
	end
	if game.PlaceId ~= current.gameplayPlace then
		prepareTravel(current.gameplayPlace, true)
		return false, "Join The Candy Vault from DOORS' elevator menu, then press Start."
	end
	local state = Doors.ensure()
	Doors.settings().route = true
	refresh()
	state.attempts = {}
	state.runGeneration = generation
	state.entitySuspended = false
	state.candySuspended = false
	table.insert(App.cleanups, function()
		state.candySuspended = true
		Doors.releaseCandy(state)
		Doors.releaseWalk(state)
		Doors.releaseKey(state)
		EventInput.release(state)
		Doors.releaseTerminal(state)
		state.runGeneration = nil
		state.entitySuspended = true
		Doors.releaseGaze(state)
		state.suspendFrame = Doors.dialFrame()
	end)
	state.suspendFrame, state.blocked, state.blockCount = nil, nil, 0
	state.dialStart, state.dialChanges, state.inputRetryAt = os.clock(), 0, 0
	local checkAt, retryAt = os.clock() + 30, 0
	while active(generation) do
		Doors.scan(state)
		if not Doors.dialFrame() then
			Doors.adoptTerminal(state)
		end
		local room, number = Doors.room(state)
		local detail
		if Doors.value("Floor") == nil then
			detail = "Waiting for the floor data to load"
		elseif Doors.value("Floor") ~= "Halloween26" then
			return false, "This is a different floor. Join The Candy Vault for the Hollow badge."
		elseif Doors.value("RunHasBeenEnded") == true then
			if verify(current, true) then
				return true, "Sweet Deceit confirmed"
			end
			return false, "The run ended. Check the results to see if Sweet Deceit counted."
		elseif not Doors.life(generation, false) then
			detail = Doors.blocker(generation, false)
		elseif state.terminal then
			local _, message = Doors.terminalStep(state, generation)
			detail = message or "Finishing the terminal interaction"
		elseif state.dialFrame or Doors.dialFrame() then
			detail = state.dialMessage or "Turning the vault dial"
		elseif not Doors.settings().route then
			detail = "Manual play. ESP, warnings, and optional dial assist stay separate."
		elseif Doors.waitingForHost() then
			detail = "Waiting for the host's start signal"
		elseif Doors.hiding() then
			detail = Doors.avoid(state, generation)
		elseif not Doors.life(generation, true) then
			detail = Doors.blocker(generation, true)
		elseif select(2, Doors.threat()) <= 65 then
			detail = Doors.avoid(state, generation)
		elseif os.clock() >= retryAt then
			local target, reason = Doors.nextTarget(state)
			if target then
				detail = target.title
				status("The Candy Vault", target.title, App.progress)
				local function allowed()
					return Doors.room(state) == room
						and target.object:IsDescendantOf(state.rooms)
						and (not target.prompt or Doors.promptEnabled(target.prompt))
				end
				local reached, blocked, progressed = Doors.walkTo(
					state,
					target.point,
					generation,
					allowed,
					target.prompt and math.min(7, target.prompt.MaxActivationDistance * 0.85) or 4,
					{ prompt = target.prompt }
				)
				if reached and target.prompt and Doors.life(generation, true) and allowed() then
					state.blockCount = 0
					local model, _, humanoid = character()
					if target.kind == "door" then
						local tool = Doors.keyTool()
						if tool and tool.Parent ~= model then
							pcall(humanoid.EquipTool, humanoid, tool)
						end
					end
					local minigame = model:GetAttribute("InMinigame")
					if target.kind == "terminal" and not minigame then
						local remote = target.object:FindFirstChild("TerminalRemote")
						if remote and remote:IsA("RemoteFunction") then
							state.terminal = {
								object = target.object,
								remote = remote,
								character = model,
								target = target,
								openingUntil = os.clock() + 2,
							}
						end
					end
					local success = Doors.interact(state, target, generation, function()
						local _, near = Doors.threat()
						return Doors.life(generation, true) and near > 65 and allowed()
					end)
					Doors.attempt(state, target, success)
					retryAt = os.clock() + 0.25
				elseif reached and target.kind == "exit" and Doors.life(generation, true) then
					state.blockCount = 0
					local exit = target.object
					local entrance = room:FindFirstChild("RoomEntrance")
					local forward = exit.CFrame.LookVector
					if entrance then
						local from = exit.Position - entrance.Position
						if forward.X * from.X + forward.Y * from.Y + forward.Z * from.Z < 0 then
							forward = forward * -1
						end
					end
					if forward.Magnitude > 0.01 then
						Doors.walkTo(state, exit.Position + forward * (7 / forward.Magnitude), generation, allowed, 3)
					end
					retryAt = os.clock() + 0.5
				elseif not reached then
					detail, retryAt = blocked, os.clock() + (progressed and 0.15 or 0.75)
					if progressed then
						state.blockCount = 0
					elseif Doors.life(generation, true) and allowed() then
						state.blockCount = (state.blockCount or 0) + 1
						if state.blockCount >= 3 then
							local _, root = character()
							state.blocked = { room = room, position = root.Position, retryAt = os.clock() + 4 }
							state.blockCount = 0
						end
					end
				end
			else
				detail = reason
			end
			state.routeDetail = detail
		else
			detail = state.routeDetail or "Rechecking the room"
		end
		if os.clock() >= checkAt then
			checkAt = os.clock() + 30
			if verify(current, true) then
				return true, "Sweet Deceit confirmed"
			end
		end
		if not active(generation) then
			break
		end
		status(
			"The Candy Vault",
			string.format(
				"Room %s | Run candy: %s\n%s",
				tostring(number or "?"),
				tostring(Doors.value("CandyPot") or 0),
				detail or "Rechecking the room"
			),
			App.progress
		)
		if not pause(0.15, generation) then
			break
		end
	end
	return false, "Stopped"
end

local Nights = {}

function Nights.life(session, generation, model)
	local live, root, humanoid = character()
	if
		not active(generation)
		or not live
		or model and live ~= model
		or root.Anchored
		or humanoid.Sit
		or humanoid.PlatformStand
		or App.player:GetAttribute("Undead") == true
		or App.player:GetAttribute("Dead") == true
	then
		return false
	end
	if session.client then
		local ok, ready = pcall(function()
			return session.client.PlayerHandler.Alive ~= false
				and not session.client.Utility.IsDisabled(App.player)
				and not session.client.CutsceneModuleClient.IsCutsceneRunning()
		end)
		if not ok or not ready then
			return false
		end
	end
	return true
end

function Nights.progress()
	local map = workspace:FindFirstChild("HollowMap")
	local total = map and map:GetAttribute("PlantCount")
	if type(total) ~= "number" or total <= 0 or total % 1 ~= 0 or total > 500 then
		return nil
	end
	local remaining = {}
	for name, point in pairs(map:GetAttributes()) do
		if name:match("^HollowPlant%d+$") and typeof(point) == "Vector3" then
			table.insert(remaining, { name = name, point = Vector3.new(point.X, -300, point.Z) })
		end
	end
	return remaining, total, map
end

function Nights.flower(session)
	local remaining, total, map = Nights.progress()
	if not remaining then
		return nil, total, map
	end
	local _, root = character()
	if not root then
		return nil, total, map
	end
	local best, distance = nil, math.huge
	local streamed = Collection:GetTagged("HollowPlant")
	for _, entry in ipairs(remaining) do
		for _, model in ipairs(streamed) do
			if model:IsDescendantOf(map) then
				local point = positionOf(model)
				if point and Vector3.new(point.X - entry.point.X, 0, point.Z - entry.point.Z).Magnitude < 12 then
					entry.object, entry.point = model, point
					break
				end
			end
		end
		local length = (entry.point - root.Position).Magnitude
		if
			os.clock() >= (session.retryAt[entry.name] or 0)
			and (
				not best
				or entry.object and not best.object
				or (entry.object ~= nil) == (best.object ~= nil) and length < distance
			)
		then
			best, distance = entry, length
		end
	end
	return best, total, map, #remaining
end

function Nights.void()
	local _, root = character()
	return root
		and App.player:GetAttribute("InHollowRun") == true
		and Vector3.new(root.Position.X, 0, root.Position.Z - 8000).Magnitude < 1600
		and root.Position.Y <= -150
		and root.Position.Y > -600
end

function Nights.move(session, point, generation)
	return approach(point, generation, nil, false, function()
		return Nights.life(session, generation)
	end)
end

function Nights.ground(point)
	if math.abs(point.X) > 880 or math.abs(point.Z - 8000) > 880 then
		return nil
	end
	local map, terrain = workspace:FindFirstChild("HollowMap"), workspace:FindFirstChildOfClass("Terrain")
	local ground = map and map:FindFirstChild("Ground")
	if not ground and not terrain then
		return nil
	end
	local params = RaycastParams.new()
	params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Include, { ground or terrain }
	if ground and terrain then
		params.FilterDescendantsInstances = { ground, terrain }
	end
	params.RespectCanCollide, params.IgnoreWater = true, true
	local bottom = math.max(-580, workspace.FallenPartsDestroyHeight + 32)
	local hit = workspace:Raycast(Vector3.new(point.X, -145, point.Z), Vector3.new(0, bottom + 145, 0), params)
	if hit and hit.Normal.Y > 0.65 and hit.Position.Y < -150 and hit.Position.Y > bottom then
		return hit.Position
	end
	return nil
end

function Nights.stream(session, point, generation)
	if os.clock() < (session.streamAt or 0) then
		return
	end
	session.streamAt = os.clock() + 1.5
	call("Void flower streaming", function()
		if Nights.life(session, generation) and Nights.void() then
			App.player:RequestStreamAroundAsync(point, 1)
		end
	end, 2, generation)
end

function Nights.seek(session, flower, generation)
	if not Nights.life(session, generation) or not Nights.void() then
		return false
	end
	if not flower.object then
		Nights.stream(session, flower.point, generation)
		local refreshed = Nights.flower(session)
		if refreshed and refreshed.name == flower.name and refreshed.object then
			flower.object, flower.point = refreshed.object, refreshed.point
		end
	end
	if not Nights.life(session, generation) or not Nights.void() then
		return false
	end
	local ground = Nights.ground(flower.point)
	if ground then
		return Nights.move(session, ground, generation)
	end
	local _, root = character()
	local delta = Vector3.new(flower.point.X - root.Position.X, 0, flower.point.Z - root.Position.Z)
	if delta.Magnitude < 8 then
		return false
	end
	local forward = delta.Unit
	local right = Vector3.new(-forward.Z, 0, forward.X)
	session.explored = session.explored or {}
	local best, score
	for _, length in ipairs({ 120, 80, 40 }) do
		for _, side in ipairs({ 0, 0.7, -0.7, 1.5, -1.5 }) do
			local direction = (forward + right * side).Unit
			local point = root.Position + direction * math.min(length, delta.Magnitude)
			local floor = Nights.ground(point)
			if floor then
				local key = math.floor(point.X / 40) .. ":" .. math.floor(point.Z / 40)
				local cost = (flower.point - floor).Magnitude + ((session.explored[key] or 0) > os.clock() and 300 or 0)
				if not score or cost < score then
					best, score = { point = floor, key = key }, cost
				end
			end
		end
	end
	status("Exploring the void", "Moving closer so the remaining flowers can load", App.progress)
	if best then
		session.explored[best.key] = os.clock() + 20
		Nights.move(session, best.point, generation)
	end
	return false
end

function Nights.release(session)
	if session.dragConstraint then
		pcall(session.dragConstraint.Destroy, session.dragConstraint)
		session.dragConstraint = nil
	end
	if session.carried then
		fire(getPath(Storage, "RemoteEvents", "StopDraggingItem"), session.carried)
		session.carried = nil
	end
	EventInput.release(session)
	if session.inventory and session.usedAxe then
		pcall(session.inventory.DeactivateTool)
	end
end

function Nights.fuel(session, generation)
	local fireModel = getPath(workspace, "Map", "Campground", "MainFire")
	local point = fireModel and positionOf(fireModel)
	local items = workspace:FindFirstChild("Items")
	local _, root = character()
	if not point or not items or not root then
		return false, "Waiting for the campfire and loose fuel"
	end
	local interaction = session.client and session.client.InteractionHandler
	if interaction and type(interaction.GetDraggingItem) == "function" and interaction.GetDraggingItem() then
		return false, "Put down the item you're dragging first"
	end
	local selected, best = nil, math.huge
	for _, item in ipairs(items:GetChildren()) do
		if not item:IsA("Model") or not item.PrimaryPart then
			continue
		end
		local fuel, owner = item:GetAttribute("BurnFuel"), item:GetAttribute("Owner")
		local itemPoint = positionOf(item)
		if
			type(fuel) == "number"
			and fuel > 0
			and (item:GetAttribute("Wet") or 0) < 1
			and (owner == nil or owner == App.player.UserId)
			and item:GetAttribute("Locked") ~= true
			and itemPoint
			and os.clock() >= (session.retryAt[item] or 0)
		then
			local cost = (itemPoint - root.Position).Magnitude / math.min(fuel, 270)
			if cost < best then
				selected, best = item, cost
			end
		end
	end
	if not selected then
		return false, "Looking for dry fuel or an axe to cut more wood"
	end
	local model = character()
	status(
		"Fueling the campfire",
		selected.Name .. " | Fire level " .. tostring(workspace:GetAttribute("Progress") or "?"),
		0.05
	)
	if
		not Nights.move(session, point + Vector3.new(10, 0, 0), generation)
		or not Nights.life(session, generation, model)
	then
		return false, "Rechecking the fuel route"
	end
	if
		not selected:IsDescendantOf(items)
		or selected:GetAttribute("Owner") and selected:GetAttribute("Owner") ~= App.player.UserId
	then
		return false, "Someone took that fuel, finding another"
	end
	local part = selected.PrimaryPart
	local attachment = part and part:FindFirstChild("DraggingAttachment")
	if not attachment then
		session.retryAt[selected] = os.clock() + 5
		return false, "Waiting for the fuel's drag attachment"
	end
	local near = point + Vector3.new(9, 2, 0)
	local brought = pcall(function()
		selected:PivotTo(CFrame.new(near))
		part.AssemblyLinearVelocity, part.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
	end)
	if not brought or not pause(0.15, generation) or not Nights.life(session, generation, model) then
		return false, "Fuel pickup interrupted"
	end
	session.carried = selected
	local sent = fire(getPath(Storage, "RemoteEvents", "RequestStartDraggingItem"), selected)
	local owned = sent
		and waitUntil(function()
			local owner = selected:GetAttribute("Owner")
			if
				not selected:IsDescendantOf(items)
				or not Nights.life(session, generation, model)
				or owner and owner ~= App.player.UserId
			then
				return "interrupted"
			end
			return owner == App.player.UserId and "ready"
		end, 2, generation)
	if owned ~= "ready" then
		session.retryAt[selected] = os.clock() + 5
		Nights.release(session)
		return false, "Waiting for the game to accept the fuel pickup"
	end
	if (workspace:GetAttribute("Progress") or 0) >= 3 then
		Nights.release(session)
		return true
	end
	local zone = fireModel:FindFirstChild("InnerTouchZone")
	local destination = zone and zone:IsA("BasePart") and zone.Position or point + Vector3.new(0, 2, 0)
	local before, beforeLevel = fireModel:GetAttribute("FuelRemaining"), workspace:GetAttribute("Progress") or 0
	local moved = pcall(function()
		local constraint = Instance.new("AlignPosition")
		session.dragConstraint = constraint
		constraint.Mode = Enum.PositionAlignmentMode.OneAttachment
		constraint.Attachment0 = attachment
		constraint.MaxForce, constraint.Responsiveness = 10000, 50
		constraint.Position = destination
		constraint.Parent = part
	end)
	if not moved then
		Nights.release(session)
		return false, "Fuel delivery interrupted"
	end
	local requested = false
	local credited = waitUntil(function()
		local fuel = fireModel:GetAttribute("FuelRemaining")
		if
			(type(fuel) == "number" and type(before) == "number" and fuel > before)
			or (workspace:GetAttribute("Progress") or 0) > beforeLevel
		then
			return "credited"
		end
		if
			not Nights.life(session, generation, model)
			or selected:GetAttribute("Owner") and selected:GetAttribute("Owner") ~= App.player.UserId
		then
			return "interrupted"
		end
		if not requested and selected:IsDescendantOf(items) and selected:GetAttribute("Owner") == App.player.UserId then
			local itemPoint = positionOf(selected)
			if itemPoint and (itemPoint - destination).Magnitude <= 3 then
				requested = true
				fire(getPath(Storage, "RemoteEvents", "RequestBurnItem"), fireModel, selected)
			end
		end
	end, 5, generation)
	session.retryAt[selected] = os.clock() + 5
	Nights.release(session)
	return credited == "credited",
		credited == "credited" and "Fuel added" or "Waiting for the campfire to credit the fuel"
end

function Nights.chop(session, generation)
	if not session.inventory then
		return false
	end
	local inventory = App.player:FindFirstChild("Inventory")
	local axe
	for _, item in ipairs(inventory and inventory:GetChildren() or {}) do
		if item:GetAttribute("ToolName") == "GenericAxe" then
			axe = item
			break
		end
	end
	if not axe then
		return false
	end
	session.trees = session.trees or setmetatable({}, { __mode = "k" })
	if not session.treeScan or (#session.treeScan == 0 and os.clock() >= (session.treeScanAt or 0)) then
		local foliage = getPath(workspace, "Map", "Foliage")
		session.treeScan = foliage and { foliage } or {}
		session.treeScanAt = os.clock() + 5
	end
	local untilAt = os.clock() + 0.0015
	for _ = 1, 120 do
		local object = table.remove(session.treeScan)
		if not object then
			break
		end
		if object:IsDescendantOf(workspace) then
			if object:IsA("Model") and object:GetAttribute("Resource") == "Tree" then
				session.trees[object] = true
			else
				for _, child in ipairs(object:GetChildren()) do
					table.insert(session.treeScan, child)
				end
			end
		end
		if os.clock() >= untilAt then
			break
		end
	end
	local tree, best = nil, math.huge
	local _, root = character()
	for model in pairs(session.trees) do
		local point = model.Parent and positionOf(model)
		if point and root and (model:GetAttribute("Health") or 0) > 0 then
			local distance = (root.Position - point).Magnitude
			if distance < best then
				tree, best = model, distance
			end
		else
			session.trees[model] = nil
		end
	end
	if not tree then
		return false
	end
	local point = positionOf(tree)
	if not point or not Nights.move(session, point + Vector3.new(3, 0, 0), generation) then
		return false
	end
	if not Nights.life(session, generation) then
		return false
	end
	local ok = pcall(session.inventory.RequestEquipItem, axe)
	if not ok or not pause(0.2, generation) then
		return false
	end
	if
		type(session.inventory.GetCurrentlyEquipped) ~= "function"
		or session.inventory.GetCurrentlyEquipped() ~= axe
	then
		return false
	end
	local _, root = character()
	if not Nights.life(session, generation) or not root then
		return false
	end
	root.CFrame = CFrame.lookAt(root.Position, Vector3.new(point.X, root.Position.Y, point.Z))
	session.usedAxe = true
	for _ = 1, 15 do
		if not Nights.life(session, generation) or not tree.Parent or (tree:GetAttribute("Health") or 0) <= 0 then
			break
		end
		pcall(session.inventory.ActivateTool)
		if not pause(math.clamp(axe:GetAttribute("ToolCooldown") or 0.5, 0.3, 3), generation) then
			break
		end
	end
	pcall(session.inventory.DeactivateTool)
	return true
end

function Nights.enter(session, generation)
	local entrance = getPath(workspace, "Map", "Landmarks", "HollowEntrance")
	local teleporter = getPath(entrance, "Functional", "Teleporter1")
	local point = teleporter and positionOf(teleporter) or entrance and positionOf(entrance)
	if not point then
		local ok, value = invoke(getPath(Storage, "RemoteEvents", "GetHollowEntrancePosition"), generation)
		if ok and typeof(value) == "Vector3" then
			point = value
		end
	end
	if not point then
		return false, "Waiting for the void entrance to load"
	end
	status("Entering the void", "Moving into the event teleporter", 0.15)
	if not Nights.move(session, point, generation) then
		return false, "Rechecking the void entrance"
	end
	local prompt = teleporter and teleporter:FindFirstChildWhichIsA("ProximityPrompt", true)
	if prompt and prompt.Enabled and Nights.life(session, generation) then
		EventInput.hold(session, prompt, generation, function()
			return Nights.life(session, generation)
		end)
	end
	local entered = waitUntil(function()
		return Nights.void() or not Nights.life(session, generation)
	end, 12, generation)
	return entered and Nights.void(), "Waiting for the event teleporter"
end

function Nights.upgrade(session, generation)
	local ready = App.player:GetAttribute("HollowUpgradesReady") or 0
	if ready <= 0 or session.upgradePending then
		if session.upgradePending and ready < session.upgradePending then
			session.upgradePending = nil
		end
		return
	end
	local ok, offers = invoke(getPath(Storage, "RemoteEvents", "GetHollowUpgradeOffer"), generation)
	if not ok or type(offers) ~= "table" or not Nights.life(session, generation) or not Nights.void() then
		return
	end
	local selected, best = nil, -1
	for _, offer in ipairs(offers) do
		if type(offer) == "table" and (type(offer.Id) == "string" or type(offer.Id) == "number") then
			local text = (tostring(offer.Id) .. " " .. tostring(offer.Text)):lower()
			local score = text:find("hunger", 1, true) and 3 or text:find("speed", 1, true) and 2 or 1
			if score > best then
				selected, best = offer, score
			end
		end
	end
	if selected and pause(0.5, generation) and Nights.life(session, generation) and Nights.void() then
		session.upgradePending = ready
		invoke(getPath(Storage, "RemoteEvents", "ChooseHollowUpgrade"), generation, selected.Id)
	end
end

local function runNights(generation)
	if verify(current, true) then
		return true, "The Hollow badge is already on your account"
	end
	if game.PlaceId ~= current.gameplayPlace then
		prepareTravel(current.gameplayPlace, true)
		return false, "Join a forest match first. The helper will run there if teleport continuation is supported."
	end
	local session = { retryAt = setmetatable({}, { __mode = "k" }) }
	table.insert(App.cleanups, function()
		Nights.release(session)
	end)
	local client = module(getPath(App.player, "PlayerScripts", "Client"), generation)
	if client then
		session.client = client
		local ok, inventory = pcall(function()
			return client.InventoryHandler
		end)
		if ok then
			session.inventory = inventory
		end
	end
	local deadline, checkAt = os.clock() + 1800, 0
	while active(generation) and os.clock() < deadline do
		if App.player:GetAttribute("OwnsHollowBadge") == true then
			return true, "The Hollow badge confirmed"
		end
		if os.clock() >= checkAt then
			checkAt = os.clock() + 20
			if App.player:GetAttribute("OwnsHollowBadge") == true or verify(current, true) then
				return true, "The Hollow badge confirmed"
			end
		end
		if Storage:GetAttribute("Hollow_Active") == false then
			return false, "The Hollow event isn't active in this server"
		end
		if not Nights.life(session, generation) then
			status("Waiting for your character", "Letting the revival or cutscene finish", App.progress)
		elseif App.player:GetAttribute("HollowBeaten") == true then
			status("Flowers collected", "Waiting for the badge to be saved", 0.98)
		elseif Nights.void() then
			Nights.upgrade(session, generation)
			local flower, total, map, remaining = Nights.flower(session)
			if total then
				local count = total - (remaining or total)
				status(
					"Collecting red flowers",
					string.format("%d / %d flowers collected", count, total),
					0.2 + 0.75 * count / total
				)
			end
			if flower then
				if Nights.seek(session, flower, generation) then
					local prompt = flower.object and flower.object:FindFirstChildWhichIsA("ProximityPrompt", true)
					if prompt and prompt.Enabled then
						EventInput.hold(session, prompt, generation, function()
							return Nights.life(session, generation) and Nights.void()
						end)
					end
					waitUntil(function()
						return map:GetAttribute(flower.name) == nil or not Nights.void()
					end, 2, generation)
				end
				session.retryAt[flower.name] = os.clock() + 1.5
			else
				status(
					total and "Waiting for flower progress" or "Loading the void map",
					"Checking the remaining flowers",
					App.progress
				)
			end
		elseif App.player:GetAttribute("InHollowRun") == true then
			status("Entering the void", "Waiting for the transition to finish", App.progress)
		elseif (workspace:GetAttribute("Progress") or 0) < 3 then
			local fueled, reason = Nights.fuel(session, generation)
			if not fueled then
				Nights.chop(session, generation)
				status("Fueling the campfire", reason, 0.05)
			end
		else
			Nights.enter(session, generation)
		end
		if not pause(0.2, generation) then
			break
		end
	end
	return false, active(generation) and "The forest run reached its time limit" or "Stopped"
end

local runners = {
	hollow = runHollow,
	keyboard = runKeyboard,
	egg = runEgg,
	royale = runRoyale,
	garden = runGarden,
	mvsd = runMvsd,
	duels = runDuels,
	hunted = runHunted,
	arcade = runArcade,
	needle = runGraveyard,
	prism = runPrism,
	moo = runMoo,
	duck = runDuck,
	bloxburg = runBloxburg,
	toons = runToons,
	lemons = runLemons,
	flee = runFlee,
	demonology = runDemonology,
	dandy = runDandy,
	aooni = runAooni,
	doors = runDoors,
	nights = runNights,
}
do
	-- hospital
	local Hospital = {}
	function Hospital.board(puzzle)
		if not puzzle or puzzle:GetAttribute("PuzzleSetupDone") ~= true then
			return nil
		end
		local board, slots, seen, empty = {}, {}, {}, 0
		for index = 1, 9 do
			local slot = puzzle:FindFirstChild(tostring(index))
			if not slot or not slot:IsA("BasePart") then
				return nil
			end
			slots[index] = slot
			local value = 0
			for _, piece in ipairs(slot:GetChildren()) do
				if piece:IsA("Decal") then
					local id = tonumber(piece.Name)
					if not id or id % 1 ~= 0 or id < 1 or id > 9 or value ~= 0 or seen[id] then
						return nil
					end
					value, seen[id] = id, true
				end
			end
			board[index] = value
			if value == 0 then
				empty += 1
			end
		end
		return empty == 1 and board or nil, slots
	end
	function Hospital.same(a, b)
		if not a or not b then
			return false
		end
		for i = 1, 9 do
			if a[i] ~= b[i] then
				return false
			end
		end
		return true
	end
	function Hospital.ready(session, generation)
		local model, root = character()
		local camera = workspace.CurrentCamera
		return active(generation)
			and (not session.manual or not App.running)
			and model == session.model
			and root
			and not root.Anchored
			and not App.cameraBusy
			and (not camera or camera.CameraType ~= Enum.CameraType.Scriptable)
	end
	function Hospital.objective(session)
		local label = getPath(App.player, "PlayerGui", "Objective", "Frame", "keys", "objective")
		local text = label and Hospital.visible(label) and label.Text or session.text or ""
		if session.objectiveText ~= text then
			if session.text and text ~= session.text then
				session.target, session.location = nil, nil
			end
			session.objectiveText = text
			session.revision = (session.revision or 0) + 1
			session.inspected = setmetatable({}, { __mode = "k" })
		end
		return text
	end
	function Hospital.bind(session)
		local net = getPath(Storage, "Util", "Net")
		for name, callback in pairs({
			SetObjective = function(text, _, target)
				if session.text ~= text or session.target ~= target then
					session.revision = (session.revision or 0) + 1
				end
				session.text, session.target, session.location = text, target, nil
			end,
			SetObjectiveByLocation = function(location, text)
				if session.text ~= text or session.location ~= location then
					session.revision = (session.revision or 0) + 1
				end
				session.text, session.target, session.location = text, nil, location
			end,
		}) do
			local remote = net and net:FindFirstChild("RE/" .. name)
			if remote and remote:IsA("RemoteEvent") and not session.bound[remote] then
				session.bound[remote] = remote.OnClientEvent:Connect(callback)
			end
		end
	end
	function Hospital.related(object, target)
		return object
			and target
			and (object == target or object:IsDescendantOf(target) or target:IsDescendantOf(object))
	end
	function Hospital.pictureRequested(session, puzzle)
		local text = Hospital.text(Hospital.objective(session))
		local target = Hospital.target(session)
		if session.target and target == session.target then
			return puzzle and Hospital.related(target, puzzle)
		end
		return puzzle
			and (
				Hospital.related(target, puzzle)
				or text:find("puzzle", 1, true)
				or text:find("tiles", 1, true)
				or text:find("picture", 1, true) and (text:find("solve", 1, true) or text:find("slid", 1, true))
			)
	end
	function Hospital.inspecting(session)
		local getter = type(session.lib) == "table" and rawget(session.lib, "GetCurrentInspect")
		if type(getter) == "function" then
			local ok, object = pcall(getter)
			if ok then
				return object, true
			end
		end
		return nil, false
	end
	function Hospital.dismissInspect(session, generation)
		EventInput.release(session)
		if not active(generation) then
			return false
		end
		if type(firesignal) == "function" then
			local ok = pcall(firesignal, Input.InputBegan, {
				UserInputType = Enum.UserInputType.MouseButton1,
				KeyCode = Enum.KeyCode.Unknown,
			}, false)
			if ok then
				return true
			end
		end
		return pcall(function()
			local manager = game:GetService("VirtualInputManager")
			local point = workspace.CurrentCamera.ViewportSize * 0.5
			local pressed, why = pcall(manager.SendMouseButtonEvent, manager, point.X, point.Y, 0, true, game, 0)
			pcall(manager.SendMouseButtonEvent, manager, point.X, point.Y, 0, false, game, 0)
			if not pressed then
				error(why)
			end
		end)
	end
	function Hospital.aim(session, part, generation)
		local camera = workspace.CurrentCamera
		if not camera or not Hospital.ready(session, generation) then
			return false
		end
		local look = session.look
		if not look or look.target ~= part or look.camera ~= camera or look.cameraEpoch ~= App.cameraEpoch then
			EventInput.endLook(session)
			look = {
				camera = camera,
				kind = camera.CameraType,
				previous = camera.CFrame,
				cameraEpoch = App.cameraEpoch,
				target = part,
			}
			session.look = look
			local function update()
				if session.look ~= look then
					return
				end
				if
					not part.Parent
					or not Hospital.ready(session, generation)
					or camera ~= workspace.CurrentCamera
					or camera.CameraType ~= look.kind
					or look.cameraEpoch ~= App.cameraEpoch
				then
					EventInput.endLook(session)
					return
				end
				look.aim = CFrame.lookAt(camera.CFrame.Position, part.Position)
				camera.CFrame = look.aim
			end
			look.update = update
			local binding = "HollowHospitalLook_" .. tostring(generation)
			if pcall(RunService.BindToRenderStep, RunService, binding, Enum.RenderPriority.Last.Value - 1, update) then
				look.binding = binding
			end
		end
		look.update()
		return pause(0.08, generation) and Hospital.ready(session, generation)
	end
	function Hospital.click(session, detector, generation)
		local part = detector and detector.Parent
		local camera, _, root = workspace.CurrentCamera, character()
		if
			not camera
			or not part
			or not part:IsA("BasePart")
			or not detector:IsDescendantOf(workspace)
			or not Hospital.ready(session, generation)
			or (root.Position - part.Position).Magnitude > detector.MaxActivationDistance
		then
			return false, "The picture tile is out of reach"
		end
		local ok, why = false, "Picture clicking isn't available on this executor"
		if Hospital.aim(session, part, generation) then
			if type(fireclickdetector) == "function" then
				ok, why = pcall(fireclickdetector, detector)
				ok = ok and why ~= false
			else
				local point, visible = camera:WorldToScreenPoint(part.Position)
				local gui = App.player:FindFirstChild("PlayerGui")
				local clear = visible
				if clear and gui then
					for _, object in ipairs(gui:GetGuiObjectsAtPosition(point.X, point.Y)) do
						if object.Active then
							clear = false
							break
						end
					end
				end
				if clear then
					ok, why = pcall(function()
						local service = game:GetService("VirtualInputManager")
						local pressed, problem =
							pcall(service.SendMouseButtonEvent, service, point.X, point.Y, 0, true, game, 0)
						pcall(service.SendMouseButtonEvent, service, point.X, point.Y, 0, false, game, 0)
						if not pressed then
							error(problem)
						end
					end)
				else
					why = "A menu covers the tile. Hide the panel or move it aside."
				end
			end
		end
		return ok, why
	end
	function Hospital.solve(session, puzzle, generation, allowed)
		local function ready()
			return Hospital.ready(session, generation) and (not allowed or allowed())
		end
		local board, slots = Hospital.board(puzzle)
		if not board then
			return false, "Waiting for the picture tiles to load"
		end
		local deadline = os.clock() + 12
		local moves, why = Logic.solveCandyPicture(board, function()
			return ready() and puzzle.Parent and os.clock() < deadline and pause(0.01, generation)
		end)
		if not moves then
			return false, why
		end
		if #moves == 0 then
			return true
		end
		local center, normal = slots[5].Position, slots[5].CFrame.LookVector
		local stance = center + Vector3.new(normal.X, 0, normal.Z) * 6
		local moved, reason = approach(stance, generation, puzzle, false, function()
			return ready()
		end)
		if not moved then
			return false, reason
		end
		for step, index in ipairs(moves) do
			if not ready() or not Hospital.same(Hospital.board(puzzle), board) then
				return false, "The picture moved, checking it again"
			end
			local detector = slots[index]:FindFirstChildWhichIsA("ClickDetector")
			local expected = table.clone(board)
			local blank = table.find(expected, 0)
			expected[blank], expected[index] = expected[index], 0
			local accepted = false
			for attempt = 1, 3 do
				if not ready() then
					return false, "Picture interaction paused"
				end
				status("Solving the candy picture", string.format("Tile move %d / %d", step, #moves), App.progress)
				local clicked, problem = Hospital.click(session, detector, generation)
				if not clicked then
					return false, problem
				end
				waitUntil(function()
					return not ready() or not Hospital.same(Hospital.board(puzzle), board)
				end, 2, generation)
				if not ready() then
					return false, "Picture interaction paused"
				end
				local actual = Hospital.board(puzzle)
				if Hospital.same(actual, expected) then
					accepted = true
					break
				end
				if not Hospital.same(actual, board) then
					return false, "The picture moved, checking it again"
				end
				if not pause(0.3 * attempt, generation) then
					return false, "Stopped"
				end
			end
			if not accepted then
				return false, "The game hasn't accepted the tile click yet"
			end
			board = expected
			if not pause(0.2, generation) then
				return false, "Stopped"
			end
		end
		local final = Hospital.board(puzzle)
		if not final then
			return false, "Waiting for the final picture tile"
		end
		local remaining = Logic.solveCandyPicture(final)
		return remaining ~= nil and #remaining == 0, "Checking the finished picture"
	end
	function Hospital.target(session)
		local target = session.target
		if typeof(target) == "Instance" and target:IsDescendantOf(workspace) then
			return target
		end
		local location = session.location
		if typeof(location) == "Instance" and location:IsDescendantOf(workspace) then
			return location
		end
		if type(location) == "string" and location ~= "" then
			local roots = { workspace:FindFirstChild("Rooms"), workspace:FindFirstChild("Misc") }
			for _, root in pairs(roots) do
				if root then
					local found = root:FindFirstChild(location, true)
					if found then
						return found
					end
				end
			end
		end
		return nearest("HalloweenGuideBeam")
	end
	function Hospital.taskPrompt(target)
		if not target then
			return nil
		end
		local candidates = target:IsA("ProximityPrompt") and { target } or target:GetDescendants()
		local parent = target.Parent
		for _ = 1, 3 do
			if not parent or parent == workspace then
				break
			end
			local prompt = parent:FindFirstChildOfClass("ProximityPrompt")
			if prompt then
				table.insert(candidates, prompt)
			end
			if parent:IsA("Model") then
				break
			end
			parent = parent.Parent
		end
		for _, prompt in ipairs(candidates) do
			if prompt:IsA("ProximityPrompt") and prompt.Enabled then
				local text = (prompt.ActionText .. " " .. prompt.ObjectText):lower()
				if
					not text:find("buy", 1, true)
					and not text:find("purchase", 1, true)
					and not text:find("robux", 1, true)
					and not text:find("skip", 1, true)
				then
					return prompt
				end
			end
		end
		return nil
	end
	function Hospital.text(value)
		return tostring(value or "")
			:gsub("<[^>]+>", "")
			:gsub("&amp;", "&")
			:gsub("^%s*[%>%-]*%s*", "")
			:gsub("%s+$", "")
			:lower()
	end
	function Hospital.visible(object)
		if not object or not object.Parent then
			return false
		end
		local node = object
		while node do
			if node:IsA("GuiObject") and not node.Visible then
				return false
			end
			if node:IsA("LayerCollector") and not node.Enabled then
				return false
			end
			node = node.Parent
		end
		return true
	end
	function Hospital.guiTap(object, generation, activated)
		if not active(generation) or not object or not object:IsA("GuiButton") or not Hospital.visible(object) then
			return false
		end
		if type(firesignal) == "function" then
			local signal = activated and object.Activated
				or Input.TouchEnabled and not Input.KeyboardEnabled and object.MouseButton1Up
				or object.MouseButton1Down
			local ok = pcall(firesignal, signal)
			if ok then
				return true
			end
		end
		local p, size = object.AbsolutePosition, object.AbsoluteSize
		local x, y = p.X + size.X / 2, p.Y + size.Y / 2
		local gui = App.player:FindFirstChild("PlayerGui")
		if not gui or size.X <= 0 or size.Y <= 0 then
			return false
		end
		for _, over in ipairs(gui:GetGuiObjectsAtPosition(x, y)) do
			if
				over.Active
				and over ~= object
				and not over:IsDescendantOf(object)
				and not object:IsDescendantOf(over)
			then
				return false
			end
		end
		local ok = pcall(function()
			local manager = game:GetService("VirtualInputManager")
			local inset = game:GetService("GuiService"):GetGuiInset()
			local pressed, problem =
				pcall(manager.SendMouseButtonEvent, manager, x + inset.X, y + inset.Y, 0, true, game, 0)
			pcall(manager.SendMouseButtonEvent, manager, x + inset.X, y + inset.Y, 0, false, game, 0)
			if not pressed then
				error(problem)
			end
		end)
		return ok
	end
	function Hospital.overlap(a, b)
		local p, q, s, t = a.AbsolutePosition, b.AbsolutePosition, a.AbsoluteSize, b.AbsoluteSize
		return p.X < q.X + t.X and p.X + s.X > q.X and p.Y < q.Y + t.Y and p.Y + s.Y > q.Y
	end
	function Hospital.ui(session, generation)
		local gui = App.player:FindFirstChild("PlayerGui")
		if not gui then
			return false
		end
		local options = getPath(gui, "Dialogue", "Frame", "Options")
		if options and Hospital.visible(options) then
			local best, score = nil, -math.huge
			for _, button in ipairs(options:GetChildren()) do
				if button:IsA("GuiButton") and Hospital.visible(button) then
					local text = Hospital.text(button.Text)
					local rank = (
						text == "yes"
						or text == "okay"
						or text == "ok"
						or text == "continue"
						or text == "sure"
					)
							and 5
						or (text:find("help", 1, true) or text:find("accept", 1, true) or text:find("let's", 1, true)) and 3
						or 0
					if
						text:find("buy", 1, true)
						or text:find("robux", 1, true)
						or text:find("leave", 1, true)
						or text:find("no thanks", 1, true)
					then
						rank = -10
					end
					if rank > score or rank == score and best and button.LayoutOrder < best.LayoutOrder then
						best, score = button, rank
					end
				end
			end
			if best then
				status("Talking to the patient", "Choosing: " .. best.Text, App.progress)
				if os.clock() >= (session.nextChoice or 0) then
					session.nextChoice = os.clock() + 1
					if score >= 0 then
						Hospital.guiTap(best, generation, true)
					end
				end
				return true
			end
		end
		local circle = getPath(gui, "Minigame", "Frame")
		if circle and Hospital.visible(circle) and Collection:HasTag(App.player, "InMinigame") then
			local hasCircles = false
			for _, target in ipairs(circle:GetChildren()) do
				if
					(target.Name == "Template" or target.Name == "Danger")
					and target:IsA("GuiButton")
					and Hospital.visible(target)
				then
					hasCircles = true
				end
				if
					target.Name == "Template"
					and target:IsA("GuiButton")
					and Hospital.visible(target)
					and target.AbsoluteSize.X > 8
					and not session.clicked[target]
				then
					session.clicked[target] = true
					if not Hospital.guiTap(target, generation) then
						session.clicked[target] = nil
					end
				end
			end
			local heart = getPath(gui, "HeartbeatMinigameUI", "Frame")
			if hasCircles or heart and Hospital.visible(heart) then
				status("Scanning the patient", "Completing the heartbeat checks", App.progress)
				return true
			end
		end
		local dna = getPath(gui, "DNAMinigame", "Frame")
		if dna and Hospital.visible(dna) then
			local bar, button = dna:FindFirstChild("bar"), dna:FindFirstChild("SkillCheck")
			if bar and button and os.clock() >= (session.dnaAt or 0) then
				for _, goal in ipairs(Collection:GetTagged("DNAGoal")) do
					if
						goal:IsDescendantOf(dna)
						and not goal:GetAttribute("Done")
						and Hospital.visible(goal)
						and Hospital.overlap(goal, bar)
					then
						session.dnaAt = os.clock() + 0.22
						Hospital.guiTap(button, generation)
						break
					end
				end
			end
			status("Testing the DNA sample", "Matching the moving bar to the sample markers", App.progress)
			return true
		end
		local oxygen = getPath(gui, "BarMinigame", "Base")
		if oxygen and Hospital.visible(oxygen) then
			local fill, button, pump =
				getPath(oxygen, "Pump", "Fill"), oxygen:FindFirstChild("SkillCheck"), oxygen:FindFirstChild("Pump")
			if fill and button and button.AutoButtonColor and os.clock() >= (session.oxygenAt or 0) then
				local height = fill.Size.Y.Scale
				local shouldTap = height <= 0.051
				if not shouldTap then
					local inGreen, inRed = false, false
					for _, area in ipairs(pump:GetChildren()) do
						if area:IsA("GuiObject") then
							local low = area.Position.Y.Scale - area.AnchorPoint.Y * area.Size.Y.Scale
							local inside = 1 - height >= low + 0.01 and 1 - height <= low + area.Size.Y.Scale - 0.01
							if area.Name:match("^GreenArea") and inside then
								inGreen = true
							end
							if area.Name:match("^RedArea") and inside then
								inRed = true
							end
						end
					end
					shouldTap = inGreen and not inRed
				end
				if shouldTap then
					session.oxygenAt = os.clock() + 0.18
					Hospital.guiTap(button, generation)
				end
			end
			status("Treating the patient", "Working the oxygen pump", App.progress)
			return true
		end
		return false
	end
	function Hospital.index(session, generation)
		session.objects, session.rooms = {}, {}
		local function add(object)
			if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then
				session.objects[object] = true
			end
			if Collection:HasTag(object, "Room") then
				session.rooms[object] = true
			end
		end
		session.bound.indexAdded = workspace.DescendantAdded:Connect(add)
		session.bound.indexRemoved = workspace.DescendantRemoving:Connect(function(object)
			session.objects[object], session.rooms[object], session.retry[object] = nil, nil, nil
		end)
		for index, object in ipairs(workspace:GetDescendants()) do
			if not active(generation) then
				return false
			end
			add(object)
			if index % 200 == 0 and not pause(0.01, generation) then
				return false
			end
		end
		return true
	end
	function Hospital.room(object)
		local root = workspace:FindFirstChild("Rooms")
		local node = object
		while node and node ~= workspace do
			if node.Parent and node.Parent.Parent == root then
				return node
			end
			node = node.Parent
		end
	end
	function Hospital.desk(object)
		local misc, node = workspace:FindFirstChild("Misc"), object
		while node and node ~= workspace do
			if node.Parent == misc and (node.Name == "CheckIn" or node.Name == "CheckIn2") then
				return node
			end
			node = node.Parent
		end
	end
	function Hospital.held()
		local result = {}
		for _, parent in ipairs({ App.player.Character, App.player:FindFirstChild("Backpack") }) do
			if parent then
				for _, object in ipairs(parent:GetChildren()) do
					if object:IsA("Tool") then
						result[Hospital.text(object:GetAttribute("ItemName") or object.Name)] = object
					end
				end
			end
		end
		return result
	end
	function Hospital.needs(session)
		local needed = {}
		for room in pairs(session.rooms) do
			if room:IsDescendantOf(workspace) and room:GetAttribute("Enabled") ~= false then
				local report = getPath(room, "Minigame", "TV", "Screen", "UI", "Report")
				if report and Hospital.visible(report) then
					local folder = report:FindFirstChild("Folder")
					for _, row in ipairs(folder and folder:GetChildren() or {}) do
						local label = row:FindFirstChild("name")
						if label and Hospital.visible(row) and row:GetAttribute("Done") ~= true then
							local name = Hospital.text(label.Text)
							if #name > 0 then
								needed[name] = room
							end
						end
					end
				end
			end
		end
		return needed
	end
	function Hospital.machine(detector)
		if not detector or detector.Name ~= "Clicker" then
			return nil
		end
		local node = detector.Parent
		while node and node ~= workspace do
			if node.Name == "Computer" and (Hospital.desk(node) or Hospital.room(node)) then
				return node
			end
			node = node.Parent
		end
	end
	function Hospital.busy(machine)
		if not machine or not machine.Parent then
			return false
		end
		local inUse = machine:GetAttribute("InUse")
		if inUse == true or type(inUse) == "number" and inUse > 0 then
			return true
		end
		local frame = getPath(machine, "Screen", "UI", "Frame")
		if frame and Hospital.visible(frame) then
			return true
		end
		local room = Hospital.room(machine)
		local analyzer = getPath(room, "Minigame", "Analyzer", "Screen", "UI", "Frame")
		return analyzer ~= nil and Hospital.visible(analyzer)
	end
	function Hospital.available(machine)
		local owner = machine and machine:GetAttribute("InUse")
		if type(owner) == "number" and owner > 0 and type(Players.GetPlayerByUserId) == "function" then
			local ok, player = pcall(Players.GetPlayerByUserId, Players, owner)
			if ok and player and player ~= App.player then
				return false
			end
		end
		return true
	end
	function Hospital.matches(object, text)
		local name = Hospital.text(object:GetFullName())
		if object:IsA("ProximityPrompt") then
			name ..= " " .. Hospital.text(object.ActionText) .. " " .. Hospital.text(object.ObjectText)
		end
		for _, pair in ipairs({
			{ "clipboard", "clipboard" },
			{ "clipboard", "clip board" },
			{ "computer", "computer" },
			{ "keyboard", "computer" },
			{ "register", "computer" },
			{ "photo", "camera" },
			{ "print", "printer" },
			{ "badge", "badge" },
			{ "nurse", "nurse" },
			{ "report", "monitor" },
			{ "sample", "sample" },
			{ "identity", "identity" },
			{ "bell", "bell" },
			{ "cauldron", "cauldron" },
			{ "camera", "camera" },
		}) do
			if text:find(pair[1], 1, true) and name:find(pair[2], 1, true) then
				return true
			end
		end
		for word in text:gmatch("[%w_]+") do
			if
				#word >= 4
				and word ~= "patient"
				and word ~= "check"
				and word ~= "interact"
				and word ~= "finish"
				and word ~= "complete"
				and word ~= "halloween"
				and name:find(word, 1, true)
			then
				return true
			end
		end
		return false
	end
	function Hospital.pick(session, text)
		local _, root = character()
		if not root then
			return nil
		end
		local target = Hospital.target(session)
		local marked = Hospital.taskPrompt(target)
		text = Hospital.text(text)
		if Hospital.pictureRequested(session, getPath(workspace, "Halloween", "Puzzle")) then
			return nil
		end
		local needed, held = Hospital.needs(session), Hospital.held()
		local sampler, sample, results
		for name, tool in pairs(held) do
			if name:find("sampler", 1, true) then
				sampler = tool
			elseif name:find("sample", 1, true) then
				sample = tool
			end
			if name:find("result", 1, true) or name:find("report", 1, true) then
				results = tool
			end
		end
		local sampleTask = Hospital.text(text):find("sample", 1, true) or Hospital.text(text):find("dna", 1, true)
		if not sampleTask then
			for prompt in pairs(session.objects) do
				if
					prompt.Parent
					and prompt:IsA("ProximityPrompt")
					and prompt.Enabled
					and Hospital.room(prompt)
					and Hospital.text(prompt.ActionText):find("sample", 1, true)
				then
					sampleTask = true
					break
				end
			end
		end
		local best, bestScore, bestItem
		for object in pairs(session.objects) do
			local eligible, score, item = false, 0, nil
			if object:IsDescendantOf(workspace) and os.clock() >= (session.retry[object] or 0) then
				if object:IsA("ProximityPrompt") and object.Enabled then
					local action = Hospital.text(object.ActionText)
					local desk, room = Hospital.desk(object), Hospital.room(object)
					local matched = Hospital.matches(object, text)
					if object == marked then
						eligible, score = true, 250
					end
					if desk then
						if action == "register" then
							eligible, score = true, 100
						end
						if action == "take photo" then
							eligible, score = true, 110
						end
						if action == "print badge" then
							eligible, score = true, 120
						end
						if action == "take" then
							eligible, score = true, 130
						end
					end
					if room and action ~= "inspect" and action ~= "" and action ~= "talk" then
						if action == "apply treatment" then
							for name, owner in pairs(needed) do
								if owner == room and held[name] then
									item = held[name]
									break
								end
							end
							eligible, score = item ~= nil, 180
						elseif
							action == "prepare patient"
							or action:match("^begin")
							or action == "process results"
							or action == "set up"
							or action == "turn on"
							or action == "collect"
							or action == "print badge"
							or action:find("scan", 1, true)
							or action:find("analy", 1, true)
						then
							eligible, score = true, 140
						end
					end
					if
						action == "inspect"
						and not (session.inspected and session.inspected[object])
						and (
							object == marked
							or matched
							or room and (text:find("clipboard", 1, true) or text:find("report", 1, true))
						)
					then
						eligible, score = true, 230
					end
					if action == "inspect" and session.inspected and session.inspected[object] then
						eligible = false
					end
					if matched and action ~= "" and action ~= "inspect" then
						eligible, score = true, math.max(score, 210)
					end
					if action == "take dna sampler" and sampleTask and not sampler and not sample then
						eligible, score = true, 175
					end
					if action == "take sample" or action == "collect sample" then
						eligible, score, item = sampler ~= nil, 180, sampler
					end
					if action == "analyze sample" or action == "insert sample" then
						eligible, score, item = sample ~= nil, 180, sample
					end
					if action == "process results" and results then
						item = results
					end
					if needed[action] and not held[action] then
						eligible, score = true, 170
					end
					if
						action == "talk"
						and (
							object:IsDescendantOf(workspace:FindFirstChild("NPCs") or object)
							or object.Parent == getPath(workspace, "Misc", "Nurse")
						)
					then
						eligible, score = true, 70
					end
					local fullText = action .. " " .. Hospital.text(object.ObjectText)
					if
						action:find("give", 1, true)
							and (fullText:find("badge", 1, true) or fullText:find("card", 1, true))
						or action == "check in"
							and object:IsDescendantOf(workspace:FindFirstChild("NPCs") or object)
					then
						for name, tool in pairs(held) do
							if name:find("badge", 1, true) or name:find("card", 1, true) then
								item = tool
								break
							end
						end
						eligible, score = item ~= nil, 190
					end
					if
						action:find("buy", 1, true)
						or action:find("purchase", 1, true)
						or action:find("robux", 1, true)
						or action:find("skip", 1, true)
					then
						eligible = false
					end
					if desk and not Hospital.available(object.Parent) then
						eligible = false
					end
					if room and room:GetAttribute("Enabled") == false then
						eligible = false
					end
					local scope = session.scope
					if
						eligible
						and scope
						and scope.Parent
						and not target
						and (room or desk)
						and (room or desk) ~= scope
					then
						eligible = false
					end
					if
						eligible
						and not object.Parent:IsDescendantOf(workspace:FindFirstChild("Halloween") or object)
						and (object == marked or matched)
					then
						score = math.max(score, 250)
					end
					if eligible and object == marked then
						score = math.max(score, 350)
					end
				elseif object:IsA("ClickDetector") and object.MaxActivationDistance > 0 then
					local machine = Hospital.machine(object)
					if
						machine
						and Hospital.busy(machine)
						and Hospital.available(machine)
						and os.clock() >= (session.retry[machine] or 0)
					then
						eligible, score = true, 220
					end
					if
						not machine
						and target
						and Hospital.related(object.Parent, target)
						and not Hospital.related(object, getPath(workspace, "Halloween", "Puzzle"))
					then
						eligible, score = true, 245
					end
					if
						session.scope
						and machine
						and not target
						and (Hospital.room(machine) or Hospital.desk(machine)) ~= session.scope
					then
						eligible = false
					end
				end
				if eligible then
					local point = EventInput.point(object.Parent)
					if point then
						score -= math.min((point - root.Position).Magnitude, 1000) * 0.02
						if
							object.Parent
							and Hospital.text(object.Parent.Name):find("visitor", 1, true)
							and Hospital.text(text):find("patient", 1, true)
						then
							score -= 5
						end
						if not bestScore or score > bestScore then
							best, bestScore, bestItem = object, score, item
						end
					end
				end
			end
		end
		if not best and session.scope then
			session.scopeEmptyAt = session.scopeEmptyAt or os.clock()
			if os.clock() - session.scopeEmptyAt > 4 then
				session.scope, session.scopeEmptyAt = nil, nil
			end
		elseif best then
			session.scopeEmptyAt = nil
		end
		return best, bestItem
	end
	function Hospital.hold(session, prompt, generation, allowed)
		local triggered, connection = false, nil
		if prompt.Triggered then
			local ok, result = pcall(prompt.Triggered.Connect, prompt.Triggered, function(player)
				if player == nil or player == App.player then
					triggered = true
				end
			end)
			if ok then
				connection = result
			end
		end
		local before, revision = prompt.ActionText, session.revision
		local function changed()
			return triggered
				or not prompt.Parent
				or not prompt.Enabled
				or prompt.ActionText ~= before
				or session.revision ~= revision
				or Hospital.busy(prompt.Parent)
		end
		local ok, why = EventInput.hold(session, prompt, generation, allowed, { keepLook = true, accepted = changed })
		if active(generation) and allowed() and not changed() and type(fireproximityprompt) == "function" then
			ok, why = call("Hospital prompt", function()
				if active(generation) and allowed() and not changed() then
					return fireproximityprompt(prompt, prompt.HoldDuration)
				end
				return false
			end, prompt.HoldDuration + 2, generation)
			ok = ok and why ~= false
		end
		if connection then
			pcall(connection.Disconnect, connection)
		end
		if not active(generation) then
			EventInput.release(session)
			return false, "Stopped"
		end
		return changed() or ok, why
	end
	function Hospital.action(session, object, item, generation)
		local model, root, humanoid = character()
		if not Hospital.ready(session, generation) or not object.Parent then
			return false
		end
		local point = EventInput.point(object.Parent)
		if not point then
			return false
		end
		local prompt = object:IsA("ProximityPrompt")
		local function allowed()
			return Hospital.ready(session, generation)
				and object:IsDescendantOf(workspace)
				and (not prompt or object.Enabled)
		end
		if (root.Position - point).Magnitude > math.max(2, object.MaxActivationDistance * 0.8) then
			if not approach(point, generation, nil, false, allowed) then
				return false
			end
		end
		if not allowed() then
			return false
		end
		if item and item.Parent ~= model then
			session.previousTool = session.previousTool or model:FindFirstChildOfClass("Tool")
			if not pcall(humanoid.EquipTool, humanoid, item) or not pause(0.1, generation) or not allowed() then
				return false
			end
			session.equipped = item
		end
		local action = prompt and object.ActionText or "Typing at the computer"
		status("Animal Hospital", action, App.progress)
		local before = prompt and object.ActionText
		local revision = session.revision
		local success = prompt and Hospital.hold(session, object, generation, allowed)
			or not prompt and Hospital.click(session, object, generation)
		if not active(generation) then
			return false
		end
		if success then
			local machine = prompt and object.Parent or Hospital.machine(object)
			machine = machine or object.Parent
			session.scope = Hospital.room(object) or Hospital.desk(object) or session.scope
			session.work = {
				object = object,
				machine = machine,
				prompt = prompt,
				started = os.clock(),
				before = before or action,
				seenBusy = Hospital.busy(machine),
				revision = revision,
				inspect = prompt and Hospital.text(before) == "inspect",
				target = Hospital.target(session),
			}
		else
			EventInput.release(session)
		end
		session.retry[object] = os.clock() + (success and (prompt and 1.5 or 0.12) or 3)
		return success
	end
	function Hospital.working(session, generation)
		local work = session.work
		if not work then
			return false
		end
		local function finish()
			EventInput.release(session)
			session.work = nil
		end
		if not work.object.Parent or not work.machine.Parent then
			finish()
			return false
		end
		local inspected, knowsInspection = Hospital.inspecting(session)
		if session.revision ~= work.revision and work.revision ~= nil and not inspected then
			finish()
			return false
		end
		local busy = Hospital.busy(work.machine)
		if busy then
			work.seenBusy = true
		end
		if busy and not Hospital.available(work.machine) then
			finish()
			return false
		end
		if busy and os.clock() - work.started >= 60 then
			session.retry[work.object], session.retry[work.machine] = os.clock() + 15, os.clock() + 15
			finish()
			return false
		end
		if busy then
			local detector = work.machine:FindFirstChild("Clicker", true)
			if not detector then
				local computer = getPath(Hospital.room(work.machine), "Minigame", "Computer")
				detector = computer and computer:FindFirstChild("Clicker", true)
			end
			if
				detector
				and detector:IsA("ClickDetector")
				and os.clock() >= (session.retry[detector] or 0)
				and Hospital.ready(session, generation)
			then
				session.retry[detector] = os.clock() + 0.15
				Hospital.click(session, detector, generation)
			end
			status("Finishing " .. tostring(work.before), "Waiting for the station to finish", App.progress)
			return true
		end
		if work.inspect then
			if inspected then
				work.seenInspect = true
			end
			if os.clock() - work.started < 1 then
				return true
			end
			if knowsInspection and not inspected and work.seenInspect then
				session.inspected = session.inspected or setmetatable({}, { __mode = "k" })
				session.inspected[work.object] = true
				finish()
				return false
			end
			if inspected or not knowsInspection then
				if os.clock() >= (work.dismissAt or 0) then
					work.dismissAt = os.clock() + 1.5
					work.dismissed = Hospital.dismissInspect(session, generation) or work.dismissed
				end
				if os.clock() - work.started > 15 then
					session.problem = "Close the inspection to continue"
				end
				if not knowsInspection and work.dismissed and not work.object.Enabled then
					session.inspected = session.inspected or setmetatable({}, { __mode = "k" })
					session.inspected[work.object] = true
					finish()
					return false
				end
				return true
			end
			if os.clock() - work.started > 3 then
				finish()
				return false
			end
			return true
		end
		if
			work.seenBusy
			or work.prompt and (not work.object.Enabled or work.object.ActionText ~= work.before)
			or os.clock() - work.started > 2
		then
			finish()
			return false
		end
		return true
	end
	function Hospital.run(generation)
		if verify(current) == true then
			return true, "Animal Hospital's Hollow badge is already earned"
		end
		local session = {
			model = nil,
			bound = {},
			nextPuzzle = 0,
			nextPrompt = 0,
			badgeAt = 0,
			retry = {},
			clicked = setmetatable({}, { __mode = "k" }),
		}
		table.insert(App.cleanups, function()
			for _, connection in pairs(session.bound) do
				connection:Disconnect()
			end
			EventInput.release(session)
			local model, _, humanoid = character()
			if session.equipped and model and session.equipped.Parent == model then
				if session.previousTool and session.previousTool.Parent == App.player:FindFirstChild("Backpack") then
					pcall(humanoid.EquipTool, humanoid, session.previousTool)
				else
					pcall(humanoid.UnequipTools, humanoid)
				end
			end
		end)
		Hospital.bind(session)
		if not Hospital.index(session, generation) then
			return false, "Stopped"
		end
		local libObject = getPath(Storage, "Lib")
		if libObject then
			session.lib = module(libObject, generation)
		end
		local deadline = os.clock() + 3600
		while active(generation) and os.clock() < deadline do
			if os.clock() >= session.badgeAt then
				session.badgeAt = os.clock() + 15
				if verify(current, true) == true then
					return true, "Animal Hospital's Hollow badge is earned"
				end
			end
			Hospital.bind(session)
			local model = character()
			if model ~= session.model then
				EventInput.release(session)
				session.model, session.work, session.equipped, session.previousTool = model, nil, nil, nil
				session.scope, session.scopeEmptyAt, session.inspected = nil, nil, nil
			end
			local shift = tonumber(Players:GetAttribute("Night"))
			local prefix = shift and "Shift " .. tostring(shift) .. " | " or ""
			local text = Hospital.objective(session)
			status("Animal Hospital", prefix .. tostring(text), App.progress)
			if Hospital.ui(session, generation) then
				if not pause(0.03, generation) then
					break
				end
				continue
			end
			if session.work and Hospital.working(session, generation) then
				if session.problem then
					return false, session.problem
				end
				if not pause(0.05, generation) then
					break
				end
				continue
			end
			if model and Hospital.ready(session, generation) then
				local puzzle = getPath(workspace, "Halloween", "Puzzle")
				local board = Hospital.pictureRequested(session, puzzle) and Hospital.board(puzzle)
				local object, item = Hospital.pick(session, text)
				if object then
					Hospital.action(session, object, item, generation)
				elseif board and os.clock() >= session.nextPuzzle then
					session.nextPuzzle = os.clock() + 8
					local solved, reason = Hospital.solve(session, puzzle, generation, function()
						return Hospital.pictureRequested(session, puzzle)
					end)
					EventInput.release(session)
					if not solved and active(generation) then
						status("Candy picture", tostring(reason), App.progress)
					end
					pause(1, generation)
				else
					status(
						"Animal Hospital",
						prefix .. tostring(text) .. "\nChecking for the next patient, card, test or treatment.",
						App.progress
					)
				end
			end
			if not pause(0.15, generation) then
				break
			end
		end
		return false, active(generation) and "The Hospital helper reached its time limit" or "Stopped"
	end
	App.hospitalApi = Hospital
	runners.hospital = Hospital.run
end
do
	local Dti = {}
	function Dti.remote(name)
		return getPath(Storage, "RemoteEvents", name)
	end
	function Dti.point(value)
		if typeof(value) == "CFrame" then
			return value.Position
		elseif typeof(value) == "Vector3" then
			return value
		elseif typeof(value) == "Instance" then
			return EventInput.point(value)
		end
		return nil
	end
	function Dti.visible(object)
		if not object then
			return false
		end
		local parent = object
		while parent do
			if parent:IsA("GuiObject") and not parent.Visible or parent:IsA("ScreenGui") and not parent.Enabled then
				return false
			end
			parent = parent.Parent
		end
		return true
	end
	function Dti.boat()
		return getPath(workspace, "Chapter 1", "RiverOfStyx", "boat")
	end
	function Dti.ready(session, generation)
		local model, root, humanoid = character()
		local camera = workspace.CurrentCamera
		local cover = getPath(App.player, "PlayerGui", "QuestBlackout", "Frame")
		return active(generation)
			and not session.closed
			and model == session.model
			and root
			and not root.Anchored
			and humanoid.Health > 0
			and not App.cameraBusy
			and not (camera and camera.CameraType == Enum.CameraType.Scriptable)
			and not (Dti.visible(cover) and cover.BackgroundTransparency < 0.1)
	end
	function Dti.release(session)
		EventInput.release(session)
		if session.soulHolding then
			fire(Dti.remote("HoldSoulPrompt"), session.soulHolding, false)
			session.soulHolding = nil
		end
	end
	function Dti.clear(session)
		if session.closed then
			return
		end
		session.closed = true
		for _, connection in pairs(session.bound) do
			pcall(connection.Disconnect, connection)
		end
		table.clear(session.bound)
		Dti.release(session)
	end
	function Dti.receive(session, name, a, b, c)
		if name == "HoldingFuel" and type(a) == "boolean" then
			session.holding = a
		elseif name == "UpdateCurrentFuel" and type(a) == "number" then
			session.fuel = a
			session.maxFuel = math.max(session.maxFuel or 0, a)
		elseif name == "UpdateCurrentFuelStorage" and type(a) == "number" then
			session.storage = a
		elseif name == "UpdateDistance" then
			session.sailing = type(a) == "number"
			if type(a) == "number" and a ~= session.distance then
				session.distance, session.distanceGoal = a, b
				session.progressAt = os.clock()
			end
		elseif name == "UpdateCollectedOrbs" then
			session.collecting = type(a) == "number"
			if type(a) == "number" then
				if a ~= session.orbs then
					session.progressAt = os.clock()
				end
				session.orbs, session.orbGoal = a, b
			end
		elseif name == "CollectedOrb" then
			if a then
				session.collected[a] = true
			end
			session.progressAt = os.clock()
		elseif name == "GuidePath" then
			session.guideObserved = true
			session.guide, session.guideIndex = {}, 1
			if type(a) == "table" then
				for _, value in ipairs(a) do
					local point = Dti.point(value)
					if point then
						table.insert(session.guide, point)
					end
					if #session.guide >= 256 then
						break
					end
				end
			end
			session.progressAt = os.clock()
		elseif name == "BoatEndSequence" then
			session.boatEnded = true
			session.progressAt = os.clock()
		elseif name == "EndBoatEndSequence" then
			session.boatEnded = true
			session.progressAt = os.clock()
		elseif name == "EndSistersScene" then
			session.sistersEnded = true
			session.progressAt = os.clock()
		elseif name == "StartSistersScene" then
			session.sistersStarted = true
			session.progressAt = os.clock()
		elseif name == "QuestBlackout" then
			Dti.release(session)
			session.progressAt = os.clock()
		elseif name == "SoulWhacked" then
			if a then
				session.whacked[a] = os.clock()
			end
			session.progressAt = os.clock()
		elseif name == "MoveBoat" then
			local point = Dti.point(b)
			if point and (not session.boatPoint or (point - session.boatPoint).Magnitude > 2) then
				session.boatPoint, session.progressAt = point, os.clock()
			end
		end
	end
	function Dti.bind(session, generation)
		if os.clock() < (session.bindAt or 0) then
			return
		end
		session.bindAt = os.clock() + 1
		for _, name in ipairs({
			"HoldingFuel",
			"UpdateCurrentFuel",
			"UpdateCurrentFuelStorage",
			"UpdateDistance",
			"UpdateCollectedOrbs",
			"CollectedOrb",
			"GuidePath",
			"BoatEndSequence",
			"EndBoatEndSequence",
			"StartSistersScene",
			"EndSistersScene",
			"QuestBlackout",
			"SoulWhacked",
			"MoveBoat",
		}) do
			local remote = Dti.remote(name)
			local prior = session.remotes[name]
			if prior ~= remote then
				if prior and session.bound[prior] then
					session.bound[prior]:Disconnect()
					session.bound[prior] = nil
				end
				session.remotes[name] = remote
			end
			if
				remote
				and not session.bound[remote]
				and (remote:IsA("RemoteEvent") or remote:IsA("UnreliableRemoteEvent"))
			then
				session.bound[remote] = remote.OnClientEvent:Connect(function(...)
					if active(generation) and not session.closed then
						local ok, why = pcall(Dti.receive, session, name, ...)
						if not ok then
							session.note = tostring(why):sub(1, 150)
						end
					end
				end)
			end
		end
	end
	function Dti.read(session)
		local gui = App.player:FindFirstChild("PlayerGui")
		for _, row in ipairs({ { "DistanceLabel", "distance", "distanceGoal" }, { "OrbsLabel", "orbs", "orbGoal" } }) do
			local label = getPath(gui, "BoatGui", row[1])
			if Dti.visible(label) and label:IsA("TextLabel") then
				local amount, goal = label.Text:match("(%d+)%s*/%s*(%d+)")
				amount, goal = tonumber(amount), tonumber(goal)
				if amount and goal and goal > 0 then
					if session[row[2]] ~= amount then
						session.progressAt = os.clock()
					end
					session[row[2]], session[row[3]] = amount, goal
					if row[2] == "orbs" then
						session.collecting = true
					end
				end
			end
		end
		if os.clock() >= (session.holdingAt or 0) then
			session.holdingAt = os.clock() + 2
			local query = getPath(App.player, "PlayerScripts", "QuestEvents", "IsHoldingFuel")
			if query and query:IsA("BindableFunction") then
				local ok, value = call(query, function()
					return query:Invoke()
				end, 0.5, session.generation)
				if ok and type(value) == "boolean" then
					session.holding = value
				end
			end
		end
	end
	function Dti.skip(session)
		if os.clock() < (session.skipAt or 0) then
			return
		end
		local gui = App.player:FindFirstChild("PlayerGui")
		local dialogue = getPath(gui, "Dialogue2", "SkipLabel")
		if Dti.visible(dialogue) and dialogue.Text:lower():find("vote skip", 1, true) then
			if fire(Dti.remote("SkipSimpleDialogue")) then
				session.skipAt = os.clock() + 2
			end
		end
		local skip = getPath(gui, "Dialog", "SkipButton")
		if Dti.visible(skip) and skip:IsA("GuiButton") then
			if fire(Dti.remote("Skip_Cutscene_Remote")) then
				session.skipAt = os.clock() + 2
			end
		end
	end
	function Dti.move(session, point, generation, boat, allowed, ignore)
		local model, root, humanoid = character()
		local function ready()
			return Dti.ready(session, generation) and App.player.Character == model and (not allowed or allowed())
		end
		if typeof(point) ~= "Vector3" or not ready() or point.Y <= workspace.FallenPartsDestroyHeight + 40 then
			return false
		end
		if (point - root.Position).Magnitude > 70 and os.clock() >= (session.streamAt or 0) then
			session.streamAt = os.clock() + 2
