		if not hit or hit.Normal.Y < 0.6 or hit.Position.Y <= workspace.FallenPartsDestroyHeight + 40 then
			return false
		end
		local destination = hit.Position + Vector3.new(0, math.max(2.6, humanoid.HipHeight + root.Size.Y / 2), 0)
		if not ready() or (destination - point).Magnitude > 24 then
			return false
		end
		if (destination - root.Position).Magnitude > 1.5 then
			root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
			local target = CFrame.new(destination) * root.CFrame.Rotation
			model:PivotTo(target * root.CFrame:ToObjectSpace(model:GetPivot()))
		end
		return pause(0.1, generation) and ready()
	end
	function Dti.prompts(tag)
		local out = {}
		for _, object in ipairs(Collection:GetTagged(tag)) do
			if object:IsA("ProximityPrompt") and object.Enabled and object:IsDescendantOf(workspace) then
				table.insert(out, object)
			end
		end
		return out
	end
	function Dti.use(session, prompt, role, generation, soul)
		if os.clock() < (session.retry[prompt] or 0) then
			return false
		end
		local point = EventInput.point(prompt.Parent)
		local occupied = soul and soul:GetAttribute("Occupied")
		local holding, fuel = session.holding, session.fuel
		local started = os.clock()
		local function allowed()
			return Dti.ready(session, generation)
				and prompt:IsDescendantOf(workspace)
				and prompt.Enabled
				and (not soul or soul:GetAttribute("Occupied") == occupied)
		end
		local function accepted()
			if not prompt.Parent or not prompt.Enabled then
				return true
			end
			if role == "soul" then
				return soul:GetAttribute("Occupied") ~= occupied or (session.whacked[soul] or -1) > started
			end
			if role == "take" then
				return session.holding == true and holding ~= true
			end
			return session.holding == false and holding ~= false or session.fuel and fuel and session.fuel > fuel
		end
		local _, root = character()
		if not point or not root or not allowed() then
			return false
		end
		if (root.Position - point).Magnitude > math.max(2, prompt.MaxActivationDistance - 1) then
			local boat = Dti.boat()
			local spawn = boat and boat:FindFirstChild("SpawnAtt")
			local center = spawn and EventInput.point(spawn)
			local destination = point
			if center then
				local inside = Vector3.new(center.X - point.X, 0, center.Z - point.Z)
				if inside.Magnitude > 0.1 then
					destination += inside.Unit * math.min(2.5, prompt.MaxActivationDistance * 0.4, inside.Magnitude)
				end
			end
			if not Dti.move(session, destination, generation, boat, allowed) then
				return false
			end
		end
		session.retry[prompt] = started + 1
		local nativeName = role == "take" and "TriggerFuelPrompt" or role == "add" and "TriggerLanternPrompt"
		local native = nativeName and Dti.remote(nativeName)
		if native and native:IsA("RemoteEvent") then
			if not allowed() or (root.Position - point).Magnitude > prompt.MaxActivationDistance then
				return false
			end
			local sent = fire(native)
			if sent then
				waitUntil(function()
					return accepted() or not Dti.ready(session, generation)
				end, 2.5, generation)
			end
			if active(generation) and accepted() then
				session.progressAt = os.clock()
				return true
			end
			session.retry[prompt] = os.clock() + 2
			return false
		end
		session.soulHolding = soul
		EventInput.hold(session, prompt, generation, allowed, { accepted = accepted })
		session.soulHolding = nil
		local confirmed = waitUntil(function()
			return accepted() or not Dti.ready(session, generation)
		end, 1.2, generation)
		if confirmed and Dti.ready(session, generation) then
			session.progressAt = os.clock()
			return true
		end
		if not allowed() then
			return false
		end
		if type(fireproximityprompt) == "function" then
			session.soulHolding = soul
			call(prompt, function()
				if allowed() then
					return fireproximityprompt(prompt, prompt.HoldDuration)
				end
				return false
			end, prompt.HoldDuration + 1, generation)
			session.soulHolding = nil
			if waitUntil(accepted, 1, generation) then
				session.progressAt = os.clock()
				return true
			end
		end
		session.retry[prompt] = os.clock() + 2
		return false
	end
	function Dti.orb(session)
		local _, root = character()
		local best, distance
		for _, object in ipairs(Collection:GetTagged("SpawnedOrb")) do
			if
				object:IsA("BasePart")
				and object:IsDescendantOf(workspace)
				and not session.collected[object]
				and os.clock() >= (session.retry[object] or 0)
				and root
			then
				local range = (object.Position - root.Position).Magnitude
				if not distance or range < distance then
					best, distance = object, range
				end
			end
		end
		return best
	end
	function Dti.collect(session, generation, orb)
		status(
			"Gathering lantern fuel",
			string.format("%d / %d fuel orbs", session.orbs or 0, session.orbGoal or 10),
			0.25
		)
		if orb then
			local before = session.orbs
			local function available()
				return orb:IsDescendantOf(workspace)
					and not session.collected[orb]
					and session.collecting ~= false
					and not session.boatEnded
			end
			if Dti.move(session, orb.Position, generation, nil, available, orb) then
				local credited = waitUntil(function()
					return not available() or session.orbs ~= before
				end, 1.5, generation)
				if credited then
					session.progressAt = os.clock()
				else
					session.retry[orb] = os.clock() + 2
				end
			else
				session.retry[orb] = os.clock() + 1
			end
			return
		end
		local spawns = getPath(workspace, "Chapter 1", "Refuel1", "PotentialOrbSpawns")
		local _, root = character()
		local best, cost
		for _, spawn in ipairs(spawns and spawns:GetChildren() or {}) do
			local point = EventInput.point(spawn)
			if point and root then
				local score = (point - root.Position).Magnitude + (session.explored[spawn] and 10000 or 0)
				if not cost or score < cost then
					best, cost = spawn, score
				end
			end
		end
		if best and os.clock() >= (session.exploreAt or 0) then
			session.exploreAt = os.clock() + 1
			if cost >= 10000 then
				table.clear(session.explored)
			end
			if Dti.move(session, EventInput.point(best), generation) then
				session.explored[best] = true
			end
		end
	end
	function Dti.board(session, generation)
		local boat = Dti.boat()
		local spawn = boat and (boat:FindFirstChild("SpawnAtt") or boat:FindFirstChild("SpawnLocation"))
		local point = spawn and EventInput.point(spawn)
		local _, root = character()
		if not point or not root then
			return false
		end
		local params = RaycastParams.new()
		params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Include, { boat }
		params.RespectCanCollide = true
		local floor = workspace:Raycast(root.Position, Vector3.new(0, -8, 0), params)
		if floor and (root.Position - point).Magnitude < 22 then
			return true
		end
		return Dti.move(session, point, generation, boat)
	end
	function Dti.follow(session, generation)
		local _, root = character()
		if session.boatEnded and not session.guideObserved and not session.guide then
			local folder = getPath(workspace, "SoulField", "GuideNodes")
			local nodes = {}
			for _, object in ipairs(folder and folder:GetChildren() or {}) do
				local order = tonumber(object.Name:match("^Node(%d+)$"))
				local point = EventInput.point(object)
				if order and point then
					table.insert(nodes, { order = order, point = point })
				end
			end
			table.sort(nodes, function(a, b)
				return a.order < b.order
			end)
			if #nodes > 0 and root then
				local closest, distance = 1, math.huge
				session.guide = {}
				for i, item in ipairs(nodes) do
					table.insert(session.guide, item.point)
					local range = (root.Position - item.point).Magnitude
					if range < distance then
						closest, distance = i, range
					end
				end
				session.guideIndex = closest
			end
		end
		local guide = session.guide
		local index = session.guideIndex or 1
		local point = guide and guide[index]
		if point and root then
			status("Following the lantern path", string.format("Path %d / %d", index, #guide), 0.8)
			if (point - root.Position).Magnitude < 10 then
				session.guideIndex, session.progressAt = index + 1, os.clock()
			else
				Dti.move(session, point, generation, nil, function()
					return session.guide == guide
				end)
			end
			return true
		end
		if not session.boatEnded then
			return false
		end
		if session.sistersStarted then
			status("The sisters", "Waiting for the chapter reward", 0.95)
			return true
		end
		local trigger = getPath(workspace, "SistersInteraction", "MoraiCutsceneTrigger")
		if trigger and trigger:IsA("BasePart") then
			status("Reaching the sisters", "Following the path to the chapter ending", 0.9)
			if os.clock() >= (session.endingAt or 0) then
				session.endingAt = os.clock() + 2
				Dti.move(session, trigger.Position, generation)
			end
		else
			status("Following the lantern path", "Waiting for the next part of the path", 0.8)
		end
		return true
	end
	function Dti.step(session, generation)
		Dti.bind(session, generation)
		local model = character()
		if model ~= session.model then
			Dti.release(session)
			session.model, session.holding, session.holdingAt = model, nil, 0
			session.retry = setmetatable({}, { __mode = "k" })
		end
		Dti.read(session)
		Dti.skip(session)
		if not model then
			status("Dark King Chapter 1", "Revive or rejoin to keep going", App.progress)
			return
		end
		if workspace:GetAttribute("Started") == false then
			status("Dark King Chapter 1", "Waiting for the other players", 0)
			return
		end
		if not Dti.ready(session, generation) then
			Dti.release(session)
			status("Dark King Chapter 1", "Waiting for the scene to finish", App.progress)
			return
		end
		if session.sistersEnded then
			status("Chapter 1 finished", "Waiting for the saved badge", 0.98)
			return
		end
		local orb = Dti.orb(session)
		if
			orb and session.collecting ~= false
			or session.collecting and (session.orbs or 0) < (session.orbGoal or 10)
		then
			Dti.collect(session, generation, orb)
			return
		end
		if Dti.follow(session, generation) then
			return
		end
		local lantern, fuel = Dti.prompts("LanternPrompt")[1], Dti.prompts("FuelPrompt")[1]
		if session.holding == true or lantern and session.holding == nil then
			status("Feeding the lantern", "Adding the fuel orb", 0.4)
			if lantern then
				Dti.use(session, lantern, "add", generation)
			else
				Dti.board(session, generation)
			end
			return
		end
		local soul, prompt, deadline
		for _, attachment in ipairs(Collection:GetTagged("SoulAtt")) do
			local occupied = attachment:GetAttribute("Occupied")
			local interaction = attachment:FindFirstChildWhichIsA("ProximityPrompt")
			if
				type(occupied) == "number"
				and interaction
				and interaction.Enabled
				and attachment:IsDescendantOf(workspace)
				and os.clock() >= (session.retry[interaction] or 0)
				and (not deadline or occupied < deadline)
			then
				soul, prompt, deadline = attachment, interaction, occupied
			end
		end
		if prompt then
			status("Clearing a soul", "Keeping it away from the boat", 0.45)
			Dti.use(session, prompt, "soul", generation, soul)
			return
		end
		local lowFuel = session.fuel and session.fuel <= (session.maxFuel or session.fuel) * 0.35
		local unknownFuel = session.fuel == nil and os.clock() >= (session.fuelTryAt or 0)
		if fuel and session.storage ~= 0 and (lowFuel or unknownFuel) then
			session.fuelTryAt = os.clock() + 12
			status("Picking up lantern fuel", "Getting an orb from the boat", 0.35)
			Dti.use(session, fuel, "take", generation)
			return
		end
		local boat = Dti.boat()
		local finish = getPath(workspace, "Chapter 1", "RiverOfStyx", "FinalBoatCF")
		local boatPoint, finishPoint = boat and EventInput.point(boat), finish and EventInput.point(finish)
		if boatPoint and finishPoint and (boatPoint - finishPoint).Magnitude < 20 then
			session.boatEnded = true
			Dti.follow(session, generation)
			return
		end
		local aboard = Dti.board(session, generation)
		status(
			aboard and "Crossing the river" or "Boarding the boat",
			session.distance
					and string.format(
						"%.0f / %.0f traveled",
						session.distance,
						session.distanceGoal or session.distance
					)
				or "Staying with the Ferryman",
			0.15
		)
	end
	function Dti.enter(generation)
		if game.PlaceId == current.questPlace then
			status("Joining Chapter 1", "Joining the river quest", 0.05)
			prepareTravel(current.chapterPlace, true)
			local ok, why = pcall(function()
				Teleport:Teleport(current.chapterPlace, App.player)
			end)
			if not ok then
				return false, "Couldn't join Chapter 1. Use its elevator, then press Start inside."
			end
			pause(20, generation)
			return false, "Try the Chapter 1 elevator if you haven't joined yet."
		end
		status("Entering the Dark King quest", "Finding the H26 quest portal", 0.1)
		local portal = waitUntil(function()
			return nearest("EventPortal", function(part)
				return part:GetAttribute("Type") == "H26"
			end)
		end, 45, generation)
		local remote = getPath(Storage, "RemoteEvents", "EVENT_TELEPORT")
		if not portal or not remote then
			return false, "The Halloween quest portal hasn't loaded. Try Start again in a DTI lobby."
		end
		local trigger = portal:FindFirstChild("Trigger")
		if not trigger or not trigger:IsA("BasePart") then
			return false, "The quest portal's entrance is still loading"
		end
		local moved, why = approach(trigger.Position, generation, trigger)
		if not moved then
			return false, why
		end
		if not active(generation) or not portal:IsDescendantOf(workspace) then
			return false, "Stopped"
		end
		prepareTravel(current.questPlace, true)
		local sent, problem = fire(remote, portal)
		if not sent then
			return false, tostring(problem)
		end
		status("Joining the Dark King quest", "The helper will continue in Chapter 1", 0.15)
		pause(20, generation)
		return false, "Try DTI's portal again if you didn't join."
	end
	function Dti.run(generation)
		if verify(current, true) == true then
			return true, "DTI's Hollow badge is already earned"
		end
		if not active(generation) then
			return false, "Stopped"
		end
		if game.PlaceId ~= current.chapterPlace then
			return Dti.enter(generation)
		end
		local session = {
			generation = generation,
			bound = {},
			remotes = {},
			progressAt = os.clock(),
			badgeAt = 0,
			retry = setmetatable({}, { __mode = "k" }),
			collected = setmetatable({}, { __mode = "k" }),
			whacked = setmetatable({}, { __mode = "k" }),
			explored = setmetatable({}, { __mode = "k" }),
		}
		table.insert(App.cleanups, function()
			Dti.clear(session)
		end)
		local deadline = os.clock() + 5400
		while active(generation) and os.clock() < deadline do
			if os.clock() >= session.badgeAt then
				session.badgeAt = os.clock() + (session.sistersEnded and 3 or 15)
				if verify(current, true) == true then
					return true, "DTI's Chapter 1 badge earned"
				end
			end
			Dti.step(session, generation)
			if os.clock() - session.progressAt > 360 then
				return false, "No quest progress for a while. Check the current task, then try Start again."
			end
			if not pause(0.15, generation) then
				break
			end
		end
		return false, active(generation) and "The chapter helper reached its time limit" or "Stopped"
	end
	runners.dti = Dti.run
end
do
	local Mimic = {}
	Mimic.booths = {
		{ name = "PopTheBalloon", kind = "Darts" },
		{ name = "RingToss", kind = "Ring" },
		{ name = "DunkBooth", kind = "Dunk" },
		{ name = "WhackAClown", kind = "Whack" },
		{ name = "MiniGolf", kind = "MiniGolf" },
		{ name = "High Striker", kind = "HighStriker" },
		{ name = "Basketball", kind = "Basketball" },
	}

	function Mimic.position(object)
		if not object then
			return nil
		end
		if object:IsA("Attachment") then
			return object.WorldPosition
		end
		if object:IsA("BasePart") then
			return object.Position
		end
		if object:IsA("Model") then
			return object:GetPivot().Position
		end
		return nil
	end

	function Mimic.packet(session, name, ...)
		if not session.packet then
			return false
		end
		local args = table.pack(...)
		local ok, why = pcall(function()
			local section, action = name:match("^([^/]+)/(.+)$")
			session.packet.send[section or "Section1"][action or name](table.unpack(args, 1, args.n))
		end)
		if not ok then
			session.error = tostring(why):sub(1, 160)
		end
		return ok
	end

	function Mimic.receive(session, generation, name, ...)
		if not active(generation) or type(name) ~= "string" then
			return
		end
		local args = table.pack(...)
		if name == "Section2/BeginObjective" then
			session.section2, session.cutscene = true, false
			session.lastProgress = os.clock()
		elseif name == "Section2/IntroCutsceneStart" then
			session.section2, session.cutscene = true, true
		elseif name == "Section2/IntroCutsceneEnd" then
			session.cutscene = false
		elseif name == "Section2/CrystalBallWishOffer" then
			session.wishes = args[1]
			session.lastProgress = os.clock()
		elseif name == "Section2/CrystalBallWishTimeout" then
			session.wishes = nil
		elseif name == "Section2/CrystalBallAllRelicsPlaced" then
			session.placed = true
		elseif name == "Section2/CrystalBallWishAnnounce" then
			session.wishes = nil
			session.lastProgress = os.clock()
		end
		for _, kind in ipairs({ "Star", "Moon", "Tarot" }) do
			if name == "Section2/" .. kind .. "PuzzleStart" then
				session.section2 = true
				session.puzzle = { kind = kind, started = os.clock(), functions = {} }
				session.lastProgress = os.clock()
			elseif name == "Section2/" .. kind .. "PuzzleEnd" then
				session.puzzle = nil
				session.lastProgress = os.clock()
			end
		end
		for _, kind in ipairs({ "Star", "Eye", "Moon", "Fate" }) do
			if name == "Section2/" .. kind .. "RelicObtained" then
				session.relics = session.relics or {}
				session.relics[kind] = true
				session.lastProgress = os.clock()
			end
		end
		if name == "Section2/EyePuzzleStarted" then
			session.eye = { order = {}, lit = {}, lastAt = os.clock() }
		end
		for _, booth in ipairs(Mimic.booths) do
			if name == "Section1/" .. booth.kind .. "Start" then
				session.mini = {
					booth = booth,
					args = args,
					nextAt = os.clock() + 0.5,
					started = os.clock(),
					tried = setmetatable({}, { __mode = "k" }),
				}
				session.expected, session.requestAt = nil, nil
				session.lastProgress = os.clock()
				return
			elseif name == "Section1/" .. booth.kind .. "End" then
				if session.mini and session.mini.booth == booth then
					session.mini = nil
					session.nextBoothAt = os.clock() + 0.8
				end
				return
			elseif name == "Section1/" .. booth.kind .. "Cooldown" and session.mini and session.mini.booth == booth then
				if type(args[1]) == "number" then
					session.mini.nextAt = math.max(session.mini.nextAt, os.clock() + math.clamp(args[1], 0.1, 15))
				end
				return
			end
		end
		if name == "TheHollow/CutsceneStart" or name == "TheHollow/Cutscene2Start" then
			session.cutscene = true
		elseif name == "TheHollow/CutsceneEnd" or name == "TheHollow/CutsceneReveal" then
			session.cutscene = false
			session.lastProgress = os.clock()
		end
	end

	function Mimic.uv(point, camera, center, width, height)
		if
			typeof(point) ~= "Vector3"
			or typeof(camera) ~= "CFrame"
			or typeof(center) ~= "Vector3"
			or type(width) ~= "number"
			or type(height) ~= "number"
			or width <= 0
			or height <= 0
		then
			return nil
		end
		local delta = point - center
		local x, y = delta:Dot(camera.RightVector) / width, delta:Dot(camera.UpVector) / height
		if x ~= x or y ~= y or math.abs(x) > 1.03 or math.abs(y) > 1.03 then
			return nil
		end
		return math.clamp(x, -1, 1), math.clamp(y, -1, 1)
	end

	function Mimic.progress(root)
		local result = { complete = 0, missing = 0, roots = {}, signature = {} }
		for _, booth in ipairs(Mimic.booths) do
			local gameRoot = root and root:FindFirstChild(booth.name)
			result.roots[booth.name] = gameRoot
			if not gameRoot then
				result.missing += 1
			end
			if gameRoot and gameRoot:GetAttribute("Complete") == true then
				result.complete += 1
			end
			local attrs = gameRoot and gameRoot:GetAttributes() or {}
			for _, key in ipairs({ "Complete", "Round", "BalloonsLeft", "Ringers", "Dunks", "HoleIndex", "Makes" }) do
				table.insert(result.signature, booth.name .. key .. tostring(attrs[key]))
			end
		end
		result.signature = table.concat(result.signature, "|")
		return result
	end

	function Mimic.nextTarget(mini, folder, attribute)
		local found, oldest = nil, math.huge
		for _, object in ipairs(folder and folder:GetChildren() or {}) do
			if
				attribute == "Active" and object:GetAttribute(attribute) ~= true
				or attribute ~= "Active" and object:GetAttribute(attribute) == true
			then
				continue
			end
			if not Mimic.position(object) then
				continue
			end
			local tried = mini.tried[object] or 0
			if tried <= os.clock() and tried < oldest then
				found, oldest = object, tried
			end
		end
		return found
	end

	function Mimic.golfPoint(root, ball, goal)
		local delta = goal - ball.Position
		delta = Vector3.new(delta.X, 0, delta.Z)
		if delta.Magnitude < 0.1 then
			return nil
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Include
		local obstacles = root:FindFirstChild("Barriers")
		params.FilterDescendantsInstances = obstacles and { obstacles } or {}
		params.RespectCanCollide = true
		local hit = workspace:Raycast(ball.Position, delta, params)
		if not hit then
			return goal
		end
		local part = hit.Instance
		if not part or not part:IsA("BasePart") then
			return nil
		end
		local radius = math.max(ball.Size.X, ball.Size.Z) * 0.6 + 0.3
		local candidates = {}
		for _, x in ipairs({ -1, 1 }) do
			for _, z in ipairs({ -1, 1 }) do
				local point = part.CFrame
					* Vector3.new(x * (part.Size.X / 2 + radius), 0, z * (part.Size.Z / 2 + radius))
				point = Vector3.new(point.X, ball.Position.Y, point.Z)
				local ray = point - ball.Position
				if ray.Magnitude > radius and not workspace:Raycast(ball.Position, ray, params) then
					table.insert(candidates, { point = point, length = ray.Magnitude + (goal - point).Magnitude })
				end
			end
		end
		table.sort(candidates, function(a, b)
			return a.length < b.length
		end)
		return candidates[1] and candidates[1].point
	end

	function Mimic.play(session, generation, games)
		local mini = session.mini
		if not mini or os.clock() < mini.nextAt then
			return
		end
		local booth, args = mini.booth, mini.args
		local root = games:FindFirstChild(booth.name)
		if not root or root:GetAttribute("Complete") == true then
			Mimic.packet(session, booth.kind .. "Leave")
			session.mini = nil
			return
		end
		mini.nextAt = os.clock() + 0.3
		if booth.kind == "Darts" then
			local target = Mimic.nextTarget(mini, root:FindFirstChild("Balloons"), "Popped")
			local point = Mimic.position(target)
			if point then
				local x, y = Mimic.uv(point, args[1], args[3], args[4], args[5])
				if x then
					Mimic.packet(session, "DartsThrow", x, y)
					mini.tried[target], mini.nextAt = os.clock() + 1.2, os.clock() + 0.45
				end
			end
		elseif booth.kind == "Dunk" then
			local target = getPath(root, "TargetHold", "Target")
			if target and root:GetAttribute("Dunking") ~= true then
				local x, y = Mimic.uv(Mimic.position(target), args[1], args[2], args[3], args[4])
				if x then
					Mimic.packet(session, "DunkThrow", x, y)
					mini.nextAt = os.clock() + 0.9
				end
			end
		elseif booth.kind == "Ring" then
			local target = Mimic.nextTarget(mini, root:FindFirstChild("Bottles"), "Ringed")
			if
				target
				and typeof(args[1]) == "CFrame"
				and typeof(args[3]) == "Vector3"
				and type(args[4]) == "number"
				and args[4] > 0
				and type(args[5]) == "number"
				and type(args[6]) == "number"
				and args[6] > args[5]
			then
				local right, look = args[1].RightVector, args[1].LookVector
				right, look = Vector3.new(right.X, 0, right.Z).Unit, Vector3.new(look.X, 0, look.Z).Unit
				local delta = target.Position - args[3]
				delta = Vector3.new(delta.X, 0, delta.Z)
				local x, power = delta:Dot(right) / args[4], (delta:Dot(look) - args[5]) / (args[6] - args[5])
				if math.abs(x) <= 1.01 and power >= 0 and power <= 1 then
					Mimic.packet(session, "RingThrow", math.clamp(x, -1, 1), power)
					mini.tried[target], mini.nextAt = os.clock() + 2, os.clock() + 1.2
				end
			end
		elseif booth.kind == "Whack" then
			local targets = root:FindFirstChild("Clowns")
			local target = Mimic.nextTarget(mini, targets, "Active")
			if target then
				Mimic.packet(session, "Whack", target)
				mini.tried[target], mini.nextAt = os.clock() + 0.7, os.clock() + 0.35
			end
		elseif booth.kind == "HighStriker" then
			local phase = root:GetAttribute("Phase")
			if phase == "idle" or phase == "windup" then
				Mimic.packet(session, "HighStrikerClick")
				mini.nextAt = os.clock() + 0.1
			end
		elseif booth.kind == "Basketball" then
			if mini.holdAt then
				if os.clock() - mini.holdAt >= mini.holdFor then
					Mimic.packet(session, "BasketballRelease", os.clock() - mini.holdAt)
					mini.holdAt, mini.nextAt = nil, os.clock() + 1.1
				else
					mini.nextAt = os.clock() + 0.02
				end
			elseif
				root:GetAttribute("Phase") == "idle"
				and type(args[2]) == "number"
				and args[2] > 0
				and args[2] <= 8
			then
				if Mimic.packet(session, "BasketballHold") then
					mini.holdAt, mini.holdFor, mini.nextAt = os.clock(), args[2], os.clock() + 0.02
				end
			end
		elseif booth.kind == "MiniGolf" then
			local ball, hole = root:FindFirstChild("GolfBall"), root:FindFirstChild("Hole")
			if
				ball
				and ball:IsA("BasePart")
				and hole
				and root:GetAttribute("BallReady") == true
				and ball.AssemblyLinearVelocity.Magnitude < 0.8
			then
				local goal = Mimic.position(hole)
				local holeIndex = root:GetAttribute("HoleIndex")
				if mini.holeIndex ~= holeIndex then
					mini.holeIndex, mini.shot, mini.deceleration = holeIndex, nil, nil
				end
				local point = goal and Mimic.golfPoint(root, ball, goal)
				if point then
					local delta = point - ball.Position
					delta = Vector3.new(delta.X, 0, delta.Z)
					local distance = delta.Magnitude
					if distance > 0.1 then
						if mini.shot and (ball.Position - mini.shot.start).Magnitude > 0.5 then
							local travelled = (ball.Position - mini.shot.start).Magnitude
							mini.deceleration = math.clamp(mini.shot.speed ^ 2 / (2 * travelled), 3, 100)
						end
						local speed = math.sqrt(2 * (mini.deceleration or 18) * distance)
						local power = math.clamp(speed / 100, 0.025, 0.85)
						if Mimic.packet(session, "MiniGolfShot", delta.Unit, power) then
							ball.AssemblyLinearVelocity = delta.Unit * (power * 100)
							mini.shot = { start = ball.Position, speed = power * 100 }
							mini.nextAt = os.clock() + 1
						end
					end
				end
			end
		end
	end

	function Mimic.upvalues(fn)
		local reader = getupvalues or (debug and debug.getupvalues)
		if type(reader) == "function" then
			local ok, values = pcall(reader, fn)
			if ok and type(values) == "table" then
				return values
			end
		end
		local readerOne = getupvalue or (debug and debug.getupvalue)
		local values = {}
		if type(readerOne) == "function" then
			for i = 1, 64 do
				local result = table.pack(pcall(readerOne, fn, i))
				if not result[1] then
					break
				end
				local value
				if result.n >= 3 then
					value = result[3]
				else
					value = result[2]
				end
				values[i] = value
			end
		end
		return values
	end

	function Mimic.puzzleFunctions(ui)
		local queue, seen, depths = {}, {}, {}
		local function add(fn, depth)
			if type(fn) == "function" and not seen[fn] and #queue < 192 then
				seen[fn] = true
				queue[#queue + 1] = fn
				depths[fn] = depth or 0
			end
		end
		add(ui.show)
		add(ui.hide)
		if ui.element and type(getconnections) == "function" then
			for _, button in ipairs(ui.element:GetDescendants()) do
				if button:IsA("GuiButton") then
					local ok, connections = pcall(getconnections, button.Activated)
					if ok then
						for _, connection in ipairs(connections) do
							local readable, callback = pcall(function()
								return connection.Function
							end)
							if readable then
								add(callback)
							end
						end
					end
				end
			end
		end
		local i = 1
		while i <= #queue do
			if depths[queue[i]] < 1 then
				for _, value in pairs(Mimic.upvalues(queue[i])) do
					add(value, 1)
				end
			end
			i = i + 1
		end
		return queue
	end

	function Mimic.solveRelicUI(session, generation)
		local puzzle = session.puzzle
		if not puzzle or os.clock() < (puzzle.nextAt or 0) then
			return false
		end
		local ui = session.puzzleUIs[puzzle.kind]
		if not ui or not ui.element or not ui.element.Visible then
			return false
		end
		puzzle.nextAt = os.clock() + 0.2
		if not puzzle.scanned then
			if #puzzle.functions == 0 then
				puzzle.functions = Mimic.puzzleFunctions(ui)
			end
			puzzle.scanned = true
		end
		for _, fn in ipairs(puzzle.functions) do
			local values = Mimic.upvalues(fn)
			local shape = values[1]
			if type(shape) == "table" and type(shape.stars) == "table" and type(shape.edges) == "table" then
				local stubs, locked, angles, targets = values[2], values[3], values[4], values[5]
				if
					type(stubs) == "table"
					and type(stubs[1]) == "table"
					and stubs[1][1]
					and stubs[1][1].edge_index
					and type(locked) == "table"
					and type(angles) == "table"
					and type(targets) == "table"
					and #angles == #shape.stars
					and #angles == #targets
				then
					puzzle.functions = { fn }
					puzzle.lastRead, session.puzzleNote = os.clock(), nil
					for i = 1, #angles do
						angles[i] = targets[i]
					end
					for i = 1, #angles do
						if not active(generation) or session.puzzle ~= puzzle then
							return false
						end
						pcall(fn, i)
					end
					return true
				end
			elseif type(shape) == "table" and type(shape.moons) == "table" then
				local locked, angles, targets = values[2], values[3], values[4]
				if
					type(locked) == "table"
					and type(angles) == "table"
					and type(targets) == "table"
					and #angles == #shape.moons
					and #targets == #angles
					and type(locked[1]) == "boolean"
					and type(values[5]) == "function"
					and type(values[6]) == "number"
				then
					puzzle.functions = { fn }
					puzzle.lastRead, session.puzzleNote = os.clock(), nil
					for i = 1, #angles do
						if not active(generation) or session.puzzle ~= puzzle then
							return false
						end
						angles[i] = targets[i]
						pcall(fn, i)
					end
					return true
				end
			elseif shape == "guessing" and puzzle.kind == "Tarot" then
				local slots, target = values[2], values[7]
				if
					type(slots) == "table"
					and #slots == 4
					and type(values[4]) == "table"
					and type(values[8]) == "table"
					and type(target) == "number"
					and slots[target]
				then
					puzzle.functions = { fn }
					puzzle.lastRead, session.puzzleNote = os.clock(), nil
					pcall(fn, slots[target])
					return true
				end
			end
		end
		if os.clock() - (puzzle.lastRead or puzzle.started) > 8 then
			session.puzzleNote = "Finish this puzzle in the game. I'll pick up from there."
		end
		return false
	end

	function Mimic.clearEyes(session)
		for _, connection in ipairs(session.eyeWatches or {}) do
			connection:Disconnect()
		end
		session.eyeRoot, session.eyeParts, session.eyeWatches = nil, nil, nil
	end

	function Mimic.eyeLit(eye, session)
		if not eye then
			return false
		end
		local cache = session and session.eyeParts
		local parts = cache and cache[eye]
		if not parts then
			parts = {}
			for _, part in ipairs(eye:GetDescendants()) do
				if part:IsA("BasePart") or part:IsA("Decal") then
					parts[part] = "Transparency"
				elseif part:IsA("Light") or part:IsA("ParticleEmitter") then
					parts[part] = "Enabled"
				end
			end
			if cache then
				cache[eye] = parts
			end
		end
		for part, property in pairs(parts) do
			if property == "Transparency" and part.Transparency < 0.5 or property == "Enabled" and part.Enabled then
				return true
			end
		end
		return false
	end

	function Mimic.watchEyes(session, puzzle)
		local state = session.eye
		local mirrors = puzzle and puzzle:FindFirstChild("Mirrors")
		if session.eyeRoot ~= mirrors then
			Mimic.clearEyes(session)
		end
		if not state or not mirrors then
			return
		end
		if not session.eyeRoot then
			session.eyeRoot, session.eyeParts, session.eyeWatches = mirrors, {}, {}
			local function changed()
				session.eyeParts = {}
			end
			for _, signal in ipairs({ mirrors.DescendantAdded, mirrors.DescendantRemoving }) do
				table.insert(session.eyeWatches, signal:Connect(changed))
			end
		end
		local rises, any = {}, false
		for i = 1, 4 do
			local mirror = mirrors:FindFirstChild("Mirror" .. i)
			local lit = Mimic.eyeLit(mirror and mirror:FindFirstChild("Eye"), session)
			if lit and not state.lit[i] then
				rises[#rises + 1] = i
			end
			state.lit[i], any = lit, any or lit
		end
		if #rises == 1 then
			if state.playing then
				state.order, state.ready, state.playing, state.next = {}, nil, nil, nil
			end
			state.ready = nil
			state.order[#state.order + 1] = rises[1]
			state.lastAt = os.clock()
		end
		if not any and #state.order > 0 and os.clock() - state.lastAt >= 1.5 then
			state.ready = true
		end
	end

	function Mimic.relicProgress(session, objective)
		local out = { complete = 0, roots = {} }
		for i, kind in ipairs({ "Star", "Eye", "Moon", "Fate" }) do
			local root = objective and objective:FindFirstChild("Puzzle" .. i)
			out.roots[i] = root
			local done = session.relics and session.relics[kind]
			if root and (root:GetAttribute("Complete") == true or root:GetAttribute("RelicObtained") == true) then
				done = true
			end
			if done then
				out.complete = out.complete + 1
			end
			out[i] = done == true
		end
		return out
	end
	function Mimic.activateButton(button, generation)
		if not active(generation) or not button or not button:IsA("GuiButton") then
			return false
		end
		local ancestor = button
		while ancestor do
			if
				ancestor:IsA("GuiObject") and not ancestor.Visible
				or ancestor:IsA("ScreenGui") and not ancestor.Enabled
			then
				return false
			end
			ancestor = ancestor.Parent
		end
		if type(firesignal) == "function" then
			local ok, result = pcall(firesignal, button.Activated)
			if ok and result ~= false then
				return true
			end
		end
		if type(getconnections) == "function" then
			local ok, connections = pcall(getconnections, button.Activated)
			if ok then
				local sent = false
				for _, connection in ipairs(connections) do
					local readable, callback, enabled = pcall(function()
						return connection.Function, connection.Enabled
					end)
					if readable and enabled ~= false and type(callback) == "function" and active(generation) then
						local called = pcall(callback)
						sent = sent or called
					end
				end
				return sent
			end
		end
		return false
	end
	function Mimic.pickWish(session, id, generation)
		if not active(generation) or os.clock() < (session.wishAt or 0) then
			return false
		end
		session.wishAt = os.clock() + 0.75
		local ui = session.wishUI
		if not ui or not ui.element or not ui.element.Visible then
			return false
		end
		local title = ({ Leave = "LEAVE", Blessing = "BLESSING", StunDimitra = "STILLED HAND" })[id]
		for _, label in ipairs(ui.element:GetDescendants()) do
			if label:IsA("TextLabel") and label.Text == title then
				local button = label.Parent
				while button and button ~= ui.element and not button:IsA("GuiButton") do
					button = button.Parent
				end
				if button ~= ui.element and Mimic.activateButton(button, generation) then
					return true
				end
			end
		end
		local values = Mimic.upvalues(ui.show)
		local callback, slots = values[1], values[2]
		if type(callback) == "function" and type(slots) == "table" and #slots == 3 and type(ui.hide) == "function" then
			for _, slot in ipairs(slots) do
				local ok, offered = pcall(function()
					return slot:get()
				end)
				if ok and offered == id then
					local hidden = pcall(ui.hide)
					if hidden and active(generation) then
						return pcall(callback, id)
					end
				end
			end
		end
		return false
	end

	function Mimic.relicStep(session, generation)
		local objective = getPath(workspace, "Section2", "MainObjective")
		local progress = Mimic.relicProgress(session, objective)
		local eye = progress.roots[2]
		Mimic.watchEyes(session, eye)
		if session.puzzle then
			local native = session.puzzleUIs[session.puzzle.kind]
			if native and native.element and not native.element.Visible and os.clock() - session.puzzle.started > 2 then
				Mimic.packet(session, "Section2/" .. session.puzzle.kind .. "PuzzleLeave")
				session.puzzle, session.puzzleNote = nil, nil
				session.nextBoothAt = os.clock() + 1
				return
			end
			status(
				"Solving the " .. session.puzzle.kind .. " relic",
				session.puzzleNote or "Following the current puzzle round",
				0.55 + progress.complete * 0.08
			)
			Mimic.solveRelicUI(session, generation)
			return
		end
		if session.wishes then
			for _, wanted in ipairs({ "Leave", "Blessing", "StunDimitra" }) do
				for _, choice in pairs(session.wishes) do
					local id = type(choice) == "table" and (choice.id or choice.key or choice.name) or choice
					if id == wanted then
						if Mimic.pickWish(session, id, generation) then
							session.leaveWish, session.wishes = id == "Leave", nil
							session.nextBoothAt = os.clock() + 2
						else
							status(
								"Choose " .. wanted .. " in the crystal ball menu",
								"Pick your wish in the game, then I'll keep going",
								0.9
							)
						end
						return
					end
				end
			end
			status("Choose a wish", "The available wishes are in the game's panel", 0.9)
			return
		end
		local model, root = character()
		if not model or root.Anchored or session.cutscene or session.movement.movementLocked then
			return
		end
		if os.clock() < (session.nextBoothAt or 0) then
			return
		end
		status(
			"Collecting the four relics",
			string.format("%d / 4 relics obtained", progress.complete),
			0.55 + progress.complete * 0.08
		)
		if session.eye and session.eye.ready and not progress[2] then
			local state = session.eye
			state.next, state.playing = state.next or 1, true
			local statues = eye and eye:FindFirstChild("EyeStatues")
			local target = statues and statues:FindFirstChild("Eye" .. tostring(state.order[state.next]))
			if target and Mimic.prompt(session, target, generation, true) then
				state.next = state.next + 1
				session.nextBoothAt = os.clock() + 0.4
				if state.next > #state.order then
					state.ready = false
				end
			end
			return
		end
		if progress.complete == 4 or session.placed then
			local ball = objective and objective:FindFirstChild("CrystalBallWish")
			if session.leaveWish then
				local section = workspace:FindFirstChild("Section2")
				local exit = section
					and (section:FindFirstChild("Exit", true) or section:FindFirstChild("ExitGate", true))
				if exit then
					Mimic.prompt(session, exit, generation)
				end
				status("Leaving the circus", "Waiting for the exit and the saved Hollow badge", 0.95)
			elseif ball then
				Mimic.prompt(session, ball, generation)
			end
			return
		end
		local choices = {}
		for i = 1, 4 do
			local target = progress.roots[i]
			if target and not progress[i] then
				local prompt = target:FindFirstChildWhichIsA("ProximityPrompt", true)
				local point = prompt and EventInput.point(prompt.Parent)
				if prompt and prompt.Enabled and point and os.clock() >= (session.retryAt[prompt] or 0) then
					choices[#choices + 1] = { root = target, distance = (point - root.Position).Magnitude }
				elseif target:FindFirstChild("PromptPart") then
					local marker = target.PromptPart
					if (marker.Position - root.Position).Magnitude > 30 and os.clock() >= (session.streamAt or 0) then
						session.streamAt = os.clock() + 5
						approach(marker.Position, generation)
						return
					end
				end
			end
		end
		table.sort(choices, function(a, b)
			return a.distance < b.distance
		end)
		if choices[1] then
			Mimic.prompt(session, choices[1].root, generation)
		end
	end

	function Mimic.release(session)
		Mimic.clearEyes(session)
		Mimic.clearMenu(session)
		EventInput.release(session)
		if session.wishes and session.wishState and type(session.wishState.interrupt) == "function" then
			pcall(session.wishState.interrupt)
			session.wishes = nil
		end
		if session.eyeConnection then
			session.eyeConnection:Disconnect()
			session.eyeConnection = nil
		end
		if session.connection then
			session.connection:Disconnect()
			session.connection = nil
		end
		if session.mini then
			if session.mini.holdAt then
				Mimic.packet(session, "BasketballRelease", os.clock() - session.mini.holdAt)
			end
			Mimic.packet(session, session.mini.booth.kind .. "Leave")
			session.mini = nil
		end
		if session.puzzle then
			Mimic.packet(session, "Section2/" .. session.puzzle.kind .. "PuzzleLeave")
		end
	end

	function Mimic.prompt(session, root, generation, singlePress)
		if not root then
			return false
		end
		local prompt = root:FindFirstChildWhichIsA("ProximityPrompt", true)
		if not prompt or not prompt.Enabled or os.clock() < (session.retryAt[prompt] or 0) then
			return false
		end
		local point = EventInput.point(prompt.Parent)
		local model, playerRoot = character()
		if not model or not point then
			return false
		end
		local function allowed()
			local _, nowRoot = character()
			return active(generation)
				and App.player.Character == model
				and nowRoot
				and not nowRoot.Anchored
				and not session.mini
				and not session.cutscene
				and not session.movement.movementLocked
				and prompt.Parent
		end
		if (point - playerRoot.Position).Magnitude > math.min(prompt.MaxActivationDistance * 0.6, 5) then
			if not approach(point, generation, nil, false, allowed) then
				return false
			end
		end
		session.retryAt[prompt] = os.clock() + (singlePress and 0.25 or 4)
		local held = EventInput.hold(session, prompt, generation, allowed, { customCamera = true, keepLook = true })
		if not pause(0.5, generation) then
			EventInput.release(session)
			return false
		end
		if
			(not singlePress or not held)
			and not session.mini
			and allowed()
			and prompt.Enabled
			and type(fireproximityprompt) == "function"
		then
			call(prompt, function()
				if allowed() then
					fireproximityprompt(prompt, prompt.HoldDuration)
				end
			end, math.min(prompt.HoldDuration + 2, 32), generation)
		end
		EventInput.release(session)
		return held
			or session.mini ~= nil
			or session.puzzle ~= nil
			or session.cutscene == true
			or prompt.Enabled == false
	end

	function Mimic.clearMenu(session)
		for _, connection in ipairs(session.menuWatches or {}) do
			connection:Disconnect()
		end
		session.menuGui, session.menuLabels, session.menuWatches = nil, nil, nil
	end

	function Mimic.menu(session, generation)
		if os.clock() < (session.menuAt or 0) then
			return
		end
		session.menuAt = os.clock() + 0.8
		local gui = App.player:FindFirstChild("PlayerGui")
		if gui ~= session.menuGui then
			Mimic.clearMenu(session)
			if gui then
				local labels = {}
				session.menuGui, session.menuLabels, session.menuWatches = gui, labels, {}
				local function add(object)
					if
						(object:IsA("TextButton") or object:IsA("TextLabel"))
						and not (App.gui and object:IsDescendantOf(App.gui))
					then
						labels[object] = true
					end
				end
				if gui.DescendantAdded then
					table.insert(session.menuWatches, gui.DescendantAdded:Connect(add))
					table.insert(
						session.menuWatches,
						gui.DescendantRemoving:Connect(function(object)
							labels[object] = nil
						end)
					)
				end
				for _, object in ipairs(gui:GetDescendants()) do
					add(object)
				end
			end
		end
		for button in pairs(session.menuLabels or {}) do
			local text = button.Text:gsub("<.->", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
			local warning = text == "tap anywhere to continue"
				or text == "click or press any key to continue"
				or text == "press any button to continue"
			if
				not warning
				and (
					not button:IsA("TextButton")
					or text ~= "ready" and text ~= "skip" and text ~= "skip cutscene" and text ~= "i understand"
				)
			then
				continue
			end
			local visible, parent = button.Visible, button.Parent
			while visible and parent and parent ~= gui do
				if parent:IsA("GuiObject") then
					visible = parent.Visible
				end
				if parent:IsA("ScreenGui") then
					visible = parent.Enabled
				end
				parent = parent.Parent
			end
			if visible then
				if warning and not session.mini then
					EventInput.tap(session, generation, Enum.KeyCode.Space)
					return
				end
				if Mimic.activateButton(button, generation) then
					return
				end
			end
		end
	end

	function Mimic.discover(session, generation)
		if os.clock() < (session.streamAt or 0) then
			return
		end
		session.streamAt = os.clock() + 4
		local areas = current.searchAreas or {}
		if #areas == 0 then
			return
		end
		session.area = (session.area or 0) % #areas + 1
		local point = Vector3.new(table.unpack(areas[session.area]))
		call("Carnival streaming", function()
			App.player:RequestStreamAroundAsync(point, 2)
		end, 3, generation)
		if not active(generation) or session.mini or session.cutscene or session.movement.movementLocked then
			return
		end
		approach(point, generation, nil, false, function()
			return active(generation)
				and not session.mini
				and not session.cutscene
				and not session.movement.movementLocked
		end)
	end

	function Mimic.run(generation)
		if verify(current) == true then
			return true, "The Mimic's Hollow badge is already earned"
		end
		if game.PlaceId ~= current.eventPlace then
			return false, "Enter Nightmare Circus through The Mimic's Hollow event entrance, then press Start"
		end
		local loaded = waitUntil(function()
			return workspace:FindFirstChild("Section1") or workspace:FindFirstChild("Section2")
		end, 60, generation)
		if not loaded then
			return false, "Nightmare Circus hasn't loaded yet"
		end
		local section = workspace:FindFirstChild("Section1")
		if
			workspace:GetAttribute("MimicEvent") ~= "TheHollow"
			and workspace:GetAttribute("MimicHollowSelected") ~= true
			and workspace:GetAttribute("MimicHollowActive") ~= true
			and (not section or section:GetAttribute("HollowSelected") ~= true)
			and (not section or section:GetAttribute("HollowActive") ~= true)
		then
			return false, "This is regular Nightmare Circus. Join The Hollow event mode in The Mimic first."
		end
		status("Loading Nightmare Circus", "Waiting for the carnival controls", 0)
		local controls = waitUntil(function()
			local packetObject = getPath(Storage, "modules", "Packet")
			local movementObject = getPath(Storage, "framework", "controllers", "movement")
			local stateObject = getPath(Storage, "framework", "game", "minigame_state")
			local remote = packetObject and packetObject:FindFirstChild("Reliable")
			return packetObject
				and movementObject
				and stateObject
				and remote
				and { packet = packetObject, movement = movementObject, state = stateObject, remote = remote }
		end, 30, generation)
		if not controls then
			return false, "The booths haven't loaded yet. Press Start to retry."
		end
		local packetObject = controls.packet
		local packet = module(packetObject, generation)
		local movement = module(controls.movement, generation)
		local nativeState = module(controls.state, generation)
		local remote = controls.remote
		if not packet or not movement or not nativeState or not remote then
			return false, "The carnival controls haven't loaded yet. Press Start to retry."
		end
		local session = {
			packet = packet,
			movement = movement,
			retryAt = {},
			lastProgress = os.clock(),
			badgeAt = 0,
			puzzleUIs = {},
		}
		for _, kind in ipairs({ "Star", "Moon", "Tarot" }) do
			local object = getPath(Storage, "framework", "ui", kind:lower() .. "_puzzle")
			if object then
				session.puzzleUIs[kind] = module(object, generation)
			end
		end
		local wishObject = getPath(Storage, "framework", "ui", "wish_selection")
		if wishObject then
			session.wishUI = module(wishObject, generation)
		end
		local wishStateObject = getPath(Storage, "framework", "game", "wish_menu_state")
		if wishStateObject then
			session.wishState = module(wishStateObject, generation)
		end
		table.insert(App.cleanups, function()
			Mimic.release(session)
		end)
		session.connection = remote.OnClientEvent:Connect(function(name, ...)
			local ok, why = pcall(Mimic.receive, session, generation, name, ...)
			if not ok then
				session.error = tostring(why):sub(1, 160)
			end
		end)
		if RunService and RunService.Heartbeat then
			local nextWatch = 0
			session.eyeConnection = RunService.Heartbeat:Connect(function()
				if active(generation) and session.eye and os.clock() >= nextWatch then
					nextWatch = os.clock() + 0.04
					pcall(Mimic.watchEyes, session, getPath(workspace, "Section2", "MainObjective", "Puzzle2"))
				end
			end)
		end
		local games = section and section:FindFirstChild("Games")
		local signature, resetAt = nil, 0
		while active(generation) do
			if os.clock() >= session.badgeAt then
				session.badgeAt = os.clock() + 12
				if verify(current, true) == true then
					return true, "The Mimic's Hollow badge earned"
				end
			end
			section = workspace:FindFirstChild("Section1")
			games = section and section:FindFirstChild("Games")
			local progress = Mimic.progress(games)
			if progress.signature ~= signature then
				signature, session.lastProgress = progress.signature, os.clock()
			end
			Mimic.menu(session, generation)
			local model, root = character()
			local relicArea = getPath(workspace, "Section2", "MainObjective")
			if model and relicArea and not session.section2 then
				for _, puzzle in ipairs(relicArea:GetChildren()) do
					local marker = puzzle:FindFirstChild("PromptPart")
					if marker and marker:IsA("BasePart") and (marker.Position - root.Position).Magnitude < 150 then
						session.section2 = true
						session.eye = { order = {}, lit = {}, lastAt = os.clock() }
						break
					end
				end
			end
			if session.section2 then
				if not session.eye then
					session.eye = { order = {}, lit = {}, lastAt = os.clock() }
				end
				for _, kind in ipairs({ "Star", "Moon", "Tarot" }) do
					local native = session.puzzleUIs[kind]
					if not session.puzzle and native and native.element and native.element.Visible then
						session.puzzle = { kind = kind, started = os.clock(), functions = {} }
					end
				end
				Mimic.relicStep(session, generation)
			else
				local inGame = type(nativeState.in_minigame) == "table" and nativeState.in_minigame:get() == true
				if session.mini then
					status(
						"Playing " .. session.mini.booth.name,
						string.format("%d / 7 carnival games complete", progress.complete),
						progress.complete / 8
					)
					if model and not session.cutscene then
						Mimic.play(session, generation, games)
					end
				elseif model and inGame then
					if os.clock() >= resetAt then
						resetAt = os.clock() + 3
						local closest, distance = nil, 14
						for _, booth in ipairs(Mimic.booths) do
							local prompt = progress.roots[booth.name]
								and progress.roots[booth.name]:FindFirstChildWhichIsA("ProximityPrompt", true)
							local point = prompt and EventInput.point(prompt.Parent)
							if point and (point - root.Position).Magnitude < distance then
								closest, distance = booth, (point - root.Position).Magnitude
							end
						end
						if closest then
							Mimic.packet(session, closest.kind .. "Leave")
						end
					end
				elseif model and not root.Anchored and not movement.movementLocked and not session.cutscene then
					if os.clock() >= (session.nextBoothAt or 0) then
						if not section or progress.complete == 7 or section:GetAttribute("GamesOpen") ~= true then
							status(
								progress.complete == 7 and "Going to the relics" or "Starting the Hollow carnival",
								progress.complete == 7
										and "The seven games are complete. Continuing through the Fatebox."
									or "Waiting for the games to open",
								progress.complete / 8
							)
							local box = getPath(section, "Fatebox", "DimitraBox")
							if box then
								Mimic.prompt(session, box, generation)
							else
								Mimic.discover(session, generation)
							end
						else
							local choices = {}
							for _, booth in ipairs(Mimic.booths) do
								local boothRoot = progress.roots[booth.name]
								local prompt = boothRoot and boothRoot:FindFirstChildWhichIsA("ProximityPrompt", true)
								local point = prompt and EventInput.point(prompt.Parent)
								if
									boothRoot
									and boothRoot:GetAttribute("Complete") ~= true
									and boothRoot:GetAttribute("InUse") ~= true
									and point
									and prompt.Enabled
									and os.clock() >= (session.retryAt[prompt] or 0)
								then
									table.insert(
										choices,
										{ root = boothRoot, distance = (root.Position - point).Magnitude }
									)
								end
							end
							table.sort(choices, function(a, b)
								return a.distance < b.distance
							end)
							status(
								"Finding the next booth",
								string.format("%d / 7 carnival games complete", progress.complete),
								progress.complete / 8
							)
							if choices[1] then
								Mimic.prompt(session, choices[1].root, generation)
							elseif progress.missing > 0 then
								Mimic.discover(session, generation)
							end
						end
					end
				end
			end
			if os.clock() - session.lastProgress > 300 then
				return false,
					session.error
						or session.puzzleNote
						or "The circus hasn't credited more progress. Press Start to redetect the current stage."
			end
			if not pause(0.05, generation) then
				break
			end
		end
		return false, "Stopped"
	end
	runners.mimic = Mimic.run
end

do
	local Rails = {}
	Rails.hints = {
		find_stain = "Find the marked stain and move close enough to see it.",
		open_lock = "Pick up the Phantom Key and use it on the lock.",
		board = "Board the Phantom Train through the marked gate.",
		travel_to_town = "Stay aboard until the town stop.",
		find_town_key = "Find the town's Phantom Key. Watch for the residents turning hostile.",
		travel_to_prison = "Return to the train and travel to the prison.",
		find_prison_key = "Find the prison key and prepare for the Goliath.",
		defeat_goliath = "Defeat the marked Goliath using your weapon.",
		travel_to_conductor = "Continue aboard the train to the conductor.",
	}
	function Rails.part(object)
		if not object then
			return nil
		end
		if object:IsA("BasePart") then
			return object
		end
		if object:IsA("Model") then
			return object.PrimaryPart or object:FindFirstChildWhichIsA("BasePart", true)
		end
		return nil
	end
	function Rails.code(value)
		if type(value) == "number" then
			if value ~= value or value <= 0 or value > 99999999 or value % 1 ~= 0 then
				return nil
			end
			return string.format("%.0f", value)
		elseif type(value) == "string" then
			local code = value:match("^%s*(%d+)%s*$")
			if code and #code <= 8 and tonumber(code) > 0 then
				return code
			end
		end
		return nil
	end
	function Rails.vaultCode(vault)
		local value = vault and vault:FindFirstChild("Combination")
		if value and (value:IsA("IntValue") or value:IsA("NumberValue") or value:IsA("StringValue")) then
			return Rails.code(value.Value)
		end
		return nil
	end
	function Rails.itemKind(id)
		if type(id) ~= "string" then
			return nil
		end
		local key = id:lower():gsub("[%s_%-]", "")
		if key == "phantomkey" then
			return "key", "Phantom Key"
		end
		if key == "rockkey" then
			return "key", "Prison key"
		end
		if key == "skeletonkey" then
			return "key", "Skeleton Key"
		end
		if key == "supplydepotkey" then
			return "key", "Supply depot key"
		end
		if key == "bankcombonote" then
			return "note", "Bank code note"
		end
		if key:match("^bankcombo[1-5]$") then
			return "note", "Bank code piece"
		end
		return nil
	end
	function Rails.index(session, object)
		if not object:IsDescendantOf(workspace) then
			return
		end
		local name = object.Name:lower()
		if object:IsA("Model") or object:IsA("BasePart") then
			local kind, title =
				Rails.itemKind(object:GetAttribute("ObjectId") or object:GetAttribute("ObjectType") or object.Name)
			if kind then
				session.scene[object] = { kind = kind, title = title }
			elseif name == "vault" and object:IsA("Model") then
				session.scene[object] = { kind = "vault", title = "Bank vault" }
			elseif name == "lock" then
				local train = workspace:FindFirstChild("PhantomTrain")
				if train and object:IsDescendantOf(train) then
					session.scene[object] = { kind = "lock", title = "Train lock" }
				end
			end
		elseif
			name == "combination"
			and (object:IsA("IntValue") or object:IsA("NumberValue") or object:IsA("StringValue"))
		then
			local vault = object.Parent
			if vault and vault.Name:lower() == "vault" then
				session.scene[vault] = { kind = "vault", title = "Bank vault" }
			end
		elseif object:IsA("ProximityPrompt") then
			local text = (object.ObjectText or ""):lower()
			local kind = Rails.itemKind(text)
			if kind == "key" or text == "key" then
				local owner = object:FindFirstAncestorOfClass("Model") or object.Parent
				if owner and Rails.part(owner) and not session.scene[owner] then
					session.scene[owner] = {
						kind = "key",
						title = object.ObjectText ~= "" and object.ObjectText or "Key",
						prompt = object,
					}
				end
			end
		end
	end
	function Rails.watch(session, generation)
		session.scene = setmetatable({}, { __mode = "k" })
		session.itemData = setmetatable({}, { __mode = "k" })
		session.scanComplete = false
		if workspace.DescendantAdded then
			session.added = workspace.DescendantAdded:Connect(function(object)
				if active(generation) and App.railsSession == session then
					pcall(Rails.index, session, object)
				end
			end)
		end
		task.spawn(function()
			local objects = workspace:GetDescendants()
			for i, object in ipairs(objects) do
				if not active(generation) or App.railsSession ~= session then
					return
				end
				pcall(Rails.index, session, object)
				if i % 300 == 0 then
					task.wait()
				end
			end
			if active(generation) and App.railsSession == session then
				session.scanComplete = true
			end
		end)
		task.spawn(function()
			while active(generation) and App.railsSession == session do
				local components = getPath(Storage, "Shared", "Universe", "ECS", "components")
				local world = getPath(Storage, "Shared", "Universe", "ECS", "world")
				if components and world then
					local fields = module(components, generation)
					if not active(generation) or App.railsSession ~= session then
						return
					end
					local values = module(world, generation)
					if not active(generation) or App.railsSession ~= session then
						return
					end
					if type(fields) == "table" and type(values) == "table" then
						session.ecs = { fields = fields, world = values }
						return
					end
				end
				if not pause(5, generation) then
					return
				end
			end
		end)
	end
	function Rails.readItems(session)
		local ecs = session and session.ecs
		if not ecs or os.clock() < (session.itemsAt or 0) then
			return
		end
		session.itemsAt = os.clock() + 1
		local fields, world = ecs.fields, ecs.world
		if not fields.ObjectId or not fields.ModelInstance or type(world.query) ~= "function" then
			return
		end
		local nextData = setmetatable({}, { __mode = "k" })
		local ok = pcall(function()
			local count = 0
			for entity, id, object in world:query(fields.ObjectId, fields.ModelInstance) do
				count = count + 1
				if count > 2048 then
					break
				end
				local kind, title = Rails.itemKind(id)
				if kind and typeof(object) == "Instance" and object:IsDescendantOf(workspace) then
					local data = { kind = kind, title = title }
					if kind == "note" and fields.BankNoteCombo and type(world.get) == "function" then
						local read, value = pcall(world.get, world, entity, fields.BankNoteCombo)
						if read then
							data.code = Rails.code(value)
						end
					end
					nextData[object] = data
				end
			end
		end)
		if ok then
			session.itemData = nextData
		end
	end
	function Rails.anchor(object, kind)
		if kind == "vault" then
			local door = object:FindFirstChild("Door")
			local combo = door and door:FindFirstChild("Combo")
			return Rails.part(combo) or Rails.part(door) or Rails.part(object)
		elseif kind == "key" then
			local grip = object:FindFirstChild("Grip")
			return Rails.part(grip) or Rails.part(object)
		end
		return Rails.part(object)
	end
	function Rails.targets(session)
		local out, seen = {}, {}
		local _, playerRoot = character()
		local parking = workspace:FindFirstChild("PhantomParking")
		local function add(object, title, danger, data)
			local part = object and Rails.anchor(object, data and data.kind)
			if
				object
				and not seen[object]
				and object:IsDescendantOf(workspace)
				and part
				and (not parking or not object:IsDescendantOf(parking))
			then
				local distance = playerRoot and (part.Position - playerRoot.Position).Magnitude or 0
				if distance > (danger and 600 or 4000) then
					return
				end
				local humanoid = danger and object:FindFirstChildWhichIsA("Humanoid", true)
				if humanoid and humanoid.Health <= 0 then
					return
				end
				seen[object] = true
				out[#out + 1] = {
					object = object,
					title = title,
					danger = danger,
					distance = distance,
					part = part,
					kind = data and data.kind,
					code = data and data.code,
					priority = data and (data.kind == "key" and 0 or data.kind == "vault" and 1 or 2)
						or (danger and 10 or 3),
				}
			end
		end
		if session then
			Rails.readItems(session)
			for object, data in pairs(session.itemData or {}) do
				add(object, data.title, false, data)
			end
			for object, data in pairs(session.scene or {}) do
				if not object:IsDescendantOf(workspace) then
					session.scene[object] = nil
				else
					local entry =
						{ kind = data.kind, code = data.kind == "vault" and Rails.vaultCode(object) or data.code }
					if data.kind ~= "key" or not data.prompt or data.prompt.Parent and data.prompt.Enabled then
						add(object, data.title, false, entry)
					end
				end
			end
		end
		for _, tag in ipairs({
			"PhantomGate",
			"PhantomWatcher",
			"PhantomWatchingConductor",
			"PhantomTownResident",
			"Enemy",
		}) do
			for _, object in ipairs(Collection:GetTagged(tag)) do
				add(
					object,
					tag == "PhantomGate" and "Train gate"
						or tag == "PhantomWatchingConductor" and "Conductor"
						or (tag == "Enemy" and "Enemy" or "Phantom threat"),
					tag ~= "PhantomGate" and tag ~= "PhantomWatchingConductor"
				)
			end
		end
		local stains = workspace:FindFirstChild("Stains")
		for _, stain in ipairs(stains and stains:GetChildren() or {}) do
			add(stain:FindFirstChild("Root"), "Stain")
		end
		for _, name in ipairs({ "RuntimeItems", "ObjectModels", "RuntimeEntities", "RuntimeEnemies" }) do
			local folder = workspace:FindFirstChild(name)
			for _, object in ipairs(folder and folder:GetChildren() or {}) do
				local id = tostring(
					object:GetAttribute("ObjectId")
						or object:GetAttribute("ObjectType")
						or object:GetAttribute("EntityName")
						or object.Name
				):lower()
				if id:find("phantom_key", 1, true) or id:find("phantom key", 1, true) then
					add(object, "Phantom Key", false, { kind = "key" })
				elseif id:find("goliath", 1, true) then
					add(object, "Goliath", true)
				end
			end
		end
		return out
	end
	function Rails.color(target)
		return target.kind == "key" and Color3.fromRGB(255, 223, 85)
			or target.kind == "vault" and Color3.fromRGB(100, 190, 255)
			or target.kind == "note" and Color3.fromRGB(204, 160, 255)
			or target.kind == "lock" and Color3.fromRGB(255, 174, 90)
			or target.danger and Color3.fromRGB(255, 98, 98)
			or Color3.fromRGB(117, 222, 185)
	end
	function Rails.area(object)
		while object and object ~= workspace do
			if object.Name == "PrisonCar" then
				return "prison"
			end
			if object.Name == "TownCar" then
				return "town"
			end
			object = object.Parent
		end
		return nil
	end
	function Rails.nearest(targets, kind, objective)
		local best, bestRank
		for _, target in ipairs(targets) do
			local area = Rails.area(target.object)
			local allowed = not (
					objective == "find_town_key" and (area == "prison" or target.title == "Prison key")
				) and not (objective == "find_prison_key" and area == "town")
			local questKey = target.title == "Phantom Key"
				or objective == "find_prison_key" and target.title == "Prison key"
			local rank = kind == "key"
					and (objective == "find_town_key" or objective == "find_prison_key" or objective == "open_lock")
					and not questKey
					and 1
				or 0
			if
				target.kind == kind
				and allowed
				and (not best or rank < bestRank or rank == bestRank and target.distance < best.distance)
			then
				best, bestRank = target, rank
			end
		end
		return best
	end
	function Rails.focus(targets, objective, mode)
		local vault = Rails.nearest(targets, "vault", mode ~= "vault" and objective or nil)
		local lock = Rails.nearest(targets, "lock", objective)
		local key = Rails.nearest(targets, "key", objective)
		local note = Rails.nearest(targets, "note", objective)
		if mode == "vault" then
			return vault or lock
		end
		if mode == "auto" then
			local title = objective == "find_stain" and "Stain"
				or objective == "board" and "Train gate"
				or objective == "travel_to_conductor" and "Conductor"
			if title then
				local closest
				for _, target in ipairs(targets) do
					if target.title == title and (not closest or target.distance < closest.distance) then
						closest = target
					end
				end
				if closest then
					return closest
				end
			end
			if objective == "open_lock" and (not key or key.distance < 8) then
				return lock or key
			end
			if objective == "defeat_goliath" then
				for _, target in ipairs(targets) do
					if target.title == "Goliath" then
						return target
					end
				end
			end
		end
		return key or note or vault or lock
	end
	function Rails.line(session, target)
		if not App.railsLine or not target then
			if session.beam then
				session.beam.Enabled = false
			end
			return
		end
		local _, root = character()
		local part = target.part or Rails.anchor(target.object, target.kind)
		if not root or not part then
			if session.beam then
				session.beam.Enabled = false
			end
			return
		end
		if not session.beam then
			local anchors = {}
			for i = 1, 2 do
				local anchor = Instance.new("Part")
				anchor.Name, anchor.Size, anchor.Transparency = "GuideAnchor", Vector3.new(0.1, 0.1, 0.1), 1
				anchor.Anchored, anchor.CanCollide, anchor.CanQuery, anchor.CanTouch, anchor.CastShadow =
					true, false, false, false, false
				anchor.Parent = session.worldFolder
				local attachment = Instance.new("Attachment")
				attachment.Parent = anchor
				anchors[i] = { part = anchor, attachment = attachment }
			end
			local beam = Instance.new("Beam")
			beam.Attachment0, beam.Attachment1 = anchors[1].attachment, anchors[2].attachment
			beam.Width0, beam.Width1, beam.FaceCamera, beam.Segments = 0.1, 0.18, true, 1
			beam.LightEmission = 1
			beam.Parent = session.worldFolder
			session.beam, session.anchors = beam, anchors
		end
		session.anchors[1].part.CFrame = CFrame.new(root.Position)
		session.anchors[2].part.CFrame = CFrame.new(part.Position + Vector3.new(0, 1, 0))
		session.beam.Color = ColorSequence.new(Rails.color(target))
		session.beam.Enabled = true
	end
	function Rails.guidance(session, targets, objective)
		local vault = Rails.nearest(targets, "vault")
		session.vault = vault and vault.object or nil
		local code = session.vault and Rails.vaultCode(session.vault)
		local mode = App.railsTracking or "auto"
		local focus = Rails.focus(targets, objective, mode)
		session.focus = focus
		Rails.line(session, focus)
		local text = focus and string.format("Tracking %s - %.0f studs", focus.title, focus.distance)
			or (
				session.scanComplete and "No keys or vaults nearby yet. Keep exploring."
				or "Scanning the live scenery for keys and vaults..."
			)
		if focus then
			local _, root = character()
			local difference = root and (focus.part.Position.Y - root.Position.Y) or 0
			if math.abs(difference) > 8 then
				text = text .. (difference > 0 and " (above you)" or " (below you)")
			end
		end
		if vault then
			text = text .. "\n" .. (code and "Vault code: " .. code or "Found a vault. Its code hasn't loaded yet.")
			if code then
				text = text .. ". Enter it with the vault's own dial."
			end
		end
		App.railsGuideText = text
		refresh()
		return text
	end
	function Rails.clear(session)
		if session.added then
			pcall(session.added.Disconnect, session.added)
			session.added = nil
		end
		if session.folder then
			session.folder:Destroy()
			session.folder = nil
		end
		if session.worldFolder then
			session.worldFolder:Destroy()
			session.worldFolder = nil
		end
		if App.railsSession == session then
			App.railsSession = nil
		end
		App.railsGuideText = "Enable helpers to mark live keys, bank clues and vault codes."
	end
	App.setRailsTracking = function(mode)
		if mode ~= "key" and mode ~= "vault" then
			return
		end
		App.railsTracking = App.railsTracking == mode and "auto" or mode
		refresh()
	end
	App.setRailsLine = function()
		App.railsLine = not App.railsLine
		if App.railsSession and not App.railsLine and App.railsSession.beam then
			App.railsSession.beam.Enabled = false
		end
		refresh()
	end
	App.copyRailsCode = function()
		local session = App.railsSession
		local vault = session and session.vault
		local parking = workspace:FindFirstChild("PhantomParking")
		local code = vault
			and vault:IsDescendantOf(workspace)
			and (not parking or not vault:IsDescendantOf(parking))
			and Rails.vaultCode(vault)
		if not code then
			log("No live vault code nearby. Enable helpers and approach the bank first.")
			return false
		end
		local copy = setclipboard or toclipboard
		local ok = type(copy) == "function" and pcall(copy, code)
		log(
			ok and "Vault code copied: " .. code
				or "Vault code: " .. code .. ". Clipboard isn't available on this executor."
		)
		return ok
	end
	function Rails.marker(session, target)
		local marker = session.markers[target.object]
		local part = target.part or Rails.anchor(target.object, target.kind)
		if not part then
			return
		end
		if not marker then
			local color = Rails.color(target)
			local gui = Instance.new("BillboardGui")
			gui.Name, gui.Size, gui.AlwaysOnTop, gui.MaxDistance =
				"PhantomMarker", UDim2.fromOffset(220, 64), true, 4000
			gui.StudsOffset = Vector3.new(0, 3, 0)
			gui.Parent = session.folder
			local label = Instance.new("TextLabel")
			label.Size, label.BackgroundTransparency, label.TextSize = UDim2.fromScale(1, 1), 1, 14
			label.TextColor3, label.TextStrokeTransparency, label.Font = color, 0.3, Enum.Font.GothamMedium
			label.Parent = gui
			local highlight = Instance.new("Highlight")
			highlight.Adornee, highlight.FillTransparency, highlight.OutlineColor = target.object, 0.85, color
			highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			highlight.Parent = session.worldFolder or session.folder
			marker = { gui = gui, label = label, highlight = highlight }
			session.markers[target.object] = marker
		end
		marker.gui.Adornee = part
		local color = Rails.color(target)
		marker.label.TextColor3, marker.highlight.OutlineColor, marker.highlight.FillColor = color, color, color
		marker.label.TextSize = target.kind == "key" and 17 or target.danger and 12 or 14
		local _, root = character()
		marker.label.Text = target.title
			.. (target.code and "\nCODE: " .. target.code or "")
			.. (root and string.format("  %.0f studs", (part.Position - root.Position).Magnitude) or "")
	end
	function Rails.run(generation)
		local folder = Instance.new("Folder")
		folder.Name, folder.Parent = "PhantomHelpers", App.gui
		local worldFolder = Instance.new("Folder")
		worldFolder.Name, worldFolder.Parent = "PhantomWorldGuides", workspace
		local session = { folder = folder, worldFolder = worldFolder, markers = {}, badgeAt = 0 }
		App.railsSession = session
		App.railsLine = App.railsLine ~= false
		App.railsTracking = App.railsTracking or "auto"
		table.insert(App.cleanups, function()
			Rails.clear(session)
		end)
		Rails.watch(session, generation)
		while active(generation) do
			if os.clock() >= session.badgeAt then
				session.badgeAt = os.clock() + 15
				if verify(current, true) == true then
					return true, "Dead Rails' Hollow badge earned"
				end
			end
			local targets, live, danger = Rails.targets(session), {}, 0
			table.sort(targets, function(a, b)
				if a.priority ~= b.priority then
					return a.priority < b.priority
				end
				if a.danger ~= b.danger then
					return not a.danger
				end
				return a.distance < b.distance
			end)
			for i, target in ipairs(targets) do
				if i > 64 then
					break
				end
				live[target.object] = true
				Rails.marker(session, target)
				if target.danger then
					danger = danger + 1
				end
			end
			for object, marker in pairs(session.markers) do
				if not live[object] then
					marker.gui:Destroy()
					marker.highlight:Destroy()
					session.markers[object] = nil
				end
			end
			local objective = Storage:GetAttribute("PhantomObjective")
			Rails.guidance(session, targets, objective)
			status(
				"Phantom Train helpers",
				(Rails.hints[objective] or "Enter a Dead Rails run and find the Phantom stain.")
					.. string.format(
						"\n%d event markers | %d threats marked. Movement and combat are yours.",
						math.min(#targets, 64),
						danger
					),
				0
			)
			if not pause(0.5, generation) then
				break
			end
		end
		return false, "Helpers stopped"
	end
	runners.rails = Rails.run
end

do
	local Home = {}
	Home.steps = { "watcher", "inspector", "hallwayChase", "mimic" }
	Home.throwTasks =
		{ cleanChildrenRoom = true, cleanGuestBedroom = true, clearParentRoom = true, cleanPoolTable = true }
	Home.tapTasks = { watcher = true, washDishes = true, washBathroom = true, cleanWindow = true }
	Home.itemTasks = {
		mop = { "soakWater", "soakBasementWater" },
		dish = { "washDishes" },
		sponge = { "washBathroom" },
		sprayBottle = { "cleanKitchen" },
		waterCan = { "waterPlants" },
		coffeeBean = { "startCaffeeMaker" },
		pan = { "cookTomorrowsLunch" },
		pasta = { "cookTomorrowsLunch" },
		tshirt = { "clearParentRoom", "cleanGuestBedroom", "cleanClothes" },
		clothesPile = { "cleanClothes" },
		colaBoxes = { "fillMiniFridge" },
		waterBottlePack = { "fillMiniFridge" },
	}
	function Home.read(session, scope, key)
		local reader = session.values["read" .. scope]
		if type(reader) ~= "function" then
			return nil
		end
		local ok, value
		if scope == "Player" then
			ok, value = pcall(reader, App.player, key)
		else
			ok, value = pcall(reader, key)
		end
		if ok then
			return value
		end
		return nil
	end
	function Home.itemTask(item, tasks, preferred)
		if type(item) ~= "string" or type(tasks) ~= "table" then
			return nil
		end
		local ids = Home.itemTasks[item]
		if item == "basketBall" or item == "carToy" or item:match("^crayon") then
			ids = { "cleanChildrenRoom" }
		elseif item:match("^poolBall%d+$") then
			ids = { "cleanPoolTable" }
		end
		if preferred and tasks[preferred] == false and table.find(ids or {}, preferred) then
			return preferred
		end
		for _, id in ipairs(ids or {}) do
			if tasks[id] == false then
				return id
			end
		end
		return nil
	end
	function Home.attributes(object)
		local data = object:GetAttributes()
		for _, child in ipairs(object:GetChildren()) do
			if child:IsA("StyleDerive") then
				for key, value in pairs(child:GetAttributes()) do
					data[key] = value
				end
			end
		end
		return data
	end
	function Home.visible(object)
		if not object or not object.Parent then
			return false
		end
		while object do
			if
				object:IsA("GuiObject") and not object.Visible
				or object:IsA("LayerCollector") and not object.Enabled
			then
				return false
			end
			object = object.Parent
		end
		return true
	end
	function Home.mode(session)
		local mode = Home.read(session, "Internal", "camera_state")
		if type(mode) == "string" and mode ~= "" then
			return mode
		end
		local gui = App.player and App.player:FindFirstChild("PlayerGui")
		for _, pair in ipairs({ { "CameraMain", "camera" }, { "CustomCameraMain", "custom" } }) do
			for _, object in ipairs(Collection:GetTagged(pair[1])) do
				local ui = object:IsA("GuiObject") and object or object.Parent
				if gui and ui and ui:IsA("GuiObject") and ui:IsDescendantOf(gui) and Home.visible(ui) then
					return pair[2]
				end
			end
		end
		return "normal"
	end
	function Home.normal(session)
		return not Home.read(session, "Internal", "cinematic") and Home.mode(session) == "normal"
	end
	function Home.press(button, generation)
		local gui = App.player and App.player:FindFirstChild("PlayerGui")
		if
			not active(generation)
			or not gui
			or not button
			or not button:IsA("GuiButton")
			or not button:IsDescendantOf(gui)
			or not Home.visible(button)
		then
			return false
		end
		if type(firesignal) == "function" then
			local ok, result = pcall(firesignal, button.Activated)
			if ok and result ~= false then
				return true
			end
		end
		local point, size = button.AbsolutePosition, button.AbsoluteSize
		return size.X > 0
			and size.Y > 0
			and pcall(function()
				local manager = game:GetService("VirtualInputManager")
				local inset = game:GetService("GuiService"):GetGuiInset()
				local x, y = point.X + size.X / 2 + inset.X, point.Y + size.Y / 2 + inset.Y
				local ok, why = pcall(manager.SendMouseButtonEvent, manager, x, y, 0, true, game, 0)
				pcall(manager.SendMouseButtonEvent, manager, x, y, 0, false, game, 0)
				if not ok then
					error(why)
				end
			end)
	end
	function Home.exitCamera(session, generation)
		EventInput.release(session)
		if Home.normal(session) then
			session.exitAt, session.exitTries = nil, nil
			return true
		end
		if Home.read(session, "Internal", "cinematic") or os.clock() < (session.exitAt or 0) then
			return false
		end
		session.exitAt = os.clock() + 1
		session.exitTries = (session.exitTries or 0) + 1
		local tag = Home.mode(session) == "camera" and "CameraExit" or "CloseCustomCamera"
		for _, object in ipairs(Collection:GetTagged(tag)) do
			local button = object:IsA("GuiButton") and object or object.Parent
			if Home.press(button, generation) then
				break
			end
		end
		return Home.normal(session)
	end
	function Home.infer(item, tasks, preferred)
		local data, prompt = item.data, item.prompt
		if type(data.taskId) == "string" then
			return data.taskId
		end
		local id = Home.itemTask(data.spawnItem or data.enableRequirement or data.disableRequirement, tasks, preferred)
		if id then
			return id
		end
		local name = (prompt:GetFullName() .. " " .. (prompt.ObjectText or "")):lower()
		if name:find("musicbox", 1, true) or name:find("music box", 1, true) then
			return "watcher"
		elseif name:find("dish", 1, true) then
			return "washDishes"
		elseif name:find("mop", 1, true) or name:find("puddle", 1, true) then
			return Home.itemTask("mop", tasks, preferred)
		end
		for word in name:gmatch("[%w_]+") do
			for _, toy in ipairs({
				"basketBall",
				"carToy",
				"crayonBk",
				"crayonBox",
				"crayonBu",
				"crayonG",
				"crayonJ",
				"crayonV",
			}) do
				if word == toy:lower() then
					return "cleanChildrenRoom"
				end
			end
		end
		return nil
	end
	function Home.count(steps)
		local count = 0
		for _, id in ipairs(Home.steps) do
			if type(steps) == "table" and steps[id] == true then
				count = count + 1
			end
		end
		return count
	end
	function Home.hide(session, danger, generation)
		local _, root = character()
		if not root or not danger then
			return false
		end
		local candidates = Collection:GetTagged("HiddenCornerPositions")
		local best, score
		for _, object in ipairs(candidates) do
			if object:IsDescendantOf(workspace) then
				if object:IsA("StyleDerive") then
					object = object.Parent
				end
				local points = object:IsA("Folder") and object:GetChildren() or { object }
				for _, pointObject in ipairs(points) do
					local point = EventInput.point(pointObject)
					if point then
						local distance = (point - danger).Magnitude
						local value = distance - (point - root.Position).Magnitude * 0.05
						if not score or value > score then
							best, score = point, value
						end
					end
				end
			end
		end
		if best and (root.Position - best).Magnitude > 4 and os.clock() >= (session.evadeAt or 0) then
			session.evadeAt = os.clock() + 1
			return approach(best, generation)
		end
		return best ~= nil
	end
	function Home.hallway(session, generation)
		local monster = workspace:FindFirstChild("werewolf")
		local point = EventInput.point(monster)
		local model, root = character()
		if not point or not model or root.Anchored then
			session.chase = nil
			return false
		end
		if not session.chase or session.chase.monster ~= monster then
			session.chase = { monster = monster, phase = "approach", started = os.clock(), origin = point }
		end
		local chase = session.chase
		local chasing = (point - chase.origin).Magnitude > 0.5
		local animator = monster:FindFirstChildWhichIsA("Animator", true)
		if animator then
			local ok, tracks = pcall(animator.GetPlayingAnimationTracks, animator)
			if ok then
				for _, track in ipairs(tracks) do
					if track.Animation and tostring(track.Animation.AnimationId):find("129098856846204", 1, true) then
						chasing = true
					end
				end
			end
		end
		if chasing then
			chase.phase = "escape"
		end
		if chase.phase == "approach" and os.clock() < (chase.aimAt or 0) then
			return true
		end
		if chase.phase == "approach" and os.clock() - chase.started > 20 then
			session.chase = nil
			return false
		end
		if chase.phase == "approach" then
			local anchors = Collection:GetTagged("WerewolfChasePart")
			local anchor = anchors[1]
			for _, zone in ipairs(Collection:GetTagged("zone")) do
				if zone:GetAttribute("zoneName") == "hallway" and zone.Parent and zone.Parent:IsA("BasePart") then
					anchor = zone.Parent
					break
				end
			end
			if anchor and anchor:IsA("BasePart") then
				local landing = anchor.Position
				if (landing - point).Magnitude < 10 then
					landing = landing - anchor.CFrame.LookVector * 12
				end
				if not approach(landing, generation) then
					return true
				end
			end
			local camera = workspace.CurrentCamera
			local previous, own = camera and camera.CFrame, nil
			local epoch = App.cameraEpoch
			local untilTime = os.clock() + 0.5
			while
				camera
				and active(generation)
				and os.clock() < untilTime
				and not App.cameraBusy
				and epoch == App.cameraEpoch
			do
				if own and camera.CFrame ~= own then
					previous = camera.CFrame
				end
				own = CFrame.lookAt(camera.CFrame.Position, point)
				camera.CFrame = own
				if not pause(0.03, generation) then
					break
				end
			end
			if camera and own and camera.CFrame == own and not App.cameraBusy and epoch == App.cameraEpoch then
				camera.CFrame = previous
			end
			chase.aimAt = os.clock() + 1
			status("Starting the hallway encounter", "Looking at the Werewolf from inside the hallway", App.progress)
			return true
		end
		Home.hide(session, point, generation)
		status("Surviving the hallway chase", "Getting away from the Werewolf", App.progress)
		return true
	end
	function Home.prompts(session)
		local out, seen = {}, {}
		local intro = workspace:FindFirstChild("intro")
		local function add(prompt, data, tag)
			if
				prompt
				and prompt:IsA("ProximityPrompt")
				and prompt.Enabled
				and prompt:IsDescendantOf(workspace)
				and (not intro or not prompt:IsDescendantOf(intro))
			then
				local item = seen[prompt]
				if not item then
					item = { prompt = prompt, data = Home.attributes(prompt), tags = {} }
					seen[prompt] = item
					out[#out + 1] = item
				end
				for key, value in pairs(data or {}) do
					item.data[key] = value
				end
				item.tags[tag] = true
			end
		end
		for _, tag in ipairs({ "Custom_Prompt", "TaskPrompt", "MainDoorPrompt", "ComputerPrompt", "LightSwitchPrompt" }) do
			for _, object in ipairs(Collection:GetTagged(tag)) do
				add(object:IsA("ProximityPrompt") and object or object.Parent, Home.attributes(object), tag)
			end
		end
		return out
	end
	function Home.choose(session, root, tasks, visitor)
		local choice
		local visitorState = Home.read(session, "Global", "visitor_state")
		local held = Home.read(session, "Player", "item")
		for _, item in ipairs(Home.prompts(session)) do
			local prompt, data = item.prompt, item.data
			local point = EventInput.point(prompt.Parent)
			local text = (prompt.ObjectText .. " " .. prompt.ActionText .. " " .. prompt:GetFullName()):lower()
			local taskId = Home.infer(item, tasks, session.job and session.job.id)
			item.id = taskId
			local rank = (taskId == "watcher" or text:find("music", 1, true)) and -1000 or 0
			local valid = taskId and type(tasks) == "table" and tasks[taskId] == false
			item.role = "task"
			if session.job and session.job.id ~= taskId then
				valid = false
			end
			if
				data.enableRequirement and data.enableRequirement ~= held
				or data.disableRequirement and data.disableRequirement == held
				or held
					and not data.enableRequirement
					and (data.spawnItem or data.stepId == "take" or text:find("pick up", 1, true))
			then
				valid = false
			end
			if held and data.enableRequirement == held then
				rank -= 500
			end
			if text:find("reset", 1, true) or text:find("buy", 1, true) or text:find("purchase", 1, true) then
				valid = false
			end
			if item.tags.ComputerPrompt then
				valid = false
			end
			if item.tags.LightSwitchPrompt then
				item.role = "light"
				valid = not session.job
					and visitor
					and visitor.isAnomaly
					and visitorState == "knock"
					and text:find("off", 1, true) ~= nil
				rank = -1500
			end
			if item.tags.MainDoorPrompt or text:find("maindoor", 1, true) or text:find("main door", 1, true) then
				item.role = "visitor"
				if not session.job and visitor and visitorState == "knock" then
					valid = true
					rank = rank - 500
					if visitor.isAnomaly and (text:find("open", 1, true) or text:find("accept", 1, true)) then
						valid = false
					end
					if not visitor.isAnomaly and (text:find("reject", 1, true) or text:find("refuse", 1, true)) then
						valid = false
					end
				else
					valid = false
				end
			end
			if point and valid and os.clock() >= (session.retryAt[prompt] or 0) then
				item.point, item.score = point, rank + (point - root.Position).Magnitude
				if not choice or item.score < choice.score then
					choice = item
				end
			end
		end
		return choice
	end
	function Home.interact(session, item, generation)
		local prompt = item.prompt
		local function allowed()
			local model, root = character()
			return active(generation)
				and model == session.character
				and root
				and (not root.Anchored or session.prompt == prompt)
				and prompt.Parent
				and prompt.Enabled
				and Home.normal(session)
		end
		if not allowed() then
			return false
		end
		if not approach(item.point, generation, nil, false, allowed) then
			return false
		end
		local ok = EventInput.hold(session, prompt, generation, allowed, { customCamera = true, keepLook = true })
		EventInput.release(session)
		session.retryAt[prompt] = os.clock() + math.max(2, prompt.HoldDuration + 1)
		return ok
	end
	function Home.detector(session, job)
		local _, root = character()
		local camera = workspace.CurrentCamera
		local found, score
		for _, object in ipairs(Collection:GetTagged("TaskDetector")) do
			local detector = object:IsA("ClickDetector") and object or object.Parent
			if
				detector
				and detector:IsA("ClickDetector")
				and detector:IsDescendantOf(workspace)
				and detector.MaxActivationDistance > 0
			then
				local data = Home.attributes(object)
				local point = EventInput.point(detector.Parent)
				local same = data.taskId == job.id
					or not data.taskId and job.source and detector:IsDescendantOf(job.source)
				if not data.taskId and point and job.anchor and camera then
					same = same
						or (point - job.anchor).Magnitude < 18 and (point - camera.CFrame.Position).Magnitude < 18
				end
				if same and point and root and (point - root.Position).Magnitude <= detector.MaxActivationDistance then
					local distance = camera and (point - camera.CFrame.Position).Magnitude
						or (point - root.Position).Magnitude
					if detector == job.detector then
						distance -= 100
					end
					if not score or distance < score then
						found, score = detector, distance
					end
				end
			end
		end
		job.detector = found
		return found
	end
	function Home.click(session, job, generation, held)
		if not active(generation) or Home.read(session, "Internal", "cinematic") then
			return false
		end
		if os.clock() < (job.clickAt or 0) then
			return true
		end
		job.clickAt = os.clock() + (Home.throwTasks[job.id] and 0.2 or 0.05)
		if job.id == "watcher" or Home.throwTasks[job.id] and held then
			return session.events and type(session.events.fire) == "function" and pcall(session.events.fire, "click")
		end
		local detector = Home.detector(session, job)
		if not detector then
			return false
		end
		if type(fireclickdetector) == "function" then
			local ok, result = pcall(fireclickdetector, detector)
			if ok and result ~= false then
				return true
			end
		end
		local camera, point = workspace.CurrentCamera, EventInput.point(detector.Parent)
		if not camera or not point then
			return false
		end
		local screen, visible = camera:WorldToScreenPoint(point)
		if not visible then
			return false
		end
		return pcall(function()
			local manager = game:GetService("VirtualInputManager")
			local ok, why = pcall(manager.SendMouseButtonEvent, manager, screen.X, screen.Y, 0, true, game, 0)
			pcall(manager.SendMouseButtonEvent, manager, screen.X, screen.Y, 0, false, game, 0)
			if not ok then
				error(why)
			end
		end)
	end
	function Home.adoptCamera(session, tasks)
		local camera, _, root = workspace.CurrentCamera, character()
		if not camera or not root then
			return nil
		end
		local held = Home.read(session, "Player", "item")
		local heldId = Home.itemTask(held, tasks)
		if heldId and Home.tapTasks[heldId] then
			local job = { id = heldId, anchor = root.Position }
			if Home.detector(session, job) then
				return job
			end
		end
		for _, item in ipairs(Home.prompts(session)) do
			local id = Home.infer(item, tasks)
			local pose = item.data.cframe
			if
				id
				and tasks
				and tasks[id] == false
				and Home.tapTasks[id]
				and typeof(pose) == "CFrame"
				and (pose.Position - camera.CFrame.Position).Magnitude < 5
			then
				return { id = id, anchor = EventInput.point(item.prompt.Parent), source = item.prompt.Parent }
			end
		end
		return nil
	end
	function Home.light(session, visitor)
		if os.clock() < (session.lightAt or 0) then
			return session.lightTarget
		end
		session.lightAt, session.lightTarget = os.clock() + 0.25, nil
		local state = Home.read(session, "Global", "visitor_state")
		if not visitor or not visitor.isAnomaly or (state ~= "knock" and state ~= "idle") then
			return nil
		end
		for _, item in ipairs(Home.prompts(session)) do
			if item.tags.LightSwitchPrompt and (item.prompt.ActionText or ""):lower():find("off", 1, true) then
				item.role, item.point = "light", EventInput.point(item.prompt.Parent)
				session.lightTarget = item
				return item
			end
		end
		return nil
	end
	function Home.step(session, tasks, visitor, generation)
		if not active(generation) then
			return nil, "Stopped"
		end
		local model, root = character()
		if not model then
			EventInput.release(session)
			return 0.12
		end
		if session.character and session.character ~= model then
			EventInput.release(session)
			session.job, session.utility, session.exitAt, session.exitTries = nil, nil, nil, nil
		end
		session.character = model
		local function note(text)
			status(session.title, text, session.progress or App.progress)
		end
		if Home.read(session, "Internal", "cinematic") then
			EventInput.release(session)
			note("Waiting for the scene to finish")
			return 0.12
		end
		if type(tasks) ~= "table" then
			EventInput.release(session)
			note("Waiting for the house tasks to load")
			return 0.2
		end
		local mode, held = Home.mode(session), Home.read(session, "Player", "item")
		local job = session.job
		if job and job.id and type(tasks) == "table" and tasks[job.id] ~= false then
			job.finished = true
		end
		local light = Home.light(session, visitor)
		if mode ~= "normal" then
			if not job and mode == "custom" and not light then
				job = Home.adoptCamera(session, tasks)
				if job then
					job.started, job.cameraOwned = os.clock(), true
					session.job = job
				end
			end
			if job and mode == "custom" and not job.finished and not light then
				job.cameraOwned = job.cameraOwned or os.clock() < (job.cameraExpectedUntil or 0)
				if job.cameraOwned then
					job.pending, job.retryTarget = nil, nil
					job.tapStarted = job.tapStarted or os.clock()
					note(session.labels[job.id] or "Finishing this task")
					if Home.tapTasks[job.id] then
						if Home.click(session, job, generation, held) then
							job.noInputAt = nil
						else
							job.noInputAt = job.noInputAt or os.clock()
							if os.clock() - job.noInputAt > 8 then
								return nil, "Couldn't tap this task's control. Press Start to retry."
							end
						end
					end
					if os.clock() - job.tapStarted > 120 then
						return nil, "This task isn't finishing. Stopped here so nothing else gets started."
					end
					return 0.05
				end
			end
			note("Leaving the camera view")
			Home.exitCamera(session, generation)
			if (session.exitTries or 0) >= 8 and not Home.normal(session) then
				return nil, "Couldn't close the camera view. Close it, then press Start."
			end
			return 0.1
		end
		session.exitAt, session.exitTries = nil, nil
		if session.utility then
			local pending = session.utility
			if
				not pending.prompt.Parent
				or not pending.prompt.Enabled
				or pending.prompt.ActionText ~= pending.action
				or Home.read(session, "Global", "visitor_state") ~= pending.state
			then
				session.utility, session.lightTarget, session.lightAt = nil, nil, 0
				session.progressAt = os.clock()
			elseif os.clock() - pending.at > 6 then
				return nil, "That interaction didn't finish. Stopped before trying anything else."
			end
			return 0.12
		end
		if light then
			note("Turning off the lights")
			local action, state = light.prompt.ActionText, Home.read(session, "Global", "visitor_state")
			if Home.interact(session, light, generation) then
				session.utility = { prompt = light.prompt, action = action, state = state, at = os.clock() }
			end
			return 0.12
		end
		if job and job.finished then
			EventInput.release(session)
			session.job, session.progressAt = nil, os.clock()
			return 0.12
		end
		if job then
			job.cameraOwned, job.tapStarted = nil, nil
			if held ~= job.held then
				job.held, job.lastProgress = held, os.clock()
				session.progressAt = os.clock()
			end
			if job.pending then
				local pending = job.pending
				if
					held ~= pending.held
					or not pending.pickup
						and (not pending.prompt.Parent or not pending.prompt.Enabled or pending.prompt.ActionText ~= pending.action)
				then
					job.pending, job.retryTarget, job.rejects, job.lastProgress = nil, nil, 0, os.clock()
					session.progressAt = os.clock()
				elseif os.clock() - pending.at < (pending.pickup and 8 or 5) then
					note("Waiting for this step to finish")
					return 0.12
				else
					if pending.pickup then
						return nil, "The picked-up item hasn't arrived. Stopped before grabbing another."
					end
					job.retryTarget = pending.target
					job.pending = nil
					job.rejects = (job.rejects or 0) + 1
					if job.rejects >= 3 then
						return nil, "This task isn't responding. Stopped before starting another one."
					end
				end
			end
			if Home.throwTasks[job.id] and held and Home.itemTask(held, tasks, job.id) == job.id then
				note(session.labels[job.id] or "Putting this item away")
				Home.click(session, job, generation, held)
				if os.clock() - (job.lastProgress or job.started) > 30 then
					return nil, "This item hasn't been put away. Stopped before picking up another."
				end
				return 0.05
			end
			if os.clock() - (job.lastProgress or job.started) > 180 then
				return nil, "This task is stuck. Stopped here so another task won't interrupt it."
			end
		end
		if not job and held then
			local id = Home.itemTask(held, tasks)
			if id then
				job = { id = id, started = os.clock(), lastProgress = os.clock(), held = held }
				session.job = job
				return 0.05
			end
			note("Put down the held item before starting another task")
			return 0.2
		end
		if root.Anchored or App.cameraBusy then
			return 0.12
		end
		local target = job and job.retryTarget
		if target and (not target.prompt.Parent or not target.prompt.Enabled) then
			job.retryTarget, target = nil, nil
		end
		target = target or Home.choose(session, root, tasks, visitor)
		if not target then
			note(
				job and (session.labels[job.id] or "Waiting for this task's next step")
					or "Waiting for the next task or visitor"
			)
			return 0.12
		end
		if not job and target.id then
			job = { id = target.id, started = os.clock(), lastProgress = os.clock(), held = held }
			session.job = job
		end
		if job then
			job.anchor, job.source = target.point, target.prompt.Parent
			job.cameraExpectedUntil = os.clock() + 5
		end
		note(
			job and (session.labels[job.id] or "Finishing this task")
				or ((target.prompt.ActionText or "") .. " " .. (target.prompt.ObjectText or ""))
		)
		local action, visitorState = target.prompt.ActionText, Home.read(session, "Global", "visitor_state")
		local ok = Home.interact(session, target, generation)
		if not active(generation) then
			return nil, "Stopped"
		end
		if job then
			if
				ok
				or Home.mode(session) ~= "normal"
				or Home.read(session, "Player", "item") ~= held
				or not target.prompt.Parent
			then
				job.pending = {
					target = target,
					prompt = target.prompt,
					action = action,
					held = held,
					at = os.clock(),
					pickup = target.data.spawnItem ~= nil
						or target.data.stepId == "take"
						or target.data.disableRequirement ~= nil and target.data.enableRequirement == nil
						or (action or ""):lower():find("pick", 1, true) ~= nil,
				}
			else
				job.rejects = (job.rejects or 0) + 1
				if job.rejects >= 3 then
					return nil, "Couldn't start this task. Stopped before trying another one."
				end
			end
		elseif ok then
			session.utility = { prompt = target.prompt, action = action, state = visitorState, at = os.clock() }
		end
		return 0.12
	end
	function Home.run(generation)
		status("Loading Home Alone", "Waiting for the event data", 0)
		local object = waitUntil(function()
			return getPath(Storage, "Utils", "Value", "Client")
		end, 60, generation)
		local values = object and module(object, generation)
		local registryObject = getPath(Storage, "Utils", "Registry", "Client")
		local registry = registryObject and module(registryObject, generation)
		if not values or not registry then
			return false, "Home Alone's game data hasn't loaded. Press Start to retry."
		end
		local session = { values = values, retryAt = {}, badgeAt = 0, progressAt = os.clock(), labels = {} }
		local taskData = module(getPath(Storage, "Data", "Tasks"), generation)
		for id, data in pairs(taskData and taskData.tasks or {}) do
			session.labels[id] = data.displayText
		end
		table.insert(App.cleanups, function()
			EventInput.release(session)
			if
				App.player.Character == session.character
				and session.job
				and session.job.cameraOwned
				and Home.mode(session) == "custom"
				and not Home.read(session, "Internal", "cinematic")
			then
				session.exitAt = 0
				Home.exitCamera(session)
			end
		end)
		local eventObject = getPath(Storage, "Utils", "Event")
		local events = eventObject and module(eventObject, generation)
		session.events = events
		local visitorObject = getPath(Storage, "Client", "VisitorClient")
		local visitors = visitorObject and module(visitorObject, generation)
		if events and type(events.connect) == "function" then
			local ok, connection = pcall(events.connect, "inspectorLook", function(data)
				if active(generation) and type(data) == "table" then
					session.inspectorWindow = data.window
				end
			end)
			if ok and connection then
				table.insert(App.cleanups, function()
					if type(connection.disconnect) == "function" then
						connection:disconnect()
					elseif type(connection.Disconnect) == "function" then
						connection:Disconnect()
					end
				end)
			end
		end
		local initialMatch = waitUntil(function()
			local ok, value = pcall(registry.readLocalEntry, "teleportData", "isMatch")
			return ok and type(value) == "boolean" and { value = value }
		end, 60, generation)
		if not initialMatch then
			return false, "The house's session data hasn't arrived yet. Press Start to retry."
		end
		local previous
		while active(generation) do
			local delay = 0.12
			local steps = Home.read(session, "Owner", "theHollowSteps")
			local count = Home.count(steps)
			if os.clock() >= session.badgeAt then
				session.badgeAt = os.clock() + 12
				if verify(current, true) == true then
					return true, "Home Alone's Hollow badge earned"
				end
			end
			if count ~= previous then
				previous, session.progressAt = count, os.clock()
			end
			local ok, isMatch = pcall(registry.readLocalEntry, "teleportData", "isMatch")
			if not ok or isMatch ~= true then
				return false, "Join a Night 1 story run, then press Start inside the house."
			end
			if count == 4 then
				status("All four encounters finished", "Waiting for the saved Hollow badge", 0.98)
			else
				local tasks = Home.read(session, "Global", "tasks")
				local visitor
				if visitors and type(visitors.get) == "function" then
					local good, value = pcall(visitors.get)
					if good then
						visitor = value
					end
				end
				local model, root = character()
				local cinematic = Home.read(session, "Internal", "cinematic")
				local title = "Home Alone | " .. count .. " / 4 encounters"
				session.title = title
				session.progress = count / 4
				if cinematic then
					EventInput.release(session)
					status(title, "Waiting for the game's scene to finish", count / 4)
				elseif not Home.normal(session) or session.utility or Home.light(session, visitor) then
					local why
					delay, why = Home.step(session, tasks, visitor, generation)
					if not delay then
						return false, why
					end
				elseif
					model
					and not root.Anchored
					and (not steps or steps.hallwayChase ~= true)
					and Home.hallway(session, generation)
				then
				elseif
					visitor
					and tostring(visitor.visitorId):lower():find("inspector", 1, true)
					and Home.read(session, "Global", "visitor_state") == "idle"
					and model
					and not root.Anchored
				then
					local danger = EventInput.point(session.inspectorWindow) or EventInput.point(visitor.model)
					status(title, "Staying clear of the Inspector's windows", count / 4)
					if danger then
						Home.hide(session, danger, generation)
					end
				else
					local why
					delay, why = Home.step(session, tasks, visitor, generation)
					if not delay then
						return false, why
					end
				end
			end
			if os.clock() - session.progressAt > 600 then
				return false, "Progress hasn't changed for a while. Check the current task, then try Start again."
			end
			if not pause(delay, generation) then
				break
			end
		end
		return false, "Stopped"
	end
	runners.home = Home.run
end

do
	-- arcade guides
	local ArcadeGuide = {}
	ArcadeGuide.spacing, ArcadeGuide.arrowLimit, ArcadeGuide.markerLimit = 7, 40, 32
	function ArcadeGuide.current(state)
		return App.alive and App.arcadeGuideState == state and not state.closed
	end
	function ArcadeGuide.notice(state, text)
		if ArcadeGuide.current(state) and App.arcadeGuideText ~= text then
			App.arcadeGuideText = text
			refresh()
		end
	end
	function ArcadeGuide.carrying()
		local state = App.arcadeGuideState
		for _, slot in ipairs({ "HandItem", "BackItem" }) do
			local event = state and state.inventory and state.inventory[slot]
			local item = event
					and event.model == App.player.Character
					and event.match == Storage:FindFirstChild("ArcadeMatch")
					and event.item
				or App.player:GetAttribute(slot)
			if item == "PAYLOAD" then
				return true
			end
		end
		return false
	end
	App.arcadeHasGas = ArcadeGuide.carrying
	function ArcadeGuide.inventory(state)
		local remote = getPath(Storage, "ArcadeRemotes", "Inventory")
		if state.inventoryRemote == remote or not remote or not remote:IsA("RemoteEvent") then
			return
		end
		if state.inventoryConnection then
			state.inventoryConnection:Disconnect()
		end
		state.inventory = state.inventory or {}
		state.connections = state.connections or {}
		state.inventoryRemote = remote
		state.inventoryConnection = remote.OnClientEvent:Connect(function(slot, _, item)
			local key = slot == "hand" and "HandItem" or slot == "back" and "BackItem"
			if not key or type(item) ~= "string" or not ArcadeGuide.current(state) then
				return
			end
			state.inventory[key] =
				{ item = item, model = App.player.Character, match = Storage:FindFirstChild("ArcadeMatch") }
			pcall(ArcadeGuide.tick, state)
		end)
		state.connections[#state.connections + 1] = state.inventoryConnection
	end
	function ArcadeGuide.targets(root)
		local out, seen = {}, {}
		local function add(object, generator)
			if seen[object] or not object:IsDescendantOf(workspace) then
				return
			end
			local body = object:IsA("BasePart") and object or object:FindFirstChild("GeneratorVolume")
			if not body or not body:IsA("BasePart") then
				return
			end
			local prompt = body:FindFirstChildOfClass("ProximityPrompt")
			local state = generator and object:GetAttribute("GenState")
			if generator then
				if state ~= "live" and state ~= "full" then
					return
				end
			elseif
				object:GetAttribute("Kind") ~= "payload"
				or object:GetAttribute("Flying") == true
				or object:GetAttribute("Thrown") == true
				or not prompt
				or not prompt.Enabled
			then
				return
			end
			seen[object] = true
			out[#out + 1] = {
				object = object,
				body = body,
				prompt = prompt,
				generator = generator,
				full = state == "full",
				usable = state ~= "full" and (generator or prompt ~= nil and prompt:GetAttribute("Blocked") ~= true),
				distance = (body.Position - root.Position).Magnitude,
			}
		end
		for _, object in ipairs(Collection:GetTagged("Generator")) do
			add(object, true)
		end
		local items = workspace:FindFirstChild("ArcadeItems")
		for _, object in ipairs(items and items:GetChildren() or {}) do
			add(object, false)
		end
		table.sort(out, function(a, b)
			if a.generator ~= b.generator then
				return a.generator
			end
			return a.distance < b.distance
		end)
		return out
	end
	function ArcadeGuide.choices(state, entries, carrying)
		local choices = {}
		local retry = {}
		for _, entry in ipairs(entries) do
			if entry.generator == carrying and entry.usable then
				local list = state.rejected and (state.rejected[entry.object] or 0) > os.clock() and retry or choices
				list[#list + 1] = entry
			end
		end
		if #choices == 0 then
			choices = retry
		end
		table.sort(choices, function(a, b)
			return a.distance < b.distance
		end)
		return choices
	end
	function ArcadeGuide.color(entry)
		return entry.full and Color3.fromRGB(145, 155, 162)
			or entry.generator and Color3.fromRGB(255, 190, 80)
			or Color3.fromRGB(91, 231, 230)
	end
	function ArcadeGuide.clearRoute(state)
		state.epoch = state.epoch + 1
		local request = state.busy
		state.busy = nil
		if request then
			request.cancelled = true
			if request.path then
				pcall(request.path.Destroy, request.path)
			end
		end
		local route = state.route
		state.route = nil
		ArcadeGuide.dispose(route)
		for _, arrow in ipairs(state.arrows) do
			ArcadeGuide.hide(arrow)
		end
	end
	function ArcadeGuide.hide(arrow)
		if arrow.hidden then
			return
		end
		arrow.hidden = true
		for index, part in ipairs(arrow) do
			part.Transparency = 1
			if arrow.faces and arrow.faces[index] then
				arrow.faces[index].gui.Enabled = false
			end
		end
	end
	function ArcadeGuide.dispose(route)
		if route then
			if route.connection then
				pcall(route.connection.Disconnect, route.connection)
			end
			if route.path then
				pcall(route.path.Destroy, route.path)
			end
		end
	end
	function ArcadeGuide.clear(state)
		if not state or state.closed then
			return
		end
		state.closed = true
		if App.arcadeGuideState == state then
			App.arcadeGuideState = nil
		end
		pcall(ArcadeGuide.clearRoute, state)
		for _, connection in ipairs(state.connections or {}) do
			pcall(connection.Disconnect, connection)
		end
		state.connections = {}
		if state.folder then
			pcall(state.folder.Destroy, state.folder)
			state.folder = nil
		end
	end
	function ArcadeGuide.markers(state, entries)
		local visible = {}
		if App.arcadeEsp then
			for i = 1, math.min(#entries, ArcadeGuide.markerLimit) do
				local entry = entries[i]
				visible[entry.object] = true
				local marker = state.markers[entry.object]
				if not marker then
					local highlight = Instance.new("Highlight")
					highlight.Name, highlight.Adornee = "ArcadeTarget", entry.object
					highlight.DepthMode, highlight.FillTransparency, highlight.OutlineTransparency =
						Enum.HighlightDepthMode.AlwaysOnTop, 0.82, 0
					highlight.Parent = state.folder
					local gui = Instance.new("BillboardGui")
					gui.Name, gui.Adornee, gui.Size = "ArcadeLabel", entry.body, UDim2.fromOffset(190, 48)
					gui.AlwaysOnTop, gui.LightInfluence, gui.MaxDistance = true, 0, 3000
					gui.StudsOffsetWorldSpace = Vector3.new(0, 4, 0)
					gui.Parent = state.folder
					local text = Instance.new("TextLabel")
					text.Size, text.BackgroundTransparency, text.Font = UDim2.fromScale(1, 1), 1, Enum.Font.GothamMedium
					text.TextSize, text.TextStrokeTransparency = 14, 0.25
					text.Parent = gui
					marker = { highlight = highlight, gui = gui, text = text }
					state.markers[entry.object] = marker
				end
				local color = ArcadeGuide.color(entry)
				marker.highlight.FillColor, marker.highlight.OutlineColor, marker.text.TextColor3 = color, color, color
				marker.gui.Adornee = entry.body
				marker.text.Text = (entry.generator and (entry.full and "GENERATOR (FULL)" or "GENERATOR") or "GAS CAN")
					.. string.format("\n%.0f studs", entry.distance)
			end
		end
		for object, marker in pairs(state.markers) do
			if not visible[object] then
				marker.highlight:Destroy()
				marker.gui:Destroy()
				state.markers[object] = nil
			end
		end
	end
	function ArcadeGuide.params(state, target)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		if not state.rayIgnore or os.clock() >= (state.rayAt or 0) or state.rayModel ~= App.player.Character then
			local ignore = { state.folder }
			for _, player in ipairs(Players:GetPlayers()) do
				if player.Character then
					ignore[#ignore + 1] = player.Character
				end
			end
			local dress = getPath(workspace, "Maze", "Corn", "CornDress")
			if dress then
				ignore[#ignore + 1] = dress
			end
			state.rayIgnore, state.rayAt, state.rayModel = ignore, os.clock() + 0.5, App.player.Character
			local _, root = character()
			state.rayGroup = root and root.CollisionGroup
		end
		local ignore = table.clone(state.rayIgnore)
		if target then
			ignore[#ignore + 1] = target
		end
		params.FilterDescendantsInstances, params.IgnoreWater = ignore, true
		pcall(function()
			params.RespectCanCollide = true
			if state.rayGroup then
				params.CollisionGroup = state.rayGroup
			end
		end)
		return params, ignore
	end
	function ArcadeGuide.floor(state, point, target)
		local params, ignore = ArcadeGuide.params(state, target)
		for _ = 1, 6 do
			local hit = workspace:Raycast(point + Vector3.new(0, 5, 0), Vector3.new(0, -24, 0), params)
			if not hit then
				break
			end
			if hit.Normal.Y >= 0.6 and hit.Position.Y <= point.Y + 1.5 and math.abs(hit.Position.Y - point.Y) <= 10 then
				return hit.Position, hit.Normal
			end
			if not hit.Instance or hit.Instance == workspace.Terrain then
				break
			end
			ignore[#ignore + 1] = hit.Instance
			params.FilterDescendantsInstances = ignore
		end
		return nil
	end
	function ArcadeGuide.samples(points)
		local samples = {}
		for i = 1, math.min(#points - 1, 255) do
			local from, to = points[i].Position, points[i + 1].Position
			local delta = to - from
			local flat = Vector3.new(delta.X, 0, delta.Z)
			if flat.Magnitude > 0.1 then
				local steps = math.max(1, math.ceil(flat.Magnitude / ArcadeGuide.spacing))
				for n = 0, steps - 1 do
					if #samples >= 512 then
						return samples
					end
					samples[#samples + 1] =
						{ point = from + delta * (n / steps), direction = flat.Unit, waypoint = i + 1 }
				end
			end
		end
		return samples
	end
	function ArcadeGuide.progress(route, position, visible)
		local candidates = {}
		for i, sample in ipairs(route.samples) do
			local delta = sample.point - position
			local distance = Vector3.new(delta.X, 0, delta.Z).Magnitude
			if
				(not route.blockedAt or sample.waypoint < route.blockedAt)
				and (#candidates < 4 or distance < candidates[#candidates].distance)
			then
				local rank = #candidates + 1
				while rank > 1 and distance < candidates[rank - 1].distance do
					candidates[rank] = candidates[rank - 1]
					rank -= 1
				end
				candidates[rank] = { index = i, distance = distance }
				candidates[5] = nil
			end
		end
		for i = 1, math.min(4, #candidates) do
			local candidate = candidates[i]
			if not visible or visible(route.samples[candidate.index]) then
				route.index = candidate.index
				return candidate.index, candidate.distance, true
			end
		end
		local closest = candidates[1]
		return route.index or 1, closest and closest.distance or math.huge, false
	end
	function ArcadeGuide.sight(state, root, entry, point)
		local params = ArcadeGuide.params(state, entry.object)
		return not workspace:Raycast(root.Position, point + Vector3.new(0, 3, 0) - root.Position, params)
	end
	function ArcadeGuide.passage(state, from, to, entry)
		if math.abs(from.Y - to.Y) > 2 then
			return false
		end
		local middle = ArcadeGuide.floor(state, (from + to) * 0.5, entry.object)
		if not middle or math.abs(middle.Y - (from.Y + to.Y) * 0.5) > 2 then
			return false
		end
		local delta = to - from
		local flat = Vector3.new(delta.X, 0, delta.Z)
		if flat.Magnitude < 0.1 then
			return true
		end
		local side = Vector3.new(-flat.Z, 0, flat.X).Unit
		local params = ArcadeGuide.params(state, entry.object)
		for _, offset in ipairs({
			Vector3.new(0, 1.2, 0),
			Vector3.new(0, 3, 0),
			side + Vector3.new(0, 2.2, 0),
			side * -1 + Vector3.new(0, 2.2, 0),
		}) do
			if workspace:Raycast(from + offset, delta, params) then
				return false
			end
		end
		return true
	end
	function ArcadeGuide.grid(state, entry, origin, valid)
		local from = ArcadeGuide.floor(state, origin, entry.object)
		local goal = ArcadeGuide.floor(state, entry.body.Position, entry.object)
		if not from or not goal then
			return nil
		end
		local cells, heap = {}, {}
		local step, reach = 4, math.clamp((entry.prompt and entry.prompt.MaxActivationDistance or 10) * 0.5, 3, 6)
		local gx, gz = (goal.X - from.X) / step, (goal.Z - from.Z) / step
		local margin = math.min(72, 24 + (state.planFailures or 0) * 16)
		local minX, maxX = math.floor(math.min(0, gx)) - margin, math.ceil(math.max(0, gx)) + margin
		local minZ, maxZ = math.floor(math.min(0, gz)) - margin, math.ceil(math.max(0, gz)) + margin
		local function push(node)
			local value = {
				node = node,
				cost = node.cost,
				score = node.cost + math.abs(node.point.X - goal.X) + math.abs(node.point.Z - goal.Z),
			}
			local i = #heap + 1
			while i > 1 and heap[math.floor(i / 2)].score > value.score do
				heap[i] = heap[math.floor(i / 2)]
				i = math.floor(i / 2)
			end
			heap[i] = value
		end
		local function pop()
			local first = heap[1]
			local last = table.remove(heap)
			if #heap > 0 then
				local i = 1
				while i * 2 <= #heap do
					local child = i * 2
					if child < #heap and heap[child + 1].score < heap[child].score then
						child += 1
					end
					if heap[child].score >= last.score then
						break
					end
					heap[i], i = heap[child], child
				end
				heap[i] = last
			end
			return first
		end
		local start = { x = 0, z = 0, point = from, cost = 0 }
		cells["0:0"] = start
		push(start)
		local count, deadline, sliceAt = 0, os.clock() + 4, os.clock()
		local directions = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
		while #heap > 0 and count < 4096 and os.clock() < deadline do
			if not valid() then
				return nil
			end
			local record = pop()
			local node = record.node
			if node.closed or record.cost ~= node.cost then
				continue
			end
			node.closed = true
			count += 1
			local delta = node.point - goal
			if
				Vector3.new(delta.X, 0, delta.Z).Magnitude <= reach
				and ArcadeGuide.passage(state, node.point, goal, entry)
			then
				local chain, points = {}, {}
				while node do
					chain[#chain + 1] = node.point
					node = node.parent
				end
				for i = #chain, 1, -1 do
					local point = chain[i]
					local length = #points
					if
						length >= 2
						and (points[length].Position - points[length - 1].Position):Cross(
								point - points[length].Position
							).Magnitude
							< 0.01
					then
						points[length] = { Position = point }
					else
						points[length + 1] = { Position = point }
					end
				end
				return #points > 1 and points or nil
			end
			for _, direction in ipairs(directions) do
				local x, z = node.x + direction[1], node.z + direction[2]
				if x < minX or x > maxX or z < minZ or z > maxZ then
					continue
				end
				local key = x .. ":" .. z
				local nextNode = cells[key]
				if nextNode == nil then
					local ground = ArcadeGuide.floor(
						state,
						Vector3.new(from.X + x * step, node.point.Y, from.Z + z * step),
						entry.object
					)
					nextNode = ground and { x = x, z = z, point = ground, cost = math.huge } or false
					cells[key] = nextNode
				end
				local cost = node.cost + step
				if
					nextNode
					and not nextNode.closed
					and cost < nextNode.cost
					and ArcadeGuide.passage(state, node.point, nextNode.point, entry)
				then
					nextNode.cost, nextNode.parent = cost, node
					push(nextNode)
				end
			end
			if count % 24 == 0 or os.clock() - sliceAt >= 0.003 then
				task.wait(0.01)
				sliceAt = os.clock()
			end
		end
		return nil
	end
	function ArcadeGuide.paint(state, entry, samples, start, blockedAt)
		local painted = 0
		local tint = entry.full and "full" or entry.generator and "generator" or "gas"
		for slot = 1, ArcadeGuide.arrowLimit do
			local sample = samples[start + slot - 1]
			if sample and blockedAt and sample.waypoint >= blockedAt then
				sample = nil
			end
			local arrow = state.arrows[slot]
			if sample and (not sample.checked or not sample.ground and os.clock() >= (sample.groundAt or 0)) then
				sample.ground, sample.normal = ArcadeGuide.floor(state, sample.point, entry.object)
				sample.checked = true
				sample.groundAt = os.clock() + 0.4
			end
			if sample and sample.ground then
				if not arrow then
					arrow = { faces = {} }
					for arm = 1, 2 do
						local part = Instance.new("Part")
						part.Name, part.Anchored, part.CanCollide, part.CanTouch, part.CanQuery =
							"RouteArrow", true, false, false, false
						part.CastShadow, part.Material = false, Enum.Material.Neon
						part.Parent = state.folder
						arrow[arm] = part
						if slot <= 16 then
							local gui = Instance.new("SurfaceGui")
							gui.Name, gui.Adornee, gui.Face = "ArrowFace", part, Enum.NormalId.Top
							gui.AlwaysOnTop, gui.LightInfluence, gui.MaxDistance, gui.Active = true, 0, 110, false
							gui.CanvasSize = Vector2.new(16, 64)
							gui.Parent = part
							local strip = Instance.new("Frame")
							strip.Size, strip.BorderSizePixel, strip.Active, strip.Parent =
								UDim2.fromScale(1, 1), 0, false, gui
							arrow.faces[arm] = { gui = gui, strip = strip }
						end
					end
					state.arrows[slot] = arrow
				end
				if
					arrow.ground ~= sample.ground
					or arrow.normal ~= sample.normal
					or arrow.direction ~= sample.direction
				then
					local direction = sample.direction - sample.normal * sample.direction:Dot(sample.normal)
					arrow.ground, arrow.normal, arrow.direction = sample.ground, sample.normal, sample.direction
					arrow.valid = direction.Magnitude > 0.1
					if arrow.valid then
						direction = direction.Unit
						local side = direction:Cross(sample.normal).Unit
						local center = sample.ground + sample.normal * 0.12
						local tip = center + direction * 1.1
						for arm = 1, 2 do
							local tail = center - direction * 0.9 + side * (arm == 1 and 0.95 or -0.95)
							arrow[arm].Size = Vector3.new(0.22, 0.1, (tip - tail).Magnitude)
							arrow[arm].CFrame = CFrame.lookAt((tail + tip) * 0.5, tip, sample.normal)
						end
					end
				end
				if arrow.valid and (arrow.hidden or arrow.tint ~= tint) then
					local color = ArcadeGuide.color(entry)
					for arm = 1, 2 do
						local part = arrow[arm]
						part.Color, part.Transparency = color, 0.05
						local face = arrow.faces and arrow.faces[arm]
						if face then
							face.strip.BackgroundColor3, face.gui.Enabled = part.Color, true
						end
					end
					arrow.hidden, arrow.tint = false, tint
				end
				if arrow.valid then
					painted += 1
				else
					ArcadeGuide.hide(arrow)
				end
			elseif arrow then
				ArcadeGuide.hide(arrow)
			end
		end
		return painted > 0
	end
	function ArcadeGuide.direction(state, root, entry)
		local delta = entry.body.Position - root.Position
		local flat = Vector3.new(delta.X, 0, delta.Z)
		local direction = flat.Magnitude > 0.1 and flat.Unit or Vector3.new(0, 0, 1)
		local point = root.Position + direction * math.min(3, flat.Magnitude * 0.5)
		if not ArcadeGuide.sight(state, root, entry, point - Vector3.new(0, 3, 0)) then
			point = root.Position
		end
		local ground, normal = ArcadeGuide.floor(state, point, entry.object)
		if not ground then
			ground, normal = ArcadeGuide.floor(state, root.Position, entry.object)
		end
		if ground then
			state.lastGround = { point = ground, normal = normal, at = os.clock(), model = App.player.Character }
		else
			local last = state.lastGround
			if
				last
				and last.model == App.player.Character
				and os.clock() - last.at < 1
				and (last.point - root.Position).Magnitude < 8
			then
				ground, normal = last.point, last.normal
			end
		end
		local samples = ground
				and { { point = ground, ground = ground, normal = normal, checked = true, direction = direction } }
			or {}
		ArcadeGuide.paint(state, entry, samples, 1)
	end
	function ArcadeGuide.draw(state, root)
		local route = state.route
		if not route then
			return false
		end
		local start, distance, visible = ArcadeGuide.progress(route, root.Position, function(sample)
			return ArcadeGuide.sight(state, root, route.target, sample.point)
		end)
		route.detached = route.moved
			or distance > 18
			or not visible
			or route.direct
				and not ArcadeGuide.sight(state, root, route.target, route.points[#route.points].Position)
		if route.detached then
			return false
		end
		if route.grid and os.clock() >= (route.checkAt or 0) then
			route.checkAt = os.clock() + 0.5
			for index = start + 1, math.min(start + 4, #route.samples) do
				if
					not ArcadeGuide.passage(
						state,
						route.samples[index - 1].point,
						route.samples[index].point,
						route.target
					)
				then
					route.detached = true
					state.planAt = 0
					return false
				end
			end
		end
		route.waypoint = route.samples[start] and route.samples[start].waypoint or route.waypoint
		return ArcadeGuide.paint(state, route.target, route.samples, start, route.blockedAt)
	end
	function ArcadeGuide.direct(state, root, entry, model, carrying, match)
		local from = ArcadeGuide.floor(state, root.Position, entry.object)
		local to = ArcadeGuide.floor(state, entry.body.Position, entry.object)
		if not from or not to or (to - from).Magnitude > 90 or not ArcadeGuide.passage(state, from, to, entry) then
			return nil
		end
		local points = { { Position = from }, { Position = to } }
		local samples = ArcadeGuide.samples(points)
		for _, sample in ipairs(samples) do
			sample.ground, sample.normal = ArcadeGuide.floor(state, sample.point, entry.object)
			if not sample.ground then
				return nil
			end
			sample.checked = true
		end
		if #samples == 0 then
			return nil
		end
		return {
			direct = true,
			points = points,
			samples = samples,
			index = 1,
			target = entry,
			model = model,
			carrying = carrying,
			match = match,
		}
	end
	function ArcadeGuide.plan(state, choices, model, root, carrying, match)
		if state.busy or (state.requests or 0) >= 4 or #choices == 0 then
			return
		end
		local entry = choices[1]
		local epoch, origin = state.epoch, root.Position
		local useGrid = state.forceGrid or (state.requests or 0) >= 3
		local request = { started = os.clock(), kind = useGrid and "grid" or "native" }
		state.busy = request
		state.requests = (state.requests or 0) + 1
		local function valid()
			return ArcadeGuide.current(state)
				and not request.cancelled
				and state.epoch == epoch
				and App.arcadeArrows
				and App.player.Character == model
				and not App.traveling
				and ArcadeGuide.carrying() == carrying
				and state.target
				and state.target.object == entry.object
				and entry.object:IsDescendantOf(workspace)
				and match.Parent
				and match:GetAttribute("Phase") == "Live"
				and not match:GetAttribute("Cutscene")
				and not App.player:GetAttribute("InCutscene")
				and App.player:GetAttribute("Alive") == true
		end
		task.spawn(function()
			local candidate, result
			local ok = pcall(function()
				if not valid() or useGrid then
					return
				end
				local paths = game:GetService("PathfindingService")
				local goal = entry.body.Position
				local toward = Vector3.new(origin.X - goal.X, 0, origin.Z - goal.Z)
				if toward.Magnitude < 0.1 then
					toward = Vector3.new(0, 0, 1)
				end
				local range = entry.prompt and entry.prompt.MaxActivationDistance or 10
				local radius = math.clamp(range * 0.5, 2, 5)
				for _, offset in ipairs({ toward.Unit * radius, Vector3.zero }) do
					if not valid() then
						return
					end
					local ground = ArcadeGuide.floor(state, goal + offset, entry.object)
					if ground then
						candidate = paths:CreatePath({
							AgentRadius = 1.4,
							AgentHeight = 5,
							AgentCanJump = false,
							AgentCanClimb = false,
							WaypointSpacing = 7,
						})
						request.path = candidate
						local computed = pcall(candidate.ComputeAsync, candidate, origin, ground)
						if computed and valid() and candidate.Status == Enum.PathStatus.Success then
							local points = candidate:GetWaypoints()
							if #points > 1 and #points <= 256 then
								result = {
									path = candidate,
									points = points,
									samples = ArcadeGuide.samples(points),
									index = 1,
									target = entry,
									carrying = carrying,
									model = model,
									match = match,
								}
								candidate = nil
								return
							end
						end
						pcall(candidate.Destroy, candidate)
						candidate = nil
					end
				end
			end)
			if candidate then
				pcall(candidate.Destroy, candidate)
			end
			if valid() and not result then
				request.kind, state.forceGrid = "grid", true
				ok = pcall(function()
					local points = ArcadeGuide.grid(state, entry, origin, valid)
					if points then
						result = {
							grid = true,
							points = points,
							samples = ArcadeGuide.samples(points),
							index = 1,
							target = entry,
							carrying = carrying,
							model = model,
							match = match,
						}
					end
				end)
			end
			if state.busy == request then
				state.busy = nil
			end
			request.path = nil
			state.requests = math.max(0, (state.requests or 1) - 1)
			if not ok or not valid() or not result or #result.samples == 0 then
				ArcadeGuide.dispose(result)
				if valid() then
					state.planFailures = (state.planFailures or 0) + 1
					state.planAt = os.clock() + 1
					if state.planFailures >= 2 and (not state.route or state.route.detached) then
						state.rejected = state.rejected or setmetatable({}, { __mode = "k" })
						state.rejected[entry.object] = os.clock() + 8
					end
				end
				return
			end
			ArcadeGuide.dispose(state.route)
			state.route = result
			state.planFailures = 0
			state.planAt = os.clock() + 0.5
			if result.path and result.path.Blocked then
				result.connection = result.path.Blocked:Connect(function(index)
					if ArcadeGuide.current(state) and state.route == result and index >= (result.waypoint or 1) then
						result.blockedAt = math.min(result.blockedAt or math.huge, index)
						state.planAt = 0
					end
				end)
			end
		end)
	end
	function ArcadeGuide.tick(state)
		ArcadeGuide.inventory(state)
		local request = state.busy
		if request and request.kind == "native" and os.clock() - request.started >= 2 then
			request.cancelled = true
			if request.path then
				pcall(request.path.Destroy, request.path)
			end
			state.busy, state.forceGrid, state.planAt = nil, true, 0
		end
		local match = Storage:FindFirstChild("ArcadeMatch")
		local model, root = character()
		if
			not match
			or not model
			or App.player:GetAttribute("Alive") ~= true
			or match:GetAttribute("Phase") ~= "Live"
			or match:GetAttribute("Finale")
			or match:GetAttribute("Cutscene")
			or App.traveling
			or App.player:GetAttribute("InCutscene")
			or App.player:GetAttribute("DeathScreen")
			or App.player:GetAttribute("ResultsCamera")
		then
			ArcadeGuide.clearRoute(state)
			state.target = nil
			ArcadeGuide.markers(state, {})
			ArcadeGuide.notice(state, "Gas and generator guides appear during a live Arcade round.")
			return
		end
		local entries = ArcadeGuide.targets(root)
		if os.clock() >= (state.markersAt or 0) then
			ArcadeGuide.markers(state, entries)
			state.markersAt = os.clock() + 0.35
		end
		local carrying = ArcadeGuide.carrying()
		local choices = ArcadeGuide.choices(state, entries, carrying)
		local target
		if state.target and state.carrying == carrying and state.model == model and state.match == match then
			for _, entry in ipairs(choices) do
				if entry.object == state.target.object then
					target = entry
					break
				end
			end
		end
		target = target or choices[1]
		local changed = not target
			or not state.target
			or target.object ~= state.target.object
			or carrying ~= state.carrying
			or model ~= state.model
			or match ~= state.match
		if changed then
			ArcadeGuide.clearRoute(state)
			state.planAt, state.directAt = 0, 0
			state.planFailures = 0
		end
		state.target, state.carrying, state.model, state.match = target, carrying, model, match
		if not App.arcadeArrows then
			ArcadeGuide.notice(state, "Arrows are off. Blue = gas, yellow = generators, gray = full.")
			return
		end
		if not target then
			ArcadeGuide.notice(
				state,
				carrying and "Waiting for a generator that still needs gas." or "Looking for another gas can"
			)
			return
		end
		if state.route then
			state.route.target = target
			state.route.moved = (target.body.Position - state.route.points[#state.route.points].Position).Magnitude > 14
			if state.route.moved then
				state.route.detached = true
			end
		end
		if
			(not state.route or state.route.detached or state.route.blockedAt)
			and os.clock() >= (state.directAt or 0)
		then
			state.directAt = os.clock() + 0.4
			local direct = ArcadeGuide.direct(state, root, target, model, carrying, match)
			if direct then
				ArcadeGuide.dispose(state.route)
				state.route = direct
			end
		end
		local range = target.prompt and target.prompt.MaxActivationDistance or 10
		local arrived = target.distance <= math.max(6, range * 0.7)
		local walking = not arrived and ArcadeGuide.draw(state, root)
		if not walking then
			ArcadeGuide.direction(state, root, target)
		end
		if
			not state.busy
			and not arrived
			and os.clock() >= (state.planAt or 0)
			and (not state.route or state.route.detached or state.route.blockedAt)
		then
			ArcadeGuide.plan(state, { target }, model, root, carrying, match)
		end
		local name = carrying and "generator" or "gas can"
		ArcadeGuide.notice(
			state,
			arrived and (carrying and "Hold the generator prompt to deliver the gas." or "Pick up this gas can.")
				or string.format(
					"%s arrows to a %s (%.0f studs). %s",
					carrying and "AMBER" or "CYAN",
					name,
					target.distance,
					walking and "Follow the arrows through the maze."
						or (state.planFailures or 0) > 0 and "Checking another way around."
						or "Finding a path through the maze..."
				)
		)
	end
	function App.clearArcadeGuide()
		ArcadeGuide.clear(App.arcadeGuideState)
	end
	function App.startArcadeGuide()
		if
			not App.alive
			or not App.player
			or not current
			or current.id ~= "arcade"
			or game.PlaceId ~= current.eventPlace
			or not (App.arcadeArrows or App.arcadeEsp)
			or App.arcadeGuideState
		then
			return
		end
		local state = { markers = {}, arrows = {}, connections = {}, epoch = 0 }
		local folder = Instance.new("Folder")
		folder.Name, folder.Parent = "HollowArcadeGuides", workspace
		state.folder = folder
		App.arcadeGuideState = state
		if type(App.player.GetAttributeChangedSignal) == "function" then
			for _, name in ipairs({ "HandItem", "BackItem" }) do
				state.connections[#state.connections + 1] = App.player
					:GetAttributeChangedSignal(name)
					:Connect(function()
						if ArcadeGuide.current(state) then
							if state.inventory then
								state.inventory[name] = nil
							end
							pcall(ArcadeGuide.tick, state)
						end
					end)
			end
		end
		pcall(ArcadeGuide.tick, state)
		task.spawn(function()
			while ArcadeGuide.current(state) do
				local ok, why = pcall(ArcadeGuide.tick, state)
				if not ok then
					ArcadeGuide.notice(state, "Finding the route again...")
					if os.clock() >= (state.errorAt or 0) then
						log("Arcade guide: " .. tostring(why):sub(1, 180))
						state.errorAt = os.clock() + 15
					end
				end
				task.wait(0.12)
			end
			ArcadeGuide.clear(state)
		end)
	end
	function App.setArcadeVisual(option, enabled)
		local key = option == "arrows" and "arcadeArrows" or option == "esp" and "arcadeEsp"
		if not key then
			return
		end
		App[key] = enabled == nil and not App[key] or enabled == true
		local state = App.arcadeGuideState
		if state and key == "arcadeArrows" then
			ArcadeGuide.clearRoute(state)
			state.planAt = 0
		end
		if state and key == "arcadeEsp" then
			state.markersAt = 0
		end
		if not App.arcadeArrows and not App.arcadeEsp then
			App.clearArcadeGuide()
			App.arcadeGuideText = "Ground arrows and gas/generator visuals are off."
		else
			App.startArcadeGuide()
		end
		refresh()
	end
end

-- lanterns + event guides
do
	local Event7 = {}
	local amber = Color3.fromRGB(255, 191, 78)
	local red = Color3.fromRGB(255, 100, 114)
	local mint = Color3.fromRGB(116, 224, 179)

	function Event7.part(object)
		if not object or not object:IsDescendantOf(workspace) then
			return nil
		end
		if object:IsA("BasePart") then
			return object
		end
		if object:IsA("Attachment") then
			return Event7.part(object.Parent)
		end
		if object:IsA("Model") and object.PrimaryPart then
			return object.PrimaryPart
		end
		return object:FindFirstChildWhichIsA("BasePart", true)
	end

	function Event7.torch()
		local model = App.player and App.player.Character
		local backpack = App.player and App.player:FindFirstChild("Backpack")
		local tool = model and model:FindFirstChild("Torch") or backpack and backpack:FindFirstChild("Torch")
		return tool and tool:IsA("Tool") and tool or nil
	end

	function Event7.lit(part, accepted)
		return accepted and accepted[part] == true
			or part.Material == Enum.Material.Neon
			or part:FindFirstChildOfClass("PointLight") ~= nil
	end

	function Event7.pumpkins(accepted)
		local list = {}
		for _, part in ipairs(Collection:GetTagged("%JackOLantern")) do
			if
				part:IsA("BasePart")
				and part:IsDescendantOf(workspace)
				and part:GetAttribute(tostring(App.player.UserId))
				and not Event7.lit(part, accepted)
			then
				table.insert(list, { object = part, part = part, title = "Unlit pumpkin", color = amber })
			end
		end
		return list
	end

	function Event7.closest(list, blocked)
		local _, root = character()
		local best, distance
		if not root then
			return nil
		end
		for _, item in ipairs(list) do
			if
				item.part
				and item.part:IsDescendantOf(workspace)
				and (not blocked or (blocked[item.object] or 0) <= os.clock())
			then
				local gap = (item.part.Position - root.Position).Magnitude
				if not distance or gap < distance then
					best, distance = item, gap
				end
			end
		end
		return best
	end

	function Event7.interact(session, prompt, generation, allowed)
		local part = prompt and Event7.part(prompt.Parent)
		if not part or not prompt.Enabled then
			return false
		end
		local moved = approach(part.Position, generation, nil, nil, allowed, { settleSeconds = 0.12 })
		if not moved or not active(generation) then
			return false
		end
		return EventInput.hold(session, prompt, generation, allowed)
	end

	function Event7.touch(part, generation)
		local _, root = character()
		if
			not active(generation)
			or not root
			or not part.Parent
			or part.CanTouch == false
			or (root.Position - part.Position).Magnitude > 8
			or type(firetouchinterest) ~= "function"
		then
			return false
		end
		local began = pcall(firetouchinterest, root, part, 0)
		if began then
			pause(0.05, generation)
			pcall(firetouchinterest, root, part, 1)
		end
		return began and active(generation)
	end

	function Bridge.lanternsCompleted()
		for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
			if tonumber(number) == 7 then
				return true
			end
		end
		return false
	end

	function Bridge.solveLanterns(_, _, generation)
		local session = { accepted = {}, blocked = {} }
		table.insert(App.cleanups, function()
			EventInput.release(session)
		end)
		for _, name in ipairs({ "Brazier", "JackOLantern" }) do
			local loaded, why = hollowModule(name, generation)
			if not loaded then
				return false, why
			end
		end
		while active(generation) do
			if App.player:GetAttribute("HasRelic") == true then
				return true
			end
			if App.player:GetAttribute("InMaze") ~= 7 then
				return false, "The floor changed. Start again inside floor 7."
			end
			local tool = Event7.torch()
			local model, _, humanoid = character()
			if session.model ~= model then
				session.model, session.accepted, session.blocked = model, {}, {}
			end
			if tool and model and tool.Parent ~= model then
				pcall(humanoid.EquipTool, humanoid, tool)
				pause(0.2, generation)
			end
			if not model then
				status("Waiting to respawn", "", 0.1)
			elseif not tool or tool:GetAttribute("Lit") ~= true then
				status("Getting a lit torch", "", 0.1)
				local braziers = {}
				for _, part in ipairs(Collection:GetTagged("%Brazier")) do
					if Event7.part(part) then
						table.insert(braziers, { object = part, part = Event7.part(part) })
					end
				end
				local nextBrazier = Event7.closest(braziers, session.blocked)
				if nextBrazier then
					local part = nextBrazier.part
					local prompt = part:FindFirstChildWhichIsA("ProximityPrompt", true)
					if prompt then
						Event7.interact(session, prompt, generation)
					else
						approach(part.Position, generation)
					end
					local got = waitUntil(function()
						local torch = Event7.torch()
						return torch and torch:GetAttribute("Lit") == true
					end, 1.5, generation)
					if not got and active(generation) then
						local _, root = character()
						local remote = part:FindFirstChild("LightRemote")
						if root and (root.Position - part.Position).Magnitude <= 10 then
							fire(remote)
						end
					end
					session.blocked[nextBrazier.object] = os.clock() + 3
				end
			else
				local pumpkins = Event7.pumpkins(session.accepted)
				local nextPumpkin = Event7.closest(pumpkins, session.blocked)
				status("Lighting pumpkins", #pumpkins .. " unlit nearby", 0.35)
				if nextPumpkin then
					local part = nextPumpkin.part
					local allowed = function()
						local now = Event7.torch()
						return App.player:GetAttribute("InMaze") == 7
							and now
							and now.Parent == App.player.Character
							and now:GetAttribute("Lit") == true
							and part.Parent
							and part:GetAttribute(tostring(App.player.UserId))
					end
					local prompt = part:FindFirstChildWhichIsA("ProximityPrompt", true)
					if prompt then
						Event7.interact(session, prompt, generation, allowed)
					else
						approach(part.Position, generation, nil, nil, allowed)
					end
					local lit = waitUntil(function()
						return Event7.lit(part, session.accepted)
					end, 1, generation)
					if not lit and active(generation) and allowed() then
						local _, root = character()
						local remote = part:FindFirstChild("LightRemote")
						if
							remote
							and remote:IsA("RemoteFunction")
							and root
							and (root.Position - part.Position).Magnitude <= 10
						then
							local ok, result = invoke(remote, generation)
							if ok and result == true then
								session.accepted[part] = true
							end
						end
					end
					session.blocked[part] = os.clock() + 3
				end
			end
			pause(0.35, generation)
		end
		return false, "Stopped"
	end

	-- banana
	function Event7.bananaState()
		local properties = workspace:FindFirstChild("GameProperties")
		local quest = getPath(App.player, "UserDataHolder", "HollowQuest")
		if not properties or not quest or not quest:IsA("BoolValue") then
			return nil
		end
		local function value(name)
			local object = properties:FindFirstChild(name)
			return object and object.Value
		end
		return {
			unlocked = quest.Value == true,
			playing = value("GameBegan") == true,
			escape = value("GameBegan") == true and value("EscapeSignal") == true,
			team = App.player.Team and App.player.Team.Name or "",
			map = getPath(workspace, "GameKeeper", "Map"),
		}
	end

	function Event7.bananaControl(object, limit)
		local scope, detector, targetPart = object, nil, nil
		for _ = 1, 4 do
			if not scope or scope == limit then
				break
			end
			local prompt = scope:FindFirstChildWhichIsA("ProximityPrompt", true)
			if prompt and EventInput.point(prompt.Parent) then
				return prompt, nil, Event7.part(prompt.Parent)
			end
			local click = scope:FindFirstChildWhichIsA("ClickDetector", true)
			local part = click and Event7.part(click.Parent)
			if part and not detector then
				detector, targetPart = click, part
			end
			scope = scope.Parent
		end
		return nil, detector, targetPart or Event7.part(object)
	end

	function Event7.bananaItems()
		if game.PlaceId == 105438027287525 then
			return Event7.basementItems()
		end
		local list, state = {}, Event7.bananaState()
		if not state then
			return list
		end
		if state.playing and state.team == "Runners" and not state.unlocked then
			local items = state.map and state.map:FindFirstChild("Items")
			for _, object in ipairs(Collection:GetTagged("HollowKey")) do
				if state.map and object:IsDescendantOf(state.map) then
					local prompt, click, part = Event7.bananaControl(object, items or state.map)
					local _, root = character()
					local keyPart = Event7.part(object)
					if part and keyPart and (not root or math.abs(keyPart.Position.Y - root.Position.Y) <= 60) then
						table.insert(list, {
							object = object,
							part = part,
							prompt = prompt,
							click = click,
							title = "Hollow key",
							color = amber,
							kind = "key",
						})
					end
				end
			end
		end
		if state.escape and state.team == "Runners" then
			local exits = getPath(workspace, "GameKeeper", "Exits")
			for _, object in ipairs(exits and exits:GetChildren() or {}) do
				local part = object:FindFirstChild("Trigger", true)
					or object:FindFirstChild("Hitbox", true)
					or object:FindFirstChild("Door", true)
					or Event7.part(object)
				part = Event7.part(part)
				if part then
					table.insert(list, { object = object, part = part, title = "Escape", color = mint, kind = "exit" })
				end
			end
		end
		if state.unlocked and state.team == "Lobby" then
			local doors = getPath(workspace, "HollowQuestHolder", "HollowDoorsHolder")
			local door = doors and doors:FindFirstChild("Door_Open")
			local prompt = door and door:FindFirstChildWhichIsA("ProximityPrompt", true)
			local part = prompt and Event7.part(prompt.Parent)
			if part then
				table.insert(
					list,
					{ object = door, part = part, prompt = prompt, title = "Red door", color = red, kind = "redDoor" }
				)
			end
		end
		return list
	end

	function Event7.bananas()
		local list, seen, instances = {}, {}, {}
		local function add(object, rendered)
			if not object or instances[object] or rendered and seen[object.Name] then
				return
			end
			local humanoid = object:FindFirstChildWhichIsA("Humanoid")
			if humanoid and humanoid.Health <= 0 then
				return
			end
			local part = object:FindFirstChild("HumanoidRootPart")
				or object:FindFirstChild("RootPart")
				or Event7.part(object)
			if part and part:IsA("BasePart") and part:IsDescendantOf(workspace) then
				seen[object.Name], instances[object] = true, true
				table.insert(list, { object = object, part = part, title = "Banana", color = red, kind = "threat" })
			end
		end
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= App.player and player.Team and player.Team.Name == "Banana" then
				add(player.Character)
			end
		end
		for _, name in ipairs({ "GameBots", "GameBananas" }) do
			local holder = workspace:FindFirstChild(name)
			for _, object in ipairs(holder and holder:GetChildren() or {}) do
				add(object, name == "GameBananas")
			end
		end
		return list
	end

	function Event7.clearance(point, threats)
		local distance = math.huge
		for _, item in ipairs(threats) do
			distance = math.min(distance, (point - item.part.Position).Magnitude)
		end
		return distance
	end

	function Event7.heldKey(model)
		local item = model and model:FindFirstChild("Item")
		if not item then
			return false
		end
		local name = item:FindFirstChild("ItemName", true)
		return name and name:IsA("StringValue") and name.Value == "HollowKey"
			or item:FindFirstChild("HollowKey", true) ~= nil
	end

	function Event7.bananaSafeSpot(session, state, threats)
		local model, root = character()
		if not root or not state.map then
			return nil
		end
		local points = {}
		for _, name in ipairs({ "RunnerSpawns", "TokenSpawns" }) do
			local holder = state.map:FindFirstChild(name)
			for index, object in ipairs(holder and holder:GetChildren() or {}) do
				if index > 64 then
					break
				end
				local part = Event7.part(object)
				if part then
					table.insert(points, part.Position)
				end
			end
		end
		for _, point in ipairs(session.safePoints or {}) do
			table.insert(points, point)
		end
		for _, item in ipairs(Event7.bananaItems()) do
			table.insert(points, item.part.Position)
		end
		for _, radius in ipairs({ 45, 90, 125 }) do
			for angle = 0, 7 do
				local yaw = angle * math.pi / 4
				table.insert(points, root.Position + Vector3.new(math.cos(yaw) * radius, 0, math.sin(yaw) * radius))
			end
		end
		local params = RaycastParams.new()
		local excluded = { model }
		for _, item in ipairs(threats) do
			table.insert(excluded, item.object)
		end
		for _, player in ipairs(Players:GetPlayers()) do
			if player.Character and player.Character ~= model then
				table.insert(excluded, player.Character)
			end
		end
		params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, excluded
		params.RespectCanCollide, params.IgnoreWater = true, true
		local currentGap = Event7.clearance(root.Position, threats)
		local best, bestScore, rays = nil, nil, 0
		for _, point in ipairs(points) do
			if rays >= 32 then
				break
			end
			if Event7.clearance(point, threats) < math.min(65, currentGap + 18) then
				continue
			end
			rays += 1
			local hit = workspace:Raycast(point + Vector3.new(0, 10, 0), Vector3.new(0, -40, 0), params)
			if
				hit
				and hit.Instance
				and hit.Normal.Y > 0.65
				and math.abs(hit.Position.Y - root.Position.Y) <= 12
				and hit.Position.Y > workspace.FallenPartsDestroyHeight + 32
			then
				local landing = hit.Position + Vector3.new(0, 3, 0)
				local gap = Event7.clearance(landing, threats)
				local score = gap - (landing - root.Position).Magnitude * 0.05
				if gap > currentGap + 15 and (not bestScore or score > bestScore) then
					best, bestScore = landing, score
				end
			end
		end
		return best
	end

	function Event7.evadeBanana(session, state, generation)
		local model, root = character()
		if not root or root.Anchored or not state.playing or state.team ~= "Runners" then
			return false
		end
		local threats = Event7.bananas()
		local gap = Event7.clearance(root.Position, threats)
		if gap >= 60 then
			if gap < math.huge and os.clock() >= (session.rememberAt or 0) then
				session.rememberAt = os.clock() + 2
				session.safePoints = session.safePoints or {}
				if #session.safePoints >= 8 then
					table.remove(session.safePoints, 1)
				end
				table.insert(session.safePoints, root.Position)
			end
			return false
		end
		if os.clock() < (session.evadeAt or 0) then
			return false
		end
		session.evadeAt = os.clock() + 0.4
		EventInput.release(session)
		local point = Event7.bananaSafeSpot(session, state, threats)
		if not point then
			return false
		end
		status("Moving away from Banana", "", 0.3)
		return approach(point, generation, nil, nil, function()
			local latest = Event7.bananaState()
			return App.player.Character == model
				and latest
				and latest.playing
				and latest.team == "Runners"
				and latest.map == state.map
				and Event7.clearance(point, Event7.bananas()) > 45
		end, { streamSeconds = 0.1, streamWait = 0.25, settleSeconds = 0.05 })
	end

	function Event7.bananaUse(session, item, generation, allowed, fallback)
		local function ready()
			local _, root = character()
			return active(generation)
				and root
				and not root.Anchored
				and item.object:IsDescendantOf(workspace)
				and item.part.Parent
				and (not allowed or allowed())
		end
		if not ready() then
			return false
		end
		local moved = approach(
			item.part.Position,
			generation,
			nil,
			nil,
			ready,
			{ streamSeconds = 0.15, streamWait = 0.35, settleSeconds = 0.08 }
		)
		if not moved or not ready() then
			return false
		end
		if item.kind == "key" and Event7.heldKey(App.player.Character) then
			return true
		end
		local prompt, click = item.prompt, item.click
		if prompt and prompt.Parent and prompt.Enabled then
			local used = EventInput.hold(session, prompt, generation, ready)
			if used and fallback and ready() and type(fireproximityprompt) == "function" then
				if Event7.face(session, item.part) and pause(0.06, generation) and ready() then
					local ok, result = call(prompt, function()
						if ready() then
							return fireproximityprompt(prompt, prompt.HoldDuration)
						end
						return false
					end, prompt.HoldDuration + 2, generation)
					used = ok and result ~= false
				else
					used = false
				end
				EventInput.release(session)
			end
			return used
		elseif click and click.Parent then
			local _, root = character()
			if not root or (root.Position - item.part.Position).Magnitude > (click.MaxActivationDistance or 12) then
				return false
			end
			if not Event7.face(session, item.part) then
				return false
			end
			if not pause(0.06, generation) or not ready() then
				EventInput.release(session)
				return false
			end
			local ok = false
			if type(fireclickdetector) == "function" then
				ok = pcall(fireclickdetector, click)
			end
			EventInput.release(session)
			return ok
		end
		return Event7.touch(item.part, generation)
	end

	function Event7.pollBananaBadge(session, generation)
		if session.badgeBusy or os.clock() < (session.badgeAt or 0) then
			return
		end
		session.badgeBusy, session.badgeAt = true, os.clock() + 15
		local force = session.forceBadge
		session.forceBadge = nil
		task.spawn(function()
			local ok, owned = pcall(verify, current, force)
			if active(generation) and not session.closed then
				session.badge = ok and owned == true
			end
			session.badgeBusy = false
		end)
	end

	-- basement
	function Event7.basementState()
		local holder = workspace:FindFirstChild("HollowCakesHolder")
		local count = holder and holder:FindFirstChild("CakeCollected")
		local cake = holder and getPath(holder, "CakePuzzle", "Cake")
		local goal = 0
		for _, part in ipairs(cake and cake:GetChildren() or {}) do
			if part:IsA("BasePart") and tonumber(part.Name) then
				goal += 1
			end
		end
		if not holder or not count or type(count.Value) ~= "number" or goal < 1 then
			return nil
		end
		return { holder = holder, count = count.Value, goal = goal }
	end

	function Event7.basementItems(finished)
		local state, list = Event7.basementState(), {}
		if not state then
			return list
		end
		if state.count < state.goal and not finished then
			local slices = state.holder:FindFirstChild("CakeSlices")
			for _, object in ipairs(slices and slices:GetChildren() or {}) do
				local prompt, click, part = Event7.bananaControl(object, slices)
				if part and ((prompt and prompt.Enabled) or click) then
					table.insert(list, {
						object = object,
						part = part,
						prompt = prompt,
						click = click,
						title = "Cake slice",
						color = amber,
						kind = "cake",
					})
				end
			end
		else
			local object = workspace:FindFirstChild("Badge_Giver")
			local part = object and object:FindFirstChild("Root")
			if part and part:IsA("BasePart") then
				table.insert(
					list,
					{ object = object, part = part, title = "Hollow reward", color = mint, kind = "badge" }
				)
			end
		end
		return list
	end

	function Event7.basementReady()
		local model, root, humanoid = character()
		local camera = workspace.CurrentCamera
		local frame = getPath(App.player, "PlayerGui", "EffectGui", "CutsceneFrame")
		return model
			and not root.Anchored
			and humanoid.WalkSpeed > 0
			and camera
			and camera.CameraType ~= Enum.CameraType.Scriptable
			and not (frame and frame.Visible)
	end

	function Event7.runBasement(session, generation)
		local watch, connection, countAt, scan = nil, nil, 0, 0
		table.insert(App.cleanups, function()
			if connection then
				connection:Disconnect()
			end
		end)
		while active(generation) do
			Event7.pollBananaBadge(session, generation)
			if not active(generation) then
				break
			end
			if session.badge then
				return true, "Hollow badge earned"
			end
			local state = Event7.basementState()
			if not state then
				status("Loading Banana's Basement", "Waiting for the cake puzzle", 0.85)
			else
				local model = character()
				if session.model ~= model then
					session.model, session.pendingCake, session.blocked = model, nil, {}
				end
				if watch ~= state.holder then
					if connection then
						connection:Disconnect()
					end
					watch, connection, session.ending = state.holder, nil, false
				end
				local cue = watch:FindFirstChild("CueEnd")
				if not connection and cue and cue:IsA("RemoteEvent") then
					connection = cue.OnClientEvent:Connect(function()
						if active(generation) then
							session.ending = true
							EventInput.release(session)
						end
					end)
				end
				if not Event7.basementReady() then
					status("Watching the basement ending", "", 0.95)
				elseif state.count >= state.goal or session.ending then
					if not session.completionKnown then
						session.completionKnown, session.forceBadge, session.badgeAt = true, true, 0
					end
					countAt = countAt == 0 and os.clock() or countAt
					status("Collecting the Hollow reward", "Waiting for badge credit", 0.98)
					if os.clock() - countAt > 3 then
						local reward = Event7.closest(Event7.basementItems(true), session.blocked)
						if reward then
							if Event7.bananaUse(session, reward, generation, Event7.basementReady) then
								session.forceBadge, session.badgeAt = true, os.clock() + 0.5
							end
							session.blocked[reward.object] = os.clock() + 5
						end
					end
				else
					local pending = session.pendingCake
					if pending then
						if state.count > pending.count or not pending.object:IsDescendantOf(workspace) then
							session.pendingCake = nil
						elseif os.clock() - pending.at < 2 then
							status("Picking up the cake", "Waiting for it to count", 0.85)
							pause(0.1, generation)
							continue
						else
							session.pendingCake = nil
							session.blocked[pending.object] = nil
						end
					end
					local items = Event7.basementItems()
					local item = Event7.closest(items, session.blocked)
					status(
						"Collecting cake slices",
						state.count .. " / " .. state.goal,
						0.8 + state.count / state.goal * 0.12
					)
					if item then
						local used = Event7.bananaUse(session, item, generation, function()
							local latest = Event7.basementState()
							return Event7.basementReady()
								and latest
								and latest.holder == state.holder
								and latest.count == state.count
								and not session.ending
						end, (session.attempts[item.object] or 0) > 0)
						session.attempts[item.object] = (session.attempts[item.object] or 0) + 1
						session.blocked[item.object] = os.clock() + (used and 2 or 1)
						if used then
							session.pendingCake = { object = item.object, count = state.count, at = os.clock() }
						end
					elseif #items == 0 and os.clock() >= (session.scanAt or 0) and not session.ending then
						session.scanAt, scan = os.clock() + 2, scan % 7 + 1
						local areas = {
							{ 660.5, 15.1, 72.3 },
							{ 649.6, 18.2, 58.9 },
							{ 671.6, 19.2, 70.5 },
							{ 714.2, 15.4, 15.1 },
							{ 632.7, 15.1, 146.6 },
							{ 653.4, 15.2, 106.6 },
							{ 690.6, 18.2, 115.7 },
						}
						approach(
							Vector3.new(table.unpack(areas[scan])),
							generation,
							nil,
							nil,
							Event7.basementReady,
							{ streamSeconds = 0.2, streamWait = 0.4, settleSeconds = 0.1 }
						)
					end
				end
			end
			if not pause(0.15, generation) then
				break
			end
		end
		return false, "Stopped"
	end

	function Event7.runBanana(generation)
		local session = { blocked = {}, attempts = {} }
		table.insert(App.cleanups, function()
			session.closed = true
			EventInput.release(session)
		end)
		if game.PlaceId == 105438027287525 then
			return Event7.runBasement(session, generation)
		end
		local joinAt, doorAt = 0, 0
		while active(generation) do
			Event7.pollBananaBadge(session, generation)
			if not active(generation) then
				break
			end
			if session.badge then
				return true, "Hollow badge earned"
			end
			local state, model, root = Event7.bananaState(), character()
			if not state or not root or root.Anchored then
				status("Loading Banana Eats", "Waiting for your round data", 0)
			elseif state.unlocked and state.team == "Lobby" then
				status("Entering the red door", "", 0.8)
				local door = Event7.closest(Event7.bananaItems())
				if door and os.clock() >= doorAt then
					doorAt = os.clock() + 15
					prepareTravel(105438027287525, true)
					Event7.bananaUse(session, door, generation, function()
						local latest = Event7.bananaState()
						return latest and latest.unlocked and latest.team == "Lobby"
					end, (session.attempts[door.object] or 0) > 0)
					session.attempts[door.object] = (session.attempts[door.object] or 0) + 1
				end
			elseif state.team == "Runners" and state.playing then
				if session.model ~= model or session.map ~= state.map then
					session.model, session.map, session.pending = model, state.map, nil
					session.blocked, session.attempts, session.safePoints = {}, {}, {}
				end
				if Event7.evadeBanana(session, state, generation) then
					pause(0.1, generation)
					continue
				end
				local holding = Event7.heldKey(model) or state.unlocked
				local pending = session.pending
				if pending then
					if holding or not pending.object:IsDescendantOf(workspace) or os.clock() - pending.at >= 2 then
						session.pending = nil
					else
						status("Picking up the Hollow key", "Waiting for the pickup to count", 0.25)
						pause(0.1, generation)
						continue
					end
				end
				local candidates, threats = {}, Event7.bananas()
				for _, item in ipairs(Event7.bananaItems()) do
					if
						(item.kind == "exit" and holding or item.kind == "key" and not holding)
						and Event7.clearance(item.part.Position, threats) > 45
					then
						table.insert(candidates, item)
					end
				end
				local item = Event7.closest(candidates, session.blocked)
				if item then
					status(
						item.kind == "key" and "Getting the Hollow key" or "Leaving the round",
						"",
						holding and 0.65 or 0.2
					)
					local used = Event7.bananaUse(session, item, generation, function()
						local latest, nowModel, nowRoot = Event7.bananaState(), character()
						return latest
							and latest.playing
							and latest.team == "Runners"
							and latest.map == state.map
							and nowModel == model
							and nowRoot
							and Event7.clearance(nowRoot.Position, Event7.bananas()) > 35
							and Event7.clearance(item.part.Position, Event7.bananas()) > 35
					end, (session.attempts[item.object] or 0) > 0)
					session.attempts[item.object] = (session.attempts[item.object] or 0) + 1
					session.blocked[item.object] = os.clock() + (used and 2 or 1)
					if used and item.kind == "key" then
						session.pending = { object = item.object, at = os.clock() }
					end
				else
					status(
						holding and "Surviving with the key" or "Looking for a safe key",
						holding and "Waiting for an open exit" or "",
						holding and 0.5 or 0.1
					)
				end
			elseif state.team == "Banana" then
				status("You're Banana this round", "Waiting for the next survivor round", 0.1)
			else
				session.pending, session.map = nil, nil
				status("Waiting for a survivor round", "Find a Hollow key, survive, then enter the red door", 0.05)
				if os.clock() >= joinAt then
					joinAt = os.clock() + 10
					local gui = App.player:FindFirstChild("PlayerGui")
					local afk = gui and gui:FindFirstChild("AFKLabel", true)
					local events = Storage:FindFirstChild("Events")
					if afk and afk:IsA("GuiObject") and afk.Visible then
						invoke(events and events:FindFirstChild("ActiveToggle"), generation)
					end
					if active(generation) then
						invoke(events and events:FindFirstChild("JoinRequest"), generation)
					end
				end
			end
			if not pause(0.1, generation) then
				break
			end
		end
		return false, "Stopped"
	end

	-- shawarma
	function Event7.eventTarget(object)
		if not object or not object:IsDescendantOf(workspace) then
			return false
		end
		local halloween = workspace:FindFirstChild("Halloween")
		if halloween and object:IsDescendantOf(halloween) then
			return true
		end
		local text = object:IsA("ProximityPrompt") and string.lower(object.ActionText .. " " .. object.ObjectText) or ""
		return text:find("breach", 1, true) ~= nil or text:find("hollow", 1, true) ~= nil
	end

	function Event7.shawarmaIndex()
		if Event7.index then
			return Event7.index
		end
		local index = { prompts = {}, connections = {} }
		Event7.index = index
		local function add(object)
			if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then
				index.prompts[object] = true
			end
		end
		table.insert(index.connections, workspace.DescendantAdded:Connect(add))
		table.insert(
			index.connections,
			workspace.DescendantRemoving:Connect(function(object)
				index.prompts[object] = nil
			end)
		)
		for count, object in ipairs(workspace:GetDescendants()) do
			if Event7.index ~= index or not App.alive then
				return index
			end
			add(object)
			if count % 400 == 0 then
				task.wait()
			end
		end
		return index
	end

	function Event7.shawarmaItems()
		local list = {}
		for object in pairs(Event7.shawarmaIndex().prompts) do
			local enabled = object:IsA("ClickDetector") or object.Enabled
			local part = enabled and Event7.eventTarget(object) and Event7.part(object.Parent)
			if part then
				table.insert(
					list,
					{ object = object, part = part, kind = "prompt", title = "Hollow interaction", color = mint }
				)
			end
		end
		for _, object in ipairs(Collection:GetTagged("canHold")) do
			local part = Event7.eventTarget(object) and Event7.part(object)
			if part then
				table.insert(
					list,
					{ object = object, part = part, kind = "hold", title = "Hollow breach", color = amber }
				)
			end
		end
		return list
	end

	function Event7.face(session, part)
		EventInput.endLook(session)
		local camera = workspace.CurrentCamera
		if not camera or App.cameraBusy or camera.CameraType == Enum.CameraType.Scriptable then
			return false
		end
		local look =
			{ camera = camera, kind = camera.CameraType, previous = camera.CFrame, cameraEpoch = App.cameraEpoch }
		session.look = look
		look.update = function()
			if session.look ~= look then
				return
			end
			if
				not App.alive
				or App.cameraBusy
				or App.cameraEpoch ~= look.cameraEpoch
				or workspace.CurrentCamera ~= camera
				or camera.CameraType ~= look.kind
				or not part.Parent
			then
				EventInput.endLook(session)
				return
			end
			if (camera.CFrame.Position - part.Position).Magnitude > 0.1 then
				if look.aim and camera.CFrame ~= look.aim then
					look.previous = camera.CFrame
				end
				look.aim = CFrame.lookAt(camera.CFrame.Position, part.Position)
				camera.CFrame = look.aim
			end
		end
		look.update()
		EventInput.lookSerial = (EventInput.lookSerial or 0) + 1
		look.binding = "HollowEventLook_" .. EventInput.lookSerial
		local ok = pcall(
			RunService.BindToRenderStep,
			RunService,
			look.binding,
			Enum.RenderPriority.Last.Value - 1,
			function()
				local updated = pcall(look.update)
				if not updated then
					EventInput.endLook(session)
				end
			end
		)
		if not ok then
			look.binding = nil
		end
		return true
	end

	function Event7.shawarmaUse(session, item, generation)
		local object, part = item.object, item.part
		local allowed = function()
			return Event7.eventTarget(object) and part.Parent and character() ~= nil
		end
		if item.kind == "prompt" and object:IsA("ProximityPrompt") then
			return Event7.interact(session, object, generation, allowed)
		end
		if not approach(part.Position, generation, nil, nil, allowed, { settleSeconds = 0.15 }) then
			return false
		end
		if not Event7.face(session, part) then
			return false
		end
		local duration = item.kind == "hold" and object:GetAttribute("HoldTime") or 0
		duration = type(duration) == "number" and math.clamp(duration, 0, 30) or 0
		local finish = os.clock() + duration + 0.15
		while active(generation) and allowed() and os.clock() < finish do
			if session.look then
				session.look.update()
			end
			if not pause(0.05, generation) then
				break
			end
		end
		local ok = false
		local _, root = character()
		if active(generation) and allowed() and root and (root.Position - part.Position).Magnitude <= 12 then
			if item.kind == "hold" and Collection:HasTag(object, "canHold") then
				ok = fire(getPath(Storage, "MouseHolded", "Server"), object)
			elseif object:IsA("ClickDetector") and type(fireclickdetector) == "function" then
				ok = pcall(fireclickdetector, object)
			end
		end
		EventInput.release(session)
		return ok
	end

	function Event7.runShawarma(generation)
		local session = { blocked = {}, count = 0, connections = {} }
		table.insert(App.cleanups, function()
			EventInput.release(session)
			for _, connection in ipairs(session.connections) do
				connection:Disconnect()
			end
			if not Event7.markers then
				Event7.closeIndex()
			end
		end)
		if game.PlaceId == current.place then
			prepareTravel(current.eventPlace, true)
			local hub = waitUntil(function()
				return getPath(workspace, "TeleportHubs", "Story1")
			end, 30, generation)
			local gate = hub and (hub:FindFirstChild("GatePart") or hub:FindFirstChild("spawnPart"))
			if not gate then
				return false, "The Story Mode queue hasn't loaded"
			end
			if not waitUntil(character, 25, generation) then
				return false, "Waiting for your character"
			end
			status("Joining Story Mode", "Choosing the full story", 0.05)
			local chosen, nextChoice = false, 0
			local opened = Storage:FindFirstChild("StoryChoice_Open")
			if opened and opened:IsA("RemoteEvent") then
				table.insert(
					session.connections,
					opened.OnClientEvent:Connect(function(hubName)
						if active(generation) and hubName == hub.Name then
							chosen = fire(Storage:FindFirstChild("StoryChoice_Pick"), hubName, "full")
						end
					end)
				)
			end
			if not approach(gate.Position, generation) then
				return false, "Couldn't reach the Story Mode queue"
			end
			Event7.touch(gate, generation)
			local deadline = os.clock() + 90
			while active(generation) and os.clock() < deadline do
				local panel = getPath(App.player, "PlayerGui", "ResponsiveGUI", "Root", "TeleportStory")
				if
					not chosen
					and panel
					and panel.Visible
					and panel:GetAttribute("CurrentHubName") == hub.Name
					and os.clock() >= nextChoice
				then
					nextChoice = os.clock() + 3
					chosen = fire(Storage:FindFirstChild("StoryChoice_Pick"), hub.Name, "full")
				end
				pause(0.25, generation)
			end
			return false, active(generation) and "The queue didn't leave. Rejoin Story Mode and try again." or "Stopped"
		end
		local controller, progressRemote, voteRemote, badgeAt, voteAt = nil, nil, nil, 0, 0
		while active(generation) do
			if os.clock() >= badgeAt then
				badgeAt = os.clock() + 15
				if verify(current) then
					return true, "Hollow badge earned"
				end
			end
			if not active(generation) then
				break
			end
			local nextController = getPath(workspace, "Halloween", "Voids", "VoidScript")
			if nextController ~= controller then
				for _, connection in ipairs(session.connections) do
					connection:Disconnect()
				end
				table.clear(session.connections)
				controller, progressRemote, voteRemote = nextController, nil, nil
				session.count, session.final, session.blocked = 0, false, {}
			end
			local progress = controller and controller:FindFirstChild("TheHollowProgressRemote")
			if progress and progress ~= progressRemote and progress:IsA("RemoteEvent") then
				progressRemote = progress
				table.insert(
					session.connections,
					progress.OnClientEvent:Connect(function(kind, value)
						if not active(generation) then
							return
						end
						if kind == "Progress" or kind == "Final" then
							session.count = math.clamp(tonumber(value) or session.count, 0, 7)
							session.final = kind == "Final"
						elseif kind == "Opening" then
							session.opening = true
						end
					end)
				)
				fire(progressRemote, "Ready")
			end
			local vote = controller and controller:FindFirstChild("TheHollowVoteRemote")
			if vote and vote ~= voteRemote and vote:IsA("RemoteEvent") then
				voteRemote = vote
				fire(voteRemote, "Ready")
			end
			local voteGui = getPath(App.player, "PlayerGui", "TheHollowVoteGui")
			local yes = voteGui and voteGui:FindFirstChild("VoteYes", true)
			if
				voteRemote
				and voteGui
				and voteGui.Enabled
				and yes
				and yes.Visible
				and yes.Active
				and os.clock() >= voteAt
			then
				voteAt = os.clock() + 10
				fire(voteRemote, "Vote", "Yes")
			end
			local item = not session.final and Event7.closest(Event7.shawarmaItems(), session.blocked)
			if not active(generation) then
				break
			end
			if item then
				status("Closing the breach", session.count .. " / 7 sealed", session.count / 7)
				Event7.shawarmaUse(session, item, generation)
				session.blocked[item.object] = os.clock() + 8
			else
				status(
					session.final and "Breach sealed" or "Waiting for the next Hollow task",
					session.final and "Waiting for the badge"
						or session.count .. " / 7 sealed. Hollow markers can help with manual steps.",
					session.count / 7
				)
			end
			pause(0.35, generation)
		end
		return false, "Stopped"
	end

	-- markers
	function Event7.clearMarkers()
		local state = Event7.markers
		Event7.markers = nil
		if state then
			state.closed = true
			for _, marker in pairs(state.items) do
				marker.folder:Destroy()
				marker.highlight:Destroy()
			end
			if state.worldFolder then
				state.worldFolder:Destroy()
			end
		end
	end

	function Event7.closeIndex()
		if Event7.index then
			for _, connection in ipairs(Event7.index.connections) do
				connection:Disconnect()
			end
			Event7.index = nil
		end
	end

	function Event7.clear()
		Event7.clearMarkers()
		Event7.closeIndex()
	end

	function Event7.items()
		if current.id == "banana" then
			local items = Event7.bananaItems()
			for _, item in ipairs(Event7.bananas()) do
				table.insert(items, item)
			end
			return items
		elseif current.id == "mega" then
			return App.mega.markers()
		elseif current.id == "shawarma" then
			return game.PlaceId == current.eventPlace and Event7.shawarmaItems() or {}
		elseif current.id == "hollow" then
			local items = Event7.pumpkins()
			for _, object in ipairs(Collection:GetTagged("%Brazier")) do
				local part = Event7.part(object)
				if part then
					table.insert(items, { object = object, part = part, title = "Torch", color = mint })
				end
			end
			return items
		end
		return {}
	end

	function Event7.updateMarkers(state)
		if state.closed or not App.alive then
			return
		end
		if not state.worldFolder then
			state.worldFolder = Instance.new("Folder")
			state.worldFolder.Name, state.worldFolder.Parent = "HollowEventHighlights", workspace
		end
		local _, root = character()
		local items = Event7.items()
		if state.closed or not App.alive then
			return
		end
		if root then
			table.sort(items, function(a, b)
				return (a.part.Position - root.Position).Magnitude < (b.part.Position - root.Position).Magnitude
			end)
		end
		local keep = {}
		for index, item in ipairs(items) do
			if index > 24 then
				break
			end
			local marker = state.items[item.object]
			if not marker then
				local folder = Instance.new("Folder")
				folder.Name, folder.Parent = "HollowEventMarker", App.gui
				local highlight = Instance.new("Highlight")
				highlight.Adornee = item.object:IsA("Model") and item.object or item.part
				highlight.FillTransparency, highlight.OutlineColor, highlight.FillColor = 0.8, item.color, item.color
				highlight.DepthMode, highlight.Parent = Enum.HighlightDepthMode.AlwaysOnTop, state.worldFolder
				local billboard = Instance.new("BillboardGui")
				billboard.Adornee, billboard.AlwaysOnTop = item.part, true
				billboard.Size, billboard.StudsOffset, billboard.Parent =
					UDim2.fromOffset(160, 40), Vector3.new(0, 2.5, 0), folder
				local text = Instance.new("TextLabel")
				text.Size, text.BackgroundTransparency = UDim2.fromScale(1, 1), 1
				text.TextSize, text.Font, text.TextStrokeTransparency, text.TextColor3 =
					13, Enum.Font.GothamMedium, 0.2, item.color
				text.Parent = billboard
				marker = { folder = folder, text = text, billboard = billboard, highlight = highlight }
				state.items[item.object] = marker
			end
			marker.billboard.Adornee = item.part
			marker.highlight.Adornee = item.object:IsA("Model") and item.object or item.part
			local title = item.title
				.. (root and "\n" .. math.floor((root.Position - item.part.Position).Magnitude) .. " studs" or "")
			if marker.text.Text ~= title then
				marker.text.Text = title
			end
			keep[item.object] = true
		end
		for object, marker in pairs(state.items) do
			if not keep[object] then
				marker.folder:Destroy()
				marker.highlight:Destroy()
				state.items[object] = nil
			end
		end
	end

	function Event7.toggleMarkers()
		if Event7.markers then
			Event7.clearMarkers()
			if not App.running then
				Event7.closeIndex()
			end
			refresh()
			return
		end
		local state = { items = {} }
		Event7.markers = state
		refresh()
		task.spawn(function()
			while App.alive and Event7.markers == state do
				pcall(Event7.updateMarkers, state)
				task.wait(0.35)
			end
		end)
	end

	App.event7 = Event7
	runners.banana = Event7.runBanana
	runners.shawarma = Event7.runShawarma
end

-- mega store
do
	local Mega = {}
	local candyNames = { "Candy1", "Candy2", "Candy3" }
	local candyTitles = { Candy1 = "Energy candy", Candy2 = "Night candy", Candy3 = "Health candy" }
	local cyan, amber, red = Color3.fromRGB(116, 224, 219), Color3.fromRGB(255, 199, 103), Color3.fromRGB(255, 113, 113)
	local timing = { streamSeconds = 0.2, streamWait = 0.5, settleSeconds = 0.12 }

	function Mega.util()
		return getPath(workspace, "Map", "Util")
	end

	function Mega.cauldron()
		return getPath(Mega.util(), "Cauldron")
	end

	function Mega.counts()
		local cauldron = Mega.cauldron()
		local display = getPath(cauldron, "_Util", "DisplayPart")
		local counts, total, known = {}, 0, true
		for _, name in ipairs(candyNames) do
			local frame = display and display:FindFirstChild(name, true)
			local label = frame and frame:FindFirstChild("AmountTL", true)
			local text = label and label:IsA("TextLabel") and label.Text:gsub("<[^>]*>", "")
			local count = text and tonumber(text:match("%d+"))
			counts[name] = count and math.clamp(count, 0, 6) or 0
			total += counts[name]
			known = known and count ~= nil
		end
		return counts, total, known
	end

	function Mega.inventory()
		local counts, tools, slots = {}, {}, 0
		for _, parent in pairs({ App.player:FindFirstChild("Backpack"), App.player.Character }) do
			if parent then
				for _, tool in ipairs(parent:GetChildren()) do
					if tool:IsA("Tool") then
						slots += 1
						if candyTitles[tool.Name] then
							local amount = tonumber(tool:GetAttribute("StackAmount")) or 1
							counts[tool.Name] = (counts[tool.Name] or 0) + math.max(0, amount)
							table.insert(tools, tool)
						end
					end
				end
			end
		end
		return counts, tools, slots
	end

	function Mega.ready()
		local model, root, humanoid = character()
		local camera = workspace.CurrentCamera
		return model
			and not root.Anchored
			and humanoid.WalkSpeed > 0
			and model:GetAttribute("AllowEquipping") ~= false
			and not App.cameraBusy
			and camera
			and camera.CameraType ~= Enum.CameraType.Scriptable
	end

	function Mega.threats()
		local items = {}
		local folder = workspace:FindFirstChild("Enemies")
		for _, object in ipairs(folder and folder:GetChildren() or {}) do
			local humanoid = object:FindFirstChildWhichIsA("Humanoid", true)
			local part = object:FindFirstChild("HumanoidRootPart", true) or App.event7.part(object)
			if part and part:IsA("BasePart") and (not humanoid or humanoid.Health > 0) then
				table.insert(items, { object = object, part = part, title = object.Name, color = red })
			end
		end
		return items
	end

	function Mega.clearance(point)
		return App.event7.clearance(point, Mega.threats())
	end

	function Mega.safe()
		local _, root = character()
		return Mega.ready() and root and not Mega.danger(root.Position, 12)
	end

	function Mega.scan()
		local util = Mega.util()
		if Mega.cache and Mega.cache.util == util and os.clock() < Mega.cache.untilAt then
			return Mega.cache.items
		end
		local items = {}
		local folder = getPath(util, "PumpkinChests")
		for _, object in ipairs(folder and folder:GetChildren() or {}) do
			for _, prompt in ipairs(object:GetDescendants()) do
				if prompt:IsA("ProximityPrompt") then
					local part = App.event7.part(prompt.Parent)
					if part then
						table.insert(items, {
							object = object,
							part = part,
							prompt = prompt,
							kind = "chest",
							title = "Pumpkin chest",
							color = amber,
						})
					end
				end
			end
		end
		Mega.cache = { util = util, untilAt = os.clock() + 2, items = items }
		return items
	end

	function Mega.items()
		local items = {}
		local counts, _, known = Mega.counts()
		local inventory = Mega.inventory()
		local folder = getPath(Mega.util(), "Items")
		for _, object in ipairs(folder and folder:GetChildren() or {}) do
			if candyTitles[object.Name] then
				local part = App.event7.part(object)
				if part and (not known or counts[object.Name] + (inventory[object.Name] or 0) < 6) then
					table.insert(
						items,
						{ object = object, part = part, kind = "candy", title = candyTitles[object.Name], color = cyan }
					)
				end
			end
		end
		local phase = getPath(Storage, "GameInfo", "TimeOfDay")
		local day = phase and string.find(string.lower(tostring(phase.Value)), "day", 1, true)
		for _, item in ipairs(Mega.scan()) do
			if item.object:IsDescendantOf(workspace) and item.prompt.Parent and item.prompt.Enabled and not day then
				table.insert(items, item)
			end
		end
		local reward = Mega.reward()
		if reward then
			table.insert(items, reward)
		end
		return items
	end

	function Mega.reward()
		local output = getPath(Mega.cauldron(), "_Util", "OutputPart")
		if not output or not output:IsA("BasePart") then
			return nil
		end
		local folder = getPath(Mega.util(), "Items")
		for _, tool in ipairs(folder and folder:GetChildren() or {}) do
			if tool:IsA("Tool") and tool.Name == "HalloweenSlingshot" then
				local part = App.event7.part(tool)
				if part and (part.Position - output.Position).Magnitude < 15 then
					return { object = tool, part = part, kind = "reward", title = "Brew reward", color = amber }
				end
			end
		end
	end

	function Mega.next(session)
		local pickups, chests = {}, {}
		local threats = Mega.threats()
		for _, item in ipairs(Mega.items()) do
			if not Mega.danger(item.part.Position, item.kind == "chest" and 22 or 12, threats) then
				table.insert(item.kind == "chest" and chests or pickups, item)
			end
		end
		local pickup = App.event7.closest(pickups, session.blocked)
		if pickup then
			return pickup
		end
		if #pickups > 0 then
			return nil, "Waiting to retry the candy pickup"
		end
		return App.event7.closest(chests, session.blocked)
	end

	function Mega.markers()
		local items = Mega.items()
		local part = getPath(Mega.cauldron(), "_Util", "InteractPart")
		if part and part:IsA("BasePart") then
			table.insert(items, { object = Mega.cauldron(), part = part, title = "Cauldron", color = amber })
		end
		for _, item in ipairs(Mega.threats()) do
			table.insert(items, item)
		end
		return items
	end

	function Mega.move(point, generation, ignore, allowed, within)
		if not active(generation) or not Mega.ready() or allowed and not allowed() then
			return false
		end
		local _, root = character()
		if (root.Position - point).Magnitude <= (within or 6) then
			return true
		end
		return approach(point, generation, ignore, nil, function()
			return Mega.ready() and (not allowed or allowed())
		end, timing)
	end

	function Mega.cauldronStand(generation, allowed)
		local zone = getPath(Mega.cauldron(), "_Util", "IngredientZone")
		local _, root = character()
		if not zone or not zone:IsA("BasePart") or not root then
			return false
		end
		local points = {}
		local radius = math.max(zone.Size.X, zone.Size.Z) / 2 + 3.5
		for _, offset in ipairs({
			Vector3.new(radius, 0, 0),
			Vector3.new(-radius, 0, 0),
			Vector3.new(0, 0, radius),
			Vector3.new(0, 0, -radius),
		}) do
			table.insert(points, zone.Position + offset)
		end
		table.sort(points, function(a, b)
			return (a - root.Position).Magnitude < (b - root.Position).Magnitude
		end)
		for _, point in ipairs(points) do
			if not Mega.danger(point, 18) and Mega.move(point, generation, nil, allowed, 1) then
				return true
			end
			if not active(generation) or not Mega.ready() then
				return false
			end
		end
		return false
	end

	function Mega.evade(generation)
		if not Mega.ready() then
			return false
		end
		local _, root = character()
		local threats = Mega.threats()
		local distance = App.event7.clearance(root.Position, threats)
		if distance > 12 or not Mega.danger(root.Position, 12, threats) then
			return false
		end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { App.player.Character, workspace:FindFirstChild("Enemies") }
		params.RespectCanCollide = true
		params.IgnoreWater = true
		local best, score
		for i = 1, 12 do
			local angle = i * math.pi / 6
			local point = root.Position + Vector3.new(math.cos(angle) * 32, 5, math.sin(angle) * 32)
			local hit = workspace:Raycast(point, Vector3.new(0, -18, 0), params)
			if hit and hit.Normal.Y > 0.7 and math.abs(hit.Position.Y + 3 - root.Position.Y) < 7 then
				local gap = App.event7.clearance(hit.Position, threats)
				if gap > math.max(25, distance + 8) and (not score or gap > score) then
					best, score = hit.Position, gap
				end
			end
		end
		if best then
			Mega.move(best, generation, nil, function()
				return Mega.clearance(best) > 23
			end)
		end
		return true
	end

	-- pickups
	function Mega.chestStand(item, generation, allowed)
		local _, root = character()
		if not root then
			return false
		end
		local points = {}
		for _, offset in ipairs({
			Vector3.new(4, 0, 0),
			Vector3.new(-4, 0, 0),
			Vector3.new(0, 0, 4),
			Vector3.new(0, 0, -4),
		}) do
			table.insert(points, item.part.Position + offset)
		end
		table.sort(points, function(a, b)
			return (a - root.Position).Magnitude < (b - root.Position).Magnitude
		end)
		for _, point in ipairs(points) do
			if not Mega.danger(point, 22) and Mega.move(point, generation, item.object, allowed, 1) then
				return true
			end
			if not active(generation) or not Mega.ready() then
				return false
			end
		end
		return false
	end

	function Mega.danger(point, radius, threats)
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { App.player.Character, workspace:FindFirstChild("RaycastIgnore") }
		params.IgnoreWater = true
		for _, enemy in ipairs(threats or Mega.threats()) do
			if (enemy.part.Position - point).Magnitude < radius then
				local origin = point + Vector3.new(0, 1, 0)
				local hit = workspace:Raycast(origin, enemy.part.Position + Vector3.new(0, 1, 0) - origin, params)
				if not hit or hit.Instance == enemy.part or hit.Instance:IsDescendantOf(enemy.object) then
					return true
				end
			end
		end
		return false
	end

	function Mega.chestDanger(root)
		return Mega.danger(root.Position, 12)
	end

	function Mega.holdChest(session, item, generation, fallback, allowed)
		local prompt = item.prompt
		local model, root, humanoid = character()
		if Mega.holding or not model or not prompt or not prompt.Parent or not prompt.Enabled then
			return false
		end
		local duration = prompt.HoldDuration
		if type(duration) ~= "number" or duration ~= duration or duration < 0 or duration > 30 then
			return false
		end
		local job = { health = humanoid.Health, riskAt = 0, before = {}, connections = {} }
		local folder = getPath(Mega.util(), "Items")
		for _, tool in ipairs(folder and folder:GetChildren() or {}) do
			job.before[tool] = true
		end
		Mega.holding = job
		local function owned()
			return active(generation)
				and not session.closed
				and Mega.holding == job
				and App.player.Character == model
				and (not allowed or allowed())
		end
		local function opened()
			if not job.started or not job.triggered and os.clock() < job.started + duration then
				return false
			end
			if not prompt.Parent or not prompt:IsDescendantOf(workspace) or not prompt.Enabled then
				return true
			end
			for _, tool in ipairs(folder and folder:GetChildren() or {}) do
				local part = candyTitles[tool.Name] and not job.before[tool] and App.event7.part(tool)
				if part and (part.Position - item.part.Position).Magnitude < 14 then
					return true
				end
			end
			return false
		end
		local function ready()
			local currentModel, currentRoot, currentHumanoid = character()
			local point = prompt.Parent and EventInput.point(prompt.Parent)
			local camera = workspace.CurrentCamera
			if
				not owned()
				or currentModel ~= model
				or not point
				or not camera
				or App.cameraBusy
				or camera.CameraType == Enum.CameraType.Scriptable
				or (currentRoot.Position - point).Magnitude > prompt.MaxActivationDistance - 0.1
				or currentHumanoid.Health < job.health - 0.5
			then
				return false
			end
			if os.clock() >= job.riskAt then
				job.riskAt, job.danger = os.clock() + 0.2, Mega.chestDanger(currentRoot)
			end
			return not job.danger
		end
		local ok, complete = pcall(function()
			if not ready() or not App.event7.face(session, item.part) then
				return false
			end
			if not pause(0.1, generation) or not ready() then
				return false
			end
			table.insert(
				job.connections,
				prompt.Triggered:Connect(function(player)
					if owned() and (player == nil or player == App.player) then
						job.triggered = true
					end
				end)
			)
			session.prompt = prompt
			job.started = os.clock()
			local deadline = os.clock() + duration + 1.5
			local began = false
			if not fallback or type(fireproximityprompt) ~= "function" then
				began = pcall(prompt.InputHoldBegin, prompt)
			end
			if not began and ready() and type(fireproximityprompt) == "function" then
				local sent, result = call(prompt, function()
					if ready() then
						return fireproximityprompt(prompt, duration)
					end
					return false
				end, duration + 2, generation)
				began = sent and result ~= false
			end
			if not began then
				return false
			end
			while owned() and os.clock() < deadline do
				if opened() then
					return true
				end
				if not prompt.Enabled then
					return false
				end
				if not ready() then
					return false
				end
				if job.triggered and session.prompt == prompt then
					pcall(prompt.InputHoldEnd, prompt)
					session.prompt = nil
				end
				if not pause(0.04, generation) then
					return false
				end
			end
			return owned() and opened()
		end)
		for _, connection in ipairs(job.connections) do
			connection:Disconnect()
		end
		EventInput.release(session)
		if Mega.holding == job then
			Mega.holding = nil
		end
		if ok and complete and active(generation) and not session.closed then
			local untilAt = os.clock() + 0.8
			while active(generation) and os.clock() < untilAt and Mega.safe() do
				if not pause(0.08, generation) then
					break
				end
			end
			return active(generation)
		end
		return false
	end

	function Mega.use(session, item, generation, move, fallback, allowed)
		if Mega.holding then
			return false
		end
		local model = App.player.Character
		local function ready()
			return active(generation)
				and Mega.safe()
				and App.player.Character == model
				and item.object:IsDescendantOf(workspace)
				and item.part.Parent
				and not Mega.danger(item.part.Position, item.kind == "chest" and 22 or 12)
				and (not allowed or allowed())
		end
		if not ready() then
			return false
		end
		if move then
			local moved = item.kind == "chest" and Mega.chestStand(item, generation, ready)
				or item.kind ~= "chest" and Mega.move(item.part.Position, generation, nil, ready)
			if not moved then
				return false
			end
		end
		local _, root = character()
		if not ready() or (root.Position - item.part.Position).Magnitude > 9 then
			return false
		end
		if item.kind == "chest" then
			return Mega.holdChest(session, item, generation, fallback, allowed)
		end
		if item.kind == "candy" or item.kind == "reward" then
			return fire(getPath(Storage, "Remotes", "RequestPickupItem"), item.object)
		end
		if not App.event7.face(session, item.part) or not pause(0.15, generation) or not ready() then
			EventInput.release(session)
			return false
		end
		local prompt = item.prompt or item.object:FindFirstChildWhichIsA("ProximityPrompt", true)
		local ok = false
		if prompt and prompt.Enabled then
			ok = EventInput.hold(session, prompt, generation, ready)
			if
				fallback
				and ready()
				and type(fireproximityprompt) == "function"
				and prompt.Parent
				and prompt.Enabled
			then
				local sent, result = call(prompt, function()
					if ready() then
						return fireproximityprompt(prompt, prompt.HoldDuration)
					end
					return false
				end, prompt.HoldDuration + 2, generation)
				ok = sent and result ~= false
			end
		end
		EventInput.release(session)
		return ok
	end

	function Mega.deposit(session, generation, move, allowed)
		local cauldron = Mega.cauldron()
		local zone = getPath(cauldron, "_Util", "IngredientZone")
		local counts, _, known = Mega.counts()
		if not zone or not zone:IsA("BasePart") then
			return false
		end
		local function ready()
			return active(generation)
				and Mega.safe()
				and zone.Parent
				and Mega.cauldron() == cauldron
				and cauldron:GetAttribute("CauldronState") == "Collecting"
				and (not allowed or allowed())
		end
		if not ready() then
			return false
		end
		local _, tools = Mega.inventory()
		for _, tool in ipairs(tools) do
			if counts[tool.Name] < 6 then
				local model, root, humanoid = character()
				if move and not Mega.cauldronStand(generation, ready) then
					return false
				end
				if not ready() or (root.Position - zone.Position).Magnitude > 10 then
					return false
				end
				if model:GetAttribute("AllowEquipping") == false then
					return false
				end
				humanoid:EquipTool(tool)
				if not pause(0.15, generation) or not ready() or tool.Parent ~= model then
					return false
				end
				if not App.event7.face(session, zone) then
					return false
				end
				if not pause(0.1, generation) or not ready() then
					EventInput.release(session)
					return false
				end
				local before, name = counts[tool.Name], tool.Name
				local sent = fire(getPath(Storage, "Remotes", "RequestDropItem"), tool, zone.Position)
				EventInput.release(session)
				if not sent then
					return false
				end
				local credited = waitUntil(function()
					if not active(generation) or not Mega.safe() or not zone.Parent or Mega.cauldron() ~= cauldron then
						return true
					end
					local now, _, loaded = Mega.counts()
					return loaded and now[name] > before
				end, 3, generation)
				local now, _, loaded = Mega.counts()
				return credited ~= nil and active(generation) and loaded and now[name] > before
			end
		end
		return false
	end

	function Mega.stir(session, generation, move, allowed)
		local cauldron = Mega.cauldron()
		local prompt = getPath(cauldron, "_Util", "InteractPart", "StirPrompt")
		if not prompt or not prompt.Enabled then
			return false
		end
		local part = App.event7.part(prompt.Parent)
		if not part then
			return false
		end
		if move and not Mega.cauldronStand(generation, Mega.safe) then
			return false
		end
		return Mega.use(
			session,
			{ object = cauldron, part = part, prompt = prompt, kind = "stir" },
			generation,
			false,
			session.stirMissed,
			allowed
		)
	end

	function Mega.progress()
		if game.PlaceId ~= current.eventPlace then
			return "Join a store round to start the quest"
		end
		local counts, _, known = Mega.counts()
		if not known then
			return Mega.cauldron() and "Checking candy totals" or "Finding the cauldron"
		end
		return string.format("Energy %d/6  |  Night %d/6  |  Health %d/6", counts.Candy1, counts.Candy2, counts.Candy3)
	end

	function Mega.pollBadge(session, generation)
		if session.badgeBusy or os.clock() < (session.badgeAt or 0) then
			return
		end
		session.badgeBusy, session.badgeAt = true, os.clock() + 15
		task.spawn(function()
			local ok, owned = pcall(verify, current, true)
			if active(generation) and not session.closed then
				session.badge = ok and owned == true
			end
			session.badgeBusy = false
		end)
	end

	function Mega.explore(session, generation)
		if os.clock() < (session.exploreAt or 0) then
			return false
		end
		session.exploreAt = os.clock() + 4
		local phase = getPath(Storage, "GameInfo", "TimeOfDay")
		if not phase or not string.find(string.lower(tostring(phase.Value)), "night", 1, true) then
			return false
		end
		local stock = getPath(Mega.util(), "StockAreas")
		if not stock then
			return false
		end
		local areas = {}
		for _, area in ipairs(stock:GetChildren()) do
			local part = App.event7.part(area)
			if part and part.Position.Y > workspace.FallenPartsDestroyHeight + 32 then
				local unique = true
				for _, point in ipairs(areas) do
					if (point - part.Position).Magnitude < 65 then
						unique = false
						break
					end
				end
				if unique then
					table.insert(areas, part.Position)
				end
				if #areas >= 16 then
					break
				end
			end
		end
		if #areas == 0 then
			return false
		end
		session.area = (session.area or 0) % #areas + 1
		local point = areas[session.area]
		status("Checking the store for chests", Mega.progress())
		call("Mega store streaming", function()
			if active(generation) then
				App.player:RequestStreamAroundAsync(point, 0.5)
			end
		end, 0.8, generation)
		Mega.cache = nil
		if not active(generation) or #Mega.items() > 0 then
			return true
		end
		Mega.move(point, generation, nil, function()
			return Mega.safe() and Mega.clearance(point) > 28
		end)
		return true
	end

	function Mega.run(generation)
		if game.PlaceId ~= current.eventPlace then
			return false, "Join a store round, then press Start"
		end
		local session = { blocked = setmetatable({}, { __mode = "k" }), misses = setmetatable({}, { __mode = "k" }) }
		Mega.session = session
		if Mega.helper then
			EventInput.release(Mega.helper)
		end
		table.insert(App.cleanups, function()
			session.closed = true
			EventInput.release(session)
			if Mega.session == session then
				Mega.session = nil
			end
			Mega.cache = nil
		end)
		local startAt, checkAt = 0, 0
		while active(generation) do
			Mega.pollBadge(session, generation)
			if session.badge then
				return true, "Tasty Brew badge earned"
			end
			local cauldron = Mega.cauldron()
			local state = cauldron and cauldron:GetAttribute("CauldronState")
			local stirPrompt = getPath(cauldron, "_Util", "InteractPart", "StirPrompt")
			local counts, total, known = Mega.counts()
			local inv, tools, slots = Mega.inventory()
			local reward = Mega.reward()
			local stored = 0
			for _, name in ipairs(candyNames) do
				stored += math.min(inv[name] or 0, 6 - counts[name])
			end
			if stored == 0 then
				session.banking = false
			end
			if not Mega.ready() then
				status("Waiting for the store", "Let the game finish loading or reviving", total / 18)
			elseif Mega.evade(generation) then
				status("Moving away from employees", Mega.progress(), total / 18)
			elseif reward and os.clock() >= (session.blocked[reward.object] or 0) then
				status("Picking up the brew", "Checking for the badge", total / 18)
				Mega.use(session, reward, generation, true)
				waitUntil(function()
					return not reward.object:IsDescendantOf(workspace) or not Mega.safe()
				end, 1.5, generation)
				session.blocked[reward.object] = os.clock() + 3
				if not reward.object:IsDescendantOf(workspace) then
					session.badgeAt = 0
				end
			elseif stirPrompt and stirPrompt.Enabled and state ~= "Brewing" then
				status("Stirring the cauldron", Mega.progress(), total / 18)
				Mega.stir(session, generation, true)
				session.stirMissed = true
			elseif state == "Brewing" then
				local began, duration = cauldron:GetAttribute("BrewStartedAt"), cauldron:GetAttribute("BrewTime")
				local remaining = type(began) == "number"
					and type(duration) == "number"
					and math.max(0, math.ceil(began + duration - workspace:GetServerTimeNow()))
				status(
					"Brewing",
					remaining and (remaining > 0 and remaining .. "s left" or "Checking for the finished brew")
						or "The cauldron is brewing",
					total / 18
				)
			elseif known and total >= 18 then
				status("Ready to stir", "Checking the stir prompt", total / 18)
				if os.clock() >= (session.cauldronAt or 0) then
					session.cauldronAt = os.clock() + 3
					Mega.cauldronStand(generation, Mega.safe)
				end
			elseif stored > 0 and (session.banking or slots >= 4 or total + stored >= 18) then
				session.banking = true
				status("Adding candy", Mega.progress(), total / 18)
				Mega.deposit(session, generation, true)
			else
				local item, waiting = Mega.next(session)
				if item then
					local before = inv[item.object.Name] or 0
					status(
						item.kind == "candy" and "Picking up candy" or "Opening a pumpkin chest",
						Mega.progress(),
						total / 18
					)
					local used = Mega.use(session, item, generation, true, (session.misses[item.object] or 0) > 0)
					local changed = used
					if item.kind ~= "chest" then
						waitUntil(function()
							if not Mega.safe() or not item.object:IsDescendantOf(workspace) then
								return true
							end
							local now = Mega.inventory()
							return (now[item.object.Name] or 0) > before
						end, 1.8, generation)
						local now = Mega.inventory()
						changed = not item.object:IsDescendantOf(workspace) or (now[item.object.Name] or 0) > before
					end
					session.misses[item.object] = changed and 0 or (session.misses[item.object] or 0) + 1
					session.blocked[item.object] = os.clock() + (changed and 4 or 1)
				elseif stored > 0 then
					session.banking = true
					status("Adding candy", Mega.progress(), total / 18)
					Mega.deposit(session, generation, true)
				elseif waiting then
					status(
						slots >= 5 and "Make room in your hotbar" or "Retrying the candy pickup",
						waiting,
						total / 18
					)
				else
					local prompt = getPath(Mega.util(), "StartGamePart", "ProximityPrompt")
					local round = getPath(Storage, "GameInfo", "Round")
					if prompt and prompt.Enabled and round and round.Value == 0 and os.clock() >= startAt then
						startAt = os.clock() + 8
						status("Entering the store", "", 0)
						Mega.use(
							session,
							{ object = prompt.Parent, part = prompt.Parent, prompt = prompt },
							generation,
							true
						)
					elseif not Mega.explore(session, generation) then
						status(
							slots >= 5 and "Make room in your hotbar" or "Waiting for candy or pumpkin chests",
							"Chests open at night. ESP works without Start.",
							total / 18
						)
					end
					if os.clock() >= checkAt then
						checkAt = os.clock() + 6
						Mega.cache = nil
					end
				end
			end
			pause(0.35, generation)
		end
		return false, "Stopped"
	end

	-- manual assist
	function Mega.assistOnce(session)
		local function allowed()
			return Mega.assist and not App.running and not session.closed
		end
		if not allowed() or not Mega.safe() then
			return
		end
		local _, root = character()
		local camera = workspace.CurrentCamera
		local function looking(part)
			local delta = part.Position - camera.CFrame.Position
			return (root.Position - part.Position).Magnitude <= 8
				and delta.Magnitude > 0.1
				and camera.CFrame.LookVector:Dot(delta.Unit) > 0.92
		end
		local prompt = getPath(Mega.cauldron(), "_Util", "InteractPart", "StirPrompt")
		if prompt and prompt.Enabled and looking(prompt.Parent) then
			Mega.stir(session, nil, false, allowed)
			return
		end
		local zone = getPath(Mega.cauldron(), "_Util", "IngredientZone")
		if zone and zone:IsA("BasePart") and looking(zone) then
			if Mega.deposit(session, nil, false, allowed) then
				return
			end
		end
		for _, item in ipairs(Mega.items()) do
			if looking(item.part) then
				Mega.use(session, item, nil, false, session.retry, allowed)
				session.retry = true
				return
			end
		end
	end

	function Mega.toggleAssist()
		Mega.assist = not Mega.assist
		if Mega.helper then
			Mega.helper.closed = true
			EventInput.release(Mega.helper)
			Mega.helper = nil
		end
		refresh()
		if not Mega.assist then
			return
		end
		local session = {}
		Mega.helper = session
		task.spawn(function()
			while App.alive and Mega.assist and Mega.helper == session do
				pcall(Mega.assistOnce, session)
				task.wait(0.75)
			end
			EventInput.release(session)
		end)
	end

	function Mega.clear()
		Mega.assist, Mega.cache = false, nil
		if Mega.helper then
			Mega.helper.closed = true
			EventInput.release(Mega.helper)
			Mega.helper = nil
		end
	end

	function Mega.watch()
		if Mega.watching then
			return
		end
		Mega.watching = true
		task.spawn(function()
			while App.alive do
				pcall(refresh)
				task.wait(0.75)
			end
		end)
	end

	App.mega = Mega
	runners.mega = Mega.run
end

local function start()
	if App.running or App.traveling or not App.player or not current then
		return
	end
	if current.manual then
		status("Play this one in the game", current.objective, 0)
		return
	end
	if App.qol then App.qol.suspendInputs() end
	App.running = true
	App.generation += 1
	local generation = App.generation
	status("Starting", current.name, 0)
	task.spawn(function()
		local ok, success, detail = pcall(function()
			local ready = waitUntil(function()
				return game:IsLoaded()
					and (
						current.id == "duels"
						or (current.id == "royale" and game.PlaceId ~= current.eventPlace)
						or (current.id == "arcade" and game.PlaceId ~= current.eventPlace)
						or (current.id == "needle" and game.PlaceId ~= current.eventPlace)
						or current.id == "prism"
						or current.id == "moo"
						or current.id == "duck"
						or current.id == "bloxburg"
						or current.id == "toons"
						or current.id == "lemons"
						or current.id == "mvsd"
						or current.id == "flee"
						or current.id == "demonology"
						or current.id == "dandy"
						or current.id == "aooni"
						or current.id == "doors"
						or current.id == "nights"
						or current.id == "mimic"
						or current.id == "rails"
						or current.id == "home"
						or current.id == "banana"
						or current.id == "shawarma"
						or current.id == "mega"
						or current.id == "piggy"
						or current.id == "peta"
						or character()
					)
			end, 25, generation)
			if not ready then
				return false, "Character or game is not ready"
			end
			return runners[current.id](generation)
		end)
		if not active(generation) then
			return
		end
		App.running = false
		cleanRun()
		if not ok then
			detail, success = tostring(success), false
		end
		status(
			success == nil and "Traveling" or (success and "Done" or "Paused"),
			detail,
			success and 1 or App.progress
		)
		log(detail or "Finished")
	end)
end

local colors = {
	base = Color3.fromRGB(18, 20, 23),
	raised = Color3.fromRGB(28, 32, 36),
	border = Color3.fromRGB(48, 54, 60),
	text = Color3.fromRGB(238, 242, 242),
	muted = Color3.fromRGB(149, 161, 168),
	mint = Color3.fromRGB(116, 224, 179),
	coral = Color3.fromRGB(244, 153, 134),
}
local function new(class, parent, properties)
	local object = Instance.new(class)
	if object:IsA("GuiObject") then
		object.BorderSizePixel = 0
	end
	for key, value in pairs(properties or {}) do
		object[key] = value
	end
	object.Parent = parent
	return object
end
local function rounded(object, radius)
	new("UICorner", object, { CornerRadius = UDim.new(0, radius or 6) })
end
local function label(parent, text, position, size, fontSize, color)
	return new("TextLabel", parent, {
		Text = text,
		Position = position,
		Size = size,
		BackgroundTransparency = 1,
		TextColor3 = color or colors.text,
		TextSize = fontSize or 13,
		Font = Enum.Font.Gotham,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextWrapped = true,
	})
end
local function button(parent, text, position, size, callback)
	local object = new("TextButton", parent, {
		Text = text,
		Position = position,
		Size = size,
		BackgroundColor3 = colors.raised,
		TextColor3 = colors.text,
		TextSize = 13,
		Font = Enum.Font.GothamMedium,
		AutoButtonColor = true,
		Active = true,
	})
	rounded(object)
	connect(object.Activated, callback)
	return object
end

-- offerings + day 8
do
	(function()
		local Day8 = { markers = false, skills = true, bossAim = true, modules = {} }
		local instruments = {
			{ item = "flotsam_guitar", member = "Flotsam Direwick", attribute = "TheHollowGuitar", title = "Guitar" },
			{ item = "malvus_drumsticks", member = "Malvus", attribute = "TheHollowDrumsticks", title = "Drumsticks" },
			{ item = "siren_head_keys", member = "Siren Head", attribute = "TheHollowKeys", title = "Keys" },
		}

		function Day8.part(object)
			return App.event7.part(object)
		end

		function Day8.nearest(items)
			local _, root = character()
			if not root then
				return nil
			end
			local best, length
			for _, item in ipairs(items) do
				if item.part and item.part.Parent then
					local distance = (root.Position - item.part.Position).Magnitude
					if not length or distance < length then
						best, length = item, distance
					end
				end
			end
			return best, length
		end

		function Day8.load(name, generation)
			if Day8.modules[name] then
				return Day8.modules[name]
			end
			local object = Storage:FindFirstChild("Sonar")
			local loader = object and module(object, generation)
			if type(loader) ~= "function" then
				return nil
			end
			local ok, value = call("Sonaria " .. name, function()
				return loader(name)
			end, 8, generation)
			if ok and type(value) == "table" and active(generation) then
				Day8.modules[name] = value
				return value
			end
		end

		function Day8.hollowState()
			local puzzle = Day8.offerings
			local state = puzzle and type(puzzle.getState) == "function" and puzzle.getState()
			return type(state) == "table" and type(state.Needs) == "table" and type(state.Placed) == "table" and state
				or nil
		end

		function Day8.altar(generation)
			local entries = {}
			for _, object in ipairs(Collection:GetTagged("%OfferingAltar")) do
				local part = Day8.part(object)
				if part then
					table.insert(entries, { object = object, part = part })
				end
			end
			local altar = Day8.nearest(entries)
			return altar
				and approach(altar.part.Position, generation, altar.object, false, function()
					return active(generation) and App.player:GetAttribute("InMaze") == 8
				end)
		end

		function Day8.pedestals(state)
			local items = {}
			if not state then
				return items
			end
			for _, object in ipairs(Collection:GetTagged("%OfferingPedestal")) do
				local key = object:GetAttribute(tostring(App.player.UserId))
				key = key ~= nil and tostring(key) or nil
				local part = Day8.part(object)
				if part and key and state.Needs[key] and not state.Placed[key] then
					table.insert(items, {
						object = object,
						part = part,
						key = key,
						item = state.Needs[key],
						title = tostring(state.Needs[key]),
					})
				end
			end
			return items
		end

		function Bridge.offeringsCompleted()
			for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
				if tonumber(number) == 8 then
					return true
				end
			end
			return false
		end

		function Bridge.solveOfferings(_, _, generation)
			for _, name in ipairs({ "OfferingsPuzzle", "OfferingAltar", "OfferingPedestal" }) do
				local value, reason = hollowModule(name, generation)
				if not value then
					return false, reason
				end
				if name == "OfferingsPuzzle" then
					Day8.offerings = value
				end
			end
			local session, missingAt = {}, os.clock()
			table.insert(App.cleanups, function()
				EventInput.release(session)
			end)
			while active(generation) and App.player:GetAttribute("InMaze") == 8 do
				if App.player:GetAttribute("HasRelic") == true then
					return true
				end
				local state, model = Day8.hollowState(), character()
				if not state or not model then
					status("Loading the offerings", "Waiting for your altar and pedestal list", 0.15)
				elseif state.Solved then
					status("Offerings placed", "Waiting for the relic", 0.85)
				else
					local holding = Day8.offerings.holding()
					local pending = Day8.pedestals(state)
					local placed, total = 0, 0
					for key in pairs(state.Needs) do
						total += 1
						if state.Placed[key] then
							placed += 1
						end
					end
					status(
						"Placing the offerings",
						string.format("%d / %d placed", placed, total),
						0.2 + 0.6 * placed / math.max(1, total)
					)
					local target
					if holding then
						local matching = {}
						for _, entry in ipairs(pending) do
							if entry.item == holding then
								table.insert(matching, entry)
							end
						end
						target = Day8.nearest(matching)
						if target then
							local function allowed()
								return active(generation)
									and App.player.Character == model
									and App.player:GetAttribute("InMaze") == 8
									and Day8.offerings.holding() == holding
									and target.object:IsDescendantOf(workspace)
							end
							if approach(target.part.Position, generation, target.object, false, allowed) then
								waitUntil(function()
									local now = Day8.hollowState()
									return now and now.Placed[target.key] or not allowed()
								end, 4, generation)
							end
						end
					else
						target = Day8.nearest(pending)
					end
					if target and not holding then
						if Day8.altar(generation) and active(generation) then
							Day8.offerings.useAltarItem(target.item)
							waitUntil(function()
								return Day8.offerings.holding() ~= nil or not active(generation)
							end, 4, generation)
						end
					elseif holding and not target then
						status("Returning the extra offering", tostring(holding), App.progress)
						if Day8.altar(generation) and active(generation) then
							Day8.offerings.useAltarItem(holding)
							waitUntil(function()
								return Day8.offerings.holding() ~= holding
							end, 4, generation)
						end
					end
					if target then
						missingAt = os.clock()
					end
				end
				if os.clock() - missingAt > 35 then
					local hint = nearest("%OfferingAltar") or nearest("%OfferingPedestal")
					if hint then
						approach(positionOf(hint), generation, hint)
					end
					missingAt = os.clock()
				end
				if not pause(0.25, generation) then
					break
				end
			end
			return false, active(generation) and "The floor changed" or "Stopped"
		end

		-- instruments
		function Day8.team(player)
			return player:GetAttribute("TeamID") or player.Team and player.Team.Name
		end

		function Day8.killerItems()
			local result = {}
			for _, object in ipairs(Collection:GetTagged("Collectable")) do
				local id = object:GetAttribute("CollectableID") or object.Name
				for _, spec in ipairs(instruments) do
					if spec.item == id and App.player:GetAttribute(spec.attribute) ~= true then
						local part = Day8.part(object)
						if part then
							table.insert(result, { object = object, part = part, title = spec.title, spec = spec })
						end
					end
				end
			end
			return result
		end

		function Day8.members()
			local result = {}
			for _, object in ipairs(Collection:GetTagged("LobbyStage")) do
				for _, spec in ipairs(instruments) do
					local member = object:FindFirstChild(spec.member, true)
					local part = member and Day8.part(member)
					if part then
						table.insert(result, { object = member, part = part, title = spec.member, spec = spec })
					end
				end
			end
			return result
		end

		function Day8.killerThreats()
			local result = {}
			for _, player in ipairs(Players:GetPlayers()) do
				local model = player ~= App.player and player.Character
				local humanoid = model and model:FindFirstChildOfClass("Humanoid")
				local part = model and Day8.part(model)
				if part and humanoid and humanoid.Health > 0 and Day8.team(player) == "Killer" then
					table.insert(result, { object = model, part = part, title = "Killer", threat = true })
				end
			end
			return result
		end

		function Day8.ready(generation)
			local model, root, humanoid = character()
			local camera = workspace.CurrentCamera
			return active(generation)
				and model
				and root
				and humanoid
				and not root.Anchored
				and humanoid.Health > 0
				and not App.cameraBusy
				and camera
				and camera.CameraType ~= Enum.CameraType.Scriptable
				and App.player:GetAttribute("Downed") ~= true
		end

		function Day8.clearance(point, threats)
			local closest = math.huge
			for _, entry in ipairs(threats) do
				if entry.part.Parent then
					closest = math.min(closest, (point - entry.part.Position).Magnitude)
				end
			end
			return closest
		end

		function Day8.evade(session, threats, generation)
			local _, root = character()
			if not root or not Day8.ready(generation) then
				return false
			end
			local currentGap = Day8.clearance(root.Position, threats)
			if currentGap >= 24 or os.clock() < (session.evadeAt or 0) then
				return false
			end
			session.evadeAt = os.clock() + 1.5
			local params = RaycastParams.new()
			params.FilterType, params.RespectCanCollide = Enum.RaycastFilterType.Exclude, true
			local excluded = { App.player.Character }
			for _, entry in ipairs(threats) do
				table.insert(excluded, entry.object)
			end
			params.FilterDescendantsInstances = excluded
			local best, score
			for _, radius in ipairs({ 28, 45 }) do
				for angle = 0, 7 do
					local offset = Vector3.new(math.cos(angle * math.pi / 4), 0, math.sin(angle * math.pi / 4)) * radius
					local hit = workspace:Raycast(
						root.Position + offset + Vector3.new(0, 10, 0),
						Vector3.new(0, -22, 0),
						params
					)
					if
						hit
						and hit.Normal.Y > 0.7
						and math.abs(hit.Position.Y - root.Position.Y) < 12
						and hit.Position.Y > workspace.FallenPartsDestroyHeight + 32
					then
						local gap = Day8.clearance(hit.Position, threats)
						if gap > currentGap + 10 and (not score or gap > score) then
							best, score = hit.Position, gap
						end
					end
				end
			end
			return best
					and approach(best, generation, nil, false, function()
						return Day8.ready(generation)
					end, { streamSeconds = 0.2, streamWait = 0.3, settleSeconds = 0.12 })
				or false
		end

		function Day8.vote(network, session)
			if workspace:GetAttribute("GameState") ~= 3 then
				session.vote = nil
				return
			end
			for index = 1, 4 do
				local tile = "Map" .. index
				if workspace:GetAttribute("MapVoting_" .. tile) == "Happy Neighborhood" and session.vote ~= tile then
					network:FireServer("MapVote", tile)
					session.vote = tile
					return
				end
			end
		end

		function Day8.killerExits()
			local exits = {}
			for _, object in ipairs(Collection:GetTagged("Exit")) do
				local trigger = object:FindFirstChild("Trigger", true)
				if trigger and trigger:IsA("BasePart") and object:GetAttribute("Open") == true then
					table.insert(exits, { object = object, part = trigger, title = "Open exit" })
				end
			end
			return exits
		end

		function Day8.scout(session, generation)
			if workspace:GetAttribute("Map") ~= "Happy Neighborhood" or os.clock() < (session.searchAt or 0) then
				return
			end
			session.searchAt = os.clock() + 4
			local map = workspace:FindFirstChild("Happy Neighborhood")
			if not map then
				return
			end
			local spawns = map:FindFirstChild("SurvivorSpawns")
			local points = {}
			for _, object in ipairs(spawns and spawns:GetChildren() or {}) do
				local part = Day8.part(object)
				if part then
					table.insert(points, part)
				end
			end
			table.sort(points, function(a, b)
				return a.Name < b.Name
			end)
			if #points == 0 then
				return
			end
			session.searchIndex = (session.searchIndex or 0) % #points + 1
			local point = points[session.searchIndex]
			approach(point.Position, generation, nil, false, function()
				return Day8.ready(generation)
					and Day8.team(App.player) == "Survivor"
					and not App.player:GetAttribute("Collectable")
					and #Day8.killerItems() == 0
			end)
		end

		function Day8.pickup(session, entry, generation)
			if not Day8.ready(generation) then
				return false
			end
			local model = App.player.Character
			local function allowed()
				return Day8.ready(generation)
					and App.player.Character == model
					and entry.object:IsDescendantOf(workspace)
			end
			if not approach(entry.part.Position, generation, entry.object, false, allowed) or not allowed() then
				return false
			end
			if App.player:GetAttribute("Collectable") == entry.spec.item then
				return true
			end
			local prompt = entry.object:FindFirstChildWhichIsA("ProximityPrompt", true)
			if prompt and prompt.Enabled then
				return EventInput.hold(session, prompt, generation, allowed, {
					accepted = function()
						return App.player:GetAttribute("Collectable") == entry.spec.item
					end,
				})
			end
			App.event7.face(session, entry.part)
			EventInput.tap(session, generation, Enum.KeyCode.E)
			EventInput.release(session)
			return waitUntil(function()
				return App.player:GetAttribute("Collectable") == entry.spec.item or not allowed()
			end, 1.5, generation) ~= nil and App.player:GetAttribute("Collectable") == entry.spec.item
		end

		function Day8.runKiller(generation)
			local load = module(Storage:FindFirstChild("Load"), generation)
			local network = waitUntil(function()
				load = load or module(Storage:FindFirstChild("Load"), generation)
				local ok, value = false, nil
				if type(load) == "function" then
					ok, value = call("Killer network", function()
						return load("Network")
					end, 8, generation)
				end
				return ok and type(value) == "table" and value
			end, 30, generation)
			if not network then
				return false, "The game controls haven't loaded yet"
			end
			local session = { retry = {} }
			table.insert(App.cleanups, function()
				EventInput.release(session)
			end)
			local badgeAt, stageAt = 0, 0
			while active(generation) do
				if os.clock() >= badgeAt then
					badgeAt = os.clock() + 12
					if verify(current, true) then
						return true, "Hollow badge earned"
					end
				end
				local carried = App.player:GetAttribute("Collectable")
				local completed = 0
				for _, spec in ipairs(instruments) do
					if App.player:GetAttribute(spec.attribute) == true then
						completed += 1
					end
				end
				local lobby = Day8.team(App.player) == "Lobby"
				Day8.vote(network, session)
				if not Day8.ready(generation) then
					status("Waiting to get up", "The route resumes when you're back", completed / 3)
				elseif completed == 3 then
					status("Instruments returned", "Checking for the badge", 0.98)
				elseif Day8.team(App.player) == "Killer" then
					status("Waiting for a survivor round", "Your instrument progress stays saved", completed / 3)
				elseif not lobby and Day8.evade(session, Day8.killerThreats(), generation) then
					status("Moving away from the killer", "Your instrument stays with you", completed / 3)
				elseif lobby and carried then
					local wanted
					for _, entry in ipairs(Day8.members()) do
						if entry.spec.item == carried then
							wanted = entry
							break
						end
					end
					if wanted then
						status("Returning " .. wanted.spec.title, wanted.title, completed / 3)
						if
							approach(wanted.part.Position, generation, wanted.object, false, function()
								return Day8.ready(generation)
							end)
						then
							if active(generation) and App.player:GetAttribute("Collectable") == carried then
								call("Return " .. carried, function()
									return network:InvokeServer("ReturnHollowInstrument", wanted.spec.member)
								end, 8, generation)
								waitUntil(function()
									return App.player:GetAttribute(wanted.spec.attribute) == true
								end, 3, generation)
							end
						end
					else
						status("Loading the band", "Looking for the lobby stage", completed / 3)
					end
				elseif lobby then
					status("Waiting for Happy Neighborhood", "Voting for it whenever it's offered", completed / 3)
				elseif carried then
					status("Instrument secured", "Find an open exit. It stays with you if you die.", completed / 3)
					local exit = Day8.nearest(Day8.killerExits())
					if exit then
						approach(exit.part.Position, generation, exit.object, false, function()
							return Day8.ready(generation)
						end)
						pause(1, generation)
					end
				else
					local items = {}
					for _, entry in ipairs(Day8.killerItems()) do
						if os.clock() >= (session.retry[entry.object] or 0) then
							table.insert(items, entry)
						end
					end
					local target = Day8.nearest(items)
					if target then
						status("Getting " .. target.title, "Returning it to the band after this round", completed / 3)
						Day8.pickup(session, target, generation)
						session.retry[target.object] = os.clock() + 2
					else
						status(
							"Looking for the instruments",
							"They appear in Happy Neighborhood. Checking the loaded map.",
							completed / 3
						)
						Day8.scout(session, generation)
					end
				end
				if lobby and carried and os.clock() >= stageAt and #Day8.members() == 0 then
					stageAt = os.clock() + 8
					pcall(network.FireServer, network, "TeleportToEventStage")
				end
				if not pause(0.4, generation) then
					break
				end
			end
			return false, "Stopped"
		end

		-- sonaria
		function Day8.state(key)
			local state = Day8.modules.GameplayStateService
			return state and type(state.GetState) == "function" and state.GetState(key) or nil
		end

		function Day8.objectiveItems()
			local result = {}
			local api = Day8.modules.Objective
			for _, object in pairs(api and api.GetAll and api.GetAll() or {}) do
				local instance = object.Instance
				local part = Day8.part(object.Model or instance)
				if
					instance
					and instance.Parent
					and part
					and instance:GetAttribute("Activated") ~= true
					and instance:GetAttribute("Dead") ~= true
					and (tonumber(instance:GetAttribute("Health")) or 1) > 0
				then
					table.insert(result, {
						object = instance,
						part = part,
						native = object,
						title = instance:GetAttribute("Locked") and "Locked infection" or "Infection",
					})
				end
			end
			return result
		end

		function Day8.releaseObjective(session)
			local lease = session.objective
			session.objective = nil
			if lease and lease.native and lease.native.Active and type(lease.native.Exit) == "function" then
				task.spawn(function()
					pcall(lease.native.Exit, lease.native)
				end)
			end
			EventInput.release(session)
		end

		function Day8.skill(object)
			local wrapper = object and object.ActiveSkillCheck
			local mini = wrapper and wrapper.Minigame
			if not Day8.skills or not mini or type(mini.Click) ~= "function" then
				return false
			end
			local valid, win, critical = false, false, false
			if type(mini._checkZones) == "function" and type(mini.CurrentScale) == "number" then
				valid, win, critical = pcall(mini._checkZones, mini, mini.CurrentScale)
			elseif type(mini.CheckPosition) == "function" and mini.MoverPosition and mini.SuccessZone then
				valid, win, critical = pcall(mini.CheckPosition, mini, mini.MoverPosition, mini.SuccessZone)
			end
			if valid and win and (not mini.Tutorial and not mini.CriticalOnly or critical) then
				return pcall(mini.Click, mini)
			end
			return false
		end

		function Day8.startObjective(session, entry, generation)
			local object = entry.native
			if not Day8.ready(generation) or not object:CanInteract() then
				return false
			end
			local wrapper = Day8.modules.PlayerWrapper
			local player = wrapper and wrapper.getWrapperFromPlayer(App.player)
			if not player then
				return false
			end
			local point = object:GetInteractionPositionForPlayer(App.player)
			if typeof(point) == "CFrame" then
				point = point.Position
			end
			if typeof(point) ~= "Vector3" then
				point = entry.part.Position
			end
			if
				not approach(point, generation, entry.object, false, function()
					return Day8.ready(generation) and entry.object.Parent ~= nil and object:CanInteract()
				end)
			then
				return false
			end
			for _, menu in ipairs(object.ProximityMenus or {}) do
				if menu.Config and type(menu.Config.Run) == "function" then
					local ok = call(entry.object, function()
						if Day8.ready(generation) and object:CanInteract() then
							menu.Config.Run()
							if not active(generation) and object.Active then
								object:Exit()
							end
						end
					end, 6, generation)
					if ok and active(generation) then
						local started = waitUntil(function()
							return object.Active == true or not entry.object.Parent
						end, 2, generation)
						if started and object.Active then
							session.objective = entry
							return true
						end
					end
					break
				end
			end
			return false
		end

		function Day8.sonariaThreats()
			local result = {}
			for _, object in ipairs(Collection:GetTagged("Mob")) do
				local part = Day8.part(object)
				if part and object:GetAttribute("Dead") ~= true then
					table.insert(result, { object = object, part = part, title = "Monster", threat = true })
				end
			end
			return result
		end

		function Day8.claws()
			local api = Day8.modules.SpawnedConsumableClient
			local result = {}
			for _, entry in pairs(api and api.GetAll and api.GetAll() or {}) do
				if
					entry.ConsumableType == "HollowClaw"
					and entry.SpawnPart
					and entry.SpawnPart.Parent
					and not entry.Claiming
				then
					local part = Day8.part(entry.SpawnPart)
					if part then
						table.insert(
							result,
							{ object = entry.SpawnPart, part = part, native = entry, title = "Hollow Claw" }
						)
					end
				end
			end
			return result
		end

		function Day8.boss(session, generation)
			if Day8.evade(session, Day8.sonariaThreats(), generation) then
				return "Moving clear of the monsters"
			end
			local wrapper = Day8.modules.PlayerWrapper.getWrapperFromPlayer(App.player)
			local hotbar = wrapper and wrapper.PlayerData and wrapper.PlayerData:FindFirstChild("Hotbar")
			local slot
			for _, value in ipairs(hotbar and hotbar:GetChildren() or {}) do
				if value:IsA("StringValue") and value.Value == "HollowClaw" then
					slot = value
					break
				end
			end
			if not slot then
				session.clawSlot = nil
				local claw = Day8.nearest(Day8.claws())
				if claw and claw.native:CanClaim() == true then
					if
						approach(claw.part.Position, generation, claw.object, false, function()
							return Day8.ready(generation)
						end)
					then
						call(claw.object, function()
							if Day8.ready(generation) then
								return claw.native:Claim()
							end
						end, 6, generation)
					end
					return "Getting a Hollow Claw"
				end
				if claw then
					return "Clear a hotbar slot for a Hollow Claw"
				end
				return "Waiting for another Hollow Claw to spawn"
			end
			local strike, hits = Day8.modules.HollowClawStrike, Day8.modules.StainBossHits
			if session.clawSlot ~= slot then
				strike.OnHotbarSlotPressed(slot)
				session.clawSlot = slot
			end
			local boss = strike.GetBossRoot()
			if not boss or not boss.Parent then
				return "Waiting for the boss"
			end
			if not hits.IsHittable() then
				return "Waiting for the boss to surface"
			end
			local _, root = character()
			if (root.Position - boss.Position).Magnitude > 120 then
				local flat = Vector3.new(root.Position.X - boss.Position.X, 0, root.Position.Z - boss.Position.Z)
				if flat.Magnitude < 1 then
					flat = Vector3.new(1, 0, 0)
				end
				approach(boss.Position + flat.Unit * 85, generation, nil, false, function()
					return Day8.ready(generation)
				end)
			end
			local service = Day8.modules.ConsumablesService
			if not Day8.bossAim then
				return "Aim at the boss and throw your Hollow Claw"
			end
			if service.CanUseConsumable(App.player, slot.Name) ~= true then
				return "Waiting for the claw cooldown"
			end
			if Day8.ready(generation) then
				App.event7.face(session, boss)
				if pause(0.06, generation) and Day8.ready(generation) then
					local _, aimed = strike.GetAim()
					if aimed and service.CanUseConsumable(App.player, slot.Name) == true then
						call("Hollow Claw", function()
							if Day8.ready(generation) then
								return service.UseConsumable(slot.Name)
							end
						end, 6, generation)
					end
				end
				EventInput.release(session)
			end
			return "Throwing Hollow Claws at the boss"
		end

		function Day8.upgrade(session, generation)
			local object = Storage:FindFirstChild("ChoiceUpgradeReplication")
			local payload = object and object:GetAttribute("Choices")
			if type(payload) ~= "string" or payload == "" then
				session.upgrade = nil
				return false
			end
			if session.upgrade ~= payload and os.clock() >= (session.upgradeAt or 0) then
				session.upgradeAt = os.clock() + 3
				local ok, choices = pcall(Http.JSONDecode, Http, payload)
				if ok and type(choices) == "table" and #choices > 0 then
					local api = Day8.modules.ChoiceUpgradeService
					if api then
						local accepted, result = call("Sonaria upgrade", function()
							if active(generation) then
								return api.RequestToSelectUpgrade(1)
							end
						end, 5, generation)
						if accepted and result == true then
							session.upgrade = payload
						end
					end
				end
			end
			return true
		end

		function Day8.runSonaria(generation)
			if game.PlaceId ~= current.eventPlace then
				return false, "Join the Hollow event run, then press Start"
			end
			local needed = {
				"GameplayStateService",
				"GameModeRunService",
				"PlayerWrapper",
				"Objective",
				"SpawnedConsumableClient",
				"ConsumablesService",
				"HollowClawStrike",
				"StainBossHits",
				"ReviveService",
				"ChoiceUpgradeService",
			}
			for _, name in ipairs(needed) do
				status("Loading Sonaria Horror Escape", "Waiting for the event controls", 0)
				if not waitUntil(function()
					return Day8.load(name, generation)
				end, 25, generation) then
					return false, "The event controls haven't loaded. Choose a character, then try Start."
				end
			end
			local session = { retry = {}, round = nil }
			table.insert(App.cleanups, function()
				Day8.releaseObjective(session)
			end)
			Day8.session = session
			local badgeAt, readyAt = 0, 0
			while active(generation) do
				if os.clock() >= badgeAt then
					badgeAt = os.clock() + 12
					if verify(current, true) then
						return true, "Hollow badge earned"
					end
				end
				local mode = Day8.modules.GameModeRunService
				local round = Day8.state("RoundNumber") or 0
				if session.round ~= round then
					Day8.releaseObjective(session)
					session.round, session.retry = round, {}
				end
				local native = Day8.modules.Objective.GetActiveInteraction()
				if native and not session.objective then
					for _, entry in ipairs(Day8.objectiveItems()) do
						if entry.native == native then
							session.objective = entry
							break
						end
					end
				end
				local alive = Day8.modules.GameplayStateService.IsPlayerAlive(App.player)
				if mode.GetModeId() ~= "RobloxHalloween2026" then
					Day8.releaseObjective(session)
					status("Waiting for the Hollow run", "Join through the Hollow event gate", 0)
				elseif not alive then
					Day8.releaseObjective(session)
					status("Waiting to revive", "Using a free revive if one is available", round / 6)
					local revive = Day8.modules.ReviveService
					if revive.CanUseFreeRevive(App.player) and os.clock() >= (session.reviveAt or 0) then
						session.reviveAt = os.clock() + 8
						pcall(revive.RequestFreeRevive)
					end
				elseif Day8.upgrade(session, generation) then
					Day8.releaseObjective(session)
					status("Picking an upgrade", "Waiting for the next round", round / 6)
				elseif not session.objective and not Day8.ready(generation) then
					status("Waiting for the run", "Choose your character or wait for the cutscene", round / 6)
				elseif Day8.state("BossFightDefeated") == true then
					Day8.releaseObjective(session)
					status("Boss defeated", "Let the ending finish. Checking for the badge.", 0.98)
				elseif Day8.modules.StainBossHits.IsActive() then
					Day8.releaseObjective(session)
					status("The Hollow boss", Day8.boss(session, generation), 0.8)
				elseif session.objective then
					local entry = session.objective
					if
						not entry.object.Parent
						or entry.object:GetAttribute("Dead") == true
						or entry.object:GetAttribute("Activated") == true
						or (tonumber(entry.object:GetAttribute("Health")) or 1) <= 0
					then
						Day8.releaseObjective(session)
					elseif entry.native.Active then
						status("Clearing the infection", "Staying here until it's done", math.min(0.8, round / 6))
						Day8.skill(entry.native)
						local click = entry.native.ActiveMaid and entry.native.ActiveMaid.ClickMinigame
						local target = click and click.ActiveTarget
						if
							not entry.native.ActiveSkillCheck
							and target
							and target.Instance
							and target.Instance.Visible
							and target.Config
							and type(target.Config.OnClick) == "function"
						then
							pcall(target.Config.OnClick)
						end
						local _, gap = Day8.nearest(Day8.sonariaThreats())
						if gap and gap < 16 then
							session.retry[entry.object] = os.clock() + 4
							Day8.releaseObjective(session)
							Day8.evade(session, Day8.sonariaThreats(), generation)
						end
					else
						session.retry[entry.object] = os.clock() + 1
						Day8.releaseObjective(session)
					end
				elseif Day8.evade(session, Day8.sonariaThreats(), generation) then
					status("Moving away from the monsters", "Looking for a safer infection", round / 6)
				else
					local candidates = {}
					for _, entry in ipairs(Day8.objectiveItems()) do
						if
							entry.native:CanInteract()
							and os.clock() >= (session.retry[entry.object] or 0)
							and Day8.clearance(entry.part.Position, Day8.sonariaThreats()) > 24
						then
							table.insert(candidates, entry)
						end
					end
					local target = Day8.nearest(candidates)
					if target then
						status("Going to an infection", "Round " .. tostring(round) .. " / 6", round / 6)
						if not Day8.startObjective(session, target, generation) then
							session.retry[target.object] = os.clock() + 2
						end
					else
						status("Waiting for the next round", "No available infection nearby", round / 6)
						if os.clock() >= readyAt and Day8.modules.GameplayStateService.IsInIntermission() then
							readyAt = os.clock() + 5
							pcall(Day8.modules.GameplayStateService.RequestToReadyUp)
						end
					end
				end
				if not pause(0.08, generation) then
					break
				end
			end
			return false, "Stopped"
		end

		-- manual guides
		function Day8.items()
			if current.id == "killer" then
				local items = Day8.killerItems()
				for _, entry in ipairs(Day8.members()) do
					table.insert(items, entry)
				end
				for _, entry in ipairs(Day8.killerThreats()) do
					table.insert(items, entry)
				end
				for _, entry in ipairs(Day8.killerExits()) do
					table.insert(items, entry)
				end
				return items
			elseif current.id == "sonariaescape" then
				local items = Day8.objectiveItems()
				for _, entry in ipairs(Day8.claws()) do
					table.insert(items, entry)
				end
				for _, entry in ipairs(Day8.sonariaThreats()) do
					table.insert(items, entry)
				end
				return items
			end
			return Day8.pedestals(Day8.hollowState())
		end

		function Day8.clearMarkers()
			Day8.markers = false
			Day8.markerEpoch = (Day8.markerEpoch or 0) + 1
			for _, item in pairs(Day8.visuals or {}) do
				item.highlight:Destroy()
				item.billboard:Destroy()
			end
			Day8.visuals = {}
		end

		function Day8.draw()
			local keep = {}
			local _, root = character()
			local items = Day8.items()
			if root then
				table.sort(items, function(a, b)
					return (a.part.Position - root.Position).Magnitude < (b.part.Position - root.Position).Magnitude
				end)
			end
			for index, entry in ipairs(items) do
				if index > 24 then
					break
				end
				local visual = Day8.visuals[entry.object]
				if not visual then
					local highlight = Instance.new("Highlight")
					highlight.Adornee = entry.object:IsA("Model") and entry.object or entry.part
					highlight.FillTransparency, highlight.DepthMode = 0.85, Enum.HighlightDepthMode.AlwaysOnTop
					highlight.OutlineColor = entry.threat and Color3.fromRGB(255, 100, 100) or colors.mint
					highlight.Parent = App.gui
					local billboard = Instance.new("BillboardGui")
					billboard.Size, billboard.StudsOffset, billboard.AlwaysOnTop =
						UDim2.fromOffset(170, 42), Vector3.new(0, 3, 0), true
					billboard.Adornee, billboard.Parent = entry.part, App.gui
					local text = Instance.new("TextLabel")
					text.Size, text.BackgroundTransparency, text.TextSize = UDim2.fromScale(1, 1), 1, 13
					text.TextColor3, text.TextStrokeTransparency, text.Parent = highlight.OutlineColor, 0.2, billboard
					visual = { highlight = highlight, billboard = billboard, text = text }
					Day8.visuals[entry.object] = visual
				end
				visual.text.Text = entry.title
					.. (root and "\n" .. math.floor((entry.part.Position - root.Position).Magnitude) .. " studs" or "")
				keep[entry.object] = true
			end
			for object, visual in pairs(Day8.visuals) do
				if not keep[object] then
					visual.highlight:Destroy()
					visual.billboard:Destroy()
					Day8.visuals[object] = nil
				end
			end
		end

		function Day8.toggleMarkers()
			if Day8.markers then
				Day8.clearMarkers()
				refresh()
				return
			end
			Day8.markers, Day8.visuals = true, {}
			Day8.markerEpoch = (Day8.markerEpoch or 0) + 1
			local epoch = Day8.markerEpoch
			task.spawn(function()
				if current.id == "sonariaescape" then
					for _, name in ipairs({ "Objective", "SpawnedConsumableClient" }) do
						Day8.load(name)
					end
				elseif current.id == "hollow" then
					Day8.offerings = hollowModule("OfferingsPuzzle")
				end
				while App.alive and Day8.markers and Day8.markerEpoch == epoch do
					pcall(Day8.draw)
					task.wait(0.4)
				end
			end)
			refresh()
		end

		function Day8.clear()
			Day8.helpers = false
			Day8.helperEpoch = (Day8.helperEpoch or 0) + 1
			Day8.clearMarkers()
			if Day8.session then
				Day8.releaseObjective(Day8.session)
				Day8.session = nil
			end
		end

		function Day8.startHelpers()
			if Day8.helpers or current.id ~= "sonariaescape" then
				return
			end
			Day8.helpers = true
			Day8.helperEpoch = (Day8.helperEpoch or 0) + 1
			local epoch = Day8.helperEpoch
			task.spawn(function()
				if Day8.load("Objective") then
					while App.alive and Day8.helpers and Day8.helperEpoch == epoch do
						if Day8.skills then
							local object = Day8.modules.Objective.GetActiveInteraction()
							if object then
								pcall(Day8.skill, object)
							end
						end
						task.wait(0.08)
					end
				end
				if Day8.helperEpoch == epoch then
					Day8.helpers = false
					refresh()
				end
			end)
		end
		App.day8 = Day8
		runners.killer, runners.sonariaescape = Day8.runKiller, Day8.runSonaria
	end)()
end

-- levers + day 9
do
	(function()
		local Day9 = { markers = false, assist = false, lookAway = true, visuals = {} }
		local piggyTags = {
			BossCannon = "Cannon",
			BossPlank = "Plank",
			BossBot = "Boss bot",
			TentaclePile = "Tentacle pile",
			ArenaPlatform = "Platform",
		}

		function Day9.value(parent, name)
			local object = parent and parent:FindFirstChild(name)
			return object and object.Value
		end

		function Day9.part(object)
			return App.day8.part(object)
		end

		-- floor 9
		function Bridge.leversCompleted()
			for number in tostring(App.player:GetAttribute("CompletedFloors") or ""):gmatch("%d+") do
				if tonumber(number) == 9 then
					return true
				end
			end
			return false
		end

		function Day9.leverState()
			local puzzle = Day9.levers
			local state = puzzle and puzzle.getState()
			return type(state) == "table"
					and type(state.Walls) == "table"
					and type(state.Levers) == "table"
					and type(state.Opened) == "number"
					and state
				or nil
		end

		function Day9.leverItems(state)
			local items = {}
			if not state then
				return items
			end
			local expected = state.Walls[state.Opened + 1]
			for _, object in ipairs(Collection:GetTagged(expected and "%WallLever" or "%LeverWallsRelic")) do
				local part = Day9.part(object)
				local key = object:GetAttribute(tostring(App.player.UserId))
				local symbol = key ~= nil and (state.Levers[tostring(key)] or state.Levers[key])
				if part and (not expected or symbol == expected) then
					table.insert(items, {
						object = object,
						part = part,
						key = key,
						title = expected and "Next lever: " .. tostring(expected) or "Take rune",
					})
				end
			end
			return items
		end

		function Bridge.solveLevers(objects, _, generation)
			local why
			Day9.levers, why = hollowModule("LeverWallsPuzzle", generation)
			if not Day9.levers then
				return false, why
			end
			local deadline, retryAt = os.clock() + 300, 0
			while active(generation) and os.clock() < deadline do
				if App.player:GetAttribute("HasRelic") == true then
					return true
				end
				if App.player:GetAttribute("InMaze") ~= 9 then
					return false, "Floor changed"
				end
				local state = Day9.leverState()
				local item = state and App.day8.nearest(Day9.leverItems(state))
				if state and state.Solved then
					status("Waiting for the rune", "", 0.84)
				elseif item and os.clock() >= retryAt then
					local opened, expected = state.Opened, state.Walls[state.Opened + 1]
					status(
						expected and "Pulling the next lever" or "Taking the rune",
						item.title,
						0.12 + 0.68 * math.min(opened / math.max(1, #state.Walls), 1)
					)
					local kind = expected and "WallLever" or "LeverWallsRelic"
					local ok, native = call("Floor 9 " .. kind, function()
						return objects.getObjectAsync(kind, item.object)
					end, 4, generation)
					if ok and native and active(generation) then
						local point = EventInput.point(native.prompt and native.prompt.Parent or item.part)
						local moved = point and approach(point, generation, native.handle or item.object)
						local live = Day9.leverState()
						if moved and live == state and live.Opened == opened and not live.Solved then
							local valid = not expected or type(native.icon) == "function" and native:icon() == expected
							if valid then
								local sent = call("Floor 9 action", function()
									if expected then
										Day9.levers.pull(native)
									else
										Day9.levers.claim(native)
									end
								end, 4, generation)
								if sent then
									waitUntil(function()
										local latest = Day9.leverState()
										return App.player:GetAttribute("HasRelic") == true
											or latest ~= state
											or latest and (latest.Opened ~= opened or latest.Solved)
									end, 5, generation)
								end
							end
						end
					end
					retryAt = os.clock() + 1
				else
					status("Waiting for the next lever", "It'll retry when the room loads", 0.12)
				end
				if not pause(0.3, generation) then
					break
				end
			end
			return false, active(generation) and "The lever room hasn't advanced" or "Stopped"
		end

		-- live objects
		function Day9.roots()
			local roots = {}
			if current.id == "peta" then
				for _, name in ipairs({ "MapGenerated", "MapCore", "SpawnedItems", "SystemParts" }) do
					local object = getPath(workspace, "Server", name)
					if object then
						table.insert(roots, object)
					end
				end
			elseif current.id == "piggy" then
				for _, arena in ipairs(Collection:GetTagged("BossArena")) do
					if arena:IsDescendantOf(workspace) then
						table.insert(roots, arena)
					end
				end
			end
			return roots
		end

		function Day9.resetIndex()
			Day9.index = { queue = {}, head = 1, objects = {}, nextScan = 0 }
		end

		function Day9.scan()
			if not Day9.index then
				Day9.resetIndex()
			end
			local index = Day9.index
			if index.head > #index.queue then
				if os.clock() < index.nextScan then
					return index.objects
				end
				index.queue, index.head, index.pending = Day9.roots(), 1, {}
				index.nextScan = os.clock() + 1.5
			end
			local start = os.clock()
			for _ = 1, 350 do
				local object = index.queue[index.head]
				if not object then
					break
				end
				index.head += 1
				if object:IsDescendantOf(workspace) then
					if object:IsA("ProximityPrompt") or object.Name == "NozokiAna" or object.Name == "Safe" then
						table.insert(index.pending, object)
					end
					for _, child in ipairs(object:GetChildren()) do
						table.insert(index.queue, child)
					end
				end
				if os.clock() - start > 0.003 then
					break
				end
			end
			if index.head > #index.queue then
				index.objects, index.pending = index.pending, nil
			end
			return index.objects
		end

		function Day9.petaState()
			local state = Storage:FindFirstChild("GameStatus")
			return state, tonumber(Day9.value(state, "Stage"))
		end

		function Day9.petaEntries()
			local items = {}
			for _, object in ipairs(Day9.scan()) do
				if object.Parent and object:IsDescendantOf(workspace) then
					if object:IsA("ProximityPrompt") and object.Enabled then
						local holder, title, kind = object.Parent, nil, nil
						local room = holder and holder.Parent
						if object.Name == "focus" and room and room:FindFirstChild("kimo") then
							local hint = getPath(room, "fakeRoom", "doll", "HintPaper", "SurfaceGui")
							if not hint or not hint.Enabled then
								title, kind = "Evil room", "hole"
							end
						elseif object:GetAttribute("isObtainable") then
							if holder.Name == "Key" or room and room.Name == "Key" then
								title, kind = "Key", "key"
							end
						elseif object:GetAttribute("isOfudaBox") then
							title, kind = "Ofuda box", "box"
						elseif room and room.Name == "Safe" then
							title, kind = "Safe", "safe"
						elseif object:GetAttribute("SFX") == "Fusuma" and object.ActionText == "Open" then
							title, kind = "Door", "door"
						end
						local point = title and EventInput.point(holder)
						local part = point and Day9.part(holder)
						if part then
							table.insert(items, {
								object = object,
								part = part,
								point = point,
								title = title,
								kind = kind,
								owner = room,
							})
						end
					end
				end
			end
			return items
		end

		function Day9.piggyItems()
			local items = {}
			for tag, title in pairs(piggyTags) do
				for _, object in ipairs(Collection:GetTagged(tag)) do
					local part = Day9.part(object)
					if part and not object:GetAttribute("BreakAt") then
						table.insert(items, { object = object, part = part, title = title, threat = tag == "BossBot" })
					end
				end
			end
			for _, arena in ipairs(Day9.roots()) do
				local puzzle = arena:FindFirstChild("PreBossPuzzle")
				if puzzle then
					for index = 1, 12 do
						local section = puzzle:FindFirstChild("Section" .. index)
						if section and App.player:GetAttribute("CrossedSection" .. index) ~= true then
							local part = Day9.part(section)
							if part then
								table.insert(items, { object = section, part = part, title = "Section " .. index })
							end
							break
						end
					end
				end
			end
			return items
		end

		function Day9.piggyReady()
			local at = App.player:GetAttribute("VoidRescueAt")
			return not App.player:GetAttribute("HalloweenCutscene")
				and not App.player:GetAttribute("InPortalTransition")
				and not (type(at) == "number" and workspace:GetServerTimeNow() < at + 2)
				and App.day8.ready(nil)
		end

		function Day9.signature(entry)
			local object = entry.object
			if not object.Parent then
				return "gone"
			end
			local owner = entry.owner or object.Parent
			return tostring(object.Enabled)
				.. ":"
				.. tostring(owner:GetAttribute("claimed"))
				.. ":"
				.. tostring(owner:GetAttribute("shared"))
				.. ":"
				.. tostring(owner:GetAttribute("isOpen"))
		end

		function Day9.hold(session, entry, generation, allowed)
			local before = Day9.signature(entry)
			local ok = EventInput.hold(session, entry.object, generation, allowed, {
				accepted = function()
					return Day9.signature(entry) ~= before
				end,
			})
			EventInput.release(session)
			return ok
		end

		function Day9.nearby(session, generation)
			if not Day9.piggyReady() then
				return false
			end
			local _, root = character()
			if not root then
				return false
			end
			local entries = {}
			for _, prompt in ipairs(Day9.scan()) do
				if prompt:IsA("ProximityPrompt") and prompt.Parent and prompt.Enabled then
					local point = EventInput.point(prompt.Parent)
					local part = point and Day9.part(prompt.Parent)
					if
						part
						and (root.Position - point).Magnitude <= math.min(prompt.MaxActivationDistance, 12)
						and (session.retry[prompt] or 0) < os.clock()
					then
						table.insert(entries, { object = prompt, part = part })
					end
				end
			end
			local entry = App.day8.nearest(entries)
			if not entry then
				return false
			end
			Day9.hold(session, entry, generation, Day9.piggyReady)
			session.retry[entry.object] = os.clock() + 2
			return true
		end

		-- evil room
		function Day9.petaUI()
			return getPath(App.player, "PlayerGui", "GameUI")
		end

		function Day9.click(object, generation)
			if not active(generation) or not object or not object:IsA("GuiButton") or not Hospital.visible(object) then
				return false
			end
			if type(firesignal) == "function" then
				local ok = pcall(firesignal, object.MouseButton1Click)
				if ok then
					return true
				end
			end
			return Hospital.guiTap(object, generation, true)
		end

		function Day9.apparition(ui)
			local image = ui and ui:FindFirstChild("kimoSUI")
			local transparency = Day9.value(image, "transp")
			return image
					and image.Adornee
					and (type(transparency) == "number" and transparency <= 0.1 or type(image.Brightness) == "number" and image.Brightness >= 1)
					and true
				or false
		end

		function Day9.avoid(session, generation, force)
			local ui = Day9.petaUI()
			local focus = ui and ui:FindFirstChild("NozokiUI")
			if not focus or not focus.Visible or App.player:GetAttribute("inFocus") ~= true then
				session.closing = nil
				Day9.closing = nil
				return false
			end
			if Day9.closing and os.clock() < Day9.closing then
				return true
			end
			if force or Day9.apparition(ui) then
				if Day9.click(getPath(focus, "Close", "Button"), generation) then
					Day9.closing = os.clock() + 1
				end
			end
			return true
		end

		function Day9.petaReady(generation)
			local state = Day9.petaState()
			return active(generation)
				and not App.player:GetAttribute("DEAD")
				and not App.player:GetAttribute("inFocus")
				and not App.player:GetAttribute("InCutscene")
				and not App.player:GetAttribute("teleporting")
				and state
				and Day9.value(state, "StageResetting") ~= true
				and App.day8.ready(generation)
		end

		function Day9.openDoor(session, point, generation)
			local _, root = character()
			if not root then
				return false
			end
			for _, entry in ipairs(Day9.petaEntries()) do
				if
					entry.kind == "door"
					and (root.Position - entry.point).Magnitude <= math.min(8, entry.object.MaxActivationDistance)
					and (entry.point - point).Magnitude < (root.Position - point).Magnitude
					and (session.retry[entry.object] or 0) < os.clock()
				then
					Day9.hold(session, entry, generation, function()
						return Day9.petaReady(generation)
					end)
					session.retry[entry.object] = os.clock() + 3
					return true
				end
			end
			return false
		end

		function Day9.walk(session, point, generation, valid)
			local model, root, humanoid = character()
			if not root or not Day9.petaReady(generation) then
				return false
			end
			if (root.Position - point).Magnitude < 3 then
				return true
			end
			local ok, waypoints = call("PETAPETA route", function()
				local path = game:GetService("PathfindingService")
					:CreatePath({ AgentRadius = 1.5, AgentHeight = 5, AgentCanJump = true })
				path:ComputeAsync(root.Position, point)
				return path.Status == Enum.PathStatus.Success and path:GetWaypoints() or nil
			end, 4, generation)
			if not ok or not waypoints then
				Day9.openDoor(session, point, generation)
				return false
			end
			local deadline = os.clock() + 45
			for _, waypoint in ipairs(waypoints) do
				if not Day9.petaReady(generation) or valid and not valid() or App.player.Character ~= model then
					return false
				end
				if waypoint.Action == Enum.PathWaypointAction.Jump then
					humanoid.Jump = true
				end
				humanoid:MoveTo(waypoint.Position)
				session.walking = humanoid
				local last, stalled = root.Position, os.clock() + 2
				while
					Vector3.new(root.Position.X - waypoint.Position.X, 0, root.Position.Z - waypoint.Position.Z).Magnitude
						> 2.5
					or math.abs(root.Position.Y - waypoint.Position.Y) > 6
				do
					if
						not Day9.petaReady(generation)
						or App.player.Character ~= model
						or valid and not valid()
						or os.clock() > deadline
						or os.clock() > stalled
					then
						humanoid:MoveTo(root.Position)
						session.walking = nil
						if Day9.petaReady(generation) then
							Day9.openDoor(session, point, generation)
						end
						return false
					end
					if (root.Position - last).Magnitude > 0.5 then
						last, stalled = root.Position, os.clock() + 2
					end
					if not pause(0.08, generation) then
						return false
					end
				end
			end
			session.walking = nil
			return true
		end

		function Day9.safe(session, generation)
			local ui = Day9.petaUI()
			local panel, lockUI = ui and ui:FindFirstChild("SafeUI"), ui and ui:FindFirstChild("SafeLockUI")
			if not panel or not panel.Visible or not lockUI or not lockUI.Enabled or not session.safe then
				return false
			end
			local safe = session.safe
			if lockUI.Adornee ~= safe:FindFirstChild("UIPart") then
				return false
			end
			local function owned()
				return active(generation)
					and safe.Parent
					and panel.Visible
					and lockUI.Enabled
					and App.player:GetAttribute("inFocus") == true
					and not App.player:GetAttribute("DEAD")
			end
			if not session.feedbackConnection then
				local remote = Storage:FindFirstChild("MemoTextColorUpdateEvent")
				if not remote or not remote:IsA("RemoteEvent") then
					return true
				end
				session.feedbackConnection = remote.OnClientEvent:Connect(function(kind, matches)
					if kind == "FindCode" and owned() and type(matches) == "string" then
						session.matches, session.feedbackVersion = matches, (session.feedbackVersion or 0) + 1
					end
				end)
			end
			status("Opening the safe", "Turning the dials", 0.3)
			for index = 1, 3 do
				local solved = false
				for _ = 1, 12 do
					if not owned() then
						break
					end
					local version = session.feedbackVersion or 0
					if not Day9.click(getPath(lockUI, "Circle" .. index, "Left"), generation) then
						break
					end
					local response = waitUntil(function()
						return (session.feedbackVersion or 0) > version
					end, 2, generation)
					if not response then
						break
					end
					if (session.matches or ""):find(tostring(index), 1, true) then
						solved = true
						break
					end
					if not pause(0.18, generation) then
						break
					end
				end
				if not solved then
					break
				end
			end
			if owned() and session.matches == "123" then
				local prompt = getPath(safe, "HandleInteractPoint", "handle")
				if prompt then
					EventInput.hold(session, prompt, generation, owned, {
						customCamera = true,
						accepted = function()
							return Day9.value(safe, "Unlocked") == true
						end,
					})
				end
				waitUntil(function()
					return Day9.value(safe, "Unlocked") == true or not owned()
				end, 3, generation)
			end
			if owned() then
				Day9.click(getPath(panel, "Close", "Button"), generation)
			end
			if session.feedbackConnection then
				session.feedbackConnection:Disconnect()
				session.feedbackConnection = nil
			end
			session.matches, session.safe = nil, nil
			EventInput.release(session)
			return true
		end

		function Day9.ofuda(session, generation)
			local state = Day9.petaState()
			if not state or Day9.value(state, "OfudaPlaced") or App.player:GetAttribute("isInRoom") ~= false then
				return false
			end
			local model, root, humanoid = character()
			local tool = model and model:FindFirstChildWhichIsA("Tool")
			if not tool or not tool:GetAttribute("Ofuda") then
				for _, child in ipairs((App.player:FindFirstChild("Backpack") or App.player):GetChildren()) do
					if child:IsA("Tool") and child:GetAttribute("Ofuda") then
						tool = child
						break
					end
				end
			end
			if not tool or not tool:GetAttribute("Ofuda") then
				return false
			end
			local camera = workspace.CurrentCamera
			if not camera or not Day9.petaReady(generation) then
				return false
			end
			humanoid:EquipTool(tool)
			local previous = camera.CFrame
			local aim = CFrame.lookAt(camera.CFrame.Position, root.Position - Vector3.new(0, 3, 0))
			session.look = {
				camera = camera,
				kind = camera.CameraType,
				previous = previous,
				aim = aim,
				cameraEpoch = App.cameraEpoch,
			}
			camera.CFrame = aim
			if pause(0.3, generation) and Day9.petaReady(generation) then
				tool:Activate()
			end
			pause(0.5, generation)
			EventInput.release(session)
			return true
		end

		function Day9.release(session)
			EventInput.release(session)
			if session.walking then
				local _, root = character()
				if root then
					pcall(session.walking.MoveTo, session.walking, root.Position)
				end
				session.walking = nil
			end
			if session.guideConnection then
				session.guideConnection:Disconnect()
				session.guideConnection = nil
			end
			if session.feedbackConnection then
				session.feedbackConnection:Disconnect()
				session.feedbackConnection = nil
			end
			if session.safe then
				local ui = Day9.petaUI()
				local lockUI = ui and ui:FindFirstChild("SafeLockUI")
				if lockUI and lockUI.Adornee == session.safe:FindFirstChild("UIPart") then
					Day9.click(getPath(ui, "SafeUI", "Close", "Button"), nil)
				end
				session.safe = nil
			end
			if session.ownedFocus then
				Day9.avoid(session, nil, true)
				session.ownedFocus = nil
			end
		end

		function Day9.runPeta(generation)
			local session = { retry = {} }
			table.insert(App.cleanups, function()
				Day9.release(session)
			end)
			local checked, lastBadge, guideRemote = nil, -10, nil
			while active(generation) do
				local state, stage = Day9.petaState()
				local ui = Day9.petaUI()
				if os.clock() - lastBadge >= 8 and App.player:GetAttribute("inFocus") ~= true then
					lastBadge = os.clock()
					checked = verify(current, generation)
					if checked == true then
						return true, "PETAPETA badge earned"
					end
				end
				local remote = Storage:FindFirstChild("Stage1GuideEvent")
				if remote and remote ~= guideRemote and remote:IsA("RemoteEvent") then
					if session.guideConnection then
						session.guideConnection:Disconnect()
					end
					guideRemote = remote
					session.guideConnection = remote.OnClientEvent:Connect(function(kind, point)
						if kind == "ShowArrow" and typeof(point) == "Vector3" then
							session.guide = point
						elseif kind == "HideArrow" then
							session.guide = nil
						end
					end)
				end
				if session.stage ~= stage then
					session.stage, session.retry, session.guide = stage, {}, nil
					Day9.resetIndex()
				end
				if stage == 1 and not session.guide then
					for index = 20, 1, -1 do
						local arrow = workspace:FindFirstChild("Stage1PathArrow_" .. index .. "_" .. App.player.UserId)
						local part = arrow and Day9.part(arrow)
						if part then
							session.arrow = part
							break
						end
					end
				end
				if Day9.safe(session, generation) then
				elseif Day9.avoid(session, generation, false) then
					status("Watching the hole", "Waiting for the apparition", 0.85)
				elseif Day9.petaReady(generation) then
					local entries, choices = Day9.petaEntries(), {}
					for _, entry in ipairs(entries) do
						local wanted = stage == 3 and entry.kind == "hole"
							or (stage == 1 or stage == 2)
								and (entry.kind == "key" and Day9.value(state, "KeyObtained") ~= true or entry.kind == "box" and Day9.value(
									state,
									"KeyObtained"
								) == true and Day9.value(state, "BoxOpened") ~= true or stage == 2 and entry.kind == "safe" and Day9.value(
									state,
									"KeyObtained"
								) ~= true and entry.object.Name == "focus")
						if (session.retry[entry.object] or 0) <= os.clock() and wanted then
							table.insert(choices, entry)
						end
					end
					local entry = App.day8.nearest(choices)
					if entry then
						status(
							"Heading to " .. entry.title:lower(),
							"Stage " .. tostring(stage),
							stage == 3 and 0.7 or 0.15
						)
						local valid = function()
							return entry.object.Parent and entry.object.Enabled and select(2, Day9.petaState()) == stage
						end
						if Day9.walk(session, entry.point, generation, valid) and valid() then
							if entry.kind == "hole" then
								session.ownedFocus = true
							end
							if entry.kind == "safe" then
								session.safe = entry.owner
							end
							Day9.hold(session, entry, generation, function()
								return Day9.petaReady(generation)
							end)
						end
						session.retry[entry.object] = os.clock() + (entry.kind == "box" and 6 or 3)
					elseif (stage == 1 or stage == 2) and Day9.ofuda(session, generation) then
						status("Placing the hallway Ofuda", "", 0.3)
					elseif stage == 1 and (session.guide or session.arrow and session.arrow.Parent) then
						local point = session.guide or session.arrow.Position
						Day9.walk(session, point, generation, function()
							return select(2, Day9.petaState()) == stage
						end)
					else
						status(
							"PETAPETA",
							stage == 3 and "Looking for the evil room"
								or stage == 2 and "Looking for the key and safe"
								or "Follow the story to stage 3. Keys, boxes and the evil room have assist.",
							0.1
						)
					end
				else
					status(
						"Waiting for PETAPETA",
						App.player:GetAttribute("DEAD") and "Join the next run to continue" or "Waiting for the stage",
						0.1
					)
				end
				if not pause(0.08, generation) then
					break
				end
			end
			return false, "Stopped"
		end

		-- piggy
		function Day9.piggyStatus()
			local arena = Day9.roots()[1]
			if not arena then
				return "Enter The Hollow from Piggy's menu. Helpers will pick it up here."
			end
			local phase = arena:GetAttribute("State")
			if phase == "Vortex" then
				return "Vortex active. Stay clear of the middle."
			end
			if phase == "Done" then
				return "Finish the portal sequence to claim the badge"
			end
			if phase == "Charge" or phase == "Fire" then
				return "Boss attack. Use the platforms for cover."
			end
			return "Follow the section markers. Planks and cannons are marked too."
		end

		function Day9.runPiggy(generation)
			local session, lastBadge = { retry = {} }, -10
			table.insert(App.cleanups, function()
				Day9.release(session)
			end)
			if not Day9.markers then
				Day9.toggleMarkers()
			end
			while active(generation) do
				if os.clock() - lastBadge >= 8 then
					lastBadge = os.clock()
					if verify(current, generation) == true then
						return true, "Piggy badge earned"
					end
				end
				status("Piggy helpers", Day9.piggyStatus(), 0)
				if Day9.roots()[1] then
					Day9.nearby(session, generation)
				end
				if not pause(0.2, generation) then
					break
				end
			end
			return false, "Stopped"
		end

		-- markers
		function Day9.items()
			if current.id == "piggy" then
				return Day9.piggyItems()
			end
			if current.id == "peta" then
				return Day9.petaEntries()
			end
			return Day9.leverItems(Day9.leverState())
		end

		function Day9.clearMarkers()
			Day9.markers = false
			for _, visual in pairs(Day9.visuals) do
				visual.highlight:Destroy()
				visual.billboard:Destroy()
			end
			Day9.visuals = {}
		end

		function Day9.draw()
			local keep, entries = {}, Day9.items()
			local _, root = character()
			if root then
				table.sort(entries, function(a, b)
					return (a.part.Position - root.Position).Magnitude < (b.part.Position - root.Position).Magnitude
				end)
			end
			for index, entry in ipairs(entries) do
				if index > 24 then
					break
				end
				local visual = Day9.visuals[entry.object]
				if not visual then
					local highlight = Instance.new("Highlight")
					highlight.Adornee = entry.part
					highlight.FillTransparency, highlight.DepthMode = 0.85, Enum.HighlightDepthMode.AlwaysOnTop
					highlight.OutlineColor = entry.threat and colors.coral or colors.mint
					highlight.Parent = App.gui
					local billboard = Instance.new("BillboardGui")
					billboard.Size, billboard.StudsOffset, billboard.AlwaysOnTop =
						UDim2.fromOffset(180, 42), Vector3.new(0, 3, 0), true
					billboard.Adornee, billboard.Parent = entry.part, App.gui
					local text =
						label(billboard, "", UDim2.fromOffset(0, 0), UDim2.fromScale(1, 1), 13, highlight.OutlineColor)
					text.TextStrokeTransparency = 0.2
					visual = { highlight = highlight, billboard = billboard, text = text }
					Day9.visuals[entry.object] = visual
				end
				visual.text.Text = entry.title
					.. (root and "\n" .. math.floor((entry.part.Position - root.Position).Magnitude) .. " studs" or "")
				keep[entry.object] = true
			end
			for object, visual in pairs(Day9.visuals) do
				if not keep[object] then
					visual.highlight:Destroy()
					visual.billboard:Destroy()
					Day9.visuals[object] = nil
				end
			end
		end

		function Day9.watch()
			if Day9.watching then
				return
			end
			Day9.watching = true
			Day9.epoch = (Day9.epoch or 0) + 1
			local epoch, session, nextDraw = Day9.epoch, { retry = {} }, 0
			Day9.helperSession = session
			task.spawn(function()
				while
					App.alive
					and Day9.epoch == epoch
					and (Day9.markers or Day9.assist or current.id == "peta" and Day9.lookAway)
				do
					local ok = pcall(function()
						if Day9.markers and os.clock() >= nextDraw then
							Day9.draw()
							nextDraw = os.clock() + 0.4
						end
						if current.id == "peta" and Day9.lookAway then
							Day9.avoid(session, nil, false)
						elseif not App.running and current.id == "piggy" and Day9.assist then
							Day9.nearby(session)
						end
					end)
					if not ok then
						EventInput.release(session)
					end
					task.wait(0.08)
				end
				Day9.release(session)
				if Day9.epoch == epoch then
					Day9.watching, Day9.helperSession = false, nil
				end
			end)
		end

		function Day9.toggleMarkers()
			if Day9.markers then
				Day9.clearMarkers()
			else
				Day9.markers = true
				if current.id == "hollow" then
					task.spawn(function()
						Day9.levers = hollowModule("LeverWallsPuzzle")
					end)
				end
				Day9.watch()
			end
			refresh()
		end

		function Day9.clear()
			Day9.assist, Day9.lookAway = false, false
			Day9.epoch, Day9.watching = (Day9.epoch or 0) + 1, false
			Day9.clearMarkers()
			if Day9.helperSession then
				Day9.release(Day9.helperSession)
				Day9.helperSession = nil
			end
			Day9.index = nil
		end

		App.day9 = Day9
		runners.peta, runners.piggy = Day9.runPeta, Day9.runPiggy
	end)()
end

-- discord + manual helpers
do
	(function()
		local Qol = { invite = "discord.gg/ntGXMJsVB5", code = "ntGXMJsVB5", visuals = {}, epoch = 0 }

		-- invite
		function Qol.noticeKey()
			return tostring(App.player.UserId) .. "_" .. Qol.code
		end
		function Qol.noticeSeen()
			local key = Qol.noticeKey()
			local remembered = env.__HOLLOW_COMMUNITY_SEEN
			if type(remembered) == "table" and remembered[key] then
				return true
			end
			if type(readfile) == "function" then
				local ok, value = pcall(readfile, "zephyr-hollow-discord-" .. App.player.UserId .. ".txt")
				if ok and value == Qol.code then
					return true
				end
			end
			return false
		end
		function Qol.rememberNotice()
			if type(env.__HOLLOW_COMMUNITY_SEEN) ~= "table" then
				env.__HOLLOW_COMMUNITY_SEEN = {}
			end
			env.__HOLLOW_COMMUNITY_SEEN[Qol.noticeKey()] = true
			if type(writefile) == "function" then
				Qol.saved = pcall(writefile, "zephyr-hollow-discord-" .. App.player.UserId .. ".txt", Qol.code)
			end
		end
		function Qol.copyInvite()
			local copy = type(setclipboard) == "function" and setclipboard or toclipboard
			if type(copy) == "function" and pcall(copy, "https://" .. Qol.invite) then
				if ui.discordCopy then
					ui.discordCopy.Text = "Invite copied"
				end
				return true
			end
			if ui.discordText then
				ui.discordText.Visible = true
				ui.discordText:CaptureFocus()
			end
			return false
		end
		function Qol.dismissNotice()
			if Qol.notice then
				Qol.notice:Destroy()
				Qol.notice = nil
			end
		end
		function Qol.mount()
			local ok, tween = pcall(function()
				return game:GetService("TweenService"):Create(
					ui.discordLink,
					TweenInfo.new(1.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
					{ TextColor3 = Color3.fromRGB(190, 170, 255) }
				)
			end)
			if ok then
				Qol.pulse = tween
				local function visibility()
					if ui.panel.Visible then
						tween:Play()
					else
						tween:Pause()
					end
				end
				connect(ui.panel:GetPropertyChangedSignal("Visible"), visibility)
				visibility()
			end
			if Qol.noticeSeen() then
				return
			end
			Qol.rememberNotice()
			local card = new(
				"Frame",
				ui.panel,
				{
					Name = "DiscordWelcome",
					Position = UDim2.fromOffset(12, 68),
					Size = UDim2.new(1, -24, 0, 196),
					BackgroundColor3 = colors.raised,
					ZIndex = 30,
					Active = true,
				}
			)
			rounded(card, 10)
			Qol.notice = card
			local title = label(card, "Join the Zephyr Discord", UDim2.fromOffset(16, 12), UDim2.new(1, -32, 0, 28), 17)
			title.Font, title.ZIndex = Enum.Font.GothamBold, 31
			local link = label(card, Qol.invite, UDim2.fromOffset(16, 44), UDim2.new(1, -32, 0, 25), 16, colors.mint)
			link.ZIndex, link.TextScaled = 31, true
			new("UITextSizeConstraint", link, { MinTextSize = 10, MaxTextSize = 16 })
			local text = label(
				card,
				"Updates, help and the official script.\nSharing a showcase? Leave the invite too.",
				UDim2.fromOffset(16, 74),
				UDim2.new(1, -32, 0, 54),
				12,
				colors.muted
			)
			text.ZIndex = 31
			local copy =
				button(card, "Copy invite", UDim2.new(0, 12, 1, -56), UDim2.new(0.5, -18, 0, 44), Qol.copyInvite)
			local close =
				button(card, "Got it", UDim2.new(0.5, 6, 1, -56), UDim2.new(0.5, -18, 0, 44), Qol.dismissNotice)
			copy.ZIndex, close.ZIndex = 31, 31
			copy.BackgroundColor3, copy.TextColor3 = colors.mint, colors.base
			task.delay(12, function()
				if Qol.notice == card then
					Qol.dismissNotice()
				end
			end)
		end

		-- hospital
		function Qol.session()
			if Qol.hospital then
				return Qol.hospital
			end
			local session = {
				manual = true,
				model = character(),
				bound = {},
				objects = {},
				rooms = {},
				retry = {},
				clicked = setmetatable({}, { __mode = "k" }),
				queue = { workspace },
				head = 1,
			}
			local api = App.hospitalApi
			local function add(object)
				if object:IsA("ProximityPrompt") or object:IsA("ClickDetector") then
					session.objects[object] = true
					local room = api.room(object)
					if room then
						session.rooms[room] = true
					end
				end
			end
			session.add = add
			session.bound.added = workspace.DescendantAdded:Connect(add)
			session.bound.removed = workspace.DescendantRemoving:Connect(function(object)
				session.objects[object], session.rooms[object], session.retry[object] = nil, nil, nil
			end)
			Qol.hospital = session
			return session
		end
		function Qol.hospitalScan(session)
			local api, start = App.hospitalApi, os.clock()
			api.bind(session)
			if not session.lib and not session.libLoading and os.clock() >= (session.libRetry or 0) then
				session.libLoading, session.libRetry = true, os.clock() + 6
				task.spawn(function()
					local ok, lib = pcall(module, Storage:FindFirstChild("Lib"))
					if Qol.hospital == session and App.alive then
						session.lib = ok and lib or nil
					end
					session.libLoading = false
				end)
			end
			for _ = 1, 250 do
				local object = session.queue[session.head]
				if not object then
					break
				end
				session.head += 1
				session.add(object)
				for _, child in ipairs(object:GetChildren()) do
					table.insert(session.queue, child)
				end
				if os.clock() - start > 0.002 then
					break
				end
			end
			if session.head > #session.queue then
				session.queue, session.head = {}, 1
			end
			local model = character()
			if model ~= session.model then
				EventInput.release(session)
				session.model, session.clicked = model, setmetatable({}, { __mode = "k" })
			end
		end
		function Qol.entry(object, title, extra)
			local part = App.day8.part(object)
			if not part and object then
				part = App.day8.part(object.Parent)
			end
			if not part then
				return nil
			end
			local entry = extra or {}
			entry.object, entry.part, entry.title = object, part, title
			return entry
		end
		function Qol.hospitalItems()
			local session, api, items = Qol.session(), App.hospitalApi, {}
			Qol.hospitalScan(session)
			local text = api.objective(session)
			local target = api.target(session)
			local object, tool = api.pick(session, text)
			Qol.nextObject, Qol.nextTool = object, tool
			local nextEntry = Qol.entry(
				object or target,
				"NEXT: " .. (object and object:IsA("ProximityPrompt") and object.ActionText or text)
			)
			if nextEntry then
				table.insert(items, nextEntry)
			end
			local needed, held = api.needs(session), api.held()
			local wanted = {}
			for name in pairs(needed) do
				if not held[name] then
					table.insert(wanted, name)
				end
			end
			table.sort(wanted)
			Qol.detail = tostring(text) .. (#wanted > 0 and "\nNeed: " .. table.concat(wanted, ", ") or "")
			for prompt in pairs(session.objects) do
				if prompt.Parent and prompt:IsA("ProximityPrompt") and prompt.Enabled and prompt ~= object then
					local action = api.text(prompt.ActionText)
					local supply = needed[action] and not held[action]
					if supply or target and api.related(prompt, target) then
						local entry = Qol.entry(prompt, supply and "GET: " .. prompt.ActionText or prompt.ActionText)
						if entry then
							table.insert(items, entry)
						end
					end
				end
			end
			return items, nextEntry
		end
		function Qol.miniVisible()
			for _, names in ipairs({
				{ "Minigame", "Frame" },
				{ "DNAMinigame", "Frame" },
				{ "BarMinigame", "Base" },
				{ "HeartbeatMinigameUI", "Frame" },
			}) do
				local object = getPath(App.player, "PlayerGui", table.unpack(names))
				if object and App.hospitalApi.visible(object) then
					return true
				end
			end
			return false
		end
		function Qol.hospitalAssist()
			if App.running or Qol.busy then
				return
			end
			local session, api = Qol.session(), App.hospitalApi
			if Qol.taps and Qol.miniVisible() then
				api.ui(session)
				return
			end
			if Qol.miniVisible() then
				return
			end
			local inspected = api.inspecting(session)
			local _, root = character()
			if not root or not api.ready(session) then
				return
			end
			if Qol.taps then
				for object in pairs(session.objects) do
					local machine = object.Parent and object:IsA("ClickDetector") and api.machine(object)
					local point = machine and EventInput.point(object.Parent)
					if
						point
						and api.busy(machine)
						and api.available(machine)
						and (not inspected or api.related(machine, inspected))
						and (root.Position - point).Magnitude <= math.min(10, object.MaxActivationDistance)
						and os.clock() >= (session.retry[object] or 0)
					then
						session.retry[object] = os.clock() + 0.15
						api.click(session, object)
						EventInput.release(session)
						return
					end
				end
			end
			if inspected then
				return
			end
			local prompt = Qol.prompts and Qol.nextObject
			local point = prompt and prompt.Parent and prompt:IsA("ProximityPrompt") and EventInput.point(prompt.Parent)
			if
				not point
				or (root.Position - point).Magnitude > prompt.MaxActivationDistance * 0.9
				or os.clock() < (session.retry[prompt] or 0)
			then
				return
			end
			local tool = Qol.nextTool
			if tool and tool.Parent ~= session.model then
				return
			end
			local revision = session.revision
			session.retry[prompt] = os.clock() + 2
			api.hold(session, prompt, nil, function()
				return Qol.prompts and not App.running and api.ready(session) and session.revision == revision
			end)
			EventInput.release(session)
		end

		-- warden
		function Qol.loadWarden()
			if Qol.loading then
				return
			end
			Qol.loading = true
			local epoch = Qol.epoch
			task.spawn(function()
				pcall(function()
					for _, name in ipairs({
						"Objective",
						"SpawnedConsumableClient",
						"GameplayStateService",
						"HollowClawStrike",
						"StainBossHits",
						"PlayerWrapper",
						"ConsumablesService",
					}) do
						if not App.alive or Qol.epoch ~= epoch then
							break
						end
						App.day8.load(name)
					end
				end)
				Qol.loading = false
			end)
		end
		function Qol.wardenItems()
			local day, items, candidates = App.day8, {}, {}
			local threats = day.sonariaThreats()
			local objectiveApi = day.modules.Objective
			local activeObjective = objectiveApi and objectiveApi.GetActiveInteraction()
			local activeEntry
			for _, entry in ipairs(day.objectiveItems()) do
				local locked = entry.object:GetAttribute("Locked") == true
					or entry.native and entry.native.LockedObjective == true
				entry.title = locked and "Locked infection"
					or "Infection | " .. tostring(entry.object:GetAttribute("Health") or "")
				table.insert(items, entry)
				if entry.native and entry.native == activeObjective then
					activeEntry = entry
				end
				local available = not locked
				if entry.native and type(entry.native.CanInteract) == "function" then
					local ok, result = pcall(entry.native.CanInteract, entry.native)
					available = available and ok and result == true
				end
				if available and day.clearance(entry.part.Position, threats) > 24 then
					table.insert(candidates, entry)
				end
			end
			for _, entry in ipairs(threats) do
				table.insert(items, entry)
			end
			local api = day.modules.SpawnedConsumableClient
			for _, native in pairs(api and api.GetAll and api.GetAll() or {}) do
				if not native.Claimed and not native.Claiming then
					local entry = Qol.entry(
						native.SpawnPart,
						tostring(native.ConsumableType or "Supply"),
						{ supply = true, native = native }
					)
					if entry then
						table.insert(items, entry)
					end
				end
			end
			local nextEntry = activeEntry or day.nearest(candidates)
			local _, gap = day.nearest(threats)
			local hits, strike = day.modules.StainBossHits, day.modules.HollowClawStrike
			if hits and hits.IsActive() then
				local boss = strike and strike.GetBossRoot()
				local entry = Qol.entry(boss, "Hollow boss", { threat = true })
				if entry then
					table.insert(items, entry)
					nextEntry = entry
				end
				Qol.detail = (
					hits.IsHittable() and "BOSS OPEN: throw a Hollow Claw" or "Boss protected. Wait for the opening."
				)
				if type(hits.GetHealthFraction) == "function" then
					Qol.detail ..= "\nBoss health: " .. math.floor(math.clamp(hits.GetHealthFraction(), 0, 1) * 100) .. "%"
				end
			else
				Qol.detail = activeEntry and "Clearing this infection"
					or nextEntry and "Follow the line to a safer infection"
					or "Waiting for an available infection"
			end
			Qol.warning = gap and gap < 45 and "MONSTER: " .. math.floor(gap) .. " studs" or nil
			return items, nextEntry
		end
		function Qol.wardenTaps()
			if App.running or not Qol.taps then
				return
			end
			local api = App.day8.modules.Objective
			local object = api and api.GetActiveInteraction()
			local target = object and object.ActiveMaid and object.ActiveMaid.ClickMinigame
			target = target and target.ActiveTarget
			if
				object
				and object.Active
				and not object.ActiveSkillCheck
				and target
				and target.Instance
				and target.Instance.Visible
				and target.Config
				and type(target.Config.OnClick) == "function"
				and os.clock() >= (Qol.tapAt or 0)
			then
				Qol.tapAt = os.clock() + 0.12
				target.Config.OnClick()
			end
		end
		function Qol.throwClaw()
			if App.running or Qol.busy then
				return false
			end
			local modules, day = App.day8.modules, App.day8
			local hits, strike, wrapperApi, service =
				modules.StainBossHits, modules.HollowClawStrike, modules.PlayerWrapper, modules.ConsumablesService
			if
				not hits
				or not strike
				or not wrapperApi
				or not service
				or not hits.IsActive()
				or not hits.IsHittable()
				or not day.ready()
			then
				return false
			end
			local wrapper = wrapperApi.getWrapperFromPlayer(App.player)
			local hotbar = wrapper and wrapper.PlayerData and wrapper.PlayerData:FindFirstChild("Hotbar")
			local slot
			for _, item in ipairs(hotbar and hotbar:GetChildren() or {}) do
				if item:IsA("StringValue") and item.Value == "HollowClaw" then
					slot = item
					break
				end
			end
			local boss = strike.GetBossRoot()
			if not slot or not boss or service.CanUseConsumable(App.player, slot.Name) ~= true then
				return false
			end
			Qol.busy = true
			local session = {}
			local ok, used = pcall(function()
				strike.OnHotbarSlotPressed(slot)
				App.event7.face(session, boss)
				if not pause(0.08) or App.running or not day.ready() or not hits.IsHittable() then
					return false
				end
				local _, aimed = strike.GetAim()
				if aimed and service.CanUseConsumable(App.player, slot.Name) == true then
					return service.UseConsumable(slot.Name) ~= false
				end
				return false
			end)
			EventInput.release(session)
			Qol.busy = false
			return ok and used == true
		end

		-- guides
		function Qol.clearVisuals()
			for _, visual in pairs(Qol.visuals) do
				visual.highlight:Destroy()
				visual.billboard:Destroy()
			end
			Qol.visuals = {}
			if Qol.line then
				Qol.line.beam:Destroy()
				Qol.line.first:Destroy()
				Qol.line.last:Destroy()
				Qol.line = nil
			end
			if Qol.hud then
				Qol.hud:Destroy()
				Qol.hud = nil
			end
		end
		function Qol.draw(items, nextEntry)
			local _, root = character()
			if not root then
				Qol.clearVisuals()
				return
			end
			local keep = {}
			if Qol.markers then
				table.sort(items, function(a, b)
					if a == b then
						return false
					end
					if a == nextEntry then
						return true
					end
					if b == nextEntry then
						return false
					end
					return (a.part.Position - root.Position).Magnitude < (b.part.Position - root.Position).Magnitude
				end)
				for index, entry in ipairs(items) do
					if index > 22 then
						break
					end
					local visual = Qol.visuals[entry.object]
					if not visual then
						local highlight = new(
							"Highlight",
							App.gui,
							{
								Adornee = entry.part,
								FillTransparency = 0.88,
								DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
								OutlineColor = entry.threat and colors.coral or colors.mint,
							}
						)
						local billboard = new(
							"BillboardGui",
							App.gui,
							{
								Adornee = entry.part,
								AlwaysOnTop = true,
								StudsOffset = Vector3.new(0, 3, 0),
								Size = UDim2.fromOffset(190, 48),
							}
						)
						local text = label(
							billboard,
							"",
							UDim2.fromOffset(0, 0),
							UDim2.fromScale(1, 1),
							12,
							highlight.OutlineColor
						)
						text.TextStrokeTransparency = 0.2
						visual = { highlight = highlight, billboard = billboard, text = text }
						Qol.visuals[entry.object] = visual
					end
					visual.text.Text = entry.title
						.. "\n"
						.. math.floor((entry.part.Position - root.Position).Magnitude)
						.. " studs"
					keep[entry.object] = true
				end
			end
			for object, visual in pairs(Qol.visuals) do
				if not keep[object] then
					visual.highlight:Destroy()
					visual.billboard:Destroy()
					Qol.visuals[object] = nil
				end
			end
			if Qol.guide then
				if not Qol.hud then
					Qol.hud = label(App.gui, "", UDim2.new(0.5, -145, 0, 72), UDim2.fromOffset(290, 70), 13)
					Qol.hud.TextStrokeTransparency = 0.25
				end
				Qol.hud.Text = (Qol.warning and Qol.warning .. "\n" or "") .. tostring(Qol.detail or "")
				Qol.hud.TextColor3 = Qol.warning and colors.coral or colors.text
				if nextEntry and nextEntry.part.Parent then
					if not Qol.line then
						local first, last = Instance.new("Attachment"), Instance.new("Attachment")
						local beam = new(
							"Beam",
							first,
							{
								Attachment0 = first,
								Attachment1 = last,
								Width0 = 0.08,
								Width1 = 0.08,
								FaceCamera = true,
								Color = ColorSequence.new(colors.mint),
								LightEmission = 0.6,
								Segments = 1,
							}
						)
						Qol.line = { first = first, last = last, beam = beam }
					end
					Qol.line.first.Parent, Qol.line.last.Parent = root, nextEntry.part
					Qol.line.beam.Enabled = true
				elseif Qol.line then
					Qol.line.beam.Enabled = false
				end
			else
				if Qol.hud then
					Qol.hud:Destroy()
					Qol.hud = nil
				end
				if Qol.line then
					Qol.line.beam.Enabled = false
				end
			end
		end
		function Qol.enabled()
			return Qol.markers or Qol.guide or Qol.taps or Qol.prompts
		end
		function Qol.watch()
			if Qol.watching or not Qol.enabled() then
				return
			end
			Qol.watching = true
			local epoch = Qol.epoch
			if current.id == "sonariaescape" then
				Qol.loadWarden()
			end
			task.spawn(function()
				local nextDraw, nextLoad = 0, os.clock() + 5
				while App.alive and Qol.epoch == epoch and Qol.enabled() do
					local ok = pcall(function()
						if os.clock() >= nextDraw then
							nextDraw = os.clock() + 0.35
							local items, nextEntry
							if current.id == "hospital" then
								items, nextEntry = Qol.hospitalItems()
							else
								items, nextEntry = Qol.wardenItems()
							end
							Qol.nextEntry = nextEntry
							Qol.draw(items, nextEntry)
							if ui.manualInfo then
								ui.manualInfo.Text = Qol.detail or "Waiting for your next task"
							end
						end
						if current.id == "hospital" then
							Qol.hospitalAssist()
						else
							Qol.wardenTaps()
							if os.clock() >= nextLoad then
								nextLoad = os.clock() + 8
								Qol.loadWarden()
							end
						end
					end)
					if not ok and Qol.hospital then
						EventInput.release(Qol.hospital)
					end
					task.wait(0.05)
				end
				if Qol.epoch == epoch then
					Qol.watching = false
					Qol.clearVisuals()
				end
			end)
		end
		function Qol.toggle(key)
			Qol[key] = not Qol[key]
			if not Qol.enabled() then
				Qol.clearHelpers()
			else
				Qol.watch()
			end
			refresh()
		end
		function Qol.goToTask()
			if current.id ~= "hospital" or App.running or Qol.busy then
				return false
			end
			local _, entry = Qol.hospitalItems()
			if not entry then
				return false
			end
			Qol.busy = true
			local epoch = Qol.epoch
			local ok, moved = pcall(approach, entry.part.Position, nil, nil, false, function()
				return not App.running
					and Qol.epoch == epoch
					and App.hospitalApi.ready(Qol.session())
					and entry.part.Parent ~= nil
			end)
			Qol.busy = false
			return ok and moved == true
		end
		function Qol.solvePicture()
			if current.id ~= "hospital" or App.running or Qol.busy then
				return false
			end
			local session, api = Qol.session(), App.hospitalApi
			Qol.hospitalScan(session)
			local puzzle = getPath(workspace, "Halloween", "Puzzle")
			if not puzzle or not api.pictureRequested(session, puzzle) then
				return false
			end
			local epoch = Qol.epoch
			Qol.busy = true
			local ok, solved = pcall(api.solve, session, puzzle, nil, function()
				return not App.running and Qol.epoch == epoch and api.pictureRequested(session, puzzle)
			end)
			EventInput.release(session)
			Qol.busy = false
			return ok and solved == true
		end
		function Qol.clearHelpers()
			Qol.epoch, Qol.watching = Qol.epoch + 1, false
			Qol.markers, Qol.guide, Qol.taps, Qol.prompts = false, false, false, false
			Qol.clearVisuals()
			local session = Qol.hospital
			Qol.hospital = nil
			if session then
				EventInput.release(session)
				for _, connection in pairs(session.bound) do
					pcall(connection.Disconnect, connection)
				end
			end
		end
		function Qol.suspendInputs()
			if Qol.hospital then
				EventInput.release(Qol.hospital)
			end
		end
		function Qol.clear()
			Qol.clearHelpers()
			Qol.dismissNotice()
			if Qol.pulse then
				Qol.pulse:Cancel()
				Qol.pulse = nil
			end
		end
		App.qol = Qol
	end)()
end


