	local drag
	local function place(object, center)
		local half, viewport = object.AbsoluteSize / 2, root.AbsoluteSize
		local x = math.clamp(center.X, half.X + 12, math.max(half.X + 12, viewport.X - half.X - 12))
		local y = math.clamp(center.Y, half.Y + 12, math.max(half.Y + 12, viewport.Y - half.Y - 12))
		object.Position = UDim2.fromOffset(x, y)
		return Vector2.new(x / math.max(1, viewport.X), y / math.max(1, viewport.Y))
	end
	local function layout()
		local viewport = root.AbsoluteSize
		if viewport.X <= 0 or viewport.Y <= 0 then
			return
		end
		drag = nil
		panel.Size =
			UDim2.fromOffset(math.min(480, math.max(1, viewport.X - 24)), math.min(560, math.max(1, viewport.Y - 24)))
		local compact = viewport.Y < 440
		local bodyTop = compact and 96 or 132
		header.Size = UDim2.new(1, -112, 0, compact and 44 or 67)
		mark.Position = UDim2.fromOffset(16, compact and 6 or 14)
		mark.Size = UDim2.fromOffset(compact and 32 or 38, compact and 32 or 38)
		heading.Position = UDim2.fromOffset(compact and 56 or 65, compact and 1 or 13)
		subtitle.Position = UDim2.fromOffset(compact and 56 or 65, compact and 24 or 37)
		minimize.Position = UDim2.new(1, -108, 0, compact and 0 or 12)
		close.Position = UDim2.new(1, -56, 0, compact and 0 or 12)
		navigation.Position = UDim2.fromOffset(16, compact and 44 or 76)
		actions.Position = UDim2.new(0, 16, 1, compact and -68 or -80)
		footer.Position = UDim2.new(0, 16, 1, compact and -20 or -27)
		footer.Size = UDim2.new(1, -32, 0, compact and 16 or 20)
		for _, page in pairs(pages) do
			page.Position = UDim2.fromOffset(16, bodyTop)
			page.Size = UDim2.new(1, -32, 0, math.max(1, panel.Size.Y.Offset - bodyTop - (compact and 76 or 92)))
		end
		local center = ui.center or Vector2.new(0.5, 0.5)
		ui.center = place(panel, Vector2.new(center.X * viewport.X, center.Y * viewport.Y))
		if ui.reopenCenter then
			place(ui.reopen, Vector2.new(ui.reopenCenter.X * viewport.X, ui.reopenCenter.Y * viewport.Y))
		end
		footer.Text = Input.KeyboardEnabled and "INS  /  HIDE OR SHOW" or "DRAG THE HEADER TO MOVE  /  - TO HIDE"
	end
	local function setProperty(object, key, value)
		if object[key] ~= value then
			object[key] = value
		end
	end
