				local selected = App.railsTracking == mode
				setProperty(item.control, "Text", item.title .. (selected and ": ON" or ""))
				setProperty(item.control, "BackgroundColor3", selected and colors.mint or colors.raised)
				setProperty(item.control, "TextColor3", selected and colors.base or colors.text)
			end
			local line = App.railsLine ~= false
			setProperty(ui.railsLine, "Text", "Guidance line: " .. (line and "ON" or "OFF"))
			setProperty(ui.railsLine, "BackgroundColor3", line and colors.mint or colors.raised)
			setProperty(ui.railsLine, "TextColor3", line and colors.base or colors.text)
			setProperty(
				ui.railsGuideText,
				"Text",
				App.railsGuideText or "Enable helpers to mark live keys, bank clues and vault codes."
			)
		end
	end
	ui.reopen.AnchorPoint = Vector2.new(0.5, 0.5)
	ui.reopenCenter = Vector2.new(0.12, 0.5)
	local function beginDrag(object, input)
		if
			not drag
			and (
				input.UserInputType == Enum.UserInputType.MouseButton1
				or input.UserInputType == Enum.UserInputType.Touch
			)
		then
			if object == ui.reopen then
				ui.reopenDragged = false
			end
			drag = {
				object = object,
				input = input,
				origin = input.Position,
				position = object.AbsolutePosition + object.AbsoluteSize / 2 - root.AbsolutePosition,
			}
		end
	end
	connect(header.InputBegan, function(input)
		beginDrag(panel, input)
	end)
	connect(ui.reopen.InputBegan, function(input)
		beginDrag(ui.reopen, input)
	end)
	connect(Input.InputChanged, function(input)
		if
			drag
			and (
				input == drag.input
				or (
					drag.input.UserInputType == Enum.UserInputType.MouseButton1
					and input.UserInputType == Enum.UserInputType.MouseMovement
				)
			)
		then
			local delta = input.Position - drag.origin
			if delta.X * delta.X + delta.Y * delta.Y < 64 then
				return
			end
			local center = place(drag.object, drag.position + Vector2.new(delta.X, delta.Y))
			if drag.object == panel then
				ui.center = center
			else
				ui.reopenCenter, ui.reopenDragged = center, true
			end
		end
	end)
	connect(Input.InputEnded, function(input)
		if drag and input == drag.input then
			drag = nil
		end
	end)
	local cursor, cursorBound, cursorConnection, cursorActive
	local cursorBinding = "HollowPanelCursor"
	local focused = true
	local mouseMode = Input.MouseEnabled and (not Input.TouchEnabled or Input.KeyboardEnabled)
	local cameraPointers = {}
	local function releaseCursor(preserve)
		cursorActive = false
		if cursorBound then
			pcall(RunService.UnbindFromRenderStep, RunService, cursorBinding)
			cursorBound = false
		end
		if cursorConnection then
			cursorConnection:Disconnect()
			cursorConnection = nil
		end
		header.Modal = false
		if cursor then
			pcall(function()
				if Input.MouseBehavior == Enum.MouseBehavior.Default then
					Input.MouseBehavior = cursor.behavior
				end
				if Input.MouseIconEnabled then
					Input.MouseIconEnabled = cursor.icon
				end
			end)
			if not preserve then
				cursor = nil
			end
		end
	end
	local function syncCursor()
		if
			not App.alive
			or not panel.Visible
			or not focused
			or App.cameraBusy
			or not Input.MouseEnabled
			or not mouseMode
		then
			releaseCursor(App.alive and panel.Visible)
			return
		end
		if cursorActive then
			return
		end
		cursor = cursor or { behavior = Input.MouseBehavior, icon = Input.MouseIconEnabled }
		cursorActive = true
		header.Modal = true
		local function unlock()
			if App.alive and panel.Visible and focused and not App.cameraBusy then
				if Input.MouseBehavior ~= Enum.MouseBehavior.Default then
					Input.MouseBehavior = Enum.MouseBehavior.Default
				end
				if not Input.MouseIconEnabled then
					Input.MouseIconEnabled = true
				end
			end
		end
		unlock()
		cursorBound =
			pcall(RunService.BindToRenderStep, RunService, cursorBinding, Enum.RenderPriority.Last.Value + 1, unlock)
		if not cursorBound then
			cursorConnection = connect(RunService.RenderStepped, unlock)
		end
	end
	ui.setVisible = function(visible)
		drag = nil
		panel.Visible, ui.reopen.Visible = visible, not visible
		syncCursor()
	end
	App.releaseUI = function()
		drag = nil
		table.clear(cameraPointers)
		App.cameraBusy, App.cameraEpoch = false, (App.cameraEpoch or 0) + 1
		releaseCursor()
	end
	local function insideMenu(point)
		for _, object in ipairs({ panel, ui.reopen }) do
			local origin, size = object.AbsolutePosition, object.AbsoluteSize
			if
				object.Visible
				and point.X >= origin.X
				and point.X <= origin.X + size.X
				and point.Y >= origin.Y
				and point.Y <= origin.Y + size.Y
			then
				return true
			end
		end
		return false
	end
	local function cameraChanged()
		local busy = not focused
		for _, pointer in pairs(cameraPointers) do
			busy = busy or pointer.active
		end
		if busy and not App.cameraBusy then
			App.cameraEpoch = (App.cameraEpoch or 0) + 1
		end
		App.cameraBusy = busy
		syncCursor()
	end
	connect(Input.InputBegan, function(input, processed)
		if input.UserInputType == Enum.UserInputType.Touch then
			mouseMode = false
			syncCursor()
		elseif
			input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.MouseButton2
			or input.UserInputType == Enum.UserInputType.Keyboard
		then
			mouseMode = true
		end
		if input.KeyCode == Enum.KeyCode.Insert and not processed and not Input:GetFocusedTextBox() then
			ui.setVisible(not panel.Visible)
		elseif not processed and input.Position and not insideMenu(input.Position) then
			if
				input.UserInputType == Enum.UserInputType.MouseButton2
				or input.UserInputType == Enum.UserInputType.Touch
			then
				cameraPointers[input] =
					{ origin = input.Position, active = input.UserInputType == Enum.UserInputType.MouseButton2 }
				cameraChanged()
			end
		end
		syncCursor()
	end)
	connect(Input.InputChanged, function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement and Input.MouseEnabled and not mouseMode then
			mouseMode = true
			syncCursor()
		end
		local pointer = cameraPointers[input]
		if not pointer then
			return
		end
		if input.UserInputState == Enum.UserInputState.Cancel or input.UserInputState == Enum.UserInputState.End then
			cameraPointers[input] = nil
		else
			local delta = input.Position - pointer.origin
			pointer.active = pointer.active or delta.X * delta.X + delta.Y * delta.Y >= 64
		end
		cameraChanged()
	end)
	connect(Input.InputEnded, function(input)
		cameraPointers[input] = nil
		cameraChanged()
	end)
	connect(Input.WindowFocusReleased, function()
		focused, drag = false, nil
		table.clear(cameraPointers)
		cameraChanged()
	end)
	connect(Input.WindowFocused, function()
		focused = true
		cameraChanged()
	end)
	connect(Input:GetPropertyChangedSignal("MouseEnabled"), syncCursor)
	connect(root:GetPropertyChangedSignal("AbsoluteSize"), layout)
	connect(gui.Destroying, function()
		App.unload()
	end)
	layout()
	refresh()
	ui.setVisible(true)
	App.qol.mount()
end

App.unload = function()
	if not App.alive or App.unloading then
		return
	end
	App.unloading = true
	App.generation += 1
	App.running = false
	if App.qol then
		pcall(App.qol.clear)
	end
	if App.day9 then
		pcall(App.day9.clear)
	end
	if App.day8 then
		pcall(App.day8.clear)
	end
	if App.event7 then
		pcall(App.event7.clear)
	end
	if App.mega then
		pcall(App.mega.clear)
	end
	if App.releaseUI then
		pcall(App.releaseUI)
	end
	if App.dandyEspState then
		pcall(Dandy.setEsp, false)
	end
	if App.doorsState then
		pcall(Doors.clear, App.doorsState)
	end
	if App.clearArcadeGuide then
		pcall(App.clearArcadeGuide)
	end
	cleanRun()
	App.alive = false
	for _, connection in ipairs(App.connections) do
		pcall(connection.Disconnect, connection)
	end
	table.clear(App.connections)
	if App.gui then
		pcall(App.gui.Destroy, App.gui)
	end
	if env.__HOLLOW_PANEL == App then
		env.__HOLLOW_PANEL = nil
	end
end
env.__HOLLOW_PANEL = App

task.spawn(function()
	local ok, err = pcall(function()
		App.player = waitUntil(function()
			return Players.LocalPlayer
		end, 30)
		if not App.player or not App.alive then
			return
		end
		local playerGui = waitUntil(function()
			return App.player:FindFirstChild("PlayerGui")
		end, 20)
		if not playerGui or not App.alive then
			return
		end
		buildUI(playerGui)
		if App.startArcadeGuide then
			App.startArcadeGuide()
		end
		if current and current.id == "doors" then
			Doors.ensure()
		end
		connect(Teleport.TeleportInitFailed, function(player, _, message)
			if player == App.player then
				App.traveling = false
				status("Travel failed", message)
			end
		end)
		status(
			current and (current.manual and "Play this one in the game" or "Ready") or "Unsupported game",
			current and current.objective or "",
			0
		)
		log(current and ("Detected " .. current.name) or "Open Travel to pick an event game")
		if current and current.badges then
			verify(current, true)
		end
		if App.alive and current and (resumePlace == game.PlaceId or current.id == "aooni" and Aooni.arrival()) then
			start()
		end
	end)
	if not ok and App.alive then
		status("Startup stopped", tostring(err))
		log(err)
	end
end)
]=]
local launch, err = loadstring(source)
if launch then
    launch(source)
else
    warn("[Hollow] " .. tostring(err))
end
